	["a defensive combat stance"] = { ko = "안정된 방어 태세입니다.", zhCN = "防御型作战姿态。" },
	["a defensive combat stance. decreases damage taken by #% and damage caused by #%. increases all threat generated by #%"] = { ko = "안정된 방어 태세입니다. 받는 피해가 {1}%만큼, 공격력이 {2}%만큼 감소합니다. 모든 위협 수준 생성량이 {3}%만큼 증가합니다.", zhCN = "防御型作战姿态。受到的伤害降低{1}%，造成的伤害降低{2}%。产生的所有威胁值提高{3}%。", zhTW = "防禦型的戰鬥姿態，受到的傷害降低{1}%，對敵人造成的傷害也降低{2}%。產生的所有威脅值提高{3}%。" },
	["a long-range shot that deals ranged damage plus # and increases the range of your next # shots by # yards for # sec"] = { ko = "먼 거리에서 사격하여 원거리 피해에 {1}의 추가 피해를 입히고, {3}초 동안 다음 사격 {2}회의 사정거리가 {4}미터 늘어납니다." },
	["a maximum of # attacks will cause retaliation"] = { ko = "최대 {1}회의 반격이 가능합니다.", zhCN = "最多可反击{1}次攻击。", zhTW = "最多可反擊{1}次攻擊。" },
	["a mocking attack that causes # damage, a moderate amount of threat and forces the target to focus attacks on you for # sec"] = { ko = "적에게 도발의 일격을 날려 {1}의 피해를 입히고 위협 수준을 증가시켜 {2}초 동안 자신에게 공격을 집중하도록 만듭니다.", zhCN = "对目标造成{1}点额外伤害和中量的威胁，并迫使它在{2}秒内一直攻击你。", zhTW = "對目標造成{1}點額外傷害和中量的威脅，並迫使它在{2}秒內一直攻擊你。" },
	["a powerful kick that deals #% melee weapon damage and increases movement speed by #% for # sec"] = { ko = "근접 무기 공격력의 {1}%에 해당하는 피해를 입히는 강력한 발차기입니다. {3}초 동안 이동 속도가 {2}%만큼 증가합니다.", zhCN = "A powerful kick that deals {1}% melee weapon damage and increases movement speed by {2}% for {3}秒.", zhTW = "A powerful kick that deals {1}% melee weapon damage and increases movement speed by {2}% for {3}秒." },
	["a powerful prayer that heals the target and their party for # to #"] = { ko = "강력한 기원으로 대상과 대상의 파티를 {1}~{2}만큼 치유합니다.", zhCN = "强大的祷言，治疗目标及其小队，回复{1}至{2}点生命值。", zhTW = "唱誦強大的禱言，為目標和其隊伍治療{1}至{2}點生命力。" },
	["a powerful prayer that heals the target and their party for # to # party members must be within # yards of target"] = { ko = "강력한 기원으로 대상과 대상의 파티를 {1}~184만큼 치유합니다. 파티원이 대상의 {3}미터 내에 있어야 합니다.", zhCN = "强大的祷言，治疗目标及其小队，回复{1}至184点生命值。小队成员必须位于目标{3}码范围内。", zhTW = "唱誦強大的禱言，為目標和其隊伍治療{1}至184點生命力。小隊成員必須在目標附近{3}碼內。" },
	["a quick kick that injures a single foe for # damage"] = { ko = "적을 발로 가격하여 {1}의 피해를 입힙니다." },
	["a quick kick that injures a single foe for # damage. it also interrupts spellcasting and prevents any spell in that school from being cast for # sec"] = { ko = "적을 발로 가격하여 {1}의 피해를 입힙니다. 또한 대상이 {2}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다.", zhCN = "用脚快速踢敌人，对其造成{1}点伤害，打断其正在施放的法术，并使其在{2}秒内无法施放任何该系的法术。", zhTW = "用腳快速踢敵人，對其造成{1}點傷害，打斷其正在施放的法術，並使其在{2}秒內無法施放任何該系的法術。" },
	["a short-range shot that deals #% weapon damage and disorients the target for # sec"] = { zhCN = "短程射击，对目标造成{1}%的武器伤害，并使其困惑{2}秒。", zhTW = "短程射擊，對目標造成{1}%的武器傷害，並使其暈眩{2}秒。" },
	["a short-range shot that deals #% weapon damage and disorients the target for # sec. any damage caused will remove the effect. turns off your attack when used"] = { ko = "무기 공격력에 {1}%에 해당하는 피해를 입히고 {2}초 동안 적을 방향 감각 상실 상태로 만듭니다. 사정거리가 짧습니다. 대상이 피해를 입으면 효과가 사라집니다. 사용하면 자동 공격을 중단합니다.", zhCN = "短程射击，对目标造成{1}%的武器伤害，并使其困惑{2}秒。任何伤害都会打断该效果。使用之后结束你的攻击。", zhTW = "短程射擊，對目標造成{1}%的武器傷害，並使其暈眩{2}秒。任何傷害都會打斷該效果。使用時會結束你的攻擊。" },
	["a slow casting spell that heals a single target for # to #"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시킵니다.", zhCN = "施法缓慢的法术，可以为单一目标治疗{1}至{2}点伤害。", zhTW = "施法緩慢的法術，可以為單一目標治療{1}至{2}點傷害。" },
	["a slow casting spell that heals a single target for #,# to #,#"] = { ko = "대상의 생명력을 {1},{2}~{3},{4}만큼 회복시킵니다.", zhCN = "施法缓慢的法术，可以为单一目标治疗{1},{2}至{3},{4}点伤害。", zhTW = "施法緩慢的法術，可以為單一目標治療{1},{2}至{3},{4}點傷害。" },
	["a stinging shot that puts the target to sleep for # sec"] = { zhCN = "钉刺目标，使其沉睡{1}秒。", zhTW = "釘刺目標，使其沉睡{1}秒。" },
	["a stinging shot that puts the target to sleep for # sec. any damage will cancel the effect. when the target wakes up, the sting causes # nature damage over # sec. only usable out of combat. only one sting per hunter can be active on the target at a time"] = { ko = "적에게 쐐기를 발사하여 {1}초 동안 잠재웁니다. 대상이 피해를 입으면 깨어납니다. 대상이 깨어나면 쐐기는 {3}초에 걸쳐 {2}의 자연 피해를 입힙니다. 비전투 상태에서만 사용 가능하며 한 번에 하나의 대상에게만 사용할 수 있습니다.", zhCN = "钉刺目标，使其沉睡{1}秒。任何伤害都会取消沉睡效果。当目标醒来时，钉刺会在{3}秒内对其造成{2}点自然伤害。只能在非战斗状态下使用。每个猎人在同一时间内只能对一个目标使用一种钉刺，且同类钉刺无法叠加。", zhTW = "釘刺目標，使其沉睡{1}秒。任何傷害都會取消沉睡效果。當目標醒來時，釘刺會在{3}秒內對其造成{2}點自然傷害。只能在非戰鬥狀態下使用。每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["a strike that becomes active after parrying an opponent's attack"] = { ko = "이 효과는 적의 공격을 무기로 막아낸 후에 활성화됩니다.", zhCN = "招架对手的攻击后可使用。" },
	["a strike that becomes active after parrying an opponent's attack. this attack deals #% weapon damage and disarms the target for # sec"] = { ko = "이 효과는 적의 공격을 무기로 막아낸 후에 활성화됩니다. 다음 공격은 무기 공격력의 {1}%에 해당하는 피해를 입히고 대상을 {2}초 동안 무장 해제시킵니다.", zhCN = "在招架了敌人的攻击之后可以使用的技能，对目标造成{1}%的武器伤害，并使其被缴械，持续{2}秒。", zhTW = "在招架敵人的攻擊之後可以使用的技能，對目標造成{1}%的武器傷害，並使其被繳械，持續{2}秒。" },
	["a strike that becomes active after parrying an opponent's attack. this attack deals #% weapon damage plus # and immobilizes the target for # sec. counterattack cannot be blocked, dodged, or parried"] = { ko = "이 효과는 적의 공격을 무기로 막아낸 후에 활성화됩니다. 무기 공격력의 {1}%에 {2}의 추가 피해를 입히고 대상을 {3}초 동안 이동 불가 상태로 만듭니다. 역습은 방패로 막거나, 회피하거나, 무기로 막을 수 없습니다.", zhCN = "招架对手的攻击后可使用。该攻击造成{1}%武器伤害外加{2}点伤害，并使目标无法移动{3}秒。反击无法被格挡、躲闪或招架。", zhTW = "在招架敵人的攻擊之後可以使用的技能，對敵人造成{1}%武器傷害再加上{2}點傷害，並使其無法移動，持續{3}秒。反擊無法被格擋、閃躲或招架。" },
	["a strike that deals #% (#% if a dagger is equipped in your main hand) weapon damage and increases your chance to dodge by #% for # sec"] = { ko = "적을 공격하여 무기 공격력의 {1}%(단검을 주무기로 착용 시 {2}%)에 해당하는 피해를 입히고 {4}초 동안 자신의 회피율이 {3}%만큼 증가합니다.", zhCN = "打击敌人，造成{1}%（主手装备匕首时为{2}%）武器伤害，并使你的躲闪几率提高{3}%，持续{4}秒。", zhTW = "鬼魅般的攻擊，造成{1}%（如果主手裝備匕首則為{2}%）的武器傷害，並使你的閃躲機率提高{3}%，持續{4}秒。" },
	["a strike that deals #% (#% if a dagger is equipped in your main hand) weapon damage and increases your chance to dodge by #% for # sec. awards # combo point"] = { ko = "적을 공격하여 무기 공격력의 {1}%(단검을 주무기로 착용 시 {2}%)에 해당하는 피해를 입히고 {4}초 동안 자신의 회피율이 {3}%만큼 증가합니다. 연계 점수 {5}점을 생성합니다.", zhCN = "打击敌人，造成{1}%（主手装备匕首时为{2}%）武器伤害，并使你的躲闪几率提高{3}%，持续{4}秒。奖励{5}个连击点。", zhTW = "鬼魅般的攻擊，造成{1}%（如果主手裝備匕首則為{2}%）的武器傷害，並使你的閃躲機率提高{3}%，持續{4}秒。獎勵{5}個連擊點數。" },
	["a strong attack that deals melee weapon damage plus #"] = { ko = "적을 강하게 내리쳐 근접 무기 공격력에 추가로 {1}의 피해를 입힙니다.", zhCN = "强力的攻击，造成近战武器伤害，外加{1}点伤害。", zhTW = "強力的攻擊，造成近戰武器傷害再加上{1}點傷害。" },
	["a strong attack that increases melee damage by # and causes a high amount of threat"] = { ko = "적을 강하게 내리쳐 {1}의 추가 피해를 입힙니다. 위협 수준이 크게 증가합니다.", zhCN = "强力的攻击，使近战攻击所造成的伤害提高{1}点，并造成大量的威胁。", zhTW = "強力的攻擊，使近戰攻擊所造成的傷害提高{1}點並造成大量威脅。" },
	["a sweeping attack that does your weapon damage plus # to the target and a second nearby enemy"] = { ko = "무기를 크게 휘둘러 공격하여 대상과 그 주위의 두 번째 적에게 무기 공격력에 {1}의 추가 피해를 입힙니다.", zhCN = "发动横扫攻击，对目标及附近的另一名敌人造成武器伤害外加{1}点伤害。", zhTW = "橫掃攻擊，對目標和其附近的第二個敵人造成你的武器傷害再加上{1}點傷害。" },
	["a target may be affected by only one contingency plan"] = { ko = "대상 하나에는 비상 대책이 하나만 걸립니다.", zhCN = "一个目标同一时间只能受到一个应急方案的影响。", zhTW = "一個目標同一時間只能受到一個應變計畫的影響。" },
	["a targeted party member is protected from all physical attacks for # sec, but during that time they cannot attack or use physical abilities"] = { zhCN = "使一名小队成员免受一切物理攻击，持续{1}秒，但在此期间其不能攻击或使用物理技能。", zhTW = "受保護的目標小隊成員將對一切物理攻擊免疫，同時也無法攻擊或使用物理技能，持續{1}秒。" },
	["a targeted party member is protected from all physical attacks for # sec, but during that time they cannot attack or use physical abilities. players may only have one blessing on them per paladin at any one time. applies forbearance for # min. cannot be cast while forbearance is active"] = { ko = "대상 파티원을 {1}초 동안 모든 물리 공격으로부터 보호합니다. 하지만 대상은 이 동안 공격을 하거나 물리 능력을 사용하지 못합니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다. {2}분 동안 참을성이 부여됩니다. 참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "使一名小队成员免受一切物理攻击，持续{1}秒，但在此期间其不能攻击或使用物理技能。每名圣骑士在同一时间对同一玩家只能施加一种祝福。施加自律，持续{2}分钟。自律效果激活时无法施放。", zhTW = "受保護的目標小隊成員將對一切物理攻擊免疫，同時也無法攻擊或使用物理技能，持續{1}秒。每個聖騎士在同一時間內只能給目標施加一種祝福。施加自律效果，持續{2}分鐘。自律效果生效期間，無法施放。" },
	["a vicious strike that deals weapon damage plus # and wounds the target, reducing the effectiveness of any healing by #% for # sec"] = { ko = "무기 공격력에 추가로 {1}만큼의 피해를 입히고 {3}초 동안 모든 치유의 효과가 {2}%만큼 감소되도록 상처를 입힙니다.", zhCN = "一次邪恶的攻击，对目标造成武器伤害外加{1}点伤害，并使任何形式的治疗对其产生的效果降低{2}%，持续{3}秒。", zhTW = "一次猛烈的攻擊，對目標造成武器傷害外加{1}點傷害，並使任何形式的治療對其產生的效果降低{2}%，持續{3}秒。" },
	["a wave of flame radiates outward from the caster, damaging all enemies caught within the blast for # to # fire damage, and dazing them for #% reduced movement speed for # sec"] = { ko = "불의 파도가 시전자 주위로 뿜어져 나와 모든 적을 불길로 감싸 {1}~{2}의 화염 피해를 입히고, 멍하게 만들어 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "施法者向外释放一道火焰冲击波，对冲击范围内的所有敌人造成{1}至{2}点火焰伤害，并使其眩晕，移动速度降低{3}%，持续{4}秒。", zhTW = "施法者放出一道烈焰衝擊波，所有被衝擊波觸及的敵人都會受到{1}至{2}點火焰傷害，並使其陷入暈眩，移動速度降低{3}%，持續{4}秒。" },
	["a word of dark binding that inflicts # to # shadow damage to the target"] = { ko = "어둠의 힘으로 대상에게 {1}~{2}의 암흑 피해를 입힙니다.", zhCN = "黑暗束缚的咒语，对目标造成{1}至{2}点暗影伤害。", zhTW = "黑暗的咒語對目標造成{1}至{2}點暗影傷害。" },
	["a word of dark binding that inflicts # to # shadow damage to the target. if your target is not killed by shadow word: death, you take backlash damage equal to #% of your maximum health"] = { ko = "어둠의 힘으로 대상에게 {1}~{2}의 암흑 피해를 입힙니다. 대상이 어둠의 권능: 죽음으로 사망하지 않으면 최대 생명력의 {3}%에 해당하는 반발 피해를 받습니다.", zhCN = "黑暗束缚的咒语，对目标造成{1}至{2}点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值{3}%的伤害反噬。", zhTW = "黑暗的咒語對目標造成{1}至{2}點暗影傷害。如果你的目標沒有被暗言術：死所殺害，你會受到相當於你生命力上限{3}%的反傷。" },
	["a word of darkness that causes # shadow damage over # sec"] = { ko = "어둠의 힘으로 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다.", zhCN = "黑暗的咒语，在{2}秒内造成总计{1}点暗影伤害。", zhTW = "黑暗的咒語，在{2}秒內造成總計{1}點暗影傷害。" },
	["absorbs # fire damage"] = { ko = "{1}의 화염 피해를 흡수합니다.", zhCN = "吸收{1}点火焰伤害。" },
	["absorbs # fire damage. lasts # sec"] = { ko = "{1}의 화염 피해를 흡수합니다. {2}초 동안 지속됩니다.", zhCN = "吸收{1}点火焰伤害。持续{2}秒。", zhTW = "吸收{1}點火焰傷害，持續{2}秒。" },
	["absorbs # frost damage"] = { ko = "{1}의 냉기 피해를 흡수합니다.", zhCN = "吸收{1}点冰霜伤害。" },
	["absorbs # frost damage. lasts # sec"] = { ko = "{1}의 냉기 피해를 흡수합니다. {2}초 동안 지속됩니다.", zhCN = "吸收{1}点冰霜伤害。持续{2}秒。", zhTW = "吸收{1}點冰霜傷害，持續{2}秒。" },
	["absorbs # physical damage, draining mana instead"] = { ko = "마나를 소비하여 {1}의 물리 피해를 흡수합니다.", zhCN = "吸收{1}点物理伤害，同时消耗法力值。", zhTW = "吸收{1}點物理傷害，同時消耗法力。" },
	["absorbs # physical damage, draining mana instead. drains # mana per damage absorbed. lasts # min"] = { ko = "마나를 소비하여 {1}의 물리 피해를 흡수합니다. 흡수된 피해당 {2}의 마나를 소비합니다. {3}분 동안 지속됩니다.", zhCN = "吸收{1}点物理伤害，同时消耗法力值。每吸收{3}点物理伤害，就消耗{2}点法力值。持续1分钟。", zhTW = "吸收{1}點物理傷害，同時消耗法力。每吸收{3}點物理傷害，就消耗{2}點法力。持續1分鐘。" },
	["absorbs # shadow damage"] = { ko = "{1}의 암흑 피해를 흡수합니다.", zhTW = "吸收{1}點暗影傷害。" },
	["absorbs # shadow damage. lasts # sec"] = { ko = "{1}의 암흑 피해를 흡수합니다. {2}초 동안 지속됩니다.", zhCN = "吸收{1}点暗影伤害，持续{2}秒。", zhTW = "吸收{1}點暗影傷害，持續{2}秒。" },
	["activate a set of jets to increase your movement speed by up to #%, for up to # sec"] = { ko = "추진기를 가동하여 이동 속도가 최대 {1}%만큼 증가합니다. 최대 {2}초 동안 지속됩니다.", zhCN = "激活一组推进器，使你的移动速度提高{1}%，持续最多{2}秒。", zhTW = "啟用一組推進器，使你的移動速度提高{1}%，持續最多{2}秒。" },
	["additionally, experience gained from kills is increased by #%"] = { ko = "추가로, 적 처치 시 획득하는 경험치가 {1}%만큼 증가합니다." },
	["additionally, your pet gains #% of the effect of your aspect of the monkey ability"] = { ko = "추가로 야수가 원숭이의 상 효과의 {1}%를 받습니다.", zhCN = "此外，你的宠物获得灵猴守护效果的{1}%。", zhTW = "此外，你的寵物獲得你靈猴守護技能的{1}%效果。" },
	["adds # combo points to your target"] = { ko = "대상에 대한 연계 점수 {1}점이 추가됩니다.", zhCN = "为你的目标增加{1}个连击点数。", zhTW = "為你的目標增加{1}個連擊點數。" },
	["adds # combo points to your target. you must add to or use those combo points within # sec or the combo points are lost"] = { ko = "대상에 대한 연계 점수 {1}점이 추가됩니다. {2}초 내에 연계 점수를 추가하거나 추가된 연계 점수를 사용하지 않으면 연계 점수가 사라집니다.", zhCN = "为你的目标增加{1}个连击点数。你必须在{2}秒内增加或消耗这些连击点数，否则它们就会消失。", zhTW = "為你的目標增加{1}個連擊點數。你必須在{2}秒內追加或消耗掉這些點數，否則它們就會消失。" },
	["adds a chill effect to your blizzard spell"] = { ko = "눈보라 주문이 빙결 효과를 일으킵니다." },
	["adds a chill effect to your blizzard spell. this effect lowers the target's movement speed by #% for # sec"] = { ko = "눈보라 주문이 빙결 효과를 일으킵니다. 빙결 효과는 {2}초 동안 적의 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "为你的暴风雪法术附加冰冷效果，使目标的移动速度降低{1}%，持续{2}秒。", zhTW = "為你的暴風雪法術增加冰冷效果，使目標的移動速度降低{1}%，持續{2}秒。" },
	["affected targets will suffer # additional damage every # sec for # sec"] = { ko = "영향을 받는 대상은 {3}초 동안 {2}초마다 {1}의 추가 피해를 받습니다.", zhCN = "受影响的目标每{2}秒额外受到{1}点伤害，持续{3}秒。", zhTW = "受影響的目標每{2}秒額外受到{1}點傷害，持續{3}秒。" },
	["affects # total targets"] = { ko = "최대 {1}명의 대상을 공격합니다." },
	["afflicts the target for # min, causing #% of all damage done by the warlock to other targets to also be dealt to the cursed target"] = { zhCN = "使目标遭受浩劫灾祸，持续{1}分钟，术士对其他目标造成的所有伤害有{2}%也会施加给被诅咒的目标。", zhTW = "對目標施加災厄，使其受到相當於該術士對其他目標所造成的所有傷害的{2}%傷害，持續{1}分鐘。" },
	["afflicts the target for # min, causing #% of all damage done by the warlock to other targets to also be dealt to the cursed target. bane of havoc is limited to # target, and only one bane per warlock can be active on any one target"] = { ko = "{1}분 동안 대상을 고통에 빠뜨립니다. 이때 흑마법사가 다른 대상에게 입히는 모든 피해의 {2}%를 저주받은 대상에게도 입힙니다. 대혼란의 파멸은 한 번에 하나의 대상에게만 걸 수 있으며, 흑마법사마다 한 대상에게 하나의 파멸만 걸 수 있습니다.", zhCN = "使目标遭受浩劫灾祸，持续{1}分钟，术士对其他目标造成的所有伤害有{2}%也会施加给被诅咒的目标。浩劫灾祸只能影响{3}个目标，且每个术士在任一目标身上只能维持一种灾祸。", zhTW = "對目標施加災厄，使其受到相當於該術士對其他目標所造成的所有傷害的{2}%傷害，持續{1}分鐘。僅限對{3}個目標施加浩劫之禍，且每個術士只能對同一個目標施加一種災厄。" },
	["afflicts the target with a disease that causes # shadow damage over # sec"] = { ko = "적을 질병에 감염시켜 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다." },
	["afflicts the target with a disease that causes # shadow damage over # sec. damage caused by the devouring plague heals the caster"] = { ko = "적을 질병에 감염시켜 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다. 파멸의 역병으로 인해 입히는 피해만큼 시전자의 생명력이 회복됩니다.", zhCN = "使目标患上疾病，在{2}秒内造成总计{1}点暗影伤害，并为施法者恢复等量的生命值。", zhTW = "使目標患上疾病，在{2}秒內造成總計{1}點暗影傷害，並為施法者恢復等量的生命力。" },
	["afflicts the target with agony, causing # shadow damage over # sec"] = { ko = "고통의 저주를 걸어 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다.", zhCN = "使目标遭受痛楚，在{2}秒内受到{1}点暗影伤害。", zhTW = "對目標施加痛苦，使其在{2}秒內受到{1}點暗影傷害。" },
	["afflicts the target with agony, causing # shadow damage over # sec. this damage is dealt slowly at first, and builds up as the bane reaches its full duration. only one bane per warlock can be active on any one target"] = { ko = "고통의 저주를 걸어 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다. 처음엔 피해를 천천히 입히다가 갈수록 피해를 주는 속도가 빨라집니다. 흑마법사마다 대상에 동시에 하나의 파멸만 걸 수 있습니다.", zhCN = "使目标遭受痛楚，在{2}秒内受到{1}点暗影伤害。该伤害起初较低，并会随着灾祸接近完整持续时间而逐渐提高。每个术士在任一目标身上只能维持一种灾祸。", zhTW = "對目標施加痛苦，使其在{2}秒內受到{1}點暗影傷害。此傷害在初期較低，但是會在作用效果期間不斷提高，直到結束。每個術士只能對同一個目標施加一種災禍。" },
	["afflicts the target with impending doom, causing #,# shadow damage after # min"] = { ko = "대상에게 임박하는 파멸을 걸어 {1}분 후에 {3},{2}의 암흑 피해를 입힙니다.", zhCN = "对目标施加末日将至的效果，在{1}分钟后造成{3},{2}点暗影伤害。", zhTW = "對目標施加厄運降臨，在{1}分鐘後造成{3},{2}點暗影傷害。" },
	["afflicts the target with impending doom, causing #,# shadow damage after # min. if the target dies from this damage, there is a chance that a doomguard will be summoned. cannot be cast on players. only one bane per warlock can be active on any one target"] = { ko = "대상에게 임박하는 파멸을 걸어 {1}분 후에 {3},{2}의 암흑 피해를 입힙니다. 그 피해로 인해 대상이 죽으면 일정 확률로 파멸의 수호병이 소환됩니다. 플레이어에게는 사용할 수 없습니다. 흑마법사마다 한 대상에게 하나의 파멸만 걸 수 있습니다.", zhCN = "对目标施加末日将至的效果，在{1}分钟后造成{3},{2}点暗影伤害。如果目标死于该伤害，则有几率召唤一名末日守卫。无法对玩家施放。每个术士对同一目标同时只能施加一种灾祸。", zhTW = "對目標施加厄運降臨，在{1}分鐘後造成{3},{2}點暗影傷害。如果目標死於該傷害，則有機率召喚出一個末日守衛。無法對玩家施放。每個術士只能對一個目標施加一種災厄。" },
	["afflicts your target with shadow energy that causes all party members to be healed for #% of any shadow spell damage you deal for # sec"] = { ko = "대상에게 암흑 마법을 겁니다. {2}초 동안 암흑 주문으로 입히는 피해의 {1}%만큼 모든 파티원을 치유합니다.", zhCN = "以暗影能量笼罩目标，使你在{2}秒内对其造成的所有暗影法术伤害的{1}%转化为对全体小队成员的治疗。吸血鬼的拥抱还会使受其影响的敌人死亡时，有几率触发你的精神分流天赋。", zhTW = "以暗影能量籠罩目標，使你在{2}秒內對其造成的所有暗影法術傷害的{1}%轉化為對全體小隊成員的治療。吸血鬼的擁抱還會使受其影響的敵人死亡時，有機率觸發你的精神分流天賦。" },
	["after being struck by a melee or ranged critical hit, or suffering more than #% of your maximum health from a single attack, heal #% of the damage taken over # sec"] = { ko = "근접 및 원거리 치명타 공격을 받거나 한 번의 공격으로 최대 생명력의 {1}%를 넘는 피해를 받으면 {3}초에 걸쳐 받은 피해의 {2}%만큼 생명력을 회복합니다.", zhCN = "在遭受近战或远程爆击，或单次攻击受到超过最大生命值{1}%的伤害后，在{3}秒内恢复相当于所受伤害{2}%的生命值。", zhTW = "受到近戰或遠程致命一擊，或單次攻擊承受超過相當於你生命力上限{1}%的傷害後，在{3}秒內治療受到傷害的{2}%。" },
	["after being struck by a melee or ranged critical hit, or suffering more than #% of your maximum health from a single attack, heal #% of the damage taken over # sec. refreshing this effect carries over any remaining healing"] = { ko = "근접 및 원거리 치명타 공격을 받거나 한 번의 공격으로 최대 생명력의 {1}%를 넘는 피해를 받으면 {3}초에 걸쳐 받은 피해의 {2}%만큼 생명력을 회복합니다. 이 효과를 갱신하면 남은 치유량이 이월됩니다.", zhCN = "在遭受近战或远程爆击，或单次攻击受到超过最大生命值{1}%的伤害后，在{3}秒内恢复相当于所受伤害{2}%的生命值。刷新该效果时会保留剩余治疗量。", zhTW = "受到近戰或遠程致命一擊，或單次攻擊承受超過相當於你生命力上限{1}%的傷害後，在{3}秒內治療受到傷害的{2}%。重置此效果會繼承剩餘的所有治療效果。" },
	["after entering combat, reduce the next instance of physical damage taken within # sec by #"] = { ko = "전투가 시작된 후 {1}초 안에 받는 다음 물리 피해가 {2}만큼 감소합니다." },
	["after getting a critical effect from your flash of light, holy light, light's vigil, or holy shock heal spell you have a #% chance to gain mana equal to #% of the base cost of the spell"] = { ko = "빛의 섬광이나 성스러운 빛, 빛의 경계, 신성 충격의 치유 효과가 극대화 효과를 발휘하면 {1}%의 확률로 해당 주문의 기본 마나 소모량의 {2}%에 해당하는 마나를 회복합니다.", zhCN = "在你的圣光闪现、圣光术、圣光守夜或神圣震击治疗法术造成爆击效果后，你有{1}%的几率回复相当于该法术基础消耗{2}%的法力值。", zhTW = "在你的聖光閃現、聖光術、聖光戒備或神聖震擊等治療法術造成極效治療後，你有{1}%的機率獲得該法術基礎法力消耗的{2}%法力。" },
	["after killing a non-trivial enemy, gives you a #% increased critical strike chance on your next sinister strike, backstab, ambush, mutilate, or ghostly strike"] = { ko = "사소하지 않은 적을 처치하면 다음 사악한 일격, 기습, 매복, 절단 또는 그림자 일격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "击杀一个能为你提供经验值或荣誉值的敌人后，使你的下一次邪恶攻击、背刺、伏击、毁伤或鬼魅攻击的爆击几率提高{1}%。" },
	["after killing a non-trivial enemy, gives you a #% increased critical strike chance on your next sinister strike, backstab, ambush, mutilate, or ghostly strike. lasts # sec"] = { ko = "사소하지 않은 적을 처치하면 다음 사악한 일격, 기습, 매복, 절단 또는 그림자 일격의 치명타 및 극대화율이 {1}%만큼 증가합니다. {2}초 동안 지속됩니다.", zhCN = "击杀一个能为你提供经验值或荣誉值的敌人后，使你的下一次邪恶攻击、背刺、伏击、毁伤或鬼魅攻击的爆击几率提高{1}%。持续{2}秒。", zhTW = "在殺死一個有實力的敵人後，使你的下一次邪惡攻擊、背刺、伏擊、截肢或鬼魅攻擊造成致命一擊的機率提高{1}%，效果持續{2}秒。" },
	["after the effect expires, the health is lost"] = { ko = "20초 동안 지속되며 지속시간이 끝나면 임시 생명력은 사라집니다.", zhCN = "效果结束后会失去这些生命值。", zhTW = "效果結束後，這些生命力會被扣除。" },
	["aimed shot shares its cooldown with multi-shot"] = { ko = "조준 사격은 일제 사격과 재사용 대기시간을 공유합니다.", zhCN = "瞄准射击与多重射击共享冷却时间。", zhTW = "瞄準射擊與多重射擊共用冷卻時間。" },
	["all camping features share a cooldown of # hr"] = { ko = "모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "所有露营功能共享{1}小时冷却时间。", zhTW = "所有紮營功能共享{1}小時冷卻時間。" },
	["all critical strikes against you cause #% of the damage taken to the attacker as well"] = { ko = "자신이 치명타 및 극대화 공격을 받으면 공격자에게 받은 피해의 {1}%에 해당하는 피해를 입힙니다.", zhCN = "所有对你造成的爆击也会对攻击者造成相当于你所受伤害{1}%的伤害。" },
	["all critical strikes against you cause #% of the damage taken to the attacker as well. the damage caused by eye for an eye will not exceed #% of the paladin's total health"] = { ko = "자신이 치명타 및 극대화 공격을 받으면 공격자에게 받은 피해의 {1}%에 해당하는 피해를 입힙니다. 눈에는 눈 특성으로 인한 피해는 성기사 최대 생명력의 {2}%를 초과하지 않습니다.", zhCN = "所有对你造成的爆击也会对攻击者造成相当于你所受伤害{1}%的伤害。以眼还眼造成的伤害不会超过圣骑士总生命值的{2}%。", zhTW = "你受到的所有致命一擊都會令攻擊者受到該次攻擊{1}%的傷害，但以眼還眼造成的傷害不會超過聖騎士生命力上限的{2}%。" },
	["all enemies within # yards will be slowed by #% while in the area of effect"] = { zhCN = "效果区域内{1}码范围的所有敌人移动速度降低{2}%。", zhTW = "所有在{1}碼範圍內的敵人的移動速度都會降低{2}%。" },
	["all non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by #% for # sec"] = { ko = "비주기적 주문이 치명타 및 극대화 효과를 발휘할 때마다 자연의 축복을 받아 {2}초 동안 주문 시전 속도가 {1}%만큼 증가하고 전역 재사용 대기시간은 그만큼 감소합니다.", zhCN = "你的所有非周期性法术爆击都会使你获得自然的赐福，使施法速度提高并公共冷却时间缩短{1}%，持续{2}秒。", zhTW = "你的任何非週期性法術造成致命一擊後可獲得自然的賜福，使你的施法速度提高{1}%，且共用冷卻時間也縮短相同的百分比，持續{2}秒。" },
	["allows #% of your mana regeneration to continue while casting"] = { ko = "시전 중에도 평소의 {1}%에 달하는 속도로 마나가 회복됩니다.", zhCN = "使你在施法时仍保持{1}%的法力值恢复速度。", zhTW = "使你在施法時仍保持{1}%的法力恢復速度。" },
	["allows health funnel to be used regardless of your demon's health"] = { zhCN = "无论恶魔的生命值如何都可以使用生命通道。", zhTW = "可無視惡魔的生命力隨時使用生命通道。" },
	["allows one-hand and off-hand weapons to be equipped in the off-hand"] = { ko = "두 가지의 한손 무기를 동시에 착용할 수 있습니다.", zhCN = "可以在副手上装备单手和副手武器。", zhTW = "可以在副手上裝備單手和副手武器。" },
	["allows opening of locked chests and doors"] = { ko = "잠긴 상자나 문을 열 수 있습니다.", zhCN = "可以打开上锁的箱子和门。", zhTW = "可以打開上鎖的箱子和門。" },
	["allows the caster to levitate, floating a few feet above the ground"] = { ko = "시전자가 몸을 공중에 띄운 상태로 이동할 수 있도록 합니다.", zhCN = "使施法者漂浮在离地数尺的空中。" },
	["allows the caster to levitate, floating a few feet above the ground. while levitating, you will fall at a reduced speed and travel over water-like surfaces. mounting or any damage taken will cancel the effect. lasts # min"] = { ko = "시전자가 몸을 공중에 띄운 상태로 이동할 수 있도록 합니다. 공중 부양 중에는 낙하 속도가 감소하며 물 위를 걸을 수 있습니다. 탈것에 타거나 피해를 받으면 효과가 사라집니다. {1}분 동안 지속됩니다.", zhCN = "使施法者漂浮在离地数尺的空中。漂浮时，你的下落速度降低，并可在水面等表面上移动。骑乘坐骑或受到任何伤害都会取消该效果。持续{1}分钟。", zhTW = "使施法者可以漂浮在地面上，漂浮時墜落的速度將大幅減緩，並可於水體表面行走。騎乘坐騎或受到任何傷害都會中斷漂浮效果。持續{1}分鐘。" },
	["allows the caster to see through the target's eyes for # min"] = { ko = "{1}분 동안 대상의 눈을 통해 주위를 볼 수 있습니다.", zhCN = "使施法者通过目标的眼睛观察世界，持续{1}分钟。", zhTW = "使施法者通過目標的眼睛觀察世界，持續{1}分鐘。" },
	["allows the caster to see through the target's eyes for # min. will not work if the target is in another instance or on another continent"] = { ko = "{1}분 동안 대상의 눈을 통해 주위를 볼 수 있습니다. 대상이 다른 대륙이나 인스턴스 지역에 있을 때는 사용할 수 없습니다.", zhCN = "使施法者通过目标的眼睛观察世界，持续{1}分钟。如果该目标身处另一个副本区域或另一块大陆则无法施展。", zhTW = "使施法者通過目標的眼睛觀察世界，持續{1}分鐘。如果該目標身處另一個副本區域或另一塊大陸則無法施展。" },
	["allows the druid to prowl around, but reduces your movement speed by #%"] = { ko = "은신한 상태로 이동할 수 있지만 이동 속도가 {1}%만큼 감소합니다." },
	["allows the druid to prowl around, but reduces your movement speed by #%. lasts until cancelled"] = { ko = "은신한 상태로 이동할 수 있지만 이동 속도가 {1}%만큼 감소합니다. 취소할 때까지 지속됩니다.", zhCN = "使德鲁伊进入潜行状态，但是移动速度降低{1}%，效果一直持续，直到取消。", zhTW = "使德魯伊進入潛行狀態，但是移動速度降低{1}%，效果一直持續，直到取消。" },
	["allows the friendly target to detect greater invisibility for # min"] = { ko = "대상은 {1}분 동안 상급 투명체를 감지할 수 있습니다.", zhCN = "让友方目标能够侦查到强效隐形术，持续{1}分钟。", zhTW = "讓友方目標能夠偵查到強效隱形術，持續{1}分鐘。" },
	["allows the friendly target to detect invisibility for # min"] = { ko = "대상은 {1}분 동안 투명체를 감지할 수 있습니다.", zhCN = "让友方目标能够侦查到隐形术，持续{1}分钟。", zhTW = "讓友方目標能夠偵查到隱形術，持續{1}分鐘。" },
	["allows the friendly target to detect lesser invisibility for # min"] = { ko = "아군 대상이 {1}분 동안 하급 투명체를 감지할 수 있도록 만듭니다.", zhCN = "让友方目标能够侦查到次级隐形术，持续{1}分钟。", zhTW = "讓友方目標能夠偵查到次級隱形術，持續{1}分鐘。" },
	["allows the friendly target to walk across water for # min"] = { ko = "대상에 주술을 걸어 {1}분 동안 물 위를 걸을 수 있도록 합니다.", zhCN = "使友方目标可以在水面上行走，持续{1}分钟。", zhTW = "使友方目標可以在水面或類似的表面上行走，持續{1}分鐘。" },
	["allows the friendly target to walk across water for # min. any damage will cancel the effect"] = { ko = "대상에 주술을 걸어 {1}분 동안 물 위를 걸을 수 있도록 합니다. 피해를 받으면 효과가 사라집니다.", zhCN = "使友方目标可以在水面上行走，持续{1}分钟。任何伤害都会取消水上行走效果。", zhTW = "使友方目標可以在水面或類似的表面上行走，持續{1}分鐘。受到任何傷害都會解除水上行走效果。" },
	["allows the rogue to sneak around, but reduces your speed by #%"] = { ko = "은신한 상태로 이동할 수 있지만 이동 속도가 {1}%만큼 감소합니다." },
	["allows the rogue to sneak around, but reduces your speed by #%. lasts until cancelled"] = { ko = "은신한 상태로 이동할 수 있지만 이동 속도가 {1}%만큼 감소합니다. 취소할 때까지 지속됩니다.", zhCN = "使潜行者进入潜行状态，但是移动速度降低{1}%，效果一直持续，直到取消。", zhTW = "使盜賊進入潛行狀態，但是移動速度降低{1}%，效果一直持續，直到取消。" },
	["allows the rogue to vanish from sight, entering an improved stealth mode for # sec"] = { ko = "{1}초 동안 시야에서 사라져 상급 은신 상태를 취합니다.", zhCN = "使潜行者从视野中消失，进入强化的潜行模式，持续{1}秒。" },
	["allows the rogue to vanish from sight, entering an improved stealth mode for # sec. also breaks movement impairing effects"] = { ko = "{1}초 동안 시야에서 사라져 상급 은신 상태를 취합니다. 이동 방해 효과에서 벗어날 수 있습니다.", zhCN = "使潜行者从视野中消失，进入强化的潜行模式，持续{1}秒。同时解除一切移动限制效果。", zhTW = "使盜賊消失，進入強化的潛行模式，持續{1}秒，同時解除移動限制效果。" },
	["allows the rogue to vanish from sight, entering an improved stealth mode for # sec. also breaks movement impairing effects. more effective than vanish (rank #)"] = { ko = "{1}초 동안 시야에서 사라져 상급 은신 상태를 취합니다. 이동 방해 효과에서 벗어날 수 있습니다. {2} 레벨 소멸보다 효과가 좋습니다.", zhCN = "使潜行者从视野中消失，进入强化的潜行模式，持续{1}秒。同时解除一切移动限制效果。比消失（等级 {2}）更有效。", zhTW = "使盜賊消失並進入強化的潛行狀態，持續{1}秒，同時移除移動限制效果。比消失（等級{2}）更有效。" },
	["allows the target to breathe underwater for # min"] = { ko = "대상을 {1}분 동안 물 속에서 숨쉴 수 있도록 해줍니다.", zhCN = "使目标可以在水下自由呼吸，持续{1}分钟。", zhTW = "使目標可以在水下自由呼吸，持續{1}分鐘。" },
	["allows you to look far into the distance"] = { ko = "더 먼 곳까지 볼 수 있습니다.", zhCN = "使你看得更远。", zhTW = "使你看得更遠。" },
	["allows you to resurrect yourself upon death with #% health and mana"] = { ko = "{1}%의 생명력과 마나를 지닌 채로 스스로 죽음에서 부활할 수 있습니다.", zhCN = "使你可以在死后自行复活并回复{1}%的生命值和法力值。", zhTW = "使你可以在死後自行復活並回復{1}%的生命力和法力。每小時可用一次。" },
	["also breaks movement impairing effects"] = { ko = "이동 방해 효과에서 벗어날 수 있습니다.", zhCN = "同时解除一切移动限制效果。" },
	["also frees the caster from stuns and immobilizes"] = { ko = "전방에는 장애물이 없어야 합니다.", zhCN = "同时解除施法者的昏迷和定身效果。" },
	["also silences targets in the blast for # sec"] = { ko = "또한 {1}초 동안 대상을 침묵시킵니다.", zhCN = "同时使爆炸范围内的目标沉默{1}秒。", zhTW = "同時使爆炸範圍內的目標沉默{1}秒。" },
	["ambush the target, causing #% weapon damage plus # to the target. must be stealthed and behind the target. requires a dagger in the main hand. awards # combo point"] = { ko = "매복한 상태에서 적을 급습하여 무기 공격력의 {1}%에 추가로 {2}의 피해를 입힙니다. 주무기로 단검을 착용해야 하며 적의 배후에서 은신 상태로 사용해야 합니다. {3}의 연계 포인트가 주어집니다.", zhCN = "伏击目标，对其造成{1}%的武器伤害再加上{2}点额外伤害。必须在潜行状态下从目标背后发动。奖励{3}个连击点数。", zhTW = "伏擊目標，對其造成{1}%的武器傷害再加上{2}點額外傷害。必須在潛行狀態下從目標背後發動。獎勵{3}個連擊點數。" },
	["amplifies magic used against the targeted party member, increasing damage taken from spells by up to # and healing spells by up to #"] = { ko = "대상 파티원에게 미치는 마법의 위력을 증폭시켜 치유 주문에 의한 회복량을 최대 {2}만큼 증가시키지만, 마법 공격으로 받는 피해가 최대 {1}만큼 증가됩니다." },
	["amplifies magic used against the targeted party member, increasing damage taken from spells by up to # and healing spells by up to # lasts # min"] = { ko = "대상 파티원에게 미치는 마법의 위력을 증폭시켜 치유 주문에 의한 회복량을 최대 45만큼 증가시키지만, 마법 공격으로 받는 피해가 최대 {1}만큼 증가됩니다. {3}분 동안 지속됩니다.", zhCN = "增强施放于目标小队成员身上的魔法效果，使其受到的法术伤害最多提高{1}点，治疗法术所恢复的生命值最多提高45点，持续{3}分钟。", zhTW = "增強施放於目標小隊成員身上的魔法效果，使其受到的法術傷害最多提高{1}點，治療法術所恢復的生命力最多提高45點，持續{3}分鐘。" },
	["an aggressive stance"] = { ko = "공격적인 전투 태세입니다.", zhCN = "攻击型姿态。" },
	["an aggressive stance. critical strike chance increased by #% and all damage taken is increased by #%"] = { ko = "공격적인 전투 태세입니다. 치명타 및 극대화율이 {1}%만큼 증가하지만, 받는 모든 피해가 {2}%만큼 증가합니다.", zhCN = "攻击型姿态。爆击几率提高{1}%，受到的所有伤害提高{2}%。", zhTW = "攻擊型的姿態，致命一擊機率提高{1}%，受到的所有傷害提高{2}%。" },
	["an aimed shot that increases ranged damage by #"] = { ko = "적을 정확하게 조준하여 {1}의 추가 원거리 피해를 입힙니다.", zhCN = "瞄准射击，使远程伤害提高{1}点。", zhTW = "仔細瞄準目標的射擊，使遠程傷害提高{1}點。" },
	["an aimed shot that increases ranged damage by # aimed shot shares its cooldown with multi-shot"] = { ko = "적을 정확하게 조준하여 20의 추가 원거리 피해를 입힙니다. 조준 사격은 일제 사격과 재사용 대기시간을 공유합니다.", zhCN = "瞄准射击，使远程伤害提高20点。瞄准射击与多重射击共享冷却时间。", zhTW = "仔細瞄準目標的射擊，使遠程傷害提高20點。瞄準射擊與多重射擊共用冷卻時間。" },
	["an infernal rises from the crater, under the command of the caster for # min"] = { ko = "분화구에서 일어난 지옥불정령은 {1}분 동안 흑마법사의 지배를 받습니다.", zhCN = "一个巨大的地狱火恶魔将从着陆点出现，并被施法者控制{1}分钟。", zhTW = "一個煉獄火將從著陸點出現，並受控於施法者，持續{1}分鐘。" },
	["an instant attack that lashes the target, causing # shadow damage"] = { ko = "즉시 적에게 채찍을 날려 {1}의 암흑 피해를 입힙니다.", zhCN = "一次瞬发攻击，鞭笞目标，对其造成{1}点暗影伤害。", zhTW = "立即攻擊目標，造成{1}點暗影傷害。" },
	["an instant shot that causes # arcane damage"] = { ko = "즉시 사격하여 {1}의 비전 피해를 입힙니다.", zhCN = "迅速射出一箭，对敌人造成{1}点奥术伤害。", zhTW = "迅速射出一箭，對敵人造成{1}點秘法傷害。" },
	["an instant strike that causes # damage in addition to your normal weapon damage"] = { ko = "대상을 순간적으로 공격하여 {1}의 추가 피해를 입힙니다." },
	["an instant strike that causes # damage in addition to your normal weapon damage. awards # combo point"] = { ko = "대상을 순간적으로 공격하여 {1}의 추가 피해를 입힙니다. {2}의 연계 포인트가 주어집니다.", zhCN = "对目标造成普通武器伤害再加上{1}点额外伤害，奖励{2}个连击点数。", zhTW = "對目標造成普通武器傷害再加上{1}點額外傷害，獎勵{2}個連擊點數。" },
	["an instant strike that causes #% weapon damage plus an additional # to # as holy damage"] = { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%에 {2}~{3}의 추가 신성 피해를 입힙니다.", zhCN = "立即打击，造成{1}%武器伤害，外加{2}至{3}点神圣伤害。", zhTW = "立即對敵人造成{1}%的武器傷害，同時額外造成{2}至{3}點神聖傷害。" },
	["an instant strike that deals #% weapon damage (#% if a dagger is equipped) and causes the target to take #% increased rupture damage from the rogue"] = { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%(단검 착용 시 {2}%)에 해당하는 피해를 입히고 대상이 도적의 파열로 받는 피해를 {3}%만큼 증가시킵니다." },
	["an instant strike that deals #% weapon damage (#% if a dagger is equipped) and causes the target to take #% increased rupture damage from the rogue. lasts # sec. awards # combo point"] = { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%(단검 착용 시 {2}%)에 해당하는 피해를 입히고 대상이 도적의 파열로 받는 피해를 {3}%만큼 증가시킵니다. {4}초 동안 지속됩니다. 연계 점수 {5}점을 생성합니다.", zhCN = "发动瞬发打击，造成{1}%武器伤害（装备匕首时为{2}%），并使目标受到来自游荡者的割裂伤害提高{3}%，持续{4}秒。奖励{5}个连击点数。", zhTW = "立即對目標造成{1}%的武器傷害（如果裝備匕首則為{2}%），並使盜賊對目標造成的割裂傷害提高{3}%，持續{4}秒。獎勵{5}個連擊點數。" },
	["any damage caused will awaken the target"] = { ko = "대상이 피해를 입으면 깨어납니다.", zhCN = "造成任何伤害都会唤醒目标。", zhTW = "任何傷害都會喚醒目標。" },
	["any damage caused will break the ice"] = { ko = "적이 다가오면 얼려서 최대 10초 동안 모든 행동을 불가능하게 만듭니다.", zhCN = "造成任何伤害都会打破冰冻。", zhTW = "任何傷害都會中斷冰凍效果。" },
	["any damage caused will release the target"] = { ko = "대상은 피해를 입으면 해제됩니다.", zhCN = "任何对其造成伤害的行为都将解除束缚。", zhTW = "任何對其造成傷害的行為都將解除束縛。" },
	["any damage caused will remove the effect"] = { ko = "피해를 입게 되면 효과가 사라집니다.", zhCN = "任何伤害都会打断该效果。", zhTW = "任何傷害都會打斷該效果。" },
	["any damage taken will break the effect"] = { ko = "피해를 받으면 효과가 해제됩니다.", zhCN = "受到任何伤害都会打破该效果。", zhTW = "受到任何傷害都會中斷此效果。" },
	["any damage will awaken the target"] = { ko = "대상이 피해를 입으면 깨어납니다." },
	["any damage will break the effect"] = { ko = "대상이 피해를 받으면 효과가 사라집니다.", zhCN = "任何伤害都会打断此效果。", zhTW = "任何傷害都會打斷此效果。" },
	["any damage will cancel the effect"] = { ko = "피해를 받으면 효과가 사라집니다.", zhCN = "任何伤害都会取消沉睡效果。", zhTW = "任何傷害都會取消沉睡效果。" },
	["any successful spell cast against the priest will burn # of the attacker's mana, causing # shadow damage for each point of mana burned"] = { ko = "자신에게 주문이 적중했을 경우 공격자의 마나를 {1}만큼 소진시키고 소진된 마나 당 {2}의 암흑 피해를 입힙니다.", zhCN = "任何对牧师成功施放的敌对法术都会令施法者损失{1}点法力值，并对其造成等量的暗影伤害。" },
	["applies forbearance for # min"] = { ko = "{1}분 동안 참을성이 부여됩니다.", zhCN = "施加自律，持续{1}分钟。", zhTW = "施加自律效果，持續{1}分鐘。" },
	["applies light's vigil to the target for # sec"] = { ko = "{1}초 동안 대상에게 빛의 경계를 겁니다." },
	["applies light's vigil to the target for # sec. your next holy shock cast on them triggers no cooldown and causes enemy targets to suffer # to # holy damage and refund #% of light's vigil's mana cost, or allied targets to heal their party for # to # you may only have one light's vigil active per party"] = { ko = "{1}초 동안 대상에게 빛의 경계를 겁니다. 다음에 그 대상에게 시전하는 신성 충격은 재사용 대기시간이 발생하지 않으며, 적이면 {2}~{3}의 신성 피해를 입히고 빛의 경계 마나 비용의 {4}%를 돌려받고, 아군이면 그 파티원을 {5}~333만큼 치유합니다. 빛의 경계는 파티당 하나만 유지할 수 있습니다.", zhCN = "Applies Light's Vigil to the target for {1}秒. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer {2}至{3} Holy damage and refund {4}% of Light's Vigil's Mana cost, or allied targets to heal their party for {5}至{6} The Paladin may only have one Light's Vigil active per party.", zhTW = "Applies Light's Vigil to the target for {1}秒. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer {2}至{3} Holy damage and refund {4}% of Light's Vigil's Mana cost, or allied targets to heal their party for {5}至{6} The Paladin may only have one Light's Vigil active per party." },
	["armor increased by #"] = { ko = "방어도가 {1}만큼 증가합니다.", zhCN = "护甲值提高{1}点。", zhTW = "護甲值值提高{1}點。" },
	["assault the target's mind with shadow energy, causing # shadow damage over # sec and slowing their movement speed by #%"] = { ko = "대상의 정신을 암흑의 기운으로 공격하여, {2}초에 걸쳐 {1}의 암흑 피해를 입히고 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "以暗影能量冲击目标的心灵，在{2}秒内造成{1}点暗影伤害，并使其移动速度降低{3}%。", zhTW = "以暗影能量攻擊目標的心智，在{2}秒內對其造成{1}點暗影傷害，並使其移動速度降低{3}%。" },
	["assembles a camp chair that allows you and others sitting nearby to gain #% increased critical strike chance with all spells and attacks, mutually exclusive with moonkin aura"] = { ko = "야영지 의자를 조립해 자신과 주위에 앉은 다른 플레이어의 모든 주문 및 공격의 치명타 및 극대화율을 {1}%만큼 증가시킵니다. 달빛야수 오라와 겸용해서 사용할 수 없습니다.", zhCN = "组装一把营地椅子，使你和附近坐下的其他人所有法术和攻击的爆击几率提高{1}%，与枭兽光环不叠加。", zhTW = "組裝一把營地椅子，使你和附近坐下的其他人所有法術和攻擊的致命一擊機率提高{1}%，與梟獸光環不疊加。" },
	["assume shadowform, increasing your shadow damage by #%, reducing the mana cost of all shadow spells by #%, increasing the critical strike damage bonus of your shadow spells by #%, and reducing physical damage taken by you by #%"] = { zhCN = "进入暗影形态，使你的暗影伤害提高{1}%，所有暗影法术消耗的法力值降低{2}%，暗影法术的爆击伤害加成提高{3}%，你受到的物理伤害降低{4}%。", zhTW = "進入暗影形態，使你造成的暗影傷害提高{1}%，所有暗影法術的法力消耗降低{2}%，暗影法術的致命一擊傷害加成提高{3}%，你受到的物理傷害降低{4}%。" },
	["assume shadowform, increasing your shadow damage by #%, reducing the mana cost of all shadow spells by #%, increasing the critical strike damage bonus of your shadow spells by #%, and reducing physical damage taken by you by #%. however, you may not cast healing spells while in this form"] = { ko = "어둠의 형상을 취해 암흑 공격력이 {1}%만큼 증가하고 모든 암흑 주문의 마나 소모량이 {2}%만큼 감소합니다. 추가로 암흑 주문의 치명타 및 극대화 피해 증가량이 {3}%만큼 증가하며, 받는 물리 피해가 {4}%만큼 감소합니다. 하지만 이 상태에서는 치유 주문을 시전하지 못합니다.", zhCN = "进入暗影形态，使你的暗影伤害提高{1}%，所有暗影法术消耗的法力值降低{2}%，暗影法术的爆击伤害加成提高{3}%，你受到的物理伤害降低{4}%。但是在此形态下，你无法施放治疗法术。", zhTW = "進入暗影形態，使你造成的暗影傷害提高{1}%，所有暗影法術的法力消耗降低{2}%，暗影法術的致命一擊傷害加成提高{3}%，你受到的物理傷害降低{4}%。然而，在此形態下你無法施放治療法術。" },
	["attaches a permanent scope to a bow, gun, or crossbow that increases its critical strike chance by #%"] = { ko = "활이나 총, 석궁에 영구적으로 장착하여 치명타 및 극대화율을 {1}%만큼 증가시킵니다.", zhCN = "在弓、枪械或弩上加装永久性的瞄准镜，使其爆击几率提高{1}%。", zhTW = "在弓、槍械或弩上加裝永久性的瞄準鏡，使其致命一擊機率提高{1}。" },
	["attack all nearby enemies, dealing weapon damage plus # every # sec for # sec, and reducing your own movement speed by #%"] = { ko = "주위 모든 적을 공격해 {3}초 동안 {2}초마다 무기 공격력에 {1}의 피해를 합산하여 입히고, 자신의 이동 속도를 {4}%만큼 감소시킵니다.", zhCN = "攻击附近的所有敌人，每{2}秒造成武器伤害外加{1}点伤害，持续{3}秒，并使你的移动速度降低{4}%。", zhTW = "攻擊附近所有敵人，造成武器傷害，同時每{2}秒額外造成{1}點傷害，持續{3}秒，並使你的移動速度降低{4}%。" },
	["attackers can only be damaged once every few seconds"] = { ko = "이로 인한 피해는 위협 수준을 발생시키지 않습니다.", zhCN = "一个攻击者在短期内只会受到一次反噬伤害。", zhTW = "一個攻擊者在短期內只會受到一次反噬傷害。" },
	["attacks have a #% chance to"] = { zhCN = "攻击有{1}%的几率对目标", zhTW = "攻擊有{1}%的機率對目標" },
	["attempt to finish off a wounded foe, causing # damage and converting each extra point of rage into # additional damage"] = { ko = "상처 입은 적에게 마무리 일격을 시도하여 {1}의 피해를 입히고 나머지 분노를 모두 소모하여 분노당 {2}의 피해를 추가로 입힙니다.", zhCN = "尝试杀死一个受伤的敌人，对其造成{1}点基础伤害，并将每一个额外的怒气点数转化为{2}点额外伤害。", zhTW = "嘗試殺死一個受傷的敵人，對其造成{1}點基礎傷害，並將每一個額外的怒氣點數轉化為{2}點額外傷害。" },
	["attempt to finish off a wounded foe, causing # damage and converting each extra point of rage into # additional damage. only usable on enemies that have #% or less health"] = { ko = "상처 입은 적에게 마무리 일격을 시도하여 {1}의 피해를 입히고 나머지 분노를 모두 소모하여 분노당 {2}의 피해를 추가로 입힙니다. 생명력이 {3}%미만인 적에게만 사용할 수 있습니다.", zhCN = "尝试杀死一个受伤的敌人，对其造成{1}点基础伤害，并将每一个额外的怒气点数转化为{2}点额外伤害。只对生命值少于{3}%的敌人有效。", zhTW = "嘗試殺死一個受傷的敵人，對其造成{1}點基礎傷害，並將每一個額外的怒氣點數轉化為{2}點額外傷害。只對生命力少於{3}%的敵人有效。" },
	["attempts to cure # disease effect on the target, and # more disease effect every # sec for # sec"] = { ko = "질병 {1}개의 치료를 시도하고 추가로 {4}초 동안 매 {3}초마다 {2}개의 질병 해제를 시도합니다.", zhCN = "尝试驱散目标身上的{1}个疾病效果，并每{3}秒驱散{2}个疾病效果，持续{4}秒。", zhTW = "嘗試驅散目標身上的{1}個疾病效果，並每{3}秒驅散{2}個疾病效果，持續{4}秒。" },
	["attempts to cure # poison effect on the target, and # more poison effect every # sec for # sec"] = { ko = "독 {1}개의 치료를 시도하고 추가로 {4}초 동안 매 {3}초마다 {2}개의 독 해제를 시도합니다.", zhCN = "尝试驱散目标身上的{1}个中毒效果，并每{3}秒驱散{2}个中毒效果，持续{4}秒。", zhTW = "嘗試驅散目標身上的{1}個中毒效果，並每{3}秒驅散{2}個中毒效果，持續{4}秒。" },
	["attempts to disengage from the target by reducing threat"] = { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다.", zhCN = "尝试脱离目标，降低威胁值。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。" },
	["attempts to disengage from the target by reducing threat. disables auto-attack"] = { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다. 자동 공격을 비활성화합니다.", zhCN = "尝试脱离目标，降低威胁值。停用自动攻击。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。停用自動攻擊。" },
	["attempts to disengage from the target by reducing threat. more effective than disengage (rank #). disables auto-attack"] = { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다. 철수 {1}레벨보다 효과가 높습니다. 자동 공격이 비활성화됩니다.", zhCN = "尝试通过降低威胁来脱离目标。比逃脱（等级 {1}）更有效。会停止自动攻击。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。比逃脫（等級{1}）更有效。停用自動攻擊。" },
	["attempts to remove # frenzy effect from an enemy creature"] = { ko = "적에게서 광기 효과 {1}개의 제거를 시도합니다.", zhCN = "尝试从一个敌方生物身上移除{1}个疯狂效果。", zhTW = "嘗試從一個敵方生物身上移除{1}個瘋狂效果。" },
	["augment your belt to give the following effect:"] = { ko = "허리띠를 강화하여 아래 효과를 부여합니다.", zhCN = "强化你的腰带，提供以下效果：", zhTW = "強化你的腰帶，提供以下效果：" },
	["automatically shoots the target until cancelled"] = { ko = "취소할 때까지 자동으로 적을 공격합니다.", zhCN = "自动射击目标，直到取消。", zhTW = "自動射擊目標，直到取消。" },
	["awards # combo point"] = { ko = "{1}의 연계 포인트가 주어집니다.", zhCN = "奖励{1}个连击点数。", zhTW = "獎勵{1}個連擊點數。" },
	["awards # combo points"] = { ko = "{1}의 연계 포인트가 주어집니다.", zhCN = "奖励{1}个连击点。", zhTW = "獎勵{1}個連擊點數。" },
	["axe/polearm: increases your"] = { zhCN = "斧/长柄武器：使你的", zhTW = "斧/長柄武器：使你的" },
	["axe/sword: your successful"] = { zhTW = "斧/劍：近戰攻擊" },
	["backstab the target, causing #% weapon damage plus # to the target. must be behind the target. requires a dagger in the main hand. awards # combo point"] = { ko = "적을 기습하여 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다. 주장비에 단검을 착용해야 하며 적의 배후에서 공격해야 합니다. {3}의 연계 점수를 얻습니다.", zhCN = "背刺目标，对其造成{1}%的武器伤害外加{2}点伤害，必须在目标背后发动，你的主手中必须有一把匕首。奖励{3}个连击点数。", zhTW = "背刺目標，對其造成{1}%武器傷害再加上{2}點傷害，必須在目標背後發動，需要在主手裝備匕首。獎勵{3}個連擊點數。" },
	["bane of havoc is limited to # target, and only one bane per warlock can be active on any one target"] = { zhCN = "浩劫灾祸只能影响{1}个目标，且每个术士在任一目标身上只能维持一种灾祸。", zhTW = "僅限對{1}個目標施加浩劫之禍，且每個術士只能對同一個目標施加一種災厄。" },
	["banishes the enemy target, preventing all action but making it invulnerable for up to # sec. only one target can be banished at a time. only works on demons and elementals"] = { ko = "적을 차원의 저편으로 추방하여 어떤 행동도 하지 못하게 만듭니다. 최대 {1}초 동안 이 대상에겐 어떤 피해도 입히지 못합니다. 동시에 한 대상만 추방할 수 있습니다. 악마와 정령에게만 사용할 수 있습니다.", zhCN = "放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续{1}秒。每个术士在同一时间内只能放逐一个目标，只能对恶魔和元素生物使用。", zhTW = "放逐敵對目標，使其完全無法行動，但也不會受到任何傷害，最多持續{1}秒。每個術士在同一時間內只能放逐一個目標，只能對惡魔和元素生物使用。" },
	["bashes the target with your shield for # damage"] = { ko = "적을 방패로 가격하여 {1}의 피해를 입힙니다." },
	["bashes the target with your shield for # damage. it also interrupts spellcasting and prevents any spell in that school from being cast for # sec"] = { ko = "적을 방패로 가격하여 {1}의 피해를 입힙니다. 또한 대상이 {2}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다.", zhCN = "使用你的盾牌重击目标，对其造成{1}点伤害，并使其无法施放法术，持续{2}秒。", zhTW = "使用你的盾牌重擊目標，對其造成{1}點傷害，並使其無法施放法術，持續{2}秒。" },
	["begins a ritual that sacrifices a random participant to summon a doomguard"] = { ko = "참가자 중 한명을 무작위로 제물로 바쳐 파멸의수호병을 소환하는 의식을 올립니다.", zhTW = "進行儀式，犧牲一名隨機參與者以召喚末日守衛。" },
	["begins a ritual that sacrifices a random participant to summon a doomguard. the doomguard must be immediately subjugated or it will attack the ritual participants. requires the caster and # additional party members to complete the ritual. in order to participate, all players must right-click the portal and not move until the ritual is complete"] = { ko = "참가자 중 한명을 무작위로 제물로 바쳐 파멸의수호병을 소환하는 의식을 올립니다. 파멸의 수호병을 즉시 예속하지 않으면 의식에 참가한 사람을 공격합니다. 의식을 수행하려면 흑마법사를 제외하고 파티원 {1}명이 필요합니다. 의식에 참가하려는 플레이어는 파멸의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhCN = "进行祭祀仪式，随机牺牲一个参与者以召唤出一个末日守卫。你必须立即征服末日守卫，否则它就会攻击参与仪式者。需要施法者和{1}个队友共同进行仪式，所有参与者都必须使用右键点击传送门，在完成仪式之前不得移动。", zhTW = "進行儀式，犧牲一名隨機參與者以召喚末日守衛。務必立刻制伏該末日守衛，否則它就會攻擊儀式參與者。需要施法者以及{1}名額外的隊伍成員才能完成儀式。所有參與者都必須使用右鍵點擊傳送門，並且在完成儀式之前不得移動。" },
	["begins a ritual that summons the targeted group member"] = { ko = "대상 파티원을 소환하는 의식을 시작합니다.", zhCN = "开启一个召唤指定队友的传送门。", zhTW = "開啟一個召喚指定隊友的傳送門。" },
	["begins a ritual that summons the targeted group member. requires the caster and # additional party members to complete the ritual. in order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete"] = { ko = "대상 파티원을 소환하는 의식을 시작합니다. 의식을 수행하려면 흑마법사를 제외하고 파티원 {1}명이 필요합니다. 의식에 참가하려는 플레이어는 비전투 상태여야 하며 소환의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhCN = "开启一个召唤指定队友的传送门。需要施法者和{1}名队友共同完成召唤仪式。所有参与召唤的队友都必须使用右键点击传送门，并且在召唤完成之前不得移动。", zhTW = "開啟一個召喚指定隊友的傳送門。需要施法者和{1}名隊友共同完成召喚儀式。所有參與召喚的隊友都必須必須離開交戰狀態並使用右鍵點擊傳送門，並且在召喚完成之前不得移動。" },
	["begins taming a beast to be your companion"] = { ko = "야수를 길들여 친구로 만듭니다." },
	["begins taming a beast to be your companion. your armor is reduced by #% while you focus on taming the beast for # sec. if you lose the beast's attention for any reason, the taming process will fail. once tamed, the beast will be very unhappy and disloyal. try feeding the pet immediately to make it happy"] = { ko = "야수를 길들여 친구로 만듭니다. 야수를 길들이는 데 집중하는 {2}초 동안은 방어도가 {1}%만큼 감소합니다. 만약 이 동안 어떤 이유로든 야수의 주의가 딴데로 돌아가게 된다면 길들이는 것은 실패하게 됩니다. 길들이는 데 성공하면 만족도와 충성도가 매우 낮습니다. 즉시 먹을 것을 줘서 만족도를 높이도록 하십시오.", zhCN = "尝试驯服一只野兽，使其成为你的宠物。在这个过程中，你的护甲值降低{1}%，持续{2}秒。如果你因为任何原因失去了它的注意力，则驯服过程失败。刚刚被驯服的野兽会表现得非常烦躁而不可靠，立刻给它喂食可以让它高兴一些。", zhTW = "嘗試馴服一隻野獸，使其成為你的寵物。在這個過程中，你的護甲值降低{1}%，持續{2}秒。如果你因為任何原因失去了它的注意力，則馴服過程失敗。剛剛被馴服的野獸會表現得非常煩躁而不可靠，立刻給它餵食可以讓它高興一些。" },
	["being attacked cancels the effect"] = { ko = "공격을 받게 되면 효과가 취소됩니다.", zhCN = "被攻击会中断这个效果。", zhTW = "受到攻擊會取消此效果。" },
	["bite the target, dealing #% normal damage plus # and generating a high amount of threat"] = { ko = "대상을 물어뜯어 일반 피해의 {1}%에 {2}의 추가 피해를 입히고 높은 위협 수준을 생성합니다." },
	["blasts a target for # fire damage"] = { ko = "적을 강타하여 {1}의 화염 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点火焰伤害。", zhTW = "衝擊目標，對其造成{1}點火焰傷害。" },
	["blasts a target for # frost damage"] = { ko = "적을 강타하여 {1}의 냉기 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点冰霜伤害。", zhTW = "衝擊目標，對其造成{1}點冰霜傷害。" },
	["blasts a target for # nature damage"] = { ko = "적을 강타하여 {1}의 자연 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点自然伤害。", zhTW = "衝擊目標，對其造成{1}點自然傷害。" },
	["blasts a target for # nature damage. mechanical targets take #x damage"] = { ko = "대상에게 {1}의 자연 피해를 입힙니다. 기계 대상은 {2}배의 피해를 받습니다.", zhCN = "轰击目标，造成{1}点自然伤害。机械目标会受到{2}x倍的伤害。", zhTW = "衝擊目標，對其造成{1}點自然傷害。機械目標受到{2}x點傷害。" },
	["blasts enemies near the caster for # to # frost damage and freezes them in place for up to # sec"] = { ko = "주위의 적을 냉기로 강타하여 {1}에서 {2}의 냉기 피해를 입히고 최대 {3}초 동안 그 자리에 얼어붙게 만듭니다.", zhCN = "冲击施法者附近的所有敌人，对它们造成{1}至{2}点冰霜伤害并将其冻结在原地，最多持续{3}秒。", zhTW = "衝擊施法者附近的所有敵人，對它們造成{1}點到{2}點冰霜傷害並將其凍結在原地，最高可持續{3}秒。" },
	["blasts enemies near the caster for # to # frost damage and freezes them in place for up to # sec. damage caused may interrupt the effect"] = { ko = "주위의 적을 냉기로 강타하여 {1}에서 {2}의 냉기 피해를 입히고 최대 {3}초 동안 그 자리에 얼어붙게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.", zhCN = "冲击施法者附近的所有敌人，对它们造成{1}至{2}点冰霜伤害并将其冻结在原地，最多持续{3}秒。对被冻结的目标造成伤害可能打断这个效果。", zhTW = "衝擊施法者附近的所有敵人，對它們造成{1}點到{2}點冰霜傷害並將其凍結在原地，最高可持續{3}秒。任何傷害將會中止此效果。" },
	["blasts nearby enemies with thunder increasing, the time between their attacks by #% for # sec and doing # damage to them"] = { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" },
	["blasts nearby enemies with thunder increasing, the time between their attacks by #% for # sec and doing # damage to them. will affect up to # targets"] = { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다. 최대 {4}명의 대상에게 영향을 줍니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" },
	["blasts nearby enemies with thunder, increasing the time between their attacks by #% for # sec and doing # damage to them"] = { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" },
	["blasts nearby enemies with thunder, increasing the time between their attacks by #% for # sec and doing # damage to them. will affect up to # targets"] = { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다. 최대 {4}명의 대상에게 영향을 줍니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" },
	["blasts nearby enemies, increasing the time between their attacks by #% for # sec and doing # damage to them"] = { ko = "주위 적을 강타하여 {2}의 피해를 입히고 {3}초 동안 적의 공격 간격을 {1}%만큼 늘입니다.", zhCN = "冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" },
	["blasts nearby enemies, increasing the time between their attacks by #% for # sec and doing # damage to them. will affect up to # targets"] = { ko = "주위 적을 강타하여 {2}의 피해를 입히고 {3}초 동안 적의 공격 간격을 {1}%만큼 늘입니다. 최대 {4}개의 대상에게 영향을 미칩니다.", zhCN = "冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" },
	["blasts the enemy for # to # fire damage"] = { ko = "적을 강타하여 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "施放火焰冲击敌人，对其造成{1}至{2}点火焰伤害。", zhTW = "施放火焰衝擊敵人，對其造成{1}至{2}點火焰傷害。" },
	["blasts the target for # to # shadow damage, but causes a high amount of threat"] = { ko = "대상의 정신을 분열시켜 {1}~{2}의 암흑 피해를 입힙니다. 대상에 대한 위협 수준이 크게 증가합니다.", zhCN = "用暗影魔法冲击敌人，对其造成{1}至{2}点暗影伤害，同时产生很高的威胁值。", zhTW = "用暗影魔法衝擊敵人，對敵人造成{1}至{2}點暗影傷害，同時產生很高的威脅值。" },
	["blasts the target with energy, dealing # to # arcane damage"] = { ko = "적을 강력한 에너지로 강타하여 {1}~{2}의 비전 피해를 입힙니다.", zhCN = "用能量冲击目标，造成{1}至{2}点奥术伤害。", zhTW = "以能量衝擊目標，對其造成{1}至{2}點秘法傷害。" },
	["blasts the target with energy, dealing # to # arcane damage. each time you cast arcane blast, the damage of all your other spells is increased by #% and the mana cost of arcane blast is increased by #%. effect stacks up to # times and lasts # sec or until any other damage spell is cast"] = { ko = "적을 강력한 에너지로 강타하여 {1}~{2}의 비전 피해를 입힙니다. 이 주문을 시전할 때마다 다른 모든 주문의 공격력이 {3}%만큼, 비전 작렬 주문의 마나 소모량이 {4}%만큼 증가합니다. 이 효과는 최대 {5}번까지 중첩되며 {6}초 동안 혹은 비전 작렬을 제외한 다른 공격 주문 시전 시까지 지속됩니다.", zhCN = "用能量冲击目标，造成{1}至{2}点奥术伤害。每次施放奥术冲击，所有其他法术的伤害提高{3}%，奥术冲击的法力消耗提高{4}%。该效果最多叠加{5}次，持续{6}秒，或直到施放任何其他伤害法术。", zhTW = "以能量衝擊目標，對其造成{1}至{2}點秘法傷害。每次施放秘法衝擊時會使你所有其他法術的傷害提高{3}%，並且秘法衝擊的法力消耗提高{4}%。此效果最多可堆疊{5}次，持續{6}秒，或直到施放任何其他傷害性法術為止。" },
	["blasts the target with holy energy, causing # to # holy damage to an enemy, or # to # healing to an ally"] = { ko = "대상을 성스러운 기운으로 강타하여 {1}~{2}의 신성 피해를 입히거나, 아군의 생명력을 {3}~{4}만큼 회복시킵니다.", zhCN = "以神圣能量冲击目标，对一个敌人造成{1}至{2}点神圣伤害，或者为一个友方目标恢复{3}至{4}点生命值。", zhTW = "以神聖的能量衝擊目標，造成{1}至{2}點神聖傷害，或為盟友恢復{3}至{4}點生命力。" },
	["bless the grenade with the light"] = { ko = "빛으로 수류탄을 축복합니다.", zhCN = "用圣光祝福这枚手雷。", zhTW = "以聖光祝福手榴彈。" },
	["blinds the target, causing it to wander disoriented for up to # sec"] = { ko = "대상의 눈을 멀게 해 최대 {1}초 동안 방황하게 만듭니다.", zhCN = "使目标暂时失明并到处乱走，持续最多{1}秒。", zhTW = "使目標暫時失明，在周圍盲目地遊蕩，持續最多{1}秒。" },
	["blinds the target, causing it to wander disoriented for up to # sec. any damage caused will remove the effect"] = { ko = "대상의 눈을 멀게 해 최대 {1}초 동안 방황하게 만듭니다. 피해를 입게 되면 효과가 사라집니다.", zhCN = "使目标暂时失明并到处乱走，持续最多{1}秒。任何对其造成的伤害都会解除此效果。", zhTW = "使目標暫時失明，在周圍盲目地遊蕩，持續最多{1}秒。任何對其造成的傷害都會解除此效果。" },
	["brings a dead player back to life with # health and # mana"] = { zhCN = "复活一个死去的玩家，复活后该玩家拥有{1}点生命值和{2}点法力值。", zhTW = "復活一個死去的玩家，復活後該玩家擁有{1}點生命力和{2}點法力。" },
	["brings a dead player back to life with # health and # mana. cannot be cast when in combat"] = { ko = "죽은 플레이어를 되살립니다. 대상은 {1}의 생명력과 {2}의 마나를 지닌 채로 되살아납니다. 전투 중에는 사용할 수 없습니다.", zhCN = "复活一个死去的玩家，复活后该玩家拥有{1}点生命值和{2}点法力值。无法在战斗中使用。", zhTW = "復活一個死去的玩家，復活後該玩家擁有{1}點生命力和{2}點法力。無法在戰鬥中使用。" },
	["builds a basic campfire that allows cooking and the placement of up to # additional camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 기본 모닥불을 만듭니다.", zhCN = "生起一堆基础营火，可以用来烹饪，并允许额外放置最多{1}个露营设施。", zhTW = "升起基礎營火，可用來烹飪，以及設置最多額外{1}個營地功能。" },
	["builds a basic campfire that allows cooking and the placement of up to # additional camp features. players sitting or crafting nearby for # min will gain benefits from other camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 기본 모닥불을 만듭니다. 주위에서 {2}분 동안 앉아 있거나 제작을 하는 플레이어는 다른 야영 설비의 이로운 효과를 받습니다.", zhCN = "生起一堆基础营火，可以用来烹饪，并允许额外放置最多{1}个露营设施。在附近坐下或制造物品持续{2}分钟的玩家将获得其他露营设施的增益。", zhTW = "升起基礎營火，可用來烹飪，以及設置最多額外{1}個營地功能。玩家在附近坐下或製作物品，持續{2}分鐘，就能獲得其他營地功能的增益效果。" },
	["builds a journeyman campfire that allows cooking and the placement of up to # additional camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 수습 모닥불을 만듭니다.", zhCN = "生起一堆中级营火，允许进行烹饪并可放置最多{1}个额外的营地设施。", zhTW = "升起中級營火，可用來烹飪，以及設置最多額外{1}個營地功能。" },
	["builds a journeyman campfire that allows cooking and the placement of up to # additional camp features. players sitting or crafting nearby for # min will gain benefits from other camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 수습 모닥불을 만듭니다. 주위에서 {2}분 동안 앉아 있거나 제작을 하는 플레이어는 다른 야영 설비의 이로운 효과를 받습니다.", zhCN = "生起一堆中级营火，允许进行烹饪并可放置最多{1}个额外的营地设施。在附近坐下或进行制造持续{2}分钟的玩家将获得其他营地设施的增益效果。", zhTW = "升起中級營火，可用來烹飪，以及設置最多額外{1}個營地功能。玩家在附近坐下或製作物品，持續{2}分鐘，就能獲得其他營地功能的增益效果。" },
	["builds a tent that allows you and others sitting nearby to increase rested experience to #% of a level"] = { ko = "천막을 펼쳐 자신과 주위에 앉은 다른 플레이어의 휴식 경험치를 레벨의 {1}%까지 증가시킵니다.", zhCN = "搭建一座帐篷，使你和附近坐下的其他人获得充分休息经验值，最多可累积至当前等级所需经验值的{1}%。", zhTW = "搭建一頂帳篷，使你和坐在附近的其他人將休息經驗值提高至一個等級的{1}%。" },
	["builds a tent that allows you and others sitting nearby to increase rested experience to #% of a level. no effect if rested experience already exceeds that value"] = { ko = "천막을 펼쳐 자신과 주위에 앉은 다른 플레이어의 휴식 경험치를 레벨의 {1}%까지 증가시킵니다. 휴식 경험치가 이미 해당 값을 초과할 경우 아무런 효과를 발휘하지 못합니다.", zhCN = "搭建一座帐篷，使你和附近坐下的其他人获得充分休息经验值，最多可累积至当前等级所需经验值的{1}%。若已有的充分休息经验超过该数值，则不生效。", zhTW = "搭建一頂帳篷，使你和坐在附近的其他人將休息經驗值提高至一個等級的{1}%。若休息經驗值已超過該數值則無效果。" },
	["builds an expert campfire that allows cooking and the placement of up to # additional camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 숙련 모닥불을 만듭니다.", zhCN = "生起一堆高级营火，允许进行烹饪并可放置最多{1}个额外的营地设施。", zhTW = "升起高級營火，可用來烹飪，以及設置最多額外{1}個營地功能。" },
	["builds an expert campfire that allows cooking and the placement of up to # additional camp features. players sitting or crafting nearby for # min will gain benefits from other camp features"] = { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 숙련 모닥불을 만듭니다. 주위에서 {2}분 동안 앉아 있거나 제작을 하는 플레이어는 다른 야영 설비의 이로운 효과를 받습니다.", zhCN = "生起一堆高级营火，允许进行烹饪并可放置最多{1}个额外的营地设施。在附近坐下或进行制造持续{2}分钟的玩家将获得其他营地设施的增益效果。", zhTW = "升起高級營火，可用來烹飪，以及設置最多額外{1}個營地功能。玩家在附近坐下或製作物品，持續{2}分鐘，就能獲得其他營地功能的增益效果。" },
	["burn the enemy's soul, causing # to # fire damage"] = { ko = "적의 영혼을 불태워 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "燃烧敌人的灵魂，对其造成{1}至{2}点火焰伤害。", zhTW = "燃燒敵人的靈魂，對其造成{1}至{2}點火焰傷害。" },
	["burns # mana from those in the blast radius and deals #% of the mana drained in damage to the target"] = { ko = "폭파 반경 내에 있는 적의 마나를 {1}만큼 연소하고 연소한 양의 {2}%에 해당하는 피해를 입힙니다.", zhCN = "燃烧爆炸范围内目标的{1}点法力值，并对目标造成相当于所吸取法力值{2}%的伤害。", zhTW = "燃燒爆炸範圍內目標的{1}點法力，並對目標造成相當於所吸取法力{2}%的傷害。" },
	["burns # mana from those in the blast radius and deals #% of the mana drained in damage to the target. also silences targets in the blast for # sec"] = { ko = "폭파 반경 내에 있는 적의 마나를 {1}만큼 연소하고 연소한 양의 {2}%에 해당하는 피해를 입힙니다. 또한 {3}초 동안 대상을 침묵시킵니다.", zhCN = "燃烧爆炸范围内目标的{1}点法力值，并对目标造成相当于所吸取法力值{2}%的伤害。同时使爆炸范围内的目标沉默{3}秒。", zhTW = "燃燒爆炸範圍內目標的{1}點法力，並對目標造成相當於所吸取法力{2}%的傷害。同時使爆炸範圍內的目標沉默{3}秒。" },
	["burns the enemy for # fire damage and then an additional # fire damage over # sec"] = { ko = "적을 불태워 {1}의 화염 피해를 입히고 추가로 {2}초에 걸쳐 총 {3}의 화염 피해를 입힙니다.", zhCN = "灼烧敌人，对其造成{1}点火焰伤害，并在{2}秒内造成额外的{3}点火焰伤害。", zhTW = "灼燒敵人，對其造成{1}點火焰傷害，並在{2}秒內額外造成{3}點火焰傷害。" },
	["burns the enemy for # to # arcane damage and then an additional # arcane damage over # sec"] = { ko = "적을 불태워 {1}~{2}의 비전 피해를 입히고 {4}초에 걸쳐 총 {3}의 비전 피해를 입힙니다.", zhCN = "灼烧敌人，对其造成{1}至{2}点伤害，并在{4}秒内造成额外的{3}点奥术伤害。", zhTW = "灼燒敵人，對其造成{1}至{2}點傷害，並在{4}秒內造成額外的{3}點秘法傷害。" },
	["calls down a fiery rain to burn enemies in the area of effect for # fire damage over # sec"] = { ko = "{2}초에 걸쳐 불의 비를 내려 대상 지역의 모든 적에게 총 {1}의 화염 피해를 입힙니다.", zhCN = "召唤火焰之雨，在{2}秒内对目标区域中的敌人造成{1}点火焰伤害。", zhTW = "召喚火焰之雨，在{2}秒內對目標區域中的敵人造成{1}點火焰傷害。" },
	["calls down a pillar of fire, burning all enemies within the area for # to # fire damage and an additional # fire damage over # sec"] = { ko = "불기둥을 불러일으켜 그 지역 안의 모든 적에게 {1}~{2}의 화염 피해를 입히고 추가로 {4}초에 걸쳐 총 {3}의 화염 피해를 입힙니다.", zhCN = "召唤一根火柱，对区域内所有敌人造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。", zhTW = "召喚一根火柱，對攻擊範圍內的所有敵人造成{1}至{2}點火焰傷害，並在{4}秒內造成額外{3}點傷害。" },
	["calls down a pillar of fire, burning all enemies within the area for # to # fire damage and an additional # fire damage over # sec. only one flamestrike can be active per mage at a time"] = { ko = "불기둥을 불러일으켜 그 지역 안의 모든 적에게 {1}~{2}의 화염 피해를 입히고 추가로 {4}초에 걸쳐 총 {3}의 화염 피해를 입힙니다. 마법사마다 한 번에 하나의 불기둥만 활성화할 수 있습니다.", zhCN = "召唤一根火柱，对区域内所有敌人造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。每名法师同时只能有一个烈焰风暴生效。", zhTW = "召喚一根火柱，對攻擊範圍內的所有敵人造成{1}至{2}點火焰傷害，並在{4}秒內造成額外{3}點傷害。每個法師同一時間只能啟動一個烈焰風暴。" },
	["can call different totems than call of the elements"] = { ko = "원소의 부름과 다른 토템을 부를 수 있습니다.", zhCN = "可以放置与元素的召唤不同的图腾。", zhTW = "可以呼喚有別於「元素呼喚」的圖騰。" },
	["can call different totems than call of the elements or call of the ancestors"] = { ko = "원소의 부름 또는 선조의 부름과 다른 토템을 부를 수 있습니다.", zhCN = "可以放置与元素的召唤或先祖的召唤不同的图腾。", zhTW = "可以呼喚有別於「元素呼喚」或「先祖呼喚」的圖騰。" },
	["can only affect targets up to # levels higher than you"] = { ko = "시전자보다 레벨이 최대 {1}만큼 높은 대상에게만 영향을 줍니다.", zhCN = "只能影响等级最多高于你{1}级的目标。", zhTW = "只能影響等級最多高於你{1}級的目標。" },
	["can only affect targets up to # levels higher than you. some targets cannot be displaced. targets can only be affected by this effect once every # min"] = { ko = "시전자보다 레벨이 최대 {1}만큼 높은 대상에게만 영향을 줍니다. 몇몇 대상은 무효화하지 못합니다. {2}분에 한 번씩만 이 효과의 대상으로 지정할 수 있습니다.", zhCN = "只能影响等级最多高于你{1}级的目标。有些目标无法被置换。目标每{2}分钟只能受到一次该效果的影响。", zhTW = "只能影響等級最多高於你{1}級的目標。有些目標無法被置換。目標每{2}分鐘只能受到一次該效果的影響。" },
	["can only be performed after you dodge"] = { ko = "적의 공격을 회피한 후에만 사용할 수 있습니다.", zhCN = "只能在你成功躲闪后使用。", zhTW = "只能在你成功躲閃之後使用。" },
	["can only be used outdoors"] = { ko = "야외에서만 사용할 수 있습니다.", zhCN = "只能在户外使用。", zhTW = "只能在戶外使用。" },
	["cannibalize # of your own health over # sec to gain # (+ spirit) mana"] = { ko = "{2}초에 걸쳐 자신의 생명력 {1}을 소모하여 {3}(+ 정신력)의 마나를 얻습니다.", zhCN = "在{2}秒内消耗自身{1}点生命值，获得{3}（+精神）点法力值。", zhTW = "在{2}秒內消耗自身{1}點生命力，獲得{3}（+精神）點法力。" },
	["cannot be cast on players"] = { ko = "플레이어에게는 사용할 수 없습니다.", zhCN = "无法对玩家施放。", zhTW = "無法對玩家施放。" },
	["cannot be cast on self"] = { ko = "자신에게는 시전할 수 없습니다.", zhCN = "不能对自己施放。", zhTW = "無法對自己施放。" },
	["cannot be cast when in combat"] = { ko = "전투 중에는 사용할 수 없습니다.", zhCN = "无法在战斗中使用。", zhTW = "無法在戰鬥中使用。" },
	["cannot be cast while forbearance is active"] = { ko = "참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "自律效果激活时无法施放。", zhTW = "自律效果生效期間，無法施放。" },
	["cannot be used in combat"] = { ko = "전투 중에는 사용할 수 없습니다.", zhCN = "无法在战斗中使用。", zhTW = "無法在戰鬥中使用。" },
	["cannot be used while in combat"] = { ko = "전투 중에는 사용할 수 없습니다.", zhCN = "无法在战斗中使用。", zhTW = "無法在戰鬥中使用。" },
	["cannot trigger more often than # time per sec"] = { ko = "{1}초마다 한 번씩만 발동합니다.", zhCN = "每秒最多触发一次。", zhTW = "每秒只能觸發{1}次。" },
	["castable while shapeshifted"] = { ko = "변신한 상태일 때도 시전할 수 있습니다.", zhCN = "可在变形状态下施放。", zhTW = "可在變形時施放。" },
	["casts a bolt of lightning at the target for # to # nature damage"] = { ko = "대상에게 번개 화살을 날려 {1}~{2}의 자연 피해를 입힙니다.", zhCN = "向目标射出闪电箭，对其造成{1}至{2}点伤害。", zhTW = "向目標射出閃電箭，對其造成{1}至{2}點自然傷害。" },
	["causes # damage, stops your attack, and incapacitates the target for # sec"] = { ko = "{1}의 피해를 입히고, 자신은 공격을 중단하며, 대상을 {2}초 동안 행동 불가 상태로 만듭니다.", zhCN = "对目标造成{1}点伤害，停止你的攻击，并使目标瘫痪{2}秒。", zhTW = "對目標造成{1}點傷害，停止你的攻擊，並使目標癱瘓{2}秒。" },
	["causes # damage, stops your attack, and incapacitates the target for # sec. the target must be facing you. any damage taken will break the effect. awards # combo point"] = { ko = "{1}의 피해를 입히고, 자신은 공격을 중단하며, 대상을 {2}초 동안 행동 불가 상태로 만듭니다. 적의 정면에서 사용해야 합니다. 피해를 받으면 효과가 해제됩니다. 연계 점수 {3}점을 생성합니다.", zhCN = "对目标造成{1}点伤害，停止你的攻击，并使目标瘫痪{2}秒。目标必须面对你。受到任何伤害都会打破该效果。奖励{3}个连击点数。", zhTW = "對目標造成{1}點傷害，停止你的攻擊，並使目標癱瘓{2}秒。目標必須面對你。受到任何傷害都會中斷此效果。獎勵{3}個連擊點數。" },
	["causes # holy damage to any creature that strikes a party member within # yards"] = { ko = "주위 {2} 미터 반경에 있는 파티원을 공격하는 모든 생물에게 {1}의 신성 피해를 입힙니다.", zhCN = "对任何攻击{2}码内队伍成员的生物造成{1}点神圣伤害。", zhTW = "對在半徑{2}碼範圍內的隊伍成員施展近戰攻擊的生物造成{1}點神聖傷害。" },
	["causes # holy damage to any creature that strikes a party member within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "주위 {2} 미터 반경에 있는 파티원을 공격하는 모든 생물에게 {1}의 신성 피해를 입힙니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "对任何攻击{2}码内队伍成员的生物造成{1}点神圣伤害。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "對在半徑{2}碼範圍內的隊伍成員施展近戰攻擊的生物造成{1}點神聖傷害。每個聖騎士在同一時間內只能開啟一種光環。" },
	["causes # to # arcane damage to the target"] = { ko = "적에게 {1}~{2}의 비전 피해를 입힙니다.", zhCN = "对目标造成{1}至{2}点奥术伤害。", zhTW = "對目標造成{1}至{2}點秘法傷害。" },
	["causes # to # holy damage to an undead or demon target"] = { ko = "목표 언데드 또는 악마에게 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "对单一亡灵或恶魔目标造成{1}至{2}点神圣伤害。", zhTW = "對一名不死族或惡魔目標造成{1}至{2}點神聖傷害。" },
	["causes # to # nature damage to the target"] = { ko = "적에게 {1}~{2}의 자연 피해를 입힙니다.", zhCN = "对目标造成{1}至{2}点自然伤害。", zhTW = "對目標造成{1}至{2}點自然傷害。" },
	["causes a high amount of threat"] = { ko = "위협 수준이 크게 증가합니다.", zhCN = "造成高额威胁值。" },
	["causes a very high amount of threat"] = { zhCN = "产生极高的威胁。", zhTW = "產生極高威脅值。" },
	["causes all nearby enemies to be dazed, reducing movement speed by #% for # sec"] = { ko = "주위의 모든 적을 멍하게 만들어 {2}초 동안 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "使附近的所有敌人眩晕，移动速度降低{1}%，持续{2}秒。", zhTW = "使附近所有敵人暈眩，移動速度降低{1}%，持續{2}秒。" },
	["causes an explosion of arcane magic around the caster, causing # to # arcane damage to all targets within # yards"] = { ko = "시전자의 주위를 비전 마법의 힘으로 폭발시켜 {3}미터 반경에 있는 모든 적에게 {1}~{2}의 비전 피해를 입힙니다.", zhCN = "制造一次以施法者为中心的魔法爆炸，对半径{3}码范围内的所有目标造成{1}至{2}点奥术伤害。", zhTW = "製造一次以施法者為中心的魔法爆炸，對半徑{3}碼範圍內的所有目標造成{1}至{2}點秘法傷害。" },
	["causes an explosion of holy light around the caster, causing # to # holy damage to all enemy targets within # yards and healing all party members within # yards for # to #"] = { ko = "시전자의 주위를 감싸고 있는 신성한 빛을 폭발시켜 {3}미터 반경의 모든 적에게 {1}~{2}의 신성 피해를 입히고 {4}미터 반경 내의 파티원의 생명력을 {5}~{6}만큼 치유합니다.", zhCN = "在施法者周围引发神圣光芒爆炸，对{3}码内所有敌方目标造成{1}至{2}点神圣伤害，并为{4}码内所有小队成员恢复{5}至{6}点生命值。", zhTW = "在施法者身邊產生聖光爆炸，對半徑{3}碼範圍內所有敵人造成{1}至{2}點神聖傷害，並恢復半徑{4}碼範圍內所有小隊成員{5}至{6}點生命力。" },
	["causes an explosion of holy light around the caster, causing # to # holy damage to all enemy targets within # yards and healing all party members within # yards for # to # these effects cause no threat"] = { ko = "시전자의 주위를 감싸고 있는 신성한 빛을 폭발시켜 {3}미터 반경의 모든 적에게 {1}~{2}의 신성 피해를 입히고 {4}미터 반경 내의 파티원의 생명력을 {5}~55만큼 치유합니다. 이 주문은 위협 수준을 생성하지 않습니다.", zhCN = "在施法者周围引发神圣光芒爆炸，对{3}码内所有敌方目标造成{1}至{2}点神圣伤害，并为{4}码内所有小队成员恢复{5}至55点生命值。这些效果不产生威胁值。", zhTW = "在施法者身邊產生聖光爆炸，對半徑{3}碼範圍內所有敵人造成{1}至{2}點神聖傷害，並恢復半徑{4}碼範圍內所有小隊成員{5}至55點生命力。這些效果不會造成威脅值。" },
	["causes holy shock to reduce the cast time of your next holy light cast within # sec by -#.# sec"] = { ko = "신성 충격 사용 시 {1}초 안에 시전하는 다음 성스러운 빛의 시전 시간이 -{2}.{3}초만큼 감소합니다.", zhCN = "使神圣震击令你在{1}秒内施放的下一个圣光术的施法时间缩短-{2}.{3}秒。", zhTW = "使神聖震擊令你在{1}秒內施放的下一個聖光術的施法時間縮短-{2}.{3}秒。" },
	["causes the enemy target to run in horror for # sec and causes # shadow damage"] = { ko = "적을 {1}초 동안 공포에 질려 달아나게 만들고 {2}의 암흑 피해를 입힙니다." },
	["causes the enemy target to run in horror for # sec and causes # shadow damage. the caster gains #% of the damage caused in health"] = { ko = "적을 {1}초 동안 공포에 질려 달아나게 만들고 {2}의 암흑 피해를 입힙니다. 시전자는 입힌 피해의 {3}%만큼 생명력을 회복합니다.", zhCN = "使目标因恐惧而逃跑，持续{1}秒，并对其造成{2}点暗影伤害，所有伤害都被用来治疗施法者。", zhTW = "使目標因恐懼而逃跑，持續{1}秒，並對其造成{2}點暗影傷害，所有傷害都被用來治療施法者。" },
	["causes wrath to have a #% chance to restore # mana"] = { ko = "천벌 사용 시 {1}%의 확률로 {2}의 마나를 회복합니다.", zhCN = "使愤怒有{1}%的几率恢复{2}点法力值。", zhTW = "使憤怒有{1}%的機率恢復{2}點法力。" },
	["causes your attacks to ignore #% of your target's armor and increases the damage dealt by your rupture ability by #%"] = { ko = "공격 시 대상의 방어도를 {1}%만큼 무시하며, 파열로 입히는 피해가 {2}%만큼 증가합니다.", zhCN = "使你的攻击忽略目标{1}%的护甲，并使你的割裂技能造成的伤害提高{2}%。", zhTW = "使你的攻擊無視目標{1}%的護甲值，並使割裂技能造成的傷害提高{2}%。" },
	["causes your fire ward to have a #% chance to reflect fire spells while active"] = { ko = "화염계 수호가 활성화되어 있는 동안 {1}%의 확률로 화염 주문을 반사합니다.", zhCN = "你的防护火焰结界有{1}%的几率将火焰法术反射给施法者。", zhTW = "當防護火焰結界啟動時會有{1}%的機率將火焰系法術反射給施法者。" },
	["causes your primal bite ability to strike up to # targets, removes its cooldown, and increases the critical strike chance of your combo point-generating abilities by #%"] = { ko = "원시의 이빨이 최대 {1}명의 대상을 공격하고 재사용 대기시간이 사라지며, 연계 점수를 생성하는 기술의 치명타 확률이 {2}%만큼 증가합니다." },
	["causes your primal bite ability to strike up to # targets, removes its cooldown, and increases the critical strike chance of your combo point-generating abilities by #%. clears and grants immunity to fear effects for the duration. lasts # sec"] = { ko = "원시의 이빨이 최대 {1}명의 대상을 공격하고 재사용 대기시간이 사라지며, 연계 점수를 생성하는 기술의 치명타 확률이 {2}%만큼 증가합니다. 공포 효과를 해제하고 지속시간 동안 공포에 면역이 됩니다. {3}초 동안 지속됩니다.", zhCN = "Causes your Primal Bite ability to strike up to {1} targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by {2}%. Clears and grants immunity to Fear effects for the duration. Lasts {3}秒.", zhTW = "Causes your Primal Bite ability to strike up to {1} targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by {2}%. Clears and grants immunity to Fear effects for the duration. Lasts {3}秒." },
	["chance on hit to blast the target for # fire damage"] = { ko = "적중 시 일정 확률로 대상에게 {1}의 화염 피해를 입힙니다.", zhCN = "击中时有几率轰击目标，造成{1}点火焰伤害。", zhTW = "命中時有機率衝擊目標，造成{1}點火焰傷害。" },
	["changes the caster's viewpoint to the targeted location"] = { ko = "시전자의 시야를 지정한 곳으로 이동하여 먼 곳까지 볼 수 있게 합니다." },
	["changes the caster's viewpoint to the targeted location. lasts # min. only useable outdoors"] = { ko = "시전자의 시야를 지정한 곳으로 이동하여 먼 곳까지 볼 수 있게 합니다. {1}분 동안 지속됩니다. 야외에서만 사용할 수 있습니다.", zhCN = "将施法者的视点切换到目标区域，持续{1}分钟。只能在户外使用。", zhTW = "將施法者的視點切換到目標區域，持續{1}分鐘。只能在戶外使用。" },
	["channels a bolt of lightning and hurls it towards all enemies in front of the caster causing # nature damage"] = { ko = "번개를 집중시켜 시전자 전방의 모든 적에게 날려보내 {1}의 자연 피해를 입힙니다.", zhCN = "引导一道闪电并将其掷向施法者前方的所有敌人，造成{1}点自然伤害。", zhTW = "導引一發閃電箭攻擊施法者面前所有敵人，造成{1}點自然傷害。" },
	["channels a bolt of lightning and hurls it towards all enemies in front of the caster causing # nature damage. the caster is then surrounded by a barrier of electricity for # min"] = { ko = "번개를 집중시켜 시전자 전방의 모든 적에게 날려보내 {1}의 자연 피해를 입힙니다. 공격 후 시전자는 {2}분 동안 전기의 벽에 둘러싸입니다.", zhCN = "引导一道闪电并将其掷向施法者前方的所有敌人，造成{1}点自然伤害。随后，施法者会被一道电流屏障包围，持续{2}分钟。", zhTW = "導引一發閃電箭攻擊施法者面前所有敵人，造成{1}點自然傷害。施法者受閃電屏障保護，持續{2}分鐘。" },
	["charge an enemy, causing # damage and stunning it for # sec"] = { ko = "적에게 돌격하여 {1}의 피해를 입히고 {2}초 동안 기절시킵니다.", zhCN = "向敌人冲锋，造成{1}点伤害，并使其昏迷{2}秒。", zhTW = "向敵人衝鋒，造成{1}點傷害，並使其昏迷{2}秒。" },
	["charge an enemy, generate # rage, and stun it for # sec"] = { ko = "적에게 돌진하여 {1}의 분노를 얻고 {2}초 동안 기절시킵니다.", zhCN = "向一名敌人冲锋，产生{1}点怒气，并使其昏迷{2}秒。", zhTW = "向敵人衝鋒，產生{1}點怒氣，並使其昏迷{2}秒。" },
	["charge an enemy, generate # rage, and stun it for # sec. cannot be used in combat"] = { ko = "적에게 돌진하여 {1}의 분노를 얻고 {2}초 동안 기절시킵니다. 전투 중에는 사용할 수 없습니다.", zhCN = "向一名敌人冲锋，产生{1}点怒气，并使其昏迷{2}秒。无法在战斗中使用。", zhTW = "向敵人衝鋒，產生{1}點怒氣，並使其昏迷{2}秒。無法在戰鬥中使用。" },
	["charge an enemy, immobilizing them and interrupting any spell they are casting for # sec"] = { ko = "적에게 돌진해 {1}초 동안 이동 불가 상태로 만들고 시전 중인 주문을 방해합니다.", zhCN = "向敌人冲锋，使其无法移动，并打断其正在施放的任何法术，持续{1}秒。", zhTW = "向目標衝鋒，使其無法移動，並使其在{1}秒內不能施放任何法術。" },
	["charge an enemy, immobilizing them and interrupting any spell they are casting for # sec. leap behind an enemy"] = { ko = "적에게 돌진해 {1}초 동안 이동 불가 상태로 만들고 시전 중인 주문을 방해합니다. 적의 배후로 도약합니다.", zhCN = "向敌人冲锋，使其无法移动，并打断其正在施放的任何法术，持续{1}秒。 跳跃到敌人的背后。", zhTW = "向敵人衝鋒，使其無法移動，並打斷其正在施放的任何法術，持續{1}秒。 跳躍到敵人的背後。" },
	["chastise the target, causing # to # holy damage and immobilizing them for up to # sec"] = { ko = "대상을 응징하여 {1}~{2}의 신성 피해를 입히고 최대 {3}초 동안 이동 불가 상태로 만듭니다." },
	["chastise the target, causing # to # holy damage and immobilizing them for up to # sec. only works against humanoids. this spell causes very low threat"] = { ko = "대상을 응징하여 {1}~{2}의 신성 피해를 입히고 최대 {3}초 동안 이동 불가 상태로 만듭니다. 인간형에게만 효과를 발휘합니다. 이 주문은 매우 낮은 위협 수준을 생성합니다." },
	["claw the enemy for #% normal damage plus #"] = { ko = "적을 발톱으로 할퀴어 일반 공격력의 {1}%에 해당하는 피해와 {2}의 추가 피해를 입힙니다.", zhCN = "爪击敌人，造成{1}%普通伤害，外加{2}点伤害。", zhTW = "用爪攻擊敵人，造成{1}%普通傷害再加上{2}點額外傷害。" },
	["claw the enemy for #% normal damage plus # awards # combo point"] = { ko = "적을 발톱으로 할퀴어 일반 공격력의 {1}%에 해당하는 피해와 29의 추가 피해를 입힙니다. 연계 점수 {3}점을 생성합니다.", zhCN = "爪击敌人，造成{1}%普通伤害，外加29点伤害。奖励{3}个连击点。", zhTW = "用爪攻擊敵人，造成{1}%普通傷害再加上29點額外傷害。獎勵{3}個連擊點數。" },
	["claw the enemy, causing # to # damage"] = { ko = "적을 할퀴어 {1} 에서 {2}의 피해를 입힙니다.", zhCN = "用爪攻击敌人，对其造成{1}至{2}点伤害。", zhTW = "用爪攻擊敵人，對其造成{1}至{2}點傷害。" },
	["cleanses a friendly target, removing # poison effect, # disease effect, and # magic effect"] = { ko = "대상을 정화하여 아군에게서 독 {1}개와 질병 {2}개, 마법 효과 {3}개를 제거합니다.", zhCN = "净化一个友方目标，驱散{1}个中毒效果，{2}个疾病效果和{3}个魔法效果。", zhTW = "淨化一個友方目標，驅散{1}個中毒效果，{2}個疾病效果和{3}個魔法效果。" },
	["clearcasting is not consumed by wrath or by spells or abilities that cost no resources"] = { ko = "번뜩임은 천벌 또는 자원을 소모하지 않는 주문이나 능력으로는 소모되지 않습니다.", zhCN = "愤怒以及不消耗资源的法术或技能不会消耗节能施法。", zhTW = "節能施法效果不會被憤怒或不消耗資源的法術/技能消耗。" },
	["clears and grants immunity to fear effects for the duration"] = { ko = "공포 효과를 해제하고 지속시간 동안 공포에 면역이 됩니다." },
	["cloaks the user in a stealth field for up to # min"] = { ko = "최대 {1}분 동안 사용자를 은신 영역으로 감쌉니다.", zhCN = "使使用者笼罩在潜行力场中，最多持续{1}分钟。", zhTW = "將使用者罩在潛行力場中，最多持續{1}分鐘。" },
	["cloaks the user in a stealth field for up to # min. cannot be used in combat. the field lasts for up to # sec after moving"] = { ko = "최대 {1}분 동안 사용자를 은신 영역으로 감쌉니다. 전투 중에는 사용할 수 없습니다. 이동 후에도 은신 영역은 최대 {2} 동안 지속됩니다.", zhCN = "使使用者笼罩在潜行力场中，最多持续{1}分钟。无法在战斗中使用。移动后，该力场最多持续{2}秒。", zhTW = "將使用者罩在潛行力場中，最多持續{1}分鐘。無法在戰鬥中使用。此力場在移動後可持續最多{2}秒。" },
	["coats a weapon with poison that lasts for # min"] = { ko = "무기에 {1}분 동안 유지되는 독을 바릅니다.", zhCN = "给一件武器浸毒，效果持续{1}分钟。", zhTW = "給一件武器浸毒，效果持續{1}分鐘。" },
	["command a hawk to dive-bomb your targeted enemy, dealing # (+#% of ranged attack power) physical damage and continuing its assault for # sec"] = { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}(+ 원거리 전투력의 {2}%)의 물리 피해를 입히고 {3}초 동안 지속적으로 공격을 퍼붓게 합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}（+远程攻击强度的{2}%）点物理伤害并继续攻击{3}秒。", zhTW = "命令一隻雄鷹俯衝轟炸目標敵人，造成{1}（+遠程攻擊強度的{2}%）點物理傷害並繼續攻擊{3}秒。" },
	["command a hawk to dive-bomb your targeted enemy, dealing # (+#% of ranged attack power) physical damage and continuing its assault for # sec. only # hawks can be active at once. summon hawk shares its cooldown with arcane shot"] = { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}(+ 원거리 전투력의 {2}%)의 물리 피해를 입히고 {3}초 동안 지속적으로 공격을 퍼붓게 합니다. 매는 한 번에 {4}마리만 활성화될 수 있습니다. 매 소환은 신비한 사격과 재사용 대기시간을 공유합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}（+远程攻击强度的{2}%）点物理伤害并继续攻击{3}秒。同时最多只能激活{4}只雄鹰。召唤雄鹰与奥术射击共享冷却时间。", zhTW = "命令一隻雄鷹俯衝轟炸目標敵人，造成{1}（+遠程攻擊強度的{2}%）點物理傷害並繼續攻擊{3}秒。同時最多隻能啟用{4}只雄鷹。召喚獵鷹與秘法射擊共享冷卻時間。" },
	["command a hawk to dive-bomb your targeted enemy, dealing # physical damage and continuing its assault for # sec"] = { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}의 물리 피해를 입히고 {2}초 동안 지속적으로 공격을 퍼붓게 합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}点物理伤害并继续攻击{2}秒。", zhTW = "命令一隻獵鷹俯衝攻擊鎖定的敵人，造成{1}點物理傷害並持續進行攻擊，持續{2}秒。" },
	["command a hawk to dive-bomb your targeted enemy, dealing # physical damage and continuing its assault for # sec. only # hawks can be active at once. summon hawk shares its cooldown with arcane shot"] = { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}의 물리 피해를 입히고 {2}초 동안 지속적으로 공격을 퍼붓게 합니다. 매는 한 번에 {3}마리만 활성화될 수 있습니다. 매 소환은 신비한 사격과 재사용 대기시간을 공유합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}点物理伤害并继续攻击{2}秒。同时最多只能激活{3}只雄鹰。召唤雄鹰与奥术射击共享冷却时间。", zhTW = "命令一隻獵鷹俯衝攻擊鎖定的敵人，造成{1}點物理傷害並持續進行攻擊，持續{2}秒。同時最多只能有{3}隻獵鷹。召喚獵鷹與秘法射擊共用冷卻時間。" },
	["command your pet to stun the target for # sec on its next successful attack, which also gains #% increased critical strike chance"] = { ko = "야수에게 명령해 다음 공격 적중 시 대상을 {1}초 동안 기절시키고, 해당 공격의 치명타 및 극대화율을 {2}%만큼 증가시킵니다.", zhCN = "命令你的宠物在下次成功攻击时使目标昏迷{1}秒，且该次攻击的爆击几率提高{2}%。", zhTW = "命令你的寵物在下次成功攻擊敵人時使目標昏迷{1}秒，同時致命一擊機率提高{2}%。" },
	["command your pet to stun the target for # sec on its next successful attack, which also gains #% increased critical strike chance. generates high threat"] = { ko = "야수에게 명령해 다음 공격 적중 시 대상을 {1}초 동안 기절시키고, 해당 공격의 치명타 및 극대화율을 {2}%만큼 증가시킵니다. 위협 수준이 크게 증가합니다.", zhCN = "命令你的宠物在下次成功攻击时使目标昏迷{1}秒，且该次攻击的爆击几率提高{2}%。产生大量威胁值。", zhTW = "命令你的寵物在下次成功攻擊敵人時使目標昏迷{1}秒，同時致命一擊機率提高{2}%。產生大量威脅值。" },
	["concuss the target, slowing movement speed by #% for # sec"] = { ko = "대상에게 뇌진탕을 일으켜 {2}초 동안 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "震荡目标，使其移动速度降低{1}%，持续{2}秒。", zhTW = "震盪目標，使其移動速度降低{1}%，持續{2}秒。" },
	["confuses up to # enemies within # yds for # sec"] = { ko = "{2}미터 내의 적 최대 {1}명을 {3}초 동안 혼란에 빠뜨립니다.", zhCN = "迷惑{2}码内的最多{1}个敌人，持续{3}秒。", zhTW = "使{2}碼內最多{1}個敵人陷入混亂，持續{3}秒。" },
	["confuses up to # enemies within # yds for # sec. any damage taken will break the effect"] = { ko = "{2}미터 내의 적 최대 {1}명을 {3}초 동안 혼란에 빠뜨립니다. 피해를 받으면 효과가 해제됩니다.", zhCN = "迷惑{2}码内的最多{1}个敌人，持续{3}秒。任何伤害都会打断此效果。", zhTW = "使{2}碼內最多{1}個敵人陷入混亂，持續{3}秒。受到任何傷害都會中斷這個效果。" },
	["conjured items disappear if logged out for more than # min"] = { ko = "창조된 물건은 접속 종료 후 {1}분이 지나면 사라집니다.", zhCN = "这些物品会在持有者登出游戏超过{1}分钟之后消失。", zhTW = "這些物品會在持有者登出遊戲超過{1}分鐘之後消失。" },
	["conjures # bottles of crystal water, providing the mage and his allies with something to drink"] = { ko = "결정수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法晶水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法晶水以供法師和他的盟友飲用。" },
	["conjures # bottles of fresh water, providing the mage and his allies with something to drink"] = { ko = "지하수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法淡水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法淡水以供法師和他的盟友飲用。" },
	["conjures # bottles of mineral water, providing the mage and his allies with something to drink"] = { ko = "광천수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法矿泉水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法礦泉水以供法師和他的盟友飲用。" },
	["conjures # bottles of mountain spring water, providing the mage and his allies with something to drink"] = { ko = "암반수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法山泉水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法山泉水以供法師和他的盟友飲用。" },
	["conjures # bottles of purified water, providing the mage and his allies with something to drink"] = { ko = "정제수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法纯净水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法純淨水以供法師和他的盟友飲用。" },
	["conjures # bottles of sparkling water, providing the mage and his allies with something to drink"] = { ko = "탄산수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶汽水以供法师和他的盟友饮用。", zhTW = "{1}瓶魔法蘇打水以供法師和他的盟友飲用。" },
	["conjures # bottles of spring water, providing the mage and his allies with something to drink"] = { ko = "용천수 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法泉水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法泉水以供法師和他的盟友飲用。" },
	["conjures # bottles of water, providing the mage and his allies with something to drink"] = { ko = "샘물 {1}개를 창조합니다. 음료로 사용할 수 있습니다.", zhCN = "用魔法合成{1}瓶魔法水以供法师和他的盟友饮用。", zhTW = "用魔法合成{1}瓶魔法水以供法師和他的盟友飲用。" },
	["conjures # cinnamon rolls, providing the mage and his allies with something to eat"] = { ko = "계피 롤빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块肉桂面包饼以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法肉桂麵包以供法師和他的盟友食用。" },
	["conjures # loaves of bread, providing the mage and his allies with something to eat"] = { ko = "식빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法面包以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法麵包以供法師和他的盟友食用。" },
	["conjures # loaves of pumpernickel, providing the mage and his allies with something to eat"] = { ko = "호밀빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法粗面包以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法粗麵包以供法師和他的盟友食用。" },
	["conjures # loaves of rye, providing the mage and his allies with something to eat"] = { ko = "흑빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法黑面包以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法黑麵包以供法師和他的盟友食用。" },
	["conjures # loaves of sourdough, providing the mage and his allies with something to eat"] = { ko = "효모빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法酵母以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法酵母以供法師和他的盟友食用。" },
	["conjures # muffins, providing the mage and his allies with something to eat"] = { ko = "머핀 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法松饼以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法鬆餅以供法師和他的盟友食用。" },
	["conjures # sweet rolls, providing the mage and his allies with something to eat"] = { ko = "롤빵 {1}개를 창조합니다. 음식으로 사용할 수 있습니다.", zhCN = "用魔法合成{1}块魔法甜面包以供法师和他的盟友食用。", zhTW = "用魔法合成{1}塊魔法甜麵包以供法師和他的盟友食用。" },
	["conjures a mana agate that can be used to instantly restore # to # mana"] = { ko = "마나 마노를 창조합니다. 사용하면 즉시 {1}~{2}의 마나를 회복시켜줍니다.", zhCN = "制造一颗魔法玛瑙，使用后可以立刻恢复{1}至{2}点法力值。", zhTW = "製造一顆法力瑪瑙，使用後可以立刻恢復{1}至{2}點法力。" },
	["conjures a mana citrine that can be used to instantly restore # to # mana"] = { ko = "마나 황수정을 창조합니다. 사용하면 즉시 {1}~{2}의 마나를 회복시켜줍니다.", zhCN = "制造一颗魔法黄水晶，使用后可以立刻恢复{1}至{2}点法力值。", zhTW = "製造一顆魔法黃水晶，使用後可以立刻恢復{1}至{2}點法力。" },
	["conjures a mana jade that can be used to instantly restore # to # mana"] = { ko = "마나 비취를 창조합니다. 사용하면 즉시 {1}~{2}의 마나를 회복시켜줍니다.", zhCN = "制造一颗魔法翡翠，使用后可以立刻恢复{1}至{2}点法力值。", zhTW = "製造一顆魔法翡翠，使用後可以立刻恢復{1}至{2}點法力。" },
	["conjures a mana ruby that can be used to instantly restore #,# to #,# mana"] = { ko = "마나 루비를 창조합니다. 사용하면 즉시 {1},{2}~{3},{4}의 마나를 회복시켜줍니다.", zhCN = "制造一颗魔法红宝石，使用后可以立刻恢复{1},{2}至{3},{4}点法力值。", zhTW = "製造一顆魔法紅寶石，使用後可以立刻恢復{1},{2}至{3},{4}點法力。" },
	["consecrates the land beneath the paladin, doing # holy damage over # sec to enemies who enter the area"] = { ko = "성기사가 서 있는 땅을 신성화하여 그 지역에 접근하는 적에게 {2}초에 걸쳐 총 {1}의 신성 피해를 입힙니다.", zhCN = "使圣骑士脚下的土地神圣化，在{2}秒内对进入该区域的敌人造成总计{1}点神圣伤害。", zhTW = "使聖騎士腳下的土地神聖化，在{2}秒內對進入該區域的敵人造成總計{1}點神聖傷害。" },
	["consecrates the land beneath the paladin, doing # holy damage over # sec to enemies who enter the area. the first # enemies who enter the area will take an additional # damage over # sec"] = { ko = "성기사가 서 있는 땅을 신성화하여 그 지역에 접근하는 적에게 {2}초에 걸쳐 총 {1}의 신성 피해를 입힙니다. 그 지역에 처음 들어오는 적 {3}명은 {5}초에 걸쳐 {4}의 피해를 추가로 입습니다.", zhCN = "使圣骑士脚下的土地神圣化，在{2}秒内对进入该区域的敌人造成总计{1}点神圣伤害。最先进入该区域的{3}个敌人会在{5}秒内额外受到{4}点伤害。", zhTW = "使聖騎士腳下的土地神聖化，在{2}秒內對進入該區域的敵人造成總計{1}點神聖傷害。最先進入該區域的{3}個敵人會在{5}秒內額外受到{4}點傷害。" },
	["constructs a mana well that allows you and others sitting nearby to regenerate # (below #) · # (below #) · # (below #) · # (below #) · #(above) mana every # sec, muutally exclusive with blessing of wisdom"] = { ko = "마나 우물을 설치해 자신과 주위에 앉은 다른 플레이어가 {10}초마다 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}({8}레벨 미만) · {9}(그 위)의 마나를 회복하게 합니다. 지혜의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "建造一口法力之井，使你和附近坐下的其他人每{10}秒回复{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（{8}级以下） · {9}（更高）点法力值，与智慧祝福不叠加。", zhTW = "建造一口法力井，使你和附近坐下的其他人每{10}秒回覆{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（{8}級以下） · {9}（更高）點法力，與智慧祝福不疊加。" },
	["constructs a mana well that allows you and others sitting nearby to regenerate # mana every # sec, muutally exclusive with blessing of wisdom"] = { ko = "마나 우물을 설치해 자신과 주위에 앉은 다른 플레이어가 {2}초마다 {1}의 마나를 회복하게 합니다. 지혜의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "建造一口法力之井，使你和附近坐下的其他人每{2}秒回复{1}点法力值，与智慧祝福不叠加。", zhTW = "建造一口法力井，使你和附近坐下的其他人每{2}秒回覆{1}點法力，與智慧祝福不疊加。" },
	["constructs a sharpening wheel that grants you and others sitting nearby # (below #) · # (below #) · # (below #) · #(above) increased strength, mutually exclusive with strength of earth totem"] = { ko = "연마 바퀴를 제작해 자신과 주위에 앉은 다른 플레이어의 힘을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}(그 위)만큼 증가시킵니다. 대지력 토템과 겸용해서 사용할 수 없습니다.", zhCN = "搭建一个磨刀石，使你和附近坐下的其他人力量提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（更高），与大地之力图腾互斥。", zhTW = "搭建一個砂輪，使你和附近坐下的其他人力量提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（更高），與大地之力圖騰互斥。" },
	["constructs a sharpening wheel that grants you and others sitting nearby # increased strength, mutually exclusive with strength of earth totem"] = { ko = "연마 바퀴를 제작해 자신과 주위에 앉은 다른 플레이어의 힘을 {1}만큼 증가시킵니다. 대지력 토템과 겸용해서 사용할 수 없습니다.", zhCN = "搭建一个磨刀石，使你和附近坐下的其他人力量提高{1}，与大地之力图腾互斥。", zhTW = "搭建一個砂輪，使你和附近坐下的其他人力量提高{1}，與大地之力圖騰互斥。" },
	["consumes the enemy in holy flames that cause # to # holy damage and an additional # holy damage over # sec"] = { ko = "신성한 불길이 적을 집어삼켜 {1}~{2}의 신성 피해를 입히고 추가로 {4}초에 걸쳐 {3}의 신성 피해를 입힙니다.", zhCN = "神圣的烈焰吞噬敌人，对其造成{1}至{2}点神圣伤害，并在{4}秒内造成{3}点额外的神圣伤害。", zhTW = "烈焰吞噬敵人，對其造成{1}至{2}點神聖傷害，並在{4}秒內造成{3}點額外神聖傷害。" },
	["continuously fires a volley of ammo at the target area, causing # arcane damage to enemy targets within # yards every # sec for # sec"] = { ko = "{2}미터 반경의 지역에 연발 사격을 가하여 대상 지역 내의 적에게 {4}초에 걸쳐 {3}초마다 {1}의 비전 피해를 입힙니다.", zhCN = "持续向目标区域倾泻弹药，在{4}秒内每{3}秒对{2}码范围内的敌方目标造成{1}点奥术伤害。", zhTW = "持續向目標區域射擊，每{3}秒對半徑{2}碼範圍內的敵人造成{1}點秘法傷害，持續{4}秒。" },
	["controls a humanoid mind up to level #, but increases the time between attacks by #%"] = { zhCN = "控制一个最高等级为{1}的人型目标，但是使其攻击间隔延长{2}%。", zhTW = "控制一個最高等級為{1}的人型目標，但是其攻擊的間隔時間提高{2}%。" },
	["controls a humanoid mind up to level #, but increases the time between attacks by #%. lasts up to # min"] = { ko = "최대 {1} 레벨의 인간형 생명체를 지배할 수 있습니다. 공격 속도는 {2}%만큼 감소합니다. 최대 {3}분 동안 지속됩니다.", zhCN = "控制一个最高等级为{1}的人型目标，但是使其攻击间隔延长{2}%。最多持续{3}分钟。", zhTW = "控制一個最高等級為{1}的人型目標，但是其攻擊的間隔時間提高{2}%。最多持續{3}分鐘。" },
	["controls a humanoid mind up to level #, but increases the time between its attacks by #%"] = { zhCN = "控制一个最高等级为{1}的人型目标，但是使其攻击间隔延长{2}%。", zhTW = "控制一個最高等級為{1}的人型目標，但是其攻擊間隔時間提高{2}%。" },
	["controls a humanoid mind up to level #, but increases the time between its attacks by #%. lasts up to # min"] = { ko = "최대 {1} 레벨의 인간형 생명체를 지배할 수 있습니다. 공격 속도는 {2}%만큼 감소합니다. 최대 {3}분 동안 지속됩니다.", zhCN = "控制一个最高等级为{1}的人型目标，但是使其攻击间隔延长{2}%。最多持续{3}分钟。", zhTW = "控制一個最高等級為{1}的人型目標，但是其攻擊間隔時間提高{2}%。最多持續{3}分鐘。" },
	["converts # health into # mana for you"] = { ko = "{1}의 생명력을 {2}의 마나로 변환합니다.", zhCN = "将{1}点生命值转化为{2}点法力值。", zhTW = "將{1}點生命力轉化為{2}點法力。" },
	["converts # health into # mana for you. spirit increases the amount converted"] = { ko = "{1}의 생명력을 {2}의 마나로 변환합니다. 정신력에 따라 변환하는 양이 증가합니다.", zhCN = "将{1}点生命值转化为{2}点法力值。精神越高，转化的数值越多。", zhTW = "將{1}點生命力轉化為{2}點法力。精神越高，轉化的數值越多。" },
	["converts up to # rage per second into health for # sec"] = { ko = "{1}초 동안 초당 최대 {2}의 분노를 생명력으로 전환합니다.", zhCN = "每秒将最多{1}点怒气转化为生命值，持续{2}秒。", zhTW = "每秒將最多{1}點怒氣轉化為生命力，持續{2}秒。" },
	["converts up to # rage per second into health for # sec. each point of rage is converted into #% health"] = { ko = "{1}초 동안 초당 최대 {2}의 분노를 생명력으로 전환합니다. 분노 {3}은 1%의 생명력으로 전환됩니다.", zhCN = "每秒将最多{1}点怒气转化为生命值，持续{2}秒。每点怒气可转化为{3}%的生命值。", zhTW = "每秒將最多{1}點怒氣轉化為生命力，持續{2}秒。每點怒氣可以轉化為{3}%生命力。" },
	["corrupts the target, causing # damage over # sec"] = { ko = "대상을 부패시켜 {2}초에 걸쳐 총 {1}의 피해를 입힙니다.", zhCN = "腐蚀目标，在{2}秒内造成累计{1}点伤害。", zhTW = "腐蝕目標，在{2}秒內造成累計{1}點傷害。" },
	["corrupts the target, causing # shadow damage over # sec"] = { ko = "대상을 부패시켜 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다.", zhCN = "腐蚀目标，在{2}秒内造成累计{1}点伤害。", zhTW = "腐蝕目標，在{2}秒內造成累計{1}點暗影傷害。" },
	["counterattack cannot be blocked, dodged, or parried"] = { ko = "역습은 방패로 막거나, 회피하거나, 무기로 막을 수 없습니다.", zhCN = "反击无法被格挡、躲闪或招架。" },
	["counterattack the enemy for melee weapon damage plus #"] = { ko = "적의 공격에 반격하여 무기 공격력에 {1}의 추가 피해를 입힙니다.", zhCN = "反击敌人，对其造成近战武器伤害外加{1}点伤害。", zhTW = "反擊敵人，對其造成近戰武器傷害再加上{1}點傷害。" },
	["counterattack the enemy for melee weapon damage plus # can only be performed after you dodge"] = { ko = "적의 공격에 반격하여 무기 공격력에 15의 추가 피해를 입힙니다. 적의 공격을 회피한 후에만 사용할 수 있습니다.", zhCN = "反击敌人，对其造成近战武器伤害外加15点伤害。只能在你成功躲闪后使用。", zhTW = "反擊敵人，對其造成近戰武器傷害再加上15點傷害。只能在你成功躲閃之後使用。" },
	["counters the enemy's spellcast, preventing any spell from that school of magic from being cast for # sec"] = { ko = "적의 주문 시전을 차단하여 {1}초 동안 같은 계열의 주문을 시전하지 못하도록 만듭니다.", zhCN = "反制敌人的法术，使其在{1}秒内无法施放任何与该法术属于同一类别的法术。", zhTW = "反制敵人的法術，使其在{1}秒內無法施放任何與該法術屬於同一類別的法術。" },
	["counters the enemy's spellcast, preventing any spell from that school of magic from being cast for # sec. generates a high amount of threat"] = { ko = "적의 주문 시전을 차단하여 {1}초 동안 같은 계열의 주문을 시전하지 못하도록 만듭니다. 대상에 대한 위협 수준이 크게 증가합니다.", zhCN = "反制敌人的法术，使其在{1}秒内无法施放任何与该法术属于同一类别的法术。产生很高的威胁值。", zhTW = "反制敵人的法術，使其在{1}秒內無法施放任何與該法術屬於同一類別的法術。產生很高的威脅值。" },
	["cower, causing no damage but lowering your threat a large amount, making the enemy less likely to attack you"] = { ko = "몸을 웅크려 위협 수준을 크게 감소시켜 적에게 공격받을 확률을 감소시킵니다.", zhCN = "在战斗中畏缩，不造成任何伤害，但是可以大量减少你的威胁值，降低敌人攻击你的可能性。", zhTW = "在戰鬥中畏縮，不造成任何傷害，但是可以大量減少你的威脅值，降低敵人攻擊你的可能性。" },
	["cower, causing no damage but lowering your threat a medium amount, making the enemy less likely to attack you"] = { ko = "몸을 웅크려 위협 수준을 보통 정도 감소시켜 적에게 공격받을 확률을 감소시킵니다.", zhCN = "在战斗中畏缩，不造成任何伤害，但是可以中量减少你的威胁值，降低敌人攻击你的可能性。", zhTW = "在戰鬥中畏縮，不造成任何傷害，但是可以中量減少你的威脅值，降低敵人攻擊你的可能性。" },
	["cower, causing no damage but lowering your threat a small amount, making the enemy less likely to attack you"] = { ko = "몸을 웅크려 위협 수준을 조금 감소시켜 적에게 공격받을 확률을 감소시킵니다.", zhCN = "在战斗中畏缩，不造成任何伤害，但是可以少量减少你的威胁值，降低敌人攻击你的可能性。", zhTW = "在戰鬥中畏縮，不造成任何傷害，但是可以少量減少你的威脅值，降低敵人攻擊你的可能性。" },
	["craft a fermenter"] = { ko = "발효조를 만듭니다.", zhCN = "制作一个发酵桶。", zhTW = "製作發酵罐。" },
	["craft a field guide"] = { ko = "현장 안내서를 만듭니다.", zhCN = "制作一本野外指南。", zhTW = "製作野外指南。" },
	["craft a fishing rack"] = { ko = "낚시 선반을 만듭니다.", zhCN = "制作一个钓鱼架。", zhTW = "製作釣魚架。" },
	["craft a greenhouse"] = { ko = "온실을 만듭니다.", zhCN = "制作一座温室。", zhTW = "製作溫室。" },
	["craft a journeyman campfire"] = { ko = "수습 모닥불을 만듭니다.", zhCN = "制作一个中级营火。", zhTW = "製作中級營火。" },
	["craft a repair bot"] = { ko = "수리 로봇을 만듭니다.", zhCN = "制作一个修理机器人。", zhTW = "製作修理機器人。" },
	["craft a rock garden"] = { ko = "바위 정원을 만듭니다.", zhCN = "制作一个岩石园。", zhTW = "製作奇石園。" },
	["craft a spinning wheel"] = { ko = "물레를 만듭니다.", zhCN = "制作一架纺车。", zhTW = "製作紡車。" },
	["craft a tanning rack"] = { ko = "무두질 선반을 만듭니다.", zhCN = "制作一个制革架。", zhTW = "製作製皮架。" },
	["craft a toxin study"] = { ko = "독소 연구대를 만듭니다.", zhCN = "制作一项毒素研究。", zhTW = "製作毒素研究區。" },
	["craft an anvil"] = { ko = "모루를 만듭니다.", zhCN = "制作一个铁砧。", zhTW = "製作鐵砧。" },
	["craft an arcane salvager"] = { ko = "비전 수거기를 만듭니다.", zhCN = "制作一个奥术回收器。", zhTW = "製作秘法回收機。" },
	["craft cookie's feast"] = { ko = "쿠키의 잔칫상을 만듭니다.", zhCN = "制作曲奇的大餐。", zhTW = "製作餅乾之宴。" },
	["create the reagent for the blind ability"] = { ko = "실명 기술에 사용되는 재료를 만듭니다.", zhCN = "制造供致盲技能使用的材料。", zhTW = "製造供致盲技能使用的材料。" },
	["creates a firestone which can be used to enchant your weapon with fire, increasing your spell critical strike chance by #% and the damage done by your fire spells by up to #"] = { ko = "화염석을 만듭니다. 화염석으로 무기에 불의 힘을 주입해 주문 극대화율을 {1}%만큼, 화염 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一颗火焰石，可用于为你的武器附魔火焰之力，使你的法术爆击几率提高{1}%，火焰法术造成的伤害最多提高{2}点。", zhTW = "製造一塊火焰石，可用來為武器施加火焰附魔，使你的法術致命一擊機率提高{1}%，並使火焰法術造成的傷害最多提高{2}點。" },
	["creates a greater firestone which can be used to enchant your weapon with fire, increasing your spell critical strike chance by #% and the damage done by your fire spells by up to #"] = { ko = "상급 화염석을 만듭니다. 화염석으로 무기에 불의 힘을 주입해 주문 극대화율을 {1}%만큼, 화염 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一颗强效火焰石，可用于为你的武器附魔火焰之力，使你的法术爆击几率提高{1}%，火焰法术造成的伤害最多提高{2}点。", zhTW = "製造一塊強效火焰石，可用來為武器施加火焰附魔，使你的法術致命一擊機率提高{1}%，並使火焰法術造成的傷害最多提高{2}點。" },
	["creates a greater healthstone that can be used to instantly restore # health"] = { ko = "상급 생명석을 창조합니다. 창조된 생명석을 사용하면 즉시 {1}의 생명력을 회복시켜줍니다.", zhCN = "制造一块强效治疗石，使用后可以立刻恢复{1}点生命值。", zhTW = "製造一塊強效治療石，使用後可以立刻恢復{1}點生命力。" },
	["creates a greater soulstone"] = { ko = "상급 영혼석을 창조합니다." },
	["creates a greater soulstone. the soulstone can be used to store one target's soul. if the target dies while their soul is stored, they will be able to resurrect with #,# health and # mana"] = { ko = "상급 영혼석을 창조합니다. 영혼석엔 하나의 영혼을 담아 놓을 수 있습니다. 만약 영혼이 담겨진 채로 죽게 되면 대상은 {1},{2}의 생명력과 {3}의 마나를 지닌 채로 부활할 수 있습니다.", zhCN = "制造一块强效灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复{1},{2}点生命值和{3}点法力值。", zhTW = "製造一塊強效靈魂石，可以用來保存一個目標的靈魂。如果目標在靈魂被保存期間死去，則可以依靠靈魂石復活，並恢復{1},{2}點生命力和{3}點法力。" },
	["creates a greater spellstone which can be used to enchant your weapon with shadow, increasing your spell haste by #% and the damage done by your shadow spells by up to #"] = { ko = "상급 주문석을 만듭니다. 상급 주문석으로 무기에 암흑의 힘을 주입해 주문 가속을 {1}%만큼, 암흑 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一块强效法术石，可用于为你的武器附魔暗影之力，使你的法术急速提高{1}%，暗影法术造成的伤害最多提高{2}点。", zhTW = "製造一塊強效法術石，可用來為武器施加暗影附魔，使你的法術加速提高{1}%，並使暗影法術造成的傷害最多提高{2}點。" },
	["creates a healthstone that can be used to instantly restore # health"] = { ko = "중급 생명석을 창조합니다. 창조된 생명석을 사용하면 즉시 {1}의 생명력을 회복시켜줍니다.", zhCN = "制造一块治疗石，使用后可以立刻恢复{1}点生命值。", zhTW = "製造一塊治療石，使用後可以立刻恢復{1}點生命力。" },
	["creates a holy lightwell near the priest"] = { ko = "사제 주위에 성스러운 빛샘을 생성합니다.", zhCN = "在牧师身边制造一个光明之泉。", zhTW = "在牧師附近製造一個神聖光束泉。" },
	["creates a holy lightwell near the priest. members of your raid or party can click the lightwell to restore # health over # sec. being attacked cancels the effect. lightwell lasts for # min or # charges"] = { ko = "사제 주위에 성스러운 빛샘을 생성합니다. 파티원이나 공격대원이 빛샘을 클릭하면 {2}초에 걸쳐 {1}의 생명력을 회복할 수 있습니다. 공격을 받게 되면 효과가 취소됩니다. 빛샘은 {4}번 사용하거나 {3}분이 지나면 사라집니다.", zhCN = "在牧师身边制造一个光明之泉。你所属的小队或团队中的友方单位可以点击光明之泉，在{2}秒内恢复{1}点生命值。被攻击会中断这个效果。光明之泉在{3}分钟或者在被使用{4}次之后消失。", zhTW = "在牧師附近製造一個神聖光束泉。友方目標可以擊點光束泉在{2}秒內回復{1}點生命力。受到攻擊會取消此效果。光束泉持續{3}分鐘或可使用{4}次。" },
	["creates a lesser firestone which can be used to enchant your weapon with fire, increasing your spell critical strike chance by #% and the damage done by your fire spells by up to #"] = { ko = "하급 화염석을 만듭니다. 하급 화염석으로 무기에 불의 힘을 주입해 주문 극대화율을 {1}%만큼, 화염 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一颗次级火焰石，可用于为你的武器附魔火焰之力，使你的法术爆击几率提高{1}%，火焰法术造成的伤害最多提高{2}点。", zhTW = "製造一塊次級火焰石，可用來為武器施加火焰附魔，使你的法術致命一擊機率提高{1}%，並使火焰法術造成的傷害最多提高{2}點。" },
	["creates a lesser healthstone that can be used to instantly restore # health"] = { ko = "하급 생명석을 창조합니다. 창조된 생명석을 사용하면 즉시 {1}의 생명력을 회복시켜줍니다.", zhCN = "制造一块次级治疗石，使用后可以立刻恢复{1}点生命值。", zhTW = "製造一塊次級治療石，使用後可以立刻恢復{1}點生命力。" },
	["creates a lesser soulstone"] = { ko = "하급 영혼석을 창조합니다." },
	["creates a lesser soulstone. the soulstone can be used to store one target's soul. if the target dies while their soul is stored, they will be able to resurrect with # health and # mana"] = { ko = "하급 영혼석을 창조합니다. 영혼석엔 하나의 영혼을 담아 놓을 수 있습니다. 만약 영혼이 담겨진 채로 죽게 되면 대상은 {1}의 생명력과 {2}의 마나를 지닌 채로 부활할 수 있습니다.", zhCN = "制造一块次级灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复{1}点生命值和{2}点法力值。", zhTW = "製造一塊次級靈魂石，可以用來保存一個目標的靈魂。如果目標在靈魂被保存期間死去，則可以依靠靈魂石復活，並恢復{1}點生命力和{2}點法力。" },
	["creates a major firestone which can be used to enchant your weapon with fire, increasing your spell critical strike chance by #% and the damage done by your fire spells by up to #"] = { ko = "최상급 화염석을 만듭니다. 화염석으로 무기에 불의 힘을 주입해 주문 극대화율을 {1}%만큼, 화염 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一颗特效火焰石，可用于为你的武器附魔火焰之力，使你的法术爆击几率提高{1}%，火焰法术造成的伤害最多提高{2}点。", zhTW = "製造一塊極效火焰石，可用來為武器施加火焰附魔，使你的法術致命一擊機率提高{1}%，並使火焰法術造成的傷害最多提高{2}點。" },
	["creates a major healthstone that can be used to instantly restore #,# health"] = { ko = "최상급 생명석을 창조합니다. 창조된 생명석을 사용하면 즉시 {1},{2}의 생명력을 회복시켜줍니다.", zhCN = "制造一块特效治疗石，使用后可以立刻恢复{1},{2}点生命值。", zhTW = "製造一塊極效治療石，使用後可以立刻恢復{1},{2}點生命力。" },
	["creates a major soulstone"] = { ko = "최상급 영혼석을 창조합니다." },
	["creates a major soulstone. the soulstone can be used to store one target's soul. if the target dies while their soul is stored, they will be able to resurrect with #,# health and # mana"] = { ko = "최상급 영혼석을 창조합니다. 영혼석엔 하나의 영혼을 담아 놓을 수 있습니다. 만약 영혼이 담겨진 채로 죽게 되면 대상은 {1},{2}의 생명력과 {3}의 마나를 지닌 채로 부활할 수 있습니다.", zhCN = "制造一块特效灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复{1},{2}点生命值和{3}点法力值。", zhTW = "製造一塊極效靈魂石，可以用來保存一個目標的靈魂。如果目標在靈魂被保存期間死去，則可以依靠靈魂石復活，並恢復{1},{2}點生命力和{3}點法力。" },
	["creates a major spellstone which can be used to enchant your weapon with shadow, increasing your spell haste by #% and the damage done by your shadow spells by up to #"] = { ko = "최상급 주문석을 만듭니다. 최상급 주문석으로 무기에 암흑의 힘을 주입해 주문 가속을 {1}%만큼, 암흑 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一块特效法术石，可用于为你的武器附魔暗影之力，使你的法术急速提高{1}%，暗影法术造成的伤害最多提高{2}点。", zhTW = "製造一塊極效法術石，可用來為武器施加暗影附魔，使你的法術加速提高{1}%，並使暗影法術造成的傷害最多提高{2}點。" },
	["creates a minor healthstone that can be used to instantly restore # health"] = { ko = "최하급 생명석을 창조합니다. 창조된 생명석을 사용하면 즉시 {1}의 생명력을 회복시켜줍니다.", zhCN = "制造一块初级治疗石，使用后可以立刻恢复{1}点生命值。", zhTW = "製造一塊初級治療石，使用後可以立刻恢復{1}點生命力。" },
	["creates a minor soulstone"] = { ko = "최하급 영혼석을 창조합니다." },
	["creates a minor soulstone. the soulstone can be used to store one target's soul. if the target dies while their soul is stored, they will be able to resurrect with # health and # mana"] = { ko = "최하급 영혼석을 창조합니다. 영혼석엔 하나의 영혼을 담아 놓을 수 있습니다. 만약 영혼이 담겨진 채로 죽게 되면 대상은 {1}의 생명력과 {2}의 마나를 지닌 채로 부활할 수 있습니다.", zhCN = "制造一块初级灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复{1}点生命值和{2}点法力值。", zhTW = "製造一塊初級靈魂石，可以用來保存一個目標的靈魂。如果目標在靈魂被保存期間死去，則可以依靠靈魂石復活，並恢復{1}點生命力和{2}點法力。" },
	["creates a portal, teleporting group members that use it to darnassus"] = { ko = "파티원들이 이용할 수 있도록 다르나서스로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到达纳苏斯。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到達納蘇斯。" },
	["creates a portal, teleporting group members that use it to ironforge"] = { ko = "파티원들이 이용할 수 있도록 아이언포지로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到铁炉堡。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到鐵爐堡。" },
	["creates a portal, teleporting group members that use it to orgrimmar"] = { ko = "파티원들이 이용할 수 있도록 오그리마로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到奥格瑞玛。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到奧格瑪。" },
	["creates a portal, teleporting group members that use it to stormwind"] = { ko = "파티원들이 이용할 수 있도록 스톰윈드로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到暴风城。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到暴風城。" },
	["creates a portal, teleporting group members that use it to thunder bluff"] = { ko = "파티원들이 이용할 수 있도록 썬더 블러프로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到雷霆崖。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到雷霆崖。" },
	["creates a portal, teleporting group members that use it to undercity"] = { ko = "파티원들이 이용할 수 있도록 언더시티로 통하는 차원의 문을 엽니다.", zhCN = "制造一个传送门，将穿越它的队友传送到幽暗城。", zhTW = "製造一個傳送門，將穿越它的隊友傳送到幽暗城。" },
	["creates a soulstone"] = { ko = "영혼석을 창조합니다." },
	["creates a soulstone. the soulstone can be used to store one target's soul. if the target dies while their soul is stored, they will be able to resurrect with #,# health and # mana"] = { ko = "영혼석을 창조합니다. 영혼석엔 하나의 영혼을 담아 놓을 수 있습니다. 만약 영혼이 담겨진 채로 죽게 되면 대상은 {1},{2}의 생명력과 {3}의 마나를 지닌 채로 부활할 수 있습니다.", zhCN = "制造一块灵魂石，可以用来保存一个目标的灵魂。如果目标在灵魂被保存期间死去，则他可以依靠灵魂石复活，并恢复{1},{2}点生命值和{3}点法力值。", zhTW = "製造一塊靈魂石，可以用來保存一個目標的靈魂。如果目標在靈魂被保存期間死去，則可以依靠靈魂石復活，並恢復{1},{2}點生命力和{3}點法力。" },
	["creates a spellstone which can be used to enchant your weapon with shadow, increasing your spell haste by #% and the damage done by your shadow spells by up to #"] = { ko = "주문석을 만듭니다. 주문석으로 무기에 암흑의 힘을 주입해 주문 가속을 {1}%만큼, 암흑 계열 주문의 공격력을 최대 {2}만큼 증가시킬 수 있습니다.", zhCN = "制造一块法术石，可用于为你的武器附魔暗影之力，使你的法术急速提高{1}%，暗影法术造成的伤害最多提高{2}点。", zhTW = "製造一塊法術石，可用來為武器施加暗影附魔，使你的法術加速提高{1}%，並使暗影法術造成的傷害最多提高{2}點。" },
	["creates a violent storm in the target area causing # nature damage to enemies every # sec, and increasing the time between attacks by #%"] = { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 공격 간격을 {3}%만큼 늘입니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使其攻击间隔延长{3}%。" },
	["creates a violent storm in the target area causing # nature damage to enemies every # sec, and increasing the time between attacks by #%. lasts # sec. druid must channel to maintain the spell"] = { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 공격 간격을 {3}%만큼 늘입니다. {4}초 동안 지속됩니다. 주문을 유지하려면 계속 정신을 집중해야 합니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使其攻击间隔延长{3}%。持续{4}秒。德鲁伊必须持续引导才能维持该法术。", zhTW = "在施法者指定的區域製造一場強烈的風暴，對範圍內的所有敵人每{2}秒造成{1}點自然傷害，並使其攻擊間隔時間延長{3}%，持續{4}秒。德魯伊必須引導以維持法術效果。" },
	["creates a violent storm in the target area causing # nature damage to enemies every # sec, and increasing the time between attacks of enemies by #%"] = { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 적의 공격 간격을 {3}%만큼 늘입니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使敌人的攻击间隔延长{3}%。" },
	["creates a violent storm in the target area causing # nature damage to enemies every # sec, and increasing the time between attacks of enemies by #%. lasts # sec. druid must channel to maintain the spell"] = { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 적의 공격 간격을 {3}%만큼 늘입니다. {4}초 동안 지속됩니다. 주문을 유지하려면 계속 정신을 집중해야 합니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使敌人的攻击间隔延长{3}%。持续{4}秒。德鲁伊必须持续引导才能维持该法术。", zhTW = "在施法者指定的區域製造一場強烈的風暴，對範圍內的所有敵人每{2}秒造成{1}點自然傷害，並使其攻擊間隔時間延長{3}%，持續{4}秒。德魯伊必須引導以維持法術效果。" },
	["critical strike chance by #%"] = { zhCN = "爆击几率提高{1}%。", zhTW = "致命一擊機率提高{1}%。" },
	["critical strike chance increased by #% and all damage taken is increased by #%"] = { ko = "치명타 및 극대화율이 {1}%만큼 증가하지만, 받는 모든 피해가 {2}%만큼 증가합니다.", zhCN = "爆击几率提高{1}%，受到的所有伤害提高{2}%。" },
	["cures # disease on the target"] = { ko = "대상에 걸린 {1}개의 질병을 치료합니다.", zhCN = "治愈目标身上的{1}个疾病效果。", zhTW = "治癒目標身上的{1}個疾病效果。" },
	["cures # poison effect on the target"] = { ko = "대상에 걸린 {1}개의 독을 치료합니다.", zhCN = "治愈目标身上的{1}个中毒效果。", zhTW = "治癒目標身上的{1}個中毒效果。" },
	["curse the target with idiocy, reducing intellect and spirit by # every # sec until each is reduced by a total of #"] = { zhCN = "使目标受到痴呆的诅咒，每{2}秒降低{1}点智力和精神，直到这两种属性都被降低了{3}点为止。", zhTW = "使目標受到癡呆的詛咒，每{2}秒降低{1}點智力和精神，直到這兩種屬性都被降低了{3}點。" },
	["curse the target with idiocy, reducing intellect and spirit by # every # sec until each is reduced by a total of # only one curse per warlock can be active on any one target"] = { ko = "무지의 저주를 걸어 매 {2}초마다 지능과 정신력을 {1}씩 감소시킵니다. 최대 90까지 감소됩니다. 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "使目标受到痴呆的诅咒，每{2}秒降低{1}点智力和精神，直到这两种属性都被降低了90点为止。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", zhTW = "使目標受到癡呆的詛咒，每{2}秒降低{1}點智力和精神，直到這兩種屬性都被降低了90點。每個術士只能對一個目標施加一種詛咒，且同類詛咒不能疊加。" },
	["cursed enemies will not flee and will ignore fear and horror effects"] = { ko = "이 마법이 지속되는 한 대상은 도망치지 않으며 겁이나 공포 효과를 무시합니다.", zhCN = "被诅咒的敌人不会逃跑，并会无视恐惧和惊骇效果。", zhTW = "被詛咒的敵人不會逃跑，也不會受到恐懼的影響。" },
	["curses the target for # min, reducing magic resistances by # and increases magic damage taken by #%"] = { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다.", zhCN = "诅咒目标，持续{1}分钟，使其魔法抗性降低{2}点，受到的魔法伤害提高{3}%。", zhTW = "對目標施放詛咒，使其魔法抗性降低{2}點，並且受到的魔法傷害提高{3}%，效果持續{1}分鐘。" },
	["curses the target for # min, reducing magic resistances by # and increases magic damage taken by #%. only one curse per warlock can be active on any one target"] = { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "诅咒目标，持续{1}分钟，使其魔法抗性降低{2}点，受到的魔法伤害提高{3}%。每个术士对同一目标同时只能施加一种诅咒。", zhTW = "對目標施放詛咒，使其魔法抗性降低{2}點，並且受到的魔法傷害提高{3}%，效果持續{1}分鐘。每個術士只能對一個目標施加一種詛咒。" },
	["curses the target for # min, reducing magic resistances by # and increasing magic damage taken by #%"] = { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다." },
	["curses the target for # min, reducing magic resistances by # and increasing magic damage taken by #%. only one curse per warlock can be active on any one target"] = { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다." },
	["curses the target for # min, reducing shadow and arcane resistances by # and increasing shadow and arcane damage taken by #%"] = { ko = "저주를 걸어 {1}분 동안 대상의 암흑과 비전 마법에 대한 저항력을 {2}만큼 감소시키고 받는 암흑과 비전 피해를 {3}%만큼 증가시킵니다.", zhCN = "对目标施放诅咒，使其暗影和奥术抗性降低{2}点，受到暗影和奥术系攻击时所承受的伤害提高{3}%，效果持续{1}分钟。", zhTW = "對目標施放詛咒，使其暗影和秘法抗性降低{2}點，受到暗影和秘法系攻擊時所承受的傷害提高{3}%，效果持續{1}分鐘。" },
	["curses the target for # min, reducing shadow and arcane resistances by # and increasing shadow and arcane damage taken by #%. only one curse per warlock can be active on any one target"] = { ko = "저주를 걸어 {1}분 동안 대상의 암흑과 비전 마법에 대한 저항력을 {2}만큼 감소시키고 받는 암흑과 비전 피해를 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "对目标施放诅咒，使其暗影和奥术抗性降低{2}点，受到暗影和奥术系攻击时所承受的伤害提高{3}%，效果持续{1}分钟。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", zhTW = "對目標施放詛咒，使其暗影和秘法抗性降低{2}點，受到暗影和秘法系攻擊時所承受的傷害提高{3}%，效果持續{1}分鐘。每個術士只能對一個目標施加一種詛咒，且同類詛咒不能疊加。" },
	["curses the target with recklessness, reducing the target's armor by # for # min"] = { ko = "무모함의 저주를 걸어 {2}분 동안 대상의 방어도를 {1}만큼 감소시킵니다.", zhCN = "以鲁莽诅咒目标，使其护甲降低{1}点，持续{2}分钟。", zhTW = "對目標施加魯莽的詛咒，使其護甲值降低{1}點，持續{2}分鐘。" },
	["curses the target with recklessness, reducing the target's armor by # for # min. cursed enemies will not flee and will ignore fear and horror effects. only one curse per warlock can be active on any one target"] = { ko = "무모함의 저주를 걸어 {2}분 동안 대상의 방어도를 {1}만큼 감소시킵니다. 이 마법이 지속되는 한 대상은 도망치지 않으며 겁이나 공포 효과를 무시합니다. 흑마법사마다 한 대상에 하나의 저주만 걸 수 있습니다.", zhCN = "以鲁莽诅咒目标，使其护甲降低{1}点，持续{2}分钟。被诅咒的敌人不会逃跑，并会无视恐惧和惊骇效果。每个术士在任一目标身上只能维持一种诅咒。", zhTW = "對目標施加魯莽的詛咒，使其護甲值降低{1}點，持續{2}分鐘。被詛咒的敵人不會逃跑，也不會受到恐懼的影響。每個術士只能對同一個目標施加一種詛咒。" },
	["dagger/fist: increases your"] = { zhTW = "匕首/拳套：使你的" },
	["damage caused by holy shield causes #% additional threat"] = { ko = "신성한 방패로 입히는 피해는 위협 수준을 {1}%만큼 추가로 생성합니다.", zhTW = "神聖之盾造成的傷害產生的威脅值提高{1}%。" },
	["damage caused by the devouring plague heals the caster"] = { ko = "파멸의 역병으로 인해 입히는 피해만큼 시전자의 생명력이 회복됩니다." },
	["damage caused may interrupt the effect"] = { ko = "대상이 피해를 입으면 효과가 해제될 수 있습니다.", zhCN = "任何伤害都有可能打断这个效果。", zhTW = "任何傷害將會中止此效果。" },
	["damage increased by #% against poisoned targets"] = { ko = "독에 걸린 대상을 가격할 때 공격력이 {1}%만큼 증가합니다.", zhCN = "对中毒目标造成的伤害提高{1}%。", zhTW = "對中毒目標造成的傷害提高{1}%。" },
	["damage increases per combo point and by your attack power:"] = { ko = "연계 점수와 전투력에 따라 피해가 증가합니다:", zhCN = "伤害将根据连击点数和攻击强度决定：", zhTW = "根據連擊點數和你的攻擊強度決定傷害量：" },
	["damage is increased by your attack power"] = { ko = "입히는 피해는 전투력에 따라 증가합니다.", zhTW = "以你的攻擊強度來提升傷害：" },
	["damaging melee attacks against you have a #% chance to increase your chance to block by #%"] = { ko = "근접 공격을 받으면 {1}%의 확률로 방패 막기 확률이 {2}%만큼 증가합니다.", zhCN = "对你造成伤害的近战攻击有{1}%的几率使你的格挡几率提高{2}%。", zhTW = "使你每次受到近戰攻擊後有{1}%的機率使盾牌格擋的機率提高{2}%。" },
	["damaging melee attacks against you have a #% chance to increase your chance to block by #%. lasts # sec or # blocks"] = { ko = "근접 공격을 받으면 {1}%의 확률로 방패 막기 확률이 {2}%만큼 증가합니다. {3}초 동안 혹은 {4}회의 공격을 방패로 막을 때까지 지속됩니다.", zhCN = "对你造成伤害的近战攻击有{1}%的几率使你的格挡几率提高{2}%。持续{3}秒或格挡{4}次。", zhTW = "使你每次受到近戰攻擊後有{1}%的機率使盾牌格擋的機率提高{2}%。盾牌壁壘可持續{3}秒或格擋{4}次攻擊。" },
	["dampens magic used against the targeted party member, decreasing damage taken from spells by up to # and healing spells by up to #"] = { ko = "대상 파티원에게 미치는 마법의 위력을 감쇠시켜 마법 공격으로 받는 피해를 최대 {1}만큼 감소시키지만, 치유 주문에 의한 회복량이 최대 {2}만큼 감소됩니다." },
	["dampens magic used against the targeted party member, decreasing damage taken from spells by up to # and healing spells by up to # lasts # min"] = { ko = "대상 파티원에게 미치는 마법의 위력을 감쇠시켜 마법 공격으로 받는 피해를 최대 {1}만큼 감소시키지만, 치유 주문에 의한 회복량이 최대 30만큼 감소됩니다. {3}분 동안 지속됩니다.", zhCN = "降低施放于目标小队成员身上的魔法效果，使其受到的法术伤害降低最多{1}点，治疗法术恢复生命值的效果降低最多30点，持续{3}分钟。", zhTW = "降低施放於目標小隊成員身上的魔法效果，使其受到的法術傷害降低最多{1}點，治療法術恢復生命力的效果降低最多30點，持續{3}分鐘。" },
	["dazes the target, slowing movement speed by #% for # sec"] = { ko = "적을 멍하게 해 {2}초 동안 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "钉刺目标，使其移动速度降低{1}%，持续{2}秒。", zhTW = "暈眩目標，使其移動速度降低{1}%，持續{2}秒。" },
	["deals # holy damage every time you block"] = { ko = "방패 막기에 성공할 때마다 적에게 {1}의 신성 피해를 입힙니다.", zhCN = "每次格挡时造成{1}点神圣伤害。", zhTW = "每次成功格擋都會造成{1}點神聖傷害。" },
	["deals # nature damage every # sec to any enemy in an # yard radius around the caster for # sec"] = { ko = "{4}초 동안 시전자 주위 {3}미터 반경의 모든 대상에게 매 {2}초마다 {1}의 자연 피해를 입힙니다.", zhCN = "每{2}秒对施法者身边半径{3}码范围内的敌人造成{1}点自然伤害，持续{4}秒。", zhTW = "每{2}秒對施法者身邊半徑{3}碼範圍內的敵人造成{1}點自然傷害，持續{4}秒。" },
	["deals # physical damage every time you block"] = { ko = "방패 막기에 성공할 때마다 {1}의 물리 피해를 입힙니다.", zhCN = "每次格挡时造成{1}点物理伤害。", zhTW = "每次成功格擋都會造成{1}點物理傷害。" },
	["deals # to # fire damage to a target"] = { ko = "대상에게 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "对一个目标造成{1}至{2}点火焰伤害。", zhTW = "對目標造成{1}至{2}點火焰傷害。" },
	["deals # to # fire damage to your target and an additional #% damage if the target is afflicted by immolate"] = { ko = "대상에게 {1}~{2}의 화염 피해를 입힙니다. 또한 대상에게 제물이 걸려 있으면 {3}%의 추가 피해를 입힙니다.", zhCN = "对你的目标造成{1}至{2}点火焰伤害，如果目标受到献祭的影响，则额外造成{3}%的伤害。", zhTW = "對你的目標造成{1}至{2}點火焰傷害，如果目標受獻祭影響會額外造成{3}%傷害。" },
	["deals # to # frost damage to an enemy target"] = { ko = "적 대상에게 {1}~{2}의 냉기 피해를 입힙니다.", zhCN = "对一个敌方目标造成{1}至{2}点冰霜伤害。", zhTW = "對一個敵方目標造成{1}至{2}點冰霜傷害。" },
	["deals # to # frost damage to an enemy target. deals #% increased damage to frozen targets"] = { ko = "적 대상에게 {1}~{2}의 냉기 피해를 입힙니다. 얼어붙은 대상에게는 {3}%의 추가 피해를 입힙니다.", zhCN = "对一个敌方目标造成{1}至{2}点冰霜伤害。对被冰冻的目标造成的伤害提高{3}%。", zhTW = "對一個敵方目標造成{1}至{2}點冰霜傷害。對冰凍敵人造成的傷害提高{3}%。" },
	["deals #% increased damage to frozen targets"] = { ko = "얼어붙은 대상에게는 {1}%의 추가 피해를 입힙니다.", zhCN = "对被冰冻的目标造成的伤害提高{1}%。", zhTW = "對冰凍敵人造成的傷害提高{1}%。" },
	["deals #% increased damage to targets below #% health"] = { ko = "생명력이 {2}% 미만인 대상에게는 {1}%의 추가 피해를 입힙니다." },
	["decipher an untranslated scroll"] = { ko = "번역되지 않은 두루마리를 해독합니다.", zhCN = "解译一张未翻译的卷轴。", zhTW = "解讀未翻譯的卷軸。" },
	["decrease the armor of the target by # for # sec"] = { ko = "{2}초 동안 대상의 방어도를 {1}만큼 감소시킵니다.", zhCN = "使目标的护甲降低{1}点，持续{2}秒。", zhTW = "使目標的護甲降低{1}點，持續{2}秒。" },
	["decrease the armor of the target by # for # sec. while affected, the target cannot stealth or turn invisible"] = { ko = "{2}초 동안 대상의 방어도를 {1}만큼 감소시킵니다. 효과가 지속되는 동안은 은신이나 투명화가 불가능합니다.", zhCN = "使目标的护甲降低{1}点，持续{2}秒。在效果持续期间，目标无法潜行或隐形。", zhTW = "使目標的護甲降低{1}點，持續{2}秒。在效果持續期間，目標無法潛行或隱形。" },
	["decreases damage taken by #% and damage caused by #%"] = { ko = "받는 피해가 {1}%만큼, 공격력이 {2}%만큼 감소합니다.", zhCN = "受到的伤害降低{1}%，造成的伤害降低{2}%。" },
	["decreases the cooldown of your fade ability by # sec"] = { ko = "소실의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的渐隐术的冷却时间减少{1}秒。", zhTW = "使你的漸隱術的冷卻時間減少{1}秒。" },
	["decreases the cooldown of your hammer of justice spell by # sec"] = { ko = "심판의 망치의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的制裁之锤的冷却时间减少{1}秒。", zhTW = "使你的制裁之錘的冷卻時間減少{1}秒。" },
	["decreases the cooldown of your judgement ability by # sec"] = { ko = "심판의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的审判技能冷却时间缩短{1}秒。", zhTW = "使你審判技能的冷卻時間縮短{1}秒。" },
	["decreases the mana lost per point of damage taken when your mana shield spell is active by #% and increases the resistances granted by your mage armor spell by #%"] = { ko = "마나 보호막이 활성화된 동안 받는 피해 1당 소모되는 마나가 {1}%만큼 감소하고, 마법사 갑옷으로 증가하는 저항력이 {2}%만큼 증가합니다.", zhCN = "使你的法力护盾每吸收一点伤害所消耗的法力值减少{1}%，并使你的魔甲术提供的抗性提高{2}%。", zhTW = "當你的法力護盾生效時，每點傷害所需要的法力降低{1}%，且你的魔甲術賦予的抗性提高{2}%。" },
	["delivers a fatal wound for # to # physical damage"] = { ko = "치명상을 가해 {1} 에서 {2}의 물리 피해를 입힙니다." },
	["delivers a fatal wound for # to # physical damage. deals #% increased damage to targets below #% health"] = { ko = "치명상을 가해 {1} 에서 {2}의 물리 피해를 입힙니다. 생명력이 {4}% 미만인 대상에게는 {3}%의 추가 피해를 입힙니다." },
	["deploy a banner representing your chosen faction in the desolace centaur war for # min"] = { ko = "{1}분 동안 잊혀진 땅 켄타우로스 전쟁에서 선택한 진영을 나타내는 깃발을 배치합니다.", zhCN = "部署一面代表你在凄凉之地半人马战争中所选阵营的战旗，持续{1}分钟。", zhTW = "置放一面代表你在淒涼之地半人馬戰爭中所選陣營的旗幟，持續{1}分鐘。" },
	["detects beneficial magic effects on the target for # min"] = { ko = "{1}분 동안 대상에 걸린 강화 마법을 감지할 수 있습니다.", zhCN = "侦测目标身上的有益魔法效果，持续{1}分钟。", zhTW = "偵測目標身上的有益魔法效果，持續{1}分鐘。" },
	["dig up a grave"] = { ko = "무덤을 파헤칩니다." },
	["dig up a grave. usable at raven hill cemetery and scarlet monastery graveyard"] = { ko = "무덤을 파헤칩니다. 까마귀 언덕 묘지와 붉은십자군 수도원 묘지에서 사용할 수 있습니다." },
	["disables auto-attack"] = { ko = "자동 공격을 비활성화합니다.", zhCN = "停用自动攻击。", zhTW = "停用自動攻擊。" },
	["disarm target's weapon for # sec"] = { ko = "{1}초 동안 적을 무장 해제시킵니다.", zhCN = "使目标在{1}秒内无法使用武器作战。", zhTW = "使目標在{1}秒內無法使用武器作戰。" },
	["disarm the enemy's weapon for # sec"] = { ko = "{1}초 동안 적을 무장 해제시킵니다.", zhCN = "卸除敌人的武器，持续{1}秒。", zhTW = "卸除敵人的武器，持續{1}秒。" },
	["dismiss your pet"] = { ko = "야수의 소환을 해제합니다.", zhCN = "解散你的野兽。", zhTW = "解散你的寵物。" },
	["dismiss your pet. dismissing your pet will reduce its happiness by #"] = { ko = "야수의 소환을 해제합니다. 소환 해제된 야수는 충성도가 {1}만큼 감소합니다.", zhCN = "解散你的野兽。这会使其快乐值降低{1}点。", zhTW = "解散你的寵物。這會使其快樂值降低{1}點。" },
	["dismissing your pet will reduce its happiness by #"] = { ko = "소환 해제된 야수는 충성도가 {1}만큼 감소합니다.", zhCN = "这会使其快乐值降低{1}点。", zhTW = "這會使其快樂值降低{1}點。" },
	["dispels # curse or bane from a friendly target"] = { ko = "아군 대상에 걸린 저주 또는 파멸 {1}개를 해제합니다.", zhCN = "从一个友方目标身上驱散{1}个诅咒或灾祸。", zhTW = "從一個友方目標身上驅散{1}個詛咒或災禍。" },
	["dispels magic on the target, removing # harmful spell from a friend or # beneficial spell from an enemy"] = { ko = "대상에게 걸린 마법을 무효화합니다. 아군에게서 {1}개의 해로운 주문을 제거하거나 적에게서 {2}개의 이로운 주문을 제거합니다.", zhCN = "驱散目标身上的魔法效果，从友方身上移除{1}个有害法术，或是从敌人身上移除{2}个有益法术。", zhTW = "驅散目標身上的魔法效果，從友方身上移除{1}個有害法術，或是從敵人身上移除{2}個有益法術。" },
	["dispels magic on the target, removing # harmful spells from a friend or # beneficial spells from an enemy"] = { ko = "대상에게 걸린 마법을 무효화합니다. 아군에게서 {1}개의 해로운 주문을 제거하거나 적에게서 {2}개의 이로운 주문을 제거합니다.", zhCN = "驱散目标身上的魔法效果，从友方身上移除{1}个有害法术，或是从敌人身上移除{2}个有益法术。", zhTW = "驅散目標身上的魔法效果，從友方身上移除{1}個有害法術，或是從敵人身上移除{2}個有益法術。" },
	["disrupt a magnetic field between you and your nearby enemy target, knocking you both away"] = { ko = "자신과 주위 적 대상 사이의 자기장을 교란시켜 서로를 뒤로 밀쳐냅니다.", zhCN = "干扰你和附近敌方目标之间的磁场，将你们同时击退。", zhTW = "干擾你和附近敵方目標之間的磁場，將你們同時擊退。" },
	["distract the target, causing threat"] = { ko = "적에게 견제 사격을 해 자신에 대한 위협 수준을 증가시킵니다.", zhCN = "扰乱目标，对其产生威胁值。", zhTW = "擾亂目標，對其產生威脅值。" },
	["distract the target, causing threat. more effective than distracting shot (rank #)"] = { ko = "적에게 견제 사격을 해 자신에 대한 위협 수준을 증가시킵니다. {1}레벨 견제 사격보다 효과가 좋습니다.", zhCN = "扰乱目标，对其产生威胁值。比扰乱射击（等级 {1}）更有效。", zhTW = "擾亂目標，對其產生威脅值。比擾亂射擊（等級 {1}）更有效。" },
	["does not affect the cooldown of abilities which share a cooldown with arcane shot"] = { ko = "신비한 사격과 재사용 대기시간을 공유하는 능력의 재사용 대기시간에는 영향을 주지 않습니다.", zhCN = "不影响与奥术射击共享冷却时间的技能。", zhTW = "不會影響與秘法射擊共用冷卻時間的技能的冷卻時間。" },
	["does not break prowling"] = { ko = "숨기 효과가 풀리지 않습니다.", zhCN = "不会打断潜行效果。", zhTW = "不會打斷潛行。" },
	["does not break stealth"] = { ko = "은신이 풀리지 않습니다.", zhCN = "不会取消潜行状态。", zhTW = "不會取消潛行狀態。" },
	["does not consume the seal"] = { ko = "문장을 소모하지 않습니다.", zhCN = "不会消耗圣印。", zhTW = "不會消耗聖印。" },
	["don't get too close or the trap will go off"] = { ko = "너무 가까이 다가가면 함정이 동작하게 됩니다.", zhCN = "不要靠得太近，否则陷阱会被触发。", zhTW = "不要靠得太近，否則陷阱會被觸發。" },
	["drains # mana per damage absorbed"] = { ko = "흡수된 피해당 {1}의 마나를 소비합니다.", zhCN = "每吸收1点物理伤害，就消耗{1}点法力值。", zhTW = "每吸收1點物理傷害，就消耗{1}點法力。" },
	["drains # of your pet's mana, returning #% to you"] = { ko = "소환수에게서 {1}의 마나를 흡수하여 그의 {2}%에 해당하는 마나를 자신의 것으로 만듭니다.", zhCN = "从你的宠物身上抽取{1}点法力值并全部转化给你。", zhTW = "從你的寵物身上抽取{1}點法力並全部轉化給你。" },
	["drains # to # mana from a target"] = { ko = "대상의 마나를 {1}~{2}만큼 소진시킵니다." },
	["drains # to # mana from a target. for each mana drained in this way, the target takes # shadow damage"] = { ko = "대상의 마나를 {1}~{2}만큼 소진시킵니다. 대상은 소진된 마나의 절반만큼 암흑 피해를 입습니다.", zhCN = "从目标身上吸取{1}至{2}点法力值，每吸取1点法力值，目标就受到{3}点伤害。", zhTW = "從目標身上吸取{1}至{2}點法力，每吸取1點法力，目標就受到{3}點傷害。" },
	["drains all of the paladin's remaining mana when used, but does not interrupt mana regeneration"] = { ko = "이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" },
	["drains the soul of the target, causing # shadow damage over # sec"] = { ko = "적의 영혼을 소진시켜 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다.", zhCN = "吸取目标的灵魂，在{2}秒内造成{1}点暗影伤害。", zhTW = "吸取目標的靈魂，在{2}秒內對其造成累計{1}點暗影傷害。" },
	["drains the soul of the target, causing # shadow damage over # sec. non-trivial targets damaged by drain soul have a chance to grant you a soul shard. non-trivial targets killed by drain soul will always grant you a soul shard. soul shards are required for other spells"] = { ko = "적의 영혼을 소진시켜 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다. 영혼 흡수로 사소하지 않은 대상에게 피해를 입히면 일정 확률로 영혼의 조각을 얻습니다. 영혼 흡수로 사소하지 않은 대상을 처치하면 항상 영혼의 조각을 얻습니다. 영혼의 조각은 다른 흑마법에 사용됩니다.", zhCN = "吸取目标的灵魂，在{2}秒内造成{1}点暗影伤害。对能为你提供经验值或荣誉值的敌人造成吸取灵魂伤害时，有几率使你获得一块灵魂碎片。消灭一个能为你提供经验值或荣誉值的敌人且其死于吸取灵魂时，必定使你获得一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。", zhTW = "吸取目標的靈魂，在{2}秒內對其造成累計{1}點暗影傷害。以吸取靈魂對有實力的目標造成傷害時，有一定機率使你獲得一塊靈魂裂片。以吸取靈魂擊殺有實力的目標時，則一律獲得一塊靈魂裂片。靈魂碎片是施放其他一些法術所必需的材料。" },
	["draws on the soul of the party member to shield them, absorbing # damage"] = { ko = "파티원의 영적인 힘을 이용하여 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다.", zhCN = "汲取一名队伍成员的灵魂力量，为其施加护盾，吸收{1}点伤害。", zhTW = "汲取隊友的靈魂之力，為其加上魔法護盾，可吸收{1}點傷害。" },
	["draws on the soul of the party member to shield them, absorbing # damage. lasts # sec. while the shield holds, spellcasting will not be interrupted by damage. once shielded, the target cannot be shielded again for # sec"] = { ko = "파티원의 영적인 힘을 이용하여 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다. {2}초 동안 지속됩니다. 보호막이 지속되는 동안은 피해에 의해 주문 시전이 방해받지 않습니다. 한 번 보호막을 사용한 대상에겐 {3}초 동안 다시 보호막을 사용할 수 없습니다.", zhCN = "汲取一名队伍成员的灵魂力量，为其施加护盾，吸收{1}点伤害。持续{2}秒。护盾存在期间，其施法不会因受到伤害而被打断。受到护盾保护后，该目标在{3}秒内无法再次受到护盾保护。", zhTW = "汲取隊友的靈魂之力，為其加上魔法護盾，可吸收{1}點傷害。持續{2}秒。只要護盾存在，受保護者的施法就不會被傷害打斷。目標在被加上護盾之後的{3}秒內無法再被加上護盾。" },
	["drink to increase healing done by spells and effects by up to #"] = { ko = "마시면 주문 및 효과에 의한 치유량이 최대 {1}만큼 증가합니다." },
	["drink to increase healing done by spells and effects by up to # lasts # min"] = { ko = "마시면 주문 및 효과에 의한 치유량이 최대 10만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使法术和效果所造成的治疗效果提高最多10点，持续{2}分钟。", zhTW = "飲用以使法術和效果造成的治療效果最多提高10點，持續{2}分鐘。" },
	["drink to increase nature spell damage by up to #"] = { ko = "마시면 자연 주문 공격력이 최대 {1}만큼 증가합니다." },
	["drink to increase nature spell damage by up to # lasts for # min"] = { ko = "마시면 자연 주문 공격력이 최대 40만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使自然法术伤害提高最多40点，持续{2}分钟。", zhTW = "飲用以使自然法術傷害最多提高40點，持續{2}分鐘。" },
	["drink to increase spell damage by up to #"] = { ko = "마시면 주문 공격력이 최대 {1}만큼 증가합니다." },
	["drink to increase spell damage by up to # lasts for # min"] = { ko = "마시면 주문 공격력이 최대 15만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使法术伤害提高最多15点，持续{2}分钟。", zhTW = "飲用以使法術傷害最多提高15點，持續{2}分鐘。" },
	["drink to increase your intellect by #"] = { ko = "마시면 지능이 {1}만큼 증가합니다." },
	["drink to increase your intellect by # and chance to critically hit by #%"] = { ko = "마시면 지능이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다." },
	["drink to increase your intellect by # and chance to critically hit by #%. lasts for # min"] = { ko = "마시면 지능이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다. {3}분 동안 지속됩니다.", zhCN = "饮用以使你的智力提高{1}点，造成爆击的几率提高{2}%，持续{3}分钟。", zhTW = "飲用以使你的智力提高{1}點，造成致命一擊的機率提高{2}%，持續{3}分鐘。" },
	["drink to increase your intellect by # lasts for # min"] = { ko = "마시면 지능이 6만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的智力提高6点，持续{2}分钟。", zhTW = "飲用以使你的智力提高6點，持續{2}分鐘。" },
	["drink to increase your maximum health by #"] = { ko = "마시면 최대 생명력이 {1}만큼 증가합니다." },
	["drink to increase your maximum health by # lasts for # min"] = { ko = "마시면 최대 생명력이 200만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的最大生命值提高200点，持续{2}分钟。", zhTW = "飲用以使生命力上限提高200點，持續{2}分鐘。" },
	["drink to increase your spirit by #"] = { ko = "마시면 정신력이 {1}만큼 증가합니다." },
	["drink to increase your spirit by # and chance to critically hit by #%"] = { ko = "마시면 정신력이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다." },
	["drink to increase your spirit by # and chance to critically hit by #%. lasts for # min"] = { ko = "마시면 정신력이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다. {3}분 동안 지속됩니다.", zhCN = "饮用以使你的精神提高{1}点，造成爆击的几率提高{2}%，持续{3}分钟。", zhTW = "飲用以使你的精神提高{1}，造成致命一擊的機率提高{2}%，持續{3}分鐘。" },
	["drink to increase your spirit by # lasts for # min"] = { ko = "마시면 정신력이 3만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的精神提高3点，持续{2}分钟。", zhTW = "飲用以使你的精神提高3點，持續{2}分鐘。" },
	["drink to increase your strength and agility by #"] = { ko = "마시면 힘과 민첩성이 {1}만큼 증가합니다." },
	["drink to increase your strength and agility by # lasts for # min"] = { ko = "마시면 힘과 민첩성이 18만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的力量和敏捷提高18点，持续{2}分钟。", zhTW = "飲用以使你的力量和敏捷提高18點，持續{2}分鐘。" },
	["drink to increase your strength by #"] = { ko = "마시면 힘이 {1}만큼 증가합니다." },
	["drink to increase your strength by # and chance to critically hit by #%"] = { ko = "마시면 힘이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다." },
	["drink to increase your strength by # and chance to critically hit by #%. lasts for # min"] = { ko = "마시면 힘이 {1}만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다. {3}분 동안 지속됩니다.", zhCN = "饮用以使你的力量提高{1}点，造成爆击的几率提高{2}%，持续{3}分钟。", zhTW = "飲用以使你的力量提高{1}點，造成致命一擊的機率提高{2}%，持續{3}分鐘。" },
	["drink to increase your strength by # lasts for # min"] = { ko = "마시면 힘이 10만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的力量提高10点，持续{2}分钟。", zhTW = "飲用以使你的力量提高10點，持續{2}分鐘。" },
	["drink to regenerate # mana every # sec"] = { ko = "마시면 {2}초마다 마나를 {1}만큼 회복합니다." },
	["drink to regenerate # mana every # sec. lasts for # min"] = { ko = "마시면 {2}초마다 마나를 {1}만큼 회복합니다. {3}분 동안 지속됩니다.", zhCN = "饮用以使你每{2}秒恢复{1}点法力值，持续{3}分钟。", zhTW = "飲用以使你每{2}秒恢復{1}點法力，持續{3}分鐘。" },
	["drink to restore # health and # mana every # sec"] = { ko = "마시면 {3}초마다 생명력을 {1}만큼, 마나를 {2}만큼 회복합니다." },
	["drink to restore # health and # mana every # sec. lasts for # min"] = { ko = "마시면 {3}초마다 생명력을 {1}만큼, 마나를 {2}만큼 회복합니다. {4}분 동안 지속됩니다.", zhCN = "饮用以使你每{3}秒恢复{1}点生命值和{2}点法力值，持续{4}分钟。", zhTW = "飲用以每{3}秒恢復{1}點生命力和{2}點法力，持續{4}分鐘。" },
	["drink to slightly increase your stealth detection"] = { ko = "마시면 은신 감지 능력이 약간 증가합니다.", zhCN = "饮用后，你的潜行侦测能力略微提高。", zhTW = "飲用後略微提高你的潛行偵測能力。" },
	["drink to slightly increase your stealth detection. while you are not moving for # sec, nearby moving stealthed enemies may reveal a heat trail. lasts for # min"] = { ko = "마시면 은신 감지 능력이 약간 증가합니다. {1}초 동안 움직이지 않으면 주위의 은신한 적이 움직일 때 열기 흔적이 드러날 수 있습니다. {2}분 동안 지속됩니다.", zhCN = "饮用后，你的潜行侦测能力略微提高。静止不动{1}秒后，附近正在移动的潜行敌人可能显露出热力轨迹。持续{2}分钟。", zhTW = "飲用後略微提高你的潛行偵測能力。當你靜止不動{1}秒時，附近移動中的潛行敵人可能會顯現熱成像痕跡。持續{2}分鐘。" },
	["druid must channel to maintain the spell"] = { ko = "주문을 유지하려면 계속 정신을 집중해야 합니다.", zhCN = "德鲁伊必须持续引导才能维持该法术。", zhTW = "德魯伊必須引導以維持法術效果。" },
	["each block expends a charge. # charges"] = { zhTW = "每次成功格擋會消耗掉一次格擋機會，最多可格擋{1}次。" },
	["each hit causes # to # additional fire damage, based on the speed of the weapon"] = { ko = "공격이 적중할 때마다 무기의 공격 속도에 따라 {1}~{2}의 추가 화염 피해를 입힙니다.", zhCN = "每次命中会根据武器速度额外造成{1}至{2}点火焰伤害。" },
	["each hit has a #% chance of granting you # extra attacks with # extra melee attack power"] = { ko = "매 공격 시 {1}%의 확률로 근접 전투력이 {3}만큼 증가한 상태에서 {2}회의 추가 공격을 가합니다.", zhCN = "每次击中敌人都有{1}%的几率使你获得额外的{2}次攻击，且这些攻击的近战攻击强度提高{3}点。" },
	["each hit has a chance of causing # additional frost damage and slowing the target's movement speed by #% for # sec"] = { ko = "주문이 지속되는 동안 주술사의 무기는 매번 공격 시 일정 확률로 {1}의 추가 냉기 피해를 입히고 {3}초 동안 대상의 이동 속도를 {2}%만큼 감소시킵니다." },
	["each jump is #% as effective as the previous target"] = { ko = "대상이 바뀔 때마다 이전 대상 대비 {1}%의 효율을 발휘합니다.", zhCN = "治疗链每次跳跃后的治疗效果是上一个目标的{1}%。", zhTW = "治療鍊每次跳躍後的治療效果會等同於先前目標的{1}%。" },
	["each jump reduces the damage by #%"] = { ko = "대상이 바뀔 때마다 피해는 {1}%씩 감소됩니다." },
	["each main hand hit causes # to # additional fire damage, based on the speed of the weapon"] = { ko = "이때 주무기로 공격을 적중시킬 때마다 무기의 공격 속도에 따라 {1}~{2}의 추가 화염 피해를 입힙니다.", zhCN = "每次主手命中会根据武器速度额外造成{1}至{2}点火焰伤害。", zhTW = "每次主手武器命中敵人時，根據武器攻速，可額外造成{1}至{2}點火焰傷害。" },
	["each main hand hit has a #% chance of granting the attacker # extra attack with # extra melee attack power"] = { ko = "이때 주무기로 공격을 적중시킬 때마다 공격자가 {1}%의 확률로 적에게 {3}의 추가 근접 전투력으로 {2}회의 추가 공격을 가합니다.", zhCN = "每次主手命中都有{1}%的几率使攻击者额外攻击{2}次，且这些攻击获得{3}点额外近战攻击强度。", zhTW = "每次主手武器命中敵人時，都有{1}%的機率令攻擊者獲得{2}次額外攻擊機會，且該攻擊的近戰攻擊強度提高{3}點。" },
	["each melee or ranged damage hit against the priest will remove one charge"] = { ko = "근접 및 원거리 피해를 20회 받게 되면 효과가 사라집니다.", zhCN = "每次近战或远程伤害都会使牧师消耗一次防护能量。", zhTW = "每次近戰、遠程傷害攻擊牧師將解除一次防護能量。" },
	["each point of rage is converted into #% health"] = { ko = "분노 {1}은 1%의 생명력으로 전환됩니다.", zhCN = "每点怒气可转化为{1}%的生命值。", zhTW = "每點怒氣可以轉化為{1}%生命力。" },
	["each strike has a #% chance of poisoning the enemy for # nature damage over # sec"] = { zhCN = "每次攻击都有{1}%的几率令敌人中毒，在{3}秒内对其造成{2}点自然伤害，对单一目标最多可以叠加5次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，在{3}秒內對其造成{2}點自然傷害，對單一目標最多可堆疊5次。" },
	["each strike has a #% chance of poisoning the enemy for # nature damage over # sec. stacks up to # times on a single target. # charges"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초에 걸쳐 {2}의 자연 피해를 입힙니다. 효과는 대상마다 {4}번까지 중복될 수 있습니다. {5}회 사용 가능.", zhCN = "每次攻击都有{1}%的几率令敌人中毒，在{3}秒内对其造成{2}点自然伤害，对单一目标最多可以叠加{4}次。可使用{5}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，在{3}秒內對其造成{2}點自然傷害，對單一目標最多可堆疊{4}次。可使用{5}次。" },
	["each strike has a #% chance of poisoning the enemy which instantly inflicts # to # nature damage. # charges"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 즉시 {2}~{3}의 자연 피해를 입힙니다. {4}회 사용 가능합니다.", zhCN = "每次攻击都有{1}%的几率使敌人中毒，立即对其造成{2}至{3}点自然伤害。可使用{4}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，立即對其造成{2}至{3}點自然傷害。可使用{4}次。" },
	["each strike has a #% chance of poisoning the enemy which instantly inflicts # to # nature damage. #,# charges"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 즉시 {2}~{3}의 자연 피해를 입힙니다. {4},{5}회 사용 가능합니다.", zhCN = "每次攻击都有{1}%的几率使敌人中毒，立即对其造成{2}至{3}点自然伤害。可使用{4},{5}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，立即對其造成{2}至{3}點自然傷害。可使用{4},{5}次。" },
	["each strike has a #% chance of poisoning the enemy, increasing their casting time by #% for # sec. # charges"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 시전 시간을 {2}%만큼 지연시킵니다. {4}회 사용 가능.", zhCN = "每次攻击都有{1}%的几率令敌人中毒，使其施法时间延长{2}%，持续{3}秒。可使用{4}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其施法時間延長{2}%，持續{3}秒。可使用{4}次。" },
	["each strike has a #% chance of poisoning the enemy, reducing all healing effects used on them by # for # sec. stacks up to # times on a single target. # charges"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 대상에 대한 모든 치유 효과를 {2}만큼 감소시킵니다. 효과는 대상마다 {4}번까지 중첩될 수 있습니다. {5}회 사용 가능합니다.", zhCN = "每次攻击都有{1}%的几率使敌人中毒，使其受到的所有治疗效果降低{2}，持续{3}秒。对单一目标最多叠加{4}次。可使用{5}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其在受到治療時效果降低{2}點，持續{3}秒。對單一目標最多可堆疊{4}次。可使用{5}次。" },
	["each strike has a #% chance of poisoning the enemy, slowing their movement speed by #% for # sec"] = { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 이동 속도를 {2}%만큼 감소시킵니다.", zhCN = "每次攻击都有{1}%的几率令敌人中毒，使其移动速度降低{2}%，持续{3}秒。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其移動速度降低{2}%，持續{3}秒。" },
	["each swing alternates your attack speed between #% faster and #% slower"] = { ko = "공격할 때마다 공격 속도가 {1}% 증가한 상태와 {2}% 감소한 상태를 번갈아 전환합니다.", zhCN = "每次挥击都会使你的攻击速度在加快{1}%和减慢{2}%之间交替。", zhTW = "每次攻擊都會使你的攻擊速度在提高{1}%和降低{2}%之間輪換。 slower." },
	["each time holy fire deals damage, you have a #% chance for your next holy nova to cost no mana"] = { ko = "신성한 불꽃으로 피해를 입힐 때마다 {1}%의 확률로 다음 신성한 폭발이 마나를 소모하지 않습니다.", zhCN = "每次神圣之火造成伤害时，你有{1}%的几率使下一个神圣新星不消耗法力值。", zhTW = "神聖之火每次造成傷害時，都有{1}%的機率使你的下一個神聖新星不消耗法力。" },
	["each time you cast arcane blast, the damage of all your other spells is increased by #% and the mana cost of arcane blast is increased by #%"] = { ko = "이 주문을 시전할 때마다 다른 모든 주문의 공격력이 {1}%만큼, 비전 작렬 주문의 마나 소모량이 {2}%만큼 증가합니다.", zhCN = "每次施放奥术冲击，所有其他法术的伤害提高{1}%，奥术冲击的法力消耗提高{2}%。", zhTW = "每次施放秘法衝擊時會使你所有其他法術的傷害提高{1}%，並且秘法衝擊的法力消耗提高{2}%。" },
	["eat me"] = { ko = "맛있어 보이는 물고기.", zhCN = "吃我。", zhTW = "吃我。" },
	["effect stacks up to # times and lasts # sec or until any other damage spell is cast"] = { ko = "이 효과는 최대 {1}번까지 중첩되며 {2}초 동안 혹은 비전 작렬을 제외한 다른 공격 주문 시전 시까지 지속됩니다.", zhCN = "该效果最多叠加{1}次，持续{2}秒，或直到施放任何其他伤害法术。", zhTW = "此效果最多可堆疊{1}次，持續{2}秒，或直到施放任何其他傷害性法術為止。" },
	["emphasis on safe"] = { ko = "안전이 보장된 제품입니다.", zhCN = "非常非常安全！", zhTW = "非常非常安全！" },
	["enemies standing within the cloud have their hit chance reduced by #%"] = { zhCN = "站在烟雾中的敌人的命中几率降低{1}%。", zhTW = "站在煙霧中的敵人的命中機率降低{1}%。" },
	["enemies standing within the cloud suffer # nature damage every # sec"] = { ko = "구름 안에 서 있는 적은 {2}초마다 {1}의 자연 피해를 받습니다.", zhCN = "站在烟雾中的敌人每{2}秒受到{1}点自然伤害。", zhTW = "煙霧範圍內的敵人每{2}秒受到{1}點自然傷害。" },
	["enemies stunned by your kidney shot ability take #% increased damage from your poisons and attacks"] = { ko = "급소 가격으로 기절시킨 적에게 독과 공격으로 입히는 피해가 {1}%만큼 증가합니다.", zhCN = "被你的肾击昏迷的敌人，受到你的毒药和攻击的伤害提高{1}%。", zhTW = "敵人被你的腎擊技能擊昏後，你的毒藥和攻擊對其造成的傷害提高{1}%。" },
	["enemies will stop attacking the protected party member, who will be immune to all harmful attacks but cannot take any action for # min"] = { ko = "대상을 공격하던 적은 공격을 멈추게 되며 대상은 모든 공격에 대해 면역이 되지만 {1}분 동안 어떤 행동도 할 수 없습니다.", zhCN = "敌人会停止攻击被保护的队友，但该队友在{1}分钟内无法进行任何行动。", zhTW = "敵人會停止攻擊被保護的隊友，但該隊友在{1}分鐘內無法進行任何行動。" },
	["erects a lodestone that allows you and others sitting nearby to gain # (below #) · # (below #) · # (below #) · # (below #) · # (below #) · #(above) increased melee attack power, mutually exclusive with blessing of might"] = { ko = "자철석을 세워 자신과 주위에 앉은 다른 플레이어의 근접 전투력을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}({8}레벨 미만) · {9}({10}레벨 미만) · {11}(그 위)만큼 증가시킵니다. 힘의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（{8}级以下） · {9}（{10}级以下） · {11}（更高），与力量祝福互斥。", zhTW = "豎起一塊磁石，使你和附近坐下的其他人近戰攻擊強度提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（{8}級以下） · {9}（{10}級以下） · {11}（更高），與力量祝福互斥。" },
	["erects a lodestone that allows you and others sitting nearby to gain # increased melee attack power, mutually exclusive with blessing of might"] = { ko = "자철석을 세워 자신과 주위에 앉은 다른 플레이어의 근접 전투력을 {1}만큼 증가시킵니다. 힘의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高{1}，与力量祝福互斥。", zhTW = "豎起一塊磁石，使你和附近坐下的其他人近戰攻擊強度提高{1}，與力量祝福互斥。" },
	["escape all immobilizing effects"] = { ko = "모든 이동 불가 효과에서 벗어납니다.", zhCN = "解除所有定身效果。", zhTW = "擺脫所有無法移動效果。" },
	["every strike against the target causes # fire damage to the attacker"] = { ko = "이 대상을 공격할 때마다 {1}의 화염 피해를 받습니다.", zhCN = "每次击中目标都会使攻击者受到{1}点火焰伤害。", zhTW = "任何使用近戰武器擊中被保護者的敵人都會受到{1}點火焰傷害。" },
	["exposes all hidden and invisible enemies within # yards of the targeted area for # sec"] = { ko = "{2}초 동안 대상 지역 주위 {1}미터 반경 내에 있는 은신이나 투명 상태에 있는 모든 적을 감지합니다.", zhCN = "侦测指定区域半径{1}码范围内的所有潜行和隐形的敌人，持续{2}秒。", zhTW = "偵測指定區域半徑{1}碼範圍內的所有潛行和隱形的敵人，持續{2}秒。" },
	["exposes all hidden and invisible enemies within # yards of the targeted area, and staves off magical darkness for # sec"] = { ko = "{2}초 동안 대상 지역 주위 {1}미터 반경 내에 있는 은신이나 투명 상태의 적을 모두 감지하고, 마법의 어둠을 몰아냅니다.", zhCN = "使指定区域{1}码范围内的所有潜行和隐形的敌人暴露，并抵挡源自魔法的黑暗，持续{2}秒。", zhTW = "偵測指定區域半徑{1}碼範圍內的所有隱藏和隱形的敵人，並暫時阻擋魔法黑暗，持續{2}秒。" },
	["fade out, discouraging enemies from attacking you for # sec"] = { ko = "{1}초 동안 몸을 희미하게 만들어 적이 자신을 공격할 확률을 감소시킵니다.", zhCN = "渐渐消失，使敌人不再攻击你，持续{1}秒。", zhTW = "漸漸消失，使敵人不再攻擊你，持續{1}秒。" },
	["fade out, discouraging enemies from attacking you for # sec. more effective than fade (rank #)"] = { ko = "{1}초 동안 몸을 희미하게 만들어 적이 자신을 공격할 확률을 감소시킵니다. {2}레벨 소실보다 효과가 좋습니다.", zhCN = "渐渐消失，使敌人不再攻击你，持续{1}秒。比渐隐术（等级 {2}）的效果更好。", zhTW = "漸漸消失，使敵人不再攻擊你，持續{1}秒。比漸隱術（等級 {2}）的效果更好。" },
	["feed your pet the selected item"] = { ko = "자신의 야수에게 선택한 먹이를 줍니다." },
	["feed your pet the selected item. feeding your pet increases happiness. using food close to the pet's level will have a better result"] = { ko = "자신의 야수에게 선택한 먹이를 줍니다. 먹이를 주면 야수의 포만감을 높일 수 있습니다. 야수의 레벨에 맞는 먹이를 주면 더 효과가 좋습니다.", zhCN = "使用指定的食物为你的宠物喂食，提高宠物的快乐度。使用与宠物等级相近的食物效果更好。", zhTW = "使用指定的食物為你的寵物餵食，提高寵物的快樂度。使用與寵物等級相近的食物效果更好。" },
	["feeding your pet increases happiness"] = { ko = "먹이를 주면 야수의 포만감을 높일 수 있습니다." },
	["feign death which may trick enemies into ignoring you"] = { ko = "적을 속여 자신이 죽은 것처럼 보이게 만듭니다.", zhCN = "假死，可能使敌人忽略你。", zhTW = "假死，可能使敵人忽略你。" },
	["feign death which may trick enemies into ignoring you. lasts # min. if not cancelled, after # min you will actually die"] = { ko = "적을 속여 자신이 죽은 것처럼 보이게 만듭니다. {1}분 동안 지속됩니다. 취소하지 않으면 {2}분 후에 실제로 사망합니다.", zhCN = "假死，可能使敌人忽略你。持续{1}分钟。若未取消，在{2}分钟之后你将真正死亡。", zhTW = "假死，可能使敵人忽略你。持續{1}分鐘。如果未取消，你會在{2}分鐘後真的死亡。" },
	["felhunter - reduces magic damage taken by #%"] = { ko = "지옥사냥개 - 받는 마법 피해가 {1}%만큼 감소합니다.", zhCN = "地狱猎犬 - 受到的魔法伤害降低{1}%。", zhTW = "惡魔獵犬 - 受到的魔法傷害降低{1}%。" },
	["felhunter: restores #% of your total health every # sec"] = { ko = "지옥사냥개: {2}초마다 전체 생명력의 {1}%에 해당하는 생명력을 회복합니다.", zhCN = "地狱猎犬：每{2}秒恢复总生命值的{1}%。", zhTW = "惡魔獵犬：使你每{2}秒恢復{1}%生命力上限。" },
	["fills the paladin with divine fury for # sec, causing melee attacks to deal an additional # holy damage"] = { ko = "성기사가 {1}초 동안 거룩한 분노로 충만해져 근접 공격 시 {2}의 추가 신성 피해를 입히게 합니다.", zhCN = "以神圣愤怒充满圣骑士，持续{1}秒，使近战攻击额外造成{2}点神圣伤害。", zhTW = "神聖的憤怒充滿聖騎士的體內，使其近戰攻擊額外造成{2}點神聖傷害，持續{1}秒。" },
	["fills the paladin with divine fury for # sec, causing melee attacks to deal an additional # holy damage. while a shield is equipped, each attack also grants an absorb shield equal to #% of the holy damage dealt. only one seal can be active on the paladin at any one time"] = { ko = "성기사가 {1}초 동안 거룩한 분노로 충만해져 근접 공격 시 {2}의 추가 신성 피해를 입히게 합니다. 방패를 착용한 동안에는 공격할 때마다 입힌 신성 피해의 {3}%에 해당하는 피해 흡수 보호막이 부여됩니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "以神圣愤怒充满圣骑士，持续{1}秒，使近战攻击额外造成{2}点神圣伤害。装备盾牌时，每次攻击还会获得相当于所造成神圣伤害{3}%的吸收护盾。每名圣骑士在同一时间只能激活一种圣印。", zhTW = "神聖的憤怒充滿聖騎士的體內，使其近戰攻擊額外造成{2}點神聖傷害，持續{1}秒。裝備盾牌時，每次攻擊也會賦予相當於所造成神聖傷害{3}%的吸收護盾。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills the paladin with divine light for # sec, giving each melee attack a chance to heal the paladin for #"] = { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 생명력을 {2}만큼 회복시킵니다.", zhCN = "神圣之光充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率回复{2}点生命值。", zhTW = "神聖之光充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率回復{2}點生命力。" },
	["fills the paladin with divine light for # sec, giving each melee attack a chance to heal the paladin for # only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 생명력을 39만큼 회복시킵니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "神圣之光充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率回复39点生命值。圣骑士在同一时间内只能激活一种圣印。", zhTW = "神聖之光充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率回復39點生命力。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills the paladin with divine wisdom for # sec, giving each melee attack a chance to restore # of the paladin's mana"] = { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 마나를 {2}만큼 회복시킵니다.", zhCN = "神圣的智慧充满圣骑士的体内，持续{1}秒，令其每次使用近战武器击中敌人时都有一定几率恢复{2}点法力值。", zhTW = "神聖的智慧充滿聖騎士的體內，持續{1}秒，令其每次使用近戰武器擊中敵人時都有一定機率恢復{2}點法力。" },
	["fills the paladin with divine wisdom for # sec, giving each melee attack a chance to restore # of the paladin's mana. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 마나를 {2}만큼 회복시킵니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "神圣的智慧充满圣骑士的体内，持续{1}秒，令其每次使用近战武器击中敌人时都有一定几率恢复{2}点法力值。圣骑士在同一时间内只能激活一种圣印。", zhTW = "神聖的智慧充滿聖騎士的體內，持續{1}秒，令其每次使用近戰武器擊中敵人時都有一定機率恢復{2}點法力。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills the paladin with holy spirit for # sec, granting each melee attack an additional # to # holy damage"] = { ko = "{1}초 동안 성기사를 성령의 기운으로 감싸 매 근접 공격 시 {2}~{3}의 추가 신성 피해를 입힙니다.", zhCN = "神圣的灵魂充满圣骑士的体内，持续{1}秒，使每次近战攻击额外造成{2}到{3}点神圣伤害。", zhTW = "神聖的靈魂充滿聖騎士的體內，持續{1}秒，令其每次近戰攻擊額外造成{2}至{3}點神聖傷害。" },
	["fills the paladin with holy spirit for # sec, granting each melee attack an additional # to # holy damage. slower weapons cause more holy damage per swing. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 성기사를 성령의 기운으로 감싸 매 근접 공격 시 {2}~{3}의 추가 신성 피해를 입힙니다. 느린 무기일수록 매 타격 시 더 많은 신성 피해를 입힙니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "神圣的灵魂充满圣骑士的体内，持续{1}秒，使每次近战攻击额外造成{2}到{3}点神圣伤害。武器越慢，每击造成的神圣伤害越高。圣骑士在同一时间内只能激活一种圣印。", zhTW = "神聖的靈魂充滿聖騎士的體內，持續{1}秒，令其每次近戰攻擊額外造成{2}至{3}點神聖傷害。攻擊速度越慢的武器每擊造成的傷害越高。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills the paladin with the spirit of a crusader for # sec, granting # melee attack power"] = { ko = "{1}초 동안 성기사를 헌신의 기운으로 감싸 근접 전투력이 {2}만큼, 근접 공격 속도가 40%만큼 증가합니다.", zhCN = "十字军的灵魂充满圣骑士的体内，持续{1}秒，使其近战攻击强度提高{2}点。", zhTW = "十字軍的靈魂充滿聖騎士的體內，持續{1}秒，使其近戰攻擊強度提高{2}。" },
	["fills the paladin with the spirit of a crusader for # sec, granting # melee attack power. the paladin also attacks #% faster, but deals less damage with each attack. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 성기사를 헌신의 기운으로 감싸 근접 전투력이 {2}만큼, 근접 공격 속도가 {3}%만큼 증가합니다. 하지만 각 공격의 피해는 약간 저하됩니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "十字军的灵魂充满圣骑士的体内，持续{1}秒，使其近战攻击强度提高{2}点。圣骑士的攻击速度也提高{3}%，但攻击时所造成的伤害会降低。圣骑士在同一时间内只能激活一种圣印。", zhTW = "十字軍的靈魂充滿聖騎士的體內，持續{1}秒，使其近戰攻擊強度提高{2}。聖騎士的攻擊速度也提高{3}%，但攻擊時所造成的傷害會降低。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills the paladin with the spirit of justice for # sec, giving each melee attack a chance to stun for # sec"] = { ko = "{1}초 동안 성기사를 심판의 기운으로 감싸 매 근접 공격 시 일정 확률로 {2}초 동안 적을 기절시킵니다.", zhCN = "公正之魂充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率令目标昏迷{2}秒。", zhTW = "公正之魂充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率令目標昏迷{2}秒。" },
	["fills the paladin with the spirit of justice for # sec, giving each melee attack a chance to stun for # sec. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 성기사를 심판의 기운으로 감싸 매 근접 공격 시 일정 확률로 {2}초 동안 적을 기절시킵니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "公正之魂充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率令目标昏迷{2}秒。圣骑士在同一时间内只能激活一种圣印。", zhTW = "公正之魂充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率令目標昏迷{2}秒。聖騎士在同一時間內只能啟動一種聖印。" },
	["fills you with divine fury for # sec, causing melee attacks to deal an additional # holy damage"] = { ko = "{1}초 동안 자신을 신성한 격노로 채워 근접 공격 시 {2}의 신성 피해를 추가로 입힙니다." },
	["fills you with divine fury for # sec, causing melee attacks to deal an additional # holy damage. while a shield is equipped, each attack also grants an absorb shield equal to #% of the holy damage dealt. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 자신을 신성한 격노로 채워 근접 공격 시 {2}의 신성 피해를 추가로 입힙니다. 방패를 장착하고 있으면 공격할 때마다 입힌 신성 피해의 {3}%만큼 피해를 흡수하는 보호막도 얻습니다. 성기사마다 하나의 문장만 효력을 발휘합니다." },
	["fills you with divine fury for # sec, causing melee attacks to inflict an additional # holy damage"] = { ko = "{1}초 동안 자신을 신성한 격노로 채워 근접 공격 시 {2}의 신성 피해를 추가로 입힙니다." },
	["fills you with divine fury for # sec, causing melee attacks to inflict an additional # holy damage. while a shield is equipped, each attack also grants an absorb shield equal to #% of the holy damage dealt. only one seal can be active on the paladin at any one time"] = { ko = "{1}초 동안 자신을 신성한 격노로 채워 근접 공격 시 {2}의 신성 피해를 추가로 입힙니다. 방패를 장착하고 있으면 공격할 때마다 입힌 신성 피해의 {3}%만큼 피해를 흡수하는 보호막도 얻습니다. 성기사마다 하나의 문장만 효력을 발휘합니다." },
	["finishes the remaining cooldown on all your other frost spells"] = { ko = "다른 모든 냉기 주문의 남은 재사용 대기시간이 초기화됩니다.", zhCN = "结束你所有其他冰霜法术的剩余冷却时间。", zhTW = "立即結束你其他所有冰霜法術的剩餘冷卻時間。" },
	["finishes the remaining cooldown on your judgement ability and reduces the mana cost of your next judgement by #%"] = { ko = "심판의 남은 재사용 대기시간을 초기화하고, 다음 심판의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "结束审判的剩余冷却时间，并使你下一次审判消耗的法力值降低{1}%。", zhTW = "立即結束你審判技能的剩餘冷卻時間，並使你下一個審判的法力消耗降低{1}%。" },
	["finishing move that causes damage over time"] = { ko = "마무리 일격을 시도하여 적에게 지속적인 피해를 입힙니다.", zhCN = "终结技，使目标在一段时间内受到持续伤害。", zhTW = "終結技，使目標在一段時間內受到持續的傷害。" },
	["finishing move that causes damage over time, increased by your attack power"] = { zhCN = "终结技，造成持续伤害，伤害受攻击强度加成。", zhTW = "終結技，使目標在一段時間內受到持續的傷害，以攻擊強度來提升。" },
	["finishing move that causes damage over time, increased by your attack power. lasts longer per combo point:"] = { ko = "마무리 일격을 시도하여 적에게 지속 피해를 입힙니다. 입히는 피해는 전투력에 비례합니다. 연계 점수에 따라 지속시간이 증가합니다.", zhCN = "终结技，造成持续伤害，伤害受攻击强度加成。每个连击点数可延长持续时间：", zhTW = "終結技，使目標在一段時間內受到持續的傷害，以攻擊強度來提升。根據連擊點數決定持續時間：" },
	["finishing move that causes damage over time. damage increases per combo point and by your attack power:"] = { ko = "마무리 일격을 시도하여 적에게 지속적인 피해를 입힙니다. 연계 점수와 전투력에 따라 피해가 증가합니다:", zhCN = "终结技，使目标在一段时间内受到持续伤害。伤害将根据连击点数和攻击强度决定：", zhTW = "終結技，使目標在一段時間內受到持續的傷害。根據連擊點數和你的攻擊強度決定傷害量：" },
	["finishing move that causes damage per combo point and converts each extra point of energy into # additional damage"] = { ko = "적에게 마무리 일격을 날리고 남은 기력을 전환하여 {1}의 추가 피해를 입힙니다.", zhTW = "終結技，根據連擊點數決定所造成的傷害，並將每一點額外的能量點數轉化為{1}點額外傷害。" },
	["finishing move that causes damage per combo point and converts each extra point of energy into # additional damage. damage is increased by your attack power"] = { ko = "적에게 마무리 일격을 날리고 남은 기력을 전환하여 {1}의 추가 피해를 입힙니다. 입히는 피해는 전투력에 따라 증가합니다.", zhCN = "终结技，根据连击点数决定所造成的伤害，并将每一点额外的能量点数转化为{1}点额外伤害，该伤害会受到攻击强度的加成影响：", zhTW = "終結技，根據連擊點數決定所造成的傷害，並將每一點額外的能量點數轉化為{1}點額外傷害。以你的攻擊強度來提升傷害：" },
	["finishing move that causes damage per combo point, increased by attack power:"] = { ko = "적에게 마무리 일격을 날립니다. 연계 점수와 전투력에 따라 피해가 증가합니다.", zhCN = "终结技，根据连击点数造成伤害，伤害受攻击强度加成：", zhTW = "終結技，根據連擊點數決定造成的傷害，並根據攻擊強度提高傷害：" },
	["finishing move that exposes the target for # sec, reducing armor per combo point:"] = { ko = "마무리 일격으로 {1}초 동안 대상의 빈틈을 드러내, 연계 점수에 따라 방어도를 감소시킵니다." },
	["finishing move that increases melee attack speed by #%"] = { ko = "마무리 일격을 시도하여 근접 공격 속도를 {1}%만큼 증가시킵니다.", zhCN = "终结技，使近战攻击速度提高{1}%。", zhTW = "終結技，使你的近戰攻擊速度提高{1}%。" },
	["finishing move that increases melee attack speed by #%. lasts longer per combo point:"] = { ko = "마무리 일격을 시도하여 근접 공격 속도를 {1}%만큼 증가시킵니다. 연계 점수에 따라 지속시간이 증가합니다.", zhCN = "终结技，使近战攻击速度提高{1}%。根据连击点数的数量决定效果持续时间：", zhTW = "終結技，使你的近戰攻擊速度提高{1}%。根據連擊點數的數量決定效果持續時間：" },
	["finishing move that increases the damage of your poisons by #% and your chance to apply poisons by #%"] = { ko = "마무리 일격을 날려 독이 입히는 피해를 {1}%만큼, 독을 부여할 확률을 {2}%만큼 증가시킵니다.", zhCN = "终结技，使你的毒药伤害提高{1}%，施加毒药的几率提高{2}%。", zhTW = "終結技，使你的毒藥傷害提高{1}%，施加毒藥的機率提高{2}%。" },
	["finishing move that increases the damage of your poisons by #% and your chance to apply poisons by #%. lasts longer per combo point:"] = { ko = "마무리 일격을 날려 독이 입히는 피해를 {1}%만큼, 독을 부여할 확률을 {2}%만큼 증가시킵니다. 연계 점수에 따라 지속시간이 증가합니다.", zhCN = "终结技，使你的毒药伤害提高{1}%，施加毒药的几率提高{2}%。持续时间随连击点数增加：", zhTW = "終結技，使你的毒藥傷害提高{1}%，施加毒藥的機率提高{2}%。持續時間隨連擊點數增加：" },
	["finishing move that stuns the target"] = { ko = "적에게 마무리 일격을 날려 기절시킵니다.", zhCN = "终结技，使目标昏迷。", zhTW = "終結技，使目標昏迷。" },
	["finishing move that stuns the target. lasts longer per combo point:"] = { ko = "적에게 마무리 일격을 날려 기절시킵니다. 연계 포인트 당 다음 시간만큼 지속됩니다.", zhCN = "终结技，使目标昏迷。根据连击点数的数量决定效果持续时间：", zhTW = "終結技，使目標昏迷。根據連擊點數的數量決定效果持續時間：" },
	["fire damage taken increased by #%"] = { ko = "받는 화염 피해 {1}%만큼 증가", zhCN = "受到的火焰伤害提高{1}%。", zhTW = "受到的火焰傷害提高{1}%。" },
	["fires several missiles, hitting # targets"] = { ko = "여러 발의 탄환을 동시에 쏴서 {1}명의 대상을 적중시킵니다.", zhCN = "连续射出弹药，击中{1}个目标。", zhTW = "射出數發彈矢，命中{1}個目標。" },
	["fires several missiles, hitting # targets. multi-shot shares its cooldown with aimed shot"] = { ko = "여러 발의 탄환을 동시에 쏴서 {1}명의 대상을 적중시킵니다. 일제 사격은 조준 사격과 재사용 대기시간을 공유합니다.", zhCN = "连续射出弹药，击中{1}个目标。多重射击与瞄准射击共享冷却时间。", zhTW = "射出數發彈矢，命中{1}個目標。多重射擊與瞄準射擊共用冷卻時間。" },
	["for # min"] = { ko = "{1}분 동안 지속됩니다." },
	["for each mana drained in this way, the target takes # shadow damage"] = { ko = "대상은 소진된 마나의 절반만큼 암흑 피해를 입습니다." },
	["for the duration, #% of your mana regeneration will continue while casting"] = { ko = "이 동안은 주문 시전 중 마나가 평소의 {1}%의 속도로 회복됩니다.", zhCN = "在此期间，你在施法时仍可保持{1}%的正常法力回复速度。", zhTW = "在此期間，你在施法時仍可保持{1}%的正常法力回覆速度。" },
	["for the next # sec, your spells deal #% more damage while costing #% more mana to cast"] = { ko = "다음 {1}초 동안 주문 시전 시 {2}%의 마나를 추가로 소모하여 {3}%의 추가 피해를 입힙니다.", zhCN = "在接下来的{1}秒内，你的法术造成的伤害提高{2}%，但消耗的法力值也提高{3}%。", zhTW = "在接下來的{1}秒內，你的法術會造成{2}%的額外傷害，但同時也要消耗{3}%的額外法力才能施放。" },
	["forces all nearby enemies to focus attacks on you for # sec"] = { ko = "{1}초 동안 주위의 모든 적이 자신에게 공격을 집중하도록 만듭니다.", zhCN = "嘲讽附近所有的敌人，持续{1}秒。", zhTW = "嘲諷附近所有的敵人，持續{1}秒。" },
	["forces all nearby enemies within # yards to focus attacks on you for # sec"] = { ko = "{2}초 동안 주위 {1}미터 반경 내에 있는 모든 적이 자신에게 공격을 집중하도록 만듭니다.", zhCN = "嘲讽附近半径{1}码范围内的所有敌人，强制它们攻击你，持续{2}秒。", zhTW = "迫使周圍{1}碼範圍內的敵人集中攻擊你，持續{2}秒。" },
	["forces the enemy target to sleep for up to # sec"] = { ko = "적을 최대 {1}초 동안 잠들게 합니다." },
	["forces the enemy target to sleep for up to # sec. any damage will awaken the target. only one target can be forced to hibernate at a time. only works on beasts and dragonkin"] = { ko = "적을 최대 {1}초 동안 잠들게 합니다. 대상이 피해를 입으면 깨어납니다. 동시에 한 대상만 잠들게 할 수 있습니다. 야수와 용족에게만 사용할 수 있습니다.", zhCN = "使敌方目标沉睡，最多持续{1}秒，任何伤害都会唤醒被催眠的目标。在同一时间内只能强制使一个目标进入休眠状态，只对野兽和龙类有效。", zhTW = "使敵方目標沉睡，最多持續{1}秒，任何傷害都會喚醒被催眠的目標。在同一時間內只能強制使一個目標進入休眠狀態，只對野獸和龍類有效。" },
	["forces the target to speak in demonic, increasing the casting time of all spells by #%"] = { ko = "대상을 강제로 악마어로 말하도록 하여 모든 주문의 시전 시간을 {1}%만큼 증가시킵니다.", zhCN = "强迫目标使用恶魔语，使其所有法术的施放时间延长{1}%。", zhTW = "強迫目標使用惡魔語，使其所有法術的施法時間延長{1}%。" },
	["forces the target to speak in demonic, increasing the casting time of all spells by #%. only one curse per warlock can be active on any one target. lasts # sec"] = { ko = "대상을 강제로 악마어로 말하도록 하여 모든 주문의 시전 시간을 {1}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다. {2}초 동안 지속됩니다.", zhCN = "强迫目标使用恶魔语，使其所有法术的施放时间延长{1}%。每个术士在任一目标身上只能维持一种诅咒。持续{2}秒。", zhTW = "強迫目標使用惡魔語，使其所有法術的施法時間延長{1}%。每個術士只能對同一個目標施加一種詛咒。持續{2}秒。" },
	["gain # doses of venomous blood"] = { ko = "맹독성 피 {1}중첩이 부여됩니다.", zhCN = "获得{1}层毒血效果。", zhTW = "獲得{1}層毒血效果。" },
	["gain # doses of venomous blood. whenever you suffer bleed damage, one dose is spread to a nearby enemy within # yds. lasts up to # sec"] = { ko = "맹독성 피 {1}중첩이 부여됩니다. 출혈 피해를 받을 때마다 {2}미터 내의 주위 적에게 맹독성 피를 1회 살포합니다. 최대 {3}초 동안 지속됩니다.", zhCN = "获得{1}层毒血效果。每当你受到流血伤害时，就会有一层毒血传播给{2}码内的一名附近敌人。最多持续{3}秒。", zhTW = "獲得{1}層毒血效果。每當你受到流血傷害時，會將一層效果濺射至附近{2}碼範圍內的一個敵人。最多持續{3}秒。" },
	["garrote the enemy, causing # damage over # sec, increased by your attack power"] = { zhCN = "猛勒敌人的脖子，在{2}秒内对其造成总计{1}点伤害，该伤害会受到攻击强度的加成影响。" },
	["garrote the enemy, causing # damage over # sec, increased by your attack power. must be stealthed and behind the target. awards # combo point"] = { ko = "적의 목을 졸라 {2}초에 걸쳐 총 {1}의 피해를 입힙니다. 총 피해는 전투력에 따라 증가합니다. 적의 배후에서 은신 상태로 사용해야 합니다. {3}의 연계 포인트가 주어집니다.", zhCN = "猛勒敌人的脖子，在{2}秒内对其造成总计{1}点伤害，该伤害会受到攻击强度的加成影响。必须在潜行状态下从目标背后发动。奖励{3}个连击点数。", zhTW = "猛勒敵人的脖子，在{2}秒內對其造成總計{1}點傷害，以你的攻擊強度來提升，必須在潛行狀態下從目標背後發動。獎勵{3}個連擊點數。" },
	["gather information about the target beast"] = { ko = "대상 야수의 정보를 수집합니다.", zhCN = "收集目标野兽的相关资料。", zhTW = "收集目標野獸的相關資料。" },
	["gather information about the target beast. the tooltip will display damage, health, armor, any special resistances, and diet"] = { ko = "대상 야수의 정보를 수집합니다. 대상에 마우스 커서를 올려 놓으면 공격력과 생명력, 방어도, 저항력, 먹이의 종류가 표시됩니다.", zhCN = "收集目标野兽的相关资料。信息栏里会显示出该野兽的伤害、生命值、护甲值和魔法抗性，以及它通常吃的食物。", zhTW = "收集目標野獸的相關資料。資訊欄裡會顯示出該野獸的傷害、生命力、護甲值和魔法抗性，以及它通常吃的食物。" },
	["generates # rage at the cost of health, and then generates an additional # rage over # sec"] = { ko = "생명력을 대가로 {1}의 분노를 생성한 후 {2}초에 걸쳐 {3}의 추가 분노를 생성합니다." },
	["generates # rage every # sec while in combat, and reduces rage loss while out of combat by #%"] = { ko = "전투 중 {2}초마다 {1}의 분노를 생성합니다. 또한 전투 중이 아닐 때 분노 손실이 {3}%만큼 감소합니다.", zhCN = "在战斗中每{2}秒获得{1}点怒气，并使脱战怒气衰减降低{3}%。", zhTW = "在戰鬥中，每{2}秒產生{1}點怒氣，脫離戰鬥後，失去的怒氣降低{3}%。" },
	["generates a high amount of threat"] = { ko = "대상에 대한 위협 수준이 크게 증가합니다.", zhCN = "产生很高的威胁值。", zhTW = "產生很高的威脅值。" },
	["generates high threat"] = { ko = "위협 수준이 크게 증가합니다.", zhCN = "产生大量威胁值。", zhTW = "產生大量威脅值。" },
	["generates reduced threat"] = { ko = "위협 수준 생성량이 감소합니다.", zhCN = "产生的威胁较低。", zhTW = "產生的威脅值降低。" },
	["gives # additional armor to party members within # yards"] = { ko = "주위 {2}미터 반경에 있는 파티원의 방어도가 {1}만큼 상승합니다.", zhCN = "使半径{2}码范围内的所有小队成员获得{1}点额外的护甲。", zhTW = "使半徑{2}碼範圍內的所有小隊成員獲得{1}點額外的護甲。" },
	["gives # additional armor to party members within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "주위 {2}미터 반경에 있는 파티원의 방어도가 {1}만큼 상승합니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使半径{2}码范围内的所有小队成员获得{1}点额外的护甲。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。", zhTW = "使半徑{2}碼範圍內的所有小隊成員獲得{1}點額外的護甲。每個聖騎士在同一時間內只能開啟一種光環，且同類光環的效果無法疊加。" },
	["gives # additional fire resistance to all party and raid members within # yards"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 화염 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的火焰抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的火焰抗性提高額外{2}點。" },
	["gives # additional fire resistance to all party and raid members within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 화염 저항력을 {2}만큼 증가시킵니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使{1}码内所有队伍和团队成员的火焰抗性提高{2}点。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的火焰抗性提高額外{2}點。每個聖騎士在同一時間內只能開啟一種光環。" },
	["gives # additional frost resistance to all party and raid members within # yards"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的冰霜抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的冰霜抗性提高額外{2}點。" },
	["gives # additional frost resistance to all party and raid members within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 {2}만큼 증가시킵니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使{1}码内所有队伍和团队成员的冰霜抗性提高{2}点。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的冰霜抗性提高額外{2}點。每個聖騎士在同一時間內只能開啟一種光環。" },
	["gives # additional shadow resistance to all party and raid members within # yards"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 암흑 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的暗影抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的暗影抗性提高額外{2}點。" },
	["gives # additional shadow resistance to all party and raid members within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 암흑 저항력을 {2}만큼 증가시킵니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使{1}码内所有队伍和团队成员的暗影抗性提高{2}点。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的暗影抗性提高額外{2}點。每個聖騎士在同一時間內只能開啟一種光環。" },
	["gives # health to the caster's pet every second for # sec as long as the caster channels"] = { ko = "시전자가 정신을 집중하는 동안 {2}초 동안 1초마다 {1}의 생명력을 시전자의 소환수에게 이전합니다.", zhCN = "只要施法者持续引导，就会每秒为施法者的宠物恢复{1}点生命值，持续{2}秒。", zhTW = "只要施法者保持著引導法術的狀態，就會每秒將{1}點生命力轉移給施法者的寵物，最多持續{2}秒。" },
	["gives # health to the caster's pet every second for # sec as long as the caster channels. generates reduced threat"] = { ko = "시전자가 정신을 집중하는 동안 {2}초 동안 1초마다 {1}의 생명력을 시전자의 소환수에게 이전합니다. 위협 수준 생성량이 감소합니다.", zhCN = "只要施法者持续引导，就会每秒为施法者的宠物恢复{1}点生命值，持续{2}秒。产生的威胁较低。", zhTW = "只要施法者保持著引導法術的狀態，就會每秒將{1}點生命力轉移給施法者的寵物，最多持續{2}秒。產生的威脅值降低。" },
	["gives a #% chance of ignoring spell interruption when damaged to all party members within # yards"] = { ko = "{2}미터 반경 내의 파티원이 주문을 시전할 때 {1}%의 확률로 피해로 인한 방해를 받지 않도록 합니다.", zhCN = "使半径{2}码范围内的所有队友在施法时都有{1}%的几率不会因为受到伤害而被打断。", zhTW = "使半徑{2}碼範圍內的所有隊友在施法時都有{1}%的機率不會因為受到傷害而被打斷。" },
	["gives a #% chance of ignoring spell interruption when damaged to all party members within # yards. players may only have one aura on them per paladin at any one time"] = { ko = "{2}미터 반경 내의 파티원이 주문을 시전할 때 {1}%의 확률로 피해로 인한 방해를 받지 않도록 합니다. 성기사마다 하나의 대상에게 하나의 오라만 효력을 발휘합니다.", zhCN = "使半径{2}码范围内的所有队友在施法时都有{1}%的几率不会因为受到伤害而被打断。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。", zhTW = "使半徑{2}碼範圍內的所有隊友在施法時都有{1}%的機率不會因為受到傷害而被打斷。每個聖騎士在同一時間內只能開啟一種光環，且同類光環的效果無法疊加。" },
	["gives a #% chance to remove all movement impairing effects when you activate your sprint ability"] = { ko = "전력 질주 사용 시 {1}%의 확률로 모든 이동 방해 효과에서 벗어납니다.", zhCN = "使你在启动疾跑技能时有{1}%的几率移除所有移动限制效果。", zhTW = "有{1}%的機率使你在啟動疾跑後移除所有限制移動的效果。" },
	["gives a chance to parry enemy melee attacks"] = { ko = "일정 확률로 적의 근접 공격을 무기로 막아냅니다.", zhCN = "有一定几率招架敌人的近战攻击。", zhTW = "有一定機率招架敵人的近戰攻擊。" },
	["gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by #% while rockbiter weapon is not active, and increases all threat generated by #% while rockbiter weapon is active"] = { ko = "일정 확률로 적의 근접 공격을 무기로 막아냅니다. 대지의 무기가 활성화되지 않은 동안에는 공격으로 생성되는 모든 위협 수준이 {1}%만큼 감소하고, 활성화된 동안에는 모든 위협 수준 생성량이 {2}%만큼 증가합니다.", zhCN = "有几率招架敌人的近战攻击。未激活石化武器时，你的攻击产生的威胁值降低{1}%；激活石化武器时，产生的所有威胁值提高{2}%。", zhTW = "有一定機率招架敵人的近戰攻擊，在石化武器未生效時，你的攻擊產生的所有威脅值降低{1}%，而在石化武器生效期間，產生的所有威脅值提高{2}%。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of kings, increasing total stats by #% for # hr"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高{1}%，持续{2}小时。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效王者祝福的效果，使其所有屬性提高{1}%，持續{2}小時。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of kings, increasing total stats by #% for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效王者祝福的效果，使其所有屬性提高{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of light, increasing the effects of holy light spells used on the target by up to # and the effect flash of light spells used on the target by up to # lasts # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 빛의 축복을 걸어 {3}시간 동안 성스러운 빛의 효과를 최대 {1}만큼, 빛의 섬광의 효과를 최대 115만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效光明祝福的效果，使圣光术为其恢复的生命值提高{1}点，圣光闪现为其恢复的生命值提高115点，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效光明祝福的效果，使聖光術為其恢復的生命力提高{1}點，聖光閃現為其恢復的生命力提高115點，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of might, increasing melee attack power by # for # hr"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效力量祝福的效果，使其近战攻击强度提高{1}，持续{2}小时。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效力量祝福的效果，使其近戰攻擊強度提高{1}，持續{2}小時。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of might, increasing melee attack power by # for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效力量祝福的效果，使其近战攻击强度提高{1}，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效力量祝福的效果，使其近戰攻擊強度提高{1}，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of salvation, reducing the amount of all threat generated by #% for # hr"] = { zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效拯救祝福的效果，令其对怪物造成的威胁降低{1}%，持续{2}小时。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效拯救祝福的效果，令其對怪物造成的威脅降低{1}%，持續{2}小時。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of salvation, reducing the amount of all threat generated by #% for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 구원의 축복을 걸어주어 모든 행동의 위협 수준을 {1}%만큼 감소시킵니다. {2}시간 동안 지속됩니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效拯救祝福的效果，令其对怪物造成的威胁降低{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效拯救祝福的效果，令其對怪物造成的威脅降低{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of sanctuary, reducing damage dealt from all sources by up to # for # min"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 성역의 축복을 걸어 {2}분 동안 모든 계열로부터 받는 피해를 최대 {1}까지 감소시킵니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效庇护祝福的效果，使其所受到的所有类型的伤害都减少最多{1}点，持续{2}分钟。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效庇護祝福的效果，使其所受到的所有類型的傷害都減少最多{1}點，持續{2}分鐘。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of sanctuary, reducing damage dealt from all sources by up to # for # min. in addition, when the target blocks a melee attack the attacker will take # holy damage. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 성역의 축복을 걸어 {2}분 동안 모든 계열로부터 받는 피해를 최대 {1}까지 감소시킵니다. 추가로 근접 공격을 방어할 경우 공격자에게 {3}의 신성 피해를 입힙니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效庇护祝福的效果，使其所受到的所有类型的伤害都减少最多{1}点，持续{2}分钟。另外，当目标格挡了近战攻击之后，攻击者会受到{3}点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效庇護祝福的效果，使其所受到的所有類型的傷害都減少最多{1}點，持續{2}分鐘。另外，當目標格擋了近戰攻擊之後，攻擊者會受到{3}點神聖傷害。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of wisdom, restoring # mana every # sec for # hr"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 지혜의 축복을 걸어 {3}시간 동안 매 {2}초마다 {1}의 마나를 회복시킵니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效智慧祝福的效果，每{2}秒回复{1}点法力值，持续{3}小时。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效智慧祝福的效果，每{2}秒恢復{1}點法力，持續{3}小時。" },
	["gives all members of the raid or group that share the same class with the target the greater blessing of wisdom, restoring # mana every # sec for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 지혜의 축복을 걸어 {3}시간 동안 매 {2}초마다 {1}의 마나를 회복시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效智慧祝福的效果，每{2}秒回复{1}点法力值，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效智慧祝福的效果，每{2}秒恢復{1}點法力，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["gives invisibility for # sec"] = { ko = "{1}초 동안 투명화를 부여합니다.", zhCN = "隐形，持续{1}秒。", zhTW = "賦予隱形，持續{1}秒。" },
	["gives the gift of the wild to all party and raid members, increasing armor by #, all attributes by # and all resistances by # for # hr"] = { ko = "모든 파티원과 공격대원에게 야생의 선물을 선사하여 {4}시간 동안 방어도를 {1}만큼, 모든 능력치를 {2}만큼, 모든 저항력을 {3}만큼 증가시킵니다.", zhCN = "使小队和团队中的所有成员获得野性赐福的效果，护甲值提高{1}点，所有属性提高{2}点，所有抗性提高{3}点。持续{4}小时。", zhTW = "使所有隊伍和團隊成員獲得野性賜福的效果，護甲值提高{1}點，所有屬性提高{2}點，所有抗性提高{3}點。持續{4}小時。" },
	["gives the paladin a chance to deal additional holy damage equal to #% of normal weapon damage"] = { zhCN = "使圣骑士在攻击时有一定几率对目标造成与攻击伤害的{1}%等量的神圣伤害。", zhTW = "使聖騎士在攻擊時有一定機率對目標造成與普通武器傷害{1}%等量的神聖傷害。" },
	["gives the paladin a chance to deal additional holy damage equal to #% of normal weapon damage. only one seal can be active on the paladin at any one time. lasts # sec"] = { ko = "{2}초 동안 성기사를 지휘의 기운으로 감싸 일정 확률로 무기 피해의 {1}%만큼에 해당하는 추가 신성 피해를 입힙니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "使圣骑士在攻击时有一定几率对目标造成与攻击伤害的{1}%等量的神圣伤害。圣骑士在同一时间内只能激活一种圣印。持续{2}秒。", zhTW = "使聖騎士在攻擊時有一定機率對目標造成與普通武器傷害{1}%等量的神聖傷害。聖騎士在同一時間內只能啟動一種聖印。命令聖印可持續{2}秒。" },
	["gives you a #% chance of entering a clearcasting state after any damage spell hits a target"] = { ko = "공격 마법이 대상에 적중하면 {1}%의 확률로 번뜩임 상태를 취합니다.", zhCN = "使你有{1}%的几率在任何伤害法术命中目标之后进入节能施法状态。", zhTW = "使你有{1}%的機率在任何傷害法術命中目標之後進入節能施法狀態。" },
	["gives you a #% chance of entering a clearcasting state after any damage spell hits a target. the clearcasting state reduces the mana cost of your next damage spell by #%"] = { ko = "공격 마법이 대상에 적중하면 {1}%의 확률로 번뜩임 상태를 취합니다. 번뜩임 상태에서는 다음 공격 주문의 마나 소비량이 {2}%만큼 감소합니다.", zhCN = "使你有{1}%的几率在任何伤害法术命中目标之后进入节能施法状态。节能施法状态可以使你的下一个伤害性法术所消耗的法力值减少{2}%。", zhTW = "使你有{1}%的機率在任何傷害法術命中目標之後進入節能施法狀態。節能施法狀態可以使你的下一個傷害性法術所消耗的法力減少{2}%。" },
	["gives you a #% chance to add a combo point to your target after dodging one of their attacks or fully resisting one of their spells"] = { ko = "대상의 공격을 회피하거나 대상의 주문을 완전히 저항했을 때 {1}%의 확률로 그 대상에 대한 연계 포인트 1점이 추가됩니다.", zhCN = "使你在躲闪攻击或完全抵抗法术后有{1}%的几率为目标增加一个连击点数。", zhTW = "使你在躲閃攻擊或完全抵抗法術後有{1}%的機率為目標增加一個連擊點數。" },
	["gives you a #% chance to add an additional combo point to your target when using your ambush, garrote, or cheap shot ability"] = { ko = "매복, 목조르기, 비열한 습격 사용 시 {1}%의 확률로 대상에 대한 연계 포인트 1점이 추가됩니다.", zhCN = "使你有{1}%的几率在使用伏击、绞喉或偷袭技能后获得1个额外的连击点数。", zhTW = "使你有{1}%的機率在使用伏擊、絞喉或偷襲技能後獲得1個額外的連擊點數。" },
	["gives you a #% chance to avoid interruption caused by damage while casting any healing spell"] = { ko = "모든 치유 계열 주문 시전 시 {1}%의 확률로 피해로 인한 주문 시전 방해를 받지 않습니다.", zhCN = "使你在施放任意治疗法术的时候有{1}%的几率避免因受到伤害而被打断。", zhTW = "使你在施放治療法術的時候有{1}%的機率不會因為受到傷害而中斷施法。" },
	["gives you a #% chance to avoid interruption caused by damage while casting any spell"] = { ko = "주문 시전 시 {1}%의 확률로 피해로 인한 주문 시전 방해를 받지 않습니다.", zhCN = "使你在施放任何法术时有{1}%的几率避免因受到伤害而被打断。", zhTW = "使你有{1}%的機率在施放法術的時候不會因為受到傷害而中斷施法。" },
	["gives you a #% chance to avoid interruption caused by damage while casting arcane and nature spells"] = { ko = "비전 및 자연 주문 시전 시 {1}%의 확률로 피해를 입어도 마법 시전 방해를 받지 않습니다.", zhCN = "使你在施放奥术和自然法术时有{1}%的几率不会因受到伤害而被打断。", zhTW = "使你有{1}%的機率在施放秘法和自然法術時不會因受到傷害而中斷施法。" },
	["gives you a #% chance to avoid interruption caused by damage while channeling arcane missiles and a #% chance while casting arcane blast"] = { ko = "신비한 화살에 정신을 집중하는 동안 {1}%의 확률로, 비전 작렬을 시전할 때 {2}%의 확률로 피해를 입어도 마법 시전 방해를 받지 않습니다.", zhCN = "使你在引导奥术飞弹时有{1}%的几率不会因受到伤害而被打断，在施放奥术冲击时有{2}%的几率不会因受到伤害而被打断。", zhTW = "使你有{1}%的機率在引導秘法飛彈時不會因受到傷害而中斷施法，並且有{2}%的機率在施放秘法衝擊時不會因受到傷害而中斷施法。" },
	["gives you a #% chance to avoid interruption caused by damage while channeling or casting your drain life, drain mana, drain soul, or wrack spells"] = { ko = "생명력 흡수, 마나 흡수, 영혼 흡수, 파멸에 정신을 집중하거나 시전 시 {1}%의 확률로 마법 시전 방해를 받지 않습니다.", zhCN = "使你在引导或施放吸取生命、吸取法力、吸取灵魂或折磨时有{1}%的几率避免因受到伤害而被打断。", zhTW = "使你有{1}%的機率在引導或施放吸取生命、吸取法力、吸取靈魂或毀壞法術時不會因為受到傷害而中斷施法。" },
	["gives you a #% chance to deal #% increased physical damage for # sec after being the victim of any damaging attack"] = { ko = "공격으로 피해를 받으면 {1}%의 확률로 {3}초 동안 물리 공격력이 {2}%만큼 증가합니다.", zhCN = "使你在遭受任何伤害性攻击后，有{1}%的几率使你造成的物理伤害提高{2}%，持续{3}秒。", zhTW = "在受到任何傷害性攻擊之後，你有{1}%的機率使造成的物理傷害提高{2}%，持續{3}秒。" },
	["gives you a #% chance to enter a clearcasting state after casting any fire, frost, or nature damage spell"] = { ko = "화염, 냉기, 자연 계열 공격 주문을 시전한 이후 {1}%의 확률로 정신 집중 상태를 취하게 됩니다.", zhCN = "使你有{1}%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。", zhTW = "使你有{1}%的機率在施放任何火焰、冰霜或自然系的傷害性法術之後進入節能施法狀態。" },
	["gives you a #% chance to enter a clearcasting state after casting any fire, frost, or nature damage spell. the clearcasting state reduces the mana cost of your next damage spell by #%"] = { ko = "화염, 냉기, 자연 계열 공격 주문을 시전한 이후 {1}%의 확률로 정신 집중 상태를 취하게 됩니다. 정신 집중 상태에서는 다음 공격 주문의 마나 소비량이 {2}%만큼 감소됩니다.", zhCN = "使你有{1}%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。这个状态可以使你的下一个伤害性法术所消耗的法力值减少{2}%。", zhTW = "使你有{1}%的機率在施放任何火焰、冰霜或自然系的傷害性法術之後進入節能施法狀態。這個狀態可以使你的下一個傷害性法術所消耗的法力降低{2}%。" },
	["gives you a #% chance to gain # rage when you shapeshift into bear form or dire bear form"] = { ko = "곰 변신 또는 광포한 곰 변신 시 {1}%의 확률로 {2}의 분노를 생성합니다.", zhCN = "使你有{1}%的几率在变身为熊形态或巨熊形态时获得{2}点怒气。", zhTW = "使你有{1}%的機率在變身為熊形態或巨熊形態時獲得{2}點怒氣。" },
	["gives you a #% chance to gain # rage when you shapeshift into bear form or dire bear form. when you shift into cat form, you will regain #% of the energy you had when you were last in cat form, plus # energy for each second you spent not in bear form, cat form, or dire bear form, up to a maximum of # energy"] = { ko = "곰 변신 또는 광포한 곰 변신 시 {1}%의 확률로 {2}의 분노를 생성합니다. 또한 표범 변신 시 지난 표범 변신 상태일 때 보유했던 기력의 {3}%를 다시 회복하며, 추가로 곰 변신이나 표범 변신, 광포한 곰 변신 상태가 아니었던 시간 1초당 기력을 {4}만큼, 최대 {5}만큼 생성합니다.", zhCN = "使你有{1}%的几率在变身为熊形态或巨熊形态时获得{2}点怒气。当你变身为猎豹形态时，将恢复上次处于猎豹形态时所拥有能量的{3}%，外加你在未处于熊形态、猎豹形态或巨熊形态的每秒{4}点能量，最多{5}点能量。", zhTW = "在你進入熊形態和巨熊形態時有{1}%的機率獲得{2}點怒氣，在進入獵豹形態時，重新獲得上次處於獵豹形態時擁有的{3}%%能量，而且根據在非熊形態、獵豹形態或巨熊形態下的持續秒數，每秒追加{4}點能量，最多獲得{5}點能量。" },
	["gives you a #% chance to gain an additional # rage any time you get a critical strike while in bear form or dire bear form"] = { ko = "곰 변신 또는 광포한 곰 변신 상태에서 치명타 공격이 적중할 때마다 {1}%의 확률로 {2}의 추가 분노를 생성합니다.", zhCN = "使你在熊形态或巨熊形态下造成爆击时，有{1}%的几率额外获得{2}点怒气。", zhTW = "使你在熊形態或巨熊形態下對目標造成致命一擊後，有{1}%的機率額外獲得{2}點怒氣。" },
	["gives you a #% chance to gain an additional # rage any time you get a critical strike while in bear form or dire bear form. in addition, your non-periodic critical strikes from cat form abilities that generate combo points have a #% chance to add an additional combo point"] = { ko = "곰 변신 또는 광포한 곰 변신 상태에서 치명타 공격이 적중할 때마다 {1}%의 확률로 {2}의 추가 분노를 생성합니다. 또한 연계 점수를 생성하는 표범 변신 능력이 비주기적인 치명타 및 극대화 효과를 발휘하면 {3}%의 확률로 추가 연계 점수를 생성합니다.", zhCN = "使你在熊形态或巨熊形态下造成爆击时，有{1}%的几率额外获得{2}点怒气。此外，你的猎豹形态下可产生连击点数的技能的非周期性爆击有{3}%的几率额外增加一个连击点数。", zhTW = "使你在熊形態或巨熊形態下對目標造成致命一擊後，有{1}%的機率額外獲得{2}點怒氣。此外，而在獵豹形態時可產生連擊點數的非週期性效果造成致命一擊後，有{3}%的機率再獲取一個額外的連擊點數。" },
	["gives you a #% chance to gain an extra attack after blocking a melee attack and a #% chance to gain an extra attack after being the victim of a non-periodic critical strike"] = { ko = "근접 공격을 방패로 막은 후 {1}%의 확률로 추가 공격 기회를 얻고, 비주기적인 치명타 및 극대화 공격을 받았을 때 {2}%%의 확률로 추가 공격 기회를 얻습니다.", zhCN = "使你在格挡一次近战攻击后有{1}%的几率获得一次额外攻击，受到非周期性爆击之后有{2}%%的几率获得一次额外攻击。", zhTW = "使你在格擋一次近戰攻擊後有{1}%的機率獲得一次額外的攻擊機會，並在遭受非週期性致命一擊後有{2}%%的機率獲得一次額外的攻擊機會。" },
	["gives you a #% chance to gain focused casting for # sec after being the victim of a melee or ranged critical strike"] = { ko = "근접 및 원거리 치명타 공격을 받았을 때 {1}%의 확률로 {2}초 동안 집중력을 획득합니다.", zhCN = "使你有{1}%的几率在受到敌人的近战或远程爆击后得到专注施法，持续{2}秒。", zhTW = "使你有{1}%機率在受到敵人近戰或遠程致命一擊後獲得專注施法，持續{2}秒。" },
	["gives you a #% chance to gain focused casting for # sec after being the victim of a melee or ranged critical strike. the focused casting effect prevents you from losing casting time when taking damage and increases your resistance to interrupt effects by #%"] = { ko = "근접 및 원거리 치명타 공격을 받았을 때 {1}%의 확률로 {2}초 동안 집중력을 획득합니다. 집중력의 효과를 받을 땐 받는 피해로 인해 시전 시간이 지연되지 않으며 방해 효과에 대한 저항이 {3}%만큼 증가합니다.", zhCN = "使你有{1}%的几率在受到敌人的近战或远程爆击后得到专注施法，持续{2}秒。专注施法效果可以让你在施法时不会因为受到伤害而延长施法时间，且令你抵抗打断效果的几率提高{3}%。", zhTW = "使你有{1}%機率在受到敵人近戰或遠程致命一擊後獲得專注施法，持續{2}秒。專注施法效果可防止因受到傷害而損失施法時間，並使你對中斷效果的抗性提高{3}%。" },
	["gives you a #% chance to generate # additional rage when you deal melee damage with a weapon"] = { ko = "근접 무기로 적에게 피해를 입힐 시 {1}%의 확률로 {2}의 추가 분노를 생성합니다." },
	["gives you a #% chance to increase your spirit by #% for # sec after killing a non-trivial target or when an enemy afflicted by your vampiric embrace dies"] = { ko = "경험치 또는 명예 점수를 주는 적을 처치하거나 흡혈의 선물에 걸린 적이 죽으면 {1}%의 확률로 {3}초 동안 정신력이 {2}%만큼 증가합니다.", zhCN = "在消灭一个能为你提供经验值或荣誉值的敌人后，有{1}%的几率使你的精神提高{2}%，持续{3}秒。", zhTW = "在消滅一個能為你提供經驗值或榮譽值的敵人後，有{1}%的機率使你的精神提高{2}%，持續{3}秒。" },
	["gives you a #% chance to increase your spirit by #% for # sec after killing a non-trivial target or when an enemy afflicted by your vampiric embrace dies. for the duration, #% of your mana regeneration will continue while casting"] = { ko = "경험치 또는 명예 점수를 주는 적을 처치하거나 흡혈의 선물에 걸린 적이 죽으면 {1}%의 확률로 {3}초 동안 정신력이 {2}%만큼 증가합니다. 이 동안은 주문 시전 중 마나가 평소의 {4}%의 속도로 회복됩니다.", zhCN = "在消灭一个能为你提供经验值或荣誉值的敌人后，有{1}%的几率使你的精神提高{2}%，持续{3}秒。在此期间，你在施法时仍可保持{4}%的正常法力回复速度。", zhTW = "在消滅一個能為你提供經驗值或榮譽值的敵人後，有{1}%的機率使你的精神提高{2}%，持續{3}秒。在此期間，你在施法時仍可保持{4}%的正常法力回覆速度。" },
	["gives you a #% chance to resist interruption caused by damage while casting or channeling any destruction spell"] = { ko = "모든 파괴 계열 주문 시전 시 {1}%의 확률로 마법 시전 방해를 받지 않습니다.", zhCN = "使你有{1}%的几率在施放或引导任何毁灭系法术时不会因受到伤害而被打断。", zhTW = "使你有{1}%的機率在施放或引導毀滅系法術時不會因受到傷害而被打斷。" },
	["gives your arcane blast spell a #% chance, and your fireball, frostbolt, and frostfire bolt spells a #% chance to reduce the channeled duration of your next arcane missiles spell by #%, reduce the mana cost by #%, and missiles fire every # sec"] = { ko = "비전 작렬 시전 시 {1}%의 확률로, 화염구와 얼음 화살, 얼음불꽃 화살 시전 시 {2}%의 확률로 다음 신비한 화살 주문의 정신 집중 지속시간이 {3}%만큼, 마나 소모량이 {4}%만큼 감소하며, {5}초마다 화살을 발사합니다.", zhCN = "你的奥术冲击有{1}%的几率，火球术、寒冰箭和霜火之箭有{2}%的几率，使下一个奥术飞弹的引导时间缩短{3}%、法力消耗减少{4}%，且每{5}秒发射一次飞弹。", zhTW = "使你的秘法衝擊有{1}%的機率、而你的火球術、寒冰箭和霜火箭則有{2}%的機率使你下一個秘法飛彈法術的引導時間縮短{3}%，法力消耗降低{4}%，且每{5}秒發射一發飛彈。" },
	["gives your chill effects a #% chance to freeze the target for # sec"] = { ko = "{1}%의 확률로 빙결 효과에 걸린 적을 {2}초 동안 움직이지 못하도록 만듭니다.", zhCN = "你的冰冷效果有{1}%的几率将目标冰冻{2}秒。", zhTW = "使你的冰冷效果有{1}%的機率讓目標凍結{2}秒。" },
	["gives your chill effects a #% chance to grant you the fingers of frost effect, which treats your next # spell cast as if the target were frozen"] = { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。", zhTW = "你的冰冷效果有{1}%的機率使你獲得冰霜之指效果，使你的下{2}次法術將目標視為已被凍結。" },
	["gives your chill effects a #% chance to grant you the fingers of frost effect, which treats your next # spell cast as if the target were frozen. lasts # sec"] = { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다. {3}초 동안 지속됩니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。持续{3}秒。", zhTW = "你的冰冷效果有{1}%的機率使你獲得冰霜之指效果，使你的下{2}次法術將目標視為已被凍結。持續{3}秒。" },
	["gives your chill effects a #% chance to grant you the fingers of frost effect, which treats your next # spells cast as if the target were frozen"] = { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。" },
	["gives your chill effects a #% chance to grant you the fingers of frost effect, which treats your next # spells cast as if the target were frozen. lasts # sec"] = { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다. {3}초 동안 지속됩니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。持续{3}秒。", zhTW = "你的冰冷效果有{1}%的機率賦予你冰霜之指的效果，使你接下來施放的{2}發法術視同目標處於冰凍狀態，持續{3}秒。" },
	["gives your concussive shot a #% chance to stun the target for # sec"] = { ko = "충격포 사용 시 {1}%의 확률로 적을 {2}초 동안 기절시킵니다.", zhCN = "使你的震荡射击有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的震盪射擊有{1}%的機率令目標昏迷{2}秒。" },
	["gives your corruption, drain soul, drain life, and wrack spells a #% chance to cause you to enter a shadow trance after damaging the opponent"] = { ko = "부패, 영혼 흡수, 생명력 흡수, 파멸로 적에게 피해를 입히면 {1}%의 확률로 어둠의 무아지경에 빠져듭니다.", zhCN = "使你的腐蚀术、吸取灵魂、吸取生命和折磨在对敌人造成伤害后有{1}%的几率令你进入暗影冥思。", zhTW = "使你的腐蝕術、吸取靈魂、吸取生命和毀壞法術有{1}%的機率在對敵人造成傷害之後令你進入暗影冥思。" },
	["gives your corruption, drain soul, drain life, and wrack spells a #% chance to cause you to enter a shadow trance after damaging the opponent. the shadow trance reduces the casting time of your next shadow bolt spell by #%"] = { ko = "부패, 영혼 흡수, 생명력 흡수, 파멸로 적에게 피해를 입히면 {1}%의 확률로 어둠의 무아지경에 빠져듭니다. 이 상태에서 다음 어둠의 화살의 시전 시간이 {2}%만큼 단축됩니다.", zhCN = "使你的腐蚀术、吸取灵魂、吸取生命和折磨在对敌人造成伤害后有{1}%的几率令你进入暗影冥思。暗影冥思使你的下一个暗影箭的施法时间缩短{2}%。", zhTW = "使你的腐蝕術、吸取靈魂、吸取生命和毀壞法術有{1}%的機率在對敵人造成傷害之後令你進入暗影冥思。暗影冥思令你下一個暗影箭法術的施法時間縮短{2}%。" },
	["gives your damaging melee attacks a chance to reduce the target's attack power by #, and increase your attack power by #% for # sec"] = { ko = "근접 공격으로 피해를 입히면 일정 확률로 {3}초 동안 대상의 전투력을 {1}만큼 감소시키고 자신의 전투력은 {2}%만큼 증가시킵니다.", zhCN = "使你的伤害性近战攻击有几率令目标的攻击强度降低{1}点，并使你的攻击强度提高{2}%，持续{3}秒。", zhTW = "使你的近戰攻擊有一定機率使目標的攻擊強度降低{1}點，並使你的攻擊強度提高{2}%，持續{3}秒。" },
	["gives your finishing moves a #% chance to add a combo point to your target"] = { ko = "마무리 일격 사용 시 {1}%의 확률로 대상에게 연계 점수 1점을 추가합니다.", zhCN = "使你的终结技有{1}%的几率为目标增加一个连击点数。", zhTW = "使你的終結技有{1}%的機率為目標增加一個連擊點數。" },
	["gives your fire spells a #% chance to not lose casting time when you take damage and reduces the threat caused by your fire spells by #%"] = { ko = "화염 주문 사용 시 피해를 입어도 {1}%의 확률로 시전 시간이 지연되지 않으며 화염 주문으로 발생되는 위협 수준이 {2}%만큼 감소합니다.", zhCN = "使你的火焰系法术有{1}%的几率不会因为你受到伤害而被干扰，火焰系法术所造成的威胁值降低{2}%。", zhTW = "使你的火焰法術有{1}%的機率不會因為你受到傷害而損失施法時間，並使你的火焰法術所產生的威脅值降低{2}%。" },
	["gives your fire spells a #% chance to stun the target for # sec"] = { ko = "화염 주문 적중 시 {1}%의 확률로 적을 {2}초 동안 기절시킵니다.", zhCN = "使你的火焰法术有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的火焰法術有{1}%的機率令目標昏迷{2}秒。" },
	["gives your flash of light, holy light, and light's vigil spells a #% chance to not lose casting time when you take damage"] = { ko = "빛의 섬광, 성스러운 빛, 빛의 경계 시전 시 피해를 받아도 {1}%의 확률로 시전 시간이 지연되지 않습니다.", zhCN = "使你的圣光闪现、圣光术和圣光守望有{1}%的几率在受到伤害时不损失施法时间。", zhTW = "使你的聖光閃現、聖光術和聖光戒備有{1}%的機率在受到傷害時不會損失施法時間。" },
	["gives your frost damage spells a #% chance to apply the winter's chill effect, which increases the chance your ice lance and frostbolt spells will critically hit the target by #% for # sec"] = { zhCN = "你的冰霜伤害法术有{1}%的几率施加深冬之寒效果，使你的冰枪术和寒冰箭对该目标的爆击几率提高{2}%，持续{3}秒。", zhTW = "使你的冰霜傷害法術有{1}%的機率施加深冬之寒效果，使你的冰霜長矛和寒冰箭對目標造成致命一擊的機率提高{2}%，持續{3}秒。" },
	["gives your frost damage spells a #% chance to apply the winter's chill effect, which increases the chance your ice lance and frostbolt spells will critically hit the target by #% for # sec. stacks up to # times"] = { ko = "냉기 공격 주문 사용 시 {1}%의 확률로 혹한의 추위 효과가 부여됩니다. 혹한의 추위는 {3}초 동안 얼음창과 얼음 화살이 극대화 효과를 발휘할 확률을 {2}%만큼 증가시킵니다. 최대 {4}번까지 중첩됩니다.", zhCN = "你的冰霜伤害法术有{1}%的几率施加深冬之寒效果，使你的冰枪术和寒冰箭对该目标的爆击几率提高{2}%，持续{3}秒。最多叠加{4}次。", zhTW = "使你的冰霜傷害法術有{1}%的機率施加深冬之寒效果，使你的冰霜長矛和寒冰箭對目標造成致命一擊的機率提高{2}%，持續{3}秒。最多可堆疊{4}層。" },
	["gives your hamstring ability a #% chance to immobilize the target for # sec"] = { ko = "무력화 사용 시 {1}%의 확률로 대상을 {2}초 동안 이동 불가 상태로 만듭니다.", zhCN = "使你的断筋技能有{1}%的几率令目标无法移动，持续{2}秒。", zhTW = "使你的斷筋技能有{1}%的機率令目標無法移動，持續{2}秒。" },
	["gives your holy spells #% increased damage against the first # enemies that enter your consecration"] = { ko = "자신의 신성화 지역에 들어오는 첫 {2}명의 적에게 입히는 신성 주문의 피해가 {1}%만큼 증가합니다.", zhCN = "使你的神圣法术对最先进入你的奉献的{2}个敌人造成的伤害提高{1}%。", zhTW = "你神聖法術對前{2}個進入奉獻效果範圍的敵人造成的傷害提高{1}%。" },
	["gives your judgement ability a #% chance to return #% of the mana cost of the judged seal"] = { ko = "심판 사용 시, {1}%의 확률로 심판이 적용된 문장의 마나 소모량의 {2}%를 되돌려받습니다.", zhCN = "使你的审判有{1}%几率返还被审判圣印法力消耗的{2}%。", zhTW = "使你的審判技能有{1}%的機率返還審判聖印消耗的{2}%法力。" },
	["gives your kick ability a #% chance to silence the target for # sec"] = { ko = "발차기에 적중한 적을 {1}%의 확률로 {2}초 동안 침묵하도록 만듭니다.", zhCN = "使你的脚踢技能有{1}%的几率令目标沉默{2}秒。", zhTW = "使你的腳踢技能有{1}%的機率令目標沉默{2}秒。" },
	["gives your lightning bolt and chain lightning spells a #% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat"] = { ko = "번개 화살과 연쇄 번개 시전 시 {1}%의 확률로 마나 소모 없이 같은 대상에게 유사한 주문을 시전하여 절반의 피해를 입힙니다. 이 주문은 위협 수준을 생성하지 않습니다.", zhCN = "你的闪电箭和闪电链有{1}%的几率对同一目标施放第二个类似法术，不消耗额外法力，只造成一半伤害且不产生威胁。", zhTW = "使你的閃電箭和閃電鏈有{1}%的機率對同一目標發射第二發同樣的法術，不消耗任何法力也不造成威脅值，但傷害值減半。" },
	["gives your melee weapon attacks a benefit depending on the weapon"] = { zhCN = "根据你所使用的武器，为你的近战武器攻击提供一定的加成效果。", zhTW = "根據你所使用的武器，為你的近戰武器攻擊提供一定的加成效果。" },
	["gives your melee weapon attacks a benefit depending on the weapon. axe/polearm: increases your critical strike chance by #%. mace/staff: your attacks ignore #% of your target's armor. sword: your successful melee attacks have a #% chance to trigger an extra attack on the target"] = { ko = "무기 종류에 따라 근접 공격에 이로운 효과를 부여합니다. 도끼류/장창류: 치명타 및 극대화율이 {1}%만큼 증가합니다. 둔기류/지팡이류: 공격 시 대상의 방어도를 {2}%만큼 무시합니다. 도검류: 근접 공격 적중 시 {3}%의 확률로 대상에게 추가 공격을 가합니다." },
	["gives your melee weapon attacks a benefit depending on the weapon. axe/sword: your successful melee attacks have a #% chance to trigger an extra attack on the target. dagger/fist: increases your critical strike chance by #%. mace: your attacks ignore #% of your target's armor"] = { ko = "무기 종류에 따라 근접 공격에 이로운 효과를 부여합니다. 도끼류/도검류: 근접 공격 적중 시 {1}%의 확률로 대상에게 추가 공격을 가합니다. 단검류/장착 무기류: 치명타 및 극대화율이 {2}%만큼 증가합니다. 둔기류: 공격 시 대상의 방어도를 {3}%만큼 무시합니다.", zhCN = "使你的近战武器攻击根据武器类型获得不同增益。 斧/剑：你的成功近战攻击有{1}%的几率对目标触发一次额外攻击。 匕首/拳套：使你的爆击几率提高{2}%。 锤：你的攻击无视 目标{3}%的护甲值。", zhTW = "使你的近戰武器攻擊根據武器類型獲得不同增益。 斧/劍：你的成功近戰攻擊有{1}%的機率對目標觸發一次額外攻擊。 匕首/拳套：使你的致命一擊機率提高{2}%。 錘：你的攻擊無視 目標{3}%的護甲值。" },
	["gives your mend pet spell a #% chance of cleansing # curse, disease, magic, or poison effect from your pet each time it heals and reduces the mana cost by #%"] = { ko = "동물 치료 시, 치유 효과를 발휘할 때마다 {1}%의 확률로 야수에게서 {2}개의 저주나 질병, 마법, 독 효과를 제거합니다. 또한 마나 소모량이 {3}%만큼 감소합니다.", zhCN = "使你的治疗宠物每次治疗时有{1}%的几率净化宠物身上的{2}个诅咒、疾病、魔法或中毒效果，并使法力消耗降低{3}%。", zhTW = "使你的治療寵物技能每次造成治療效果時都有{1}%的機率移除寵物身上{2}個詛咒、疾病、魔法或中毒效果，並使法力消耗降低{3}%。" },
	["gives your pet a #% chance to gain a #% attack speed increase for # sec after dealing a critical strike"] = { ko = "야수의 공격이 치명타로 적중할 시 {1}%의 확률로 공격 속도가 {3}초 동안 {2}%만큼 증가합니다.", zhCN = "使你的宠物有{1}%的几率在对敌人造成爆击后获得攻击速度提高{2}%的效果，持续{3}秒。", zhTW = "使你的寵物有{1}%的機率在對敵人造成致命一擊後獲得攻擊速度提高{2}%的效果，持續{3}秒。" },
	["gives your shadow damage spells a #% chance to stun the target for # sec"] = { ko = "암흑 공격 주문 사용 시 {1}%의 확률로 대상을 {2}초 동안 기절시킵니다.", zhCN = "使你的暗影系伤害性法术有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的暗影系傷害性法術有{1}%的機率令目標昏迷{2}秒。" },
	["gives your shield bash ability a #% chance to silence the target for # sec"] = { ko = "방패 가격 시 {1}%의 확률로 {2}초 동안 적을 침묵시킵니다.", zhCN = "使你的盾击技能有{1}%的几率令目标沉默{2}秒。", zhTW = "使你的盾擊技能有{1}%的機率使目標沉默{2}秒。" },
	["gives your soul fire spell a #% chance to stun the target for # sec, and your rain of fire and hellfire spells a #% chance over their duration to stun targets they damage for # sec"] = { ko = "영혼의 불꽃이 {1}%의 확률로 대상을 {2}초 동안 기절시킵니다. 또한 불의 비와 지옥의 불길은 지속시간 동안 피해를 입힐 때 {3}%의 확률로 대상을 {4}초 동안 기절시킵니다.", zhCN = "使你的灵魂之火有{1}%的几率令目标昏迷{2}秒，并使你的火焰之雨和地狱烈焰在持续期间有{3}%的几率令受到伤害的目标昏迷{4}秒。", zhTW = "使你的靈魂之火法術有{1}%的機率使目標昏迷{2}秒，你的火焰之雨和地獄烈焰法術在造成傷害的期間中有{3}%機率使目標昏迷{4}秒。" },
	["gives your summoned demon lesser invisibility for up to # min"] = { ko = "최대 {1}분 동안 소환된 악마가 하급 투명 효과를 얻습니다.", zhCN = "使你召唤的恶魔获得次级隐形术的效果，最多持续{1}分钟。", zhTW = "使你召喚的惡魔獲得次級隱形術的效果，最多持續{1}分鐘。" },
	["gives your summoned demon lesser invisibility for up to # min. this spell can only be used out of combat"] = { ko = "최대 {1}분 동안 소환된 악마가 하급 투명 효과를 얻습니다. 비전투 상태에서만 사용할 수 있습니다.", zhCN = "使你召唤的恶魔获得次级隐形术的效果，最多持续{1}分钟。这个法术只能在非战斗状态下使用。", zhTW = "使你召喚的惡魔獲得次級隱形術的效果，最多持續{1}分鐘。這個法術只能在非戰鬥狀態下使用。" },
	["gives your wing clip ability a #% chance to immobilize the target for # sec"] = { ko = "날개 절단 사용 시 {1}%의 확률로 대상을 {2}초 동안 움직이지 못하도록 만듭니다.", zhCN = "使你的摔绊技能有{1}%的几率令目标在{2}秒内无法移动。", zhTW = "使你的摔絆技能有{1}%的機率令目標在{2}秒內無法移動。" },
	["glide downward through the air for # sec while controlling your direction of travel"] = { ko = "{1}초 동안 활공하며 내려갑니다. 시전자가 방향을 조정할 수 있습니다.", zhCN = "在半空中滑翔下降，持续{1}秒，并可控制移动方向。", zhTW = "一邊控制移動方向，一邊在空中向下滑翔，持續{1}秒。" },
	["grabs an enemy's weapon with its talons, causing # to # damage and disarming them for # sec"] = { ko = "발톱으로 적의 무기를 낚아채 {1}~{2}의 피해를 입히고 {3}초 동안 무장을 해제시킵니다.", zhCN = "用利爪夺取敌人的武器，造成{1}至{2}点伤害并将其缴械，持续{3}秒。", zhTW = "用利爪奪取敵人的武器，造成{1}至{2}點傷害並將其繳械，持續{3}秒。" },
	["grants # health and # mana every # sec for # sec when one of your spells is resisted"] = { ko = "적이 자신의 주문에 저항하면 {4}초 동안 {3}초마다 {1}의 생명력과 {2}의 마나를 회복합니다.", zhCN = "当你的法术被抵抗时，每{3}秒恢复{1}点生命值和{2}点法力值，持续{4}秒。", zhTW = "當你的其中一個法術被抵抗時，每{3}秒賦予{1}點生命力和{2}點法力，持續{4}秒。" },
	["grants both the warlock and the summoned demon an effect as long as that demon is active"] = { ko = "소환수를 부리고 있을 때 소환수의 종류에 따라 흑마법사와 소환수에게 다음의 효과가 주어집니다.", zhCN = "只要召唤的恶魔保持激活，使术士和该恶魔获得一个效果。", zhTW = "只要術士召喚的惡魔存在，術士與該惡魔便會獲得特殊效果。" },
	["grants you a #% chance to generate # rage when you dodge or parry while a shield is equipped"] = { ko = "방패를 장착한 동안 회피하거나 무기 막기에 성공하면 {1}%의 확률로 {2}의 분노를 얻습니다.", zhCN = "使你有{1}%的几率在装备盾牌并躲闪或招架时产生{2}点怒气。", zhTW = "裝備盾牌的情況下，你閃躲或招架時有{1}%的機率產生{2}點怒氣。" },
	["grants you immunity to silence and interrupt effects for # sec"] = { ko = "{1}초 동안 침묵과 시전 방해 효과에 면역이 됩니다.", zhCN = "使你免疫沉默和中断效果。持续{1}秒。", zhTW = "使你免疫沉默和中斷效果。持續{1}秒。" },
	["greatly increased chance to detect traps"] = { ko = "함정을 찾을 확률이 대폭 증가합니다.", zhCN = "极大提高侦测陷阱的能力。", zhTW = "大幅度提高偵測陷阱的機會。" },
	["harmful spell casts sear the target for # fire damage"] = { ko = "해로운 주문 시전 시 대상을 그을려 {1}의 화염 피해를 입힙니다.", zhCN = "施放有害法术会灼烧目标，造成{1}点火焰伤害。", zhTW = "施放有害法術時，灼燒目標，造成{1}點火焰傷害。" },
	["heal your target for # to #"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시킵니다.", zhCN = "治疗目标，恢复{1}至{2}点生命值。", zhTW = "治療目標，恢復{1}至{2}點生命力。" },
	["heal yourself and a friendly target for # to #"] = { ko = "자신과 아군 대상 하나를 {1}~{2}만큼 치유합니다." },
	["heal yourself and a friendly target for # to # this causes low threat"] = { ko = "자신과 아군 대상 하나를 {1}~341만큼 치유합니다. 낮은 위협 수준을 생성합니다." },
	["heals # damage over # sec"] = { ko = "{2}초에 걸쳐 생명력을 {1}만큼 회복시킵니다.", zhCN = "在{2}秒内恢复{1}点生命值。", zhTW = "在{2}秒內恢復{1}點生命力。" },
	["heals # total targets"] = { ko = "최대 {1}명의 대상에게 효력을 미칩니다.", zhCN = "总共可治疗{1}个目标。", zhTW = "總共可治療{1}個目標。" },
	["heals a friendly target and the caster for # to #"] = { ko = "아군 대상과 시전자를 {1}~{2}만큼 치유합니다.", zhCN = "为一个友方目标和施法者本身各恢复{1}至{2}点生命值。" },
	["heals a friendly target and the caster for # to # low threat"] = { ko = "아군 대상과 시전자를 {1}~271만큼 치유합니다. 낮은 위협 수준을 생성합니다.", zhCN = "为一个友方目标和施法者本身各恢复{1}至271点生命值。低威胁值的技能。", zhTW = "同時治療一名友方目標和施法者{1}至271點生命力，造成低量的威脅值。" },
	["heals a friendly target for # to #"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2}点生命值。", zhTW = "治療友方目標，恢復{1}至{2}點生命力。" },
	["heals a friendly target for # to # and another # over # sec"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 추가로 {4}초에 걸쳐 총 {3}의 생명력을 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2}点生命值，并在{4}秒内恢复额外的{3}点生命值。", zhTW = "治療友方目標，恢復{1}至{2}點生命力，並在{4}秒內恢復額外的{3}點生命力。" },
	["heals a friendly target for # to #, an additional # over # sec, and increases the effectiveness of your chain heal casts directly on that target by #%"] = { ko = "아군 대상을 {1}~{2}만큼 치유한 후, 추가로 {4}초에 걸쳐 {3}만큼 회복시킵니다. 또한 대상에게 직접 시전하는 연쇄 치유의 효과가 {5}%만큼 증가합니다.", zhCN = "治疗一个友方目标，为其恢复{1}至{2}点生命值，并在{4}秒内额外恢复{3}点，同时使你对该目标直接施放的治疗链效果提高{5}%。", zhTW = "為一個友方目標治療{1}至{2}點生命力，同時在{4}秒內額外治療{3}點生命力，且你的治療鍊直接對該目標施放時，效果提高{5}%。" },
	["heals a friendly target for # to #,#"] = { ko = "대상의 생명력을 {1}~{2},{3}만큼 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2},{3}点生命值。", zhTW = "治療友方目標，恢復{1}至{2},{3}點生命力。" },
	["heals a friendly target for # to #,# and another # over # sec"] = { ko = "대상의 생명력을 {1}~{2},{3}만큼 회복시키고 추가로 {5}초에 걸쳐 총 {4}의 생명력을 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2},{3}点生命值，并在{5}秒内恢复额外的{4}点生命值。", zhTW = "治療友方目標，恢復{1}至{2},{3}點生命力，並在{5}秒內恢復額外的{4}點生命力。" },
	["heals a friendly target for #,# to #,#"] = { ko = "대상의 생명력을 {1},{2}~{3},{4}만큼 회복시킵니다.", zhCN = "治疗友方目标，恢复{1},{2}至{3},{4}点生命值。", zhTW = "治療友方目標，恢復{1},{2}至{3},{4}點生命力。" },
	["heals a friendly target for an amount equal to the paladin's maximum health"] = { ko = "성기사의 최대 생명력만큼 아군 대상을 치유합니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力。" },
	["heals a friendly target for an amount equal to the paladin's maximum health and restores # of their mana"] = { ko = "성기사의 최대 생명력만큼 아군 대상을 치유하고 {1}의 마나를 회복시킵니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值，并为其恢复{1}点法力值。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力，並恢復{1}點法力。" },
	["heals a friendly target for an amount equal to the paladin's maximum health and restores # of their mana. drains all of the paladin's remaining mana when used, but does not interrupt mana regeneration"] = { ko = "성기사의 최대 생명력만큼 아군 대상을 치유하고 {1}의 마나를 회복시킵니다. 이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值，并为其恢复{1}点法力值。使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力，並恢復{1}點法力。使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" },
	["heals a friendly target for an amount equal to the paladin's maximum health. drains all of the paladin's remaining mana when used, but does not interrupt mana regeneration"] = { ko = "성기사의 최대 생명력만큼 아군 대상을 치유합니다. 이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值。使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力。使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" },
	["heals the friendly target for # to #, then jumps to heal additional nearby targets"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 그 주위의 아군을 연쇄적으로 회복시킵니다.", zhCN = "为友方目标回复{1}至{2}点生命值，然后转而治疗附近的目标。", zhTW = "為友方目標恢復{1}至{2}點生命力，然後轉而治療附近其他的目標。" },
	["heals the friendly target for # to #, then jumps to heal additional nearby targets. if cast on a party member, the heal will only jump to other party members. each jump is #% as effective as the previous target. heals # total targets"] = { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 그 주위의 아군을 연쇄적으로 회복시킵니다. 파티원에게 사용하면 같은 파티원에게만 효과가 전달됩니다. 대상이 바뀔 때마다 이전 대상 대비 {3}%의 효율을 발휘합니다. 최대 {4}명의 대상에게 효력을 미칩니다.", zhCN = "为友方目标回复{1}至{2}点生命值，然后转而治疗附近的目标。如果对小队成员施法，则治疗链只会继续治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的{3}%。总共可治疗{4}个目标。", zhTW = "為友方目標恢復{1}至{2}點生命力，然後轉而治療附近其他的目標。如果施放在隊伍成員身上，則治療效果只會治療其他的隊伍成員。治療鍊每次跳躍後的治療效果會等同於先前目標的{3}%。總共可治療{4}個目標。" },
	["heals the target and their party for # over # sec"] = { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다.", zhTW = "治療目標和其隊伍，使其在{2}秒內恢復{1}點生命力。" },
	["heals the target and their party for # over # sec. party members must be within # yards of target. the amount healed is applied quickly at first, and slows down as wild growth reaches its full duration"] = { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다. 파티원이 대상의 {3}미터 내에 있어야 합니다. 처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다.", zhCN = "在{2}秒内为目标及其{3}码内的小队成员恢复{1}点生命值。治疗效果起初较快，随着野性成长接近结束而变慢。", zhTW = "治療目標和其隊伍，使其在{2}秒內恢復{1}點生命力。小隊成員必須在目標附近{3}碼內。野性痊癒的恢復速度在起步時最快，並且隨時間而減緩，直到結束為止。" },
	["heals the target and their party for # over # sec. party members must be within # yds of target. the amount healed is applied quickly at first, and slows down as wild growth reaches its full duration"] = { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다. 파티원이 대상의 {3}미터 내에 있어야 합니다. 처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다." },
	["heals the target for # over # sec"] = { ko = "{2}초에 걸쳐 {1}의 생명력을 회복시킵니다.", zhCN = "治疗目标，在{2}秒内恢复总计{1}点生命值。", zhTW = "治療目標，在{2}秒內恢復總計{1}點生命力。" },
	["heals the target of # damage over # sec"] = { ko = "{2}초에 걸쳐 대상의 생명력을 총 {1}만큼 회복시킵니다.", zhCN = "治疗目标，在{2}秒内恢复总计{1}点生命值。", zhTW = "治療目標，在{2}秒內恢復總計{1}點生命力。" },
	["heals your pet # health every second while you focus"] = { ko = "야수에 정신을 집중하는 동안 매초마다 {1}의 생명력을 치료합니다.", zhCN = "集中注意力为宠物治疗，令其每秒恢复{1}点生命值。", zhTW = "集中注意力為寵物治療，令其每秒恢復{1}點生命力。" },
	["heals your pet # health every second while you focus. lasts # sec"] = { ko = "야수에 정신을 집중하는 동안 매초마다 {1}의 생명력을 치료합니다. {2}초 동안 지속됩니다.", zhCN = "集中注意力为宠物治疗，令其每秒恢复{1}点生命值。持续{2}秒。", zhTW = "集中注意力為寵物治療，令其每秒恢復{1}點生命力。持續{2}秒。" },
	["hitting a target with your serpent sting ability grants you #% and consuming rapid killing grants you #% of your mana regeneration while casting for the next # sec"] = { ko = "독사 쐐기를 대상에게 적중시키면 다음 {3}초 동안 시전 중에도 {1}%의 속도로 마나를 회복합니다. 신속한 사냥을 소모하는 경우에는 {2}%의 속도로 회복합니다.", zhCN = "用毒蛇钉刺命中目标时使你获得{1}%、消耗疾速杀戮时使你获得{2}%的施法时法力回复，持续{3}秒。", zhTW = "以毒蛇釘刺技能命中目標，或消耗急速殺戮後，分別使你在接下來的{3}秒內在施法時仍保持{1}%和{2}%的法力恢復速度。" },
	["hitting an enemy with conflagrate increases all shadow damage you deal by #% for # sec, and hitting an enemy with shadowburn increases all fire damage you deal by #% for # sec"] = { ko = "적에게 점화를 적중시키면 {2}초 동안 주는 모든 암흑 피해가 {1}%만큼 증가하고, 적에게 어둠의 연소를 적중시키면 {4}초 동안 주는 모든 화염 피해가 {3}%만큼 증가합니다.", zhTW = "以焚燒命中敵人會使你造成的所有暗影傷害提高{1}%，持續{2}秒，且以暗影灼燒命中敵人會使你造成的所有火焰傷害提高{3}%，持續{4}秒。" },
	["hitting an enemy with conflagrate increases all shadow damage you deal by #% for # sec, and hitting an enemy with shadowburn increases all fire damage you deal by #% for # sec. in addition, conflagrate has a #% chance not to consume immolate, and shadowburn has a #% chance to instantly refund a soul shard"] = { ko = "적에게 점화를 적중시키면 {2}초 동안 주는 모든 암흑 피해가 {1}%만큼 증가하고, 적에게 어둠의 연소를 적중시키면 {4}초 동안 주는 모든 화염 피해가 {3}%만큼 증가합니다. 추가로, 점화가 {5}%의 확률로 제물을 소모하지 않고, 어둠의 연소가 {6}%의 확률로 영혼의 조각을 즉시 돌려줍니다.", zhCN = "使用燃烧击中敌人后，你造成的所有暗影伤害提高{1}%，持续{2}秒。使用暗影灼烧击中敌人后，你造成的所有火焰伤害提高{3}%，持续{4}秒。此外，燃烧有{5}%的几率不消耗献祭，暗影灼烧有{6}%的几率立刻返还一块灵魂碎片。", zhTW = "以焚燒命中敵人會使你造成的所有暗影傷害提高{1}%，持續{2}秒，且以暗影灼燒命中敵人會使你造成的所有火焰傷害提高{3}%，持續{4}秒。此外，焚燒有{5}%機率不會消耗獻祭，且暗影灼燒有{6}%機率會立即返還一個靈魂裂片。" },
	["holy power infuses the target, increasing their spirit by # for # hr"] = { ko = "신성한 힘이 대상을 감싸 {2}시간 동안 정신력을 {1}만큼 증가시킵니다.", zhCN = "圣洁的能量充满目标全身，令其精神提高{1}点，持续{2}小时。", zhTW = "聖潔的能量充滿目標全身，令其精神提高{1}點，持續{2}小時。" },
	["however, you may not cast healing spells while in this form"] = { zhCN = "但是在此形态下，你无法施放治疗法术。", zhTW = "然而，在此形態下你無法施放治療法術。" },
	["howl, causing # enemies within # yds to flee in terror for # sec"] = { ko = "끔찍한 소리로 울부짖어 {2}초 동안 {3}미터 반경의 적 {1}명을 공포에 질려 도망가게 만듭니다.", zhCN = "使半径{2}码范围内的{1}个敌人因恐惧而逃跑，持续{3}秒。", zhTW = "使半徑{2}碼範圍內的{1}個敵人因恐懼而逃跑，持續{3}秒。" },
	["howl, causing # enemies within # yds to flee in terror for # sec. damage caused may interrupt the effect"] = { ko = "끔찍한 소리로 울부짖어 {2}초 동안 {3}미터 반경의 적 {1}명을 공포에 질려 도망가게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.", zhCN = "使半径{2}码范围内的{1}个敌人因恐惧而逃跑，持续{3}秒。逃跑的敌人若受到伤害，则恐惧效果可能被打断。", zhTW = "使半徑{2}碼範圍內的{1}個敵人因恐懼而逃跑，持續{3}秒。逃跑的敵人若受到傷害，則恐懼效果可能被打斷。" },
	["hurl spikes at the target, dealing # physical damage and jumping to # additional nearby enemy"] = { ko = "대상에게 가시를 던져 {1}의 물리 피해를 입히고 주위의 추가 적 {2}명에게 튕깁니다." },
	["hurl spikes at the target, dealing # physical damage and jumping to # additional nearby enemy. each jump reduces the damage by #%"] = { ko = "대상에게 가시를 던져 {1}의 물리 피해를 입히고 주위의 추가 적 {2}명에게 튕깁니다. 튕길 때마다 입히는 피해가 {3}%만큼 감소합니다." },
	["hurls a fiery ball that causes # fire damage and an additional # damage over # sec"] = { ko = "적에게 불타는 구체를 날려 {1}의 화염 피해를 입히고 {3}초에 걸쳐 총 {2}의 추가 피해를 입힙니다.", zhCN = "发射一枚火球攻击目标，对其造成{1}点火焰伤害，并在{3}秒内造成额外的{2}点伤害。", zhTW = "發射一枚火球攻擊目標，對其造成{1}點火焰傷害，並在{3}秒內造成額外的{2}點傷害。" },
	["hurls a fiery ball that causes # to # fire damage and an additional # fire damage over # sec"] = { ko = "적에게 불타는 구체를 날려 {1}~{2}의 화염 피해를 입히고 {4}초에 걸쳐 총 {3}의 추가 화염 피해를 입힙니다.", zhCN = "发射一枚火球攻击目标，对其造成{1}至{2}点火焰伤害，并在{4}秒内造成额外的{3}点伤害。", zhTW = "發射一枚火球攻擊目標，對其造成{1}至{2}點火焰傷害，並在{4}秒內造成額外的{3}點火焰傷害。" },
	["hurls a hammer that strikes an enemy for # to # holy damage"] = { ko = "망치를 적에게 던져 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "投掷一柄战锤，对敌人造成{1}至{2}点神圣伤害。", zhTW = "投擲一柄戰錘，對敵人造成{1}至{2}點神聖傷害。" },
	["hurls a hammer that strikes an enemy for # to # holy damage. only usable on enemies that have #% or less health"] = { ko = "망치를 적에게 던져 {1}~{2}의 신성 피해를 입힙니다. 생명력이 {3}%미만인 적에게만 사용할 수 있습니다.", zhCN = "投掷一柄战锤，对敌人造成{1}至{2}点神圣伤害。只能对生命值少于{3}%的目标使用。", zhTW = "投擲一柄戰錘，對敵人造成{1}至{2}點神聖傷害。只能對生命低於{3}%的目標使用。" },
	["hurls a lightning bolt at the enemy, dealing # to # nature damage and then jumping to additional nearby enemies"] = { ko = "적에게 번개를 날려 {1}~{2}의 자연 피해를 입히고 주위 적을 연쇄적으로 가격합니다." },
	["hurls a lightning bolt at the enemy, dealing # to # nature damage and then jumping to additional nearby enemies. each jump reduces the damage by #%. affects # total targets"] = { ko = "적에게 번개를 날려 {1}~{2}의 자연 피해를 입히고 주위 적을 연쇄적으로 가격합니다. 대상이 바뀔 때마다 피해는 {3}%씩 감소됩니다. 최대 {4}명의 대상을 공격합니다.", zhCN = "向敌人射出一支闪电箭，对其造成{1}至{2}点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少{3}%，最多可攻击{4}个目标。", zhTW = "向敵人射出一支閃電箭，對其造成{1}至{2}點自然傷害，隨後這支閃電箭會繼續攻擊它周圍最近的敵人。閃電箭每跳躍一次，傷害就減少{3}%，最多可影響{4}個目標。" },
	["hurls an immense fiery boulder that causes # to # fire damage and an additional # fire damage over # sec"] = { ko = "엄청난 크기의 불덩이를 던져 {1}~{2}의 화염 피해를 입히고 추가로 {4}초에 걸쳐 총 {3}의 화염 피해를 입힙니다.", zhCN = "发射一枚巨大的火球，对目标造成{1}至{2}点火焰伤害，并在{4}秒内造成总计{3}点额外伤害。", zhTW = "發射一枚巨大的火球，對目標造成{1}至{2}點火焰傷害，並在{4}秒內造成總計{3}點額外傷害。" },
	["ice shards pelt the target area doing # frost damage over # sec"] = { ko = "대상 지역에 얼음 파편을 퍼부어, {2}초에 걸쳐 총 {1}의 냉기 피해를 입힙니다.", zhCN = "破碎的冰块从天而降，在{2}秒内对目标区域中的敌人造成{1}点冰霜伤害。", zhTW = "寒冰的裂片墜落在目標區域，在{2}秒內造成總計{1}點冰霜傷害。" },
	["ice shards pelt the target area doing #,# frost damage over # sec"] = { ko = "대상 지역에 얼음 파편을 퍼부어, {3}초에 걸쳐 총 {1},{2}의 냉기 피해를 입힙니다.", zhCN = "破碎的冰块从天而降，在{3}秒内对目标区域中的敌人造成{1},{2}点冰霜伤害。", zhTW = "寒冰的裂片墜落在目標區域，在{3}秒內造成總計{1},{2}點冰霜傷害。" },
	["if a non-trivial target dies within # sec of being hit with shadowburn, the caster gains a soul shard"] = { ko = "사소하지 않은 대상이 이 주문에 걸린 지 {1}초 내에 사망하면 시전자가 영혼의 조각을 얻습니다.", zhCN = "若消灭一个能为你提供经验值或荣誉值的敌人，且其在受到暗影灼烧后的{1}秒内死亡，则施法者获得一块灵魂碎片。", zhTW = "如果有實力的目標在被暗影灼燒命中後的{1}秒內死亡，則施法者獲得一塊靈魂裂片。" },
	["if a pack member takes damage, they will be dazed for # sec"] = { ko = "이 동안 파티원이 피해를 입게 되면 {1}초 동안 멍해지게 됩니다.", zhCN = "如果任何一个队友受到伤害，则全队都会眩晕{1}秒。", zhTW = "如果任何一個隊友受到傷害，則全隊都會眩暈{1}秒。" },
	["if an effect is devoured, the felhunter will be healed for #"] = { ko = "마법을 삼키게 되면 지옥사냥개는 {1}의 생명력을 회복합니다.", zhCN = "每吞噬一个魔法效果，地狱猎犬就可回复{1}点生命值。", zhTW = "每吞噬一個魔法效果，地獄獵犬就可回復{1}點生命力。" },
	["if an enemy strikes the caster, they may have their movement slowed by #% and the time between their attacks increased by #% for # sec"] = { ko = "시전자를 공격한 적은 일정 확률로 {3}초 동안 이동 속도가 {1}%만큼 감소하고 공격 간격이 {2}%만큼 늘어납니다.", zhCN = "如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低{1}%，攻击间隔延长{2}%，冰冻效果持续{3}秒。", zhTW = "如果敵人使用近戰武器攻擊施法者，他們的移動速度就有可能降低{1}%，攻擊間隔時間延長{2}%，持續{3}秒。" },
	["if cast on a party member, the heal will only jump to other party members"] = { ko = "파티원에게 사용하면 같은 파티원에게만 효과가 전달됩니다.", zhCN = "如果对小队成员施法，则治疗链只会继续治疗其队友。", zhTW = "如果施放在隊伍成員身上，則治療效果只會治療其他的隊伍成員。" },
	["if not cancelled, after # min you will actually die"] = { ko = "취소하지 않으면 {1}분 후에 실제로 사망합니다.", zhCN = "若未取消，在{1}分钟之后你将真正死亡。", zhTW = "如果未取消，你會在{1}分鐘後真的死亡。" },
	["if the hunter takes damage, he will be dazed for # sec"] = { ko = "이 동안 피해를 입게 되면 {1}초 동안 멍해지게 됩니다.", zhCN = "如果猎人受到伤害，则他会眩晕{1}秒。", zhTW = "如果獵人受到傷害，則他會眩暈{1}秒。" },
	["if the target dies from this damage, there is a chance that a doomguard will be summoned"] = { ko = "그 피해로 인해 대상이 죽으면 일정 확률로 파멸의 수호병이 소환됩니다.", zhCN = "如果目标死于该伤害，则有几率召唤一名末日守卫。", zhTW = "如果目標死於該傷害，則有機率召喚出一個末日守衛。" },
	["if the target dies while their soul is stored, they will be able to resurrect with # health and # mana"] = { ko = "만약 영혼이 담겨진 채로 죽게 되면 대상은 {1}의 생명력과 {2}의 마나를 지닌 채로 부활할 수 있습니다." },
	["if the target dies while their soul is stored, they will be able to resurrect with #,# health and # mana"] = { ko = "만약 영혼이 담겨진 채로 죽게 되면 대상은 {1},{2}의 생명력과 {3}의 마나를 지닌 채로 부활할 수 있습니다." },
	["if the target dies within # sec of shadowburn, and yields experience or honor, the caster gains a soul shard"] = { ko = "이 주문이 걸린 지 {1}초 내에 대상이 죽고 경험치나 명예 점수를 받게되면 영혼의 조각 1개를 얻습니다.", zhCN = "如果目标受到暗影灼烧伤害之后的{1}秒内死亡，且施法者因此获得经验值或荣誉，则施法者获得一块灵魂碎片。", zhTW = "如果目標於{1}秒內死於暗影灼燒，且施法者因此獲得經驗值或榮譽，則施法者獲得一塊靈魂碎片。" },
	["if used on a casting target, it will counter the enemy's spellcast, preventing any spell from that school of magic from being cast for # sec"] = { ko = "만약 대상이 주문을 시전중이었다면 주문을 차단하고 {1}초 동안 같은 계열의 주문을 시전하지 못하도록 만듭니다.", zhCN = "如果目标正在施法，则反制该目标的施法意图，使其在{1}秒内无法施放任何与该法术属于同一类别的法术。", zhTW = "如果目標正在施法，反制敵人的法術，使其在{1}秒內無法施放任何與該法術屬於同一類別的法術。" },
	["if you lose the beast's attention for any reason, the taming process will fail"] = { ko = "만약 이 동안 어떤 이유로든 야수의 주의가 딴데로 돌아가게 된다면 길들이는 것은 실패하게 됩니다." },
	["if you repeatedly subjugate the same demon, it will become more difficult to control with each attempt"] = { ko = "같은 악마를 반복해서 예속할 경우, 시도할 때마다 점점 더 통제하기 어려워집니다.", zhCN = "如果你反复征服同一个恶魔，它摆脱控制的几率会越来越大。", zhTW = "如果你重複制伏同一個惡魔，操控惡魔的難度將會隨著制伏次數增加而提高。" },
	["if you spend at least # sec eating, you will become well fed and gain # agility for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 민첩성이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # healing power for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 치유력이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # intellect for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 지능이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # spell damage for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 주문 공격력이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # spirit for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 정신력이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # stamina for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 체력이 {2}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain # strength for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {2}분 동안 힘이 {3}만큼 증가합니다." },
	["if you spend at least # sec eating, you will become well fed and gain #% movement speed while in hyjal for # min"] = { ko = "음식을 꾸준히 {1}초 이상 먹으면 포만감을 느끼게 되고 {2}분 동안 하이잘에서 이동 속도가 {3}%만큼 증가합니다." },
	["if your flame shock is on the target, lava burst deals #% increased damage"] = { ko = "대상에 화염 충격 효과가 걸려 있으면 용암 폭발이 {1}%의 추가 피해를 입힙니다.", zhCN = "如果目标受到你的烈焰震击影响，熔岩爆裂造成的伤害提高{1}%。", zhTW = "若目標已受烈焰震擊影響時，熔岩爆發造成的傷害提高{1}%。" },
	["if your target is not killed by shadow word: death, you take backlash damage equal to #% of your maximum health"] = { ko = "대상이 어둠의 권능: 죽음으로 사망하지 않으면 최대 생명력의 {1}%에 해당하는 반발 피해를 받습니다.", zhCN = "如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值{1}%的伤害反噬。", zhTW = "如果你的目標沒有被暗言術：死所殺害，你會受到相當於你生命力上限{1}%的反傷。" },
	["ignites a target that is already afflicted by your immolate spell, dealing # to # fire damage and consuming your immolate effect"] = { ko = "자신의 제물에 걸린 대상에 사용하여 {1}~{2}의 화염 피해를 입힙니다. 점화를 사용하면 기존 제물의 효과가 사라집니다.", zhCN = "点燃一个已经受到你的献祭法术影响的目标，造成{1}至{2}点火焰伤害，并消耗献祭效果。", zhTW = "點燃一個受到你獻祭影響的目標，造成{1}至{2}點火焰傷害，並消耗你的獻祭效果。" },
	["ignites an incense candle that allows you and others sitting nearby to gain # (below #) · # (below #) · # (below #) · # (below #) · #(above) increased intellect, mutually exclusive with arcane intellect"] = { ko = "향기 나는 양초에 불을 붙여 자신과 주위에 앉은 다른 플레이어의 지능을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}({8}레벨 미만) · {9}(그 위)만큼 증가시킵니다. 신비한 지능과 겸용해서 사용할 수 없습니다.", zhCN = "点燃一根熏香蜡烛，使你和附近坐下的其他人智力提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（{8}级以下） · {9}（更高）点，与奥术智慧不叠加。", zhTW = "點燃一根薰香蠟燭，使你和附近坐下的其他人智力提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（{8}級以下） · {9}（更高）點，與秘法智慧不疊加。" },
	["ignites an incense candle that allows you and others sitting nearby to gain # increased intellect, mutually exclusive with arcane intellect"] = { ko = "향기 나는 양초에 불을 붙여 자신과 주위에 앉은 다른 플레이어의 지능을 {1}만큼 증가시킵니다. 신비한 지능과 겸용해서 사용할 수 없습니다.", zhCN = "点燃一根熏香蜡烛，使你和附近坐下的其他人智力提高{1}点，与奥术智慧不叠加。", zhTW = "點燃一根薰香蠟燭，使你和附近坐下的其他人智力提高{1}點，與秘法智慧不疊加。" },
	["ignites the area surrounding the caster, causing # fire damage to himself and # fire damage to all nearby enemies every # sec"] = { ko = "시전자 주위를 불길로 감싸 매 {3}초마다 시전자에게 {1}의 화염 피해를 입히고 주변의 적에게 {2}의 화염 피해를 입힙니다.", zhCN = "点燃施法者身边的区域，对他自身造成{1}点火焰伤害，并对周围的所有敌人每{3}秒造成{2}点火焰伤害。", zhTW = "點燃施法者身邊的區域，對他自身造成{1}點火焰傷害，並對周圍的所有敵人每{3}秒造成{2}點火焰傷害。" },
	["ignites the area surrounding the caster, causing # fire damage to himself and # fire damage to all nearby enemies every # sec. lasts # sec"] = { ko = "시전자 주위를 불길로 감싸 매 {3}초마다 시전자에게 {1}의 화염 피해를 입히고 주변의 적에게 {2}의 화염 피해를 입힙니다. {4}초 동안 지속됩니다.", zhCN = "点燃施法者身边的区域，对他自身造成{1}点火焰伤害，并对周围的所有敌人每{3}秒造成{2}点火焰伤害。持续{4}秒。", zhTW = "點燃施法者身邊的區域，對他自身造成{1}點火焰傷害，並對周圍的所有敵人每{3}秒造成{2}點火焰傷害。持續{4}秒。" },
	["imbue the shaman's weapon with fire"] = { ko = "주술사의 무기에 불의 기운을 부여합니다." },
	["imbue the shaman's weapon with fire. each hit causes # to # additional fire damage, based on the speed of the weapon. slower weapons cause more fire damage per swing. when applied to main hand, disables any benefit you personally receive from flametongue totem. lasts for # min"] = { ko = "주술사의 무기에 불의 기운을 부여합니다. 공격이 적중할 때마다 무기의 공격 속도에 따라 {1}~{2}의 추가 화염 피해를 입힙니다. 공격 속도가 느린 무기일수록 공격당 화염 피해가 커집니다. 주장비에 부여하면 불꽃의 토템 효과를 자신은 받지 못합니다. {3}분 동안 지속됩니다." },
	["imbue the shaman's weapon with frost"] = { ko = "주술사의 무기에 얼음의 기운을 부여합니다." },
	["imbue the shaman's weapon with frost. each hit has a chance of causing # additional frost damage and slowing the target's movement speed by #% for # sec. lasts for # min"] = { ko = "주술사의 무기에 얼음의 기운을 부여합니다. 주문이 지속되는 동안 주술사의 무기는 매번 공격 시 일정 확률로 {1}의 추가 냉기 피해를 입히고 {3}초 동안 대상의 이동 속도를 {2}%만큼 감소시킵니다. {4}분 동안 지속됩니다.", zhCN = "以冰霜的力量加强萨满祭司的武器，每次击中敌人都有一定几率造成{1}点额外的冰霜伤害，并使目标的移动速度降低{2}%，减速效果持续{3}秒。冰封武器效果持续{4}分钟。", zhTW = "以冰霜的力量加強薩滿的武器，每次擊中敵人都有一定機率造成{1}點額外的冰霜傷害，並使目標的移動速度降低{2}%，持續{3}秒。持續{4}分鐘。" },
	["imbue the shaman's weapon with wind"] = { ko = "주술사의 무기에 바람의 기운을 부여합니다.", zhCN = "以风的力量强化萨满祭司的武器。" },
	["imbue the shaman's weapon with wind. each hit has a #% chance of granting you # extra attacks with # extra melee attack power. when appied to main hand, disables any benefit you personally receive from windfury totem. lasts for # min"] = { ko = "주술사의 무기에 바람의 기운을 부여합니다. 매 공격 시 {1}%의 확률로 근접 전투력이 {3}만큼 증가한 상태에서 {2}회의 추가 공격을 가합니다. 주무기에 부여하면 질풍의 토템으로 얻는 이로운 효과가 비활성화됩니다. {4}분 동안 지속됩니다.", zhCN = "以风的力量强化萨满祭司的武器。每次击中敌人都有{1}%的几率使你获得额外的{2}次攻击，且这些攻击的近战攻击强度提高{3}点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续{4}分钟。", zhTW = "以風的力量加強薩滿的武器，每次命中敵人時都有{1}%的機率使你額外造成{2}次攻擊，這些攻擊獲得額外{3}點近戰攻擊強度。施加於主手武器時，會停用你個人從風怒圖騰獲得的增益效果。持續{4}分鐘。" },
	["imbue the shaman's weapon with wind. each hit has a #% chance of granting you # extra attacks with # extra melee attack power. when applied to main hand, disables any benefit you personally receive from windfury totem. lasts for # min"] = { ko = "주술사의 무기에 바람의 기운을 부여합니다. 매 공격 시 {1}%의 확률로 근접 전투력이 {3}만큼 증가한 상태에서 {2}회의 추가 공격을 가합니다. 주무기에 부여하면 질풍의 토템으로 얻는 이로운 효과가 비활성화됩니다. {4}분 동안 지속됩니다.", zhCN = "以风的力量强化萨满祭司的武器。每次击中敌人都有{1}%的几率使你获得额外的{2}次攻击，且这些攻击的近战攻击强度提高{3}点。应用于主手时，会使你无法从风怒图腾获得个人收益。持续{4}分钟。", zhTW = "以風的力量加強薩滿的武器，每次命中敵人時都有{1}%的機率使你額外造成{2}次攻擊，這些攻擊獲得額外{3}點近戰攻擊強度。施加於主手武器時，會停用你個人從風怒圖騰獲得的增益效果。持續{4}分鐘。" },
	["imbue the shaman's weapon, increasing melee attack power by # and allowing melee attacks to cause additional threat when using that weapon"] = { zhCN = "强化萨满祭司的武器，使其近战攻击强度提高{1}点，使用该武器对敌人造成近战伤害时产生额外的威胁值。", zhTW = "強化薩滿的武器，使近戰攻擊強度提高{1}點，使用該武器對敵人造成近戰傷害時產生額外的威脅值。" },
	["imbue the shaman's weapon, increasing melee attack power by # and allowing melee attacks to cause additional threat when using that weapon. lasts for # min"] = { ko = "주술사의 무기에 일시적으로 대지의 기운을 부여합니다. 주문이 지속되는 동안 근접 전투력이 {1}만큼 증가하며 위협 수준이 추가로 증가합니다. {2}분 동안 지속됩니다.", zhCN = "强化萨满祭司的武器，使其近战攻击强度提高{1}点，使用该武器对敌人造成近战伤害时产生额外的威胁值。强化效果持续{2}分钟。", zhTW = "強化薩滿的武器，使近戰攻擊強度提高{1}點，使用該武器對敵人造成近戰傷害時產生額外的威脅值。持續{2}分鐘。" },
	["imp - increases fire damage done by #%"] = { ko = "임프 - 화염 공격력이 {1}%만큼 증가합니다.", zhCN = "小鬼 - 火焰伤害提高{1}%。", zhTW = "小鬼 - 造成的火焰傷害提高{1}%。" },
	["imp: increases your shadow damage by #%"] = { ko = "임프: 암흑 공격력이 {1}%만큼 증가합니다.", zhCN = "小鬼：使你的暗影伤害提高{1}%。", zhTW = "小鬼：使你的暗影傷害提高{1}%。" },
	["improves your chance to get a critical strike with all spells and attacks by #%"] = { ko = "모든 주문과 공격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的所有法术和攻击的爆击几率提高{1}%。", zhTW = "使你的所有攻擊和法術造成致命一擊的機率提高{1}%。" },
	["improves your chance to get a critical strike with melee attacks by #%"] = { ko = "근접 공격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的近战攻击造成爆击的几率提高{1}%。", zhTW = "使你的近戰攻擊造成致命一擊的機率提高{1}%。" },
	["improves your chance to hit by #%"] = { ko = "무기의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你击中目标的几率提高{1}%。", zhTW = "使你的命中機率提高{1}%。" },
	["improves your chance to hit by #% and reduces all threat you generate by #%"] = { ko = "적중률이 {1}%만큼 증가하고 모든 위협 수준 생성량이 {2}%만큼 감소합니다.", zhCN = "使你的命中几率提高{1}%，并使你产生的所有威胁降低{2}%。", zhTW = "使你的命中機率提高{1}%，且你產生的所有威脅值降低{2}%。" },
	["improves your chance to hit with arcane spells by #%"] = { ko = "비전 주문의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的奥术法术命中几率提高{1}%。", zhTW = "你秘法法術的命中機率提高{1}%。" },
	["improves your chance to hit with frost and fire spells by #%"] = { ko = "냉기 및 화염 주문의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的冰霜和火焰法术命中几率提高{1}%。", zhTW = "你冰霜和火焰法術的命中機率提高{1}%。" },
	["improves your chance to hit with holy spells by #%"] = { ko = "신성 주문의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的神圣法术命中几率提高{1}%。", zhTW = "使你的神聖法術命中機率提高{1}%。" },
	["improves your chance to hit with shadow spells by #%"] = { ko = "암흑 주문의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的暗影法术命中几率提高{1}%。", zhTW = "你暗影法術的命中機率提高{1}%。" },
	["in a whirlwind of steel you attack up to # enemies within # yards, causing weapon damage to each enemy"] = { ko = "강철의 소용돌이가 주위를 휩쓸어 {2}미터 반경의 최대 {1}명의 적에게 무기 공격력만큼의 피해를 입힙니다.", zhCN = "像旋风一般挥舞手中的武器，攻击半径{2}码范围内的最多{1}个敌人，对它们造成武器伤害。", zhTW = "像旋風一般揮舞手中的武器，攻擊半徑{2}碼範圍內的最多{1}個敵人，對它們造成武器傷害。" },
	["in addition, both the demon and the master will inflict #% more damage"] = { ko = "추가로 흑마법사와 소환수의 공격력이 {1}%만큼 증가합니다.", zhCN = "此外，恶魔和主人造成的伤害都提高{1}%。", zhTW = "另外，惡魔和其主人造成的傷害皆提高{1}%。" },
	["in addition, conflagrate has a #% chance not to consume immolate, and shadowburn has a #% chance to instantly refund a soul shard"] = { ko = "추가로, 점화가 {1}%의 확률로 제물을 소모하지 않고, 어둠의 연소가 {2}%의 확률로 영혼의 조각을 즉시 돌려줍니다.", zhTW = "此外，焚燒有{1}%機率不會消耗獻祭，且暗影灼燒有{2}%機率會立即返還一個靈魂裂片。" },
	["in addition, gives your frost ward a #% chance to reflect frost spells and effects while active"] = { ko = "추가로 냉기계 수호가 활성화되어 있는 동안 {1}%의 확률로 냉기 주문을 반사합니다.", zhCN = "此外，你的防护冰霜结界激活时有{1}%的几率反射冰霜法术和效果。", zhTW = "另外，你的防護冰霜結界有{1}%的機率將冰霜系法術和魔法效果反射給施法者。" },
	["in addition, slam no longer interrupts or delays your melee swing and slam's cooldown is reduced by # sec"] = { ko = "또한 격돌을 사용해도 근접 공격이 방해받거나 지연되지 않으며, 격돌의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "此外，猛击不再打断或延迟你的近战挥击计时，且猛击的冷却时间缩短{1}秒。", zhTW = "此外，猛擊不再中斷或延遲你的近戰揮擊，且猛擊的冷卻時間縮短{1}秒。" },
	["in addition, when the target blocks a melee attack the attacker will take # holy damage"] = { ko = "추가로 근접 공격을 방어할 경우 공격자에게 {1}의 신성 피해를 입힙니다.", zhCN = "另外，当目标格挡一次近战攻击时，攻击者会受到{1}点神圣伤害。", zhTW = "另外，當目標格擋一次近戰攻擊時，攻擊者會受到{1}點神聖傷害。" },
	["in addition, when you kill a non-trivial enemy or it dies while afflicted by your serpent sting, you gain rapid killing, increasing the damage of your next shot ability within # sec by #%"] = { ko = "또한 사소하지 않은 적을 처치하거나 해당 적이 자신의 독사 쐐기에 걸린 상태로 사망하면 신속한 사냥이 부여되어 {1}초 안에 사용하는 다음 사격 능력의 공격력이 {2}%만큼 증가합니다.", zhCN = "此外，当你消灭一个能为你提供经验值或荣誉值的敌人，或其在受到你的毒蛇钉刺影响时死亡，你获得疾速杀戮，使你在{1}秒内的下一个射击技能造成的伤害提高{2}%。", zhTW = "此外，如果你擊殺有實力的敵人，或該敵人在受你毒蛇釘刺影響時死亡，你會獲得急速殺戮，使你在{1}秒內施放的下一個射擊技能的傷害提高{2}%。" },
	["in addition, while in bear form or dire bear form your stamina is increased by #% and while in cat form your strength is increased by #%"] = { ko = "추가로 곰 변신이나 광포한 곰 변신 상태에서 체력이 {1}%만큼, 표범 변신 상태에서 힘이 {2}%만큼 증가합니다.", zhCN = "此外，在熊形态或巨熊形态下，耐力提高{1}%；在猎豹形态下，力量提高{2}%。", zhTW = "另外，在熊形態或巨熊形態下，你的耐力提高{1}%，在獵豹形態下，你的力量提高{2}%。" },
	["in addition, your critical strikes have a #% chance to allow #% of your mana regeneration to continue while casting for # sec"] = { ko = "또한 치명타 발생 시 {1}%의 확률로 {3}초 동안 시전 중에도 평소의 {2}%에 달하는 속도로 마나가 회복됩니다." },
	["in addition, your non-periodic critical strikes from cat form abilities that generate combo points have a #% chance to add an additional combo point"] = { ko = "또한 연계 점수를 생성하는 표범 변신 능력이 비주기적인 치명타 및 극대화 효과를 발휘하면 {1}%의 확률로 추가 연계 점수를 생성합니다.", zhCN = "此外，你的猎豹形态下可产生连击点数的技能的非周期性爆击有{1}%的几率额外增加一个连击点数。", zhTW = "此外，而在獵豹形態時可產生連擊點數的非週期性效果造成致命一擊後，有{1}%的機率再獲取一個額外的連擊點數。" },
	["in order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete"] = { ko = "의식에 참가하려는 플레이어는 비전투 상태여야 하며 소환의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhCN = "所有参与召唤的队友都必须使用右键点击传送门，并且在召唤完成之前不得移动。", zhTW = "所有參與召喚的隊友都必須必須離開交戰狀態並使用右鍵點擊傳送門，並且在召喚完成之前不得移動。" },
	["in order to participate, all players must right-click the portal and not move until the ritual is complete"] = { ko = "의식에 참가하려는 플레이어는 파멸의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhTW = "所有參與者都必須使用右鍵點擊傳送門，並且在完成儀式之前不得移動。" },
	["incapacitates the target for up to # sec"] = { ko = "대상을 최대 {1}초 동안 행동 불가 상태로 만듭니다.", zhCN = "使目标瘫痪，最多持续{1}秒。", zhTW = "使目標癱瘓最多{1}秒。" },
	["incapacitates the target for up to # sec. only works on humanoids that are not in combat. any damage taken will break the effect. only # target may be sapped at a time. does not break stealth"] = { ko = "대상을 최대 {1}초 동안 행동 불가 상태로 만듭니다. 비전투 상태의 인간형 몬스터에게만 유효합니다. 대상이 피해를 받으면 효과가 해제됩니다. 동시에 한 대상만 혼절시킬 수 있습니다. 은신이 해제되지 않습니다.", zhCN = "使目标瘫痪，最多持续{1}秒。只对未进入战斗状态的人型生物有效。受到任何伤害都会打破该效果。同一时间只能闷棍{2}个目标。不会取消潜行。", zhTW = "使目標癱瘓最多{1}秒。只能使用於非戰鬥狀態下的人形生物。受到任何傷害都會中斷此效果。每個盜賊同一時間內只能用悶棍癱瘓一個目標。不會取消潛行狀態。" },
	["increase experience gained from slaying undead by #% for # min"] = { ko = "{2}분 동안 언데드를 처치하고 얻는 경험치가 {1}%만큼 증가합니다.", zhCN = "击杀亡灵获得的经验值提高{1}%，持续{2}分钟。", zhTW = "殺死不死生物獲得的經驗值提高{1}%，持續{2}分鐘。" },
	["increases all damage dealt by #% against humanoid and giant targets"] = { ko = "인간형 및 거인 대상에 대한 모든 공격력이 {1}%만큼 증가합니다.", zhCN = "对人型和巨人目标造成的所有伤害提高{1}%。", zhTW = "對人形生物和巨人目標造成的所有傷害提高{1}%。" },
	["increases all damage done by your imp, voidwalker, succubus, incubus, and felhunter pets by #%"] = { ko = "임프와 보이드워커, 서큐버스, 인큐버스, 지옥사냥개의 모든 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的小鬼、虚空行者、魅魔、夜魔和地狱猎犬宠物造成的所有伤害提高{1}%。", zhTW = "使你的小鬼、虛無行者、魅魔、夢魔和惡魔獵犬造成的所有傷害提高{1}%。" },
	["increases all damage you and your pet deal by #% while your pet is active"] = { ko = "야수가 활성화된 동안 자신과 야수의 모든 공격력이 {1}%만큼 증가합니다.", zhCN = "宠物激活时，使你和宠物造成的所有伤害提高{1}%。", zhTW = "寵物處於活動狀態時，使你和寵物造成的所有傷害提高{1}%。" },
	["increases all damage you deal by #% while a shield is equipped"] = { ko = "방패를 착용한 동안 모든 공격력이 {1}%만큼 증가합니다.", zhCN = "装备盾牌时，你造成的所有伤害提高{1}%。", zhTW = "裝備盾牌時，你造成的所有傷害提高{1}%。" },
	["increases all periodic damage done by your warlock spells by #%"] = { ko = "흑마법사 주문이 입히는 모든 주기적인 피해가 {1}%만큼 증가합니다.", zhCN = "使你的术士法术造成的所有周期性伤害提高{1}%。", zhTW = "使你術士法術造成的所有週期性傷害提高{1}%。" },
	["increases all the rage generated by your bloodrage ability by #%"] = { ko = "피의 분노로 생성되는 모든 분노가 {1}%만큼 증가합니다.", zhCN = "使你的血性狂暴技能产生的所有怒气提高{1}%。", zhTW = "使你的血性狂暴技能產生的所有怒氣提高{1}%。" },
	["increases all threat generated by #%"] = { ko = "모든 위협 수준 생성량이 {1}%만큼 증가합니다.", zhCN = "产生的所有威胁值提高{1}%。", zhTW = "產生的所有威脅值提高{1}%。" },
	["increases all threat generated in defensive stance by an additional #% while a shield is equipped"] = { ko = "방패를 장착한 동안 방어 태세일 때 생성하는 모든 위협 수준이 {1}%만큼 추가로 증가합니다.", zhCN = "装备盾牌时，在防御姿态下产生的所有威胁值额外提高{1}%。", zhTW = "你裝備盾牌時，在防禦姿態下產生的所有威脅值額外提高{1}%。" },
	["increases all your resistances by # and causes all spells you fully resist to restore #% of your total mana"] = { ko = "모든 마법 저항력이 {1}만큼 증가하고, 시전자가 주문에 완전히 저항할 때마다 전체 마나의 {2}%를 회복합니다.", zhCN = "使你的所有抗性提高{1}点，并使你完全抵抗的法术恢复最大法力值的{2}%。", zhTW = "你的所有抗性提高{1}點，使你在完全抵抗任何法術後可以恢復總法力的{2}%。" },
	["increases all your resistances by # and causes all spells you fully resist to restore #% of your total mana. cannot trigger more often than # time per sec"] = { ko = "모든 마법 저항력이 {1}만큼 증가하고, 시전자가 주문에 완전히 저항할 때마다 전체 마나의 {2}%를 회복합니다. {3}초마다 한 번씩만 발동합니다.", zhCN = "使你的所有抗性提高{1}点，并使你完全抵抗的法术恢复最大法力值的{2}%。每秒最多触发一次。", zhTW = "你的所有抗性提高{1}點，使你在完全抵抗任何法術後可以恢復總法力的{2}%。每秒只能觸發{3}次。" },
	["increases armor by #"] = { zhCN = "使护甲值提高{1}点。", zhTW = "使護甲值提高{1}點。" },
	["increases armor by # and frost resistance by #"] = { ko = "방어도를 {1}만큼, 냉기 저항력을 {2}만큼 증가시킵니다.", zhCN = "使护甲值提高{1}点，冰霜抗性提高{2}点。", zhTW = "使護甲值提高{1}點，冰霜抗性提高{2}點。" },
	["increases armor by # and frost resistance by # if an enemy strikes the caster, they may have their movement slowed by #% and the time between their attacks increased by #% for # sec. only one type of armor spell can be active on the mage at any time. lasts # min"] = { ko = "방어도를 {1}만큼, 냉기 저항력을 6만큼 증가시킵니다. 시전자를 공격한 적은 일정 확률로 {5}초 동안 이동 속도가 {3}%만큼 감소하고 공격 간격이 {4}%만큼 늘어납니다. 마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다. {6}분 동안 지속됩니다.", zhCN = "使护甲值提高{1}点，冰霜抗性提高6点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低{3}%，攻击间隔延长{4}%，持续{5}秒。法师在同一时间内只能保有一种魔法护甲效果。持续{6}分钟。", zhTW = "使護甲值提高{1}點，冰霜抗性提高6點。如果敵人使用近戰武器攻擊施法者，他們的移動速度就有可能被降低{3}%，攻擊間隔時間延長{4}%，持續{5}秒。同一時間內法師只能擁有一種護甲法術。冰甲術可持續{6}分鐘。" },
	["increases armor by # if an enemy strikes the caster, they may have their movement slowed by #% and the time between their attacks increased by #% for # sec. only one type of armor spell can be active on the mage at any time. lasts # min"] = { ko = "방어도가 {2}만큼 증가하고 시전자를 공격한 적은 일정 확률로 {4}초 동안 이동 속도가 {5}%만큼 감소하며 공격 간격이 {3}%만큼 늘어날 수 있습니다. 마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다. 30분 동안 지속됩니다.", zhCN = "使护甲值提高{2}点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低{5}%，攻击间隔延长{3}%，冰冻效果持续{4}秒。法师在同一时间内只能保有一种魔法护甲效果。持续30分钟。", zhTW = "使護甲值提高{2}點。如果敵人使用近戰武器攻擊施法者，他們的移動速度就有可能降低{5}%，攻擊間隔時間延長{3}%，持續{4}秒。同一時間內法師只能擁有一種護甲法術。霜甲術可持續30分鐘。" },
	["increases attack power by # for # sec"] = { ko = "{2}초 동안 전투력이 {1}만큼 증가합니다.", zhCN = "攻击强度提高{1}点，持续{2}秒。", zhTW = "攻擊強度提高{1}點，持續{2}秒。" },
	["increases attack power by # for # sec. this effect is doubled in volcanic areas"] = { ko = "{2}초 동안 전투력이 {1}만큼 증가합니다. 화산 지역에서는 효과가 2배로 증가합니다.", zhCN = "攻击强度提高{1}点，持续{2}秒。在火山区域时，攻击强度加成翻倍。", zhTW = "攻擊強度提高{1}點，持續{2}秒。在火山區域時，攻擊強度加成翻倍。" },
	["increases chance to block by #% for # sec, and deals # holy damage for each attack blocked while active"] = { ko = "{2}초 동안 방패 막기 확률이 {1}%만큼 증가하며, 효과가 활성화된 동안 공격을 방패로 막을 때마다 공격자에게 {3}의 신성 피해를 입힙니다.", zhTW = "使你的格擋機率提高{1}%，持續{2}秒，在此期間每次成功格擋都會對攻擊者造成{3}點神聖傷害。" },
	["increases chance to block by #% for # sec, and deals # holy damage for each attack blocked while active. damage caused by holy shield causes #% additional threat"] = { ko = "{2}초 동안 방패 막기 확률이 {1}%만큼 증가하며, 효과가 활성화된 동안 공격을 방패로 막을 때마다 공격자에게 {3}의 신성 피해를 입힙니다. 신성한 방패로 입히는 피해는 위협 수준을 {4}%만큼 추가로 생성합니다.", zhCN = "使你的格挡几率提高{1}%，持续{2}秒。在此期间每次成功格挡都会对攻击者造成{3}点神圣伤害。神圣之盾造成的伤害额外产生{4}%的威胁值。", zhTW = "使你的格擋機率提高{1}%，持續{2}秒，在此期間每次成功格擋都會對攻擊者造成{3}點神聖傷害。神聖之盾造成的傷害產生的威脅值提高{4}%。" },
	["increases chance to block by #% for # sec, and deals # holy damage for each attack blocked while active. damage caused by holy shield causes #% additional threat. each block expends a charge. # charges"] = { ko = "{2}초 동안 방패 막기 확률이 {1}%만큼 증가하며, 효과가 활성화된 동안 공격을 방패로 막을 때마다 공격자에게 {3}의 신성 피해를 입힙니다. 신성한 방패로 입히는 피해는 위협 수준을 {4}%만큼 추가로 생성합니다. 막을 때마다 충전 횟수를 1회 소모합니다. {5}회 충전됩니다.", zhCN = "使你的格挡几率提高{1}%，持续{2}秒。在此期间每次成功格挡都会对攻击者造成{3}点神圣伤害。神圣之盾造成的伤害额外产生{4}%的威胁值。每次格挡消耗一层充能。共{5}层。", zhTW = "使你的格擋機率提高{1}%，持續{2}秒，在此期間每次成功格擋都會對攻擊者造成{3}點神聖傷害。神聖之盾造成的傷害產生的威脅值提高{4}%。每次成功格擋會消耗掉一次格擋機會，最多可格擋{5}次。" },
	["increases chance to block by #% for # sec, but will only block # attacks"] = { ko = "{2}초 동안 적의 공격을 방어할 확률이 {1}%만큼 증가합니다. 단, {3}회만 방어할 수 있습니다.", zhCN = "使你的格档几率提高{1}%，效果持续{2}秒。最多只能格档{3}次攻击。", zhTW = "使你的格擋機率提高{1}%，效果持續{2}秒。最多只能格擋{3}次攻擊。" },
	["increases damage and healing done by magical spells and effects by up to #"] = { ko = "마법 주문 및 효과로 입히는 피해와 치유량이 최대 {1}만큼 증가합니다.", zhCN = "提高法术和魔法效果所造成的伤害和治疗效果，最多{1}点。", zhTW = "提高法術和魔法效果所造成的傷害和治療效果，最多{1}點。" },
	["increases damage dealt by your revenge ability by #%"] = { ko = "복수의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的复仇技能造成的伤害提高{1}%。", zhTW = "你復仇技能造成的傷害提高{1}%。" },
	["increases damage done by frost spells and effects by up to #"] = { ko = "냉기 계열의 주문과 효과의 공격력이 최대 {1}만큼 증가합니다.", zhCN = "提高冰霜法术和效果所造成的伤害，最多{1}点。", zhTW = "提高冰霜法術和效果所造成的傷害，最多{1}點。" },
	["increases damage done by your melee abilities on bleeding targets by #%"] = { ko = "출혈 상태인 대상에게 근접 능력으로 입히는 피해가 {1}%만큼 증가합니다.", zhCN = "使你的近战技能对流血目标造成的伤害提高{1}%。", zhTW = "使你近戰技能對流血目標造成的傷害提高{1}%。" },
	["increases damage done by your swipe ability by #% and reduces the chance enemies have to detect you while prowling as if you were # level higher"] = { ko = "휘둘러치기로 입히는 피해가 {1}%만큼 증가하며 숨은 상태에서 은신 효과가 {2}레벨만큼 증가합니다.", zhCN = "使你的挥击造成的伤害提高{1}%，并在潜行时使敌人侦测到你的几率降低，效果相当于你高出{2}级。", zhTW = "使你揮擊技能造成的傷害提高{1}%，並在你潛行時降低敵人偵測到你的機率，效果相當於你的等級高{2}級。" },
	["increases damage done by your swipe ability by #% and reduces the chance enemies have to detect you while prowling as if you were # levels higher"] = { ko = "휘둘러치기로 입히는 피해가 {1}%만큼 증가하며 숨은 상태에서 은신 효과가 {2}레벨만큼 증가합니다.", zhCN = "使你的挥击造成的伤害提高{1}%，并在潜行时使敌人侦测到你的几率降低，效果相当于你高出{2}级。", zhTW = "使你揮擊技能造成的傷害提高{1}%，並在你潛行時降低敵人偵測到你的機率，效果相當於你的等級高{2}級。" },
	["increases frost and shadow spell damage done by up to # for # sec"] = { ko = "{2}초 동안 냉기 및 암흑 주문 공격력이 최대 {1}만큼 증가합니다.", zhCN = "使冰霜和暗影法术造成的伤害提高最多{1}点，持续{2}秒。", zhTW = "使冰霜和暗影法術造成的傷害最多提高{1}點，持續{2}秒。" },
	["increases frost and shadow spell damage done by up to # for # sec. this effect is doubled in snowy areas"] = { ko = "{2}초 동안 냉기 및 암흑 주문 공격력이 최대 {1}만큼 증가합니다. 설원 지역에서는 효과가 2배로 증가합니다.", zhCN = "使冰霜和暗影法术造成的伤害提高最多{1}点，持续{2}秒。在雪地区域时，该效果翻倍。", zhTW = "使冰霜和暗影法術造成的傷害最多提高{1}點，持續{2}秒。此效果在雪地區域加倍。" },
	["increases healing done by up to # and damage done by up to # for all magical spells and effects"] = { ko = "모든 마법 주문 및 효과에 의한 치유량이 최대 {1}만큼, 주문 공격력이 최대 {2}만큼 증가합니다.", zhCN = "提高所有法术和魔法效果所造成的治疗效果，最多{1}点，伤害效果最多{2}点。", zhTW = "提高所有法術和魔法效果所造成的治療效果，最多{1}點，傷害效果最多{2}點。" },
	["increases health drained or damage done by your drain life, drain soul, and wrack spells by #%"] = { ko = "생명력 흡수, 영혼 흡수, 파멸의 생명력 흡수량 또는 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的吸取生命、吸取灵魂和折磨法术造成的伤害或吸取的生命提高{1}%。", zhTW = "吸取生命、吸取靈魂，以及毀壞法術造成的傷害或吸取的生命力提高{1}%。" },
	["increases movement speed and mounted movement speed by #%"] = { ko = "이동 속도와 탈것의 이동 속도가 {1}%만큼 증가합니다.", zhCN = "使你的移动速度和坐骑移动速度提高{1}%。", zhTW = "使你的移動速度和坐騎移動速度提高{1}%。" },
	["increases movement speed and mounted movement speed by #%. this does not stack with other movement speed increasing effects"] = { ko = "이동 속도와 탈것의 이동 속도가 {1}%만큼 증가합니다. 다른 이동 속도 증가 효과와 중복 적용되지 않습니다.", zhCN = "使你的移动速度和坐骑移动速度提高{1}%。这个效果不与其它同类效果叠加。", zhTW = "使你的移動速度和坐騎移動速度提高{1}%。此效果無法與其他移動速度提高效果堆疊。" },
	["increases movement speed by #% for # sec"] = { ko = "{2}초 동안 이동 속도가 {1}%만큼 증가합니다.", zhCN = "移动速度提高{1}%，持续{2}秒。", zhTW = "移動速度提高{1}%，持續{2}秒。" },
	["increases movement speed by #% for # sec. does not break prowling"] = { ko = "{2}초 동안 이동 속도가 {1}%만큼 증가합니다. 숨기 효과가 풀리지 않습니다.", zhCN = "使你的移动速度提高{1}%，持续{2}秒。不会打断潜行效果。", zhTW = "提高移動速度{1}%，持續{2}秒。不會打斷潛行。" },
	["increases party members' stamina by #"] = { ko = "파티원의 체력을 {1}만큼 증가시킵니다.", zhCN = "使小队成员的耐力提高{1}点。", zhTW = "使小隊成員的耐力提高{1}點。" },
	["increases physical damage by # for # min"] = { ko = "{2}분 동안 물리 공격력이 {1}만큼 증가합니다.", zhCN = "物理伤害提高{1}点，持续{2}分钟。", zhTW = "使物理傷害提高{1}點，持續{2}分鐘。" },
	["increases ranged and melee attack speed by #% for # sec"] = { ko = "{2}초 동안 원거리 및 근접 공격 속도가 {1}%만큼 증가합니다.", zhCN = "远程和近战攻击速度提高{1}%，持续{2}秒。", zhTW = "遠程和近戰攻擊速度提高{1}%，持續{2}秒。" },
	["increases run speed by #% for # sec"] = { ko = "{2}초 동안 달리기 속도가 {1}%만큼 증가합니다.", zhCN = "使你的奔跑速度提高{1}%，持续{2}秒。", zhTW = "使你的奔跑速度提高{1}%，持續{2}秒。" },
	["increases shadow word: death's critical strike chance on targets at or below #% health by #%"] = { ko = "생명력이 {1}% 이하인 대상에게 사용하는 어둠의 권능: 죽음의 치명타 및 극대화율이 {2}%만큼 증가합니다.", zhCN = "对生命值等于或低于{1}%的目标，使暗言术：灭的爆击几率提高{2}%。", zhTW = "使暗言術：死對生命力低於{1}%的目標造成致命一擊的機率提高{2}%。" },
	["increases spell damage by # against elementals"] = { ko = "정령에게 주문으로 입히는 피해가 {1}만큼 증가합니다." },
	["increases spell damage by # against elementals. lasts # min"] = { ko = "정령에게 주문으로 입히는 피해가 {1}만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "对元素生物的法术伤害提高{1}点，持续{2}分钟。", zhTW = "對元素生物的法術傷害提高{1}點，持續{2}分鐘。" },
	["increases spell damage by # for # sec"] = { ko = "{2}초 동안 주문 공격력이 {1}만큼 증가합니다.", zhCN = "法术伤害提高{1}点，持续{2}秒。", zhTW = "提高{1}點法術傷害，持續{2}秒。" },
	["increases spell damage by up to # for # min"] = { ko = "{2}분 동안 주문 공격력이 최대 {1}만큼 증가합니다.", zhCN = "法术伤害提高最多{1}点，持续{2}分钟。", zhTW = "使法術傷害最多提高{1}點，持續{2}分鐘。" },
	["increases spell healing by # for # sec"] = { ko = "{2}초 동안 주문 치유가 {1}만큼 증가합니다.", zhCN = "法术治疗效果提高{1}点，持续{2}秒。", zhTW = "使法術治療效果提高{1}點，持續{2}秒。" },
	["increases spirit by #%"] = { ko = "정신력이 {1}%만큼 증가합니다.", zhCN = "精神提高{1}%。", zhTW = "精神提高{1}%。" },
	["increases stealth detection and shows hidden units within detection range on the minimap"] = { ko = "은신 감지가 증가하고 감지 범위 내에 있는 은신 물체를 미니맵에 표시합니다.", zhCN = "提高潜行侦测能力，并在微缩地图上显示侦测范围内的隐藏生物。", zhTW = "提高潛行偵測能力，並在小地圖上顯示偵測範圍內的隱藏生物。" },
	["increases stealth detection and shows hidden units within detection range on the minimap. only one form of tracking can be active at a time"] = { ko = "은신 감지가 증가하고 감지 범위 내에 있는 은신 물체를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "提高潜行侦测能力，并在微缩地图上显示侦测范围内的隐藏生物。同一时间内只能激活一种追踪技能。", zhTW = "提高潛行偵測能力，並在小地圖上顯示偵測範圍內的隱藏生物。同一時間內只能啟動一種追蹤技能。" },
	["increases the amount healed by your healing wave spell by #%"] = { ko = "치유의 물결 주문으로 회복되는 생명력이 {1}%만큼 증가합니다.", zhCN = "治疗波的效果提高{1}%。", zhTW = "使你治療波的治療量提高{1}%。" },
	["increases the amount healed by your holy light, flash of light, and holy shock spells by #%"] = { ko = "성스러운 빛과 빛의 섬광, 신성 충격으로 치유되는 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的圣光术、圣光闪现和神圣震击的治疗量提高{1}%。", zhTW = "使你的聖光術、聖光閃現和神聖震擊的治療效果提高{1}%。" },
	["increases the amount healed by your renew spell by #%"] = { ko = "소생으로 치유되는 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的恢复法术的治疗效果提高{1}%。", zhTW = "使你的恢復法術的治療效果提高{1}%。" },
	["increases the amount healed by your spells by #%"] = { ko = "주문으로 회복되는 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的法术治疗量提高{1}%。", zhTW = "使你法術的治療效果提高{1}%。" },
	["increases the amount of damage absorbed by your shield by #%, and gives your blocks a #% chance to restore #% of your maximum mana"] = { zhCN = "使你的盾牌吸收的伤害提高{1}%，并使你的格挡有{2}%的几率恢复最大法力值的{3}%。", zhTW = "使你盾牌吸收的傷害值提高{1}%，且格擋時，有{2}%的機率恢復法力上限{3}%的法力。" },
	["increases the amount of damage absorbed by your shield by #%, and gives your blocks a #% chance to restore #% of your maximum mana. may only occur once every # sec"] = { ko = "방패의 피해 흡수량이 {1}%만큼 증가합니다. 또한 방패 막기 성공 시 {2}%의 확률로 최대 마나의 {3}%를 회복합니다. {4}초에 한 번씩만 발동합니다.", zhCN = "使你的盾牌吸收的伤害提高{1}%，并使你的格挡有{2}%的几率恢复最大法力值的{3}%。每{4}秒最多触发一次。", zhTW = "使你盾牌吸收的傷害值提高{1}%，且格擋時，有{2}%的機率恢復法力上限{3}%的法力。每{4}秒只能觸發一次。" },
	["increases the amount of damage reduced by your stoneskin totem and windwall totem by #% and reduces the cooldown of your grounding totem by # sec"] = { ko = "돌가죽 토템, 바람막이 토템으로 인해 감소되는 피해가 {1}%만큼 증가하고 마법정화 토템의 재사용 대기시간이 {2}초만큼 단축됩니다.", zhCN = "使你的石肤图腾和风墙图腾所能吸收的伤害提高{1}%，根基图腾的冷却时间减少{2}秒。", zhTW = "使你的石甲圖騰和風牆圖騰所能降低的傷害提高{1}%，並使根基圖騰的冷卻時間縮短{2}秒。" },
	["increases the amount of health transferred by your health funnel spell by #%, reduces its health cost by #%, and reduces all threat your health funnel generates by #%"] = { zhCN = "使你的生命通道转移的生命值提高{1}%，生命值消耗降低{2}%，并使生命通道产生的所有威胁降低{3}%。", zhTW = "使你生命通道法術所傳送的生命力提高{1}%，其生命力消耗降低{2}%，並使你生命通道產生的所有威脅值降低{3}%。" },
	["increases the amount of health transferred by your health funnel spell by #%, reduces its health cost by #%, and reduces all threat your health funnel generates by #%. allows health funnel to be used regardless of your demon's health"] = { ko = "생명력 집중으로 이전되는 생명력이 {1}%만큼 증가하고 소비되는 생명력이 {2}%만큼 감소합니다. 또한 생명력 집중의 모든 위협 수준 생성량이 {3}%만큼 감소합니다. 악마의 생명력에 상관없이 생명력 집중을 사용할 수 있습니다.", zhCN = "使你的生命通道转移的生命值提高{1}%，生命值消耗降低{2}%，并使生命通道产生的所有威胁降低{3}%。无论恶魔的生命值如何都可以使用生命通道。", zhTW = "使你生命通道法術所傳送的生命力提高{1}%，其生命力消耗降低{2}%，並使你生命通道產生的所有威脅值降低{3}%。可無視惡魔的生命力隨時使用生命通道。" },
	["increases the amount of mana awarded by your life tap spell by #%"] = { ko = "생명력 전환으로 얻는 마나가 {1}%만큼 증가합니다.", zhCN = "使你的生命分流法术所转化的法力值提高{1}%。", zhTW = "使你的生命分流法術所轉化的法力提高{1}%。" },
	["increases the area of effect of your shouts by #% and reduces their rage cost by #%"] = { ko = "외침의 효과 범위가 {1}%만큼 증가하고, 외침에 소비되는 분노가 {2}%만큼 감소합니다." },
	["increases the armor and resistance given by your frost armor and ice armor spells by #%"] = { ko = "냉기 갑옷과 얼음 갑옷으로 증가하는 방어도와 저항력이 {1}%만큼 증가합니다.", zhCN = "使你的霜甲术和冰甲术提供的护甲和抗性提高{1}%。", zhTW = "使你的霜甲術和冰甲術所提供的護甲值和抗性提高{1}%。" },
	["increases the armor and resistance given by your frost armor and ice armor spells by #%. in addition, gives your frost ward a #% chance to reflect frost spells and effects while active"] = { ko = "냉기 갑옷과 얼음 갑옷으로 증가하는 방어도와 저항력이 {1}%만큼 증가합니다. 추가로 냉기계 수호가 활성화되어 있는 동안 {2}%의 확률로 냉기 주문을 반사합니다.", zhCN = "使你的霜甲术和冰甲术提供的护甲和抗性提高{1}%。此外，你的防护冰霜结界激活时有{2}%的几率反射冰霜法术和效果。", zhTW = "使你的霜甲術和冰甲術所提供的護甲值和抗性提高{1}%。另外，你的防護冰霜結界有{2}%的機率將冰霜系法術和魔法效果反射給施法者。" },
	["increases the armor bonus of your inner fire spell by #% and increases its total charges by #"] = { ko = "내면의 열정으로 향상되는 방어도가 {1}%만큼, 내면의 열정의 총 충전 횟수가 {2}만큼 증가합니다.", zhCN = "使你的心灵之火的护甲值加成提高{1}%，并使其总充能次数提高{2}次。", zhTW = "使你的心靈之火提供額外護甲值的效果提高{1}%，且其使用次數提高{2}次。" },
	["increases the attack power reduction of your felhunter's tainted blood, the healing of its devour magic, and the detection level of its paranoia by #%, and reduces the cooldown of its spell lock by # sec"] = { ko = "지옥사냥개의 오염된 피의 전투력 감소량이 {1}%만큼 증가하고, 마법 삼키기의 치유량과 망상의 은신 감지 효과도 그만큼 증가합니다. 또한 주문 잠금의 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的地狱猎犬的腐坏之血的攻击强度降低效果、吞噬魔法的治疗效果以及多疑的侦测等级提高{1}%，并使其法术封锁的冷却时间缩短{2}秒。", zhTW = "使你惡魔獵犬腐壞之血的攻擊強度降低效果、吞噬魔法的治療效果，以及多疑的偵測等級提高{1}%，並使其法術封鎖的冷卻時間縮短{2}秒。" },
	["increases the bleed damage done by your rend ability by #%"] = { ko = "분쇄로 인한 출혈 피해가 {1}%만큼 증가합니다.", zhCN = "使你的撕裂技能造成的流血伤害提高{1}%。", zhTW = "使你的撕裂技能造成的流血傷害提高{1}%。" },
	["increases the block value of your shield by #% while holy shield is active"] = { ko = "신성한 방패가 활성화된 동안 방패의 피해 방어량이 {1}%만큼 증가합니다.", zhCN = "在神圣之盾激活期间，使你的盾牌格挡值提高{1}%。", zhTW = "神聖之盾生效時，使你的盾牌格擋值提高{1}%。" },
	["increases the chance to apply poisons to your target by #%, and gives poison applications a #% chance to not consume a charge"] = { ko = "대상이 독에 감염될 확률이 {1}%만큼 증가합니다. 또한 독을 부여할 때마다 {2}%의 확률로 사용 횟수가 소모되지 않습니다.", zhCN = "使你对目标施加毒药的几率提高{1}%，并使毒药生效时有{2}%的几率不消耗使用次数。", zhTW = "使你毒藥令目標中毒的機率提高{1}%，且每發動一次毒藥都有{2}%的機率不消耗使用次數。" },
	["increases the chance your pick pocket and distract abilities are successful by #%"] = { ko = "훔치기 및 혼란 능력이 성공할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的搜索和扰乱技能成功的几率提高{1}%", zhTW = "使你偷竊和擾亂技能的成功機率提高{1}%。" },
	["increases the critical effect chance of your healing spells by #%"] = { ko = "치유 주문의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的治疗法术产生极效治疗的几率提高{1}%。", zhTW = "使你的治療法術造成極效治療的機率提高{1}%。" },
	["increases the critical effect chance of your holy spells by #%"] = { ko = "신성 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的神圣法术造成爆击的几率提高{1}%。", zhTW = "使你神聖法術造成致命一擊的機率提高{1}%。" },
	["increases the critical effect chance of your regrowth spell by #%"] = { ko = "재생 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的愈合法术产生极效治疗效果的几率提高{1}%。", zhTW = "使你的癒合法術產生極效治療效果的機率提高{1}%。" },
	["increases the critical effect chance of your shadow spells by #%"] = { ko = "암흑 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的暗影法术爆击几率提高{1}%。", zhTW = "使你暗影法術造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of all your melee abilities by #%"] = { ko = "모든 근접 능력의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你所有近战技能的爆击几率提高{1}%。", zhTW = "你所有近戰技能的致命一擊機率提高{1}%。" },
	["increases the critical strike chance of all your spells against frozen targets by #%"] = { ko = "얼어붙은 적을 주문으로 공격했을 때 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的所有法术对被冻结目标的爆击几率提高{1}%。", zhTW = "使你的所有法術在擊中被凍結的敵人時造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of lightning bolt by #%"] = { ko = "번개 화살의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使闪电箭的爆击几率提高{1}%。", zhTW = "使閃電箭的致命一擊機率提高{1}%。" },
	["increases the critical strike chance of your ambush ability by #%"] = { ko = "매복으로 치명타를 적중시킬 확률이 {1}%만큼 증가합니다.", zhCN = "使你的伏击技能造成爆击的几率提高{1}%。", zhTW = "使你的伏擊技能造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your arcane spells by #%"] = { ko = "비전 주문의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的奥术法术爆击几率提高{1}%。", zhTW = "使你秘法法術造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your backstab by #% and your mutilate by #%, and gives backstab a #% chance to add an additional combo point"] = { ko = "기습의 치명타 및 극대화율이 {1}%만큼, 절단의 치명타 및 극대화율은 {2}%만큼 증가합니다. 또한 기습 사용 시 {3}%의 확률로 추가 연계 점수를 추가합니다.", zhCN = "使你的背刺爆击几率提高{1}%、毁伤爆击几率提高{2}%，并使背刺有{3}%的几率额外增加一个连击点数。", zhTW = "使你的背刺和截肢造成致命一擊的機率分別提高{1}%和{2}%，並使背刺有{3}%的機率額外增加一個連擊點數。" },
	["increases the critical strike chance of your conflagrate spell by #%"] = { ko = "점화의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的燃烧法术爆击几率提高{1}%。", zhTW = "使你的焚燒法術造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your fire blast, ice lance, arcane blast, and scorch spells by #%"] = { ko = "화염 작열과 얼음창, 비전 작렬, 불태우기의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的火焰冲击、冰枪术、奥术冲击和灼烧的爆击几率提高{1}%。", zhTW = "使你火焰衝擊、冰霜長矛、秘法衝擊和灼燒法術的致命一擊機率提高{1}%。" },
	["increases the critical strike chance of your fire spells by #%"] = { ko = "화염 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的火焰法术造成爆击的几率提高{1}%。", zhTW = "使你的火焰法術造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your flamestrike spell by #%"] = { ko = "불기둥이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的烈焰风暴造成爆击的几率提高{1}%。", zhTW = "使你的烈焰風暴造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your holy shock and holy strike spells by #%, and all other spells by #%"] = { ko = "신성 충격과 신성한 일격이 극대화 효과를 발휘할 확률이 {1}%만큼, 그 외 모든 주문이 극대화 효과를 발휘할 확률이 {2}%만큼 증가합니다." },
	["increases the critical strike chance of your holy shock spell by #%"] = { ko = "신성 충격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的神圣震击法术的爆击几率提高{1}%。", zhTW = "使你神聖震擊的致命一擊機率提高{1}%。" },
	["increases the critical strike chance of your lesser healing wave spell by #%"] = { ko = "하급 치유의 물결의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的次级治疗波法术的爆击几率提高{1}%。", zhTW = "使你的次級治療波法術的致命一擊機率提高{1}%。" },
	["increases the critical strike chance of your lightning bolt and chain lightning spells by #%"] = { ko = "번개 화살, 연쇄 번개 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "使你的闪电箭和闪电链的爆击几率提高{1}%。", zhTW = "使你的閃電箭和閃電鏈造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your overpower ability by #%"] = { ko = "제압 사용 시 치명타 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的压制技能造成爆击的几率提高{1}%。", zhTW = "使你的壓制技能造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your pets and hawks by #%"] = { ko = "야수와 매의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的宠物和雄鹰的爆击几率提高{1}%。", zhTW = "使你的寵物和獵鷹造成致命一擊的機率提高{1}%。" },
	["increases the critical strike chance of your searing pain spell by #% and the damage done by all your destruction spells by #%"] = { ko = "불타는 고통이 극대화 효과를 발휘할 확률이 {1}%만큼, 모든 파괴 주문이 입히는 피해가 {2}%만큼 증가합니다.", zhCN = "使你的灼热之痛的爆击几率提高{1}%，并使你所有毁灭系法术造成的伤害提高{2}%。", zhTW = "使你灼熱之痛造成致命一擊的機率提高{1}%，且你的所有毀滅系法術造成的傷害提高{2}%。" },
	["increases the critical strike damage bonus of your abilities by #%"] = { ko = "기술의 치명타 피해 보너스가 {1}%만큼 증가합니다.", zhCN = "使你的技能爆击伤害加成提高{1}%。", zhTW = "使你技能造成的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your arcane and nature spells by #%"] = { ko = "비전 및 자연 주문의 추가 치명타 및 극대화 피해가 {1}%만큼 증가합니다.", zhCN = "使你的奥术和自然法术的爆击伤害加成提高{1}%。", zhTW = "使你的秘法和自然法術的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your corruption, bane of agony, bane of doom, drain soul, drain life, siphon life, and wrack spells by #%"] = { ko = "부패, 고통의 파멸, 운명의 파멸, 영혼 흡수, 생명력 흡수, 생명력 착취, 파멸 주문의 치명타 및 극대화 피해 증가량이 {1}%만큼 증가합니다.", zhCN = "使你的腐蚀术、痛苦灾祸、末日灾祸、吸取灵魂、吸取生命、生命虹吸和折磨的爆击伤害加成提高{1}%。", zhTW = "你的腐蝕術、痛苦災厄、末日災厄、吸取靈魂、吸取生命、生命虹吸和毀壞法術的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your destruction spells by #%"] = { ko = "파괴 주문이 극대화 효과를 발휘했을 경우 피해가 {1}%만큼 증가합니다.", zhCN = "使你的毁灭系法术的爆击伤害加成提高{1}%。", zhTW = "使你的毀滅系法術的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your frost spells by #%"] = { ko = "냉기 주문이 치명타로 적중할 경우 보너스 피해가 {1}%만큼 증가합니다.", zhCN = "使你的冰霜法术爆击所造成的伤害提高{1}%。", zhTW = "使你的冰霜法術致命一擊所造成的傷害提高{1}%。" },
	["increases the critical strike damage bonus of your melee abilities by #%"] = { ko = "근접 능력의 치명타 및 극대화 피해 증가량이 {1}%만큼 증가합니다.", zhCN = "使你的近战技能的爆击伤害加成提高{1}%。", zhTW = "使你近戰技能造成的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your searing and magma totems and your fire, frost, and nature spells by #%"] = { ko = "불타는 토템 및 용암 토템, 화염과 냉기, 자연 주문의 추가 치명타 및 극대화 피해가 {1}%만큼 증가합니다.", zhCN = "使你的灼热图腾、熔岩图腾以及你的火焰、冰霜和自然系法术的爆击伤害加成提高{1}%。", zhTW = "使你的灼熱和熔岩圖騰，以及火焰、冰霜和自然法術的致命一擊傷害加成提高{1}%。" },
	["increases the critical strike damage bonus of your sinister strike, gouge, backstab, mutilate, ghostly strike, and hemorrhage abilities by #%"] = { ko = "사악한 일격, 후려치기, 기습, 절단, 그림자 일격, 과다출혈의 추가 치명타 및 극대화 피해가 {1}%만큼 증가합니다.", zhCN = "使你的邪恶攻击、凿击、背刺、毁伤、鬼魅攻击和出血技能的爆击伤害加成提高{1}%。", zhTW = "使你的邪惡攻擊、鑿擊、背刺、截肢、鬼魅攻擊和出血技能的致命一擊所造成的額外傷害提高{1}%。" },
	["increases the critical strike damage bonus on all ranged abilities by #%"] = { ko = "모든 원거리 능력의 치명타 및 극대화 피해 증가량이 {1}%만큼 증가합니다.", zhCN = "使你所有远程技能的爆击伤害加成提高{1}%。", zhTW = "使所有遠程技能的致命一擊傷害加成提高{1}%。" },
	["increases the damage absorbed by your power word: shield by #%"] = { ko = "신의 권능: 보호막으로 흡수되는 피해가 {1}%만큼 증가합니다.", zhCN = "使你的真言术：盾所吸收的伤害量提高{1}%。", zhTW = "使你的真言術：盾吸收的傷害總量提高{1}%。" },
	["increases the damage and critical strike chance of your moonfire spell by #%"] = { ko = "달빛 섬광의 공격력과 치명타 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的月火术的伤害和爆击几率提高{1}%。", zhTW = "使你的月火術的傷害和致命一擊機率提高{1}%。" },
	["increases the damage and healing of your instant cast spells by #%"] = { ko = "즉시 시전 주문의 공격력과 치유량이 {1}%만큼 증가합니다.", zhCN = "使你的瞬发法术的伤害和治疗效果提高{1}%。", zhTW = "使你瞬發法術造成的傷害和治療效果提高{1}%。" },
	["increases the damage caused by your claw, rake, shred, maul, and swipe abilities by #%"] = { ko = "할퀴기, 갈퀴 발톱, 칼날 발톱, 후려치기, 휘둘러치기의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的爪击、扫击、撕碎、槌击和横扫技能造成的伤害提高{1}%。", zhTW = "使你的爪擊、掃擊、撕碎、槌擊和揮擊技能所造成的傷害提高{1}%。" },
	["increases the damage dealt by your backstab, garrote, ambush, and mutilate abilities by #%"] = { ko = "기습, 목조르기, 매복, 절단의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的背刺、绞喉、伏击和毁伤技能造成的伤害提高{1}%。", zhTW = "使你的背刺、絞喉、伏擊和截肢技能造成的傷害提高{1}%。" },
	["increases the damage dealt by your cone of cold spell by #%"] = { ko = "냉기 돌풍의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的冰锥术所造成的伤害提高{1}%。", zhTW = "使你的冰錐術所造成的傷害提高{1}%。" },
	["increases the damage dealt by your poisons by #% and gives your poisons an additional #% chance to resist dispel effects"] = { ko = "독으로 인한 피해가 {1}%만큼 증가하고 자신의 독이 주문이나 효과에 의해 해제될 확률이 {2}%만큼 감소합니다.", zhCN = "使你的毒素所造成的伤害提高{1}%，并使你的毒药抵抗驱散效果的几率提高{2}%。", zhTW = "使你的毒藥所造成的傷害提高{1}%並給予你的毒藥額外{2}%的機率抵抗驅散效果。" },
	["increases the damage dealt or life drained by your shadow spells by #%"] = { ko = "암흑 계열 주문으로 인한 피해나 흡수되는 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的暗影法术所造成的伤害或吸取的生命值提高{1}%。", zhTW = "使你的暗影法術所造成的傷害或吸取的生命力提高{1}%。" },
	["increases the damage done by your arcane and nature spells by #%"] = { ko = "비전 및 자연 주문의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的奥术和自然法术造成的伤害提高{1}%。", zhTW = "使你的秘法和自然法術造成的傷害提高{1}%。" },
	["increases the damage done by your bane of agony by #%"] = { ko = "고통의 파멸의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的痛苦灾祸造成的伤害提高{1}%。", zhTW = "使你的痛苦災厄所造成的傷害提高{1}%。" },
	["increases the damage done by your entangling roots spell by #%, and its victims can take up to #% more damage without interrupting the effect"] = { ko = "휘감는 뿌리의 공격력이 {1}%만큼 증가합니다. 또한 대상에게 걸린 휘감는 뿌리가 해제되지 않고 받을 수 있는 피해가 최대 {2}%만큼 증가합니다.", zhCN = "使你的纠缠根须造成的伤害提高{1}%，且受其影响的目标可额外承受最多{2}%的伤害而不会打断该效果。", zhTW = "你糾纏根鬚造成的傷害提高{1}%，其受害者受到的傷害最多提高{2}%，且不會中斷效果。" },
	["increases the damage done by your eviscerate ability by #%"] = { ko = "절개의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的刺骨技能所造成的伤害提高{1}%。", zhTW = "使你的剔骨技能所造成的傷害提高{1}%。" },
	["increases the damage done by your fire nova spell by #% and reduces its cooldown by # sec"] = { ko = "불꽃 회오리의 공격력이 {1}%만큼 증가하고 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的火焰新星造成的伤害提高{1}%，冷却时间缩短{2}秒。", zhTW = "使你火焰新星法術造成的傷害提高{1}%，冷卻時間縮短{2}秒。" },
	["increases the damage done by your fire spells by #%"] = { ko = "화염 계열 주문의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的火焰法术造成的伤害提高{1}%。", zhTW = "使你的火焰法術造成的傷害提高{1}%。" },
	["increases the damage done by your fire totems and by your flame shock, fire nova, and lava burst spells by #%"] = { ko = "불의 토템과 화염 충격, 불꽃 회오리, 용암 폭발의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的火焰图腾以及烈焰震击、火焰新星和熔岩爆裂造成的伤害提高{1}%。", zhTW = "使你火焰圖騰與烈焰震擊、火焰新星和熔岩爆發法術造成的傷害提高{1}%。" },
	["increases the damage done by your frost spells by #%"] = { ko = "냉기 주문의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的冰霜法术所造成的伤害提高{1}%。", zhTW = "使你的冰霜法術所造成的傷害提高{1}%。" },
	["increases the damage done by your lightning bolt, chain lightning, and earth shock spells by #%"] = { ko = "번개 화살, 연쇄 번개, 대지 충격의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的闪电箭、闪电链和大地震击造成的伤害提高{1}%。", zhTW = "使你的閃電箭、閃電鏈和大地震擊造成的傷害提高{1}%。" },
	["increases the damage done by your lightning shield orbs by #%"] = { ko = "번개 보호막 구슬의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的闪电之盾法术所造成的伤害提高{1}%。", zhTW = "使你的閃電之盾法術所造成的傷害提高{1}%。" },
	["increases the damage done by your multi-shot, aimed shot, and volley abilities by #%"] = { ko = "일제 사격과 조준 사격, 연발 사격의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的多重射击、瞄准射击和乱射技能造成的伤害提高{1}%。", zhTW = "使你多重射擊、瞄準射擊和箭雨技能所造成的傷害提高{1}%。" },
	["increases the damage done by your off-hand weapon by #%"] = { ko = "보조 무기의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的副手武器造成的伤害提高{1}%。", zhTW = "使你副手武器所造成的傷害提高{1}%。" },
	["increases the damage done by your off-hand weapon by #% and the rage generated by your off-hand attacks by #%"] = { ko = "보조 무기의 공격력이 {1}%만큼, 보조 무기 공격으로 얻는 분노가 {2}%만큼 증가합니다." },
	["increases the damage done by your pets and hawks by #%"] = { ko = "야수와 매의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的宠物和雄鹰造成的伤害提高{1}%。", zhTW = "使你的寵物和獵鷹所造成的傷害提高{1}%。" },
	["increases the damage done by your seals and judgements by #%"] = { ko = "문장과 심판의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的圣印和审判造成的伤害提高{1}%。", zhTW = "使你的聖印和審判造成的傷害提高{1}%。" },
	["increases the damage done by your spells by #% and your critical strike chance by #%"] = { ko = "주문의 공격력이 {1}%만큼, 치명타 및 극대화율이 {2}%만큼 증가합니다.", zhCN = "使你的法术伤害提高{1}%，爆击几率提高{2}%。", zhTW = "使你法術造成的傷害提高{1}%，致命一擊機率提高{2}%。" },
	["increases the damage done or health drained by your drain life, drain soul, and wrack spells by #% per each of your other affliction effects active on the target, up to a maximum increase of #%"] = { ko = "대상에게 활성화된 다른 고통 효과 하나당 생명력 흡수, 영혼 흡수, 파멸로 입히는 피해 혹은 생명력 흡수량이 {1}%만큼, 최대 {2}%만큼 증가합니다.", zhCN = "目标身上每有一个你的其他痛苦系效果，你的吸取生命、吸取灵魂和折磨造成的伤害或吸取的生命值提高{1}%，最多提高{2}%。", zhTW = "你在目標身上每個作用中的其他痛苦效果，都會使你吸取生命、吸取靈魂，以及毀壞法術造成的傷害或吸取的生命力提高{1}%，最多提高{2}%。" },
	["increases the damage of your holy strike ability by #% and causes it to refresh all judgement effects on the target"] = { ko = "신성한 일격의 공격력이 {1}%만큼 증가하며, 사용 시 대상에게 걸린 모든 심판 효과가 갱신됩니다.", zhCN = "使你的神圣打击造成的伤害提高{1}%，并刷新目标身上的所有审判效果。", zhTW = "使你神聖打擊造成的傷害提高{1}%，並使其重置目標身上的所有審判效果。" },
	["increases the damage of your imp's firebolt spell by #% and the effect of its fire shield spell by #%"] = { ko = "임프의 불화살 주문의 공격력이 {1}%만큼, 화염 보호막의 효과가 {2}%만큼 증가합니다.", zhCN = "使你的小鬼的火焰箭造成的伤害提高{1}%，火焰之盾的效果提高{2}%。", zhTW = "使小鬼火焰箭法術造成的傷害提高{1}%，且其火焰之盾法術的效果提高{2}%。" },
	["increases the damage of your serpent sting ability by #%, reduces the cooldown of your viper sting ability by # sec, and increases the duration of your scorpid sting ability by # sec"] = { ko = "독사 쐐기의 피해가 {1}%만큼 증가하고, 살무사 쐐기의 재사용 대기시간이 {2}초만큼 단축되며, 전갈 쐐기의 지속시간이 {3}초만큼 증가합니다.", zhCN = "使你的毒蛇钉刺伤害提高{1}%，蝰蛇钉刺冷却时间缩短{2}秒，毒蝎钉刺持续时间延长{3}秒。", zhTW = "使你的毒蛇釘刺傷害提高{1}%，蝰蛇釘刺冷卻時間縮短{2}秒，毒蠍釘刺持續時間延長{3}秒。" },
	["increases the damage of your sinister strike, backstab, and eviscerate abilities by #%"] = { ko = "사악한 일격과 기습 및 절개의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的影袭、背刺和刺骨技能的伤害提高{1}%。", zhTW = "使你邪惡攻擊、背刺和剔骨技能的傷害提高{1}%。" },
	["increases the damage you deal with one-handed melee weapons by #%"] = { ko = "한손 무기류의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的单手近战武器所能造成的伤害提高{1}%。", zhTW = "使你的單手近戰武器所能造成的傷害提高{1}%。" },
	["increases the damage you deal with ranged weapons by #%"] = { ko = "원거리 무기의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的远程武器造成的伤害提高{1}%。", zhTW = "使你的遠程武器造成的傷害提高{1}%。" },
	["increases the damage you deal with two-handed melee weapons by #%"] = { ko = "양손 무기의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的双手近战武器造成的伤害提高{1}%。", zhTW = "使你的雙手近戰武器造成的傷害提高{1}%。" },
	["increases the dodge bonus of your aspect of the monkey by #%"] = { ko = "원숭이의 상의 회피율 증가량이 {1}%만큼 증가합니다.", zhCN = "使你的灵猴守护提供的躲闪加成提高{1}%。", zhTW = "使你靈猴守護所賦予的閃躲加成提高{1}%。" },
	["increases the dodge bonus of your aspect of the monkey by #%. additionally, your pet gains #% of the effect of your aspect of the monkey ability"] = { ko = "원숭이의 상의 회피율 증가량이 {1}%만큼 증가합니다. 추가로 야수가 원숭이의 상 효과의 {2}%를 받습니다.", zhCN = "使你的灵猴守护提供的躲闪加成提高{1}%。此外，你的宠物获得灵猴守护效果的{2}%。", zhTW = "使你靈猴守護所賦予的閃躲加成提高{1}%。此外，你的寵物獲得你靈猴守護技能的{2}%效果。" },
	["increases the druid's next attack by # damage"] = { ko = "드루이드의 다음 공격은 {1}의 추가 피해를 입힙니다.", zhCN = "使德鲁伊的下一次攻击造成额外的{1}点伤害。", zhTW = "使德魯伊的下一次攻擊造成額外的{1}點傷害。" },
	["increases the duration of freezing and frost trap effects by #% and the damage of immolation and explosive trap effects by #%"] = { ko = "얼음의 덫과 냉기의 덫 효과의 지속시간이 {1}%만큼 증가하고 제물의 덫과 폭발의 덫 효과의 피해가 {2}%만큼 증가합니다.", zhCN = "使你的冰冻陷阱和冰霜陷阱的效果持续时间提高{1}%，献祭陷阱和爆炸陷阱所造成的伤害提高{2}%。", zhTW = "使你的冰凍陷阱及冰霜陷阱的效果持續時間提高{1}%，並使獻祭陷阱、爆炸陷阱所造成的傷害提高{2}%。" },
	["increases the duration of rip by # sec"] = { ko = "도려내기의 지속시간이 {1}초만큼 증가합니다.", zhCN = "使撕扯的持续时间延长{1}秒。", zhTW = "撕扯的持續時間延長{1}秒。" },
	["increases the duration of your chill effects by #% and reduces the target's speed by an additional #%"] = { ko = "빙결 효과의 지속시간이 {1}%만큼 증가하고, 대상의 이동 속도를 추가로 {2}%만큼 감소시킵니다.", zhCN = "使你的冰冷效果持续时间延长{1}%，并使目标的速度额外降低{2}%。", zhTW = "使你的冰冷效果的持續時間延長{1}%，並使目標的速度額外降低{2}%。" },
	["increases the duration of your gouge ability by # sec"] = { ko = "후려치기의 지속시간이 {1}초만큼 증가합니다.", zhCN = "使你的凿击技能持续时间延长{1}秒。", zhTW = "使你的鑿擊技能的效果持續時間延長{1}秒。" },
	["increases the duration of your moonfire and rejuvenation spells by # sec, your regrowth spell by # sec, and your insect swarm spell by # sec"] = { ko = "달빛 섬광과 회복의 지속시간이 {1}초만큼, 재생의 지속시간이 {2}초만큼, 곤충 떼의 지속시간이 {3}초만큼 증가합니다.", zhCN = "使你的月火术和回春术的持续时间延长{1}秒，愈合的持续时间延长{2}秒，虫群的持续时间延长{3}秒。", zhTW = "使你的月火術和回春術的持續時間延長{1}秒，癒合的持續時間延長{2}秒，蟲群的持續時間延長{3}秒。" },
	["increases the duration of your shadow word: pain spell by # sec"] = { ko = "어둠의 권능: 고통의 지속시간이 {1}초만큼 증가합니다.", zhCN = "使你的暗言术：痛的持续时间延长{1}秒。", zhTW = "使你的暗言術：痛的持續時間延長{1}秒。" },
	["increases the duration of your slice and dice ability by #%"] = { ko = "난도질의 지속시간이 {1}%만큼 증가합니다.", zhCN = "使你的切割技能的效果持续时间延长{1}%。", zhTW = "使你的切割技能的效果持續時間延長{1}%。" },
	["increases the effect of all your healing spells by #%"] = { ko = "모든 치유 주문의 치유 효과가 {1}%만큼 증가합니다.", zhCN = "使你的所有治疗法术效果提高{1}%。", zhTW = "使你的所有治療法術的效果提高{1}%。" },
	["increases the effect of your mana spring totem by #% and increases the effect of your healing stream totem by #%"] = { ko = "마나샘 토템의 효과가 {1}%만큼, 치유의 토템의 효과가 {2}%만큼 증가합니다.", zhCN = "使你的法力之泉图腾的效果提高{1}%，治疗之泉图腾的效果提高{2}%。", zhTW = "使你法力之泉圖騰的效果提高{1}%，治療之泉圖騰的效果提高{2}%。" },
	["increases the effect of your next curse of weakness or bane of agony by #%, or your next curse of exhaustion by #%"] = { ko = "다음 사용하는 무력화 저주, 고통의 파멸 효과를 {1}%만큼 증가시키거나 피로의 저주 효과를 {2}%만큼 증가시킵니다.", zhTW = "使你的下一個虛弱詛咒或痛苦災厄的效果提高{1}%，或使你的下一個疲勞詛咒的效果提高{2}%。" },
	["increases the effect of your next curse of weakness or bane of agony by #%, or your next curse of exhaustion by #%. lasts # sec"] = { ko = "다음 사용하는 무력화 저주, 고통의 파멸 효과를 {1}%만큼 증가시키거나 피로의 저주 효과를 {2}%만큼 증가시킵니다. {3}초 동안 지속됩니다.", zhCN = "使你的下一个虚弱诅咒或痛苦灾祸的效果提高{1}%，或使你的下一个疲劳诅咒的效果提高{2}%，持续{3}秒。", zhTW = "使你的下一個虛弱詛咒或痛苦災厄的效果提高{1}%，或使你的下一個疲勞詛咒的效果提高{2}%。持續{3}秒。" },
	["increases the effect of your rejuvenation spell by #%"] = { ko = "회복 주문의 효과가 {1}%만큼 증가합니다.", zhCN = "使你的回春术的效果提高{1}%。", zhTW = "使你的回春術的效果提高{1}%。" },
	["increases the effect of your succubus' and incubus' lash of pain and soothing kiss spells by #%, and increases the duration of your succubus' and incubus' seduction and lesser invisibility spells by #%"] = { ko = "서큐버스와 인큐버스의 고통의 채찍과 유혹의 입맞춤 주문의 효과가 {1}%만큼 증가하며 현혹과 하급 투명화의 지속시간이 {2}%만큼 증가합니다.", zhCN = "使你的魅魔和夜魔的剧痛鞭笞和安抚之吻法术的效果提高{1}%，并使你的魅魔和夜魔的诱惑和次级隐形术的持续时间延长{2}%。", zhTW = "使魅魔和夢魔的劇痛鞭笞和安撫之吻法術的效果提高{1}%，並使誘惑和次級隱形術的持續時間延長{2}%。" },
	["increases the effectiveness of your demon skin and demon armor spells by #%"] = { ko = "악마의 피부와 악마의 갑옷의 효과가 {1}%만큼 증가합니다.", zhCN = "使你的恶魔皮肤和恶魔护甲法术的效果提高{1}%。", zhTW = "使你惡魔皮膚和惡魔護甲的效果提高{1}%。" },
	["increases the effectiveness of your healing spells by #%"] = { ko = "치유 주문의 효과가 {1}%만큼 증가합니다.", zhCN = "使你的治疗法术的效果提高{1}%。", zhTW = "使你治療法術的效果提高{1}%。" },
	["increases the effectiveness of your voidwalker's torment, consume shadows, sacrifice, and suffering spells by #%"] = { ko = "보이드워커의 고문, 어둠 흡수, 희생, 고통 주문의 효과가 {1}%만큼 증가합니다.", zhCN = "使你的虚空行者的折磨、吞噬暗影、牺牲和受难法术效果提高{1}%。", zhTW = "使你你虛無行者的折磨、吞噬暗影、犧牲和受難法術的效果提高{1}%。" },
	["increases the focus regeneration of your pets by #% and allows #% of your mana regeneration to continue while casting"] = { ko = "야수의 집중 회복 속도가 {1}%만큼 증가합니다. 또한 시전 중에도 평소의 {2}%에 달하는 속도로 마나가 회복됩니다.", zhCN = "使你的宠物的集中值回复速度提高{1}%，并使你在施法时仍可保持{2}%的法力回复。", zhTW = "使你的寵物的集中值恢復速度提高{1}%，並在施法時仍保持{2}%的法力恢復速度。" },
	["increases the friendly target's armor by # and all attributes by # for # hr"] = { ko = "{3}시간 동안 대상의 방어도를 {1}만큼, 모든 능력치를 {2}만큼 증가시킵니다.", zhCN = "使友方目标的护甲值提高{1}，所有属性提高{2}，持续{3}小时。", zhTW = "使友方目標的護甲值提高{1}，所有屬性提高{2}，持續{3}小時。" },
	["increases the friendly target's armor by # for # hr"] = { ko = "{2}시간 동안 대상의 방어도를 {1}만큼 증가시킵니다.", zhCN = "使友方目标的护甲值提高{1}，持续{2}小时。", zhTW = "使友方目標的護甲值提高{1}，持續{2}小時。" },
	["increases the friendly target's armor by #, all attributes by # and all resistances by # for # hr"] = { ko = "{4}시간 동안 대상의 방어도를 {1}만큼, 모든 능력치를 {2}만큼, 모든 저항력을 {3}만큼 증가시킵니다.", zhCN = "使友方目标的护甲值提高{1}，所有属性提高{2}，所有抗性提高{3}，持续{4}小时。", zhTW = "使友方目標的護甲值提高{1}，所有屬性提高{2}，所有抗性提高{3}，持續{4}小時。" },
	["increases the health and armor of your pets by #%"] = { ko = "야수의 생명력과 방어도가 {1}%만큼 증가합니다.", zhCN = "使你的宠物生命值和护甲提高{1}%。", zhTW = "使你寵物的生命力和護甲值提高{1}%。" },
	["increases the health of your stoneclaw totem by #% and the radius of your earthbind totem by #%"] = { ko = "돌발톱 토템의 생명력이 {1}%만큼 증가하고 속박의 토템의 효과 범위가 {2}%만큼 증가합니다.", zhCN = "使你的石爪图腾的生命值提高{1}%，地缚图腾的影响范围增加{2}%。", zhTW = "使你的石爪圖騰的生命力提高{1}%，地縛圖騰的有效範圍提高{2}%。" },
	["increases the initial damage of your immolate spell by #% and your conflagrate spell has a #% chance to daze the target, reducing the target's movement speed by #% for # sec"] = { ko = "제물이 입히는 최초 피해가 {1}%만큼 증가합니다. 또한 점화가 {2}%의 확률로 대상을 멍하게 만들어 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "使你的献祭的初始伤害提高{1}%，并且你的燃烧有{2}%的几率使目标眩晕，移动速度降低{3}%，持续{4}秒。", zhTW = "使你獻祭法術造成的初始傷害提高{1}%，且焚燒法術有{2}%的機率令目標暈眩，使該目標的移動速度降低{3}%，持續{4}秒。" },
	["increases the maximum health and mana of your imp, voidwalker, succubus, incubus, and felhunter by #%, and increases your maximum mana by #%"] = { ko = "임프와 보이드워커, 서큐버스, 인큐버스, 지옥사냥개의 최대 생명력과 마나가 {1}%만큼 증가합니다. 또한 시전자의 최대 마나가 {2}%만큼 증가합니다.", zhCN = "使你的小鬼、虚空行者、魅魔、夜魔和地狱猎犬的生命值与法力值上限提高{1}%，并使你的法力值上限提高{2}%。", zhTW = "使你的小鬼、虛空行者、魅魔、夢魔和惡魔獵犬的生命力上限和法力上限提高{1}%，並使你的法力上限提高{2}%。" },
	["increases the maximum number of targets you may have affected by entangling roots by #"] = { ko = "자신의 휘감는 뿌리에 영향을 받을 수 있는 최대 대상의 수가 {1}만큼 증가합니다.", zhCN = "使你同时可被纠缠根须影响的目标数量上限提高{1}个。", zhTW = "使你糾纏根鬚影響的目標數量上限提高{1}個。" },
	["increases the melee attack power bonus of your rockbiter weapon by #%, your windfury weapon effect by #% and increases the damage caused by your flametongue weapon and frostbrand weapon by #%"] = { ko = "대지의 무기로 향상되는 근접 전투력이 {1}%만큼, 질풍의 무기의 효과가 {2}%만큼 증가하고, 불꽃의 무기 및 냉기의 무기 피해가 {3}%만큼 증가합니다.", zhCN = "使你的石化武器所提供的近战攻击强度加成提高{1}%，风怒武器所提供的近战攻击强度加成提高{2}%，火舌武器和冰封武器所造成的伤害提高{3}%。", zhTW = "使你的石化武器的近戰攻擊強度加成效果提高{1}%，風怒武器的近戰攻擊強度加成效果提高{2}%，火舌武器和冰封武器的傷害提高{3}%。" },
	["increases the movement speed of your pets by #%"] = { ko = "야수의 이동 속도가 {1}%만큼 증가합니다.", zhCN = "使你的宠物移动速度提高{1}%。", zhTW = "使你寵物的移動速度提高{1}%。" },
	["increases the periodic damage and healing done by your spells and abilities by #%"] = { ko = "주문과 능력의 주기적인 피해와 치유량이 {1}%만큼 증가합니다.", zhCN = "使你的法术和技能造成的周期性伤害和治疗量提高{1}%。", zhTW = "使你法術和技能造成的週期性傷害和治療效果提高{1}%。" },
	["increases the radius of your distract ability by # yds, and further reduces the stealth detection of distracted enemies as though they were an additional # level lower"] = { ko = "혼란 능력의 반경이 {1}미터만큼 증가하고, 혼란에 빠진 적의 은신 감지 능력을 실제보다 {2}레벨만큼 감소시킵니다.", zhCN = "使你的扰乱技能的作用范围增加{1}码，并进一步降低被扰乱敌人的潜行侦测能力，使其相当于降低了{2}个等级。", zhTW = "使你的擾亂技能的作用半徑擴大{1}碼，並降低受擾亂敵人偵測潛行的能力，如同其等級額外降低{2}級。" },
	["increases the radius of your distract ability by # yds, and further reduces the stealth detection of distracted enemies as though they were an additional # levels lower"] = { ko = "혼란 능력의 반경이 {1}미터만큼 증가하고, 혼란에 빠진 적의 은신 감지 능력을 실제보다 {2}레벨만큼 감소시킵니다.", zhCN = "使你的扰乱技能的作用范围增加{1}码，并进一步降低被扰乱敌人的潜行侦测能力，使其相当于降低了{2}个等级。", zhTW = "使你的擾亂技能的作用半徑擴大{1}碼，並降低受擾亂敵人偵測潛行的能力，如同其等級額外降低{2}級。" },
	["increases the rage generated by your charge ability by #"] = { ko = "돌진으로 생성되는 분노가 {1}만큼 증가합니다.", zhCN = "使你的冲锋技能产生的怒气提高{1}点。", zhTW = "使你的衝鋒技能產生的怒氣提高{1}點。" },
	["increases the range of your arcane spells by # yards"] = { ko = "비전 주문의 사정거리가 {1}미터만큼 증가합니다.", zhCN = "使你的奥术法术的射程延长{1}码。", zhTW = "使你秘法法術的射程延長{1}碼。" },
	["increases the range of your damaging spells by #%"] = { ko = "공격 주문의 사정거리가 {1}%만큼 증가합니다.", zhCN = "使你的伤害法术射程提高{1}%。", zhTW = "使你傷害性法術的射程提高{1}%。" },
	["increases the range of your fire spells by # yards"] = { ko = "화염 주문의 사정 거리가 {1}미터만큼 증가합니다.", zhCN = "使你的火焰法术的射程增加{1}码。", zhTW = "使你的火焰法術射程增加{1}碼。" },
	["increases the range of your frostbolt and blizzard spells and the radius of your frost nova and cone of cold spells by #%"] = { ko = "얼음 화살 및 눈보라의 사정거리와 얼음 회오리, 냉기 돌풍의 범위가 {1}%만큼 증가합니다.", zhCN = "使你的冰霜新星和冰锥术的有效半径以及寒冰箭和暴风雪的射程提高{1}%。", zhTW = "使你的冰霜新星和冰錐術的有效半徑以及寒冰箭和暴風雪法術的射程提高{1}%。" },
	["increases the range of your lightning bolt, chain lightning, fire nova, and lava burst spells by # yards, and increases the range of your flame shock spell by # yards"] = { ko = "번개 화살, 연쇄 번개, 불꽃 회오리, 용암 폭발의 사정거리가 {1}미터만큼, 화염 충격의 사정거리가 {2}미터만큼 증가합니다.", zhCN = "使你的闪电箭、闪电链、火焰新星和熔岩爆裂的射程提高{1}码，烈焰震击的射程提高{2}码。", zhTW = "使你閃電箭、閃電鏈、火焰新星和熔岩爆發的施法距離延長{1}碼，並使烈焰震擊法術的施法距離延長{2}碼。" },
	["increases the range of your offensive balance spells by #% and improves your chance to hit by #%"] = { ko = "공격 조화 주문의 사정거리가 {1}%만큼 증가합니다. 또한 적중률이 {2}%만큼 증가합니다.", zhCN = "使你的进攻性平衡法术射程提高{1}%，命中几率提高{2}%。", zhTW = "使你平衡系的傷害性法術射程提高{1}%，並使你的命中機率提高{2}%。" },
	["increases the range of your offensive shadow spells by #%"] = { ko = "암흑 공격 주문의 사정거리가 {1}%만큼 증가합니다.", zhCN = "使你的暗影系伤害性法术的射程提高{1}%。", zhTW = "使你暗影系的傷害性法術射程提高{1}%。" },
	["increases the range of your ranged weapons by # yards"] = { ko = "원거리 무기의 사정거리가 {1}미터만큼 증가합니다.", zhCN = "使你的远程武器的射程延长{1}码。", zhTW = "使你的遠程武器的射程延長{1}碼。" },
	["increases the range of your smite and holy fire spells and the radius of your prayer of healing and holy nova spells by #%"] = { ko = "성스러운 일격, 신성한 불꽃 주문의 사정거리와 치유의 기원, 신성한 폭발의 적용 반경이 {1}%만큼 증가합니다.", zhCN = "使你的惩击和神圣之火的射程、治疗祷言和神圣新星的作用半径提高{1}%。", zhTW = "延長你的懲擊與神聖之火法術傷害距離，以及擴大你的治療禱言與神聖新星法術的半徑{1}%。" },
	["increases the ranged attack power of party members within # yards by #"] = { ko = "{1}미터 내에 있는 파티원의 원거리 전투력이 {2}만큼 증가합니다.", zhCN = "使{1}码内的小队成员的远程攻击强度提高{2}点。" },
	["increases the ranged attack power of party members within # yards by # lasts # min"] = { ko = "{1}미터 내에 있는 파티원의 원거리 전투력이 50만큼 증가합니다. {3}분 동안 지속됩니다.", zhCN = "使{1}码内的小队成员的远程攻击强度提高50点。持续{3}分钟。", zhTW = "使{1}碼內小隊成員的遠程攻擊強度提高50點，持續{3}分鐘。" },
	["increases the ranged attack power of party members within # yds by #"] = { ko = "{1}미터 내에 있는 파티원의 원거리 전투력이 {2}만큼 증가합니다.", zhCN = "使{1}码内的小队成员的远程攻击强度提高{2}点。", zhTW = "使{1}碼內的小隊成員的遠程攻擊強度提高{2}點。" },
	["increases the rogue's movement speed by #% for # sec"] = { ko = "{2}초 동안 이동 속도가 {1}%만큼 증가합니다.", zhCN = "使潜行者的移动速度提高{1}%，持续{2}秒。", zhTW = "使盜賊的移動速度提高{1}%，持續{2}秒。" },
	["increases the rogue's movement speed by #% for # sec. does not break stealth"] = { ko = "{2}초 동안 이동 속도가 {1}%만큼 증가합니다. 은신이 풀리지 않습니다.", zhCN = "使潜行者的移动速度提高{1}%，持续{2}秒。不会取消潜行状态。", zhTW = "使盜賊的移動速度提高{1}%，持續{2}秒。不會取消潛行狀態。" },
	["increases the speed bonus of your aspect of the cheetah and aspect of the pack by #%"] = { ko = "치타의 상과 치타 무리의 상으로 향상되는 이동 속도가 {1}%만큼 증가합니다.", zhCN = "使你的猎豹守护和豹群守护的速度加成效果提高{1}%。", zhTW = "使你的獵豹守護和豹群守護的速度加成效果提高{1}%。" },
	["increases the stealth detection of all party members within # yds of the felhunter as if they were # levels higher"] = { ko = "지옥사냥개 주위 {1}미터 반경 내에 있는 모든 파티원의 은신 감지 효과를 {2}레벨만큼 증가시킵니다.", zhCN = "使地狱猎犬{1}码内所有小队成员的潜行侦测能力提高，效果相当于高出{2}级。", zhTW = "提高惡魔獵犬半徑{1}碼內所有小隊成員的潛行偵測能力，效果相當於等級高{2}級。" },
	["increases the stun duration of your bash and pounce abilities by # sec and reduces the cooldown of bash by # sec"] = { ko = "강타와 암습의 기절 지속시간이 {1}초만큼 증가하고 강타의 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的重击和突袭的昏迷持续时间延长{1}秒，并使重击的冷却时间缩短{2}秒。", zhTW = "使你重擊跟突襲的昏迷效果持續時間延長{1}秒，重擊的冷卻時間縮短{2}秒。" },
	["increases the target's intellect by # for # hr"] = { ko = "{2}시간 동안 대상의 지능을 {1}만큼 증가시킵니다.", zhCN = "使目标的智力提高{1}点，持续{2}小时。", zhTW = "使目標的智力提高{1}點，持續{2}小時。" },
	["increases the target's mana regeneration by #% and allows #% of the target's mana regeneration to continue while casting"] = { ko = "대상의 마나 재생 속도를 {1}%만큼 증가시키고 시전 중에도 평소의 {2}%에 달하는 속도로 마나를 회복하도록 만듭니다." },
	["increases the target's mana regeneration by #% and allows #% of the target's mana regeneration to continue while casting. lasts # sec"] = { ko = "대상의 마나 재생 속도를 {1}%만큼 증가시키고 시전 중에도 평소의 {2}%에 달하는 속도로 마나를 회복하도록 만듭니다. {3}초 동안 지속됩니다.", zhCN = "使目标的法力值回复速度提高{1}%，在施法时也可保持{2}%的法力值恢复速度，持续{3}秒。", zhTW = "使目標的法力恢復點數提高{1}%並使目標在施法中可獲得{2}%的法力恢復點數，持續{3}秒。" },
	["increases the target's resistance to shadow spells by # for # min"] = { ko = "{2}분 동안 대상의 암흑 마법에 대한 저항력을 {1}만큼 증가시킵니다.", zhCN = "使目标对暗影法术的抗性提高{1}点，持续{2}分钟。", zhTW = "使目標對暗影法術的抗性提高{1}點，持續{2}分鐘。" },
	["increases the threat generated by your holy attacks by #%"] = { ko = "신성 공격으로 인해 생성되는 위협 수준이 {1}%만큼 증가합니다." },
	["increases the threat generated by your holy attacks by #%. lasts # min"] = { ko = "신성 공격으로 인해 생성되는 위협 수준이 {1}%만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "使你的神圣系攻击所造成的威胁值提高{1}%，持续{2}分钟。", zhTW = "使你的神聖系攻擊所造成的威脅值提高{1}%，持續{2}分鐘。" },
	["increases the threat generated by your holy strike ability by #%"] = { ko = "신성한 일격으로 생성되는 위협 수준이 {1}%만큼 증가합니다.", zhCN = "使你的神圣打击产生的威胁值提高{1}%。", zhTW = "使你的神聖打擊產生的威脅值提高{1}%。" },
	["increases the threat generated by your holy strike ability by #%. while righteous fury is active, holy strike also reduces your damage taken by #% for # sec"] = { ko = "신성한 일격으로 생성되는 위협 수준이 {1}%만큼 증가합니다. 정의의 격노가 활성화되어 있는 동안에는 신성한 일격이 {3}초 동안 받는 피해를 {2}%만큼 감소시킵니다.", zhCN = "使你的神圣打击产生的威胁值提高{1}%。在正义之怒激活时，神圣打击还会使你受到的伤害降低{2}%，持续{3}秒。", zhTW = "使你的神聖打擊產生的威脅值提高{1}%。在正義之怒啟用時，神聖打擊還會使你受到的傷害降低{2}%，持續{3}秒。" },
	["increases the time before your rage begins to decay after leaving combat by # sec"] = { ko = "전투에서 벗어난 뒤 분노가 줄어들기 시작할 때까지의 시간이 {1}초만큼 증가합니다." },
	["increases your agility by #%"] = { ko = "민첩성이 {1}%만큼 증가합니다.", zhCN = "使你的敏捷提高{1}%。", zhTW = "使你的敏捷提高{1}%。" },
	["increases your armor by an amount equal to #% of your intellect"] = { ko = "방어도가 지능의 {1}%만큼 증가합니다.", zhCN = "使你的护甲提高相当于智力{1}%的数值。", zhTW = "使你的護甲值提高相當於你{1}%的智力。" },
	["increases your armor value from items by #%"] = { ko = "장비 착용으로 인한 방어도가 {1}%만큼 증가합니다.", zhCN = "使你因装备而获得的护甲值提高{1}%。", zhTW = "使你因裝備而獲得的護甲值提高{1}%。" },
	["increases your attack power by #% of your intellect"] = { ko = "전투력이 지능의 {1}%만큼 증가합니다.", zhCN = "使你的攻击强度提高，数值相当于你的智力值的{1}%。", zhTW = "使你的攻擊強度提高相當於{1}%的智力。" },
	["increases your attack power by an amount equal to #% of your intellect"] = { ko = "전투력이 지능의 {1}%만큼 증가합니다.", zhCN = "使你的攻击强度提高，数值相当于你智力的{1}%。", zhTW = "使你的攻擊強度提高相當於你{1}%的智力。" },
	["increases your attack speed by #% for # sec"] = { ko = "{2}초 동안 공격 속도가 {1}%만큼 증가합니다.", zhCN = "使你的攻击速度提高{1}%，持续{2}秒。", zhTW = "使你的攻擊速度提高{1}%，持續{2}秒。" },
	["increases your attack speed by #% for your next # swings after dealing a melee critical strike"] = { ko = "근접 치명타를 적중시키면 다음 {2}회의 공격 동안 공격 속도가 {1}%만큼 증가합니다.", zhCN = "近战攻击造成爆击后，使你接下来的{2}次攻击的攻击速度提高{1}%。", zhTW = "在你的近戰攻擊造成致命一擊之後，使你下{2}次攻擊的攻擊速度提高{1}%。" },
	["increases your chance to block attacks with your shield by #% and grants you a #% chance to generate # rage when you block"] = { ko = "방패로 적의 공격을 방어할 확률이 {1}%만큼 증가하고, 방패로 공격을 막을 때마다 {2}%의 확률로 {3}의 분노를 생성합니다.", zhCN = "使你用盾牌格挡攻击的几率提高{1}%，并使你在格挡时有{2}%的几率产生{3}点怒气。", zhTW = "使你用盾牌格擋攻擊的機率提高{1}%，在成功格擋後，你有{2}%的機率產生{3}點怒氣。" },
	["increases your chance to dodge by an additional #%"] = { ko = "회피 확률이 추가로 {1}%만큼 증가합니다.", zhCN = "使你的躲闪几率提高{1}%。", zhTW = "使你的躲閃機率提高{1}%。" },
	["increases your chance to hit with off-hand attacks by #%"] = { ko = "보조 무기 공격의 적중률이 {1}%만큼 증가합니다." },
	["increases your chance to hit with your trap and feign death abilities by #%"] = { ko = "덫과 죽은 척하기의 적중률이 {1}%만큼 증가합니다.", zhCN = "使你的陷阱和假死的命中几率提高{1}%。", zhTW = "你陷阱和假死技能的命中機率提高{1}%。" },
	["increases your critical strike chance while in bear form, dire bear form, or cat form by #%"] = { ko = "곰 변신, 광포한 곰 변신, 표범 변신 시 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你在熊形态、巨熊形态或猎豹形态下的爆击几率提高{1}%。", zhTW = "使你在熊形態、巨熊形態或獵豹形態下的致命一擊機率提高{1}%。" },
	["increases your critical strike chance with all attacks and poisons by #%"] = { ko = "모든 공격 및 독의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你所有攻击和毒药的爆击几率提高{1}%。", zhTW = "使你的所有攻擊和毒藥的致命一擊機率提高{1}%。" },
	["increases your critical strike chance with all attacks by #%"] = { ko = "모든 공격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的所有攻击造成爆击的几率提高{1}%。", zhTW = "使你所有攻擊造成致命一擊的機率提高{1}%。" },
	["increases your critical strike chance with spells and melee attacks by #%"] = { ko = "주문 및 근접 공격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "使你的法术和近战攻击的爆击几率提高{1}%。", zhTW = "使你的法術和近戰攻擊造成致命一擊的機率提高{1}%。" },
	["increases your damage against undead by #%"] = { ko = "언데드에 대한 공격력이 {1}%만큼 증가합니다.", zhCN = "使你对亡灵造成的伤害提高{1}%。", zhTW = "使你對不死生物的傷害提高{1}%。" },
	["increases your damage with wands by #%"] = { ko = "마법봉의 공격력이 {1}%만큼 증가합니다.", zhCN = "使你的魔杖造成的伤害提高{1}%。", zhTW = "使你的魔杖造成的傷害提高{1}%。" },
	["increases your defense skill by #"] = { ko = "방어 숙련도가 {1}만큼 증가합니다.", zhCN = "使你的防御技能提高{1}点。", zhTW = "使你的防禦技能提高{1}點。" },
	["increases your dodge chance by #%"] = { ko = "회피율이 {1}%만큼 증가합니다.", zhCN = "使你的躲闪几率提高{1}%。", zhTW = "使你的躲閃機率提高{1}%。" },
	["increases your dodge chance by #%, and gives you a #% chance to gain # rage each time you dodge"] = { ko = "회피율이 {1}%만큼 증가합니다. 또한 회피할 때마다 {2}%의 확률로 {3}의 분노를 생성합니다.", zhCN = "使你的躲闪几率提高{1}%，并且每次躲闪有{2}%的几率获得{3}点怒气。", zhTW = "使你的閃躲機率提高{1}%，且每次閃躲時，有{2}%的機率獲得{3}點怒氣。" },
	["increases your effective stealth detection level by #"] = { ko = "은신 감지 효과가 {1}만큼 증가합니다.", zhCN = "使你的潜行侦测等级提高{1}。", zhTW = "使你的有效潛行偵測等級提高{1}。" },
	["increases your effective stealth level by #"] = { ko = "은신 효과가 {1}만큼 증가합니다.", zhCN = "使你的潜行等级提高{1}。", zhTW = "使你的有效潛行等級提高{1}。" },
	["increases your energy regeneration rate by #% for # sec"] = { ko = "{2}초 동안 기력의 회복 속도가 {1}%만큼 증가됩니다.", zhCN = "使你的能量值回复速度提高{1}%，持续{2}秒。", zhTW = "使你的能量回復速度提高{1}%，持續{2}秒。" },
	["increases your hit chance by #% and reduces the duration of movement impairing effects on you by #%"] = { ko = "자신의 적중률이 {1}%만큼 증가합니다. 또한 자신에게 시전되는 이동 방해 효과의 지속시간이 {2}%만큼 감소합니다.", zhCN = "使你的命中几率提高{1}%，并使你受到的移动限制效果的持续时间缩短{2}%。", zhTW = "使你的命中機率提高{1}%，並使你受到移動限制效果的持續時間縮短{2}%。" },
	["increases your holy damage done by #%, and gives a #% chance each time your holy fire spell deals periodic damage for your next holy nova to cost no mana"] = { ko = "신성 공격력이 {1}%만큼 증가합니다. 또한 신성한 불꽃으로 주기적인 피해를 입힐 때마다 {2}%의 확률로 다음 신성한 폭발이 마나를 소모하지 않습니다.", zhCN = "使你造成的神圣伤害提高{1}%，并且每次神圣之火造成周期性伤害时，有{2}%的几率使你的下一个神圣新星不消耗法力值。", zhTW = "你造成的神聖傷害提高{1}%，且你的神聖之火每次造成週期性傷害時，都有{2}%的機率使你的下一個神聖新星不消耗法力。" },
	["increases your intellect by #%"] = { ko = "지능이 {1}%만큼 증가합니다.", zhCN = "使你的智力值提高{1}%。", zhTW = "使你的智力提高{1}%。" },
	["increases your intellect by #% and increases the critical strike damage bonus of your arcane spells by #%"] = { ko = "지능이 {1}%만큼, 비전 주문의 치명타 및 극대화 피해 증가량이 {2}%만큼 증가합니다.", zhCN = "使你的智力提高{1}%，奥术法术的爆击伤害加成提高{2}%。", zhTW = "使你的智力提高{1}%，且秘法法術的致命一擊傷害加成提高{2}%。" },
	["increases your intellect by #%. in addition, while in bear form or dire bear form your stamina is increased by #% and while in cat form your strength is increased by #%"] = { ko = "지능이 {1}%만큼 증가합니다. 추가로 곰 변신이나 광포한 곰 변신 상태에서 체력이 {2}%만큼, 표범 변신 상태에서 힘이 {3}%만큼 증가합니다.", zhCN = "使你的智力提高{1}%。此外，在熊形态或巨熊形态下，耐力提高{2}%；在猎豹形态下，力量提高{3}%。", zhTW = "使你的智力提高{1}%。另外，在熊形態或巨熊形態下，你的耐力提高{2}%，在獵豹形態下，你的力量提高{3}%。" },
	["increases your maximum energy by #"] = { ko = "기력 최대치를 {1}만큼 증가시킵니다.", zhCN = "使你的能量值上限提高{1}点。", zhTW = "使你的能量上限提高{1}點。" },
	["increases your melee attack power by # and size for # min"] = { ko = "{2}분 동안 근접 전투력을 {1}만큼 증가시키고 거대해집니다.", zhCN = "使你的近战攻击强度提高{1}点，体型增大，持续{2}分钟。", zhTW = "使你的近戰攻擊強度提高{1}，體型增大，持續{2}分鐘。" },
	["increases your melee attack power in cat form, bear form, and dire bear form by #% of your level"] = { ko = "표범 변신과 곰 변신, 광포한 곰 변신 기술의 근접 전투력이 레벨의 {1}%만큼 증가합니다.", zhCN = "使你在猎豹形态、熊形态和巨熊形态下的近战攻击强度提高，数值相当于你等级的{1}%。", zhTW = "使你在獵豹形態、熊形態和巨熊形態下的近戰攻擊強度提高，數值相當於你目前等級的{1}%。" },
	["increases your melee attack speed by #% and your melee attacks strike an additional nearby opponent"] = { zhCN = "使你的近战攻击速度提高{1}%，并使你的近战攻击命中附近的一个额外对手。" },
	["increases your melee attack speed by #% and your melee attacks strike an additional nearby opponent. lasts # sec"] = { ko = "근접 공격 속도가 {1}%만큼 증가합니다. 추가로 근접 공격 시 주위의 적 하나를 추가로 공격합니다. {2}초 동안 지속됩니다.", zhCN = "使你的近战攻击速度提高{1}%，并使你的近战攻击命中附近的一个额外对手。持续{2}秒。", zhTW = "使你的近戰攻擊速度提高{1}%，且你的近戰攻擊還可以對附近的一個額外的敵人造成傷害，持續{2}秒。" },
	["increases your melee attack speed by #% for your next # swings after dealing a melee critical strike"] = { ko = "근접 치명타를 적중시키면 다음 {2}회의 공격 동안 근접 공격 속도가 {1}%만큼 증가합니다.", zhCN = "近战攻击造成爆击后，使你接下来的{2}次攻击的近战攻击速度提高{1}%。", zhTW = "在你的近戰攻擊造成致命一擊之後，使你下{2}次攻擊的近戰攻擊速度提高{1}%。" },
	["increases your melee critical strike damage by #% and your off hand weapon damage by #%"] = { ko = "근접 치명타 피해가 {1}%만큼 증가하고 보조 무기의 공격력이 {2}%만큼 증가합니다.", zhCN = "使你的近战爆击伤害提高{1}%，副手武器伤害提高{2}%。", zhTW = "使你的近戰致命一擊傷害提高{1}%，副手武器傷害提高{2}%。" },
	["increases your movement speed while in cat form by #%, and increases your chance to dodge by #%"] = { ko = "표범 변신 상태일 때 이동 속도가 {1}%만큼, 회피율이 {2}%만큼 증가합니다.", zhCN = "使你在猎豹形态下的移动速度提高{1}%，躲闪几率提高{2}%。", zhTW = "在獵豹形態下，你的移動速度提高{1}%，並使你的閃躲機率提高{2}%。" },
	["increases your parry chance by #%"] = { ko = "무기 막기 확률이 {1}%만큼 증가합니다.", zhCN = "使你的招架几率提高{1}%。", zhTW = "使你的招架機率提高{1}%。" },
	["increases your physical and holy damage dealt by #% for # sec after landing a non-periodic critical strike"] = { ko = "비주기적인 치명타 및 극대화 공격을 가한 후 {2}초 동안 물리 공격력과 신성 공격력이 {1}%만큼 증가합니다.", zhCN = "非周期性伤害造成爆击后，你造成的物理和神圣伤害提高{1}%，持续{2}秒。", zhTW = "造成非週期性致命一擊後，使你造成的物理和神聖傷害提高{1}%，持續{2}秒。" },
	["increases your physical and holy damage dealt by #% for # sec after landing a non-periodic critical strike. stacks up to # times"] = { ko = "비주기적인 치명타 및 극대화 공격을 가한 후 {2}초 동안 물리 공격력과 신성 공격력이 {1}%만큼 증가합니다. 최대 {3}번까지 중첩됩니다.", zhCN = "非周期性伤害造成爆击后，你造成的物理和神圣伤害提高{1}%，持续{2}秒。最多叠加{3}次。", zhTW = "造成非週期性致命一擊後，使你造成的物理和神聖傷害提高{1}%，持續{2}秒。最多可堆疊{3}層。" },
	["increases your resistance to all magic by # and allows #% of your mana regeneration to continue while casting"] = { ko = "모든 계열 저항력을 {1}만큼 증가시키고 시전 중 {2}%의 속도로 마나가 회복됩니다.", zhCN = "对所有魔法的抗性提高{1}点，施法者可在任意情况下保持{2}%的法力值回复速度。", zhTW = "使你對所有魔法抗性提高{1}點，在施法時仍保持{2}%的法力回復速度。" },
	["increases your resistance to all magic by # and allows #% of your mana regeneration to continue while casting. only one type of armor spell can be active on the mage at any time. lasts # min"] = { ko = "모든 계열 저항력을 {1}만큼 증가시키고 시전 중 {2}%의 속도로 마나가 회복됩니다. 마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다. {3}분 동안 지속됩니다.", zhCN = "对所有魔法的抗性提高{1}点，施法者可在任意情况下保持{2}%的法力值回复速度。法师在同一时间内只能保有一种魔法护甲效果。持续{3}分钟。", zhTW = "使你對所有魔法抗性提高{1}點，在施法時仍保持{2}%的法力回復速度。同一時間內法師只能擁有一種護甲法術。持續{3}分鐘。" },
	["increases your shadow damage done by #%"] = { ko = "암흑 공격력이 {1}%만큼 증가합니다.", zhCN = "你造成的暗影伤害提高{1}%。", zhTW = "使你造成的暗影傷害提高{1}%。" },
	["increases your spell damage and healing by up to #% of your intellect"] = { ko = "주문 공격력과 치유량이 지능의 최대 {1}%만큼 증가합니다.", zhCN = "使你的法术伤害和治疗效果最多提高相当于你智力{1}%的数值。", zhTW = "使你的法術傷害和治療效果最多提高相當於你智力的{1}%。" },
	["increases your spell damage and your demon pet's spell damage by up to #% of your level while you have a summoned demon pet active"] = { ko = "악마 소환수가 활성화된 동안 자신의 주문 공격력과 악마 소환수의 주문 공격력이 자신의 레벨의 최대 {1}%만큼 증가합니다.", zhCN = "召唤的恶魔宠物激活时，使你和恶魔宠物的法术伤害最多提高相当于你等级{1}%的数值。", zhTW = "召喚的惡魔寵物存在時，使你的法術傷害和惡魔寵物的法術傷害最多提高相當於你等級的{1}%。" },
	["increases your spell damage by up to #% of your intellect"] = { ko = "주문 공격력이 최대 지능의 {1}%만큼 증가합니다." },
	["increases your spell healing by up to #% of your total spirit and your spell damage by up to #% of your total spirit"] = { ko = "주문 치유량이 전체 정신력의 최대 {1}%만큼 증가하고, 주문 공격력이 전체 정신력의 최대 {2}%만큼 증가합니다.", zhCN = "使你的法术治疗量最多提高相当于你精神总值的{1}%，法术伤害最多提高相当于你精神总值的{2}%。", zhTW = "使你的法術治療效果最多提高相當於你總精神的{1}%，並使你的法術傷害最多提高相當於你總精神的{2}%。" },
	["increases your spirit by #%"] = { ko = "정신력이 {1}%만큼 증가합니다.", zhCN = "使你的精神提高{1}%。", zhTW = "使你的精神提高{1}%。" },
	["increases your stamina by #"] = { ko = "체력이 {1}만큼 증가합니다.", zhCN = "使你的耐力提高{1}点。", zhTW = "使你的耐力提高{1}點。" },
	["increases your stamina by # while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% critical strike chance"] = { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 치명타 및 극대화율이 {2}%만큼 증가합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你还会获得{2}%的爆击几率。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{2}%致命一擊機率。" },
	["increases your stamina by # while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% haste"] = { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 가속이 {2}%만큼 증가합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你还会获得{2}%的急速。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{2}%加速。" },
	["increases your stamina by # while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% hit chance"] = { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 적중률이 {2}%만큼 증가합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你还会获得{2}%的命中几率。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{2}%命中機率。" },
	["increases your stamina by # while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% reduced chance to be dodged or parried"] = { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 공격이 회피되거나 무기 막기에 막힐 확률이 {2}%만큼 감소합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你的攻击被躲闪或招架的几率还会降低{2}%。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你被閃躲或招架的機率還會降低{2}%。" },
	["increases your stamina by #%"] = { ko = "체력이 {1}%만큼 증가합니다.", zhCN = "使你的耐力提高{1}%。", zhTW = "使你的耐力提高{1}%。" },
	["increases your stealth detection as if you were # level higher and reduces your chance to be hit by spells and ranged attacks by #%"] = { ko = "은신 감지 효과가 {1}레벨만큼 증가하고 주문과 원거리 공격에 적중당할 확률이 {2}%만큼 감소합니다.", zhCN = "使你的潜行侦测相当于提高{1}级，并使你被法术和远程攻击命中的几率降低{2}%。", zhTW = "提高偵測潛行的能力，效果相當於你的等級高{1}級，並使你被法術和遠程攻擊命中的機率降低{2}%。" },
	["increases your stealth detection as if you were # levels higher and reduces your chance to be hit by spells and ranged attacks by #%"] = { ko = "은신 감지 효과가 {1}레벨만큼 증가하고 주문과 원거리 공격에 적중당할 확률이 {2}%만큼 감소합니다.", zhCN = "使你的潜行侦测相当于提高{1}级，并使你被法术和远程攻击命中的几率降低{2}%。", zhTW = "提高偵測潛行的能力，效果相當於你的等級高{1}級，並使你被法術和遠程攻擊命中的機率降低{2}%。" },
	["increases your strength by #%"] = { ko = "힘이 {1}%만큼 증가합니다.", zhCN = "使你的力量提高{1}%。", zhTW = "使你的力量提高{1}%。" },
	["increases your target's armor value by #% for # sec after getting a critical effect from one of your healing spells"] = { ko = "치유 주문이 극대화 효과를 발휘했을 때 {2}초 동안 대상의 방어도를 {1}%만큼 증가시킵니다.", zhCN = "在你的任何一个治疗法术对目标造成极效治疗效果后，使目标因装备而获得的护甲值提高{1}%，持续{2}秒。", zhTW = "在你的任何一個治療法術對目標造成極效治療效果後，使目標的護甲值提高{1}%，持續{2}秒。" },
	["increases your total health by #%"] = { ko = "전체 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的总生命值提高{1}%。", zhTW = "使你的生命力上限提高{1}%。" },
	["increases your total intellect by #%"] = { ko = "지능이 {1}%만큼 증가합니다.", zhCN = "使你的智力值上限提高{1}%。", zhTW = "使你的智力上限提高{1}%。" },
	["increases your total stamina by #%"] = { ko = "전체 체력이 {1}%만큼 증가합니다.", zhCN = "使你的耐力总值提高{1}%。", zhTW = "提高你的總耐力{1}%。" },
	["increases your total stamina by #% and reduces the cooldown of your divine shield, divine protection, and templar's bulwark spells by # sec"] = { ko = "전체 체력이 {1}%만큼 증가합니다. 또한 천상의 보호막과 신의 가호, 기사단의 보루의 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的耐力总值提高{1}%，并使圣盾术、圣佑术和圣殿骑士壁垒的冷却时间缩短{2}秒。", zhTW = "使你的總耐力提高{1}%，並使聖盾術、聖佑術和聖殿騎士之壁壘的冷卻時間縮短{2}秒。" },
	["ineffective against targets above level ?"] = { zhCN = "对?级以上的目标不产生效果。", zhTW = "對?級以上的目標不產生效果。" },
	["ineffective on targets above level #"] = { ko = "{1} 레벨을 넘는 대상에게는 효과가 없습니다.", zhCN = "对等级高于{1}的目标无效。", zhTW = "對超過{1}級的目標無效。" },
	["inflict searing pain on the enemy target, causing # to # fire damage"] = { ko = "적에게 불타는 고통을 선사하여 {1}~{2}의 화염 피해를 입힙니다." },
	["inflict searing pain on the enemy target, causing # to # fire damage. causes a high amount of threat"] = { ko = "적에게 불타는 고통을 선사하여 {1}~{2}의 화염 피해를 입힙니다. 위협 수준을 크게 증가시킵니다.", zhCN = "使目标感受灼热的痛苦，对其造成{1}至{2}点火焰伤害，并产生很高的威胁值。", zhTW = "使目標感受灼熱的痛苦，對其造成{1}至{2}點火焰傷害，並產生很高的威脅值。" },
	["inflicts # damage and reduces the enemy target's movement speed by #% for # sec"] = { ko = "{1}의 피해를 입히고 {3}초 동안 적의 이동 속도를 {2}%만큼 감소시킵니다.", zhCN = "对敌人造成{1}点伤害，并使其移动速度降低{2}%，持续{3}秒。", zhTW = "對敵人造成{1}點傷害，並使其移動速度降低{2}%，持續{3}秒。" },
	["inflicts # fire damage and stuns targets for # sec in a # yd radius"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다.", zhCN = "造成{1}点火焰伤害，并使半径{2}码范围内的目标昏迷，持续{3}秒。", zhTW = "造成{1}點火焰傷害，並使半徑{2}碼範圍內的目標昏迷，持續{3}秒。" },
	["inflicts # fire damage and stuns targets for # sec in a # yd radius. any damage will break the effect"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다. 대상이 피해를 입게 되면 효과가 사라집니다.", zhCN = "造成{1}点火焰伤害，并使半径{2}码范围内的目标昏迷，持续{3}秒。任何伤害都会打断此效果。", zhTW = "造成{1}點火焰傷害，並使半徑{2}碼範圍內的目標昏迷，持續{3}秒。任何傷害都會打斷此效果。" },
	["inflicts # fire damage and stuns targets in a # yd radius for # sec"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다.", zhCN = "造成{1}点火焰伤害，并使半径{2}码范围内的目标昏迷，持续{3}秒。", zhTW = "造成{1}點火焰傷害，並使半徑{2}碼範圍內的目標昏迷，持續{3}秒。" },
	["inflicts # fire damage and stuns targets in a # yd radius for # sec. any damage will break the effect"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다. 대상이 피해를 받으면 효과가 사라집니다.", zhCN = "造成{1}点火焰伤害，并使半径{2}码范围内的目标昏迷，持续{3}秒。任何伤害都会打断此效果。", zhTW = "造成{1}點火焰傷害，並使半徑{2}碼範圍內的目標昏迷，持續{3}秒。任何傷害都會打斷此效果。" },
	["inflicts # fire damage and stuns targets in an # yd radius for # sec"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다.", zhCN = "造成{1}点火焰伤害，并使{2}码范围内的目标昏迷{3}秒。", zhTW = "造成{1}點火焰傷害，並使{2}碼範圍內的目標昏迷{3}秒。" },
	["inflicts # fire damage and stuns targets in an # yd radius for # sec. any damage will break the effect"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다. 대상이 피해를 받으면 효과가 사라집니다.", zhCN = "造成{1}点火焰伤害，并使{2}码范围内的目标昏迷{3}秒。任何伤害都会打破该效果。", zhTW = "造成{1}點火焰傷害，並使{2}碼範圍內的目標昏迷{3}秒。任何傷害都會打破該效果。" },
	["inflicts # fire damage in a # yd radius"] = { ko = "{2}미터 반경에 {1}의 화염 피해를 입힙니다.", zhCN = "对半径{2}码范围内的目标造成{1}点火焰伤害。", zhTW = "對半徑{2}碼範圍內的目標造成{1}點火焰傷害。" },
	["infuses the target with power, increasing their spell damage and healing done by #% for # sec"] = { ko = "대상에게 마력을 주입하여 모든 주문의 피해와 치유량을 {1}%만큼 증가시킵니다. {2}초 동안 지속됩니다.", zhCN = "为目标注入能量，使其法术伤害和治疗量提高{1}%，持续{2}秒。", zhTW = "對目標注入能量，使他們造成的法術傷害和治療效果提高{1}%。持續{2}秒。" },
	["infuses the target's party and raid with brilliance, increasing their intellect by # for # hr"] = { ko = "대상 파티원 및 공격대원에게 총명한 기운을 불어넣어 {2}시간 동안 지능을 {1}만큼 증가시킵니다.", zhCN = "为目标所在的队伍和团队注入智慧，使其智力提高{1}点，持续{2}小时。", zhTW = "魔法的光輝籠罩著目標所在的隊伍和團隊，使他們的智力提高{1}點，持續{2}小時。" },
	["instantly attack the target causing # (+#% of attack power) damage and healing you for #% of your maximum health"] = { ko = "즉시 대상을 공격하여 {1}(+ 전투력의 {2}%)의 피해를 입히고 최대 생명력의 {3}%에 해당하는 생명력을 회복합니다.", zhCN = "立即攻击目标，造成{1}（+攻击强度的{2}%）点伤害，并为你恢复最大生命值的{3}%。", zhTW = "立即攻擊目標，造成{1}（+攻擊強度的{2}%）點傷害，併為你恢復最大生命力的{3}%。" },
	["instantly attack the target causing # (+#% of attack power) damage and healing you for #% of your maximum health. only useable within # sec after you kill a non-trivial enemy"] = { ko = "즉시 대상을 공격하여 {1}(+ 전투력의 {2}%)의 피해를 입히고 최대 생명력의 {3}%에 해당하는 생명력을 회복합니다. 사소하지 않은 적을 처치한 후 {4}초 동안에만 사용할 수 있습니다.", zhCN = "立即攻击目标，造成{1}（+攻击强度的{2}%）点伤害，并为你恢复最大生命值的{3}%。只能在击杀一个能为你提供经验值或荣誉值的敌人后的{4}秒内使用。", zhTW = "立即攻擊目標，造成{1}（+攻擊強度的{2}%）點傷害，併為你恢復最大生命力的{3}%。只能在擊殺一個能為你提供經驗值或榮譽值的敵人後的{4}秒內使用。" },
	["instantly attack the target causing damage equal to #% of your attack power plus # and increasing your movement speed by #% for # sec"] = { ko = "즉시 적을 공격하여 전투력의 {1}%에 해당하는 피해와 {2}의 추가 피해를 입힙니다. 추가로 {3}초 동안 시전자의 이동 속도가 {4}%만큼 증가합니다.", zhCN = "立即攻击目标，造成相当于攻击强度{1}%外加{2}点的伤害，并使移动速度提高{3}%，持续{4}秒。", zhTW = "立刻攻擊目標，對其造成相當於你的攻擊強度{1}%再加上{2}點的傷害，並使你的移動速度提高{3}%，持續{4}秒。" },
	["instantly attacks with both weapons for #% weapon damage plus an additional # with each weapon"] = { ko = "양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다.", zhCN = "立即用两把武器攻击，每把武器造成{1}%武器伤害，外加{2}点伤害。", zhTW = "立即使用主、副手武器攻擊，使其各自造成{1}%武器傷害外加{2}點的額外傷害。" },
	["instantly attacks with both weapons for #% weapon damage plus an additional # with each weapon. damage increased by #% against poisoned targets. awards # combo points"] = { ko = "양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다. 독에 걸린 대상을 가격할 때 공격력이 {3}%만큼 증가합니다. 연계 점수 {4}점이 주어집니다.", zhCN = "立即用两把武器攻击，每把武器造成{1}%武器伤害，外加{2}点伤害。对中毒目标造成的伤害提高{3}%。奖励{4}个连击点。", zhTW = "立即使用主、副手武器攻擊，使其各自造成{1}%武器傷害外加{2}點的額外傷害。對中毒目標造成的傷害提高{3}%。獎勵{4}個連擊點數。" },
	["instantly blasts the target for # to # shadow damage"] = { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다.", zhCN = "立即冲击目标，造成{1}至{2}点暗影伤害。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。" },
	["instantly blasts the target for # to # shadow damage. if a non-trivial target dies within # sec of being hit with shadowburn, the caster gains a soul shard"] = { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다. 사소하지 않은 대상이 이 주문에 걸린 지 {3}초 내에 사망하면 시전자가 영혼의 조각을 얻습니다.", zhCN = "立即冲击目标，造成{1}至{2}点暗影伤害。若消灭一个能为你提供经验值或荣誉值的敌人，且其在受到暗影灼烧后的{3}秒内死亡，则施法者获得一块灵魂碎片。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。如果有實力的目標在被暗影灼燒命中後的{3}秒內死亡，則施法者獲得一塊靈魂裂片。" },
	["instantly blasts the target for # to # shadow damage. if the target dies within # sec of shadowburn, and yields experience or honor, the caster gains a soul shard"] = { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다. 이 주문이 걸린 지 {3}초 내에 대상이 죽고 경험치나 명예 점수를 받게되면 영혼의 조각 1개를 얻습니다.", zhCN = "立即使用暗影能量冲击目标，对其造成{1}至{2}点暗影伤害。如果目标受到暗影灼烧伤害之后的{3}秒内死亡，且施法者因此获得经验值或荣誉，则施法者获得一块灵魂碎片。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。如果目標於{3}秒內死於暗影灼燒，且施法者因此獲得經驗值或榮譽，則施法者獲得一塊靈魂碎片。" },
	["instantly convert #% of base mana into # energy"] = { ko = "즉시 기본 마나의 {1}%를 {2}의 기력으로 바꿉니다." },
	["instantly convert #% of base mana into # energy. shifting power's cost is reduced by effects that reduce the cost of shapeshifting"] = { ko = "즉시 기본 마나의 {1}%를 {2}의 기력으로 바꿉니다. 변신의 마나 비용을 줄이는 효과는 변신의 힘의 비용도 줄입니다." },
	["instantly counterattack an enemy for # to # damage and a high amount of threat"] = { zhCN = "立即反击敌人，对其造成{1}至{2}点伤害，并造成大量的威胁。", zhTW = "立即反擊敵人，對其造成{1}至{2}點傷害，並造成大量的威脅。" },
	["instantly counterattack an enemy for # to # damage and a high amount of threat. revenge must follow a block, dodge or parry"] = { ko = "즉시 적의 공격에 반격하여 {1}~{2}의 피해를 입힙니다. 위협 수준이 크게 증가합니다. 적의 공격에 대해 방어 행동을 취한 직후에만 사용할 수 있습니다.", zhCN = "立即反击敌人，对其造成{1}至{2}点伤害，并造成大量的威胁。复仇只有在成功格挡、躲闪或招架之后才能使用。", zhTW = "立即反擊敵人，對其造成{1}至{2}點傷害，並造成大量的威脅。復仇只有在成功格擋、躲閃或招架之後才能使用。" },
	["instantly counterattack any enemy that strikes you in melee for # sec"] = { ko = "{1}초 동안 근접 공격을 하는 모든 적에게 반격합니다.", zhCN = "在任何敌人以近战武器击中你之后可以立刻对其进行反击，持续{1}秒。", zhTW = "在任何敵人的近戰攻擊命中你之後可以立即對其進行反擊，持續{1}秒。" },
	["instantly counterattack any enemy that strikes you in melee for # sec. melee attacks made from behind cannot be counterattacked. a maximum of # attacks will cause retaliation"] = { ko = "{1}초 동안 근접 공격을 하는 모든 적에게 반격합니다. 등 뒤에서의 공격은 반격할 수 없습니다. 최대 {2}회의 반격이 가능합니다.", zhCN = "在任何敌人以近战武器击中你之后可以立刻对其进行反击，持续{1}秒。从你背后发动的近战攻击无法被反击。最多可反击{2}次攻击。", zhTW = "在任何敵人的近戰攻擊命中你之後可以立即對其進行反擊，持續{1}秒。從你背後發動的近戰攻擊無法被反擊。最多可反擊{2}次攻擊。" },
	["instantly generates # rage and another # rage over # sec, but reduces base armor by #% in bear form and #% in dire bear form"] = { zhCN = "立即产生{1}点怒气，随后在{3}秒内额外产生{2}点怒气，但在熊形态下基础护甲降低{4}%，在巨熊形态下基础护甲降低{5}%。", zhTW = "立即產生{1}點怒氣，並在{3}秒內產生{2}點怒氣，不過在熊形態下基礎護甲值降低{4}%，在巨熊形態下則降低{5}%。" },
	["instantly generates # rage and another # rage over # sec, but reduces base armor by #% in bear form and #% in dire bear form. the druid is considered in combat for the duration"] = { ko = "즉시 {1}의 분노를 생성하고 추가로 {3}초에 걸쳐 {2}의 분노를 생성합니다. 하지만 기본 방어도가 곰 변신 상태에서 {4}%만큼, 광포한 곰 변신 상태에서 {5}%만큼 감소합니다. 지속시간 동안 전투 상태로 간주됩니다.", zhCN = "立即产生{1}点怒气，随后在{3}秒内额外产生{2}点怒气，但在熊形态下基础护甲降低{4}%，在巨熊形态下基础护甲降低{5}%。持续期间，德鲁伊被视为处于战斗中。", zhTW = "立即產生{1}點怒氣，並在{3}秒內產生{2}點怒氣，不過在熊形態下基礎護甲值降低{4}%，在巨熊形態下則降低{5}%。效果作用期間，德魯伊會被視為在戰鬥中。" },
	["instantly heals a friendly target below #% health for # to # and removes weakened soul from that target"] = { ko = "생명력이 {1}% 미만인 아군 대상을 즉시 {2}~{3}만큼 치유하고, 해당 대상에게서 약화된 영혼을 제거합니다.", zhCN = "立即为一名生命值低于{1}%的友方目标恢复{2}至{3}点生命值，并移除该目标身上的虚弱灵魂效果。", zhTW = "立即為一名生命力低於{1}%的友方目標治療{2}至{3}點生命力，並移除該目標身上的虛弱靈魂。" },
	["instantly heals a friendly target below #% health for # to # and removes weakened soul from that target. cannot be cast on self"] = { ko = "생명력이 {1}% 미만인 아군 대상을 즉시 {2}~{3}만큼 치유하고, 해당 대상에게서 약화된 영혼을 제거합니다. 자신에게는 시전할 수 없습니다.", zhCN = "立即为一名生命值低于{1}%的友方目标恢复{2}至{3}点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。", zhTW = "立即為一名生命力低於{1}%的友方目標治療{2}至{3}點生命力，並移除該目標身上的虛弱靈魂。無法對自己施放。" },
	["instantly heals a friendly target below #% health for #,# to #,# and removes weakened soul from that target"] = { ko = "생명력이 {1}% 미만인 아군 대상을 즉시 {2},{3}~{4},{5}만큼 치유하고, 해당 대상에게서 약화된 영혼을 제거합니다.", zhCN = "立即为一名生命值低于{1}%的友方目标恢复{2},{3}至{4},{5}点生命值，并移除该目标身上的虚弱灵魂效果。", zhTW = "立即為一名生命力低於{1}%的友方目標治療{2},{3}至{4},{5}點生命力，並移除該目標身上的虛弱靈魂。" },
	["instantly heals a friendly target below #% health for #,# to #,# and removes weakened soul from that target. cannot be cast on self"] = { ko = "생명력이 {1}% 미만인 아군 대상을 즉시 {2},{3}~{4},{5}만큼 치유하고, 해당 대상에게서 약화된 영혼을 제거합니다. 자신에게는 시전할 수 없습니다.", zhCN = "立即为一名生命值低于{1}%的友方目标恢复{2},{3}至{4},{5}点生命值，并移除该目标身上的虚弱灵魂效果。不能对自己施放。", zhTW = "立即為一名生命力低於{1}%的友方目標治療{2},{3}至{4},{5}點生命力，並移除該目標身上的虛弱靈魂。無法對自己施放。" },
	["instantly heals a target with an active rejuvenation or regrowth effect for an amount equal to the full duration of the periodic effect of one of those spells"] = { ko = "회복 또는 재생 효과가 활성화된 대상을 즉시 치유합니다. 이때 두 주문 중 하나의 주기적인 치유 효과가 전체 지속시간에 걸쳐 치유하는 양과 같은 생명력을 회복시킵니다.", zhCN = "立即为一个带有回春术或愈合效果的目标恢复生命值，数值等于其中一个法术完整持续时间的周期性治疗效果。", zhTW = "目標身上有作用中的回春術或癒合效果時，立刻為其治療，治療量相當於任一週期性效果在完整持續時間內恢復的生命力。" },
	["instantly heals the caster for # to #"] = { ko = "즉시 시전자의 생명력을 {1}~{2}만큼 회복시킵니다.", zhCN = "立即为施法者回复{1}至{2}点生命值。", zhTW = "立即為施法者治療{1}至{2}點傷害。" },
	["instantly heals the caster for #,# to #,#"] = { ko = "즉시 시전자의 생명력을 {1},{2}~{3},{4}만큼 회복시킵니다.", zhCN = "立即为施法者回复{1},{2}至{3},{4}点生命值。", zhTW = "立即為施法者治療{1},{2}至{3},{4}點傷害。" },
	["instantly inflicts # to # fire damage to enemies within # yd of your active fire totem"] = { ko = "활성화된 불의 토템 {3}미터 내에 있는 적에게 즉시 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "立即对激活的火焰图腾周围{3}码内的敌人造成{1}至{2}点火焰伤害。", zhTW = "立即對啟用火焰圖騰的{3}碼範圍內的敵人造成{1}至{2}點火焰傷害。" },
	["instantly overpower the enemy, causing weapon damage plus #"] = { ko = "즉시 적의 방어를 제압하여 {1}의 추가 피해를 입힙니다.", zhCN = "立刻压制敌人，对其造成武器伤害外加{1}点伤害。", zhTW = "立刻壓制敵人，對其造成武器傷害外加{1}點傷害。" },
	["instantly overpower the enemy, causing weapon damage plus # only useable after the target dodges. the overpower cannot be blocked, dodged or parried"] = { ko = "즉시 적의 방어를 제압하여 5의 추가 피해를 입힙니다. 적이 공격을 피한 직후에만 사용할 수 있습니다. 제압은 방어하거나 막거나 회피할 수 없습니다.", zhCN = "立刻压制敌人，对其造成武器伤害外加5点伤害。只能在目标躲闪之后使用。压制无法被格档、躲闪或招架。", zhTW = "立刻壓制敵人，對其造成武器傷害外加5點傷害。只能在目標躲閃之後使用。壓制無法被格擋、躲閃或招架。" },
	["instantly sears the target with fire, causing # fire damage immediately and # fire damage over # sec"] = { ko = "시전 즉시 대상을 불로 그을려 {1}의 화염 피해를 입히고 {3}초에 걸쳐 추가로 총 {2}의 화염 피해를 입힙니다.", zhCN = "立刻用火焰燃烧目标，对其造成{1}点火焰伤害，并在随后的{3}秒内造成总计{2}点火焰伤害。", zhTW = "立刻用火焰燃燒目標，對其造成{1}點火焰傷害，並在隨後的{3}秒內造成總計{2}點火焰傷害。" },
	["instantly shields you, absorbing # damage"] = { ko = "자신 주위에 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다." },
	["instantly shields you, absorbing # damage. lasts # min. while the shield holds, your spellcasts will not be interrupted or delayed from taking damage"] = { ko = "자신 주위에 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다. {2}분 동안 지속됩니다. 보호막이 지속되는 동안에는 주문 시전 중 피해를 받아도 방해받거나 지연되지 않습니다.", zhCN = "立即为自己加上护盾，吸收{1}点伤害，持续{2}分钟。护盾存在期间，你的施法不会因受到伤害而被打断或延迟。", zhTW = "立即為你施加魔法護盾，可吸收{1}點傷害，持續{2}分鐘。只要護盾存在，你的施法就不會因受到傷害而被中斷或延遲。" },
	["instantly shocks the target with concussive force, causing # to # nature damage"] = { ko = "시전 즉시 대상을 진동하는 힘으로 감싸 {1}~{2}의 자연 피해를 입힙니다." },
	["instantly shocks the target with concussive force, causing # to # nature damage. it also interrupts spellcasting and prevents any spell in that school from being cast for # sec. causes a high amount of threat"] = { ko = "시전 즉시 대상을 진동하는 힘으로 감싸 {1}~{2}의 자연 피해를 입힙니다. 또한 대상이 {3}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다. 위협 수준이 크게 증가합니다.", zhCN = "立即以震撼性的力量攻击目标，对其造成{1}至{2}点自然伤害，同时打断施法，并使其在{3}秒内无法施放该系法术。产生大量的威胁值。", zhTW = "立即以震撼性的力量攻擊目標，對其造成{1}至{2}點自然傷害，並打斷敵人施法，使其在{3}秒內不能施放同系法術。產生大量威脅值。" },
	["instantly shocks the target with frost, causing # to # frost damage and slowing movement speed by #%. lasts # sec"] = { ko = "시전 즉시 대상을 냉기로 감싸 {1}~{2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "以冰霜冲击目标，对其造成{1}至{2}点伤害，并使其移动速度降低{3}%，持续{4}秒。", zhTW = "以冰霜衝擊目標，對其造成{1}至{2}點傷害，並使其移動速度降低{3}%，持續{4}秒。" },
	["instantly strike for normal weapon damage and increase the damage you deal to the target with your next lightning bolt, chain lightning, or earth shock spell by #% for # sec"] = { ko = "즉시 적을 공격하여 일반 무기 공격력에 해당하는 피해를 입히고, {2}초 동안 대상이 자신의 다음 번개 화살 또는 연쇄 번개, 대지 충격으로 받는 피해를 {1}%만큼 증가시킵니다.", zhCN = "立即打击，造成普通武器伤害，并使你下一次用闪电箭、闪电链或大地震击对该目标造成的伤害提高{1}%，持续{2}秒。", zhTW = "立刻造成普通武器傷害，並使你下一個閃電箭、閃電鏈或大地震擊對目標造成的傷害提高{1}%，持續{2}秒。" },
	["it also interrupts spellcasting and prevents any spell in that school from being cast for # sec"] = { ko = "또한 대상이 {1}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다." },
	["it would be completely unsafe with explosives"] = { ko = "폭발물에 사용했다간 극도로 위험할 테니 말이죠.", zhCN = "将其用于爆炸物绝对是不安全的。", zhTW = "搭配炸藥將會徹底變得不安全。" },
	["jumps up to # times and lasts # sec after each jump"] = { ko = "최대 {1}번까지 이동하며, 매 이동 시 효과가 {2}초 동안 지속됩니다.", zhCN = "最多可以转移{1}次，每次转移之后持续{2}秒。", zhTW = "最多跳躍{1}次，並且每次跳躍後可持續{2}秒。" },
	["killing a non-trivial target afflicted by your drain soul increases your mana regeneration by #% for # sec and allows #% of normal mana regeneration to continue while casting"] = { ko = "경험치 또는 명예 점수를 주는 적이 자신의 영혼 흡수에 걸린 채 죽으면 {2}초 동안 마나 회복량이 {1}%만큼 증가하고, 주문 시전 중에도 평소의 {3}% 속도로 마나가 회복됩니다.", zhCN = "若受你的吸取灵魂影响的目标被击杀，你会获得灵魂收割，持续{2}秒。灵魂收割使你在施法时以正常速度的{1}%回复法力，并使法力回复提高{3}%。", zhTW = "若受你的吸取靈魂影響的目標被擊殺，你會獲得靈魂收割，持續{2}秒。靈魂收割使你在施法時以正常速度的{1}%回覆法力，並使法力回覆提高{3}%。" },
	["killing a non-trivial target increases the critical strike chance of your next fire blast cast within # sec by #%"] = { ko = "사소하지 않은 대상을 처치하면 {1}초 안에 시전하는 다음 화염 작열의 치명타 및 극대화율이 {2}%만큼 증가합니다.", zhCN = "击杀一个能为你提供经验值或荣誉值的目标后，你在{1}秒内施放的下一次火焰冲击的爆击几率提高{2}%。", zhTW = "殺死一個有實力的目標時，使你在{1}秒內施放的下一個火焰衝擊的致命一擊機率提高{2}%。" },
	["lacerates the enemy target, making them bleed for # damage over # sec plus #% weapon damage per existing application of lacerate on the target"] = { ko = "적 대상을 갈라 {2}초에 걸쳐 {1}의 출혈 피해를 입히고, 추가로 대상에게 걸린 가르기 중첩 하나당 무기 공격력의 {3}%에 해당하는 피해를 입힙니다.", zhCN = "割伤敌方目标并使其流血，在{2}秒内受到{1}点伤害，目标身上的每层割伤额外附加{3}%的武器伤害。" },
	["lacerates the enemy target, making them bleed for # damage over # sec plus #% weapon damage per existing application of lacerate on the target. causes a high amount of threat. this effect stacks up to # times on the same target"] = { ko = "적 대상을 갈라 {2}초에 걸쳐 {1}의 출혈 피해를 입히고, 추가로 대상에게 걸린 가르기 중첩 하나당 무기 공격력의 {3}%에 해당하는 피해를 입힙니다. 높은 위협 수준을 생성합니다. 이 효과는 같은 대상에게 최대 {4}번까지 중첩됩니다.", zhCN = "割伤敌方目标并使其流血，在{2}秒内受到{1}点伤害，目标身上的每层割伤额外附加{3}%的武器伤害。造成高额威胁值。该效果对同一个目标最多叠加{4}次。", zhTW = "割裂敵方目標，在{2}秒內使其因流血而受到{1}點傷害，且目標身上每有一層割裂便會外加{3}%武器傷害，同時造成大量的威脅值。此效果可對同一目標堆疊最多{4}次。" },
	["lasts # min"] = { ko = "{1}분 동안 지속됩니다.", zhCN = "持续{1}分钟。", zhTW = "持續{1}分鐘。" },
	["lasts # min or until # charges are used"] = { ko = "{1}분 동안 지속됩니다.", zhCN = "效果可持续{1}分钟，或在{2}次防护之后消失。", zhTW = "持續{1}分鐘或直至防護能量被使用{2}次。" },
	["lasts # sec"] = { ko = "{1}초 동안 지속됩니다.", zhCN = "持续{1}秒。", zhTW = "命令聖印可持續{1}秒。" },
	["lasts # sec or # blocks"] = { ko = "{1}초 동안 혹은 {2}회의 공격을 방패로 막을 때까지 지속됩니다.", zhCN = "持续{1}秒或格挡{2}次。", zhTW = "盾牌壁壘可持續{1}秒或格擋{2}次攻擊。" },
	["lasts as long as the demon is active"] = { ko = "소환수가 활성화된 동안 지속됩니다.", zhCN = "只要恶魔处于激活状态，该效果就会持续。", zhTW = "只要惡魔保持啟動狀態，該效果會一直持續。" },
	["lasts for # hr"] = { ko = "{1}시간 동안 지속됩니다.", zhCN = "持续{1}小时。", zhTW = "持續{1}小時。" },
	["lasts for # hr. you can only have the effect of one flask at a time. this effect persists through death"] = { ko = "{1}시간 동안 지속됩니다. 영약은 동시에 하나만 사용할 수 있습니다. 이 효과는 죽어도 지속됩니다.", zhCN = "持续{1}小时。你同时只能获得一种合剂的效果。这种效果在死亡后仍可继续存在。", zhTW = "持續{1}小時。你同時只能有一種精煉藥劑的效果。此效果在死亡之後仍然有效。" },
	["lasts for # min"] = { ko = "{1}분 동안 지속됩니다.", zhCN = "强化效果持续{1}分钟。", zhTW = "持續{1}分鐘。" },
	["lasts for # min or until it explodes"] = { ko = "{1}분이 지나거나 폭발할 때까지 지속됩니다.", zhCN = "持续{1}分钟或直到它爆炸为止。", zhTW = "綿羊自召喚出來後最多存在{1}分鐘。" },
	["lasts longer per combo point:"] = { ko = "연계 점수에 따라 지속시간이 증가합니다.", zhCN = "根据连击点数的数量决定效果持续时间：", zhTW = "根據連擊點數的數量決定效果持續時間：" },
	["lasts until cancelled"] = { ko = "취소할 때까지 지속됩니다." },
	["lasts up to # min"] = { ko = "최대 {1}분 동안 지속됩니다.", zhCN = "最多持续{1}分钟。", zhTW = "最多持續{1}分鐘。" },
	["lasts up to # sec"] = { ko = "최대 {1}초 동안 지속됩니다.", zhCN = "最多持续{1}秒。", zhTW = "最多持續{1}秒。" },
	["launch a magic severing bolt at the target, dealing # physical damage and interrupting the spell being cast for # sec"] = { ko = "대상에게 마법을 끊는 화살을 발사해 {1}의 물리 피해를 입히고 {2}초 동안 주문 시전을 방해합니다.", zhCN = "向目标发射一枚破咒之箭，造成{1}点物理伤害，并打断其正在施放的法术，持续{2}秒。", zhTW = "朝目標發射斷魔箭，造成{1}點物理傷害，並中斷正在施放的法術，持續{2}秒。" },
	["launches a bolt of frost at the enemy causing # to # frost damage and slowing movement speed by #% for # sec"] = { ko = "적에게 얼음 화살을 날려 {1} 에서 {2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다." },
	["launches a bolt of frost at the enemy, causing # to # frost damage and slowing movement speed by #% for # sec"] = { ko = "적에게 얼음 화살을 날려 {1}에서 {2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "向目标射出一支寒冰箭，对其造成{1}至{2}点冰霜伤害并使其移动速度降低{3}%，持续{4}秒。", zhTW = "向敵人射出一支寒冰箭，對其造成{1}點到{2}點冰霜傷害，並降低{3}%的移動速度，持續{4}秒。" },
	["launches a bolt of frostfire at the enemy, causing # to # frostfire damage, slowing movement speed by #% and causing an additional # frostfire damage over # sec"] = { ko = "적에게 얼음불꽃 화살을 발사하여 {1}~{2}의 냉기화염 피해를 입히고 이동 속도를 {3}%만큼 감소시킨 후 {5}초에 걸쳐 추가로 {4}의 냉기화염 피해를 입힙니다.", zhCN = "对敌人施放霜火之箭，造成{1}至{2}点霜火伤害，使其移动速度降低{3}%，并在{5}秒内造成额外{4}点霜火伤害。", zhTW = "向目標射出一支霜火箭，造成{1}至{2}點霜火傷害並使其移動速度降低{3}%，同時在{5}秒內額外造成{4}點霜火傷害。" },
	["launches a bolt of frostfire at the enemy, causing # to # frostfire damage, slowing movement speed by #% and causing an additional # frostfire damage over # sec. this spell will be checked against the lower of the target's frost and fire resists and counts as both frost and fire damage"] = { ko = "적에게 얼음불꽃 화살을 발사하여 {1}~{2}의 냉기화염 피해를 입히고 이동 속도를 {3}%만큼 감소시킨 후 {5}초에 걸쳐 추가로 {4}의 냉기화염 피해를 입힙니다. 이 주문은 대상의 냉기 및 화염 저항력 중 낮은 수치를 상대로 적중하며, 냉기 및 화염 피해로 간주됩니다.", zhCN = "对敌人施放霜火之箭，造成{1}至{2}点霜火伤害，使其移动速度降低{3}%，并在{5}秒内造成额外{4}点霜火伤害。该法术同时视为冰霜与火焰伤害，并以目标冰霜与火焰抗性中较低者为准。", zhTW = "向目標射出一支霜火箭，造成{1}至{2}點霜火傷害並使其移動速度降低{3}%，同時在{5}秒內額外造成{4}點霜火傷害。此法術將會檢視目標的冰霜與火焰抗性，依照較低的一方造成傷害，並同時視為冰霜和火焰傷害。" },
	["launches a volley of holy light at the target, causing # holy damage to an enemy, or # healing to an ally, instantly and every # sec for # sec"] = { ko = "대상에게 신성한 빛의 화살을 날립니다. 적에게는 즉시, 그리고 {4}초 동안 {3}초마다 {1}의 신성 피해를 입히며, 아군에게는 같은 주기로 {2}만큼 생명력을 회복시킵니다.", zhCN = "向目标释放圣光能量，立即对一名敌人造成{1}点神圣伤害，或为一名盟友恢复{2}点生命值，并在接下来的{4}秒内每{3}秒重复一次效果。", zhTW = "對目標發出數道神聖之光，立即對敵人造成{1}點神聖傷害，或為一名盟友治療{2}點生命力，每{3}秒重複一次，持續{4}秒。" },
	["launches arcane missiles at the enemy, causing # arcane damage each second for # sec"] = { ko = "{2}초에 걸쳐 적에게 마법 화살을 날려 매초마다 각각 {1}의 비전 피해를 입힙니다.", zhCN = "向目标射出数枚奥术飞弹，对其造成每秒{1}点伤害，持续{2}秒。", zhTW = "向目標射出數枚秘法飛彈，對其造成每秒{1}點傷害，持續{2}秒。" },
	["lay out cookie's feast that contains stamina-boosting food"] = { ko = "체력을 증가시키는 음식이 담긴 쿠키의 잔칫상을 차립니다.", zhCN = "摆出曲奇的大餐，其中包含可提高耐力的食物。", zhTW = "擺出餅乾之宴，提供強化耐力的食物。" },
	["lay out cookie's feast that contains stamina-boosting food. requires a cooking fire nearby. all camping features share a cooldown of # hr"] = { ko = "체력을 증가시키는 음식이 담긴 쿠키의 잔칫상을 차립니다. 주위에 요리용 모닥불이 있어야 합니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "摆出曲奇的大餐，其中包含可提高耐力的食物。需要附近有烹饪用火。所有露营功能共享{1}小时冷却时间。", zhTW = "擺出餅乾之宴，提供強化耐力的食物。需要附近有烹飪用火。所有紮營道具有共用的{1}小時冷卻時間。" },
	["leap behind an enemy"] = { ko = "적의 배후로 도약합니다.", zhCN = "跳跃到敌人的背后。", zhTW = "躍至敵方背後。" },
	["lightwell lasts for # min or # charges"] = { ko = "빛샘은 {2}번 사용하거나 {1}분이 지나면 사라집니다.", zhCN = "光明之泉在{1}分钟或者在被使用{2}次之后消失。", zhTW = "光束泉持續{1}分鐘或可使用{2}次。" },
	["lockpicking +#"] = { ko = "자물쇠 따기가 {1}만큼 증가합니다.", zhCN = "开锁+{1}。", zhTW = "+{1}點開鎖。" },
	["low threat"] = { ko = "낮은 위협 수준을 생성합니다.", zhCN = "低威胁值的技能。" },
	["mace/staff: your attacks ignore"] = { zhCN = "锤/法杖：你的攻击忽略", zhTW = "錘/法杖：你的攻擊忽略" },
	["mace: your attacks ignore #% of"] = { zhTW = "錘：你的攻擊無視目標{1}%的" },
	["maims the enemy, causing # damage and slowing the enemy's movement by #% for # sec"] = { ko = "적의 신체를 손상시켜 {1}의 피해를 입히고 {3}초 동안 이동 속도를 {2}%만큼 감소시킵니다.", zhCN = "使敌人残废，对其造成{1}点额外伤害，并使其移动速度降低{2}%，持续{3}秒。", zhTW = "使敵人殘廢，對其造成{1}點額外傷害，並使其移動速度降低{2}%，持續{3}秒。" },
	["may be placed over a camp chair to replace it"] = { ko = "야영지 의자 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在营地椅子上以将其替换。", zhTW = "可以放置在營地椅子上以將其取代。" },
	["may be placed over a camp tent to replace it"] = { ko = "야영지 천막 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在营地帐篷上以将其替换。", zhTW = "可放在營地帳篷上以取代它。" },
	["may be placed over a camp tent to replace it. all camping features share a cooldown of # hr"] = { ko = "야영지 천막 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在营地帐篷上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在營地帳篷上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over a faction banner to replace it"] = { ko = "진영 깃발 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在阵营旗帜上以将其替换。", zhTW = "可放在陣營旌旗上以取代它。" },
	["may be placed over a faction banner to replace it. all camping features share a cooldown of # hr"] = { ko = "진영 깃발 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在阵营旗帜上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在陣營旌旗上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over a first aid kit to replace it"] = { ko = "응급치료 도구 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在急救包上以将其替换。", zhTW = "可以放置在急救箱上以將其取代。" },
	["may be placed over a first aid kit to replace it. all camping features share a cooldown of # hr"] = { ko = "응급치료 도구 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在急救包上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可以放置在急救箱上以將其取代。所有紮營功能共享{1}小時冷卻時間。" },
	["may be placed over a fish bowl to replace it"] = { ko = "생선 그릇 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在鱼缸上以将其替换。", zhTW = "可以放置在魚缸上以將其取代。" },
	["may be placed over a fish bowl to replace it. all camping features share a cooldown of # hr"] = { ko = "생선 그릇 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在鱼缸上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可以放置在魚缸上以將其取代。所有紮營功能共享{1}小時冷卻時間。" },
	["may be placed over a lodestone to replace it"] = { ko = "자철석 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在磁石上以将其替换。", zhTW = "可放在磁石上以取代它。" },
	["may be placed over a lodestone to replace it. all camping features share a cooldown of # hr"] = { ko = "자철석 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在磁石上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在磁石上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over a mana well to replace it"] = { ko = "마나 우물 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在法力之井上以将其替换。", zhTW = "可放在法力井上以取代它。" },
	["may be placed over a reagent bot to replace it"] = { ko = "재료 로봇 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在试剂机器人上以将其替换。", zhTW = "可放在材料機器人上以取代它。" },
	["may be placed over a reagent bot to replace it. all camping features share a cooldown of # hr"] = { ko = "재료 로봇 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在试剂机器人上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在材料機器人上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over a sharpening wheel to replace it"] = { ko = "연마 바퀴 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在磨刀石上以将其替换。", zhTW = "可放在砂輪上以取代它。" },
	["may be placed over a sharpening wheel to replace it. all camping features share a cooldown of # hr"] = { ko = "연마 바퀴 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在磨刀石上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在砂輪上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over an enchanted lute to replace it"] = { ko = "마력 깃든 류트 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在附魔的鲁特琴上以将其替换。", zhTW = "可放在附魔魯特琴上以取代它。" },
	["may be placed over an enchanted lute to replace it. all camping features share a cooldown of # hr"] = { ko = "마력 깃든 류트 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "可以放置在附魔的鲁特琴上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "可放在附魔魯特琴上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["may be placed over an incense candle to replace it"] = { ko = "향기 나는 양초 위에 배치하여 대체할 수 있습니다.", zhCN = "可以放置在熏香蜡烛上以将其替换。", zhTW = "可放在薰香蠟燭上以取代它。" },
	["may only occur once every # sec"] = { zhCN = "每{1}秒最多触发一次。", zhTW = "每{1}秒只能觸發一次。" },
	["mechanical targets take #x damage"] = { ko = "기계 대상은 {1}배의 피해를 받습니다.", zhCN = "机械目标会受到{1}x倍的伤害。", zhTW = "機械目標受到{1}x點傷害。" },
	["melee attacks have a #% chance"] = { zhTW = "命中時，有{1}%的機率" },
	["melee attacks made from behind cannot be counterattacked"] = { ko = "등 뒤에서의 공격은 반격할 수 없습니다.", zhCN = "从你背后发动的近战攻击无法被反击。", zhTW = "從你背後發動的近戰攻擊無法被反擊。" },
	["melee attacks with this weapon torture the target, dealing # fire damage and increasing your damage dealt to that target with this effect by #, stacking up to # times"] = { ko = "이 무기로 근접 공격 시 대상을 고문하여 {1}의 화염 피해를 입히고, 이 효과가 대상에게 입히는 피해를 {2}만큼 증가시킵니다. 최대 {3}번까지 중첩됩니다.", zhCN = "这把武器的近战攻击会折磨目标，造成{1}点火焰伤害，并使你用此效果对该目标造成的伤害提高{2}点，最多叠加{3}次。", zhTW = "用這把武器進行近戰攻擊會折磨目標，造成{1}點火焰傷害，並使你透過此效果對目標造成的傷害提高{2}點，最多可堆疊{3}層。" },
	["members of your raid or party can click the lightwell to restore # health over # sec"] = { ko = "파티원이나 공격대원이 빛샘을 클릭하면 {2}초에 걸쳐 {1}의 생명력을 회복할 수 있습니다.", zhCN = "你所属的小队或团队中的友方单位可以点击光明之泉，在{2}秒内恢复{1}点生命值。", zhTW = "友方目標可以擊點光束泉在{2}秒內回復{1}點生命力。" },
	["more effective than disengage (rank #)"] = { ko = "철수 {1}레벨보다 효과가 높습니다.", zhCN = "比逃脱（等级 {1}）更有效。", zhTW = "比逃脫（等級{1}）更有效。" },
	["more effective than distracting shot (rank #)"] = { ko = "{1}레벨 견제 사격보다 효과가 좋습니다.", zhCN = "比扰乱射击（等级 {1}）更有效。", zhTW = "比擾亂射擊（等級 {1}）更有效。" },
	["more effective than fade (rank #)"] = { ko = "{1}레벨 소실보다 효과가 좋습니다.", zhCN = "比渐隐术（等级 {1}）的效果更好。", zhTW = "比漸隱術（等級 {1}）的效果更好。" },
	["more effective than soothing kiss (rank #)"] = { ko = "{1}레벨 유혹의 입맞춤보다 효과가 좋습니다.", zhCN = "比安抚之吻（等级 {1}）更有效。", zhTW = "比安撫之吻（等級 {1}）更有效。" },
	["more effective than suffering (rank #)"] = { ko = "{1}레벨 고통 보다 효과가 높습니다.", zhCN = "比受难（等级 {1}）更有效。", zhTW = "比受難（等級 {1}）更有效。" },
	["more effective than torment (rank #)"] = { ko = "{1}레벨 고문보다 효과가 좋습니다.", zhCN = "比折磨（等级 {1}）更有效。", zhTW = "比折磨（等級 {1}）更有效。" },
	["more effective than vanish (rank #)"] = { ko = "{1} 레벨 소멸보다 효과가 좋습니다.", zhCN = "比消失（等级 {1}）更有效。" },
	["mounting or any damage taken will cancel the effect"] = { ko = "탈것에 타거나 피해를 받으면 효과가 사라집니다.", zhCN = "骑乘坐骑或受到任何伤害都会取消该效果。" },
	["movement speed increased by #% in elwynn forest, westfall, redridge mountains, and the deadmines"] = { ko = "엘윈 숲, 서부 몰락지대, 붉은마루 산맥, 죽음의 폐광에서 이동 속도가 {1}%만큼 증가합니다." },
	["movement speed reduced by #%"] = { ko = "이동 속도가 {1}%만큼 감소합니다.", zhCN = "移动速度降低{1}%。", zhTW = "移動速度降低{1}%。" },
	["multi-shot shares its cooldown with aimed shot"] = { ko = "일제 사격은 조준 사격과 재사용 대기시간을 공유합니다.", zhCN = "多重射击与瞄准射击共享冷却时间。", zhTW = "多重射擊與瞄準射擊共用冷卻時間。" },
	["must be behind the target"] = { ko = "적의 배후에서 공격해야 합니다." },
	["must be prowling and behind the target"] = { ko = "숨은 상태로 적의 배후에서 공격해야 합니다.", zhCN = "必须在潜行状态下从目标背后发动。", zhTW = "必須在潛行狀態下從目標背後發動。" },
	["must be stealthed"] = { ko = "은신 상태로 공격해야 합니다." },
	["must be stealthed and behind the target"] = { zhCN = "必须在潜行状态下从目标背后发动。" },
	["must remain seated while drinking"] = { ko = "음료를 마시려면 앉아 있어야 합니다." },
	["must remain seated while eating"] = { ko = "음식을 먹으려면 앉아 있어야 합니다." },
	["naga are stunned for # sec"] = { ko = "나가는 {1}초 동안 기절합니다.", zhCN = "若目标为纳迦，则还会昏迷{1}秒。", zhTW = "納迦會昏迷{1}秒。" },
	["no effect if rested experience already exceeds that value"] = { ko = "휴식 경험치가 이미 해당 값을 초과할 경우 아무런 효과를 발휘하지 못합니다.", zhCN = "若已有的充分休息经验超过该数值，则不生效。", zhTW = "若休息經驗值已超過該數值則無效果。" },
	["non-periodic critical strikes with fireball, frostfire bolt, fire blast, and scorch reduce the cast time of your next pyroblast cast within # sec by #%, stacking up to # times"] = { ko = "화염구, 얼음불꽃 화살, 화염 작열, 불태우기가 비주기적 피해로 극대화 효과를 발휘하면 {1}초 안에 시전하는 다음 불덩이 작열의 시전 시간이 {2}%만큼 단축되며, 최대 {3}번까지 중복됩니다.", zhCN = "你的火球术、霜火之箭、火焰冲击和灼烧的非周期性爆击会使你获得炽热连击，持续{1}秒。炽热连击使炎爆术的施法时间缩短{2}%，最多叠加{3}次。", zhTW = "你的火球術、霜火箭、火焰衝擊和灼燒的非週期性致命一擊會使你獲得熾熱連擊，持續{1}秒。熾熱連擊使炎爆術的施法時間縮短{2}%，最多疊加{3}次。" },
	["non-trivial targets damaged by drain soul have a chance to grant you a soul shard"] = { ko = "영혼 흡수로 사소하지 않은 대상에게 피해를 입히면 일정 확률로 영혼의 조각을 얻습니다.", zhCN = "对能为你提供经验值或荣誉值的敌人造成吸取灵魂伤害时，有几率使你获得一块灵魂碎片。", zhTW = "以吸取靈魂對有實力的目標造成傷害時，有一定機率使你獲得一塊靈魂裂片。" },
	["non-trivial targets killed by drain soul will always grant you a soul shard"] = { ko = "영혼 흡수로 사소하지 않은 대상을 처치하면 항상 영혼의 조각을 얻습니다.", zhCN = "消灭一个能为你提供经验值或荣誉值的敌人且其死于吸取灵魂时，必定使你获得一块灵魂碎片。", zhTW = "以吸取靈魂擊殺有實力的目標時，則一律獲得一塊靈魂裂片。" },
	["not usable in combat"] = { ko = "전투 중에는 사용할 수 없습니다.", zhCN = "不能在战斗中使用。", zhTW = "不能在戰鬥中使用。" },
	["once control is lost, the infernal must be subjugated to maintain control"] = { ko = "만약 지옥불정령이 지배에서 풀려나면 다시 예속해야만 제어권을 유지할 수 있습니다.", zhCN = "如果控制失效，则施法者必须征服地狱火才能继续指挥它。", zhTW = "當它失控時，施法者必須制伏煉獄火才能繼續操控它。" },
	["once shielded, the target cannot be shielded again for # sec"] = { ko = "한 번 보호막을 사용한 대상에겐 {1}초 동안 다시 보호막을 사용할 수 없습니다.", zhCN = "受到护盾保护后，该目标在{1}秒内无法再次受到护盾保护。", zhTW = "目標在被加上護盾之後的{1}秒內無法再被加上護盾。" },
	["once tamed, the beast will be very unhappy and disloyal"] = { ko = "길들이는 데 성공하면 만족도와 충성도가 매우 낮습니다." },
	["only # hawks can be active at once"] = { ko = "매는 한 번에 {1}마리만 활성화될 수 있습니다.", zhCN = "同时最多只能激活{1}只雄鹰。", zhTW = "同時最多隻能啟用{1}只雄鷹。" },
	["only # target can be feared at a time"] = { ko = "동시에 한 대상에게만 공포를 사용할 수 있습니다." },
	["only # target may be sapped at a time"] = { ko = "동시에 한 대상만 혼절시킬 수 있습니다.", zhCN = "同一时间只能闷棍{1}个目标。", zhTW = "每個盜賊同一時間內只能用悶棍癱瘓一個目標。" },
	["only affects beast targets level # or lower"] = { ko = "{1}레벨 이하의 야수에게만 사용할 수 있습니다.", zhCN = "只对{1}级及以下等级的目标有效。", zhTW = "只對{1}級及以下等級的目標有效。" },
	["only affects humanoid targets level # or lower"] = { zhCN = "只对{1}级及以下等级的人型目标有效。", zhTW = "只對{1}級及以下等級的人型目標有效。" },
	["only one aspect can be active at a time"] = { ko = "한 번에 한 상만 취할 수 있습니다.", zhCN = "一个猎人在同一时间内只能激活一种守护。", zhTW = "一個獵人在同一時間內只能啟動一種守護。" },
	["only one ball will fire every few seconds"] = { ko = "번개 구슬이 폭발하면 다시 폭발하기까지 일정 시간이 필요합니다." },
	["only one bane per warlock can be active on any one target"] = { ko = "흑마법사마다 대상에 동시에 하나의 파멸만 걸 수 있습니다.", zhCN = "每个术士在任一目标身上只能维持一种灾祸。", zhTW = "每個術士只能對同一個目標施加一種災禍。" },
	["only one beast can be feared at a time"] = { ko = "동시에 한 야수에게만 공포를 사용할 수 있습니다.", zhCN = "每个猎人在同一时间内只能恐吓一头野兽。", zhTW = "每個獵人在同一時間內只能恐嚇一頭野獸。" },
	["only one curse per warlock can be active on any one target"] = { ko = "흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "每个术士在任一目标身上只能维持一种诅咒。", zhTW = "每個術士只能對同一個目標施加一種詛咒。" },
	["only one elemental shield can be active on the shaman at any one time"] = { ko = "주술사의 보호막은 동시에 하나만 유지할 수 있습니다.", zhCN = "萨满祭司在同一时间只能激活一种元素之盾。", zhTW = "薩滿一次只能被一種元素護盾所保護。" },
	["only one fire trap can be active at a time"] = { ko = "덫은 1분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "同一时间只能激活一个火焰陷阱。", zhTW = "同一時間內只能設置一個火焰陷阱。" },
	["only one flamestrike can be active per mage at a time"] = { ko = "마법사마다 한 번에 하나의 불기둥만 활성화할 수 있습니다.", zhCN = "每名法师同时只能有一个烈焰风暴生效。", zhTW = "每個法師同一時間只能啟動一個烈焰風暴。" },
	["only one form of tracking can be active at a time"] = { ko = "찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "同一时间只能激活一种追踪。", zhTW = "一次只能啟動一種追蹤技能。" },
	["only one frost trap can be active at a time"] = { ko = "덫은 1분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "同一时间只能激活一个冰霜陷阱。", zhTW = "同一時間內只能設置一個冰霜陷阱。" },
	["only one globe will activate every few seconds"] = { zhCN = "每隔数秒只会有一个水球被激活。" },
	["only one judgement per paladin can be active at any one time"] = { ko = "성기사마다 하나의 심판만 효력을 발휘합니다.", zhTW = "每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" },
	["only one seal can be active on the paladin at any one time"] = { ko = "성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "圣骑士在同一时间内只能激活一种圣印。", zhTW = "聖騎士在同一時間內只能啟動一種聖印。" },
	["only one sting per hunter can be active on any one target"] = { ko = "사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.", zhCN = "每个猎人在同一时间内只能对一个目标使用一种钉刺。", zhTW = "每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["only one sting per hunter can be active on the target at a time"] = { zhCN = "每个猎人在同一时间内只能对一个目标使用一种钉刺，且同类钉刺无法叠加。", zhTW = "每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["only one target can be forced to hibernate at a time"] = { ko = "동시에 한 대상만 잠들게 할 수 있습니다." },
	["only one target can be shackled at a time"] = { ko = "한 번에 하나의 대상만 속박할 수 있습니다.", zhCN = "一个牧师在同一时间内只能束缚一个目标。", zhTW = "一個牧師在同一時間內只能束縛一個目標。" },
	["only one target can be turned at a time"] = { ko = "동시에 한 대상만 퇴치할 수 있습니다.", zhTW = "最多只能同時超渡一個目標。" },
	["only one type of armor spell can be active on the mage at any time"] = { ko = "마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다.", zhCN = "法师在同一时间内只能保有一种魔法护甲效果。", zhTW = "同一時間內法師只能擁有一種護甲法術。" },
	["only one type of thing can be tracked at a time"] = { ko = "찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "同一时间内只能激活一种追踪技能。", zhTW = "同一時間內只能啟動一種追蹤技能。" },
	["only one type of tracking can be used at a time"] = { ko = "추적 및 탐지 기술은 동시에 한 종류만 사용할 수 있습니다.", zhCN = "同一时间内只能激活一种追踪技能。", zhTW = "同一時間內只能啟動一種追蹤技能。" },
	["only usable on enemies that have #% or less health"] = { ko = "생명력이 {1}%미만인 적에게만 사용할 수 있습니다.", zhCN = "只对生命值少于{1}%的敌人有效。", zhTW = "只對生命力少於{1}%的敵人有效。" },
	["only usable on items level # and above"] = { ko = "{1} 레벨 이상의 아이템에만 사용할 수 있습니다.", zhCN = "只能用于{1}级及以上的物品。", zhTW = "只能用於{1}級及以上的物品。" },
	["only usable out of combat"] = { zhCN = "只能在非战斗状态下使用。", zhTW = "只能在非戰鬥狀態下使用。" },
	["only usable outdoors"] = { ko = "야외에서만 사용할 수 있습니다.", zhCN = "只能在户外使用。", zhTW = "只能在戶外使用。" },
	["only useable after the target dodges"] = { ko = "적이 공격을 피한 직후에만 사용할 수 있습니다.", zhCN = "只能在目标躲闪之后使用。", zhTW = "只能在目標躲閃之後使用。" },
	["only useable outdoors"] = { ko = "야외에서만 사용할 수 있습니다.", zhCN = "只能在户外使用。", zhTW = "只能在戶外使用。" },
	["only useable within # sec after you kill a non-trivial enemy"] = { ko = "사소하지 않은 적을 처치한 후 {1}초 동안에만 사용할 수 있습니다.", zhCN = "只能在击杀一个能为你提供经验值或荣誉值的敌人后的{1}秒内使用。", zhTW = "只能在擊殺一個能為你提供經驗值或榮譽值的敵人後的{1}秒內使用。" },
	["only works against humanoids"] = { ko = "인간형에게만 사용할 수 있습니다.", zhCN = "只对人型生物有效。", zhTW = "只對人型生物有效。" },
	["only works on beasts and dragonkin"] = { ko = "야수와 용족에게만 사용할 수 있습니다." },
	["only works on humanoids that are not in combat"] = { ko = "비전투 상태의 인간형 몬스터에게만 유효합니다.", zhCN = "只对未进入战斗状态的人型生物有效。", zhTW = "只能使用於非戰鬥狀態下的人形生物。" },
	["override control of the target mechanical creature for up to # min"] = { ko = "대상 기계 생명체의 조종권을 최대 {1}분 동안 장악합니다.", zhCN = "控制目标机械生物，最多持续{1}分钟。", zhTW = "操控目標機械生物，最多持續{1}分鐘。" },
	["override control of the target mechanical creature for up to # min. the target will attack slower while under your control. ineffective on targets above level #"] = { ko = "대상 기계 생명체의 조종권을 최대 {1}분 동안 장악합니다. 조종하는 동안 대상의 공격 속도가 감소합니다. {2} 레벨을 넘는 대상에게는 효과가 없습니다.", zhCN = "控制目标机械生物，最多持续{1}分钟。目标在受你控制时攻击速度会变慢。对等级高于{2}的目标无效。", zhTW = "操控目標機械生物，最多持續{1}分鐘。目標受你控制時，攻擊速度降低。對超過{2}級的目標無效。" },
	["party members must be within # yards of target"] = { ko = "파티원이 대상의 {1}미터 내에 있어야 합니다.", zhCN = "小队成员必须位于目标{1}码范围内。", zhTW = "小隊成員必須在目標附近{1}碼內。" },
	["party members must be within # yds of target"] = { ko = "파티원이 대상의 {1}미터 내에 있어야 합니다." },
	["perform spell research, resulting in a bundle of scrolls"] = { ko = "주문을 연구하여 두루마리 묶음을 얻습니다.", zhCN = "进行法术研究，获得一捆卷轴。", zhTW = "進行法術研究，獲得一捆卷軸。" },
	["perform spell research, resulting in a bundle of scrolls. requires a suitable library"] = { ko = "주문을 연구하여 두루마리 묶음을 얻습니다. 알맞은 도서관이 있어야 합니다.", zhCN = "进行法术研究，获得一捆卷轴。需要在合适的图书馆中进行。", zhTW = "進行法術研究，獲得一捆卷軸。需要在合適的圖書館中進行。" },
	["performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you"] = { ko = "교란 동작을 취합니다. 피해는 주지 않지만 적의 위협 수준을 크게 감소시켜 자신을 공격할 확률을 낮춥니다.", zhCN = "做出假动作，不会对敌人造成任何伤害，但可以大量降低你的威胁值，使敌人不会优先攻击你。", zhTW = "做出假動作，不會對敵人造成任何傷害，但可以大量降低你的威脅值，使敵人不會優先攻擊你。" },
	["performs a feint, causing no damage but lowering your threat by a medium amount, making the enemy less likely to attack you"] = { ko = "교란 동작을 취합니다. 피해는 주지 않지만 적의 위협 수준을 중간 정도 감소시켜 자신을 공격할 확률을 낮춥니다.", zhCN = "做出假动作，不会对敌人造成任何伤害，但可以中量降低你的威胁值，使敌人不会优先攻击你。", zhTW = "做出假動作，不會對敵人造成任何傷害，但可以中量降低你的威脅值，使敵人不會優先攻擊你。" },
	["performs a feint, causing no damage but lowering your threat by a small amount, making the enemy less likely to attack you"] = { ko = "교란 동작을 취합니다. 피해는 주지 않지만 적의 위협 수준을 약간 감소시켜 자신을 공격할 확률을 낮춥니다.", zhCN = "做出假动作，不会对敌人造成任何伤害，但可以少量降低你的威胁值，使敌人不会优先攻击你。", zhTW = "做出假動作，不會對敵人造成任何傷害，但可以少量降低你的威脅值，使敵人不會優先攻擊你。" },
	["permanently increase the attack power value by # and armor value by # of an item worn on the chest, legs, hands, or feet"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 전투력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的攻击强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的攻擊強度提高{1}點，護甲值提高{2}點。" },
	["permanently increase the attack power value by # and armor value by # of an item worn on the chest, legs, hands, or feet. only usable on items level # and above"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 전투력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다. {3} 레벨 이상의 아이템에만 사용할 수 있습니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的攻击强度提高{1}点，护甲值提高{2}点。只能用于{3}级及以上的物品。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的攻擊強度提高{1}點，護甲值提高{2}點。只能用於{3}級及以上的物品。" },
	["permanently increase the attack power value by # and the armor value by # of an item worn on the chest, legs, hands, or feet"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 전투력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的攻击强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的攻擊強度提高{1}點，護甲值提高{2}點。" },
	["permanently increase the defense skill by # and the stamina value by # of an item worn on the chest, legs, hands, or feet"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 방어 숙련도가 {1}만큼, 체력은 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件穿在胸部、腿部、手部或脚部的物品的防御技能提高{1}点，耐力提高{2}点。", zhTW = "永久性地使一件穿在胸部、腿部、手部或腳部的物品的防禦技能提高{1}點，耐力提高{2}點。" },
	["permanently increase the defense skill by # and the stamina value by # of an item worn on the chest, legs, hands, or feet. only usable on items level # and above"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 방어 숙련도가 {1}만큼, 체력은 {2}만큼 영구적으로 증가합니다. {3} 레벨 이상의 아이템에만 사용할 수 있습니다.", zhCN = "永久性地使一件穿在胸部、腿部、手部或脚部的物品的防御技能提高{1}点，耐力提高{2}点。只能用于{3}级及以上的物品。", zhTW = "永久性地使一件穿在胸部、腿部、手部或腳部的物品的防禦技能提高{1}點，耐力提高{2}點。只能用於{3}級及以上的物品。" },
	["permanently increase the spell power value by # and armor value by # of an item worn on the chest, legs, hands, or feet"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。" },
	["permanently increase the spell power value by # and armor value by # of an item worn on the chest, legs, hands, or feet. only usable on items level # and above"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다. {3} 레벨 이상의 아이템에만 사용할 수 있습니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。只能用于{3}级及以上的物品。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。只能用於{3}級及以上的物品。" },
	["permanently increase the spell power value by # and the armor value by # of an item worn on the chest, legs, hands, or feet"] = { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。" },
	["physical damage caused by the target is reduced by # for # min"] = { ko = "{2}분 동안 대상의 물리 공격력을 {1}만큼 감소시킵니다.", zhCN = "目标造成的物理伤害降低{1}点，持续{2}分钟。", zhTW = "目標所能造成的物理傷害降低{1}點，持續{2}分鐘。" },
	["physical damage caused by the target is reduced by # for # min. only one curse per warlock can be active on any one target"] = { ko = "{2}분 동안 대상의 물리 공격력을 {1}만큼 감소시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "目标造成的物理伤害降低{1}点，持续{2}分钟。每个术士在任一目标身上只能维持一种诅咒。", zhTW = "目標所能造成的物理傷害降低{1}點，持續{2}分鐘。每個術士只能對同一個目標施加一種詛咒。" },
	["physical damage taken is reduced by #%"] = { ko = "받는 물리 피해가 {1}%만큼 감소합니다.", zhCN = "受到的物理伤害降低{1}%。" },
	["pick the target's pocket"] = { ko = "대상의 물건을 훔칩니다.", zhCN = "收集目标携带的物品。", zhTW = "偷取目標攜帶的物品。" },
	["place a compact critter carrier for # min that allows hunters in your group to access their stabled pets"] = { ko = "{1}분 동안 소형 동물 이동장을 놓아 파티 내 사냥꾼이 야수 우리에 있는 야수를 이용할 수 있게 합니다.", zhCN = "放置一个便携式小动物箱，持续{1}分钟，使队伍中的猎人可以取用寄养在兽栏中的宠物。", zhTW = "放置一個持續{1}分鐘的輕巧小動物提籠，讓你隊伍中的獵人得以取用獸欄中的寵物。" },
	["place a fire trap that explodes when an enemy approaches, causing # to # fire damage and # additional fire damage over # sec to all within # yards"] = { ko = "덫을 설치합니다.", zhCN = "放置一个火焰陷阱，当敌人接近时爆炸，对{5}码内所有目标造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。", zhTW = "在地面上放置一個火焰陷阱，當敵人接近時會爆炸，對半徑{5}碼範圍內的所有目標造成{1}至{2}點火焰傷害，並在接下來的{4}秒內額外造成{3}點火焰傷害。" },
	["place a fire trap that explodes when an enemy approaches, causing # to # fire damage and # additional fire damage over # sec to all within # yards. trap will exist for # min. only one fire trap can be active at a time"] = { ko = "덫을 설치합니다. 적이 다가오면 폭발하여 적에게 {1}~{2}의 화염 피해를 입히고 주위 {5}미터 반경에 있는 모든 대상에게 {4}초에 걸쳐 {3}의 추가 화염 피해를 입힙니다. 덫은 {6}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个火焰陷阱，当敌人接近时爆炸，对{5}码内所有目标造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。陷阱会存在{6}分钟。同一时间只能激活一个火焰陷阱。", zhTW = "在地面上放置一個火焰陷阱，當敵人接近時會爆炸，對半徑{5}碼範圍內的所有目標造成{1}至{2}點火焰傷害，並在接下來的{4}秒內額外造成{3}點火焰傷害。陷阱可存在{6}分鐘。同一時間內只能設置一個火焰陷阱。" },
	["place a fire trap that will burn the first enemy to approach for # fire damage over # sec"] = { ko = "덫을 설치합니다.", zhCN = "放置一个火焰陷阱，灼烧第一个接近它的敌人，在{2}秒内造成{1}点火焰伤害。", zhTW = "在地面上放置一個火焰陷阱，灼燒第一個接近它的敵人，在{2}秒內對其造成{1}點火焰傷害。" },
	["place a fire trap that will burn the first enemy to approach for # fire damage over # sec. trap will exist for # min. only one fire trap can be active at a time"] = { ko = "덫을 설치합니다. 적이 다가오면 불태워 {2}초에 걸쳐 총 {1}의 화염 피해를 입힙니다. 덫은 {3}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个火焰陷阱，灼烧第一个接近它的敌人，在{2}秒内造成{1}点火焰伤害。陷阱会存在{3}分钟。同一时间只能激活一个火焰陷阱。", zhTW = "在地面上放置一個火焰陷阱，灼燒第一個接近它的敵人，在{2}秒內對其造成{1}點火焰傷害。陷阱可存在{3}分鐘。同一時間內只能設置一個火焰陷阱。" },
	["place a frost trap that creates an ice slick around itself for # sec when the first enemy approaches it"] = { zhCN = "放置一个冰霜陷阱，当第一个敌人接近时，会在其周围形成一片持续{1}秒的冰面。", zhTW = "在地面上放置一個冰霜陷阱，在敵人接近時會製造一片光滑的冰面，持續{1}秒。" },
	["place a frost trap that creates an ice slick around itself for # sec when the first enemy approaches it. all enemies within # yards will be slowed by #% while in the area of effect. trap will exist for # min. only one frost trap can be active at a time"] = { ko = "냉기의 덫을 설치합니다. 적이 다가오면 얇은 얼음판을 펼쳐, {1}초 동안 {2}미터 내의 적의 이동 속도를 {3}%만큼 감소시킵니다. 덫은 {4}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个冰霜陷阱，当第一个敌人接近时，会在其周围形成一片持续{1}秒的冰面。效果区域内{2}码范围的所有敌人移动速度降低{3}%。陷阱会存在{4}分钟。同一时间只能激活一个冰霜陷阱。", zhTW = "在地面上放置一個冰霜陷阱，在敵人接近時會製造一片光滑的冰面，持續{1}秒。所有在{2}碼範圍內的敵人的移動速度都會降低{3}%。陷阱可存在{4}分鐘。同一時間內只能設置一個冰霜陷阱。" },
	["place a frost trap that freezes the first enemy that approaches, preventing all action for up to # sec"] = { ko = "냉기의 덫을 설치합니다.", zhCN = "放置一个冰霜陷阱，冻结第一个接近它的敌人，使其最多{1}秒内无法行动。", zhTW = "在地面上放置一個冰霜陷阱，將第一個接近的敵人凍結，使其無法採取任何行動，最多持續{1}秒。" },
	["place a frost trap that freezes the first enemy that approaches, preventing all action for up to # sec. any damage caused will break the ice. trap will exist for # min. only one frost trap can be active at a time"] = { ko = "냉기의 덫을 설치합니다. 적이 다가오면 얼려서 최대 {1}초 동안 모든 행동을 불가능하게 만듭니다. 덫에 걸린 적이 피해를 입으면 효과가 풀립니다. 덫은 {2}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个冰霜陷阱，冻结第一个接近它的敌人，使其最多{1}秒内无法行动。造成任何伤害都会打破冰冻。陷阱会存在{2}分钟。同一时间只能激活一个冰霜陷阱。", zhTW = "在地面上放置一個冰霜陷阱，將第一個接近的敵人凍結，使其無法採取任何行動，最多持續{1}秒。任何傷害都會中斷冰凍效果。陷阱可存在{2}分鐘。同一時間內只能設置一個冰霜陷阱。" },
	["place a holy ward on an ally for # sec"] = { ko = "{1}초 동안 아군에게 신성한 수호를 겁니다.", zhCN = "为一名友方目标施加神圣结界，持续{1}秒。", zhTW = "為一名友方目標施加神聖結界，持續{1}秒。" },
	["place a holy ward on an ally for # sec. the next time this ally takes damage dropping their health below #%, they will gain a shield absorbing # damage and begin healing for # health over # sec. a target may be affected by only one contingency plan"] = { ko = "{1}초 동안 아군에게 신성한 수호를 겁니다. 다음에 이 아군이 피해를 입어 생명력이 {2}% 아래로 떨어지면 {3}의 피해를 흡수하는 보호막을 얻고 {5}초에 걸쳐 {4}의 생명력을 회복하기 시작합니다. 대상 하나에는 비상 대책이 하나만 걸립니다.", zhCN = "为一名友方目标施加神圣结界，持续{1}秒。该目标下一次受到伤害导致生命值低于{2}%时，会获得一个可吸收{3}点伤害的护盾，并在{5}秒内恢复{4}点生命值。一个目标同一时间只能受到一个应急方案的影响。", zhTW = "為一名友方目標施加神聖結界，持續{1}秒。該目標下一次受到傷害導致生命力低於{2}%時，會獲得一個可吸收{3}點傷害的護盾，並在{5}秒內恢復{4}點生命力。一個目標同一時間只能受到一個應變計畫的影響。" },
	["places a blessing on the friendly target, granting immunity to movement impairing effects for # sec"] = { ko = "대상에게 자유의 축복을 걸어주어 {1}초 동안 이동 방해 효과에 면역이 되도록 합니다.", zhCN = "为友方目标施加祝福，使其免疫任何减缓移动速度的法术和技能效果，持续{1}秒。", zhTW = "為友方目標施加祝福，使其免疫任何減緩移動速度的法術和技能效果，持續{1}秒。" },
	["places a blessing on the friendly target, granting immunity to movement impairing effects for # sec. players may only have one blessing on them per paladin at any one time"] = { ko = "대상에게 자유의 축복을 걸어주어 {1}초 동안 이동 방해 효과에 면역이 되도록 합니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其免疫任何减缓移动速度的法术和技能效果，持续{1}秒。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其免疫任何減緩移動速度的法術和技能效果，持續{1}秒。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the friendly target, increasing melee attack power by # for # hr"] = { ko = "대상에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다.", zhCN = "为友方目标施加祝福，使其近战攻击强度提高{1}，持续{2}小时。", zhTW = "為友方目標施加祝福，使其近戰攻擊強度提高{1}，持續{2}小時。" },
	["places a blessing on the friendly target, increasing melee attack power by # for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "대상에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其近战攻击强度提高{1}，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其近戰攻擊強度提高{1}，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the friendly target, increasing the effects of holy light spells used on the target by up to # and the effect flash of light spells used on the target by up to # lasts # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "대상에게 빛의 축복을 걸어 {3}시간 동안 성스러운 빛의 효과를 최대 {1}만큼, 빛의 섬광의 효과를 최대 60만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使圣光术为其恢复的生命值提高{1}点，圣光闪现为其恢复的生命值提高60点，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使聖光術為其恢復的生命力提高{1}點，聖光閃現為其恢復的生命力提高60點，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the friendly target, increasing total stats by #% for # hr"] = { ko = "파티원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다.", zhCN = "为友方目标施加祝福，使其所有属性提高{1}%，持续{2}小时。", zhTW = "為友方目標施加祝福，使其所有屬性提高{1}%，持續{2}小時。" },
	["places a blessing on the friendly target, increasing total stats by #% for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "파티원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其所有属性提高{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其所有屬性提高{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the friendly target, reducing damage dealt from all sources by up to # for # min"] = { ko = "파티원에게 성역의 축복을 걸어 {2}분 동안 모든 계열로부터 받는 피해를 최대 {1}까지 감소시킵니다.", zhCN = "为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多{1}点，持续{2}分钟。", zhTW = "為友方目標施加祝福，使其所受到的所有類型的傷害都減少最多{1}點，持續{2}分鐘。" },
	["places a blessing on the friendly target, reducing damage dealt from all sources by up to # for # min. in addition, when the target blocks a melee attack the attacker will take # holy damage. players may only have one blessing on them per paladin at any one time"] = { ko = "파티원에게 성역의 축복을 걸어 {2}분 동안 모든 계열로부터 받는 피해를 최대 {1}까지 감소시킵니다. 추가로 근접 공격을 방어할 경우 공격자에게 {3}의 신성 피해를 입힙니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其所受到的所有类型的伤害都减少最多{1}点，持续{2}分钟。另外，当目标格挡一次近战攻击时，攻击者会受到{3}点神圣伤害。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其所受到的所有類型的傷害都減少最多{1}點，持續{2}分鐘。另外，當目標格擋一次近戰攻擊時，攻擊者會受到{3}點神聖傷害。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the friendly target, restoring # mana every # sec for # hr"] = { ko = "대상에게 지혜의 축복을 걸어 {3}시간 동안 매 {2}초마다 {1}의 마나를 회복시킵니다.", zhCN = "为友方目标施加祝福，每{2}秒回复{1}点法力值，持续{3}小时。", zhTW = "為友方目標施加祝福，每{2}秒恢復{1}點法力，持續{3}小時。" },
	["places a blessing on the friendly target, restoring # mana every # sec for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "대상에게 지혜의 축복을 걸어 {3}시간 동안 매 {2}초마다 {1}의 마나를 회복시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，每{2}秒回复{1}点法力值，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，每{2}秒恢復{1}點法力，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the party member, reducing the amount of all threat generated by #% for # hr"] = { zhCN = "为小队成员施加祝福，令其对怪物造成的威胁降低{1}%，持续{2}小时。", zhTW = "為小隊成員施加祝福，令其對怪物造成的威脅降低{1}%，持續{2}小時。" },
	["places a blessing on the party member, reducing the amount of all threat generated by #% for # hr. players may only have one blessing on them per paladin at any one time"] = { ko = "파티원에게 구원의 축복을 걸어주어 모든 행동의 위협 수준을 {1}%만큼 감소시킵니다. {2}시간 동안 지속됩니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为小队成员施加祝福，令其对怪物造成的威胁降低{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為小隊成員施加祝福，令其對怪物造成的威脅降低{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a blessing on the party member, transfering # damage taken per hit to the caster"] = { ko = "파티원에게 희생의 축복을 걸어주어 대상이 받는 모든 타격당 {1}의 피해를 시전자가 대신 입습니다." },
	["places a blessing on the party member, transfering # damage taken per hit to the caster. lasts # sec. players may only have one blessing on them per paladin at any one time"] = { ko = "파티원에게 희생의 축복을 걸어주어 대상이 받는 모든 타격당 {1}의 피해를 시전자가 대신 입습니다. {2}초 동안 지속됩니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为小队成员施加祝福，每次该队友被击中时，圣骑士都将分担{1}点伤害，持续{2}秒。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為小隊成員施加祝福，每次該隊友被擊中時，聖騎士都將分擔{1}點傷害，持續{2}秒。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a mana well"] = { zhCN = "放置一个发酵桶，允许制造特定材料，并提供法力之井的所有增益。", zhTW = "放置發酵罐，可用來製造特定材料，並提供法力井的所有增益效果。" },
	["places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a mana well. requires a campfire nearby. may be placed over a mana well to replace it. all camping features share a cooldown of # hr"] = { ko = "특정 재료를 만들 수 있는 발효조를 배치합니다. 마나 우물의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다. 마나 우물 위에 배치하여 대체할 수 있습니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "放置一个发酵桶，允许制造特定材料，并提供法力之井的所有增益。需要附近有营火。可以放置在法力之井上以将其替换。所有露营功能共享{1}小时冷却时间。", zhTW = "放置發酵罐，可用來製造特定材料，並提供法力井的所有增益效果。需要附近有營火。可放在法力井上以取代它。所有紮營道具有共用的{1}小時冷卻時間。" },
	["places a field guide that allows players to read it and gain track beasts, and provides all the benefits of a camp chair"] = { zhCN = "放置一本野外指南，允许玩家阅读并获得追踪野兽技能，并提供营地椅子的所有增益。", zhTW = "放置一本野外指南，允許玩家閱讀並獲得追蹤野獸技能，並提供營地椅子的所有增益。" },
	["places a field guide that allows players to read it and gain track beasts, and provides all the benefits of a camp chair. requires a campfire nearby"] = { ko = "플레이어가 읽고 야수 추적 효과를 얻을 수 있는 현장 길잡이를 배치합니다. 야영지 의자의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一本野外指南，允许玩家阅读并获得追踪野兽技能，并提供营地椅子的所有增益。需要附近有营火。", zhTW = "放置一本野外指南，允許玩家閱讀並獲得追蹤野獸技能，並提供營地椅子的所有增益。需要附近有營火。" },
	["places a fishing hut that grants the ability to catch rare fish for # hr, provides fishing skill lures, and provides all of the benefits of a fish bowl"] = { zhCN = "放置一个钓鱼小屋，使你能够钓到稀有的鱼，持续{1}小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", zhTW = "放置一個釣魚小屋，使你能夠釣到稀有的魚，持續{1}小時，提供釣魚技能魚餌，並提供魚缸的所有增益。" },
	["places a fishing hut that grants the ability to catch rare fish for # hr, provides fishing skill lures, and provides all of the benefits of a fish bowl. requires a campfire nearby"] = { ko = "{1}시간 동안 희귀 물고기를 낚을 수 있는 능력과 낚시 숙련도를 증가시키는 미끼를 제공하는 낚시 오두막을 배치합니다. 생선 그릇의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个钓鱼小屋，使你能够钓到稀有的鱼，持续{1}小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。需要附近有营火。", zhTW = "放置一個釣魚小屋，使你能夠釣到稀有的魚，持續{1}小時，提供釣魚技能魚餌，並提供魚缸的所有增益。需要附近有營火。" },
	["places a fishing rack that grants the ability to catch uncommon fish for # hr, provides fishing skill lures, and provides all of the benefits of a fish bowl"] = { zhCN = "放置一个钓鱼架，使你能够钓到优秀的鱼，持续{1}小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", zhTW = "放置一個釣魚架，使你能夠釣到優秀的魚，持續{1}小時，提供釣魚技能魚餌，並提供魚缸的所有增益。" },
	["places a fishing rack that grants the ability to catch uncommon fish for # hr, provides fishing skill lures, and provides all of the benefits of a fish bowl. requires a campfire nearby"] = { ko = "{1}시간 동안 고급 물고기를 낚을 수 있는 능력과 낚시 숙련도를 증가시키는 미끼를 제공하는 낚시 선반을 배치합니다. 생선 그릇의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个钓鱼架，使你能够钓到优秀的鱼，持续{1}小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。需要附近有营火。", zhTW = "放置一個釣魚架，使你能夠釣到優秀的魚，持續{1}小時，提供釣魚技能魚餌，並提供魚缸的所有增益。需要附近有營火。" },
	["places a greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an incense candle"] = { zhCN = "放置一个温室，随着时间的推移，播种的种子会生长成草药，并提供熏香蜡烛的所有增益。", zhTW = "放置溫室，種植的種子可持續長出草藥，並提供薰香蠟燭的所有增益效果。" },
	["places a greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an incense candle. requires a campfire nearby"] = { ko = "시간이 지나면 심은 씨앗에서 약초가 자라는 온실을 배치합니다. 향기 나는 양초의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个温室，随着时间的推移，播种的种子会生长成草药，并提供熏香蜡烛的所有增益。需要附近有营火。", zhTW = "放置溫室，種植的種子可持續長出草藥，並提供薰香蠟燭的所有增益效果。需要附近有營火。" },
	["places a loom usable for recipes that require it, and provides all the benefits of a faction banner"] = { zhCN = "放置一台织布机，可用于需要它的配方，并提供阵营旗帜的所有增益。", zhTW = "放置織布機，供需要用到它的配方使用，並提供陣營旌旗的所有增益效果。" },
	["places a loom usable for recipes that require it, and provides all the benefits of a faction banner. requires a campfire nearby"] = { ko = "베틀을 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 진영 깃발의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一台织布机，可用于需要它的配方，并提供阵营旗帜的所有增益。需要附近有营火。", zhTW = "放置織布機，供需要用到它的配方使用，並提供陣營旌旗的所有增益效果。需要附近有營火。" },
	["places a master forge usable for recipes that require it, and provides all of the benefits of a sharpening wheel"] = { zhCN = "放置一个大师级熔炉，可用于需要它的配方，并提供磨刀石的所有增益。", zhTW = "放置主熔爐，供需要用到它的配方使用，可提供砂輪的所有增益效果。" },
	["places a master forge usable for recipes that require it, and provides all of the benefits of a sharpening wheel. requires a campfire nearby"] = { ko = "대가의 가열로를 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 연마 바퀴의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个大师级熔炉，可用于需要它的配方，并提供磨刀石的所有增益。需要附近有营火。", zhTW = "放置主熔爐，供需要用到它的配方使用，可提供砂輪的所有增益效果。需要附近有營火。" },
	["places a molten foundry usable for recipes that require it, and provides all the benefits of a lodestone"] = { zhCN = "放置一个熔火铸造厂，可用于需要它的配方，并提供磁石的所有增益。", zhTW = "放置熔岩鑄造場，供需要用到它的配方使用，並提供磁石的所有增益效果。" },
	["places a molten foundry usable for recipes that require it, and provides all the benefits of a lodestone. requires a campfire nearby"] = { ko = "타오르는 주조소를 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 자철석의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个熔火铸造厂，可用于需要它的配方，并提供磁石的所有增益。需要附近有营火。", zhTW = "放置熔岩鑄造場，供需要用到它的配方使用，並提供磁石的所有增益效果。需要附近有營火。" },
	["places a plague doctor's laboratory that contains healing potions and poultices, and provides all of the benefits of a first aid kit"] = { zhCN = "放置一个瘟疫医生实验室，内含治疗药水和药膏，并提供急救包的所有增益。", zhTW = "放置一個瘟疫醫生實驗室，內含治療藥水和藥膏，並提供急救箱的所有增益。" },
	["places a plague doctor's laboratory that contains healing potions and poultices, and provides all of the benefits of a first aid kit. requires a campfire nearby"] = { ko = "치유 물약과 찜질약이 들어 있는 역병 의사의 실험실을 배치합니다. 응급치료 도구의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个瘟疫医生实验室，内含治疗药水和药膏，并提供急救包的所有增益。需要附近有营火。", zhTW = "放置一個瘟疫醫生實驗室，內含治療藥水和藥膏，並提供急救箱的所有增益。需要附近有營火。" },
	["places a rock garden that spawns a common mining node over time, and provides all the benefits of a lodestone"] = { zhCN = "放置一个岩石园，随着时间的推移会生成普通的采矿点，并提供磁石的所有增益。", zhTW = "放置奇石園，可持續生成普通礦石的採集點，並提供磁石的所有增益效果。" },
	["places a rock garden that spawns a common mining node over time, and provides all the benefits of a lodestone. requires a campfire nearby"] = { ko = "시간이 지나면 일반 채광 지점을 생성하는 바위 정원을 배치합니다. 자철석의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个岩石园，随着时间的推移会生成普通的采矿点，并提供磁石的所有增益。需要附近有营火。", zhTW = "放置奇石園，可持續生成普通礦石的採集點，並提供磁石的所有增益效果。需要附近有營火。" },
	["places a seed hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an incense candle"] = { zhCN = "放置一个种子杂交器，允许将种子繁殖或组合成更稀有的级别，并提供熏香蜡烛的所有增益。", zhTW = "放置種子雜交機，讓種子可以繁殖或雜交出更稀有的品種，並提供薰香蠟燭的所有增益效果。" },
	["places a seed hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an incense candle. requires a campfire nearby"] = { ko = "씨앗을 증식하거나 결합해 더 희귀한 등급으로 만들 수 있는 씨앗 교배기를 배치합니다. 향기 나는 양초의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个种子杂交器，允许将种子繁殖或组合成更稀有的级别，并提供熏香蜡烛的所有增益。需要附近有营火。", zhTW = "放置種子雜交機，讓種子可以繁殖或雜交出更稀有的品種，並提供薰香蠟燭的所有增益效果。需要附近有營火。" },
	["places a sewing machine usable for recipes that require it, and provides all of the benefits of a camp tent"] = { zhCN = "放置一台缝纫机，可用于需要它的配方，并提供营地帐篷的所有增益。", zhTW = "放置縫紉機，供需要用到它的配方使用，並提供營地帳篷的所有增益效果。" },
	["places a sewing machine usable for recipes that require it, and provides all of the benefits of a camp tent. requires a campfire nearby"] = { ko = "바느질 기계를 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 야영지 천막의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一台缝纫机，可用于需要它的配方，并提供营地帐篷的所有增益。需要附近有营火。", zhTW = "放置縫紉機，供需要用到它的配方使用，並提供營地帳篷的所有增益效果。需要附近有營火。" },
	["places a small fish bowl that allows you and others sitting nearby to gain #% increased stats, mutually exclusive with blessing of kings"] = { ko = "작은 생선 그릇을 놓아 자신과 주위에 앉은 다른 플레이어의 능력치를 {1}%만큼 증가시킵니다. 왕의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "放置一个小的鱼缸，使你和附近坐下的其他人所有属性提高{1}%，与王者祝福不叠加。", zhTW = "放置一個小的魚缸，使你和附近坐下的其他人所有屬性提高{1}%，與王者祝福不疊加。" },
	["places a spell on the target that heals them for # the next time they take damage or receive non-periodic healing"] = { ko = "대상에 주문을 걸어두어, 다음 피해를 받거나 비주기적인 치유를 받을 때 {1}의 생명력을 회복하게 합니다.", zhCN = "向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复{1}点生命值。", zhTW = "對目標施放一個法術，使其下次受到傷害或非週期性治療時恢復{1}點生命力。" },
	["places a spell on the target that heals them for # the next time they take damage or receive non-periodic healing. when the heal occurs, prayer of mending jumps to a party or raid member within # yards. jumps up to # times and lasts # sec after each jump. this spell can only be placed on one target at a time per caster"] = { ko = "대상에 주문을 걸어두어, 다음 피해를 받거나 비주기적인 치유를 받을 때 {1}의 생명력을 회복하게 합니다. 생명력이 회복되면 {2}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다. 최대 {3}번까지 이동하며, 매 이동 시 효과가 {4}초 동안 지속됩니다. 이 주문은 시전자당 한 번에 하나의 대상에게만 걸어둘 수 있습니다.", zhCN = "向目标施加一个法术，在该目标下一次受到伤害或获得非周期性治疗时为其恢复{1}点生命值。这个治疗效果发生之后，愈合祷言会转移到{2}码范围内的小队或团队成员身上。最多可以转移{3}次，每次转移之后持续{4}秒。每个施法者在同一时间内只能在一名目标身上施放该法术。", zhTW = "對目標施放一個法術，使其下次受到傷害或非週期性治療時恢復{1}點生命力。當治療效果發動時，癒合禱言將會跳至半徑{2}碼範圍內的一名小隊或團隊成員身上。最多跳躍{3}次，並且每次跳躍後可持續{4}秒。每位施法者一次只能對一個目標施放此法術。" },
	["places a spell on the target that heals them for # the next time they take damage or receive non-periodic healing. when the heal occurs, prayer of mending jumps to a party or raid member within # yds. jumps up to # times and lasts # sec after each jump. this spell can only be placed on one target at a time per caster"] = { ko = "대상에 주문을 걸어두어, 다음 피해를 받거나 비주기적인 치유를 받을 때 {1}의 생명력을 회복하게 합니다. 생명력이 회복되면 {2}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다. 최대 {3}번까지 이동하며, 매 이동 시 효과가 {4}초 동안 지속됩니다. 이 주문은 시전자당 한 번에 하나의 대상에게만 걸어둘 수 있습니다." },
	["places a spinning wheel that allows the creation of certain reagents, and provides all the benefits of a faction banner"] = { zhCN = "放置一个纺车，允许制造特定材料，并提供阵营旗帜的所有增益。", zhTW = "放置紡車，可用來製造特定材料，並提供陣營旌旗的所有增益效果。" },
	["places a spinning wheel that allows the creation of certain reagents, and provides all the benefits of a faction banner. requires a campfire nearby"] = { ko = "특정 재료를 만들 수 있는 물레를 배치합니다. 진영 깃발의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个纺车，允许制造特定材料，并提供阵营旗帜的所有增益。需要附近有营火。", zhTW = "放置紡車，可用來製造特定材料，並提供陣營旌旗的所有增益效果。需要附近有營火。" },
	["places a tanning rack that allows the creation of certain reagents, and provides all of the benefits of a camp tent"] = { zhCN = "放置一个制革架，允许制造特定材料，并提供营地帐篷的所有增益。", zhTW = "放置製皮架，可用來製造特定材料，並提供營地帳篷的所有增益效果。" },
	["places a tanning rack that allows the creation of certain reagents, and provides all of the benefits of a camp tent. requires a campfire nearby"] = { ko = "특정 재료를 만들 수 있는 무두질 선반을 배치합니다. 야영지 천막의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个制革架，允许制造特定材料，并提供营地帐篷的所有增益。需要附近有营火。", zhTW = "放置製皮架，可用來製造特定材料，並提供營地帳篷的所有增益效果。需要附近有營火。" },
	["places a toxin study that contains healing potions and anti-venom, and provides all of the benefits of a first aid kit"] = { zhCN = "放置一个毒素研究，内含治疗药水和抗毒药剂，并提供急救包的所有增益。", zhTW = "放置一個毒素研究區，內含治療藥水和抗毒藥劑，並提供急救箱的所有增益。" },
	["places a toxin study that contains healing potions and anti-venom, and provides all of the benefits of a first aid kit. requires a campfire nearby"] = { ko = "치유 물약과 해독제가 들어 있는 독소 연구대를 배치합니다. 응급치료 도구의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个毒素研究，内含治疗药水和抗毒药剂，并提供急救包的所有增益。需要附近有营火。", zhTW = "放置一個毒素研究區，內含治療藥水和抗毒藥劑，並提供急救箱的所有增益。需要附近有營火。" },
	["places a trapper's workbench containing # trap, and provides all the benefits of a camp chair"] = { zhCN = "放置一个捕兽者工作台，内含{1}个陷阱，并提供营地椅子的所有增益。", zhTW = "放置一個陷捕者的工作臺，內含{1}個陷阱，並提供營地椅子的所有增益。" },
	["places a trapper's workbench containing # trap, and provides all the benefits of a camp chair. requires a campfire nearby"] = { ko = "덫 {1}개가 들어 있는 덫사냥꾼의 작업대를 배치합니다. 야영지 의자의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个捕兽者工作台，内含{1}个陷阱，并提供营地椅子的所有增益。需要附近有营火。", zhTW = "放置一個陷捕者的工作臺，內含{1}個陷阱，並提供營地椅子的所有增益。需要附近有營火。" },
	["places an alchemy laboratory usable for recipes that require it, and provides all of the benefits of a mana well"] = { zhCN = "放置一个炼金实验室，可用于需要它的配方，并提供法力之井的所有增益。", zhTW = "放置鍊金實驗室，供需要用到它的配方使用，並提供法力井的所有增益效果。" },
	["places an alchemy laboratory usable for recipes that require it, and provides all of the benefits of a mana well. requires a campfire nearby"] = { ko = "연금술 실험실을 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 마나 우물의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个炼金实验室，可用于需要它的配方，并提供法力之井的所有增益。需要附近有营火。", zhTW = "放置鍊金實驗室，供需要用到它的配方使用，並提供法力井的所有增益效果。需要附近有營火。" },
	["places an anarchist's workbench usable for recipes that require it"] = { zhCN = "放置一个无政府主义者的工作台，可用于需要它的配方。", zhTW = "放置叛亂者的工作臺，供需要用到它的配方使用。" },
	["places an anarchist's workbench usable for recipes that require it. requires a campfire nearby. all camping features share a cooldown of # hr"] = { ko = "무정부주의자의 작업대를 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 주위에 모닥불이 있어야 합니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "放置一个无政府主义者的工作台，可用于需要它的配方。需要附近有营火。所有露营功能共享{1}小时冷却时间。", zhTW = "放置叛亂者的工作臺，供需要用到它的配方使用。需要附近有營火。所有紮營道具有共用的{1}小時冷卻時間。" },
	["places an anvil, and provides all of the benefits of a sharpening wheel"] = { zhCN = "放置一个铁砧，并提供磨刀石的所有增益。", zhTW = "放置鐵砧，可提供砂輪的所有增益效果。" },
	["places an anvil, and provides all of the benefits of a sharpening wheel. requires a campfire nearby"] = { ko = "모루를 배치합니다. 연마 바퀴의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个铁砧，并提供磨刀石的所有增益。需要附近有营火。", zhTW = "放置鐵砧，可提供砂輪的所有增益效果。需要附近有營火。" },
	["places an arcane forge usable for recipes that require it, and provides all the benefits of an enchanted lute"] = { zhCN = "放置一座奥术熔炉，可用于需要它的配方，并提供附魔的鲁特琴的所有增益。", zhTW = "放置秘法熔爐，供需要用到它的配方使用，並提供附魔魯特琴的所有增益效果。" },
	["places an arcane forge usable for recipes that require it, and provides all the benefits of an enchanted lute. requires a campfire nearby"] = { ko = "비전 가열로를 배치합니다. 해당 시설이 필요한 제작법에 사용됩니다. 마력 깃든 류트의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一座奥术熔炉，可用于需要它的配方，并提供附魔的鲁特琴的所有增益。需要附近有营火。", zhTW = "放置秘法熔爐，供需要用到它的配方使用，並提供附魔魯特琴的所有增益效果。需要附近有營火。" },
	["places an arcane salvager that enables more efficient disenchanting, and provides all the benefits of an enchanted lute"] = { zhCN = "放置一个奥术回收器，能够更高效地进行分解，并提供附魔的鲁特琴的所有增益。", zhTW = "放置秘法回收機，可提高分解的效率，並提供附魔魯特琴的所有增益效果。" },
	["places an arcane salvager that enables more efficient disenchanting, and provides all the benefits of an enchanted lute. requires a campfire nearby"] = { ko = "더 효율적인 마력 추출이 가능한 비전 수거기를 배치합니다. 마력 깃든 류트의 효과를 모두 제공합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "放置一个奥术回收器，能够更高效地进行分解，并提供附魔的鲁特琴的所有增益。需要附近有营火。", zhTW = "放置秘法回收機，可提高分解的效率，並提供附魔魯特琴的所有增益效果。需要附近有營火。" },
	["places an iron oven required for the most advanced cooking recipes"] = { ko = "최고급 요리 조리법에 필요한 철 가마를 배치합니다.", zhCN = "放置一个铁炉，可供最高级的烹饪配方使用。", zhTW = "放置鐵爐，供需要用到它的配方使用。" },
	["places an iron oven required for the most advanced cooking recipes. requires a cooking fire nearby. all camping features share a cooldown of # hr"] = { ko = "최고급 요리 조리법에 필요한 철 가마를 배치합니다. 주위에 요리용 모닥불이 있어야 합니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "放置一个铁炉，可供最高级的烹饪配方使用。需要附近有烹饪用火。所有露营功能共享{1}小时冷却时间。", zhTW = "放置鐵爐，供需要用到它的配方使用。需要附近有烹飪用火。所有紮營道具有共用的{1}小時冷卻時間。" },
	["places the hunter's mark on the target, increasing the ranged attack power of all attackers against that target by # in addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible. the target also appears on the mini-map. lasts for # min"] = { ko = "사냥꾼의 징표를 대상에게 걸어 대상을 공격하는 모든 아군의 원거리 전투력을 26만큼 증가시킵니다. 이 능력에 걸린 대상은 은신이나 투명 상태에도 사냥꾼의 시야에 보이게 되며 미니맵에 표시됩니다. {2}분 동안 지속됩니다.", zhCN = "给目标加上猎人印记，使任何攻击者的远程武器对该目标的攻击强度提高26点。另外，被施加了这项技能的目标总是可以被猎人看见，无论是隐形还是潜行都无法摆脱。目标的位置也会在微缩地图上显示出来，持续{2}分钟。", zhTW = "給目標加上獵人印記，使任何攻擊者的遠程武器對該目標的攻擊強度提高26點。另外，被施加了這項技能的目標總是可以被獵人看見，無論是隱形還是潛行都無法擺脫。目標的位置也會在小地圖上顯示出來，持續{2}分鐘。" },
	["players may only have one aura on them per paladin at any one time"] = { ko = "오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "每個聖騎士在同一時間內只能開啟一種光環。" },
	["players may only have one blessing on them per paladin at any one time"] = { ko = "성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" },
	["players sitting or crafting nearby for # min will gain benefits from other camp features"] = { ko = "주위에서 {1}분 동안 앉아 있거나 제작을 하는 플레이어는 다른 야영 설비의 이로운 효과를 받습니다.", zhCN = "在附近坐下或进行制造持续{1}分钟的玩家将获得其他营地设施的增益效果。", zhTW = "玩家在附近坐下或製作物品，持續{1}分鐘，就能獲得其他營地功能的增益效果。" },
	["poisons target for # nature damage every # sec for # sec"] = { ko = "대상을 감염시켜 {3}초 동안 매 {2}초마다 {1}의 자연 피해를 입힙니다.", zhCN = "使目标每{2}秒毒发一次，对其造成{1}点自然伤害，持续{3}秒。", zhTW = "使目標每{2}秒毒發一次，對其造成{1}點自然傷害，持續{3}秒。" },
	["pounce, stunning the target for # sec and causing # damage over # sec"] = { ko = "적을 암습하여 {1}초 동안 기절시키고 {3}초에 걸쳐 총 {2}의 피해를 입힙니다." },
	["pounce, stunning the target for # sec and causing # damage over # sec. must be prowling and behind the target. awards # combo point"] = { ko = "적을 암습하여 {1}초 동안 기절시키고 {3}초에 걸쳐 총 {2}의 피해를 입힙니다. 숨은 상태로 적의 배후에서 공격해야 합니다. {4}의 연계 포인트가 주어집니다.", zhCN = "突袭敌人，使其昏迷{1}秒并在{3}秒内造成总计{2}点伤害。必须在潜行状态下从目标背后发动，奖励{4}个连击点数。", zhTW = "突襲敵人，使其昏迷{1}秒並在{3}秒內造成總計{2}點傷害。必須在潛行狀態下從目標背後發動，獎勵{4}個連擊點數。" },
	["power infuses all party and raid members, increasing their shadow resistance by # for # min"] = { ko = "모든 파티원과 공격대원에게 힘이 깃들어 {2}분 동안 암흑 저항력을 {1}만큼 증가시킵니다.", zhCN = "力量注入所有队伍和团队成员，使其暗影抗性提高{1}点，持续{2}分钟。", zhTW = "能量充滿所有小隊與團隊成員，使其暗影抗性提高{1}點，持續{2}分鐘。" },
	["power infuses all party and raid members, increasing their spirit by # for # hr"] = { ko = "모든 파티원과 공격대원에게 힘이 깃들어 {2}시간 동안 정신력을 {1}만큼 증가시킵니다.", zhCN = "将力量注入所有小队和团队成员体内，使其精神提高{1}点，持续{2}小时。", zhTW = "能量充滿所有小隊與團隊成員，使其精神提高{1}點，持續{2}小時。" },
	["power infuses all party and raid members, increasing their stamina by # for # hr"] = { ko = "파티원과 공격대원에게 성스러운 기운을 불어넣어 {2}시간 동안 체력을 {1}만큼 증가시킵니다.", zhCN = "圣洁的能量充满小队和团队成员的身体，使其耐力提高{1}点，持续{2}小时。", zhTW = "聖潔的能量充滿目標小隊和團隊成員的身體，提高他們的耐力{1}點，持續{2}小時。" },
	["power infuses the target, increasing their stamina by # for # hr"] = { ko = "대상에 신성한 힘을 불어넣어 {2}시간 동안 체력을 {1}만큼 증가시킵니다.", zhCN = "圣洁的能量充满目标全身，令其耐力提高{1}点，持续{2}小时。", zhTW = "聖潔的能量充滿目標全身，令其耐力提高{1}點，持續{2}小時。" },
	["protects the caster, increasing armor by # and increases health regeneration by # health per # sec"] = { ko = "방어도가 {1}만큼, {3}초당 생명력 회복 속도가 {2}만큼 증가합니다." },
	["protects the caster, increasing armor by # and increases health regeneration by # health per # sec. for # min"] = { ko = "방어도가 {1}만큼, {3}초당 생명력 회복 속도가 {2}만큼 증가합니다. {4}분 동안 지속됩니다.", zhCN = "保护施法者，使其护甲提高{1}点，并使其每{3}秒恢复{2}点生命值，持续{4}分钟。", zhTW = "保護施法者，使其護甲值提高{1}點，生命力恢復速度每{3}秒提高{2}點生命力，持續{4}分鐘。" },
	["protects the caster, increasing armor by #, shadow resistance by # and increases health regeneration by # health per # sec"] = { ko = "방어도가 {1}만큼, 암흑 저항력이 {2}만큼, {4}초당 생명력 회복 속도가 {3}만큼 증가합니다." },
	["protects the caster, increasing armor by #, shadow resistance by # and increases health regeneration by # health per # sec. for # min"] = { ko = "방어도가 {1}만큼, 암흑 저항력이 {2}만큼, {4}초당 생명력 회복 속도가 {3}만큼 증가합니다. {5}분 동안 지속됩니다.", zhCN = "保护施法者，使其护甲提高{1}点、暗影抗性提高{2}点，并使其每{4}秒恢复{3}点生命值，持续{5}分钟。", zhTW = "保護施法者，使其護甲值提高{1}點，暗影抗性提高{2}點，同時生命力恢復速度每{4}秒提高{3}點生命力，持續{5}分鐘。" },
	["protects the paladin from all damage and spells for # sec, but reduces all damage you deal by #%"] = { ko = "{1}초 동안 모든 공격과 주문으로부터 자신을 보호하지만 자신의 모든 공격력이 {2}%만큼 감소합니다.", zhCN = "使圣骑士免疫所有伤害和法术，持续{1}秒，但你造成的所有伤害降低{2}%。", zhTW = "使聖騎士對所有的傷害和法術攻擊免疫，持續{1}秒，但令你造成的所有傷害降低{2}%。" },
	["protects the paladin from all damage and spells for # sec, but reduces all damage you deal by #%. applies forbearance for # min. cannot be cast while forbearance is active"] = { ko = "{1}초 동안 모든 공격과 주문으로부터 자신을 보호하지만 자신의 모든 공격력이 {2}%만큼 감소합니다. {3}분 동안 참을성이 부여됩니다. 참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "使圣骑士免疫所有伤害和法术，持续{1}秒，但你造成的所有伤害降低{2}%。施加自律，持续{3}分钟。自律效果激活时无法施放。", zhTW = "使聖騎士對所有的傷害和法術攻擊免疫，持續{1}秒，但令你造成的所有傷害降低{2}%。施加自律效果，持續{3}分鐘。自律效果生效期間，無法施放。" },
	["pummel the target for # damage"] = { ko = "적을 무기 자루로 공격하여 {1}의 피해를 입힙니다." },
	["pummel the target for # damage and interrupt the spell being cast for # sec"] = { ko = "적을 무기 자루로 공격하여 {1}의 피해를 입히고 {2}초 동안 주문 시전을 방해합니다.", zhCN = "击打目标，对其造成{1}点伤害，并且使其在{2}秒内不能施法。", zhTW = "擊打目標，對其造成{1}點傷害，並且使其在{2}秒內不能施法。" },
	["pummel the target for # damage. it also interrupts spellcasting and prevents any spell in that school from being cast for # sec"] = { ko = "적을 무기 자루로 공격하여 {1}의 피해를 입힙니다. 또한 대상이 {2}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다.", zhCN = "击打目标，对其造成{1}点伤害，并且使其在{2}秒内不能施法。", zhTW = "擊打目標，對其造成{1}點傷害，並且使其在{2}秒內不能施法。" },
	["punctures target's armor, lowering it by #"] = { ko = "적의 방어구를 관통하여 방어도를 {1}만큼 감소시킵니다." },
	["purges # harmful magic effect from a friend or # beneficial magic effect from an enemy"] = { ko = "아군으로부터 {1}개의 해로운 마법 효과를 제거하거나 적으로부터 {2}개의 이로운 마법 효과를 제거합니다.", zhCN = "从一个友方目标身上消除{1}个有害魔法效果，或者从一个敌方目标身上消除{2}个有益魔法效果。", zhTW = "從一個友方目標身上消除{1}個有害魔法效果，或者從一個敵方目標身上消除{2}個有益魔法效果。" },
	["purges # harmful magic effect from a friend or # beneficial magic effect from an enemy. if an effect is devoured, the felhunter will be healed for #"] = { ko = "아군으로부터 {1}개의 해로운 마법 효과를 제거하거나 적으로부터 {2}개의 이로운 마법 효과를 제거합니다. 마법을 삼키게 되면 지옥사냥개는 {3}의 생명력을 회복합니다.", zhCN = "从一个友方目标身上消除{1}个有害魔法效果，或者从一个敌方目标身上消除{2}个有益魔法效果。每吞噬一个魔法效果，地狱猎犬就可回复{3}点生命值。", zhTW = "從一個友方目標身上消除{1}個有害魔法效果，或者從一個敵方目標身上消除{2}個有益魔法效果。每吞噬一個魔法效果，地獄獵犬就可回復{3}點生命力。" },
	["purges the enemy target, removing # beneficial magic effects"] = { ko = "적을 정화하여 {1}개의 이로운 마법 효과를 제거합니다.", zhCN = "净化敌方目标，移除{1}个增益魔法效果。", zhTW = "淨化敵方目標，移除{1}個增益魔法效果。" },
	["purges the enemy target, removing # magic effect"] = { ko = "적을 정화하여 {1}개의 이로운 마법 효과를 제거합니다.", zhCN = "净化敌方目标，移除{1}个魔法效果。", zhTW = "淨化敵方目標，移除{1}個魔法效果。" },
	["purifies the friendly target, removing # disease effect and # poison effect"] = { ko = "대상을 순화하여 질병 {1}개와 독 {2}개를 제거합니다.", zhCN = "净化友方目标，移除{1}个疾病效果和{2}个中毒效果。", zhTW = "淨化友方目標，移除{1}個疾病效果和{2}個中毒效果。" },
	["puts the enemy target in a state of meditation, incapacitating them for up to # sec"] = { ko = "적을 최대 {1}초 동안 회고의 시간을 가지게 하여 행동 불가 상태로 만듭니다.", zhCN = "使敌方目标进入冥想状态，最多瘫痪{1}秒。", zhTW = "使目標進入冥想狀態，令其癱瘓最多持續{1}秒。" },
	["puts the enemy target in a state of meditation, incapacitating them for up to # sec. any damage caused will awaken the target. only works against humanoids"] = { ko = "적을 최대 {1}초 동안 회고의 시간을 가지게 하여 행동 불가 상태로 만듭니다. 대상이 피해를 입으면 깨어납니다. 인간형에게만 사용할 수 있습니다.", zhCN = "使敌方目标进入冥想状态，最多瘫痪{1}秒。造成任何伤害都会唤醒目标。只对人型生物有效。", zhTW = "使目標進入冥想狀態，令其癱瘓最多持續{1}秒。任何傷害都會喚醒目標。只對人型生物有效。" },
	["rains starshards down on the enemy target's head, causing # arcane damage over # sec"] = { ko = "적의 머리 위로 별조각을 내려 {2}초에 걸쳐 총 {1}의 비전 피해를 입힙니다.", zhCN = "召唤群星的碎片攻击敌人，在{2}秒内对其造成{1}点奥术伤害。", zhTW = "召喚群星的碎片攻擊敵人，在{2}秒內對其造成{1}點秘法傷害。" },
	["rains starshards down on the enemy target's head, causing #,# arcane damage over # sec"] = { ko = "적의 머리 위로 별조각을 내려 {3}초에 걸쳐 총 {1},{2}의 비전 피해를 입힙니다.", zhCN = "召唤群星的碎片攻击敌人，在{3}秒内对其造成{1},{2}点奥术伤害。", zhTW = "召喚群星的碎片攻擊敵人，在{3}秒內對其造成{1},{2}點秘法傷害。" },
	["rake the target for # damage and an additional # damage over # sec"] = { ko = "대상을 발톱으로 할퀴어 {1}의 피해를 입히고 추가로 {3}초에 걸쳐 총 {2}의 피해를 입힙니다.", zhCN = "对目标造成{1}点伤害，并在{3}秒内造成总计{2}点额外伤害。", zhTW = "對目標造成{1}點傷害，並在{3}秒內造成總計{2}點額外傷害。" },
	["rake the target for # damage and an additional # damage over # sec. awards # combo point"] = { ko = "대상을 발톱으로 할퀴어 {1}의 피해를 입히고 추가로 {3}초에 걸쳐 총 {2}의 피해를 입힙니다. {4}의 연계 포인트가 주어집니다.", zhCN = "对目标造成{1}点伤害，并在{3}秒内造成总计{2}点额外伤害。奖励{4}个连击点数。", zhTW = "對目標造成{1}點傷害，並在{3}秒內造成總計{2}點額外傷害。獎勵{4}個連擊點數。" },
	["ravage the target, causing #% damage plus # to the target"] = { ko = "대상을 공격하여 공격력의 {1}%에 추가로 {2}의 피해를 입힙니다.", zhCN = "重击目标，对其造成{1}%外加{2}点伤害。", zhTW = "重擊目標，對其造成{1}%外加{2}點傷害。" },
	["ravage the target, causing #% damage plus # to the target. must be prowling and behind the target. awards # combo point"] = { ko = "대상을 공격하여 공격력의 {1}%에 추가로 {2}의 피해를 입힙니다. 숨은 상태로 적의 배후에서 공격해야 합니다. {3}의 연계 포인트가 주어집니다.", zhCN = "重击目标，对其造成{1}%外加{2}点伤害。必须在潜行状态下从目标背后发动。奖励{3}个连击点数。", zhTW = "重擊目標，對其造成{1}%外加{2}點傷害。必須在潛行狀態下從目標背後發動。獎勵{3}個連擊點數。" },
	["reach into the bag and hope for the best"] = { ko = "가방에 손을 넣고 좋은 게 나오기를 바랍니다.", zhCN = "把手伸进袋子里，自求多福吧。", zhTW = "將手伸入袋子中，祈求最好的結果。" },
	["reduces all damage taken by #%"] = { ko = "받는 모든 피해가 {1}%만큼 감소합니다.", zhCN = "使你受到的所有伤害降低{1}%。", zhTW = "受到的所有傷害降低{1}%。" },
	["reduces all spell damage taken by #%"] = { ko = "모든 주문으로부터 받는 피해가 {1}%만큼 감소합니다.", zhCN = "使你受到的所有法术伤害降低{1}%。", zhTW = "對你所造成的法術傷害降低{1}%。" },
	["reduces damage from falling"] = { ko = "낙하 피해가 감소됩니다.", zhCN = "减少从高处坠落所受的伤害。", zhTW = "減少從高處墜落所受的傷害。" },
	["reduces damage taken from fire, frost, and nature effects by #%"] = { ko = "받는 화염, 냉기, 자연 피해가 {1}%만큼 감소합니다.", zhCN = "受到的火焰、冰霜和自然效果伤害降低{1}%。", zhTW = "所受到的火焰、冰霜和自然傷害降低{1}%。" },
	["reduces target enemy's attack power by # for # sec"] = { ko = "{2}초 동안 적의 전투력을 {1}만큼 감소시킵니다.", zhCN = "使敌人的攻击强度降低{1}点，持续{2}秒。", zhTW = "使敵人的攻擊強度降低{1}點，持續{2}秒。" },
	["reduces the cast time of starfire by # sec and starfire has a #% chance to stun its target for # sec"] = { ko = "별빛 화살의 시전 시간이 {1}초만큼 감소하며, 별빛 화살 적중 시 {2}%의 확률로 적을 {3}초 동안 기절시킵니다.", zhCN = "使你的星火术的施法时间缩短{1}秒，并有{2}%的几率使目标昏迷{3}秒。", zhTW = "使你的星火術的施法時間縮短{1}秒，且星火術有{2}%的機率使目標昏迷{3}秒。" },
	["reduces the cast time of your ghost wolf spell by # sec, and ghost wolf may be used indoors"] = { ko = "늑대 정령 주문의 시전 시간이 {1}초만큼 감소합니다. 또한 늑대 정령을 실내에서 사용할 수 있도록 합니다.", zhCN = "使你的幽魂之狼法术的施法时间缩短{1}秒，且可在室内使用。", zhTW = "使你的鬼魂之狼法術的施法時間縮短{1}秒，並可在室內使用鬼魂之狼。" },
	["reduces the cast time of your hammer of wrath by # sec, and reduces all threat you generate by #% while righteous fury is not active"] = { ko = "천벌의 망치의 시전 시간이 {1}초만큼 감소합니다. 정의의 격노가 활성화되지 않은 동안에는 모든 위협 수준 생성량이 {2}%만큼 감소합니다.", zhCN = "使你的愤怒之锤施法时间缩短{1}秒，并在正义之怒未激活时，你产生的所有威胁值降低{2}%。", zhTW = "使你憤怒之錘的施法時間縮短{1}秒，且當正義之怒未生效時，你產生的所有威脅值降低{2}%。" },
	["reduces the cast time of your healing touch spell by # sec and increases all damage you deal by #%"] = { ko = "치유의 손길의 시전 시간이 {1}초만큼 감소합니다. 또한 자신의 모든 공격력이 {2}%만큼 증가합니다.", zhCN = "使你的治疗之触的施法时间缩短{1}秒，并使你造成的所有伤害提高{2}%。", zhTW = "使你的治療之觸的施法時間縮短{1}秒，你造成的所有傷害提高{2}%。" },
	["reduces the cast time of your lightning bolt, chain lightning, and lava burst spells by # sec"] = { ko = "번개 화살과 연쇄 번개, 용암 폭발의 시전 시간이 {1}초만큼 감소합니다.", zhCN = "使你的闪电箭、闪电链和熔岩爆裂的施法时间缩短{1}秒。", zhTW = "使你的閃電箭、閃電鏈和熔岩爆發的施法時間縮短{1}秒。" },
	["reduces the cast time of your wrath spell by # sec and its mana cost by #%"] = { ko = "천벌 주문의 시전 시간이 {1}초만큼, 마나 소모량은 {2}%만큼 감소합니다.", zhCN = "使你的愤怒法术的施法时间缩短{1}秒，法力值消耗降低{2}%。", zhTW = "使你的憤怒法術的施法時間縮短{1}秒，法力消耗降低{2}%。" },
	["reduces the casting time of your corruption spell by # sec and increases the damage it deals by #%"] = { ko = "부패의 시전 시간이 {1}초만큼 감소합니다. 또한 부패가 입히는 피해가 {2}%만큼 증가합니다.", zhCN = "使你的腐蚀术的施法时间缩短{1}秒，造成的伤害提高{2}%。", zhTW = "使你腐蝕術的施法時間縮短{1}秒，且其造成的傷害提高{2}%。" },
	["reduces the casting time of your fireball and frostfire bolt spells by # sec"] = { ko = "화염구 및 얼음불꽃 화살의 시전 시간이 {1}초만큼 단축됩니다.", zhCN = "使你的火球术和霜火之箭的施法时间缩短{1}秒。", zhTW = "使你火球術和霜火箭的施法時間縮短{1}秒。" },
	["reduces the casting time of your frostbolt spell by # sec"] = { ko = "얼음 화살의 시전 시간이 {1}초만큼 단축됩니다.", zhCN = "使你的寒冰箭的施法时间缩短{1}秒。", zhTW = "使你寒冰箭的施法時間縮短{1}秒。" },
	["reduces the casting time of your healing wave spell by # sec"] = { ko = "치유의 물결의 시전 시간이 {1}초만큼 단축됩니다.", zhCN = "使你的治疗波的施法时间减少{1}秒。", zhTW = "使你治療波的施法時間縮短{1}秒。" },
	["reduces the casting time of your imp, voidwalker, succubus, incubus, and felhunter summoning spells by # sec and the mana cost by #%"] = { ko = "임프와 보이드워커, 서큐버스, 인큐버스, 지옥사냥개 소환의 시전 시간이 {1}초만큼 단축되고 소비되는 마나가 {2}%만큼 감소됩니다.", zhCN = "使你召唤小鬼、虚空行者、魅魔、夜魔和地狱猎犬的施法时间减少{1}秒，法力值消耗降低{2}%。", zhTW = "使你的召喚小鬼、虛空行者、魅魔、夢魔和地獄獵犬的施法時間減少{1}秒，法力消耗降低{2}%。" },
	["reduces the casting time of your mana burn spell by # sec"] = { ko = "마나 연소의 시전 시간이 {1}초만큼 단축됩니다.", zhCN = "使你的法力燃烧的施法时间缩短{1}秒。", zhTW = "使你法力燃燒的施法時間縮短{1}秒。" },
	["reduces the casting time of your shadow bolt, immolate, and incinerate spells by # sec and your soul fire spell by # sec"] = { ko = "어둠의 화살과 제물, 소각의 시전 시간이 {1}초만큼, 영혼의 불꽃의 시전 시간이 {2}초만큼 단축됩니다.", zhCN = "使你的暗影箭、献祭和烧尽的施法时间缩短{1}秒，灵魂之火的施法时间缩短{2}秒。", zhTW = "使你的暗影箭、獻祭和燒盡的施法時間縮短{1}秒，靈魂之火的施法時間縮短{2}秒。" },
	["reduces the casting time of your smite, holy fire, heal, and greater heal spells by # sec"] = { ko = "성스러운 일격과 신성한 불꽃, 치유, 상급 치유의 시전 시간이 {1}초만큼 단축됩니다.", zhCN = "使你的惩击、神圣之火、治疗术和强效治疗术的施法时间缩短{1}秒。", zhTW = "使你懲擊、神聖之火、治療術和強效治療術的施法時間縮短{1}秒。" },
	["reduces the chance enemies have to detect you while in stealth mode as if you were # level higher"] = { ko = "은신 효과를 {1} 레벨 증가시켜, 적이 자신을 발견할 확률이 감소합니다.", zhCN = "当你在潜行状态下时，降低敌人侦测到你的几率，等同于你的等级提高了{1}级。", zhTW = "當你在潛行狀態下時，降低敵人偵測到你的機率，效果相當於你的等級高{1}級。" },
	["reduces the chance enemies have to detect you while in stealth mode as if you were # levels higher"] = { ko = "은신 효과를 {1} 레벨 증가시켜, 적이 자신을 발견할 확률이 감소합니다.", zhCN = "当你在潜行状态下时，降低敌人侦测到你的几率，等同于你的等级提高了{1}级。", zhTW = "當你在潛行狀態下時，降低敵人偵測到你的機率，效果相當於你的等級高{1}級。" },
	["reduces the chance for your attacks to be dodged or parried by #%"] = { ko = "공격이 회피당하거나 무기 막기에 막힐 확률이 {1}%만큼 감소합니다.", zhCN = "使你的攻击被躲闪或招架的几率降低{1}%。", zhTW = "使你的攻擊被閃躲或招架的機率降低{1}%。" },
	["reduces the chance you'll be hit by melee and ranged attacks by #% for # sec or until you are missed # times"] = { ko = "{2}초 동안 또는 자신에 대한 공격이 {3}회 빗나갈 때까지 근접 및 원거리 공격에 적중당할 확률이 {1}%만큼 감소합니다.", zhCN = "使你被近战和远程攻击命中的几率降低{1}%，持续{2}秒，或直到被未命中{3}次为止。", zhTW = "使你被近戰和遠程攻擊命中的機率降低{1}%，持續{2}秒，或直到{3}次攻擊未命中你為止。" },
	["reduces the cooldown of grounding totem by -# sec"] = { ko = "마법정화 토템의 재사용 대기시간이 -{1}초만큼 감소합니다.", zhCN = "使根基图腾的冷却时间缩短-{1}秒。", zhTW = "使根基圖騰的冷卻時間縮短-{1}秒。" },
	["reduces the cooldown of your arcane shot by # sec"] = { ko = "신비한 사격의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的奥术射击的冷却时间缩短{1}秒。", zhTW = "使你的秘法射擊的冷卻時間減少{1}秒。" },
	["reduces the cooldown of your arcane shot by # sec. does not affect the cooldown of abilities which share a cooldown with arcane shot"] = { ko = "신비한 사격의 재사용 대기시간이 {1}초만큼 감소합니다. 신비한 사격과 재사용 대기시간을 공유하는 능력의 재사용 대기시간에는 영향을 주지 않습니다.", zhCN = "使你的奥术射击的冷却时间缩短{1}秒。不影响与奥术射击共享冷却时间的技能。", zhTW = "使你的秘法射擊的冷卻時間減少{1}秒。不會影響與秘法射擊共用冷卻時間的技能的冷卻時間。" },
	["reduces the cooldown of your blessing of protection by # min and increases the duration of your blessing of freedom by # sec"] = { ko = "보호의 축복의 재사용 대기시간이 {1}분만큼 단축되고 자유의 축복 지속시간이 {2}만큼 증가합니다.", zhCN = "使你的保护祝福冷却时间缩短{1}分钟，并使自由祝福持续时间延长{2}秒。", zhTW = "使你的保護祝福的冷卻時間縮短{1}分鐘，自由祝福的效果持續時間延長{2}秒。" },
	["reduces the cooldown of your disarm ability by # sec"] = { ko = "무장 해제의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的缴械技能冷却时间缩短{1}秒。", zhTW = "使你的繳械技能的冷卻時間縮短{1}秒。" },
	["reduces the cooldown of your fire blast spell by # sec"] = { ko = "화염 작열의 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的火焰冲击冷却时间缩短{1}秒。", zhTW = "使你火焰衝擊的冷卻時間縮短{1}秒。" },
	["reduces the cooldown of your fire blast spell by # sec. killing a non-trivial target increases the critical strike chance of your next fire blast cast within # sec by #%"] = { ko = "화염 작열의 재사용 대기시간이 {1}초만큼 감소합니다. 사소하지 않은 대상을 처치하면 {2}초 안에 시전하는 다음 화염 작열의 치명타 및 극대화율이 {3}%만큼 증가합니다.", zhCN = "使你的火焰冲击冷却时间缩短{1}秒。击杀一个能为你提供经验值或荣誉值的目标后，你在{2}秒内施放的下一次火焰冲击的爆击几率提高{3}%。", zhTW = "使你火焰衝擊的冷卻時間縮短{1}秒。殺死一個有實力的目標時，使你在{2}秒內施放的下一個火焰衝擊的致命一擊機率提高{3}%。" },
	["reduces the cooldown of your frost nova spell by # sec"] = { ko = "얼음 회오리의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的冰霜新星的冷却时间减少{1}秒。", zhTW = "使你的冰霜新星的冷卻時間減少{1}秒。" },
	["reduces the cooldown of your intercept ability by # sec"] = { ko = "봉쇄의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的拦截技能的冷却时间减少{1}秒。", zhTW = "使你的攔截技能的冷卻時間減少{1}秒。" },
	["reduces the cooldown of your mind blast spell by # sec"] = { ko = "정신 분열의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的心灵震爆的冷却时间减少{1}秒。", zhTW = "使你的心靈震爆的冷卻時間減少{1}秒。" },
	["reduces the cooldown of your psychic scream spell by # sec"] = { ko = "영혼의 절규 주문의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的心灵尖啸的冷却时间减少{1}秒。", zhTW = "使你的心靈尖嘯的冷卻時間減少{1}秒。" },
	["reduces the cooldown of your reincarnation spell by # min, increases your maximum health by #%, and increases the amount of health and mana you reincarnate with by an additional #%"] = { ko = "윤회 주문의 재사용 대기시간이 {1}분만큼 단축되고, 최대 생명력이 {2}%만큼 증가합니다. 또한 윤회로 부활할 때 지니는 생명력과 마나가 추가로 {3}%만큼 증가합니다.", zhCN = "使你的复生法术冷却时间缩短{1}分钟，最大生命值提高{2}%，并使你复生时获得的生命值和法力值额外提高{3}%。", zhTW = "使你復生法術的冷卻時間縮短{1}分鐘，使你的生命力上限提高{2}%，並使你復生時獲得的生命力和法力額外提高{3}%。" },
	["reduces the cooldown of your shield wall ability by # min"] = { ko = "방패의 벽의 재사용 대기시간이 {1}분만큼 감소합니다.", zhCN = "使你的盾墙技能的冷却时间缩短{1}分钟。", zhTW = "使你盾牆技能的冷卻時間縮短{1}分鐘。" },
	["reduces the cooldown of your shifting power spell by # sec"] = { ko = "변신의 힘의 재사용 대기시간이 {1}초만큼 단축됩니다." },
	["reduces the cooldown of your shock spells by # sec"] = { ko = "충격 계열 주문의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的震击法术的冷却时间减少{1}秒。", zhTW = "使你的震擊法術的冷卻時間縮短{1}秒。" },
	["reduces the cooldown of your soul fire spell by #%"] = { ko = "영혼의 불꽃의 재사용 대기시간이 {1}%만큼 감소합니다.", zhCN = "使你的灵魂之火冷却时间缩短{1}%。", zhTW = "你靈魂之火法術的冷卻時間縮短{1}%。" },
	["reduces the cooldown of your soul fire spell by #%. when you cast shadow bolt or searing pain on an enemy below #% health, they deal #% increased damage, and for the next # sec your soul fire spell has its cast time reduced by #% and costs no soul shards"] = { ko = "영혼의 불꽃의 재사용 대기시간이 {1}%만큼 감소합니다. 생명력이 {2}% 미만인 적에게 어둠의 화살 또는 불타는 고통을 시전하면 {3}%의 추가 피해를 입히며, 다음 {4}초 동안 영혼의 불꽃의 시전 시간이 {5}%만큼 감소하고 영혼의 조각을 소모하지 않습니다.", zhCN = "使你的灵魂之火冷却时间缩短{1}%。当你对生命值低于{2}%的敌人施放暗影箭或灼热之痛时，这些法术造成的伤害提高{3}%，并且在接下来的{4}秒内，你的灵魂之火施法时间缩短{5}%，且不消耗灵魂碎片。", zhTW = "你靈魂之火法術的冷卻時間縮短{1}%。當你對生命力低於{2}%的敵人施放暗影箭或灼熱之痛時，其造成的傷害提高{3}%，同時在接下來的{4}秒內，你靈魂之火法術的施法時間縮短{5}%，且不消耗靈魂裂片。" },
	["reduces the cooldown of your sprint and evasion abilities by #%"] = { ko = "전력 질주와 회피의 재사용 대기시간이 {1}%만큼 단축됩니다.", zhCN = "使你的疾跑和闪避技能冷却时间缩短{1}%。", zhTW = "使你的疾跑和閃避技能的冷卻時間縮短{1}%。" },
	["reduces the cooldown of your swiftmend spell by -# sec"] = { ko = "신속한 치유의 재사용 대기시간이 -{1}초만큼 감소합니다.", zhCN = "使你的迅捷治愈法术的冷却时间缩短-{1}秒。", zhTW = "使你的迅癒法術的冷卻時間縮短-{1}秒。" },
	["reduces the cooldown of your trap and deterrence abilities by #%"] = { ko = "덫과 공격 저지 기술의 재사용 대기시간이 {1}%만큼 단축됩니다.", zhCN = "使你的陷阱和威慑技能的冷却时间缩短{1}%。", zhTW = "使你的陷阱和威懾技能的冷卻時間縮短{1}%。" },
	["reduces the cooldown of your vanish and blind abilities by # sec"] = { ko = "소멸과 실명의 재사용 대기시간이 {1}초만큼 단축됩니다.", zhCN = "使你的消失和致盲技能的冷却时间缩短{1}秒。", zhTW = "使你的閃避和致盲技能的冷卻時間縮短{1}秒。" },
	["reduces the cooldown on your power word: shield spell by # sec and reduces its mana cost by #%"] = { ko = "신의 권능: 보호막의 재사용 대기시간이 {1}초만큼, 마나 소모량이 {2}%만큼 감소합니다.", zhCN = "使你的真言术：盾冷却时间缩短{1}秒，法力消耗降低{2}%。", zhTW = "使你真言術：盾的冷卻時間縮短{1}秒，法力消耗降低{2}%。" },
	["reduces the cooldown on your rapid fire ability by # min"] = { ko = "속사의 재사용 대기시간이 {1}분만큼 감소합니다.", zhCN = "使你的急速射击冷却时间缩短{1}分钟。", zhTW = "你急速射擊的冷卻時間縮短{1}分鐘。" },
	["reduces the cooldown on your rapid fire ability by # min. in addition, when you kill a non-trivial enemy or it dies while afflicted by your serpent sting, you gain rapid killing, increasing the damage of your next shot ability within # sec by #%"] = { ko = "속사의 재사용 대기시간이 {1}분만큼 감소합니다. 또한 사소하지 않은 적을 처치하거나 해당 적이 자신의 독사 쐐기에 걸린 상태로 사망하면 신속한 사냥이 부여되어 {2}초 안에 사용하는 다음 사격 능력의 공격력이 {3}%만큼 증가합니다.", zhCN = "使你的急速射击冷却时间缩短{1}分钟。此外，当你消灭一个能为你提供经验值或荣誉值的敌人，或其在受到你的毒蛇钉刺影响时死亡，你获得疾速杀戮，使你在{2}秒内的下一个射击技能造成的伤害提高{3}%。", zhTW = "你急速射擊的冷卻時間縮短{1}分鐘。此外，如果你擊殺有實力的敵人，或該敵人在受你毒蛇釘刺影響時死亡，你會獲得急速殺戮，使你在{2}秒內施放的下一個射擊技能的傷害提高{3}%。" },
	["reduces the cost of your heroic strike ability by # rage"] = { ko = "영웅의 일격에 소모되는 분노가 {1}만큼 감소합니다.", zhCN = "使你的英勇打击消耗的怒气减少{1}点。", zhTW = "使你的英勇打擊技能所消耗的怒氣降低{1}點。" },
	["reduces the cost of your maul, primal bite, swipe, claw, and rake abilities by # rage or energy"] = { ko = "후려치기, 원시의 이빨, 휘둘러치기, 할퀴기, 갈퀴 발톱 기술에 소모되는 기력 또는 분노가 {1}만큼 감소합니다." },
	["reduces the crafting time of smelt copper, smelt tin, smelt bronze, and smelt silver by #%"] = { ko = "구리 제련, 주석 제련, 청동 제련, 은 제련의 제작 시간이 {1}%만큼 감소합니다.", zhCN = "使熔炼铜锭、熔炼锡锭、熔炼青铜和熔炼银锭的制造时间缩短{1}%。", zhTW = "使熔煉銅錠、熔煉錫錠、熔煉青銅錠和熔煉銀錠的製作時間縮短{1}%。" },
	["reduces the damage taken from all attacks by #% for # sec"] = { ko = "{2}초 동안 모든 공격으로 받는 피해가 {1}%만큼 감소합니다.", zhCN = "使你受到的所有攻击伤害降低{1}%，持续{2}秒。", zhTW = "在遭到所有攻擊時受到的傷害降低{1}%，持續{2}秒。" },
	["reduces the duration of all movement impairing effects on you by #%"] = { ko = "자신에게 걸리는 모든 이동 방해 효과의 지속시간이 {1}%만큼 감소합니다.", zhCN = "使你受到的所有移动限制效果的持续时间缩短{1}%。", zhTW = "使你身上所有移動限制效果的持續時間縮短{1}%。" },
	["reduces the duration of fear and disorient effects on you by #%"] = { ko = "자신에게 걸린 공포와 방향 감각 상실 효과의 지속시간이 {1}%만큼 감소합니다.", zhCN = "使你受到的恐惧和迷惑效果的持续时间缩短{1}%。", zhTW = "使你受到的恐懼和迷惑效果的持續時間縮短{1}%。" },
	["reduces the duration of stun and fear effects inflicted on you by #%"] = { ko = "자신에게 걸리는 기절과 공포 효과의 지속시간이 {1}%만큼 감소합니다.", zhCN = "使你受到的昏迷和恐惧效果的持续时间缩短{1}%。", zhTW = "使你身上的昏迷和恐懼效果的持續時間縮短{1}%。" },
	["reduces the energy cost of your cheap shot and garrote abilities by #, and your garrote ability no longer requires you to be behind your target"] = { ko = "비열한 습격과 목조르기에 소비되는 기력이 {1}만큼 감소합니다. 추가로 대상의 배후에 있지 않아도 목조르기를 사용할 수 있도록 합니다.", zhCN = "使你的偷袭和绞喉消耗的能量值降低{1}点，且绞喉不再要求你位于目标身后。", zhTW = "使你的偷襲和絞喉技能的能量消耗降低{1}點，且絞喉不再需要從目標背後發動。" },
	["reduces the energy cost of your eviscerate ability by #"] = { ko = "절개에 소비되는 기력이 {1}만큼 감소합니다.", zhCN = "使你的刺骨消耗的能量值降低{1}点。", zhTW = "使你剔骨技能的能量消耗降低{1}點。" },
	["reduces the energy cost of your expose armor ability by #, and refunds # combo point when cast with # combo points"] = { ko = "약점 노출에 소비되는 기력이 {1}만큼 감소합니다. 또한 연계 점수 {3}점을 소모해 시전하면 연계 점수 {2}점을 되돌려받습니다.", zhCN = "使你的破甲消耗的能量值降低{1}点，并在以{3}个连击点数施放时返还{2}个连击点。", zhTW = "使你破甲技能的能量消耗降低{1}點，並且以{3}個連擊點數施放時，會返還{2}個連擊點數。" },
	["reduces the energy cost of your expose armor ability by #, and refunds # combo points when cast with # combo points"] = { ko = "약점 노출에 소비되는 기력이 {1}만큼 감소합니다. 또한 연계 점수 {3}점을 소모해 시전하면 연계 점수 {2}점을 되돌려받습니다.", zhCN = "使你的破甲消耗的能量值降低{1}点，并在以{3}个连击点数施放时返还{2}个连击点。", zhTW = "使你破甲技能的能量消耗降低{1}點，並且以{3}個連擊點數施放時，會返還{2}個連擊點數。" },
	["reduces the energy cost of your sap and blind abilities by #%"] = { ko = "혼절시키기와 실명에 소비되는 기력이 {1}%만큼 감소합니다.", zhCN = "使你的闷棍和致盲技能消耗的能量值减少{1}%。", zhTW = "使你悶棍和致盲的能量消耗降低{1}%。" },
	["reduces the energy cost of your shred ability by # and reduces the rage cost of your lacerate ability by #"] = { ko = "칼날 발톱에 소비되는 기력이 {1}만큼, 가르기에 소비되는 분노가 {2}만큼 감소합니다.", zhCN = "使你的撕碎消耗的能量值降低{1}点，割伤消耗的怒气降低{2}点。", zhTW = "使你的撕碎技能的能量消耗降低{1}點，並使割裂技能的怒氣消耗降低{2}點。" },
	["reduces the energy cost of your sinister strike ability by #"] = { ko = "사악한 일격에 소모되는 기력이 {1}만큼 감소합니다.", zhCN = "使你的邪恶攻击技能所消耗的能量值减少{1}点。", zhTW = "使你的邪惡攻擊技能所消耗的能量減少{1}點。" },
	["reduces the global cooldown and cast time of your slam ability by # sec"] = { ko = "격돌의 전역 재사용 대기시간과 시전 시간이 {1}초만큼 감소합니다.", zhCN = "使你的猛击技能的公共冷却时间和施法时间缩短{1}秒。", zhTW = "使你猛擊技能的共用冷卻時間和施法時間縮短{1}秒。" },
	["reduces the global cooldown and cast time of your slam ability by # sec. in addition, slam no longer interrupts or delays your melee swing and slam's cooldown is reduced by # sec"] = { ko = "격돌의 전역 재사용 대기시간과 시전 시간이 {1}초만큼 감소합니다. 또한 격돌을 사용해도 근접 공격이 방해받거나 지연되지 않으며, 격돌의 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的猛击技能的公共冷却时间和施法时间缩短{1}秒。此外，猛击不再打断或延迟你的近战挥击计时，且猛击的冷却时间缩短{2}秒。", zhTW = "使你猛擊技能的共用冷卻時間和施法時間縮短{1}秒。此外，猛擊不再中斷或延遲你的近戰揮擊，且猛擊的冷卻時間縮短{2}秒。" },
	["reduces the global cooldown by # sec on your rejuvenation, swiftmend, and wild growth spells"] = { ko = "회복, 신속한 치유, 급속 성장의 전역 재사용 대기시간이 {1}초만큼 감소합니다.", zhCN = "使你的回春术、迅捷治愈和野性成长的公共冷却时间缩短{1}秒。", zhTW = "使你的回春術、迅癒和野性痊癒法術的共用冷卻時間縮短{1}秒。" },
	["reduces the hit chance of disorient effects against you by #%"] = { ko = "자신에게 걸리는 방향 감각 상실 효과의 적중률이 {1}%만큼 감소합니다.", zhCN = "使你被迷惑效果击中的几率降低{1}%。", zhTW = "困惑效果對你的命中機率降低{1}%。" },
	["reduces the hit chance of fear effects against you by #%"] = { ko = "자신에게 걸리는 공포 효과의 적중률이 {1}%만큼 감소합니다.", zhCN = "使你被恐惧效果击中的几率降低{1}%。", zhTW = "恐懼效果命中你的機率降低{1}%。" },
	["reduces the hit chance of silence effects against you by #%"] = { ko = "자신에게 걸리는 침묵 효과의 적중률이 {1}%만큼 감소합니다.", zhCN = "使你被沉默效果命中的几率降低{1}%。", zhTW = "沉默效果對你的命中機率降低{1}%。" },
	["reduces the hit chance of sleep effects against you by #%"] = { ko = "자신에게 걸리는 수면 효과의 적중률이 {1}%만큼 감소합니다.", zhCN = "使你被催眠效果击中的几率降低{1}%。", zhTW = "沉睡效果對你的命中機率降低{1}%。" },
	["reduces the mana cost of all instant cast spells and abilities by #%"] = { ko = "모든 즉시 시전 주문 및 능력에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你所有瞬发法术和技能所消耗的法力值降低{1}%。", zhTW = "使你所有瞬發法術和技能的法力消耗降低{1}%。" },
	["reduces the mana cost of all shapeshifting by #%"] = { ko = "모든 변신에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你的所有变形法术所消耗的法力值降低{1}%。", zhTW = "使你的所有變形法術所消耗的法力降低{1}%。" },
	["reduces the mana cost of your cleanse and purify spells by #% and reduces the cooldown of your exorcism and holy wrath spells by #%"] = { ko = "정화와 순화의 마나 소모량이 {1}%만큼, 퇴마술과 신의 격노의 재사용 대기시간이 {2}%만큼 감소합니다.", zhCN = "使你的清洁术和纯净术法力消耗降低{1}%，并使驱邪术和神圣愤怒的冷却时间缩短{2}%。", zhTW = "使你淨化術和純淨術的法力消耗降低{1}%，驅邪術和神聖憤怒的冷卻時間縮短{2}%。" },
	["reduces the mana cost of your consecration, holy wrath, exorcism, and hammer of wrath spells by #%"] = { ko = "신성화와 신의 격노, 퇴마술, 천벌의 망치의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "使你的奉献、神圣愤怒、驱邪术和愤怒之锤法力消耗降低{1}%。", zhTW = "使你的奉獻、神聖憤怒、驅邪術和憤怒之錘的法力消耗降低{1}%。" },
	["reduces the mana cost of your damaging spells by #%"] = { ko = "공격 주문에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "你的伤害性法术的法力消耗降低{1}%。", zhTW = "你的傷害法術消耗的法力降低{1}%。" },
	["reduces the mana cost of your destruction spells by #%"] = { ko = "파괴 계열 주문의 마나 소비량이 {1}%만큼 감소합니다.", zhCN = "使你的毁灭系法术所消耗的法力值减少{1}%。", zhTW = "使你的毀滅系法術所消耗的法力減少{1}%。" },
	["reduces the mana cost of your devouring plague by #%"] = { ko = "파멸의 역병에 소비되는 마나가 {1}%만큼 감소합니다." },
	["reduces the mana cost of your frost spells by #% and reduces the threat caused by your frost spells by #%"] = { ko = "냉기 마법을 시전하는 데 필요한 마나가 {1}%만큼 감소하고 냉기 주문으로 발생되는 위협 수준이 {2}%만큼 감소합니다.", zhCN = "使你的所有冰霜法术所消耗的法力值减少{1}%，冰霜系法术所造成的威胁值降低{2}%。", zhTW = "使你的所有冰霜法術所消耗的法力減少{1}%和使你的冰霜法術所產生的威脅值降低{2}%。" },
	["reduces the mana cost of your healing spells by #% and improves your chance to hit by #%"] = { ko = "치유 주문의 마나 소모량이 {1}%만큼 감소하고 적중률은 {2}%만큼 증가합니다.", zhCN = "使你的治疗法术法力消耗降低{1}%，并使你的命中几率提高{2}%。", zhTW = "使你治療法術的法力消耗降低{1}%，並使你的命中機率提高{2}%。" },
	["reduces the mana cost of your healing touch and tranquility spells by #%"] = { ko = "치유의 손길과 평온 주문에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你的治疗之触和宁静所消耗的法力值减少{1}%。", zhTW = "使你的治療之觸和寧靜所消耗的法力減少{1}%。" },
	["reduces the mana cost of your lesser heal, heal, greater heal, penance, and prayer of mending spells by #%"] = { ko = "하급 치유, 치유, 상급 치유, 회개, 회복의 기원의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "使你的次级治疗术、治疗术、强效治疗术、苦修和愈合祷言的法力消耗降低{1}%。", zhTW = "使你的次級治療術、治療術、強效治療術、懺悟和癒合禱言的法力消耗降低{1}%。" },
	["reduces the mana cost of your seal spells by #%"] = { ko = "문장 주문의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "使你的圣印法术所消耗的法力值降低{1}%。", zhTW = "使聖印法術的法力消耗降低{1}%。" },
	["reduces the mana cost of your seal spells by #%, and when you replace your seal of command, seal of righteousness, seal of fury, or seal of justice with a different seal, you gain an echo of that seal"] = { ko = "문장 주문에 소비되는 마나가 {1}%만큼 감소하며, 지휘의 문장, 정의의 문장, 격노의 문장, 심판의 문장을 다른 문장으로 교체하면 그 문장의 메아리를 얻습니다." },
	["reduces the mana cost of your seal spells by #%, and when you replace your seal of command, seal of righteousness, seal of fury, or seal of justice with a different seal, you gain an echo of that seal. your next melee attack applies the replaced seal's effects, consuming the echo"] = { ko = "문장 주문에 소비되는 마나가 {1}%만큼 감소하며, 지휘의 문장, 정의의 문장, 격노의 문장, 심판의 문장을 다른 문장으로 교체하면 그 문장의 메아리를 얻습니다. 다음 근접 공격 시 메아리를 소모하여 교체된 문장의 효과를 적용합니다." },
	["reduces the mana cost of your shock and lightning shield spells by #%"] = { ko = "충격 계열 주문과 번개 보호막에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你的震击和闪电之盾消耗的法力值降低{1}%。", zhTW = "使你震擊法術和閃電之盾的法力消耗降低{1}%。" },
	["reduces the mana cost of your shock, lightning bolt, lava burst, and chain lightning spells by #%"] = { ko = "번개 화살, 용암 폭발, 연쇄 번개, 충격 계열 주문에 소모되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你的震击、闪电箭、熔岩爆裂和闪电链的法力消耗降低{1}%。", zhTW = "使你的震擊法術、閃電箭、熔岩爆發和閃電鏈的法力消耗降低{1}%。" },
	["reduces the mana cost of your shots, stings, and melee abilities by #%"] = { ko = "사격, 쐐기, 근접 능력의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "使你的射击、钉刺和近战技能所消耗的法力值降低{1}%。", zhTW = "使你施放射擊、釘刺和近戰技能的法力消耗降低{1}%。" },
	["reduces the mana cost of your smite, holy fire, and instant cast spells by #%"] = { ko = "성스러운 일격, 신성한 불꽃, 즉시 시전 주문에 소비되는 마나가 {1}%만큼 감소합니다.", zhCN = "使你的惩击、神圣之火和瞬发法术消耗的法力值降低{1}%。", zhTW = "使你懲擊、神聖之火和瞬發法術的法力消耗降低{1}%。" },
	["reduces the mana cost of your totems and any spells that summon or move them by #%"] = { ko = "토템과 모든 토템 소환 또는 토템 이동 주문의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "使你的图腾以及任何召唤或移动图腾的法术所消耗的法力值降低{1}%。", zhTW = "使你施放圖騰和任何召喚或移動圖騰的法術的法力消耗降低{1}%。" },
	["reduces the mana cost of your trap abilities and melee abilities by #%"] = { ko = "덫 기술과 근접 기술에 소비되는 마나가 {1}%만큼 감소합니다." },
	["reduces the mana cost of your trap abilities and melee abilities by #%. in addition, your critical strikes have a #% chance to allow #% of your mana regeneration to continue while casting for # sec"] = { ko = "덫 기술과 근접 기술에 소비되는 마나가 {1}%만큼 감소합니다. 또한 치명타 발생 시 {2}%의 확률로 {4}초 동안 시전 중에도 평소의 {3}%에 달하는 속도로 마나가 회복됩니다." },
	["reduces the melee attack power of all enemies within # yards by # for # sec"] = { ko = "{3}초 동안 {1}미터 내의 모든 적의 근접 전투력을 {2}만큼 감소시킵니다.", zhCN = "使半径{1}码范围内的敌人的近战攻击强度降低{2}点，持续{3}秒。", zhTW = "使半徑{1}碼範圍內的敵人的近戰攻擊強度降低{2}，持續{3}秒。" },
	["reduces the pushback suffered from damaging attacks while casting lightning bolt, chain lightning, and lava burst by #%"] = { ko = "번개 화살, 연쇄 번개, 용암 폭발 시전 시 피해로 인한 시전 밀림 효과가 {1}%만큼 감소합니다.", zhCN = "使你在施放闪电箭、闪电链和熔岩爆裂时因受到伤害而遭受的施法推延降低{1}%。", zhTW = "使你施放閃電箭、閃電鏈和熔岩爆發時，因受到傷害性攻擊而損失的施法時間縮短{1}%。" },
	["reduces the rage cost of your cleave and whirlwind abilities by #"] = { ko = "회전베기와 소용돌이에 소비되는 분노가 {1}만큼 감소합니다." },
	["reduces the rage cost of your execute ability by #"] = { ko = "마무리 일격에 소비되는 분노가 {1}만큼 감소합니다.", zhCN = "使你的斩杀技能的怒气值消耗减少{1}点。", zhTW = "使你的斬殺技能的怒氣消耗減少{1}點。" },
	["reduces the rage cost of your offensive abilities by #"] = { ko = "공격 능력에 소비되는 분노가 {1}만큼 감소합니다.", zhCN = "使你的进攻技能消耗的怒气降低{1}点。", zhTW = "使你攻擊技能的怒氣消耗降低{1}點。" },
	["reduces the rage cost of your sunder armor ability by #"] = { ko = "방어구 가르기에 소모되는 분노가 {1}만큼 감소합니다.", zhCN = "使你的破甲攻击消耗的怒气减少{1}点。", zhTW = "使你的破甲攻擊技能所消耗的怒氣降低{1}點。" },
	["reduces the rage cost of your thunder clap ability by #"] = { ko = "천둥벼락에 소모되는 분노가 {1}만큼 감소합니다.", zhCN = "使你的雷霆一击技能消耗的怒气减少{1}点。", zhTW = "使你的雷霆一擊技能所消耗的怒氣降低{1}點。" },
	["reduces the target's movement speed by #% for # sec"] = { ko = "{2}초 동안 대상의 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "使目标的速度降低{1}%，持续{2}秒。", zhTW = "使目標的速度降低{1}%，持續{2}秒。" },
	["reduces the target's movement speed by #% for # sec. only one curse per warlock can be active on any one target"] = { ko = "{2}초 동안 대상의 이동 속도를 {1}%만큼 감소시킵니다. 흑마법사마다 한 대상에 하나의 저주만 걸 수 있습니다.", zhCN = "使目标的速度降低{1}%，持续{2}秒。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", zhTW = "使目標的速度降低{1}%，持續{2}秒。每個術士只能對一個目標施加一種詛咒，且同類詛咒不能疊加。" },
	["reduces the threat generated by your holy spells by #% and reduces the duration of stun, fear, and silence effects inflicted on you by #%"] = { ko = "신성 주문으로 인해 생성되는 위협 수준이 {1}%만큼 감소합니다. 또한 자신에게 걸리는 기절과 공포, 침묵 효과의 지속시간이 {2}%만큼 감소합니다.", zhCN = "使你的神圣法术产生的威胁值降低{1}%，并使你受到的昏迷、恐惧和沉默效果的持续时间缩短{2}%。", zhTW = "使你的神聖系法術產生的威脅值降低{1}%，並使你身上的昏迷、恐懼和沉默效果的持續時間縮短{2}%。" },
	["reduces the threat generated by your nature and arcane spells by #%"] = { ko = "자연 및 비전 주문의 위협 수준 생성량이 {1}%만큼 감소합니다.", zhCN = "使你的自然和奥术法术产生的威胁降低{1}%。", zhTW = "使你的自然或秘法法術產生的威脅值降低{1}%。" },
	["reduces the threat generated by your shadow spells by #%"] = { ko = "암흑 주문의 위협 수준이 {1}%만큼 감소합니다.", zhCN = "使你的暗影法术造成的威胁值降低{1}%。", zhTW = "使你的暗影法術造成的威脅值降低{1}%。" },
	["reduces the threat generated by your spells by #%"] = { ko = "주문으로 인한 위협 수준이 {1}%만큼 감소합니다.", zhCN = "使你的法术造成的威胁值降低{1}%。", zhTW = "使你的法術造成的威脅值降低{1}%。" },
	["reduces threat caused by tranquility by #% and its cooldown by #%"] = { ko = "평온에 의한 위협 수준이 {1}%만큼, 재사용 대기시간이 {2}%만큼 감소합니다.", zhCN = "使你的宁静产生的威胁值降低{1}%，冷却时间缩短{2}%。", zhTW = "使你寧靜法術造成的威脅值降低{1}%，且其冷卻時間縮短{2}%。" },
	["reduces your fall speed for # sec"] = { ko = "{1}초 동안 낙하 속도를 감소시킵니다.", zhCN = "使你的坠落速度减缓{1}秒。", zhTW = "使你的墜落速度減緩{1}秒。" },
	["reduces your speed penalty from your stealth ability by #% and reduces its cooldown by # sec"] = { ko = "은신으로 인한 이동 속도 저하 효과가 {1}%만큼 감소하며, 은신의 재사용 대기시간이 {2}초만큼 단축됩니다.", zhCN = "使你潜行时的移动速度惩罚降低{1}%，并使潜行的冷却时间缩短{2}秒。", zhTW = "潛行技能附帶的移動速度懲罰降低{1}%，且其冷卻時間縮短{2}秒。" },
	["reduces your target's resistance to all your spells by # and reduces the threat caused by your arcane spells by #%"] = { ko = "자신의 모든 주문에 대한 대상의 마법 저항력이 {1}만큼 감소하고 비전 주문으로 발생되는 위협 수준이 {2}%만큼 감소합니다.", zhCN = "使你的目标对你的所有法术的抗性降低{1}点，并使你的奥术系法术所造成的威胁值降低{2}%。", zhTW = "使目標對你所有法術的抗性降低{1}點和你的秘法法術所產生的威脅值降低{2}%。" },
	["refer to individual seals for judgement effect"] = { ko = "효과는 문장에 따라 달라집니다.", zhCN = "有关审判效果，请参阅各个圣印的说明。", zhTW = "請參閱每種聖印的審判效果說明。" },
	["refreshing this effect carries over any remaining healing"] = { ko = "이 효과를 갱신하면 남은 치유량이 이월됩니다.", zhCN = "刷新该效果时会保留剩余治疗量。", zhTW = "重置此效果會繼承剩餘的所有治療效果。" },
	["regenerates #% of your total health over # sec after being the victim of a critical strike or suffering more than #% of your maximum health from a single attack"] = { ko = "치명타 및 극대화 공격을 받거나, 한 번의 공격으로 최대 생명력의 {3}%를 넘는 피해를 받으면 {2}초에 걸쳐 전체 생명력의 {1}%를 회복합니다." },
	["regenerates all nearby party members within # yards for # every # sec for # sec"] = { ko = "{4}초 동안 {3}초마다 {1}미터 내 주위 모든 파티원의 생명력을 {2}만큼 회복시킵니다.", zhCN = "使{1}码内附近的所有队伍成员每{3}秒恢复{2}点生命值，持续{4}秒。", zhTW = "使{1}碼內的所有隊伍成員每{3}秒恢復{2}點生命力，持續{4}秒。" },
	["regenerates all nearby party members within # yards for # every # sec for # sec. druid must channel to maintain the spell"] = { ko = "{4}초 동안 {3}초마다 {1}미터 내 주위 모든 파티원의 생명력을 {2}만큼 회복시킵니다. 주문을 유지하려면 계속 정신을 집중해야 합니다.", zhCN = "使{1}码内附近的所有队伍成员每{3}秒恢复{2}点生命值，持续{4}秒。德鲁伊必须持续引导才能维持该法术。", zhTW = "使{1}碼內的所有隊伍成員每{3}秒恢復{2}點生命力，持續{4}秒。德魯伊必須引導以維持法術效果。" },
	["relocates your active totems to the specified location"] = { ko = "활성화된 토템을 지정된 위치로 재배치합니다.", zhCN = "将你激活的图腾转移到指定位置。", zhTW = "將你當前啟用的圖騰改變到特定位置。" },
	["removes # curse or bane from a friendly target"] = { ko = "아군 대상으로부터 {1}개의 저주 또는 파멸 주문을 해제합니다.", zhCN = "从一个友方目标身上移除{1}个诅咒或灾祸。", zhTW = "從一個友方目標身上解除{1}個詛咒或災禍。" },
	["removes # disease from the friendly target"] = { ko = "대상으로부터 {1}개의 질병을 제거합니다.", zhCN = "从友方目标身上移除{1}个疾病效果。", zhTW = "移除友方目標身上的{1}個疾病效果。" },
	["requires a campfire nearby"] = { ko = "주위에 모닥불이 있어야 합니다.", zhCN = "需要附近有营火。", zhTW = "需要附近有營火。" },
	["requires a campfire nearby. all camping features share a cooldown of # hr"] = { ko = "주위에 모닥불이 있어야 합니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "需要附近有营火。所有露营功能共享{1}小时冷却时间。", zhTW = "需要附近有營火。所有紮營功能共享{1}小時冷卻時間。" },
	["requires a cooking fire nearby"] = { ko = "주위에 요리용 모닥불이 있어야 합니다.", zhCN = "需要附近有烹饪用火。", zhTW = "需要附近有烹飪用火。" },
	["requires a suitable library"] = { ko = "알맞은 도서관이 있어야 합니다.", zhCN = "需要在合适的图书馆中进行。", zhTW = "需要在合適的圖書館中進行。" },
	["requires bear form, dire bear form"] = { ko = "곰 변신, 광포한 곰 변신 상태에서만 가능합니다.", zhCN = "需要熊形态或巨熊形态", zhTW = "需要熊形態、巨熊形態" },
	["requires cat form, bear form, dire bear form"] = { ko = "표범 변신, 곰 변신, 광포한 곰 변신 상태에서만 가능합니다." },
	["requires the caster and # additional party members to complete the ritual"] = { ko = "의식을 수행하려면 흑마법사를 제외하고 파티원 {1}명이 필요합니다.", zhCN = "需要施法者和{1}名队友共同完成召唤仪式。", zhTW = "需要施法者和{1}名隊友共同完成召喚儀式。" },
	["restore # charges to a manual crowd pummeler device in your possession"] = { ko = "보유 중인 수동 고철 압축기 장치의 사용 횟수를 {1}회 충전합니다.", zhCN = "为你拥有的手动惩戒器恢复{1}次使用次数。", zhTW = "使你持有的手動懲戒錘裝置恢復{1}次使用次數。" },
	["restores # charges to a saf-t or ez-thro brand device in your possession that does not involve explosions"] = { ko = "소지 중인 안전-제일 또는 초보자용 상표 장치 중, 폭발물을 제외한 장치의 사용 횟수를 {1}회 충전합니다.", zhCN = "为你拥有的一个不涉及爆炸的安全型号或简易投掷品牌装置恢复{1}次使用次数。", zhTW = "使你持有且與爆炸無關的SAF-T或簡易投擲系列裝置恢復{1}次使用次數。" },
	["restores # charges to a saf-t or ez-thro brand device in your possession that does not involve explosions. it would be completely unsafe with explosives"] = { ko = "소지 중인 안전-제일 또는 초보자용 상표 장치 중, 폭발물을 제외한 장치의 사용 횟수를 {1}회 충전합니다. 폭발물에 사용했다간 극도로 위험할 테니 말이죠.", zhCN = "为你拥有的一个不涉及爆炸的安全型号或简易投掷品牌装置恢复{1}次使用次数。将其用于爆炸物绝对是不安全的。", zhTW = "使你持有且與爆炸無關的SAF-T或簡易投擲系列裝置恢復{1}次使用次數。搭配炸藥將會徹底變得不安全。" },
	["restores # health"] = { ko = "생명력이 {1}만큼 회복됩니다.", zhCN = "恢复{1}点生命值。", zhTW = "恢復{1}點生命力。" },
	["restores # health every # sec for # sec"] = { ko = "{3}초에 걸쳐 매 {2}초마다 {1}의 생명력을 회복합니다.", zhCN = "每{2}秒恢复{1}点生命值，持续{3}秒。", zhTW = "每{2}秒恢復{1}點生命力，持續{3}秒。" },
	["restores # health instantly, however you also suffer #% of that amount over time"] = { ko = "즉시 {1}의 생명력을 회복하지만 지속적으로 치유량의 {2}%에 해당하는 피해를 받습니다.", zhCN = "立即恢复{1}点生命值，但你会逐渐失去治疗量的{2}%。", zhTW = "立即恢復{1}點生命力，但你會逐漸失去治療量的{2}%。" },
	["restores # health instantly; however you also suffer #% of that amount over time"] = { ko = "즉시 {1}의 생명력을 회복하지만 지속적으로 치유량의 {2}%에 해당하는 피해를 받습니다.", zhCN = "立即恢复{1}点生命值，但你会逐渐失去治疗量的{2}%。", zhTW = "立即恢復{1}點生命力，但你會逐漸失去治療量的{2}%。" },
	["restores # mana"] = { ko = "마나가 {1}만큼 회복됩니다.", zhCN = "恢复{1}点法力值。", zhTW = "回復{1}點法力。" },
	["restores # mana over # sec"] = { ko = "{2}초에 걸쳐 {1}의 마나를 회복합니다." },
	["restores # mana over # sec. must remain seated while drinking"] = { ko = "{2}초에 걸쳐 {1}의 마나를 회복합니다. 음료를 마시려면 앉아 있어야 합니다." },
	["restores +# mana per # sec"] = { ko = "{2}초 당 +{1} 마나 회복", zhCN = "每{2}秒回复 +{1} 法力值", zhTW = "每{2}秒回覆 +{1} 法力" },
	["restores some health over # sec"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다." },
	["restores some health over # sec. must remain seated while eating"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating you will become well fed and gain # armor for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다.음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 방어도가 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating you will become well fed and gain {3} Armor for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating you will become well fed and gain {3} Armor for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain # agility for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 민첩성이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Agility for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Agility for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain # intellect for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 지능이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Intellect for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Intellect for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain # spell damage for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 주문 공격력이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Spell Damage for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Spell Damage for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain # stamina for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 체력이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Stamina for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Stamina for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain # strength for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 힘이 {4}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Strength for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Strength for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some health over # sec. must remain seated while eating. if you spend at least # sec eating, you will become well fed and gain #% movement speed while in hyjal for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {3}분 동안 하이잘에서 이동 속도가 {4}%만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点生命值，进食时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3}% movement speed while in Hyjal for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點生命力，進食時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3}% movement speed while in Hyjal for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some mana over # sec"] = { ko = "{1}초에 걸쳐 총 일정량의 마나가 회복됩니다." },
	["restores some mana over # sec. must remain seated while drinking. if you spend at least # sec eating, you will become well fed and gain # healing power for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 마나가 회복됩니다. 음료를 마시려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 치유력이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点法力值，喝水时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Healing Power for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點法力，喝水時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Healing Power for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["restores some mana over # sec. must remain seated while drinking. if you spend at least # sec eating, you will become well fed and gain # spirit for # min. additionally, experience gained from kills is increased by #%"] = { ko = "{1}초에 걸쳐 총 일정량의 마나가 회복됩니다. 음료를 마시려면 앉아 있어야 합니다. 음식을 꾸준히 {2}초 이상 먹으면 포만감을 느끼게 되고 {4}분 동안 정신력이 {3}만큼 증가합니다. 추가로, 적 처치 시 획득하는 경험치가 {5}%만큼 증가합니다.", zhCN = "在{1}秒内恢复总计一定量点法力值，喝水时必须保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Spirit for {4} min. 此外，击杀获得的经验值提高{5}%。", zhTW = "在{1}秒內恢復總計一定量點法力，喝水時必須保持坐姿。 If you spend at least {2} sec eating, you will become well fed and gain {3} Spirit for {4} min. 此外，擊殺獲得的經驗值提高{5}%。" },
	["resummoning the sacrificed pet will still cancel the effect"] = { ko = "단, 제물로 바친 소환수를 재소환하는 경우에는 효과가 취소됩니다.", zhCN = "重新召唤已被牺牲的宠物仍会取消该效果。", zhTW = "重新召喚已被犧牲的寵物仍會取消效果。" },
	["retrieves the loot from a nearby corpse"] = { ko = "주위의 시체에서 전리품을 획득합니다.", zhCN = "从附近的尸体身上拾取物品。", zhTW = "從附近的屍體身上撿拾物品。" },
	["returns the spirit to the body, restoring a dead target to life with # health and # mana"] = { ko = "죽은자의 영혼을 육체로 불러들여 {1}의 생명력과 {2}의 마나를 지닌채 살아나게 합니다.", zhCN = "让已死的目标复活，并恢复{1}点生命值和{2}点法力值。", zhTW = "讓已死的目標復活，並恢復{1}點生命力和{2}點法力。" },
	["returns the spirit to the body, restoring a dead target to life with # health and # mana. cannot be cast when in combat"] = { ko = "죽은자의 영혼을 육체로 불러들여 {1}의 생명력과 {2}의 마나를 지닌채 살아나게 합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "让已死的目标复活，并恢复{1}点生命值和{2}点法力值。无法在战斗中施放。", zhTW = "讓已死的目標復活，並恢復{1}點生命力和{2}點法力。無法在戰鬥中施放。" },
	["returns the spirit to the body, restoring a dead target to life with #,# health and # mana"] = { ko = "죽은자의 영혼을 육체로 불러들여 {1},{2}의 생명력과 {3}의 마나를 지닌채 살아나게 합니다.", zhCN = "让已死的目标复活，并恢复{1},{2}点生命值和{3}点法力值。", zhTW = "讓已死的目標復活，並恢復{1},{2}點生命力和{3}點法力。" },
	["returns your totems to the earth, giving you #% of the mana required to cast each totem destroyed by totemic recall"] = { ko = "자신의 토템을 땅으로 돌려 보내고 토템의 귀환으로 파괴된 모든 토템 소환에 소비된 마나의 {1}%만큼을 되돌려 받습니다.", zhCN = "将你的图腾送回大地中，每个因收回而被摧毁的图腾都可以为你返还召唤该图腾所需法力值的{1}%。", zhTW = "將你的圖騰歸還大地，並使你獲得被召回圖騰所摧毀的每一根圖騰召喚時所需的{1}%法力。" },
	["revenge must follow a block, dodge or parry"] = { zhCN = "复仇只有在成功格挡、躲闪或招架之后才能使用。", zhTW = "復仇只有在成功格擋、躲閃或招架之後才能使用。" },
	["revive pet's casting time is reduced by # sec, mana cost is reduced by #%, and increases the health your pet returns with by an additional #%"] = { ko = "야수 되살리기의 시전 시간이 {1}초만큼 단축되며 소비되는 마나가 {2}%만큼 감소합니다. 또한 부활할 때 {3}%만큼 추가 생명력을 지닌 채로 부활합니다.", zhCN = "使你的复活宠物法术的施法时间减少{1}秒，法力值消耗降低{2}%，宠物复活后的生命值提高{3}%。", zhTW = "使你的復活寵物法術的施法時間減少{1}秒，法力消耗降低{2}%，寵物復活後的生命提高{3}%。" },
	["revive your pet, returning it to life with #% of its health"] = { ko = "야수를 {1}%의 생명력을 지닌 채로 되살아나게 합니다.", zhCN = "复活你的宠物，并为其回复{1}%的生命值。", zhTW = "復活你的寵物，並為其回復{1}%的生命力。" },
	["right click to summon and dismiss your robot"] = { ko = "애완용 로봇을 소환하거나 소환 해제합니다.", zhCN = "右键点击以召唤或解散你的机器人。", zhTW = "右鍵點擊以召喚或解散你的機器人。" },
	["rips the dimensional walls asunder and transports you to everlook in winterspring"] = { zhCN = "穿透空间限制，将你传送到冬泉谷的永望镇。", zhTW = "穿透空間限制，將你傳送到冬泉谷的永望鎮。" },
	["rips the dimensional walls asunder and transports you to everlook in winterspring. there are technical problems that sometimes occur, but that's what goblin engineering is all about"] = { ko = "차원의 경계를 분할하여 여명의 설원에 있는 눈망루 마을로 순간이동합니다. 가끔 기술적인 오동작이 발생하곤 하지만. 그게 바로 고블린 기계공학이니까요.", zhCN = "穿透空间限制，将你传送到冬泉谷的永望镇。虽然有些时候可能会发生技术故障，但这难道不是地精工程学的最大亮点吗？", zhTW = "穿透空間限制，將你傳送到冬泉谷的永望鎮。雖然有些時候可能會發生技術故障，但這難道不是哥布林工程學的最大特點嗎？" },
	["rips the dimensional walls asunder and transports you to kaylaena's workshop on mount hyjal"] = { ko = "차원의 벽을 찢고 하이잘 산에 있는 케이레나의 작업장으로 이동합니다.", zhCN = "撕裂空间位面，将你传送到海加尔山凯莱娜的工坊。", zhTW = "穿透空間限制，將你傳送到海加爾山的凱蕾娜的工作坊。" },
	["rips the dimensional walls asunder and transports you to kaylaena's workshop on mount hyjal. technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering"] = { ko = "차원의 벽을 찢고 하이잘 산에 있는 케이레나의 작업장으로 이동합니다. 고블린과 노움 기계공학이 광기 어린 방식으로 결합된 장치인 터라, 기술적인 문제가 발생할 확률이 높습니다.", zhCN = "撕裂空间位面，将你传送到海加尔山凯莱娜的工坊。这种地精与侏儒工程学疯狂结合的产物有很高的几率发生技术故障。", zhTW = "穿透空間限制，將你傳送到海加爾山的凱蕾娜的工作坊。但作為哥布林和地精工程學的共同結晶，發生技術故障的機率極高。" },
	["roots the target in place and causes # nature damage over # sec"] = { ko = "대상을 제자리에 묶어 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다.", zhCN = "将目标定身，并在{2}秒内对其造成总计{1}点自然伤害。", zhTW = "將目標固定在原地，並在{2}秒內對其造成總計{1}點自然傷害。" },
	["roots the target in place and causes # nature damage over # sec. damage caused may interrupt the effect. you may only have # target rooted at a time"] = { ko = "대상을 제자리에 묶어 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 동시에 한 명의 대상을 이동 불가 상태로 만들 수 있습니다.", zhCN = "将目标定身，并在{2}秒内对其造成总计{1}点自然伤害。受到伤害可能会打断该效果。同一时间内，你可以定身仅{3}个目标。", zhTW = "將目標固定在原地，並在{2}秒內對其造成總計{1}點自然傷害。任何傷害都有可能終止此效果。你同一時間只能將{3}個目標定身。" },
	["sacrifices the voidwalker, giving its owner a shield that will absorb # damage for # sec"] = { ko = "보이드워커를 희생하여 소환자를 {2}초 동안 {1}의 피해를 흡수하도록 만듭니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1}点伤害的防护盾，持续{2}秒。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1}點傷害的防護盾，持續{2}秒。" },
	["sacrifices the voidwalker, giving its owner a shield that will absorb # damage for # sec. while the shield holds, spellcasting will not be interrupted by damage"] = { ko = "보이드워커를 희생하여 소환자를 {2}초 동안 {1}의 피해를 흡수하도록 만듭니다. 이 동안은 피해에 의해 주문 시전이 방해받지 않습니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1}点伤害的防护盾，持续{2}秒。在防护盾未消失之前，术士的施法过程不会被打断。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1}點傷害的防護盾，持續{2}秒。在防護盾未消失之前，術士的施法過程不會被打斷。" },
	["sacrifices the voidwalker, giving its owner a shield that will absorb #,# damage for # sec"] = { ko = "보이드워커를 희생하여 소환자를 {3}초 동안 {1},{2}의 피해를 흡수하도록 만듭니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1},{2}点伤害的防护盾，持续{3}秒。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1},{2}點傷害的防護盾，持續{3}秒。" },
	["sacrifices the voidwalker, giving its owner a shield that will absorb #,# damage for # sec. while the shield holds, spellcasting will not be interrupted by damage"] = { ko = "보이드워커를 희생하여 소환자를 {3}초 동안 {1},{2}의 피해를 흡수하도록 만듭니다. 이 동안은 피해에 의해 주문 시전이 방해받지 않습니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1},{2}点伤害的防护盾，持续{3}秒。在防护盾未消失之前，术士的施法过程不会被打断。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1},{2}點傷害的防護盾，持續{3}秒。在防護盾未消失之前，術士的施法過程不會被打斷。" },
	["safely transport yourself to gadgetzan in tanaris"] = { ko = "타나리스 사막의 가젯잔으로 순간이동합니다.", zhCN = "将你安全地传送到塔纳利斯的加基森。", zhTW = "將你安全地傳送到塔納利斯的加基森。" },
	["safely transport yourself to gadgetzan in tanaris! emphasis on safe! yup, nothing bad could ever happen while using this device"] = { ko = "타나리스 사막의 가젯잔으로 순간이동합니다. 안전이 보장된 제품입니다. 절대로 문제가 일어나지 않으니 안심하고 사용하시기 바랍니다.", zhCN = "将你安全地传送到塔纳利斯的加基森。非常非常安全！没错，你完全不必有任何担心！", zhTW = "將你安全地傳送到塔納利斯的加基森。非常非常安全！沒錯，你完全不必有任何擔心！" },
	["salvage the wreckage of a shredder for spare parts"] = { ko = "벌목기 잔해에서 쓸 만한 부품을 수습합니다.", zhCN = "回收伐木机残骸，获取备用零件。", zhTW = "回收伐木機殘骸以取得備用零件。" },
	["scares a beast, causing it to run in fear for up to # sec"] = { ko = "야수를 겁줘서 최대 {1}초 동안 달아나도록 만듭니다.", zhCN = "恐吓一头野兽，使其因恐慌而逃跑，最多持续{1}秒。", zhTW = "恐嚇一頭野獸，使其因恐慌而逃跑，最多持續{1}秒。" },
	["scares a beast, causing it to run in fear for up to # sec. damage caused may interrupt the effect. only one beast can be feared at a time"] = { ko = "야수를 겁줘서 최대 {1}초 동안 달아나도록 만듭니다. 야수가 피해를 입으면 효과가 해제됩니다. 동시에 한 야수에게만 공포를 사용할 수 있습니다.", zhCN = "恐吓一头野兽，使其因恐慌而逃跑，最多持续{1}秒。任何伤害都有可能打断这个效果。每个猎人在同一时间内只能恐吓一头野兽。", zhTW = "恐嚇一頭野獸，使其因恐慌而逃跑，最多持續{1}秒。任何傷害都有可能打斷這個效果。每個獵人在同一時間內只能恐嚇一頭野獸。" },
	["scorch the enemy for # to # fire damage"] = { ko = "적을 불태워 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "灼烧敌人，对其造成{1}至{2}点火焰伤害。", zhTW = "灼燒敵人，對其造成{1}至{2}點火焰傷害。" },
	["seduces the target, preventing all actions for up to # sec"] = { ko = "대상을 현혹하여 최대 {1}초 동안 어떤 행동도 하지 못하도록 만듭니다.", zhCN = "诱惑目标，使其在最多{1}秒内无法行动。", zhTW = "誘惑目標，使其在最多{1}秒內無法行動。" },
	["seduces the target, preventing all actions for up to # sec. any damage caused will remove the effect. only works against humanoids"] = { ko = "대상을 현혹하여 최대 {1}초 동안 어떤 행동도 하지 못하도록 만듭니다. 대상이 피해를 입으면 효과가 사라집니다. 인간형 대상에게만 사용할 수 있습니다.", zhCN = "诱惑目标，使其在最多{1}秒内无法行动。任何伤害都会打断这个效果。只对人型生物有效。", zhTW = "誘惑目標，使其在最多{1}秒內無法行動。任何傷害都會打斷這個效果。只對人型生物有效。" },
	["send your pet into a rage causing #% additional damage for # sec"] = { ko = "야수를 광폭하게 만들어 {2}초 동안 공격력을 {1}%만큼 증가시킵니다.", zhCN = "使宠物进入疯狂状态，对目标造成的伤害提高{1}%，持续{2}秒。", zhTW = "使你的寵物進入憤怒狀態，對目標造成的傷害提高{1}%，持續{2}秒。" },
	["send your pet into a rage causing #% additional damage for # sec. while enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed"] = { ko = "야수를 광폭하게 만들어 {2}초 동안 공격력을 {1}%만큼 증가시킵니다. 광포한 동안엔 어떠한 방법으로도 공격을 저지할 수 없습니다.", zhCN = "使宠物进入疯狂状态，对目标造成的伤害提高{1}%，持续{2}秒。在这种状态下，宠物不会有任何恐惧或怜悯，也无法停止下来，除非被杀死。", zhTW = "使你的寵物進入憤怒狀態，對目標造成的傷害提高{1}%，持續{2}秒。在這種狀態下，寵物不會有任何憐憫、自責或恐懼，也無法被阻止，除非被殺死。" },
	["sends a shadowy bolt at the enemy causing # shadow damage"] = { ko = "적에게 어둠의 화살을 발사하여 {1}의 암흑 피해를 입힙니다.", zhCN = "向目标射出一支暗影箭，对其造成{1}点暗影伤害。", zhTW = "向目標射出一支暗影箭，對其造成{1}點暗影傷害。" },
	["sends a shadowy bolt at the enemy, causing # to # shadow damage"] = { ko = "적에게 어둠의 화살을 발사하여 {1}~{2}의 암흑 피해를 입힙니다.", zhCN = "向目标射出一支暗影箭，对其造成{1}至{2}点暗影伤害。", zhTW = "向目標射出一支暗影箭，對其造成{1}至{2}點暗影傷害。" },
	["sends bolts of holy power in all directions, causing # to # holy damage to all undead and demon targets within # yds and stunning them for # sec"] = { ko = "사방으로 신성한 힘의 섬광을 내뿜어 {3}미터 반경 내의 모든 언데드 또는 악마에게 {1}~{2}의 신성 피해를 입히고 {4}초 동안 기절시킵니다.", zhCN = "向四面八方射出神圣能量箭矢，对{3}码内所有亡灵和恶魔目标造成{1}至{2}点神圣伤害，并使其昏迷{4}秒。", zhTW = "向四面八方射出充滿神聖能量的箭矢，對聖騎士半徑{3}碼範圍內的所有不死生物和惡魔造成{1}至{2}點神聖傷害，並使其昏迷{4}秒。" },
	["shackles the target undead enemy for up to # sec"] = { ko = "최대 {1}초 동안 대상 언데드를 속박시킵니다.", zhCN = "束缚敌对亡灵单位，最多持续{1}秒。", zhTW = "束縛敵對不死族單位，最多持續{1}秒。" },
	["shackles the target undead enemy for up to # sec. the shackled unit is unable to move, attack or cast spells. any damage caused will release the target. only one target can be shackled at a time"] = { ko = "최대 {1}초 동안 대상 언데드를 속박시킵니다. 속박된 대상은 이동하거나 공격, 주문 시전이 불가능합니다. 대상은 피해를 입으면 해제됩니다. 한 번에 하나의 대상만 속박할 수 있습니다.", zhCN = "束缚敌对亡灵单位，最多持续{1}秒。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。", zhTW = "束縛敵對不死族單位，最多持續{1}秒。被束縛的不死族無法移動、攻擊或施法。任何對其造成傷害的行為都將解除束縛。一個牧師在同一時間內只能束縛一個目標。" },
	["shapeshift into aquatic form, increasing swim speed by #% and allowing the druid to breathe underwater. also protects the caster from polymorph effects"] = { ko = "수중 생물로 변신합니다. 수영 속도가 {1}%만큼 증가하며 물 속에서 숨을 쉴 수 있습니다. 이 동안은 변이 효과에 영향을 받지 않습니다." },
	["shapeshift into bear form, increasing attack power by #, armor contribution from items by #%, and health by # also protects the caster from polymorph effects and allows the use of various bear abilities"] = { ko = "곰 모습으로 변신합니다. 전투력이 {1}만큼, 장비 착용으로 인한 방어도가 {2}%만큼, 생명력이 180만큼 증가하며 여러 곰 능력을 사용할 수 있습니다. 이 동안은 변이 효과에 영향을 받지 않습니다." },
	["shapeshift into cat form, increasing attack power by # plus agility. also protects the caster from polymorph effects and allows the use of various cat abilities"] = { ko = "표범 모습으로 변신합니다. 전투력이 민첩성 + {1}만큼 증가하며 여러 표범 능력을 사용할 수 있습니다. 이 동안은 변이 효과에 영향을 받지 않습니다." },
	["shapeshift into dire bear form, increasing attack power by #, armor contribution from items by #%, and health by # also protects the caster from polymorph effects and allows the use of various bear abilities"] = { ko = "광포한 곰 모습으로 변신합니다. 전투력이 {1}만큼, 장비 착용으로 인한 방어도가 {2}%만큼, 생명력이 600만큼 증가하며 여러 곰 능력을 사용할 수 있습니다. 이 동안은 변이 효과에 영향을 받지 않습니다." },
	["shapeshift into moonkin form, increasing omen of clarity's chance to trigger by #%, armor contribution from items by #%, and all party members within # yards have their critical strike chance increased by #%, exclusive with leader of the pack. also protects the caster from polymorph effects and prevents the use of healing spells"] = { ko = "달빛야수로 변신합니다. 청명의 전조가 발동할 확률이 {1}%만큼, 장비 착용으로 인한 방어도가 {2}%만큼 증가하고, {3}미터 내의 모든 파티원의 치명타 확률이 {4}%만큼 증가합니다(무리의 우두머리와 중첩되지 않음). 이 동안은 변이 효과에 영향을 받지 않으며 치유 주문을 시전할 수 없습니다.", zhCN = "使德鲁伊变形为枭兽形态。在此形态下，物品提供的护甲值提高{2}%，清晰预兆触发的几率提高{1}%，并使{3}码内所有队伍成员的爆击几率提高{4}%（与兽群领袖互斥）。枭兽形态下无法施放治疗法术。", zhTW = "使德魯伊變形為梟獸形態。在此形態下，物品提供的護甲值提高{2}%，清晰預兆觸發的機率提高{1}%，並使{3}碼內所有隊伍成員的致命一擊機率提高{4}%（與獸群領袖互斥）。梟獸形態下無法施放治療法術。" },
	["shapeshift into travel form, increasing movement speed by #%. also protects the caster from polymorph effects. only useable outdoors"] = { ko = "치타의 모습으로 변신합니다. 이동 속도가 {1}%만큼 증가합니다. 이 동안은 변이 효과에 영향을 받지 않습니다. 야외에서만 사용할 수 있습니다." },
	["shifting power's cost is reduced by effects that reduce the cost of shapeshifting"] = { ko = "변신의 마나 비용을 줄이는 효과는 변신의 힘의 비용도 줄입니다." },
	["shifts the imp out of phase with the world, making it unattackable unless it attacks"] = { ko = "임프의 실체를 현실의 위상과 다르게 변화시켜 먼저 공격하기 전까진 공격받지 않도록 합니다.", zhCN = "小鬼的实体形态脱离这个世界，从而不会受到攻击，除非小鬼自己发动攻击。", zhTW = "小鬼的實體形態脫離這個世界，從而不會受到攻擊，除非小鬼自己發動攻擊。" },
	["shows the location of all nearby beasts on the minimap"] = { ko = "주변에 있는 모든 야수의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有野兽的位置。", zhTW = "在小地圖上顯示附近所有野獸的位置。" },
	["shows the location of all nearby beasts on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 야수의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有野兽的位置。同一时间只能激活一种追踪。", zhTW = "在小地圖上顯示附近所有野獸的位置。一次只能啟動一種追蹤技能。" },
	["shows the location of all nearby demons on the minimap"] = { ko = "주변에 있는 모든 악마의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有恶魔的位置。", zhTW = "在小地圖上顯示附近所有惡魔的位置，直到取消。" },
	["shows the location of all nearby demons on the minimap until cancelled"] = { ko = "취소할 때까지 주변에 있는 모든 악마의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有恶魔的位置。", zhTW = "在小地圖上顯示附近所有惡魔的位置，直到取消。" },
	["shows the location of all nearby demons on the minimap until cancelled. only one type of tracking can be used at a time"] = { ko = "취소할 때까지 주변에 있는 모든 악마의 위치를 미니맵에 표시합니다. 추적 및 탐지 기술은 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有恶魔的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有惡魔的位置，直到取消。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby demons on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 악마의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有恶魔的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有惡魔的位置，直到取消。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby dragonkin on the minimap"] = { ko = "주변에 있는 모든 용족의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有龙类的位置。", zhTW = "在小地圖上顯示附近所有龍類的位置。" },
	["shows the location of all nearby dragonkin on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 용족의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有龙类的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有龍類的位置。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby elementals on the minimap"] = { ko = "주변에 있는 모든 정령의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有元素生物的位置。", zhTW = "在小地圖上顯示附近所有元素生物的位置。" },
	["shows the location of all nearby elementals on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 정령의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有元素生物的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有元素生物的位置。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby giants on the minimap"] = { ko = "주변에 있는 모든 거인의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有巨人的位置。", zhTW = "在小地圖上顯示附近所有巨人的位置。" },
	["shows the location of all nearby giants on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 거인의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有巨人的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有巨人的位置。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby humanoids on the minimap"] = { ko = "주변에 있는 모든 인간형의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有人型生物的位置。", zhTW = "在小地圖上顯示附近所有人型生物的位置。" },
	["shows the location of all nearby humanoids on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 인간형의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有人型生物的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有人型生物的位置。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby humanoids on the minimap. only one type of thing can be tracked at a time"] = { ko = "주변에 있는 모든 인간형 몬스터의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有人型生物的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有人型生物的位置。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby undead on the minimap"] = { ko = "주변에 있는 모든 언데드의 위치를 미니맵에 표시합니다." },
	["shows the location of all nearby undead on the minimap until cancelled"] = { ko = "취소할 때까지 주변에 있는 모든 언데드의 위치를 미니맵에 표시합니다.", zhCN = "在微缩地图上显示附近所有亡灵的位置。", zhTW = "在小地圖上顯示附近所有不死族的位置，直到取消。" },
	["shows the location of all nearby undead on the minimap until cancelled. only one type of tracking can be used at a time"] = { ko = "취소할 때까지 주변에 있는 모든 언데드의 위치를 미니맵에 표시합니다. 추적 및 탐지 기술은 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有亡灵的位置。同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有不死族的位置，直到取消。同一時間內只能啟動一種追蹤技能。" },
	["shows the location of all nearby undead on the minimap. only one form of tracking can be active at a time"] = { ko = "주변에 있는 모든 언데드의 위치를 미니맵에 표시합니다. 찾기는 동시에 한 종류만 사용할 수 있습니다.", zhCN = "在微缩地图上显示附近所有亡灵的位置，同一时间内只能激活一种追踪技能。", zhTW = "在小地圖上顯示附近所有不死族的位置，同一時間內只能啟動一種追蹤技能。" },
	["shred the target, causing #% damage plus # to the target"] = { ko = "대상을 갈가리 찢어 공격력의 {1}%에 추가로 {2}의 피해를 입힙니다." },
	["shred the target, causing #% damage plus # to the target. must be behind the target. awards # combo point"] = { ko = "대상을 갈가리 찢어 공격력의 {1}%에 추가로 {2}의 피해를 입힙니다. 적의 배후에서 공격해야 합니다. {3}의 연계 포인트가 주어집니다.", zhCN = "撕扯目标，对其造成武器伤害的{1}%再加上{2}点伤害，必须在目标背后发动。奖励{3}个连击点数。", zhTW = "撕扯目標，對其造成武器傷害的{1}%再加上{2}點傷害，必須在目標背後發動。獎勵{3}個連擊點數。" },
	["silences an enemy, preventing it from casting spells for # sec"] = { ko = "적을 침묵시켜 {1}초 동안 마법 시전이 불가능하게 만듭니다." },
	["silences the enemy for # sec"] = { ko = "적을 {1}초 동안 침묵시킵니다.", zhCN = "使敌人沉默{1}秒。", zhTW = "使敵人沉默{1}秒。" },
	["silences the enemy for # sec. if used on a casting target, it will counter the enemy's spellcast, preventing any spell from that school of magic from being cast for # sec"] = { ko = "적을 {1}초 동안 침묵시킵니다. 만약 대상이 주문을 시전중이었다면 주문을 차단하고 {2}초 동안 같은 계열의 주문을 시전하지 못하도록 만듭니다.", zhCN = "使敌人沉默{1}秒。如果目标正在施法，则反制该目标的施法意图，使其在{2}秒内无法施放任何与该法术属于同一类别的法术。", zhTW = "使敵人沉默{1}秒。如果目標正在施法，反制敵人的法術，使其在{2}秒內無法施放任何與該法術屬於同一類別的法術。" },
	["silences the target, preventing them from casting spells for # sec and interrupting their spellcasts for # sec"] = { ko = "대상을 침묵시켜 {1}초 동안 주문을 시전하지 못하게 하고 {2}초 동안 주문 시전을 방해합니다.", zhCN = "使目标沉默，在{1}秒内无法施法，并打断其施法，持续{2}秒。", zhTW = "使目標沉默，並使其在{1}秒內不能施法，且其施法將被中斷，持續{2}秒。" },
	["simultaneously places up to # totems specified in the totem bar"] = { ko = "토템바에 지정된 최대 {1}개의 토템을 동시에 소환합니다.", zhCN = "同时放置图腾栏中的最多{1}个指定图腾。", zhTW = "召喚圖騰列中設定的圖騰，最多可同時召喚{1}根圖騰。" },
	["simultaneously places up to # totems specified in the totem bar. can call different totems than call of the elements"] = { ko = "토템바에 지정된 최대 {1}개의 토템을 동시에 소환합니다. 원소의 부름과 다른 토템을 부를 수 있습니다.", zhCN = "同时放置图腾栏中的最多{1}个指定图腾。可以放置与元素的召唤不同的图腾。", zhTW = "召喚圖騰列中設定的圖騰，最多可同時召喚{1}根圖騰。可以呼喚有別於「元素呼喚」的圖騰。" },
	["simultaneously places up to # totems specified in the totem bar. can call different totems than call of the elements or call of the ancestors"] = { ko = "토템바에 지정된 최대 {1}개의 토템을 동시에 소환합니다. 원소의 부름 또는 선조의 부름과 다른 토템을 부를 수 있습니다.", zhCN = "同时放置图腾栏中的最多{1}个指定图腾。可以放置与元素的召唤或先祖的召唤不同的图腾。", zhTW = "召喚圖騰列中設定的圖騰，最多可同時召喚{1}根圖騰。可以呼喚有別於「元素呼喚」或「先祖呼喚」的圖騰。" },
	["slam the target with your shield, causing # to # damage, increased by your block value, and has a #% chance of dispelling # magic effect on the target"] = { zhCN = "用盾牌猛击目标，造成{1}至{2}点伤害，该伤害受格挡值加成，并有{3}%的几率驱散目标身上的{4}个魔法效果。", zhTW = "用盾牌猛擊目標，對其造成{1}至{2}點傷害，且傷害會隨著格擋值提高，並有{3}%的機率驅散目標身上的{4}個魔法效果。" },
	["slam the target with your shield, causing # to # damage, increased by your block value, and has a #% chance of dispelling # magic effect on the target. causes a very high amount of threat"] = { ko = "대상을 방패로 가격해 {1}~{2}의 피해를 입힙니다. 이 피해는 피해 방어량에 비례하며, {3}%의 확률로 대상에게 걸린 마법 효과 {4}개를 무효화합니다. 위협 수준을 크게 증가시킵니다.", zhCN = "用盾牌猛击目标，造成{1}至{2}点伤害，该伤害受格挡值加成，并有{3}%的几率驱散目标身上的{4}个魔法效果。产生极高的威胁。", zhTW = "用盾牌猛擊目標，對其造成{1}至{2}點傷害，且傷害會隨著格擋值提高，並有{3}%的機率驅散目標身上的{4}個魔法效果。產生極高威脅值。" },
	["slams the opponent, causing weapon damage plus #"] = { ko = "적에게 강하게 부딪혀 무기 공격력에 해당하는 피해와 {1}의 추가 피해를 입힙니다.", zhCN = "猛击敌人，对其造成武器伤害再加上{1}点伤害。", zhTW = "猛擊敵人，對其造成武器傷害再加上{1}點傷害。" },
	["slower weapons cause more fire damage per swing"] = { ko = "공격 속도가 느린 무기일수록 공격당 화염 피해가 커집니다.", zhCN = "武器速度越慢，每次攻击造成的火焰伤害越高。", zhTW = "武器攻速越慢，每次命中造成的火焰傷害越高。" },
	["slower weapons cause more holy damage per swing"] = { ko = "느린 무기일수록 매 타격 시 더 많은 신성 피해를 입힙니다.", zhCN = "武器越慢，每击造成的神圣伤害越高。", zhTW = "攻擊速度越慢的武器每擊造成的傷害越高。" },
	["slows falling speed for # sec"] = { ko = "{1}초 동안 낙하 속도를 감소시킵니다.", zhCN = "减慢下落速度，持续{1}秒。", zhTW = "減緩落下速度，持續{1}秒。" },
	["smite an enemy for # to # holy damage"] = { ko = "적을 강타하여 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "对单体目标造成{1}至{2}点神圣伤害。", zhTW = "對單一目標造成{1}至{2}點神聖傷害。" },
	["sneak up on the trap in order to disarm it"] = { ko = "함정을 해제하려면 조심스럽게 다가가야 합니다.", zhCN = "靠近陷阱以解除它。", zhTW = "靠近陷阱以解除它。" },
	["sneak up on the trap in order to disarm it. don't get too close or the trap will go off"] = { ko = "함정을 해제하려면 조심스럽게 다가가야 합니다. 너무 가까이 다가가면 함정이 동작하게 됩니다.", zhCN = "靠近陷阱以解除它。不要靠得太近，否则陷阱会被触发。", zhTW = "靠近陷阱以解除它。不要靠得太近，否則陷阱會被觸發。" },
	["some targets cannot be displaced"] = { ko = "몇몇 대상은 무효화하지 못합니다.", zhCN = "有些目标无法被置换。", zhTW = "有些目標無法被置換。" },
	["soothes the target beast, reducing the range at which it will attack you by # yards"] = { ko = "대상 야수를 진정시켜 경계 범위를 {1}미터만큼 감소시킵니다.", zhCN = "安抚目标野兽，使它的警戒范围减少{1}码。", zhTW = "安撫目標野獸，使它的警戒範圍減少{1}碼。" },
	["soothes the target beast, reducing the range at which it will attack you by # yards. only affects beast targets level # or lower. lasts # sec"] = { ko = "대상 야수를 진정시켜 경계 범위를 {1}미터만큼 감소시킵니다. {2}레벨 이하의 야수에게만 사용할 수 있습니다. {3}초 동안 지속됩니다.", zhCN = "安抚目标野兽，使它的警戒范围减少{1}码。只对{2}级及以下等级的目标有效。持续{3}秒。", zhTW = "安撫目標野獸，使它的警戒範圍減少{1}碼。只對{2}級及以下等級的目標有效。持續{3}秒。" },
	["soothes the target, increasing the chance that it will attack something else"] = { ko = "대상을 진정시켜 자신이 아닌 다른 누군가를 공격할 확률을 증가시킵니다.", zhCN = "安抚目标，提高令它不再攻击你的几率。", zhTW = "安撫目標，提高令它不再攻擊你的機率。" },
	["soothes the target, increasing the chance that it will attack something else. more effective than soothing kiss (rank #)"] = { ko = "대상을 진정시켜 자신이 아닌 다른 누군가를 공격할 확률을 증가시킵니다. {1}레벨 유혹의 입맞춤보다 효과가 좋습니다.", zhCN = "安抚目标，提高令它不再攻击你的几率。比安抚之吻（等级 {1}）更有效。", zhTW = "安撫目標，提高令它不再攻擊你的機率。比安撫之吻（等級 {1}）更有效。" },
	["soothes the target, reducing the range at which it will attack you by # yards"] = { zhCN = "安抚目标，使它的警戒范围减少{1}码。", zhTW = "安撫目標，使它的警戒範圍減少{1}碼。" },
	["soothes the target, reducing the range at which it will attack you by # yards. only affects humanoid targets level # or lower. lasts # sec"] = { ko = "대상을 진정시켜 공격 범위를 {1}미터 만큼 감소시킵니다. {2}레벨 이하의 인간형 대상에만 가능하며 {3}초 동안 지속됩니다.", zhCN = "安抚目标，使它的警戒范围减少{1}码。只对{2}级及以下等级的人型目标有效。持续{3}秒。", zhTW = "安撫目標，使它的警戒範圍減少{1}碼。只對{2}級及以下等級的人型目標有效。持續{3}秒。" },
	["soul shards are required for other spells"] = { ko = "영혼의 조각은 다른 흑마법에 사용됩니다.", zhCN = "灵魂碎片是施放其他法术所需的材料。", zhTW = "靈魂碎片是施放其他一些法術所必需的材料。" },
	["speak to an innkeeper in a different place to change your home location"] = { ko = "귀환 장소를 변경하려면 여관주인과 대화하십시오.", zhCN = "与不同地区的旅店老板谈话可以改变你的家所在的位置。", zhTW = "與不同地區的旅店老闆談話可以改變你的家所在的位置。" },
	["speed is increased by #%"] = { ko = "이동 속도가 {1}%만큼 증가합니다.", zhCN = "速度提高{1}%。", zhTW = "速度提高{1}%。" },
	["spell damage received is reduced by #"] = { ko = "받는 주문 피해가 {1}만큼 감소합니다.", zhCN = "受到法术攻击时承受的伤害降低{1}点。", zhTW = "受到的法術傷害降低{1}點。" },
	["spells and attacks deal # shadow damage. deals # times as much damage to murlocs"] = { zhCN = "对鱼人的法术和攻击造成{1}点暗影伤害。", zhTW = "對魚人的法術和攻擊造成{1}點暗影傷害。" },
	["spirit increases the amount converted"] = { ko = "정신력에 따라 변환하는 양이 증가합니다.", zhCN = "精神越高，转化的数值越多。", zhTW = "精神越高，轉化的數值越多。" },
	["stacks up to # times"] = { ko = "최대 {1}번까지 중첩됩니다.", zhCN = "最多叠加{1}次。", zhTW = "最多可堆疊{1}層。" },
	["stacks up to # times on a single target"] = { ko = "효과는 대상마다 {1}번까지 중복될 수 있습니다.", zhCN = "腐坏之血的效果可以对单一目标叠加{1}次。", zhTW = "腐壞之血的效果可以對單一目標疊加{1}次。" },
	["stacks up to # times on a single target. # charges"] = { zhCN = "可使用{2}次。", zhTW = "可使用{2}次。" },
	["stamina increased by #"] = { ko = "체력이 {1}만큼 증가합니다.", zhCN = "耐力提高{1}点。", zhTW = "耐力提高{1}點。" },
	["stings the target, causing # nature damage over # sec"] = { ko = "쐐기를 대상에게 발사하여 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다.", zhCN = "钉刺目标，在{2}秒内对其造成{1}点自然伤害。", zhTW = "釘刺目標，在{2}秒內對其造成{1}點自然傷害。" },
	["stings the target, causing # nature damage over # sec. only one sting per hunter can be active on any one target"] = { ko = "쐐기를 대상에게 발사하여 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다. 사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.", zhCN = "钉刺目标，在{2}秒内对其造成{1}点自然伤害。每个猎人在同一时间内只能对一个目标使用一种钉刺。", zhTW = "釘刺目標，在{2}秒內對其造成{1}點自然傷害。每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["stings the target, draining # mana over # sec"] = { ko = "쐐기를 대상에게 발사하여 {2}초에 걸쳐 총 {1}의 마나를 소진시킵니다.", zhCN = "钉刺目标，在{2}秒内抽取{1}点法力值。", zhTW = "釘刺目標，在{2}秒內抽取{1}點法力。" },
	["stings the target, draining # mana over # sec. only one sting per hunter can be active on any one target"] = { ko = "쐐기를 대상에게 발사하여 {2}초에 걸쳐 총 {1}의 마나를 소진시킵니다. 사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.", zhCN = "钉刺目标，在{2}秒内抽取{1}点法力值。每个猎人在同一时间内只能对一个目标使用一种钉刺。", zhTW = "釘刺目標，在{2}秒內抽取{1}點法力。每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["stings the target, draining #,# mana over # sec"] = { ko = "쐐기를 대상에게 발사하여 {3}초에 걸쳐 총 {1},{2}의 마나를 소진시킵니다.", zhCN = "钉刺目标，在{3}秒内抽取{1},{2}点法力值。", zhTW = "釘刺目標，在{3}秒內抽取{1},{2}點法力。" },
	["stings the target, draining #,# mana over # sec. only one sting per hunter can be active on any one target"] = { ko = "쐐기를 대상에게 발사하여 {3}초에 걸쳐 총 {1},{2}의 마나를 소진시킵니다. 사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.", zhCN = "钉刺目标，在{3}秒内抽取{1},{2}点法力值。每个猎人在同一时间内只能对一个目标使用一种钉刺。", zhTW = "釘刺目標，在{3}秒內抽取{1},{2}點法力。每個獵人在同一時間內只能對一個目標使用一種釘刺，且同類釘刺無法疊加。" },
	["stings the target, reducing the target's chance to hit with attacks by #% for # sec"] = { ko = "쐐기를 대상에게 발사하여 {2}초 동안 대상이 사용하는 공격의 적중률을 {1}%만큼 감소시킵니다.", zhCN = "钉刺目标，使其攻击的命中几率降低{1}%，持续{2}秒。", zhTW = "釘刺目標，使目標攻擊的命中機率降低{1}%，持續{2}秒。" },
	["stings the target, reducing the target's chance to hit with attacks by #% for # sec. only one sting per hunter can be active on any one target"] = { ko = "쐐기를 대상에게 발사하여 {2}초 동안 대상이 사용하는 공격의 적중률을 {1}%만큼 감소시킵니다. 사냥꾼마다 한 대상에 동시에 하나의 쐐기만 사용할 수 있습니다.", zhCN = "钉刺目标，使其攻击的命中几率降低{1}%，持续{2}秒。每个猎人在任一目标身上只能维持一种钉刺。", zhTW = "釘刺目標，使目標攻擊的命中機率降低{1}%，持續{2}秒。每個獵人在同一時間內只能對同一個目標維持一種釘刺。" },
	["stores up to # charges"] = { ko = "최대 {1}회 충전됩니다.", zhCN = "最多储存{1}层。" },
	["strikes fear in the enemy, causing it to run in fear for up to # sec"] = { ko = "적을 공포에 사로잡히게 하여 최대 {1}초 동안 시전자로부터 도망갑니다." },
	["strikes fear in the enemy, causing it to run in fear for up to # sec. damage caused may interrupt the effect. only # target can be feared at a time"] = { ko = "적을 공포에 사로잡히게 하여 최대 {1}초 동안 시전자로부터 도망갑니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 동시에 한 대상에게만 공포를 사용할 수 있습니다.", zhCN = "使敌人因为极度的恐惧而奔逃，最多持续{1}秒。在同一时间内，只有{2}个敌人会被你的恐惧术影响。", zhTW = "使敵人因為極度的恐懼而奔逃，最多持續{1}秒。在同一時間內，只有{2}個敵人會被你的恐懼術影響。" },
	["stun the target for # sec"] = { ko = "{1}초 동안 대상을 기절시킵니다.", zhCN = "使目标昏迷{1}秒。", zhTW = "使目標昏迷{1}秒。" },
	["stuns target worgen for # sec"] = { ko = "대상 늑대인간을 {1}초 동안 기절시킵니다.", zhCN = "使目标狼人昏迷{1}秒。", zhTW = "使目標狼人昏迷{1}秒。" },
	["stuns the target for # sec"] = { ko = "{1}초 동안 대상을 기절시킵니다.", zhCN = "使目标昏迷，持续{1}秒。", zhTW = "使目標昏迷{1}秒。" },
	["stuns the target for # sec. must be stealthed. awards # combo points"] = { ko = "적을 공격하여 {1}초 동안 적을 기절시킵니다. 은신 상태로 공격해야 합니다. {2}의 연계 포인트가 주어집니다.", zhCN = "使目标昏迷{1}秒，必须在潜行状态下使用。奖励{2}点连击点数。", zhTW = "使目標昏迷{1}秒，必須在潛行狀態下使用。獎勵{2}點連擊點數。" },
	["subjugates the target demon, up to level #, forcing it to do your bidding"] = { ko = "최대 {1} 레벨의 대상 악마를 예속해 시전자의 명령을 따르게 합니다.", zhCN = "征服等级不高于{1}级的恶魔，令其听从你的命令。", zhTW = "制伏等級{1}以下的惡魔，令其聽從你的命令。" },
	["subjugates the target demon, up to level #, forcing it to do your bidding. while subjugated, the time between the demon's attacks is increased by #% and its casting speed is slowed by #%. lasts up to # min. if you repeatedly subjugate the same demon, it will become more difficult to control with each attempt"] = { ko = "최대 {1} 레벨의 대상 악마를 예속해 시전자의 명령을 따르게 합니다. 예속된 상태에서는 대상 악마의 공격 간격이 {2}%만큼 늘어나고 주문 시전 속도가 {3}%만큼 감소합니다. 최대 {4}분 동안 지속됩니다. 같은 악마를 반복해서 예속할 경우, 시도할 때마다 점점 더 통제하기 어려워집니다.", zhCN = "征服等级不高于{1}级的恶魔，令其听从你的命令。被征服的恶魔的攻击间隔延长{2}%，施法速度降低{3}%。征服效果最多持续{4}分钟。如果你反复征服同一个恶魔，它摆脱控制的几率会越来越大。", zhTW = "制伏等級{1}以下的惡魔，令其聽從你的命令。被制伏的惡魔攻擊間隔時間延長{2}%，施法速度降低{3}%。制伏效果最多持續{4}分鐘。如果你重複制伏同一個惡魔，操控惡魔的難度將會隨著制伏次數增加而提高。" },
	["succubus/incubus - increases shadow damage done by #%"] = { ko = "서큐버스/인큐버스 - 암흑 공격력이 {1}%만큼 증가합니다.", zhCN = "魅魔/夜魔 - 暗影伤害提高{1}%。", zhTW = "魅魔/夢魔 - 造成的暗影傷害提高{1}%。" },
	["succubus/incubus: increases your fire damage by #%"] = { ko = "서큐버스/인큐버스: 화염 공격력이 {1}%만큼 증가합니다.", zhCN = "魅魔/夜魔：使你的火焰伤害提高{1}%。", zhTW = "魅魔/夢魔：使你的火焰傷害提高{1}%。" },
	["summon hawk shares its cooldown with arcane shot"] = { ko = "매 소환은 신비한 사격과 재사용 대기시간을 공유합니다.", zhCN = "召唤雄鹰与奥术射击共享冷却时间。", zhTW = "召喚獵鷹與秘法射擊共享冷卻時間。" },
	["summons a charger, which serves as a mount"] = { ko = "군마를 소환하여 탈것으로 이용합니다.", zhCN = "召唤一匹战马作为你的坐骑。", zhTW = "召喚一匹戰馬作為你的坐騎。" },
	["summons a charger, which serves as a mount. speed is increased by #%"] = { ko = "군마를 소환하여 탈것으로 이용합니다. 이동 속도가 {1}%만큼 증가합니다.", zhCN = "召唤一匹战马作为你的坐骑。速度提高{1}%。", zhTW = "召喚一匹戰馬作為你的坐騎。速度提高{1}%。" },
	["summons a disease cleansing totem with # health at the feet of the caster that attempts to remove # disease effect from party members within # yards every # sec"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 질병 정화 토템을 소환하여 매 {4}초마다 주위 {3}미터 반경 내 파티원의 질병 효과 {2}개의 제거를 시도합니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的祛病图腾，每{4}秒为半径{3}码范围内的队友驱散{2}个疾病效果。", zhTW = "在施法者身邊召喚一個生命力為{1}點的祛病圖騰，每{4}秒為半徑{3}碼範圍內的隊友驅散{2}個疾病效果。" },
	["summons a disease cleansing totem with # health at the feet of the caster that attempts to remove # disease effect from party members within # yards every # sec. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 질병 정화 토템을 소환하여 매 {4}초마다 주위 {3}미터 반경 내 파티원의 질병 효과 {2}개의 제거를 시도합니다. {5}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的祛病图腾，每{4}秒为半径{3}码范围内的队友驱散{2}个疾病效果。持续{5}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的祛病圖騰，每{4}秒為半徑{3}碼範圍內的隊友驅散{2}個疾病效果。持續{5}分鐘。" },
	["summons a dreadsteed, which serves as a mount for the caster"] = { ko = "공포마를 소환하여 탈것으로 이용합니다.", zhCN = "召唤一匹恐惧战马作为你的坐骑。", zhTW = "召喚一匹恐懼戰馬作為你的坐騎。" },
	["summons a dreadsteed, which serves as a mount for the caster. speed is increased by #%"] = { ko = "공포마를 소환하여 탈것으로 이용합니다. 이동 속도가 {1}%만큼 증가합니다.", zhCN = "召唤一匹恐惧战马作为你的坐骑。速度提高{1}%。", zhTW = "召喚一匹恐懼戰馬作為你的坐騎。速度提高{1}%。" },
	["summons a felhunter under the command of the warlock"] = { ko = "지옥사냥개를 소환하여 부립니다.", zhCN = "召唤一只地狱猎犬为术士作战。", zhTW = "召喚一隻地獄獵犬為術士作戰。" },
	["summons a felsteed, which serves as a mount for the caster"] = { ko = "지옥마를 소환하여 탈것으로 이용합니다.", zhCN = "召唤一匹地狱战马作为你的坐骑。", zhTW = "召喚一匹地獄戰馬作為你的坐騎。" },
	["summons a felsteed, which serves as a mount for the caster. speed is increased by #%"] = { ko = "지옥마를 소환하여 탈것으로 이용합니다. 이동 속도가 {1}%만큼 증가합니다.", zhCN = "召唤一匹地狱战马作为你的坐骑。速度提高{1}%。", zhTW = "召喚一匹地獄戰馬作為你的坐騎。速度提高{1}%。" },
	["summons a fire nova totem that has # health and lasts # sec. unless it is destroyed within # sec., the totem inflicts # to # fire damage to enemies within # yd"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 불꽃 회오리 토템을 소환합니다. 소환 후 {3}초 안에 파괴되지 않으면 주위 {6}미터 반경 내에 있는 모든 적에게 {4} 에서 {5}의 화염 피해를 입힙니다. {2}초 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}的火焰新星图腾，在被召唤出来{3}秒钟之后，它会对半径{6}码范围内的敌人造成{4}至{5}点火焰伤害，持续{2}秒。", zhTW = "在施法者身邊召喚一個生命力為{1}的火焰新星圖騰，在被召喚出來{3}秒鐘之後，它會對半徑{6}碼範圍內的敵人造成{4}至{5}點火焰傷害，持續{2}秒。" },
	["summons a fire resistance totem with # health at the feet of the caster for # min that increases the fire resistance of party and raid members within # yards by #"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 화염 저항 토템을 소환하여 {3}미터 반경에 있는 파티원과 공격대원의 화염 저항력을 {4}만큼 증가시킵니다. {2}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的抗火图腾，持续{2}分钟。图腾周围半径{3}码范围内的所有小队和团队成员的火焰抗性提高{4}点。", zhTW = "在施法者身邊召喚一個生命力為{1}點的抗火圖騰，持續{2}分鐘。它可以使半徑{3}碼範圍內所有小隊與團隊成員的火焰抗性提高{4}點。" },
	["summons a flametongue totem with # health at the feet of the caster"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 불꽃의 토템을 소환합니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的火舌图腾。", zhTW = "在施法者身邊召喚一個生命力為{1}點的火舌圖騰。" },
	["summons a flametongue totem with # health at the feet of the caster. the totem enchants all party members' main-hand weapons with fire if they are within # yards. each hit causes # to # additional fire damage, based on the speed of the weapon. slower weapons cause more fire damage per swing. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 불꽃의 토템을 소환합니다. 토템은 {2}미터 내에 있는 모든 파티원의 주장비 무기에 불꽃을 부여합니다. 무기 공격이 적중할 때마다 무기의 공격 속도에 따라 {3}에서 {4}의 추가 화염 피해를 입힙니다. 공격 속도가 느린 무기는 공격 시 더 큰 화염 피해를 입힙니다. {5}분 동안 지속됩니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的火舌图腾。该图腾会为{2}码内所有队伍成员的主手武器附加火焰。每次命中会根据武器速度额外造成{3}至{4}点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续{5}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的火舌圖騰。它可以使半徑{2}碼範圍內的所有小隊成員的主手武器附帶火焰效果，每次命中敵人時，根據武器攻速，可額外造成{3}至{4}點火焰傷害。武器攻速越慢，每次命中造成的火焰傷害越高。持續{5}分鐘。" },
	["summons a flametongue totem with # health at the feet of the caster. the totem enhances the melee attacks of all party members within # yards. each main hand hit causes # to # additional fire damage, based on the speed of the weapon. slower weapons cause more fire damage per swing. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 불꽃의 토템을 소환합니다. 불꽃의 토템은 {2}미터 내 모든 파티원의 근접 공격을 강화합니다. 이때 주무기로 공격을 적중시킬 때마다 무기의 공격 속도에 따라 {3}~{4}의 추가 화염 피해를 입힙니다. 공격 속도가 느린 무기는 공격 시 더 큰 화염 피해를 입힙니다. {5}분 동안 지속됩니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的火舌图腾。该图腾会强化{2}码内所有队伍成员的近战攻击。每次主手命中会根据武器速度额外造成{3}至{4}点火焰伤害。武器速度越慢，每次攻击造成的火焰伤害越高。持续{5}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的火舌圖騰。它可以強化半徑{2}碼範圍內的所有小隊成員的近戰攻擊。每次主手武器命中敵人時，根據武器攻速，可額外造成{3}至{4}點火焰傷害。武器攻速越慢，每次命中造成的火焰傷害越高。持續{5}分鐘。" },
	["summons a frost resistance totem with # health at the feet of the caster for # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 냉기 저항 토템을 소환하여 30미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 30만큼 증가시킵니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的抗寒图腾，持续{2}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的抗寒圖騰，持續{2}分鐘。" },
	["summons a frost resistance totem with # health at the feet of the caster for # min. the totem increases party and raid members' frost resistance by #, if within # yards"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 냉기 저항 토템을 소환하여 {3}미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 {4}만큼 증가시킵니다. {2}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的抗寒图腾，持续{2}分钟。图腾周围半径{3}码范围内的所有小队和团队成员的冰霜抗性提高{4}点。", zhTW = "在施法者身邊召喚一個生命力為{1}點的抗寒圖騰，持續{2}分鐘。圖騰可以使半徑{3}碼範圍內所有小隊與團隊成員的冰霜抗性提高{4}點。" },
	["summons a grace of air totem with # health at the feet of the caster. the totem increases the agility of party members within # yards by # lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 은총의 토템을 소환하여 주위 {2}미터 반경 내에 있는 파티원의 민첩성을 49만큼 증가시킵니다. {4}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}的风之优雅图腾。这个图腾可以使半径{2}码范围内的小队成员的敏捷提高49点，持续{4}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}的風之優雅圖騰。這個圖騰可以使半徑{2}碼範圍內的小隊成員的敏捷提高49點，持續{4}分鐘。" },
	["summons a grounding totem with # health at the feet of the caster that will redirect one harmful spell cast on a nearby party member to itself every # sec. will not redirect area of effect spells. lasts # sec"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 마법정화 토템을 소환합니다. 매 {2}초마다 주위 파티원을 대상으로 시전되는 해로운 주문 1개의 목표가 마법정화 토템으로 바뀝니다. 광역 주문은 목표를 바꿀 수 없습니다. {3}초 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的根基图腾，每{2}秒为附近的每个队友吸收一个有害法术，但不会吸收区域效果法术。持续{3}秒。", zhTW = "在施法者身邊召喚一個生命力為{1}點的根基圖騰，每{2}秒為附近的每個隊友吸收一個有害法術，但不會吸收區域效果法術。持續{3}秒。" },
	["summons a healing stream totem with # health at the feet of the caster for # min that heals group members within # yards for # every # sec"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 치유의 토템을 소환하여 주위 {3}미터 반경 내에 있는 파티원의 생명력을 매 {5}초마다 {2}만큼 회복시키게 합니다. {4}분 동안 지속됩니다.", zhCN = "在施法者身边召唤出一个生命值为{1}点的治疗之泉图腾，每{5}秒对半径{3}码范围内的所有小队成员恢复{2}点生命值，持续{4}分钟。", zhTW = "在施法者身邊召喚出一個生命力為{1}點的治療之泉圖騰，每{5}秒對半徑{3}碼範圍內的所有小隊成員恢復{2}點生命力，持續{4}分鐘。" },
	["summons a magma totem with # health at the feet of the caster for # sec that causes # fire damage to creatures within # yards every # sec"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 용암 토템을 소환하여 매 {5}초마다 {4}미터 반경의 적에게 {2}의 화염 피해를 주게 합니다. {3}초 동안 지속됩니다.", zhCN = "在施法者身边召唤一根生命值为{1}点的熔岩图腾，每{5}秒对它身边半径{4}范围内的所有敌人造成{2}点火焰伤害。持续{3}秒。", zhTW = "在施法者身邊召喚一根生命力為{1}點的熔岩圖騰，每{5}秒對它身邊半徑{4}範圍內的所有敵人造成{2}點火焰傷害。持續{3}秒。" },
	["summons a mana spring totem with # health at the feet of the caster for # min that restores # mana every # sec to group members within # yards"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 마나샘 토템을 소환하여 주위 {5}미터 반경 내에 있는 파티원의 마나를 매 {4}초마다 {3}만큼 회복시키게 합니다. {2}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的法力之泉图腾，持续{2}分钟。它可以为半径{5}码范围内的小队成员每{4}秒回复{3}点法力值。", zhTW = "在施法者身邊召喚一個生命力為{1}點的法力之泉圖騰，持續{2}分鐘。它可以為半徑{5}碼範圍內的小隊成員每{4}秒恢復{3}點法力。" },
	["summons a mana tide totem with # health at the feet of the caster for # sec that restores # mana every # sec to group members within # yards"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 마나 해일 토템을 소환하여 주위 {5}미터 반경 내의 파티원의 마나를 매 {4}초마다 {3}만큼 회복시킵니다. {2} 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的法力之潮图腾，持续{2}秒。它可以为半径{5}码范围内的小队成员每{4}秒回复{3}点法力值。", zhTW = "在施法者身邊召喚一個生命力為{1}點的法力之潮圖騰，持續{2}秒。它可以為半徑{5}碼範圍內的小隊成員每{4}秒恢復{3}點法力。" },
	["summons a meteor from the twisting nether, causing # fire damage and stunning all enemy targets in the area for # sec"] = { ko = "뒤틀린 황천으로부터 운석을 소환하여 선택한 지역의 모든 적에게 {1}의 화염 피해를 입히고 {2}초 동안 기절시킵니다.", zhCN = "从扭曲虚空中召来一颗流星，对其着陆区域的所有敌人造成{1}点火焰伤害，并使它们昏迷{2}秒。", zhTW = "從扭曲虛空中召來一顆隕石，對其著陸區域的所有敵人造成{1}點火焰傷害，並使他們昏迷{2}秒。" },
	["summons a meteor from the twisting nether, causing # fire damage and stunning all enemy targets in the area for # sec. an infernal rises from the crater, under the command of the caster for # min. once control is lost, the infernal must be subjugated to maintain control. can only be used outdoors"] = { ko = "뒤틀린 황천으로부터 운석을 소환하여 선택한 지역의 모든 적에게 {1}의 화염 피해를 입히고 {2}초 동안 기절시킵니다. 분화구에서 일어난 지옥불정령은 {3}분 동안 흑마법사의 지배를 받습니다. 만약 지옥불정령이 지배에서 풀려나면 다시 예속해야만 제어권을 유지할 수 있습니다. 야외에서만 사용할 수 있습니다.", zhCN = "从扭曲虚空中召来一颗流星，对其着陆区域的所有敌人造成{1}点火焰伤害，并使它们昏迷{2}秒。一个巨大的地狱火恶魔将从着陆点出现，并被施法者控制{3}分钟。如果控制失效，则施法者必须征服地狱火才能继续指挥它。只能在户外使用。", zhTW = "從扭曲虛空中召來一顆隕石，對其著陸區域的所有敵人造成{1}點火焰傷害，並使他們昏迷{2}秒。一個煉獄火將從著陸點出現，並受控於施法者，持續{3}分鐘。當它失控時，施法者必須制伏煉獄火才能繼續操控它。只能在戶外使用。" },
	["summons a nature resistance totem with # health at the feet of the caster for # min that increases the nature resistance of party and raid members within # yards by #"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 자연 저항 토템을 소환하여 {3}미터 반경에 있는 파티원과 공격대원의 자연 저항력을 {4}만큼 증가시킵니다. {2}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的自然抗性图腾，持续{2}分钟。图腾周围半径{3}码范围内的所有小队和团队成员的自然抗性提高{4}点。", zhTW = "在施法者身邊召喚一個生命力為{1}點的自然抗性圖騰，持續{2}分鐘。它可以使半徑{3}碼範圍內所有小隊與團隊成員的自然抗性提高{4}點。" },
	["summons a poison cleansing totem with # health at the feet of the caster that attempts to remove # poison effect from party members within # yards every # sec"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 독 정화 토템을 소환하여 매 {4}초마다 주위 {3}미터 반경 내 파티원의 독 효과 {2}개의 제거를 시도합니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的清毒图腾，每{4}秒为半径{3}码范围内的所有队友驱散{2}个中毒效果。", zhTW = "在施法者身邊召喚一個生命力為{1}點的清毒圖騰，每{4}秒為半徑{3}碼範圍內的所有隊友驅散{2}個中毒效果。" },
	["summons a poison cleansing totem with # health at the feet of the caster that attempts to remove # poison effect from party members within # yards every # sec. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 독 정화 토템을 소환하여 매 {4}초마다 주위 {3}미터 반경 내 파티원의 독 효과 {2}개의 제거를 시도합니다. {5}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的清毒图腾，每{4}秒为半径{3}码范围内的所有队友驱散{2}个中毒效果。持续{5}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的清毒圖騰，每{4}秒為半徑{3}碼範圍內的所有隊友驅散{2}個中毒效果。持續{5}分鐘。" },
	["summons a reagent bot that allows you and others nearby to purchase reagents"] = { ko = "자신과 주위의 다른 플레이어가 재료를 구매할 수 있는 재료 로봇을 소환합니다.", zhCN = "召唤一个试剂机器人，允许你和附近的其他人购买材料。", zhTW = "召喚一個材料機器人，你和其他人可向其購買材料。" },
	["summons a reagent bot that allows you and others nearby to purchase reagents. requires a campfire nearby. all camping features share a cooldown of # hr"] = { ko = "자신과 주위의 다른 플레이어가 재료를 구매할 수 있는 재료 로봇을 소환합니다. 주위에 모닥불이 있어야 합니다. 모든 야영 설비는 {1}시간의 재사용 대기시간을 공유합니다.", zhCN = "召唤一个试剂机器人，允许你和附近的其他人购买材料。需要附近有营火。所有露营功能共享{1}小时冷却时间。", zhTW = "召喚一個材料機器人，你和其他人可向其購買材料。需要附近有營火。所有紮營道具有共用的{1}小時冷卻時間。" },
	["summons a repair bot that allows you and others nearby to buy reagents and repair gear"] = { ko = "자신과 주위의 다른 플레이어가 재료를 구매하거나 장비를 수리할 수 있는 수리 로봇을 소환합니다.", zhCN = "召唤一个修理机器人，允许你和附近的其他人购买材料和修理装备。", zhTW = "召喚修理機器人，可讓你和附近的其他人購買材料和修復裝備。" },
	["summons a repair bot that allows you and others nearby to buy reagents and repair gear. requires a campfire nearby"] = { ko = "자신과 주위의 다른 플레이어가 재료를 구매하거나 장비를 수리할 수 있는 수리 로봇을 소환합니다. 주위에 모닥불이 있어야 합니다.", zhCN = "召唤一个修理机器人，允许你和附近的其他人购买材料和修理装备。需要附近有营火。", zhTW = "召喚修理機器人，可讓你和附近的其他人購買材料和修復裝備。需要附近有營火。" },
	["summons a searing totem with # health at your feet for # sec that repeatedly attacks an enemy within # yards for # to # fire damage"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 불타는 토템을 소환하여 지속적으로 주위 {3}미터 반경 내의 적을 공격하여 {4}~{5}의 화염 피해를 입히게 합니다. {2}초 동안 지속됩니다.", zhCN = "在施法者身边召唤出一个生命值为{1}的灼热图腾，持续{2}秒。它可以频繁攻击半径{3}码范围内的某个敌人，每次对其造成{4}至{5}点火焰伤害。", zhTW = "在施法者身邊召喚出一個生命力為{1}的灼熱圖騰，持續{2}秒。它可以頻繁攻擊半徑{3}碼範圍內的某個敵人，每次對其造成{4}至{5}點火焰傷害。" },
	["summons a stoneclaw totem with # health at the feet of the caster for # sec that taunts creatures within # yards to attack it"] = { ko = "시전자의 위치에 주위 {3}미터 반경 내의 적을 도발하여 자신을 공격하도록 만드는 생명력 {1}의 돌발톱 토템을 소환합니다. {2}초 동안 지속됩니다.", zhCN = "在施法者身边召唤出一个生命值为{1}的石爪图腾。这个图腾可以吸引半径{3}码范围内的所有敌人来攻击它，持续{2}秒。", zhTW = "在施法者身邊召喚出一個生命力為{1}的石爪圖騰。這個圖騰可以吸引半徑{3}碼範圍內的所有敵人來攻擊它，持續{2}秒。" },
	["summons a stoneskin totem with # health at the feet of the caster"] = { zhCN = "在施法者脚下召唤一个拥有{1}点生命值的石肤图腾。" },
	["summons a stoneskin totem with # health at the feet of the caster. the totem protects party members within # yards, reducing physical damage taken by # lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 돌가죽 토템을 소환하여 주위 {2}미터 반경 내의 파티원이 받는 물리 피해를 4만큼 감소시킵니다. {4}분 동안 지속됩니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的石肤图腾。该图腾保护{2}码内的队伍成员，使其受到的物理伤害降低4点。持续{4}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的石甲圖騰。這個圖騰可以使半徑{2}碼範圍內的小隊成員所受到的物理傷害降低4點，持續{4}分鐘。" },
	["summons a strength of earth totem with # health at the feet of the caster. the totem increases the strength of party members within # yards by # lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 대지력 토템을 소환하여 주위 {2}미터 반경 내의 파티원의 힘을 7만큼 증가시킵니다. {4}분 동안 지속됩니다.", zhCN = "在施法者身边召唤出一个生命值为{1}的大地之力图腾。这个图腾可以使半径{2}码范围内所有小队成员的力量提高7，持续{4}分钟。", zhTW = "在施法者身邊召喚出一個生命力為{1}的大地之力圖騰。這個圖騰可以使半徑{2}碼範圍內所有小隊成員的力量提高7，持續{4}分鐘。" },
	["summons a succubus under the command of the warlock"] = { ko = "서큐버스를 소환하여 부립니다.", zhCN = "在术士身边召唤出一个魅魔。", zhTW = "召喚一個魅魔為術士作戰。" },
	["summons a tracking hound that will protect you for # min"] = { ko = "{1}분 동안 자신을 보호하는 사냥개를 소환합니다.", zhCN = "召唤一头追踪犬为你作战，持续{1}分钟。", zhTW = "召喚一隻追蹤犬保護你，持續{1}分鐘。" },
	["summons a tranquil air totem with # health at the feet of the caster"] = { zhCN = "在施法者身边召唤一个生命值为{1}点的宁静之风图腾。", zhTW = "在施法者身邊召喚一個生命力為{1}點的寧靜之風圖騰。" },
	["summons a tranquil air totem with # health at the feet of the caster. the totem reduces the threat caused by all party members within # yards by #%. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 평온의 토템을 소환하여 주위 {2}미터 반경 내 파티원의 위협 수준을 {3}%만큼 감소시킵니다. {4}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的宁静之风图腾。这个图腾可以使周围半径{2}码范围内的所有小队成员的威胁值降低{3}%。图腾持续{4}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的寧靜之風圖騰。這個圖騰可以使周圍半徑{2}碼範圍內的所有小隊成員的威脅值降低{3}%。圖騰持續{4}分鐘。" },
	["summons a tremor totem with # health at the feet of the caster that shakes the ground around it, removing fear, charm and sleep effects from party members within # yards"] = { zhCN = "在施法者身边召唤一个生命值为{1}点的战栗图腾，它会震动附近的地面，驱散半径{2}码范围内所有队友身上的恐惧、魅惑和催眠效果。", zhTW = "在施法者身邊召喚一個生命力為{1}點的戰慄圖騰，它會震動附近的地面，驅散半徑{2}碼範圍內所有隊友身上的恐懼、魅惑和催眠效果。" },
	["summons a tremor totem with # health at the feet of the caster that shakes the ground around it, removing fear, charm and sleep effects from party members within # yards. lasts # min"] = { ko = "시전자의 위치에 생명력 {1}의 진동의 토템을 소환합니다. 이 토템은 땅을 울려 주위 {2}미터 반경 내의 파티원에게 걸린 공포, 현혹, 수면 효과를 제거합니다. {3}분 동안 지속됩니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的战栗图腾，它会震动附近的地面，驱散半径{2}码范围内所有队友身上的恐惧、魅惑和催眠效果。持续{3}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的戰慄圖騰，它會震動附近的地面，驅散半徑{2}碼範圍內所有隊友身上的恐懼、魅惑和催眠效果。持續{3}分鐘。" },
	["summons a voidwalker under the command of the warlock"] = { ko = "보이드워커를 소환하여 부립니다.", zhCN = "召唤一个虚空行者为术士作战。", zhTW = "召喚一個虛空行者為術士作戰。" },
	["summons a warhorse, which serves as a mount"] = { ko = "군마를 소환하여 탈것으로 이용합니다.", zhCN = "召唤一匹军马作为你的坐骑。", zhTW = "召喚一匹軍馬作為你的坐騎。" },
	["summons a warhorse, which serves as a mount. speed is increased by #%"] = { ko = "군마를 소환하여 탈것으로 이용합니다. 이동 속도가 {1}%만큼 증가합니다.", zhCN = "召唤一匹军马作为你的坐骑。速度提高{1}%。", zhTW = "召喚一匹軍馬作為你的坐騎。速度提高{1}%。" },
	["summons a windfury totem with # health at the feet of the caster"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 질풍의 토템을 소환합니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的风怒图腾。", zhTW = "在施法者身邊召喚一個生命力為{1}點的風怒圖騰。" },
	["summons a windfury totem with # health at the feet of the caster. the totem enhances the melee attacks of all party members within # yards. each main hand hit has a #% chance of granting the attacker # extra attack with # extra melee attack power. lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 질풍의 토템을 소환합니다. 질풍의 토템은 {2}미터 내 모든 파티원의 근접 공격을 강화합니다. 이때 주무기로 공격을 적중시킬 때마다 공격자가 {3}%의 확률로 적에게 {5}의 추가 근접 전투력으로 {4}회의 추가 공격을 가합니다. {6}분 동안 지속됩니다.", zhCN = "在施法者脚下召唤一个拥有{1}点生命值的风怒图腾。该图腾会强化{2}码内所有队伍成员的近战攻击。每次主手命中都有{3}%的几率使攻击者额外攻击{4}次，且这些攻击获得{5}点额外近战攻击强度。持续{6}分钟。", zhTW = "在施法者身邊召喚一個生命力為{1}點的風怒圖騰。它可以強化半徑{2}碼範圍內的所有小隊成員的近戰攻擊。每次主手武器命中敵人時，都有{3}%的機率令攻擊者獲得{4}次額外攻擊機會，且該攻擊的近戰攻擊強度提高{5}點。持續{6}分鐘。" },
	["summons a windwall totem with # health at the feet of the caster. the totem protects party members within # yards, reducing ranged damage taken by # lasts # min"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 바람막이 토템을 소환하여 주위 {2}미터 반경 내에 있는 모든 파티원을 보호하여 원거리 무기로부터 입는 피해를 32만큼 감소시킵니다. {4}분 동안 지속됩니다.", zhCN = "在施法者身边召唤出一个生命值为{1}点的风墙图腾，使半径{2}码范围内的小队成员在被攻击时所受的远程伤害减少32点。持续{4}分钟。", zhTW = "在施法者身邊召喚出一個生命力為{1}點的風牆圖騰，使半徑{2}碼範圍內的小隊成員在被攻擊時所受的遠程傷害減少32點。持續{4}分鐘。" },
	["summons an earthbind totem with # health at the feet of the caster for # sec that slows the movement speed of enemies within # yards"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 속박의 토템을 소환하여 {2}초 동안 주위 {3}미터 반경 내에 있는 적의 이동 속도를 감소시킵니다.", zhCN = "在施法者身边召唤一个生命值为{1}点的地缚图腾，持续{2}秒。该图腾可以使它周围半径{3}码内的所有敌人的移动速度降低。", zhTW = "在施法者身邊召喚一個生命力為{1}點的地縛圖騰，持續{2}秒。該圖騰可以使它周圍半徑{3}碼內的所有敵人的移動速度降低。" },
	["summons an enchanted lute that allows you and others sitting nearby to gain # (below #) · # (below #) · # (below #) · # (below #) · # (below #) · # (below #) · # (above) armor, # (level #+) · # (level #+) · # (level #+) · # (level #+) · # (level #+) · # (level #+) increase to all stats, and # increase to all resistances, mutually exclusive with mark of the wild"] = { ko = "마력 깃든 류트를 소환해 자신과 주위에 앉은 다른 플레이어의 방어도를 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}({8}레벨 미만) · {9}({10}레벨 미만) · {11}({12}레벨 미만) · {13}(그 위)만큼, 모든 능력치를 {14}({15}레벨부터) · {16}({17}레벨부터) · {18}({19}레벨부터) · {20}({21}레벨부터) · {22}({23}레벨부터) · {24}({25}레벨부터)만큼, 모든 저항력을 {26}만큼 증가시킵니다. 야생의 징표와 겸용해서 사용할 수 없습니다.", zhCN = "召唤一把附魔的鲁特琴，使你和附近坐下的其他人获得{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（{8}级以下） · {9}（{10}级以下） · {11}（{12}级以下） · {13} （更高）点护甲值加成，{14}（{15}级起） · {16}（{17}级起） · {18}（{19}级起） · {20}（{21}级起） · {22}（{23}级起） · {24}（{25}级起）点所有属性加成，以及{26}点所有抗性加成，与野性印记不叠加。", zhTW = "召喚一把附魔魯特琴，使你和附近坐下的其他人獲得{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（{8}級以下） · {9}（{10}級以下） · {11}（{12}級以下） · {13} （更高）點護甲值加成，{14}（{15}級起） · {16}（{17}級起） · {18}（{19}級起） · {20}（{21}級起） · {22}（{23}級起） · {24}（{25}級起）點所有屬性加成，以及{26}點所有抗性加成，與野性印記不疊加。" },
	["summons an enchanted lute that allows you and others sitting nearby to gain # armor, # increase to all stats, and # increase to all resistances, mutually exclusive with mark of the wild"] = { ko = "마력 깃든 류트를 소환해 자신과 주위에 앉은 다른 플레이어의 방어도를 {1}만큼, 모든 능력치를 {2}만큼, 모든 저항력을 {3}만큼 증가시킵니다. 야생의 징표와 겸용해서 사용할 수 없습니다.", zhCN = "召唤一把附魔的鲁特琴，使你和附近坐下的其他人获得{1}点护甲值加成，{2}点所有属性加成，以及{3}点所有抗性加成，与野性印记不叠加。", zhTW = "召喚一把附魔魯特琴，使你和附近坐下的其他人獲得{1}點護甲值加成，{2}點所有屬性加成，以及{3}點所有抗性加成，與野性印記不疊加。" },
	["summons an explosive sheep which will charge at a nearby enemy and explode for # damage"] = { ko = "근처의 적에게 돌진하여 {1}의 피해를 주며 폭발하는 양 폭탄을 생성합니다.", zhCN = "召唤一只自爆绵羊，它会向附近的敌人冲锋，并在爆炸时造成{1}点伤害。", zhTW = "召喚一隻自爆綿羊衝向附近的敵人並自爆，造成{1}點傷害。" },
	["summons an explosive sheep which will charge at a nearby enemy and explode for # damage. lasts for # min or until it explodes"] = { ko = "근처의 적에게 돌진하여 {1}의 피해를 주며 폭발하는 양 폭탄을 생성합니다. {2}분이 지나거나 폭발할 때까지 지속됩니다.", zhCN = "召唤一只自爆绵羊，它会向附近的敌人冲锋，并在爆炸时造成{1}点伤害。持续{2}分钟或直到它爆炸为止。", zhTW = "召喚一隻自爆綿羊衝向附近的敵人並自爆，造成{1}點傷害。綿羊自召喚出來後最多存在{2}分鐘。" },
	["summons an eye of kilrogg and binds your vision to it"] = { ko = "킬로그의 눈을 소환하여 정신 집중을 통해 그 눈으로 세상을 볼 수 있습니다.", zhCN = "召唤一颗基尔罗格之眼，并让你以它的视角观察世界。", zhTW = "召喚一顆基爾羅格之眼，並讓你以它的視角觀察世界。" },
	["summons an eye of kilrogg and binds your vision to it. the eye moves quickly but is very fragile"] = { ko = "킬로그의 눈을 소환하여 정신 집중을 통해 그 눈으로 세상을 볼 수 있습니다. 눈은 매우 빠르지만 공격을 받으면 소멸되기 쉽습니다.", zhCN = "召唤一颗基尔罗格之眼，并让你以它的视角观察世界。基尔罗格之眼速度很快，但也非常脆弱。", zhTW = "召喚一顆基爾羅格之眼，並讓你以它的視角觀察世界。基爾羅格之眼的移動速度很快，但卻非常脆弱。" },
	["summons an immobile sentry totem with # health at your feet for # min that allows vision of nearby area and warns of enemies that attack it. right-click on buff to switch back and forth between totem sight and shaman sight"] = { ko = "시전자의 위치에 {1}의 생명력을 지닌 감시의 토템을 소환하여 주위의 시야를 보여주거나 토템을 공격하는 적을 경고하게 합니다. 활성된 아이콘에 오른쪽 버튼을 클릭하면 토템의 시야와 시전자의 시야를 전환할 수 있습니다. {2}분 동안 지속됩니다.", zhCN = "在你的脚下召唤一个拥有{1}点生命值、无法移动的岗哨图腾，持续{2}分钟。该图腾可提供附近区域的视野，并在有敌人攻击它时发出警报。右键点击增益效果，可在图腾视角和萨满祭司视角之间切换。", zhTW = "在你身邊召喚一個生命力為{1}點的固定崗哨圖騰，持續{2}分鐘。該圖騰可以監視附近的區域，並在受到攻擊時發出警報。右鍵點擊該技能的狀態圖示可以在薩滿視角和圖騰視角之間切換。" },
	["summons an imp under the command of the warlock"] = { ko = "임프를 소환하여 부립니다.", zhCN = "召唤一个小鬼为术士作战。", zhTW = "召喚一個小鬼為術士作戰。" },
	["summons an incubus under the command of the warlock"] = { ko = "인큐버스를 소환하여 부립니다.", zhCN = "在术士身边召唤出一个夜魔。", zhTW = "召喚一個夢魔為術士作戰。" },
	["summons your pet to you"] = { ko = "길들인 야수를 소환합니다.", zhCN = "召唤你的宠物。", zhTW = "召喚你的寵物。" },
	["sunders the target's armor, reducing it by # per sunder armor and causes a high amount of threat. can be applied up to # times. lasts # sec"] = { ko = "적의 방어구를 손상시켜 매 가르기마다 방어도를 {1}만큼 감소시킵니다. 위협 수준이 크게 증가합니다. 최대 {2}번까지 중복될 수 있습니다. {3}초 동안 지속됩니다.", zhCN = "击破目标的护甲，每次破甲攻击都会使其护甲值降低{1}点，同时造成大量的威胁，最多可累加{2}次，持续{3}秒。", zhTW = "擊破目標的護甲，每次破甲攻擊都會使其護甲值降低{1}點，同時造成大量的威脅，最多可累加{2}次，持續{3}秒。" },
	["surrounds the target in a shield of fire"] = { ko = "대상을 화염 보호막으로 감쌉니다.", zhCN = "使目标被火焰之盾包围。", zhTW = "使目標被一面火焰之盾包圍。" },
	["surrounds the target in a shield of fire. every strike against the target causes # fire damage to the attacker. lasts # min. your pet cannot cast fire shield on itself"] = { ko = "대상을 화염 보호막으로 감쌉니다. 이 대상을 공격할 때마다 {1}의 화염 피해를 받습니다. {2}분 동안 지속됩니다. 소환수는 자기 자신에게 화염 보호막을 시전하지 못합니다.", zhCN = "使目标被火焰之盾包围。每次击中目标都会使攻击者受到{1}点火焰伤害。持续{2}分钟。你的宠物无法对自身施放火焰之盾。", zhTW = "使目標被一面火焰之盾包圍。任何使用近戰武器擊中被保護者的敵人都會受到{1}點火焰傷害。護盾持續{2}分鐘。你的寵物不能對自己施放火焰之盾。" },
	["swim speed increased by #%"] = { ko = "수영 속도가 {1}%만큼 증가합니다.", zhCN = "游泳速度提高{1}%。", zhTW = "游泳速度提高{1}%。" },
	["swipe # nearby enemies, inflicting # damage"] = { ko = "주위 적 {1}명을 휘둘러 공격하여 {2}의 피해를 입힙니다.", zhCN = "攻击附近的{1}个敌人，对它们造成{2}点伤害。", zhTW = "攻擊附近的{1}個敵人，對它們造成{2}點傷害。" },
	["sword: your successful melee"] = { zhCN = "剑：你成功的近战", zhTW = "劍：你成功的近戰" },
	["tactical mastery lets you retain up to an additional # rage when you change stances"] = { ko = "전술 숙련의 효과로 태세를 변경할 때 최대 {1}의 분노가 추가로 유지됩니다.", zhCN = "战术掌握使你在改变姿态时最多额外保留{1}点怒气。", zhTW = "戰術專精讓你在改變姿態的時候，可以額外保留最多{1}點怒氣。" },
	["taints the felhunter's blood for # min"] = { ko = "{1}분 동안 지옥사냥개의 피를 오염시킵니다.", zhCN = "恶魔的力量玷污地狱猎犬的血液，持续{1}分钟。", zhTW = "惡魔的力量玷污地獄獵犬的血液，持續{1}分鐘。" },
	["taints the felhunter's blood for # min. when the felhunter is hit with a melee attack, the attacker will lose # melee attack power for # sec. stacks up to # times on a single target"] = { ko = "{1}분 동안 지옥사냥개의 피를 오염시킵니다. 지옥사냥개가 근접 공격을 받으면 공격자는 {3}초 동안 {2}의 근접 전투력을 상실합니다. 효과는 대상마다 {4}번까지 중복될 수 있습니다.", zhCN = "恶魔的力量玷污地狱猎犬的血液，持续{1}分钟。如果它被近战攻击打中，则攻击者会损失{2}点近战攻击强度，持续{3}秒。腐坏之血的效果可以对单一目标叠加{4}次。", zhTW = "惡魔的力量玷污地獄獵犬的血液，持續{1}分鐘。如果它被近戰攻擊打中，則攻擊者會損失{2}近戰攻擊強度，持續{3}秒。腐壞之血的效果可以對單一目標疊加{4}次。" },
	["take direct control of your pet and see through its eyes for # min"] = { ko = "{1}분 동안 자신의 야수의 눈을 통해 세상을 보고 직접 조종할 수 있습니다.", zhCN = "直接控制你的宠物，并以它的视角行动，持续{1}分钟。", zhTW = "直接控制你的寵物，並以它的視角行動，持續{1}分鐘。" },
	["target"] = { zhCN = "攻击。", zhTW = "攻擊。" },
	["target is cured of bleeds up to level #"] = { ko = "최대 {1} 레벨의 출혈을 치료합니다.", zhCN = "解除目标身上的流血效果，最高可解除{1}级的毒药。", zhTW = "解除目標身上的流血效果，最高可解除{1}級的毒藥。" },
	["target is cured of bleeds up to level # not usable in combat"] = { ko = "최대 30 레벨의 출혈을 치료합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "解除目标身上的流血效果，最高可解除30级的毒药。不能在战斗中使用。", zhTW = "解除目標身上的流血效果，最高可解除30級的毒藥。不能在戰鬥中使用。" },
	["target is cured of diseases up to level #"] = { ko = "최대 {1} 레벨의 질병을 치료합니다.", zhCN = "解除目标身上的疾病效果，最高可解除{1}级的毒药。", zhTW = "解除目標身上的疾病效果，最高可解除{1}級的毒藥。" },
	["target is cured of diseases up to level # not usable in combat"] = { ko = "최대 25 레벨의 질병을 치료합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "解除目标身上的疾病效果，最高可解除25级的毒药。不能在战斗中使用。", zhTW = "解除目標身上的疾病效果，最高可解除25級的毒藥。不能在戰鬥中使用。" },
	["target is cured of poisons up to level #"] = { ko = "최대 {1} 레벨의 독을 치료합니다.", zhCN = "解除目标身上的中毒效果，最高可解除{1}级的毒药。", zhTW = "解除目標身上的中毒效果，最高可解除{1}級的毒藥。" },
	["targets can only be affected by this effect once every # min"] = { ko = "{1}분에 한 번씩만 이 효과의 대상으로 지정할 수 있습니다.", zhCN = "目标每{1}分钟只能受到一次该效果的影响。", zhTW = "目標每{1}分鐘只能受到一次該效果的影響。" },
	["targets in a cone in front of the caster take # to # frost damage and are slowed by #% for # sec"] = { ko = "시전자 전방에 냉기의 돌풍을 내뿜어 {1}에서 {2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "施法者面前锥形范围内的目标受到{1}至{2}点冰霜伤害，移动速度降低{3}%，持续{4}秒。", zhTW = "施法者面前錐形範圍內的目標將受到{1}點到{2}點冰霜傷害，移動速度降低{3}%，持續{4}秒。" },
	["targets that die while devouring plague is active spreads it, jumping to a nearby enemy within # yds for the remaining duration"] = { ko = "파멸의 역병이 걸려 있는 동안 대상이 죽으면 {1}미터 내의 가까운 적에게 옮겨가 남은 지속시간 동안 유지됩니다." },
	["taunt the target, increasing the likelihood the creature will focus attacks on you"] = { ko = "대상을 도발하여 대상이 자신에게 공격을 집중할 확률을 증가시킵니다.", zhCN = "嘲讽目标，使其更有可能将你作为主要的攻击对象。", zhTW = "嘲諷目標，使其更有可能將你作為主要的攻擊對象。" },
	["taunts all enemies within # yards, increasing the chance that they will attack the voidwalker"] = { ko = "주위 {1}미터 반경 내의 모든 적을 도발하여 보이드워커를 공격할 확률을 증가시킵니다.", zhCN = "嘲讽半径{1}码范围内的所有敌人，使它们有更高的几率转而攻击虚空行者。", zhTW = "嘲諷附近{1}碼內的所有敵人，使它們有更高的機率轉而攻擊虛空行者。" },
	["taunts all enemies within # yards, increasing the chance that they will attack the voidwalker. more effective than suffering (rank #)"] = { ko = "주위 {1}미터 반경 내의 모든 적을 도발하여 보이드워커를 공격할 확률을 증가시킵니다. {2}레벨 고통 보다 효과가 높습니다.", zhCN = "嘲讽半径{1}码范围内的所有敌人，使它们有更高的几率转而攻击虚空行者。比受难（等级 {2}）更有效。", zhTW = "嘲諷附近{1}碼內的所有敵人，使它們有更高的機率轉而攻擊虛空行者。比受難（等級 {2}）更有效。" },
	["taunts the creature, increasing the chance that it will attack the voidwalker"] = { ko = "대상을 괴롭혀 자신을 공격할 확률을 증가시킵니다.", zhCN = "嘲讽目标，使其有更高的几率转而攻击虚空行者。", zhTW = "嘲諷目標，使其有更高的機率轉而攻擊虛空行者。" },
	["taunts the creature, increasing the chance that it will attack the voidwalker. more effective than torment (rank #)"] = { ko = "대상을 괴롭혀 자신을 공격할 확률을 증가시킵니다. {1}레벨 고문보다 효과가 좋습니다.", zhCN = "嘲讽目标，使其有更高的几率转而攻击虚空行者。比折磨（等级 {1}）更有效。", zhTW = "嘲諷目標，使其有更高的機率轉而攻擊虛空行者。比折磨（等級 {1}）更有效。" },
	["taunts the target to attack you, but has no effect if the target is already attacking you"] = { ko = "적을 도발하여 자신을 공격하도록 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다.", zhCN = "嘲讽目标，使其向你发起攻击，但是对已经在攻击你的目标无效。", zhTW = "嘲諷目標，使其向你發起攻擊，但對已經攻擊你的目標無效。" },
	["tears the target apart from within, inflicting # shadow damage every # sec and increasing the damage they take from your other shadow damage over time effects by #% for # sec"] = { ko = "대상을 내부로부터 찢어 {4}초 동안 {2}초마다 {1}의 암흑 피해를 입히고, 대상이 자신의 다른 암흑 지속 피해 효과로 입는 피해를 {3}%만큼 증가시킵니다.", zhCN = "从内部撕裂目标，每{2}秒造成{1}点暗影伤害，并使其从你的其他持续性暗影伤害效果中受到的伤害提高{3}%。持续{4}秒。", zhTW = "從內部撕裂目標，每{2}秒造成{1}點暗影傷害，並使其從你的其他持續性暗影傷害效果中受到的傷害提高{3}%。持續{4}秒。" },
	["technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering"] = { ko = "고블린과 노움 기계공학이 광기 어린 방식으로 결합된 장치인 터라, 기술적인 문제가 발생할 확률이 높습니다.", zhCN = "这种地精与侏儒工程学疯狂结合的产物有很高的几率发生技术故障。", zhTW = "但作為哥布林和地精工程學的共同結晶，發生技術故障的機率極高。" },
	["teleport forward # yds"] = { ko = "전방 {1}미터로 순간이동합니다.", zhCN = "向前传送{1}码。", zhTW = "向前傳送{1}碼。" },
	["teleports the caster # yards forward, unless something is in the way"] = { ko = "시전자를 기절시키거나 이동 불가 상태로 만드는 모든 것에서 벗어나 {1}미터 전방으로 순간이동합니다.", zhCN = "将施法者向前传送{1}码，除非途中有障碍物。" },
	["teleports the caster # yards forward, unless something is in the way. also frees the caster from stuns and immobilizes"] = { ko = "시전자를 기절시키거나 이동 불가 상태로 만드는 모든 것에서 벗어나 {1}미터 전방으로 순간이동합니다. 전방에는 장애물이 없어야 합니다.", zhCN = "将施法者向前传送{1}码，除非途中有障碍物。同时解除施法者的昏迷和定身效果。", zhTW = "將施法者傳送到正前方{1}碼的位置，路線上有阻擋物則會停止，傳送可以解除施法者身上的昏迷和無法移動的效果。" },
	["teleports the caster to dalaran"] = { ko = "시전자를 달라란으로 순간이동시킵니다.", zhCN = "将施法者传送到达拉然。", zhTW = "將施法者傳送至達拉然。" },
	["teleports the caster to darnassus"] = { ko = "시전자를 다르나서스로 순간이동시킵니다.", zhCN = "将施法者传送到达纳苏斯。", zhTW = "將施法者傳送到達納蘇斯。" },
	["teleports the caster to ironforge"] = { ko = "시전자를 아이언포지로 순간이동시킵니다.", zhCN = "将施法者传送到铁炉堡。", zhTW = "將施法者傳送到鐵爐堡。" },
	["teleports the caster to orgrimmar"] = { ko = "시전자를 오그리마로 순간이동시킵니다.", zhCN = "将施法者传送到奥格瑞玛。", zhTW = "將施法者傳送到奧格瑪。" },
	["teleports the caster to stormwind"] = { ko = "시전자를 스톰윈드로 순간이동시킵니다.", zhCN = "将施法者传送到暴风城。", zhTW = "將施法者傳送到暴風城。" },
	["teleports the caster to the moonglade"] = { ko = "시전자를 달의 숲으로 순간이동시킵니다.", zhCN = "将施法者传送到月光林地。", zhTW = "將施法者傳送到月光林地。" },
	["teleports the caster to thunder bluff"] = { ko = "시전자를 썬더 블러프로 순간이동시킵니다.", zhCN = "将施法者传送到雷霆崖。", zhTW = "將施法者傳送到雷霆崖。" },
	["teleports the caster to undercity"] = { ko = "시전자를 언더시티로 순간이동시킵니다.", zhCN = "将施法者传送到幽暗城。", zhTW = "將施法者傳送到幽暗城。" },
	["tenderize the target, increasing physical damage taken by # for # min"] = { ko = "대상을 연하게 만들어 {1}분 동안 받는 물리 피해를 {2}만큼 증가시킵니다.", zhCN = "软化目标，使其受到的物理伤害提高{1}点，持续{2}分钟。", zhTW = "使目標變得軟嫩，受到的物理傷害提高{1}點，持續{2}分鐘。" },
	["the act of shapeshifting frees the caster of polymorph and movement impairing effects"] = { ko = "변신을 하게 되면 변이와 이동 방해 효과에서 벗어날 수 있습니다.", zhCN = "变形可解除施法者身上的变形术和移动限制效果。", zhTW = "變形可解除施法者身上的變形術和移動限制效果。" },
	["the amount healed is applied quickly at first, and slows down as wild growth reaches its full duration"] = { ko = "처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다.", zhTW = "野性痊癒的恢復速度在起步時最快，並且隨時間而減緩，直到結束為止。" },
	["the caster gains #% of the damage caused in health"] = { ko = "시전자는 입힌 피해의 {1}%만큼 생명력을 회복합니다." },
	["the caster is surrounded by # balls of lightning"] = { ko = "{1}개의 번개 구슬이 시전자의 주위에 머무릅니다." },
	["the caster is surrounded by # balls of lightning. when a spell, melee or ranged attack hits the caster, the attacker will be struck for # nature damage. this expends one lightning ball. only one ball will fire every few seconds. lasts # min"] = { ko = "{1}개의 번개 구슬이 시전자의 주위에 머무릅니다. 만약 시전자에게 주문이나 근접 또는 원거리 공격을 시도할 경우 공격자는 {2}의 자연 피해를 입게 됩니다. 매번 피해를 줄 때마다 구슬이 하나씩 사라집니다. 번개 구슬이 폭발하면 다시 폭발하기까지 일정 시간이 필요합니다. {3}분 동안 지속됩니다.", zhCN = "施法者被{1}个闪电球环绕。如果施法者受到了近战、远程或法术伤害，则攻击者会受到{2}点自然伤害，并会消耗掉一个闪电球。一个攻击者在短期内只会受到一次反噬伤害。持续{3}分钟。", zhTW = "施法者被{1}個閃電球環繞。如果施法者受到了近戰、遠程或法術傷害，則攻擊者會受到{2}點自然傷害，並會消耗掉一個閃電球。一個攻擊者在短期內只會受到一次反噬傷害。持續{3}分鐘。" },
	["the caster is surrounded by # globes of water"] = { zhCN = "施法者被{1}个水球环绕。" },
	["the caster is surrounded by # globes of water. when a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, #% of maximum mana is restored to the caster, expending one water globe. only one globe will activate every few seconds. lasts # min"] = { ko = "{1}개의 물방울이 시전자의 주위에 머무릅니다. 시전자가 주문이나 근접 또는 원거리 공격에 적중당하거나 시전자의 치유 주문이 극대화 효과를 발휘하면, 시전자는 물방울로부터 최대 마나의 {2}%를 흡수합니다. 마나를 흡수할 때마다 물방울이 하나씩 사라집니다. 물방울이 하나 사라지면 다른 물방울이 효력을 발휘하기까지 일정 시간이 필요합니다. {3}분 동안 지속됩니다.", zhCN = "施法者被{1}个水球环绕。当法术、近战或远程攻击命中施法者，或施法者的治疗法术造成爆击时，恢复最大法力值的{2}%，并消耗一个水球。每隔数秒只会有一个水球被激活。持续{3}分钟。", zhTW = "施法者被{1}個水球環繞。如果施法者受到法術、近戰或遠程傷害，或施法者的其中一個治療法術造成極效治療時，則施法者會恢復法力上限的{2}%，並消耗一個水球。水球的效果每數秒內只能啟動一次，持續{3}分鐘。" },
	["the caster is surrounded by shadows"] = { ko = "시전자가 어둠에 둘러쌓이게 됩니다.", zhCN = "施法者被暗影笼罩。", zhTW = "施法者被暗影籠罩。" },
	["the caster is surrounded by shadows. when a spell, melee or ranged attack hits the caster, the attacker will be struck for # shadow damage. attackers can only be damaged once every few seconds. this damage causes no threat. # charges. lasts # min"] = { ko = "시전자가 어둠에 둘러쌓이게 됩니다. 주문이나 근접 또는 원거리 공격을 받게 되면 공격자는 {1}의 암흑 피해를 입게 됩니다. 이로 인한 피해는 위협 수준을 발생시키지 않습니다. 공격자는 몇초마다 한번씩만 피해를 입게 됩니다. {2}회 사용가능하며 {3}분 동안 지속됩니다.", zhCN = "施法者被暗影笼罩。如果施法者受到了法术、近战或远程伤害，则攻击者会受到{1}点暗影伤害。一个攻击者在短期内只会受到一次反噬伤害。这种伤害不会造成威胁值。可使用{2}次，持续{3}分钟。", zhTW = "施法者被暗影籠罩。如果施法者受到了近戰或遠程傷害，則攻擊者會受到{1}點暗影傷害。一個攻擊者在短期內只會受到一次反噬傷害。此傷害不造成威脅。可使用{2}次，持續{3}分鐘。" },
	["the caster is then surrounded by a barrier of electricity for # min"] = { ko = "공격 후 시전자는 {1}분 동안 전기의 벽에 둘러싸입니다.", zhCN = "随后，施法者会被一道电流屏障包围，持续{1}分钟。", zhTW = "施法者受閃電屏障保護，持續{1}分鐘。" },
	["the caster lets out a psychic scream, causing # enemies within # yards to flee for # sec"] = { ko = "영혼의 절규를 부르짖어 주위 {2}미터 반경 내의 적 {1}명이 {3}초 동안 달아나게 만듭니다.", zhCN = "施法者发出心灵尖啸，使附近半径{2}码范围内的{1}个敌人逃跑，持续{3}秒。", zhTW = "施法者發出心靈尖嘯，使附近半徑{2}碼範圍內的{1}個敵人逃跑，持續{3}秒。" },
	["the caster lets out a psychic scream, causing # enemies within # yards to flee for # sec. damage caused may interrupt the effect"] = { ko = "영혼의 절규를 부르짖어 주위 {2}미터 반경 내의 적 {1}명이 {3}초 동안 달아나게 만듭니다. 대상이 피해를 입게 되면 효과가 취소됩니다.", zhCN = "施法者发出心灵尖啸，使附近半径{2}码范围内的{1}个敌人逃跑，持续{3}秒。逃跑中的目标受到伤害则可能中断此效果。", zhTW = "施法者發出心靈尖嘯，使附近半徑{2}碼範圍內的{1}個敵人逃跑，持續{3}秒。逃跑中的目標受到傷害則可能中斷此效果。" },
	["the clearcasting state reduces the mana cost of your next damage spell by #%"] = { ko = "정신 집중 상태에서는 다음 공격 주문의 마나 소비량이 {1}%만큼 감소됩니다.", zhCN = "这个状态可以使你的下一个伤害性法术所消耗的法力值减少{1}%。", zhTW = "這個狀態可以使你的下一個傷害性法術所消耗的法力降低{1}%。" },
	["the damage caused by eye for an eye will not exceed #% of the paladin's total health"] = { ko = "눈에는 눈 특성으로 인한 피해는 성기사 최대 생명력의 {1}%를 초과하지 않습니다.", zhCN = "以眼还眼造成的伤害不会超过圣骑士总生命值的{1}%。" },
	["the doomguard must be immediately subjugated or it will attack the ritual participants"] = { ko = "파멸의 수호병을 즉시 예속하지 않으면 의식에 참가한 사람을 공격합니다.", zhTW = "務必立刻制伏該末日守衛，否則它就會攻擊儀式參與者。" },
	["the druid is considered in combat for the duration"] = { zhCN = "持续期间，德鲁伊被视为处于战斗中。", zhTW = "效果作用期間，德魯伊會被視為在戰鬥中。" },
	["the druid roars, decreasing nearby enemies' melee attack power by #"] = { ko = "주위 적의 근접 전투력을 {1}만큼 감소시킵니다." },
	["the druid roars, decreasing nearby enemies' melee attack power by # lasts # sec"] = { ko = "주위 적의 근접 전투력을 46만큼 감소시킵니다. {2}초 동안 지속됩니다.", zhCN = "德鲁伊发出咆哮，使附近所有敌人的近战攻击强度降低46点，持续{2}秒。", zhTW = "德魯伊發出咆哮，使附近所有敵人的近戰攻擊強度降低46，持續{2}秒。" },
	["the effect is canceled if any demon is summoned"] = { ko = "이 효과는 2시간 동안 지속되며 소환수를 소환하면 사라집니다.", zhCN = "如果召唤任何恶魔，该效果会被取消。", zhTW = "如果在此期間你召喚任意一個惡魔，該效果就會被取消。" },
	["the enemy target is swarmed by insects, decreasing their chance to hit with attacks by #% and causing # nature damage over # sec"] = { ko = "적이 곤충 떼에게 둘러싸여 공격 적중률이 {1}%만큼 감소되고 {3}초에 걸쳐 총 {2}의 자연 피해를 입습니다.", zhCN = "敌人被飞虫围绕，攻击命中几率降低{1}%，在{3}秒内受到总计{2}点自然伤害。", zhTW = "敵人被飛蟲圍繞，攻擊的命中機率降低{1}%，並在{3}秒內受到總計{2}點自然傷害。" },
	["the eye moves quickly but is very fragile"] = { ko = "눈은 매우 빠르지만 공격을 받으면 소멸되기 쉽습니다.", zhCN = "基尔罗格之眼速度很快，但也非常脆弱。", zhTW = "基爾羅格之眼的移動速度很快，但卻非常脆弱。" },
	["the field lasts for up to # sec after moving"] = { ko = "이동 후에도 은신 영역은 최대 {1} 동안 지속됩니다.", zhCN = "移动后，该力场最多持续{1}秒。", zhTW = "此力場在移動後可持續最多{1}秒。" },
	["the first # enemies who enter the area will take an additional # damage over # sec"] = { ko = "그 지역에 처음 들어오는 적 {1}명은 {3}초에 걸쳐 {2}의 피해를 추가로 입습니다.", zhCN = "最先进入该区域的{1}个敌人会在{3}秒内额外受到{2}点伤害。", zhTW = "最先進入該區域的{1}個敵人會在{3}秒內額外受到{2}點傷害。" },
	["the focused casting effect prevents you from losing casting time when taking damage and increases your resistance to interrupt effects by #%"] = { ko = "집중력의 효과를 받을 땐 받는 피해로 인해 시전 시간이 지연되지 않으며 방해 효과에 대한 저항이 {1}%만큼 증가합니다.", zhCN = "专注施法效果可以让你在施法时不会因为受到伤害而延长施法时间，且令你抵抗打断效果的几率提高{1}%。", zhTW = "專注施法效果可防止因受到傷害而損失施法時間，並使你對中斷效果的抗性提高{1}%。" },
	["the hunter and all party and raid members within # yards take on the aspect of the wild, increasing nature resistance by #"] = { ko = "사냥꾼과 {1}미터 반경 내에 있는 파티원과 공격대원은 야생의 상을 취해 자연 저항력이 {2}만큼 증가합니다.", zhCN = "猎人及{1}码内所有队伍和团队成员获得野性守护，使自然抗性提高{2}点。", zhTW = "獵人和半徑{1}碼範圍內的所有隊伍和團隊成員均獲得野性守護，使自然抗性提高{2}點。" },
	["the hunter and all party and raid members within # yards take on the aspect of the wild, increasing nature resistance by # only one aspect can be active at a time"] = { ko = "사냥꾼과 {1}미터 반경 내에 있는 파티원과 공격대원은 야생의 상을 취해 자연 저항력이 45만큼 증가합니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人及{1}码内所有队伍和团队成员获得野性守护，使自然抗性提高45点。同一时间只能激活一种守护。", zhTW = "獵人和半徑{1}碼範圍內的所有隊伍和團隊成員均獲得野性守護，使自然抗性提高45點。獵人在同一時間內只能啟動一種守護。" },
	["the hunter and group members within # yards take on the aspects of a pack of cheetahs, increasing movement speed by #%"] = { ko = "사냥꾼과 {1}미터 반경 내에 있는 사냥꾼의 파티원은 치타의 상을 취해 이동 속도가 {2}%만큼 증가합니다.", zhCN = "猎人和他周围半径{1}码范围内的队友均获得豹群守护的效果，使移动速度提高{2}%。", zhTW = "獵人和{1}碼內的隊友均獲得豹群守護，使移動速度提高{2}%。" },
	["the hunter and group members within # yards take on the aspects of a pack of cheetahs, increasing movement speed by #%. if a pack member takes damage, they will be dazed for # sec. only one aspect can be active at a time"] = { ko = "사냥꾼과 {1}미터 반경 내에 있는 사냥꾼의 파티원은 치타의 상을 취해 이동 속도가 {2}%만큼 증가합니다. 이 동안 파티원이 피해를 입게 되면 {3}초 동안 멍해지게 됩니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人和他周围半径{1}码范围内的队友均获得豹群守护的效果，使移动速度提高{2}%。如果任何一个队友受到伤害，则全队都会眩晕{3}秒。一个猎人在同一时间内只能激活一种守护。", zhTW = "獵人和{1}碼內的隊友均獲得豹群守護，使移動速度提高{2}%。如果任何一個隊友受到傷害，則全隊都會眩暈{3}秒。一個獵人在同一時間內只能啟動一種守護。" },
	["the hunter takes on the aspects of a beast, becoming untrackable and increasing melee attack power by #"] = { zhCN = "猎人获得了野兽的守护，变得无法被追踪，并使近战攻击强度提高{1}点。", zhTW = "獵人獲得野獸守護，變得無法被追蹤且近戰攻擊強度提高{1}點。" },
	["the hunter takes on the aspects of a beast, becoming untrackable and increasing melee attack power by # only one aspect can be active at a time"] = { ko = "야수의 상을 취합니다. 추적이 불가능해지고 근접 전투력이 50만큼 증가합니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人获得了野兽的守护，变得无法被追踪，并使近战攻击强度提高50点。同一时间内只能激活一种守护。", zhTW = "獵人獲得野獸守護，變得無法被追蹤且近戰攻擊強度提高50點。獵人同時只能啟動一種守護效果。" },
	["the hunter takes on the aspects of a cheetah, increasing movement speed by #%"] = { ko = "사냥꾼이 치타의 상을 취해 이동 속도가 {1}%만큼 증가합니다.", zhCN = "猎人获得猎豹守护，使移动速度提高{1}%。", zhTW = "獵人獲得獵豹守護，使移動速度提高{1}%。" },
	["the hunter takes on the aspects of a cheetah, increasing movement speed by #%. if the hunter takes damage, he will be dazed for # sec. only one aspect can be active at a time"] = { ko = "사냥꾼이 치타의 상을 취해 이동 속도가 {1}%만큼 증가합니다. 이 동안 피해를 입게 되면 {2}초 동안 멍해지게 됩니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人获得猎豹守护，使移动速度提高{1}%。如果猎人受到伤害，则他会眩晕{2}秒。一个猎人在同一时间内只能激活一种守护。", zhTW = "獵人獲得獵豹守護，使移動速度提高{1}%。如果獵人受到傷害，則他會眩暈{2}秒。一個獵人在同一時間內只能啟動一種守護。" },
	["the hunter takes on the aspects of a hawk, increasing ranged attack power by #"] = { ko = "사냥꾼이 매의 상을 취해 원거리 전투력을 {1}만큼 증가시킵니다.", zhCN = "猎人获得雄鹰守护，使远程攻击强度提高{1}点。", zhTW = "獵人獲得雄鷹守護，使遠程攻擊強度提高{1}點。" },
	["the hunter takes on the aspects of a hawk, increasing ranged attack power by # only one aspect can be active at a time"] = { ko = "사냥꾼이 매의 상을 취해 원거리 전투력을 20만큼 증가시킵니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人获得雄鹰守护，使远程攻击强度提高20点。一个猎人在同一时间内只能激活一种守护。", zhTW = "獵人獲得雄鷹守護，使遠程攻擊強度提高20點。一個獵人在同一時間內只能啟動一種守護。" },
	["the hunter takes on the aspects of a monkey, increasing chance to dodge by #%"] = { ko = "사냥꾼이 원숭이의 상을 취해 회피율이 {1}%만큼 향상됩니다.", zhCN = "猎人获得灵猴守护，使躲闪几率提高{1}%。", zhTW = "獵人獲得靈猴守護，使躲閃機率提高{1}%。" },
	["the hunter takes on the aspects of a monkey, increasing chance to dodge by #%. only one aspect can be active at a time"] = { ko = "사냥꾼이 원숭이의 상을 취해 회피율이 {1}%만큼 향상됩니다. 한 번에 한 상만 취할 수 있습니다.", zhCN = "猎人获得灵猴守护，使躲闪几率提高{1}%。一个猎人在同一时间内只能激活一种守护。", zhTW = "獵人獲得靈猴守護，使躲閃機率提高{1}%。一個獵人在同一時間內只能啟動一種守護。" },
	["the next # melee attack that strikes the caster will afflict the attacker with entangling roots (rank #)"] = { ko = "시전자가 다음 {1}회의 근접 공격을 받는 동안 공격자에게 휘감는 뿌리({2} 레벨)를 겁니다.", zhCN = "接下来击中施法者的{1}次近战攻击会使攻击者受到纠缠根须（等级 {2}）的影响。", zhTW = "接下來受到近戰攻擊時，施法者會對攻擊者施加糾纏根鬚（等級{1}），最多觸發{2}次。" },
	["the next # melee attack that strikes the caster will afflict the attacker with entangling roots (rank #). castable while shapeshifted. lasts # sec"] = { ko = "시전자가 다음 {1}회의 근접 공격을 받는 동안 공격자에게 휘감는 뿌리({2} 레벨)를 겁니다. 변신한 상태일 때도 시전할 수 있습니다. {3}초 동안 지속됩니다.", zhCN = "接下来击中施法者的{1}次近战攻击会使攻击者受到纠缠根须（等级 {2}）的影响。可在变形状态下施放。持续{3}秒。", zhTW = "接下來受到近戰攻擊時，施法者會對攻擊者施加糾纏根鬚（等級{1}），最多觸發{2}次。可在變形時施放。持續{3}秒。" },
	["the next fear effect used against the target will fail, using up the ward"] = { ko = "해당 대상에게 적용되는 다음 공포 효과는 실패하게 됩니다.", zhCN = "下一次对该目标施放的恐惧效果会失败并消耗结界。", zhTW = "下一次對該目標施放的恐懼效果會失敗並消耗結界。" },
	["the next melee attack against the caster will cause # shadow damage and reduce the attacker's melee attack power by # for # min"] = { ko = "다음 근접 공격을 받을 경우 공격자에게 {1}의 암흑 피해를 입히고 {3}분 동안 공격자의 근접 전투력을 {2}만큼 감소시킵니다.", zhCN = "对施法者进行的下一次近战攻击会使攻击者受到{1}点暗影伤害，并使其近战攻击强度降低{2}点，持续{3}分钟。", zhTW = "施法者受到下一次近戰攻擊時，會對攻擊者造成{1}點暗影傷害，並使其近戰攻擊強度降低{2}點，持續{3}分鐘。" },
	["the next melee attack on the caster will cause # shadow damage and reduce the attacker's melee attack power by the attacker by # for # min"] = { ko = "다음 근접 공격을 받을 경우 공격자에게 {1}의 암흑 피해를 입히고 {3}분 동안 공격자의 근접 전투력을 {2}만큼 감소시킵니다.", zhCN = "对施法者进行的下一次近战攻击会使攻击者受到{1}点暗影伤害，并使其近战攻击强度降低{2}点，持续{3}分钟。", zhTW = "施法者受到下一次近戰攻擊時，會對攻擊者造成{1}點暗影傷害，並使其近戰攻擊強度降低{2}點，持續{3}分鐘。" },
	["the next time this ally takes damage dropping their health below #%, they will gain a shield absorbing # damage and begin healing for # health over # sec"] = { ko = "다음에 이 아군이 피해를 입어 생명력이 {1}% 아래로 떨어지면 {2}의 피해를 흡수하는 보호막을 얻고 {4}초에 걸쳐 {3}의 생명력을 회복하기 시작합니다.", zhCN = "该目标下一次受到伤害导致生命值低于{1}%时，会获得一个可吸收{2}点伤害的护盾，并在{4}秒内恢复{3}点生命值。", zhTW = "該目標下一次受到傷害導致生命力低於{1}%時，會獲得一個可吸收{2}點傷害的護盾，並在{4}秒內恢復{3}點生命力。" },
	["the overpower cannot be blocked, dodged or parried"] = { ko = "제압은 방어하거나 막거나 회피할 수 없습니다.", zhCN = "压制无法被格档、躲闪或招架。", zhTW = "壓制無法被格擋、躲閃或招架。" },
	["the paladin also attacks #% faster, but deals less damage with each attack"] = { ko = "하지만 각 공격의 피해는 약간 저하됩니다.", zhCN = "圣骑士的攻击速度也提高{1}%，但攻击时所造成的伤害会降低。", zhTW = "聖騎士的攻擊速度也提高{1}%，但攻擊時所造成的傷害會降低。" },
	["the paladin sacrifices himself to remove the targeted party member from harms way"] = { ko = "자신을 희생하여 선택한 파티원을 전투에서 제외시킵니다.", zhCN = "圣骑士牺牲自己，保护目标队友免受任何伤害。", zhTW = "聖騎士犧牲自己，保護目標隊友免受任何傷害。" },
	["the paladin sacrifices himself to remove the targeted party member from harms way. enemies will stop attacking the protected party member, who will be immune to all harmful attacks but cannot take any action for # min"] = { ko = "자신을 희생하여 선택한 파티원을 전투에서 제외시킵니다. 대상을 공격하던 적은 공격을 멈추게 되며 대상은 모든 공격에 대해 면역이 되지만 {1}분 동안 어떤 행동도 할 수 없습니다.", zhCN = "圣骑士牺牲自己，保护目标队友免受任何伤害。敌人会停止攻击被保护的队友，但该队友在{1}分钟内无法进行任何行动。", zhTW = "聖騎士犧牲自己，保護目標隊友免受任何傷害。敵人會停止攻擊被保護的隊友，但該隊友在{1}分鐘內無法進行任何行動。" },
	["the priest becomes surrounded with anti-magic energy"] = { ko = "사제의 몸이 역순환 에너지로 둘러싸이게 됩니다.", zhCN = "牧师被一股反魔法能量笼罩。" },
	["the priest becomes surrounded with anti-magic energy. any successful spell cast against the priest will burn # of the attacker's mana, causing # shadow damage for each point of mana burned. lasts # sec"] = { ko = "사제의 몸이 역순환 에너지로 둘러싸이게 됩니다. 자신에게 주문이 적중했을 경우 공격자의 마나를 {1}만큼 소진시키고 소진된 마나 당 {2}의 암흑 피해를 입힙니다. {3}초 동안 지속됩니다.", zhCN = "牧师被一股反魔法能量笼罩。任何对牧师成功施放的敌对法术都会令施法者损失{1}点法力值，并对其造成等量的暗影伤害。效果持续{3}秒。", zhTW = "牧師被反魔法能量所包圍。任何針對牧師施放成功的法術，攻擊者會燃燒掉{1}點法力。每燃燒一點法力會造成{2}點暗影傷害。持續{3}秒。" },
	["the rogue's dodge chance will increase by #% for # sec"] = { ko = "{2}초 동안 회피할 확률이 {1}%만큼 향상됩니다.", zhCN = "使潜行者的躲闪几率提高{1}%，持续{2}秒。", zhTW = "使盜賊的躲閃機率提高{1}%，持續{2}秒。" },
	["the shackled unit is unable to move, attack or cast spells"] = { ko = "속박된 대상은 이동하거나 공격, 주문 시전이 불가능합니다.", zhCN = "被束缚的亡灵无法移动、攻击或施法。", zhTW = "被束縛的不死族無法移動、攻擊或施法。" },
	["the shadow trance reduces the casting time of your next shadow bolt spell by #%"] = { ko = "이 상태에서 다음 어둠의 화살의 시전 시간이 {1}%만큼 단축됩니다.", zhCN = "暗影冥思使你的下一个暗影箭的施法时间缩短{1}%。", zhTW = "暗影冥思令你下一個暗影箭法術的施法時間縮短{1}%。" },
	["the soulstone can be used to store one target's soul"] = { ko = "영혼석엔 하나의 영혼을 담아 놓을 수 있습니다." },
	["the spirit of redemption cannot move, attack, be attacked or targeted by any spells or effects"] = { ko = "구원의 영혼은 이동하거나 공격하거나 공격받거나 어떠한 주문이나 효과의 대상이 될 수 없습니다.", zhCN = "救赎之魂无法移动、攻击，也不会受到任何法术或效果的影响。", zhTW = "救贖之魂無法移動、攻擊，且不受任何法術或效果攻擊或鎖定。" },
	["the symptoms of this effect can manifest as either a # sec poison or a # sec disease"] = { ko = "이 효과의 증상은 {1}초 동안 독으로 혹은 {2}초 동안 질병으로 발현됩니다.", zhCN = "该效果的症状可能体现为持续{1}秒的中毒或{2}秒秒的疾病。", zhTW = "該效果的症狀可能體現為持續{1}秒的中毒或{2}秒秒的疾病。" },
	["the target must be facing you"] = { ko = "적의 정면에서 사용해야 합니다.", zhCN = "目标必须面对你。", zhTW = "目標必須面對你。" },
	["the target will attack slower while under your control"] = { ko = "조종하는 동안 대상의 공격 속도가 감소합니다.", zhCN = "目标在受你控制时攻击速度会变慢。", zhTW = "目標受你控制時，攻擊速度降低。" },
	["the targeted undead enemy will be compelled to flee for up to # sec"] = { ko = "대상이 되는 언데드를 최대 {1}초 동안 달아나게 만듭니다.", zhTW = "目標不死族將被強迫逃跑，最多{1}秒。" },
	["the targeted undead enemy will be compelled to flee for up to # sec. damage caused may interrupt the effect. only one target can be turned at a time"] = { ko = "대상이 되는 언데드를 최대 {1}초 동안 달아나게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 동시에 한 대상만 퇴치할 수 있습니다.", zhCN = "目标亡灵将被强迫逃跑，最多{1}秒。最多只能同时超度一个目标。", zhTW = "目標不死族將被強迫逃跑，最多{1}秒。任何傷害將會中止此效果。最多只能同時超渡一個目標。" },
	["the tooltip will display damage, health, armor, any special resistances, and diet"] = { ko = "대상에 마우스 커서를 올려 놓으면 공격력과 생명력, 방어도, 저항력, 먹이의 종류가 표시됩니다.", zhCN = "信息栏里会显示出该野兽的伤害、生命值、护甲值和魔法抗性，以及它通常吃的食物。", zhTW = "資訊欄裡會顯示出該野獸的傷害、生命力、護甲值和魔法抗性，以及它通常吃的食物。" },
	["the totem enchants all party members' main-hand weapons with fire if they are within # yards"] = { ko = "토템은 {1}미터 내에 있는 모든 파티원의 주장비 무기에 불꽃을 부여합니다.", zhCN = "该图腾会为{1}码内所有队伍成员的主手武器附加火焰。" },
	["the totem enhances the melee attacks of all party members within # yards"] = { ko = "불꽃의 토템은 {1}미터 내 모든 파티원의 근접 공격을 강화합니다.", zhCN = "该图腾会强化{1}码内所有队伍成员的近战攻击。", zhTW = "它可以強化半徑{1}碼範圍內的所有小隊成員的近戰攻擊。" },
	["the totem increases party and raid members' frost resistance by #, if within # yards"] = { ko = "5분 동안 지속됩니다.", zhCN = "图腾周围半径{1}码范围内的所有小队和团队成员的冰霜抗性提高{2}点。", zhTW = "圖騰可以使半徑{1}碼範圍內所有小隊與團隊成員的冰霜抗性提高{2}點。" },
	["the totem protects party members within # yards, reducing physical damage taken by #"] = { zhCN = "该图腾保护{1}码内的队伍成员，使其受到的物理伤害降低{2}点。" },
	["the totem reduces the threat caused by all party members within # yards by #%"] = { zhCN = "这个图腾可以使周围半径{1}码范围内的所有小队成员的威胁值降低{2}%。", zhTW = "這個圖騰可以使周圍半徑{1}碼範圍內的所有小隊成員的威脅值降低{2}%。" },
	["the voidwalker consumes nearby shadows to bolster its form, recovering # health over # sec"] = { ko = "보이드워커가 주위의 어둠을 흡수하여 {2}초에 걸쳐 총 {1}의 생명력을 회복합니다.", zhCN = "虚空行者吞噬附近的阴影以维持自己的形体，在{2}秒的时间内恢复总计{1}点生命值。", zhTW = "虛空行者吞噬附近的陰影以維持自己的形體，在{2}秒的時間內恢復總計{1}點生命力。" },
	["the voidwalker consumes nearby shadows to bolster its form, recovering # health over # sec. cannot be used while in combat"] = { ko = "보이드워커가 주위의 어둠을 흡수하여 {2}초에 걸쳐 총 {1}의 생명력을 회복합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "虚空行者吞噬附近的阴影以维持自己的形体，在{2}秒的时间内恢复总计{1}点生命值。无法在战斗中使用。", zhTW = "虛空行者吞噬附近的陰影以維持自己的形體，在{2}秒的時間內恢復總計{1}點生命力。無法在戰鬥中使用。" },
	["the voidwalker consumes nearby shadows to bolster its form, recovering #,# health over # sec"] = { ko = "보이드워커가 주위의 어둠을 흡수하여 {3}초에 걸쳐 총 {1},{2}의 생명력을 회복합니다.", zhCN = "虚空行者吞噬附近的阴影以维持自己的形体，在{3}秒的时间内恢复总计{1},{2}点生命值。", zhTW = "虛空行者吞噬附近的陰影以維持自己的形體，在{3}秒的時間內恢復總計{1},{2}點生命力。" },
	["the voidwalker consumes nearby shadows to bolster its form, recovering #,# health over # sec. cannot be used while in combat"] = { ko = "보이드워커가 주위의 어둠을 흡수하여 {3}초에 걸쳐 총 {1},{2}의 생명력을 회복합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "虚空行者吞噬附近的阴影以维持自己的形体，在{3}秒的时间内恢复总计{1},{2}点生命值。无法在战斗中使用。", zhTW = "虛空行者吞噬附近的陰影以維持自己的形體，在{3}秒的時間內恢復總計{1},{2}點生命力。無法在戰鬥中使用。" },
	["the warrior enters a berserker rage, becoming immune to fear and incapacitate effects and generating extra rage when taking damage"] = { ko = "전사는 광전사의 격노 상태를 취하여 공포와 행동 불가에 면역이 되며 받는 피해에 대해 추가 분노를 생성합니다." },
	["the warrior enters a berserker rage, becoming immune to fear and incapacitate effects and generating extra rage when taking damage. lasts # sec"] = { ko = "전사는 광전사의 격노 상태를 취하여 공포와 행동 불가에 면역이 되며 받는 피해에 대해 추가 분노를 생성합니다. {1}초 동안 지속됩니다.", zhCN = "战士进入狂暴状态，对恐惧和击昏效果免疫，在受到伤害时产生额外的怒气值，持续{1}秒。", zhTW = "戰士進入狂暴狀態，對恐懼和癱瘓效果免疫，在受到傷害時產生額外的怒氣，持續{1}秒。" },
	["the warrior shouts, causing the targeted enemy to cower in fear. up to # total nearby enemies will flee in fear. lasts # sec"] = { ko = "외침의 대상이 된 적은 겁에 질려 움직이지 못하고 주위의 다른 적들은 최대 {1}마리까지 {2}초 동안 겁에 질려 도망갑니다.", zhCN = "战士发出怒吼，使目标敌人因恐惧而畏缩，附近的最多{1}个敌人则因恐惧而逃跑，持续{2}秒。", zhTW = "戰士發出怒吼，使目標敵人因恐懼而畏縮。附近最多{1}名其他敵人也會因恐懼而逃跑，持續{2}秒。" },
	["the warrior shouts, increasing the melee attack power of all party members within # yards by #"] = { ko = "전사의 외침으로 주위 {1}미터 반경에 있는 모든 파티원의 근접 전투력이 {2}만큼 증가됩니다." },
	["the warrior shouts, increasing the melee attack power of all party members within # yards by # lasts # min"] = { ko = "전사의 외침으로 주위 {1}미터 반경에 있는 모든 파티원의 근접 전투력이 9만큼 증가됩니다. {3}분 동안 지속됩니다.", zhCN = "战士发出怒吼，使半径{1}码范围内的所有小队成员的近战攻击强度提高9点，持续{3}分钟。", zhTW = "戰士發出怒吼，使半徑{1}碼範圍內的所有小隊成員的近戰攻擊強度提高9，持續{3}分鐘。" },
	["the warrior will gain #% increased critical strike chance and will be immune to fear effects for the next # sec, but all damage taken is increased by #%"] = { ko = "전사의 치명타 및 극대화율이 {1}%만큼 증가하고 다음 {2}초 동안 공포 효과에 면역이 되지만, 받는 모든 피해가 {3}%만큼 증가합니다.", zhCN = "战士的爆击几率提高{1}%，并在接下来的{2}秒内免疫恐惧效果，但受到的所有伤害提高{3}%。", zhTW = "戰士的致命一擊機率提高{1}%，且在接下來的{2}秒內對恐懼效果免疫，但受到的所有傷害提高{3}%。" },
	["there are technical problems that sometimes occur, but that's what goblin engineering is all about"] = { zhCN = "虽然有些时候可能会发生技术故障，但这难道不是地精工程学的最大亮点吗？", zhTW = "雖然有些時候可能會發生技術故障，但這難道不是哥布林工程學的最大特點嗎？" },
	["these effects cause no threat"] = { ko = "이 주문은 위협 수준을 생성하지 않습니다.", zhCN = "这些效果不产生威胁值。", zhTW = "這些效果不會造成威脅值。" },
	["this amount can be further increased by multipliers from those forms"] = { zhCN = "该数值可进一步受到这些形态的倍率加成。", zhTW = "那些形態的加成可以進一步提高此數值。" },
	["this attack deals #% weapon damage and disarms the target for # sec"] = { ko = "다음 공격은 무기 공격력의 {1}%에 해당하는 피해를 입히고 대상을 {2}초 동안 무장 해제시킵니다." },
	["this attack deals #% weapon damage plus # and immobilizes the target for # sec"] = { ko = "무기 공격력의 {1}%에 {2}의 추가 피해를 입히고 대상을 {3}초 동안 이동 불가 상태로 만듭니다.", zhCN = "该攻击造成{1}%武器伤害外加{2}点伤害，并使目标无法移动{3}秒。" },
	["this causes low threat"] = { ko = "낮은 위협 수준을 생성합니다." },
	["this damage causes no threat. # charges"] = { ko = "공격자는 몇초마다 한번씩만 피해를 입게 됩니다.", zhCN = "这种伤害不会造成威胁值。", zhTW = "此傷害不造成威脅。" },
	["this damage is dealt slowly at first, and builds up as the bane reaches its full duration"] = { ko = "처음엔 피해를 천천히 입히다가 갈수록 피해를 주는 속도가 빨라집니다.", zhCN = "该伤害起初较低，并会随着灾祸接近完整持续时间而逐渐提高。", zhTW = "此傷害在初期較低，但是會在作用效果期間不斷提高，直到結束。" },
	["this does not stack with other movement speed increasing effects"] = { ko = "다른 이동 속도 증가 효과와 중복 적용되지 않습니다.", zhCN = "这个效果不与其它同类效果叠加。", zhTW = "此效果無法與其他移動速度提高效果堆疊。" },
	["this effect is doubled in snowy areas"] = { ko = "설원 지역에서는 효과가 2배로 증가합니다.", zhCN = "在雪地区域时，该效果翻倍。", zhTW = "此效果在雪地區域加倍。" },
	["this effect is doubled in volcanic areas"] = { ko = "화산 지역에서는 효과가 2배로 증가합니다.", zhCN = "在火山区域时，攻击强度加成翻倍。", zhTW = "在火山區域時，攻擊強度加成翻倍。" },
	["this effect lasts until you have caused # non-periodic critical strikes with fire spells"] = { ko = "{1}회의 비주기적인 극대화 효과를 발휘할 때까지 지속됩니다.", zhCN = "该效果会持续到你用火焰法术造成{1}次非周期性爆击为止。", zhTW = "此效果會持續到你的火焰法術造成{1}次非週期性致命一擊為止。" },
	["this effect lowers the target's movement speed by #% for # sec"] = { ko = "빙결 효과는 {2}초 동안 적의 이동 속도를 {1}%만큼 감소시킵니다." },
	["this effect persists through death"] = { ko = "이 효과는 죽어도 지속됩니다.", zhCN = "该效果在死亡后仍能保持。", zhTW = "此效果在死亡之後仍然有效。" },
	["this effect stacks up to # times on the same target"] = { ko = "이 효과는 같은 대상에게 최대 {1}번까지 중첩됩니다.", zhCN = "该效果对同一个目标最多叠加{1}次。" },
	["this enhancement is permanent and cannot be removed or replaced"] = { ko = "이 마법부여는 영구적이며 제거하거나 교체하지 못합니다.", zhCN = "此附魔永久生效，无法被移除或替换。", zhTW = "此附魔永久生效，無法被移除或取代。" },
	["this expends one lightning ball"] = { ko = "매번 피해를 줄 때마다 구슬이 하나씩 사라집니다." },
	["this spell can only be placed on one target at a time per caster"] = { ko = "이 주문은 시전자당 한 번에 하나의 대상에게만 걸어둘 수 있습니다.", zhCN = "每个施法者在同一时间内只能在一名目标身上施放该法术。", zhTW = "每位施法者一次只能對一個目標施放此法術。" },
	["this spell can only be used out of combat"] = { ko = "비전투 상태에서만 사용할 수 있습니다.", zhCN = "这个法术只能在非战斗状态下使用。", zhTW = "這個法術只能在非戰鬥狀態下使用。" },
	["this spell causes very low threat"] = { ko = "이 주문은 매우 낮은 위협 수준을 생성합니다." },
	["this spell will be checked against the lower of the target's frost and fire resists and counts as both frost and fire damage"] = { ko = "이 주문은 대상의 냉기 및 화염 저항력 중 낮은 수치를 상대로 적중하며, 냉기 및 화염 피해로 간주됩니다.", zhCN = "该法术同时视为冰霜与火焰伤害，并以目标冰霜与火焰抗性中较低者为准。", zhTW = "此法術將會檢視目標的冰霜與火焰抗性，依照較低的一方造成傷害，並同時視為冰霜和火焰傷害。" },
	["this vulnerability increases all fire damage you deal to your target by #% and lasts # sec, stacking up to # times"] = { ko = "최대 {3}번까지 중첩됩니다.", zhCN = "该易伤效果会使你对该目标造成的所有火焰伤害提高{1}%，持续{2}秒，最多叠加{3}次。" },
	["thorns sprout from the friendly target causing # nature damage to attackers when hit"] = { ko = "대상의 몸에 가시가 돋아나 공격자에게 {1}의 자연 피해를 입힙니다." },
	["thorns sprout from the friendly target causing # nature damage to attackers when hit. lasts # min"] = { ko = "대상의 몸에 가시가 돋아나 공격자에게 {1}의 자연 피해를 입힙니다. {2}분 동안 지속됩니다.", zhCN = "使友方目标身上环绕着荆棘，对任何使用近战手段击中被保护者的敌人造成{1}点自然伤害，持续{2}分钟。", zhTW = "使友方目標身上環繞著荊棘，對任何使用近戰手段擊中被保護者的敵人造成{1}點自然傷害，持續{2}分鐘。" },
	["throw a fragile concoction at the target area, revealing a cloud of caustic smog for # sec"] = { ko = "대상 지역에 불안정한 혼합물을 던져 {1}초 동안 부식성 매연 구름을 드러냅니다.", zhCN = "向目标区域投掷一瓶易碎的混合剂，释放出一团腐蚀烟雾，持续{1}秒。", zhTW = "朝目標區域投擲易碎的混合物，產生一陣腐蝕煙霧，持續{1}秒。" },
	["throw a fragile concoction at the target area, revealing a cloud of caustic smog for # sec. enemies standing within the cloud suffer # nature damage every # sec"] = { ko = "대상 지역에 불안정한 혼합물을 던져 {1}초 동안 부식성 매연 구름을 드러냅니다. 구름 안에 서 있는 적은 {3}초마다 {2}의 자연 피해를 받습니다.", zhCN = "向目标区域投掷一瓶易碎的混合剂，释放出一团腐蚀烟雾，持续{1}秒。站在烟雾中的敌人每{3}秒受到{2}点自然伤害。", zhTW = "朝目標區域投擲易碎的混合物，產生一陣腐蝕煙霧，持續{1}秒。煙霧範圍內的敵人每{3}秒受到{2}點自然傷害。" },
	["throw a fragile concoction at the target area, revealing a cloud of disorienting smog for # sec"] = { zhCN = "向目标区域投掷一瓶易碎的混合剂，释放出一团致盲烟雾，持续{1}秒。", zhTW = "向目標區域投擲一瓶易碎的混精煉藥劑，釋放出一團致盲煙霧，持續{1}秒。" },
	["throw a fragile concoction at the target area, revealing a cloud of disorienting smog for # sec. enemies standing within the cloud have their hit chance reduced by #%. ineffective against targets above level ?"] = { ko = "대상 지역에 불안정한 혼합물을 던져 {1}초 동안 혼란의 매연 구름을 드러냅니다. 구름 안에 서 있는 적은 적중률이 {2}%만큼 감소합니다. ? 레벨을 초과하는 대상에게는 효과가 없습니다.", zhCN = "向目标区域投掷一瓶易碎的混合剂，释放出一团致盲烟雾，持续{1}秒。站在烟雾中的敌人的命中几率降低{2}%。对?级以上的目标不产生效果。", zhTW = "向目標區域投擲一瓶易碎的混精煉藥劑，釋放出一團致盲煙霧，持續{1}秒。站在煙霧中的敵人的命中機率降低{2}%。對?級以上的目標不產生效果。" },
	["thrown attacks explode on impact, causing # fire damage to nearby enemies"] = { ko = "투척 공격이 충돌 시 폭발하여 주위 적에게 {1}의 화염 피해를 입힙니다.", zhCN = "投掷攻击命中时爆炸，对附近敌人造成{1}点火焰伤害。", zhTW = "投擲出去後會在擊中時爆炸，對附近的敵人造成{1}點火焰傷害。" },
	["throws a distraction, attracting the attention of all nearby enemies and reducing their stealth detection as if they were # level lower for # sec"] = { ko = "대상 지역에 혼란을 일으켜 {2}초 동안 주위 모든 적의 주의를 끌고, 해당 적의 은신 감지 효과를 {1}레벨만큼 감소시킵니다.", zhCN = "投掷诱饵，吸引附近所有敌人的注意力，并使其潜行侦测降低，效果相当于低{1}级，持续{2}秒。", zhTW = "投擲物體吸引附近所有敵人的注意力，並降低其偵測潛行的能力，如同其等級比你低{1}級，持續{2}秒。" },
	["throws a distraction, attracting the attention of all nearby enemies and reducing their stealth detection as if they were # level lower for # sec. does not break stealth"] = { ko = "대상 지역에 혼란을 일으켜 {2}초 동안 주위 모든 적의 주의를 끌고, 해당 적의 은신 감지 효과를 {1}레벨만큼 감소시킵니다. 은신 상태를 해제시키지 않습니다.", zhCN = "投掷诱饵，吸引附近所有敌人的注意力，并使其潜行侦测降低，效果相当于低{1}级，持续{2}秒。不会取消潜行。", zhTW = "投擲物體吸引附近所有敵人的注意力，並降低其偵測潛行的能力，如同其等級比你低{1}級，持續{2}秒。不會取消潛行狀態。" },
	["to trigger an extra attack on the"] = { zhTW = "額外攻擊目標" },
	["transfers # health every # sec from the target to the caster"] = { ko = "대상으로부터 {2}초마다 {1}의 생명력을 흡수합니다." },
	["transfers # health every # sec from the target to the caster. lasts # sec"] = { ko = "대상으로부터 {2}초마다 {1}의 생명력을 흡수합니다. {3}초 동안 지속됩니다.", zhCN = "每{2}秒从目标身上吸取{1}点生命值并转移给施法者，持续{3}秒。", zhTW = "每{2}秒吸取目標{1}點生命力，並將其轉移給施法者，持續{3}秒。" },
	["transfers # health from the target to the caster every # sec"] = { ko = "대상으로부터 {2}초마다 {1}의 생명력을 흡수합니다." },
	["transfers # health from the target to the caster every # sec. lasts # sec"] = { ko = "대상으로부터 {2}초마다 {1}의 생명력을 흡수합니다. {3}초 동안 지속됩니다.", zhCN = "每{2}秒将目标的{1}点生命值转移给施法者，持续{3}秒。", zhTW = "每{2}秒將目標的{1}點生命力轉移給施法者，持續{3}秒。" },
	["transfers # mana every # sec from the target to the caster"] = { ko = "대상으로부터 {2}초마다 {1}의 마나를 흡수합니다." },
	["transfers # mana every # sec from the target to the caster. lasts # sec"] = { ko = "대상으로부터 {2}초마다 {1}의 마나를 흡수합니다. {3}초 동안 지속됩니다.", zhCN = "每{2}秒从目标身上吸取{1}点法力值并转移给施法者，持续{3}秒。", zhTW = "每{2}秒將目標的{1}點法力轉移給施法者，持續{3}秒。" },
	["transform into a centaur for # min or until you enter combat"] = { ko = "{1}분 동안 또는 전투가 시작될 때까지 켄타우로스로 변신합니다.", zhCN = "变身为半人马，持续{1}分钟，或者直到你进入战斗为止。", zhTW = "變形成半人馬，持續{1}分鐘，或直到你進入戰鬥" },
	["transforms the enemy into a pig, forcing it to wander around for up to # sec. while wandering, the pig cannot attack or cast spells but will regenerate very quickly. any damage will transform the target back into its normal form. only one target can be polymorphed at a time. only works on beasts, humanoids and critters"] = { ko = "최대 {1}초 동안 적을 돼지로 변이시켜 주변을 떠돌게 만듭니다. 떠도는 동안엔 공격하거나 주문을 외울 수 없지만 매우 빠른 속도로 체력이 회복됩니다. 이 동안 공격을 받게 되면 원래 모습으로 돌아옵니다. 동시에 한 대상만 변이시킬 수 있으며 야수와 인간형, 동물에게만 사용할 수 있습니다.", zhCN = "将敌人变成一只猪，使其在周围到处闲逛，最多持续{1}秒。在这个过程中，猪无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让猪恢复正常状态。每个法师在同一时间内只能将一个目标变形，只能对野兽、人型生物和小动物施放。", zhTW = "將敵人變成豬，使其在周圍到處閒逛，最多持續{1}秒。在此期間，豬無法攻擊或施法，但會以極快的速度恢復生命力，任何傷害都會讓豬恢復正常狀態。每個法師在同一時間內只能將一個目標變成豬，只能對野獸、人型生物和小動物施放。" },
	["transforms the enemy into a sheep, forcing it to wander around for up to # sec. while wandering, the sheep cannot attack or cast spells but will regenerate very quickly. any damage will transform the target back into its normal form. only one target can be polymorphed at a time. only works on beasts, humanoids and critters"] = { ko = "최대 {1}초 동안 적을 양으로 변이시켜 주변을 떠돌게 만듭니다. 떠도는 동안엔 공격하거나 주문을 외울 수 없지만 매우 빠른 속도로 체력이 회복됩니다. 이 동안 공격을 받게 되면 원래 모습으로 돌아옵니다. 동시에 한 대상만 변이시킬 수 있으며 야수와 인간형, 동물에게만 사용할 수 있습니다.", zhCN = "将敌人变成绵羊，使其在周围到处闲逛，最多持续{1}秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。", zhTW = "將敵人變成綿羊，使其在周圍到處閒逛，最多持續{1}秒。在此期間，綿羊無法攻擊或施法，但會以極快的速度恢復生命力，任何傷害都會讓綿羊恢復正常狀態。每個法師在同一時間內只能將一個目標變成綿羊，只能對野獸、人型生物和小動物施放。" },
	["trap will exist for # min"] = { ko = "적이 다가오면 불태워 15초에 걸쳐 총 105의 화염 피해를 입힙니다.", zhCN = "陷阱会存在{1}分钟。", zhTW = "陷阱可存在{1}分鐘。" },
	["trigger an extra attack on the"] = { zhCN = "造成一次额外的", zhTW = "造成一次額外的" },
	["try feeding the pet immediately to make it happy"] = { ko = "즉시 먹을 것을 줘서 만족도를 높이도록 하십시오." },
	["turns off your attack when used"] = { zhCN = "使用之后结束你的攻击。", zhTW = "使用時會結束你的攻擊。" },
	["turns the shaman into a ghost wolf, increasing speed by #%"] = { zhCN = "将萨满祭司变成一头幽魂之狼，移动速度提高{1}%。", zhTW = "將薩滿變成一頭鬼魂之狼，移動速度提高{1}%。" },
	["turns the shaman into a ghost wolf, increasing speed by #%. only useable outdoors"] = { ko = "주술사의 모습을 늑대 정령으로 바꿉니다. 이동 속도가 {1}%만큼 증가합니다. 야외에서만 사용할 수 있습니다.", zhCN = "将萨满祭司变成一头幽魂之狼，移动速度提高{1}%。只能在户外使用。", zhTW = "將薩滿變成一頭鬼魂之狼，移動速度提高{1}%。只能在戶外使用。" },
	["turns the target into a chicken for # sec"] = { ko = "{1}초 동안 대상을 닭으로 변신시킵니다.", zhCN = "将目标变成一只小鸡，持续{1}秒。", zhTW = "將目標變成雞，持續{1}秒。" },
	["turns the target into a chicken for # sec. well, that is assuming the transmogrification polarity has not been reversed"] = { ko = "{1}초 동안 대상을 닭으로 변신시킵니다. 변이 과정이 역전되는 일은 아직까지는 발생하지 않았습니다.", zhCN = "将目标变成一只小鸡，持续{1}秒。当然，前提是幻化极性没有反转……", zhTW = "將目標變成雞，持續{1}秒。嗯，假設變形術的極性沒有被反轉…" },
	["underwater breath lasts #% longer than normal"] = { ko = "수중에서 다른 종족의 {1}%만큼 호흡을 오래 유지할 수 있습니다.", zhCN = "水下呼吸的时间延长{1}%。", zhTW = "在水下呼吸的時間延長{1}%。" },
	["unleash a belch of dragonfire, dealing # fire damage instantly in a narrow cone in front of you"] = { ko = "전방 좁은 부채꼴 범위로 용의 불꽃을 내뿜어 즉시 {1}의 화염 피해를 입힙니다.", zhCN = "喷出一口龙火，立即对前方狭窄锥形范围内的敌人造成{1}点火焰伤害。", zhTW = "吐出一團龍火，立刻在你面前的狹窄錐形範圍內造成{1}點火焰傷害。" },
	["unleash a belch of dragonfire, dealing # fire damage instantly in a narrow cone in front of you. affected targets will suffer # additional damage every # sec for # sec"] = { ko = "전방 좁은 부채꼴 범위로 용의 불꽃을 내뿜어 즉시 {1}의 화염 피해를 입힙니다. 영향을 받는 대상은 {4}초 동안 {3}초마다 {2}의 추가 피해를 받습니다.", zhCN = "喷出一口龙火，立即对前方狭窄锥形范围内的敌人造成{1}点火焰伤害。受影响的目标每{3}秒额外受到{2}点伤害，持续{4}秒。", zhTW = "吐出一團龍火，立刻在你面前的狹窄錐形範圍內造成{1}點火焰傷害。受影響的目標每{3}秒額外受到{2}點傷害，持續{4}秒。" },
	["unleash the energy of a seal spell upon an enemy"] = { ko = "문장의 에너지를 적에게 폭발시킵니다.", zhCN = "对敌人释放圣印法术的能量。", zhTW = "將聖印法術的能量釋放到敵人身上。" },
	["unleash the energy of a seal spell upon an enemy. does not consume the seal. refer to individual seals for judgement effect"] = { ko = "문장의 에너지를 적에게 폭발시킵니다. 문장을 소모하지 않습니다. 효과는 문장에 따라 달라집니다.", zhCN = "对敌人释放圣印法术的能量。不会消耗圣印。有关审判效果，请参阅各个圣印的说明。", zhTW = "將聖印法術的能量釋放到敵人身上。不會消耗聖印。請參閱每種聖印的審判效果說明。" },
	["unleashing this seal's energy causes # to # holy damage to an enemy and taunts the target to attack you for # sec"] = { ko = "문장의 에너지를 폭발시키면 적에게 {1}~{2}의 신성 피해를 입히고 대상을 도발해 {3}초 동안 자신을 공격하게 합니다.", zhCN = "释放此圣印的能量会对一名敌人造成{1}至{2}点神圣伤害，并嘲讽该目标攻击你，持续{3}秒。", zhTW = "釋放這種聖印的能量會對敵人造成{1}至{2}點神聖傷害，並嘲諷目標，使其向你發起攻擊，持續{3}秒。" },
	["unleashing this seal's energy inflicts # to # holy damage to an enemy and taunts the target to attack you for # sec"] = { ko = "문장의 에너지를 적에게 폭발시키면 {1}~{2}의 신성 피해를 입히고 {3}초 동안 대상이 자신을 공격하도록 도발합니다." },
	["unleashing this seal's energy inflicts# to # holy damage to an enemy and taunts the target to attack you for # sec"] = { ko = "문장의 에너지를 적에게 폭발시키면 {1}~{2}의 신성 피해를 입히고 {3}초 동안 대상이 자신을 공격하도록 도발합니다." },
	["unleashing this seal's energy will cause # to # holy damage to an enemy"] = { ko = "문장의 에너지를 폭발시키면 적에게 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "释放这种圣印的能量将对目标造成{1}至{2}点神圣伤害。", zhTW = "釋放這種聖印的能量將對目標造成{1}至{2}點神聖傷害。" },
	["unleashing this seal's energy will judge an enemy for # sec, granting attacks and spells used against the judged enemy a chance to restore # mana to the attacker"] = { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" },
	["unleashing this seal's energy will judge an enemy for # sec, granting attacks and spells used against the judged enemy a chance to restore # mana to the attacker. your melee strikes will refresh the spell's duration. only one judgement per paladin can be active at any one time"] = { ko = "문장의 에너지를 폭발시키면 {1}초 동안 해당 적에 심판을 내립니다. 심판이 내려진 적을 공격하는 이는 일정 확률로 {2}의 마나가 회복됩니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。如果被审判的目标受到了武器和法术攻击，攻击者就有一定几率恢复{2}点法力值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。如果被審判的目標受到了武器或法術攻擊，攻擊者就有一定機率恢復{2}點法力。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" },
	["unleashing this seal's energy will judge an enemy for # sec, granting melee attacks made against the judged enemy a chance of healing the attacker for #"] = { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" },
	["unleashing this seal's energy will judge an enemy for # sec, granting melee attacks made against the judged enemy a chance of healing the attacker for # your melee strikes will refresh the spell's duration. only one judgement per paladin can be active at any one time"] = { ko = "문장의 에너지를 폭발시키면 {1}초 동안 해당 적에 심판을 내립니다. 심판이 내려진 적을 공격하는 이는 일정 확률로 25의 생명력이 회복됩니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。使用近战武器击中被审判的目标就有一定几率令攻击者回复25点生命值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。使用近戰武器擊中被審判的目標就有一定機率令攻擊者回復25點生命力。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" },
	["unleashing this seal's energy will judge an enemy for # sec, increasing holy damage taken by up to #"] = { ko = "문장의 에너지를 적에게 폭발시키면 {1}초 동안 적이 입는 신성 피해가 {2}까지 증가합니다." },
	["unleashing this seal's energy will judge an enemy for # sec, increasing holy damage taken by up to # your melee strikes will refresh the spell's duration. only one judgement per paladin can be active at any one time"] = { ko = "문장의 에너지를 적에게 폭발시키면 {1}초 동안 적이 입는 신성 피해가 23까지 증가합니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。神圣系的伤害性法术对被审判的目标造成最多23点额外的神圣伤害。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。神聖系的傷害性法術對被審判的目標造成最多23額外的神聖傷害。你的近戰打擊會更新法術的持續時間。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" },
	["unleashing this seal's energy will judge an enemy for # sec, preventing them from fleeing"] = { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" },
	["unleashing this seal's energy will judge an enemy for # sec, preventing them from fleeing. your melee strikes will refresh the spell's duration. only one judgement per paladin can be active at any one time"] = { ko = "문장의 에너지를 폭발시키면 {1}초 동안 해당 적에 심판을 내립니다. 심판이 내려진 적은 도망가지 못합니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。被审判的目标无法逃跑。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。被審判的目標無法逃跑。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" },
	["unleashing this seal's energy will judge an enemy, instantly causing # to # holy damage, # to # if the target is stunned or incapacitated"] = { ko = "문장의 에너지를 폭발시키면 즉시 해당 적에게 {1}~{2}의 신성 피해를 입히고 만약 적이 기절 또는 행동 불가 상태였다면 {3}~{4}의 피해를 입힙니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，对其立刻造成{1}至{2}点神圣伤害，若目标昏迷或瘫痪则造成{3}至{4}点神圣伤害。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，對其立即造成{1}至{2}點神聖傷害，若目標處於昏迷或癱瘓狀態則會造成{3}至{4}點神聖傷害。" },
	["unpacks a first aid kit that allows you and others sitting nearby to gain # (below #) · # (below #) · # (below #) · # (below #) · # (below #) · #(above) increased stamina, mutually exclusive with power word: fortitude"] = { ko = "응급 치료 도구를 펼쳐 자신과 주위에 앉은 다른 플레이어의 체력을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}({8}레벨 미만) · {9}({10}레벨 미만) · {11}(그 위)만큼 증가시킵니다. 신의 권능: 인내와 겸용해서 사용할 수 없습니다.", zhCN = "打开一个急救包，使你和附近坐下的其他人耐力提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（{8}级以下） · {9}（{10}级以下） · {11}（更高）点，与真言术：韧不叠加。", zhTW = "開啟一個急救箱，使你和附近坐下的其他人耐力提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（{8}級以下） · {9}（{10}級以下） · {11}（更高）點，與真言術：韌不疊加。" },
	["unpacks a first aid kit that allows you and others sitting nearby to gain # increased stamina, mutually exclusive with power word: fortitude"] = { ko = "응급 치료 도구를 펼쳐 자신과 주위에 앉은 다른 플레이어의 체력을 {1}만큼 증가시킵니다. 신의 권능: 인내와 겸용해서 사용할 수 없습니다.", zhCN = "打开一个急救包，使你和附近坐下的其他人耐力提高{1}点，与真言术：韧不叠加。", zhTW = "開啟一個急救箱，使你和附近坐下的其他人耐力提高{1}點，與真言術：韌不疊加。" },
	["unrolls a banner that allows you and other members of the alliance sitting nearby to gain # (below #) · # (below #) · # (below #) · #(above) increased spirit, mutually exclusive with divine spirit"] = { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 얼라이언스 구성원의 정신력을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}(그 위)만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他联盟成员的精神提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（更高）。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他聯盟成員的精神提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（更高）。與神聖之靈互斥。" },
	["unrolls a banner that allows you and other members of the alliance sitting nearby to gain # increased spirit, mutually exclusive with divine spirit"] = { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 얼라이언스 구성원의 정신력을 {1}만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他联盟成员的精神提高{1}。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他聯盟成員的精神提高{1}。與神聖之靈互斥。" },
	["unrolls a banner that allows you and other members of the horde sitting nearby to gain # (below #) · # (below #) · # (below #) · #(above) increased spirit, mutually exclusive with divine spirit"] = { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 호드 구성원의 정신력을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}(그 위)만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他部落成员的精神提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（更高）。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他部落成員的精神提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（更高）。與神聖之靈互斥。" },
	["unrolls a banner that allows you and other members of the horde sitting nearby to gain # increased spirit, mutually exclusive with divine spirit"] = { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 호드 구성원의 정신력을 {1}만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他部落成员的精神提高{1}。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他部落成員的精神提高{1}。與神聖之靈互斥。" },
	["upon death, the priest becomes the spirit of redemption for # sec"] = { ko = "사제가 생명력을 모두 잃으면 {1}초 동안 구원의 영혼으로 변합니다.", zhCN = "在死亡时，牧师变成一个救赎之魂，持续{1}秒。", zhTW = "死亡之時，牧師變為救贖之魂，持續{1}秒。" },
	["upon death, the priest becomes the spirit of redemption for # sec. the spirit of redemption cannot move, attack, be attacked or targeted by any spells or effects. while in this form the priest can cast any healing spell free of cost. when the effect ends, the priest dies"] = { ko = "사제가 생명력을 모두 잃으면 {1}초 동안 구원의 영혼으로 변합니다. 구원의 영혼은 이동하거나 공격하거나 공격받거나 어떠한 주문이나 효과의 대상이 될 수 없습니다. 이 형태에서는 모든 치유 주문을 마나 소비 없이 사용할 수 있습니다. 효과가 종료되면 사제는 죽습니다.", zhCN = "在死亡时，牧师变成一个救赎之魂，持续{1}秒。救赎之魂无法移动、攻击，也不会受到任何法术或效果的影响。在这个形态下，牧师可以施放任何治疗法术，不需消耗任何法力值。当救赎之魂效果结束时，牧师死亡。", zhTW = "死亡之時，牧師變為救贖之魂，持續{1}秒。救贖之魂無法移動、攻擊，且不受任何法術或效果攻擊或鎖定。進入此形態，牧師可不消耗能量施放任何治療法術。效果結束後，牧師就會死亡。" },
	["usable at raven hill cemetery and scarlet monastery graveyard"] = { ko = "까마귀 언덕 묘지와 붉은십자군 수도원 묘지에서 사용할 수 있습니다." },
	["using food close to the pet's level will have a better result"] = { ko = "야수의 레벨에 맞는 먹이를 주면 더 효과가 좋습니다." },
	["venom shot the target for # nature damage"] = { ko = "대상에게 맹독 화살을 날려 {1}의 자연 피해를 입힙니다.", zhCN = "向目标发射毒箭，造成{1}点自然伤害。", zhTW = "對目標施放毒液射擊，造成{1}點自然傷害。" },
	["venomous blood deals # nature damage per dose when it expires"] = { ko = "맹독성 피는 만료될 때 중첩 하나당 {1}의 자연 피해를 입힙니다.", zhCN = "当毒血效果结束时，每层会造成{1}点自然伤害。", zhTW = "效果結束後，每層毒血造成{1}點自然傷害。" },
	["voidwalker - reduces physical damage taken by #%"] = { ko = "보이드워커 - 받는 물리 피해가 {1}%만큼 감소합니다.", zhCN = "虚空行者 - 受到的物理伤害降低{1}%。", zhTW = "虛無行者 - 所承受的物理傷害降低{1}%。" },
	["voidwalker: restores #% of your total mana every # sec"] = { ko = "보이드워커: {2}초마다 전체 마나의 {1}%에 해당하는 마나를 회복합니다.", zhCN = "虚空行者：每{2}秒恢复总法力值的{1}%。", zhTW = "虛無行者：使你每{2}秒恢復{1}%法力上限。" },
	["wards the friendly target against fear"] = { ko = "대상을 공포로부터 보호합니다.", zhCN = "使友方目标获得抵抗恐惧的结界。", zhTW = "使友方目標獲得抵抗恐懼的結界。" },
	["wards the friendly target against fear. the next fear effect used against the target will fail, using up the ward. lasts # min"] = { ko = "대상을 공포로부터 보호합니다. 해당 대상에게 적용되는 다음 공포 효과는 실패하게 됩니다. {1}분 동안 지속됩니다.", zhCN = "使友方目标获得抵抗恐惧的结界。下一次对该目标施放的恐惧效果会失败并消耗结界。结界持续{1}分钟。", zhTW = "使友方目標獲得抵抗恐懼的結界。下一次對該目標施放的恐懼效果會失敗並消耗結界。結界持續{1}分鐘。" },
	["weakens the target enemy, reducing melee attack power by # and reducing the effectiveness of any healing by #%"] = { zhCN = "削弱目标敌人，使其近战攻击强度降低{1}点，并使其受到的任何治疗效果降低{2}%。" },
	["weakens the target enemy, reducing melee attack power by # and reducing the effectiveness of any healing by #%. lasts # min"] = { ko = "적을 약화시켜 {3}분 동안 근접 전투력을 {1}만큼 감소시키고 해당 대상이 받는 치유 효과를 {2}%만큼 감소시킵니다.", zhCN = "削弱目标敌人，使其近战攻击强度降低{1}点，并使其受到的任何治疗效果降低{2}%。持续{3}分钟。", zhTW = "削弱目標，使其近戰攻擊強度降低{1}點，並使任何形式的治療對其產生的效果降低{2}%，持續{3}分鐘。" },
	["well, that is assuming the transmogrification polarity has not been reversed"] = { ko = "변이 과정이 역전되는 일은 아직까지는 발생하지 않았습니다.", zhCN = "当然，前提是幻化极性没有反转……", zhTW = "嗯，假設變形術的極性沒有被反轉…" },
	["when a spell, melee or ranged attack hits the caster, the attacker will be struck for # nature damage"] = { ko = "만약 시전자에게 주문이나 근접 또는 원거리 공격을 시도할 경우 공격자는 {1}의 자연 피해를 입게 됩니다." },
	["when a spell, melee or ranged attack hits the caster, the attacker will be struck for # shadow damage"] = { ko = "주문이나 근접 또는 원거리 공격을 받게 되면 공격자는 {1}의 암흑 피해를 입게 됩니다.", zhCN = "如果施法者受到了法术、近战或远程伤害，则攻击者会受到{1}点暗影伤害。", zhTW = "如果施法者受到了近戰或遠程傷害，則攻擊者會受到{1}點暗影傷害。" },
	["when a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, #% of maximum mana is restored to the caster, expending one water globe"] = { zhCN = "当法术、近战或远程攻击命中施法者，或施法者的治疗法术造成爆击时，恢复最大法力值的{1}%，并消耗一个水球。" },
	["when activated, gives your next flash of light, holy light, or holy shock spell a #% critical effect chance"] = { ko = "활성화되면 다음 빛의 섬광, 성스러운 빛, 신성 충격 주문이 {1}%의 확률로 극대화 효과를 발휘합니다.", zhCN = "激活之后，使你的下一个圣光闪现、圣光术或神圣震击有{1}%的几率造成极效治疗效果。", zhTW = "啟動之後，使你的下一個聖光閃現，聖光術或神聖震擊的治療法術有{1}%的機率造成極效治療。" },
	["when activated, increases the critical strike chance of your next sinister strike, backstab, ambush, eviscerate, or mutilate by #%"] = { ko = "활성화 시 다음 사악한 일격, 기습, 매복, 절개 또는 절단의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "激活后，使你的下一次邪恶攻击、背刺、伏击、刺骨或毁伤的爆击几率提高{1}%。", zhTW = "啟動之後，你的下一次邪惡攻擊、背刺、伏擊、剔骨或截肢造成致命一擊的機率提高{1}%。" },
	["when activated, increases your dodge and parry chance by #% for # sec"] = { ko = "활성화되면 {2}초 동안 회피와 무기 막기 확률이 {1}%만큼 증가합니다.", zhCN = "激活之后，使你的躲闪和招架几率提高{1}%，持续{2}秒。", zhTW = "啟動之後，使你的躲閃和招架機率提高{1}%，持續{2}秒。" },
	["when activated, increases your physical damage done by #% and makes you immune to fear effects, but increases all damage you take by #%"] = { ko = "활성화 시 물리 공격력이 {1}%만큼 증가하고 공포 효과에 면역이 되지만, 받는 모든 피해가 {2}%만큼 증가합니다.", zhCN = "激活后，你造成的物理伤害提高{1}%，并免疫恐惧效果，但受到的所有伤害提高{2}%。" },
	["when activated, increases your physical damage done by #% and makes you immune to fear effects, but increases all damage you take by #%. lasts # sec"] = { ko = "활성화 시 물리 공격력이 {1}%만큼 증가하고 공포 효과에 면역이 되지만, 받는 모든 피해가 {2}%만큼 증가합니다. {3}초 동안 지속됩니다.", zhCN = "激活后，你造成的物理伤害提高{1}%，并免疫恐惧效果，但受到的所有伤害提高{2}%。持续{3}秒。", zhTW = "啟動之後，你造成的物理傷害提高{1}%，並免疫恐懼效果，但你受到的所有傷害提高{2}%，持續{3}秒。" },
	["when activated, reduces the mana cost of your next spell by #% and increases its critical effect chance by #% if it is a non-periodic spell and capable of a critical effect"] = { ko = "활성화되면 다음 주문에 소비되는 마나를 {1}%만큼 감소시키고, 그 주문이 주기 효과가 아니고 극대화 효과를 낼 수 있는 주문이면 극대화 확률이 {2}%만큼 증가합니다.", zhCN = "激活之后，你的下一个法术所消耗的法力值减少{1}%，造成爆击或极效治疗的几率提高{2}%（如果它有可能造成这些效果的话）。", zhTW = "啟用之後，你的下一個法術所消耗的法力減少{1}%，造成致命一擊或極效治療的機率提高{2}%（如果它有可能造成這些效果的話）。" },
	["when activated, sacrifices your summoned demon to enhance the opposing aspect of your power, granting you an effect that lasts # hr"] = { ko = "활성화되면 소환된 악마를 제물로 바쳐 힘의 반대되는 측면을 강화합니다.", zhCN = "激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续{1}小时的效果。", zhTW = "啟動之後，犧牲你目前所召喚的惡魔，強化你力量的相反層面，使你獲得一種特殊效果，持續{1}小時。" },
	["when activated, sacrifices your summoned demon to enhance the opposing aspect of your power, granting you an effect that lasts # hr. the effect is canceled if any demon is summoned"] = { ko = "활성화되면 소환된 악마를 제물로 바쳐 힘의 반대되는 측면을 강화합니다. 이 효과는 {1}시간 동안 지속되며 소환수를 소환하면 사라집니다.", zhCN = "激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续{1}小时的效果。如果召唤任何恶魔，该效果会被取消。", zhTW = "啟動之後，犧牲你目前所召喚的惡魔，強化你力量的相反層面，使你獲得一種特殊效果，持續{1}小時。如果在此期間你召喚任意一個惡魔，該效果就會被取消。" },
	["when activated, this ability grants you an absorb shield equal to #% of your maximum health for # sec"] = { ko = "이 능력을 활성화하면 {2}초 동안 최대 생명력의 {1}%에 해당하는 피해를 흡수하는 보호막을 얻습니다.", zhCN = "激活后，获得相当于你最大生命值{1}%的吸收护盾，持续{2}秒。", zhTW = "啟用後，獲得相當於你最大生命力{1}%的吸收護盾，持續{2}秒。" },
	["when activated, this ability grants you an absorb shield equal to #% of your maximum health for # sec. applies forbearance for # min. cannot be cast while forbearance is active"] = { ko = "이 능력을 활성화하면 {2}초 동안 최대 생명력의 {1}%에 해당하는 피해를 흡수하는 보호막을 얻습니다. {3}분 동안 참을성이 부여됩니다. 참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "激活后，获得相当于你最大生命值{1}%的吸收护盾，持续{2}秒。施加自律，持续{3}分钟。自律效果激活时无法施放。", zhTW = "啟用後，獲得相當於你最大生命力{1}%的吸收護盾，持續{2}秒。施加自律，持續{3}分鐘。自律效果啟用時無法施放。" },
	["when activated, this ability immediately finishes the cooldown on your other rogue abilities"] = { ko = "활성화되면 다른 모든 도적 기술들의 재사용 대기시간이 초기화됩니다.", zhCN = "激活之后，这项技能立刻令你的其它潜行者技能的冷却时间结束。", zhTW = "啟動之後，這項技能立刻令你的其他盜賊技能的冷卻時間結束。" },
	["when activated, this ability temporarily grants you #% of your maximum health for # sec"] = { ko = "활성화 시 일시적으로 최대 생명력이 {1}%만큼 증가합니다.", zhCN = "激活后，该技能会使你暂时获得相当于最大生命值{1}%的生命值，持续{2}秒。", zhTW = "啟動之後，使你的生命力上限暫時提高{1}%，持續{2}秒。" },
	["when activated, this ability temporarily grants you #% of your maximum health for # sec. after the effect expires, the health is lost"] = { ko = "활성화 시 일시적으로 최대 생명력이 {1}%만큼 증가합니다. {2}초 동안 지속되며 지속시간이 끝나면 임시 생명력은 사라집니다.", zhCN = "激活后，该技能会使你暂时获得相当于最大生命值{1}%的生命值，持续{2}秒。效果结束后会失去这些生命值。", zhTW = "啟動之後，使你的生命力上限暫時提高{1}%，持續{2}秒。效果結束後，這些生命力會被扣除。" },
	["when activated, this spell causes each of your fire damage spell hits to increase your critical strike chance with fire damage spells by #%"] = { ko = "활성화되면 자신의 화염 공격 주문이 적중할 때마다 화염 공격 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다.", zhCN = "激活后，你的火焰伤害法术每次命中都会使你的火焰伤害法术爆击几率提高{1}%。", zhTW = "啟動之後，你每一個命中目標的火焰傷害法術會使你火焰傷害法術的致命一擊機率提高{1}%。" },
	["when activated, this spell causes each of your fire damage spell hits to increase your critical strike chance with fire damage spells by #%. this effect lasts until you have caused # non-periodic critical strikes with fire spells"] = { ko = "활성화되면 자신의 화염 공격 주문이 적중할 때마다 화염 공격 주문이 극대화 효과를 발휘할 확률이 {1}%만큼 증가합니다. {2}회의 비주기적인 극대화 효과를 발휘할 때까지 지속됩니다.", zhCN = "激活后，你的火焰伤害法术每次命中都会使你的火焰伤害法术爆击几率提高{1}%。该效果会持续到你用火焰法术造成{2}次非周期性爆击为止。", zhTW = "啟動之後，你每一個命中目標的火焰傷害法術會使你火焰傷害法術的致命一擊機率提高{1}%。此效果會持續到你的火焰法術造成{2}次非週期性致命一擊為止。" },
	["when activated, your next mage spell with a casting time less than # sec becomes an instant cast spell"] = { ko = "활성화되면 시전 시간이 {1}초 미만인 다음 주문은 시전 시간 없이 바로 발동됩니다.", zhCN = "激活之后，你的下一个施法时间低于{1}秒的法师法术会成为瞬发法术。", zhTW = "啟動之後，你的下一個施法時間低於{1}秒的法師法術會成為瞬發法術。" },
	["when activated, your next nature spell becomes an instant cast spell"] = { ko = "활성화되면 다음 자연계 주문은 시전 시간 없이 바로 발동됩니다.", zhCN = "激活之后，你的下一个自然法术会成为瞬发法术。", zhTW = "啟動之後，你的下一個自然法術會成為瞬發法術。" },
	["when activated, your next nature spell with a casting time less than # sec. becomes an instant cast spell"] = { ko = "활성화되면 시전 시간이 {1}초 미만인 다음 자연계 주문은 시전 시간 없이 바로 발동됩니다.", zhCN = "激活之后，你的下一个施法时间低于{1}秒的自然法术会成为瞬发法术。", zhTW = "啟動之後，你的下一個施法時間低於{1}秒的自然法術會成為瞬發法術。" },
	["when active, #% of all damage taken by the caster is taken by your imp, voidwalker, succubus, incubus, or felhunter demon instead"] = { ko = "활성화하면 시전자가 받는 모든 피해의 {1}%를 소환한 임프나 보이드워커, 서큐버스, 인큐버스, 지옥사냥개가 대신 받습니다.", zhCN = "激活时，施法者受到的所有伤害有{1}%由你的小鬼、虚空行者、魅魔、夜魔或地狱猎犬恶魔承受。", zhTW = "啟動之後，施法者承受的傷害有{1}%會由你的小鬼、虛無行者、魅魔、夢魔或惡魔獵犬分擔。" },
	["when active, #% of all damage taken by the caster is taken by your imp, voidwalker, succubus, incubus, or felhunter demon instead. in addition, both the demon and the master will inflict #% more damage. lasts as long as the demon is active"] = { ko = "활성화하면 시전자가 받는 모든 피해의 {1}%를 소환한 임프나 보이드워커, 서큐버스, 인큐버스, 지옥사냥개가 대신 받습니다. 추가로 흑마법사와 소환수의 공격력이 {2}%만큼 증가합니다. 소환수가 활성화된 동안 지속됩니다.", zhCN = "激活时，施法者受到的所有伤害有{1}%由你的小鬼、虚空行者、魅魔、夜魔或地狱猎犬恶魔承受。此外，恶魔和主人造成的伤害都提高{2}%。只要恶魔处于激活状态，该效果就会持续。", zhTW = "啟動之後，施法者承受的傷害有{1}%會由你的小鬼、虛無行者、魅魔、夢魔或惡魔獵犬分擔。另外，惡魔和其主人造成的傷害皆提高{2}%。只要惡魔保持啟動狀態，該效果會一直持續。" },
	["when appied to main hand, disables any benefit you personally receive from windfury totem"] = { ko = "주무기에 부여하면 질풍의 토템으로 얻는 이로운 효과가 비활성화됩니다.", zhCN = "应用于主手时，会使你无法从风怒图腾获得个人收益。" },
	["when applied to main hand, disables any benefit you personally receive from flametongue totem"] = { ko = "주장비에 부여하면 불꽃의 토템 효과를 자신은 받지 못합니다." },
	["when applied to main hand, disables any benefit you personally receive from windfury totem"] = { ko = "주무기에 부여하면 질풍의 토템으로 얻는 이로운 효과가 비활성화됩니다.", zhCN = "应用于主手时，会使你无法从风怒图腾获得个人收益。" },
	["when damaged, has a chance to grant you # armor for # sec"] = { ko = "피해를 받으면 일정 확률로 {2}초 동안 방어도가 {1}만큼 증가합니다.", zhCN = "在受到伤害时，有几率使你获得{1}点护甲值，持续{2}秒。", zhTW = "受到傷害時，有一定機率賦予你{1}點護甲值，持續{2}秒。" },
	["when damaged, has a chance to reduce threat level on all enemies by a small amount for # sec"] = { ko = "피해를 받으면 일정 확률로 {1}초 동안 모든 적에 대한 위협 수준 약간 감소합니다.", zhCN = "在受到伤害时，有一定几率小幅降低所有敌人的威胁值，持续{1}秒。", zhTW = "受到傷害時，有一定機率使你對所有敵人的威脅等級略微降低，持續{1}秒。" },
	["when seal of fury's shield is fully absorbed, restore # mana, increased by #% per level the attacker is above you, up to #%"] = { ko = "격노의 문장의 보호막이 완전히 흡수되면 {1}의 마나를 회복합니다. 회복량은 공격자가 자신보다 레벨이 높은 경우 1 레벨당 {2}%씩, 최대 {3}%까지 증가합니다.", zhCN = "愤怒圣印提供的护盾被完全吸收时，恢复{1}点法力值。攻击者每比你高一级，恢复量提高{2}%，最高提高{3}%。", zhTW = "當憤怒聖印的護盾被完全消耗時，恢復{1}點法力。攻擊者每高於你1級，法力恢復量便提高{2}%，最多提高{3}%。" },
	["when struck in combat has a #% chance of inflicting # nature damage to the attacker"] = { ko = "가격당했을 때 {1}%의 확률로 공격자에게 {2}의 자연 피해를 입힙니다.", zhCN = "在战斗中被击中时，有{1}%的几率对攻击者造成{2}点自然伤害。", zhTW = "在戰鬥中被擊中之後，有{1}%的機率對攻擊者造成{2}點自然傷害。" },
	["when struck in combat has a #% chance of inflicting # shadow damage to the attacker"] = { ko = "가격 당했을 때 {1}%의 확률로 공격자에게 {2}의 암흑 피해를 입힙니다.", zhCN = "在战斗中被敌人击中之后，有{1}%的机会对攻击者造成{2}点暗影伤害。", zhTW = "在戰鬥中被敵人擊中之後，有{1}%的機會對攻擊者造成{2}點暗影傷害。" },
	["when struck in combat inflicts # shadow damage to the attacker"] = { ko = "전투 중 공격을 받으면 공격자에게 {1}의 암흑 피해를 입힙니다.", zhCN = "在战斗中被击中时，对攻击者造成{1}点暗影伤害。", zhTW = "在戰鬥中被擊中之後，對攻擊者造成{1}點暗影傷害。" },
	["when struck in combat, drain # mana from the attacker"] = { ko = "전투 중 공격을 받으면 공격자의 마나를 {1}만큼 흡수합니다.", zhCN = "在战斗中受到攻击时，吸取攻击者{1}点法力值。", zhTW = "在戰鬥中被擊中時，從攻擊者身上吸取{1}點法力。" },
	["when struck in combat, inflicts # nature damage to the attacker"] = { ko = "가격 당했을 때 공격자에게 {1}의 자연 피해를 입힙니다." },
	["when the effect ends, the priest dies"] = { ko = "효과가 종료되면 사제는 죽습니다.", zhCN = "当救赎之魂效果结束时，牧师死亡。", zhTW = "效果結束後，牧師就會死亡。" },
	["when the felhunter is hit with a melee attack, the attacker will lose # melee attack power for # sec"] = { ko = "지옥사냥개가 근접 공격을 받으면 공격자는 {2}초 동안 {1}의 근접 전투력을 상실합니다.", zhCN = "如果它被近战攻击打中，则攻击者会损失{1}点近战攻击强度，持续{2}秒。", zhTW = "如果它被近戰攻擊打中，則攻擊者會損失{1}近戰攻擊強度，持續{2}秒。" },
	["when the heal occurs, prayer of mending jumps to a party or raid member within # yards"] = { ko = "생명력이 회복되면 {1}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다.", zhCN = "这个治疗效果发生之后，愈合祷言会转移到{1}码范围内的小队或团队成员身上。", zhTW = "當治療效果發動時，癒合禱言將會跳至半徑{1}碼範圍內的一名小隊或團隊成員身上。" },
	["when the heal occurs, prayer of mending jumps to a party or raid member within # yds"] = { ko = "생명력이 회복되면 {1}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다." },
	["when the target wakes up, the sting causes # nature damage over # sec"] = { zhCN = "当目标醒来时，钉刺会在{2}秒内对其造成{1}点自然伤害。", zhTW = "當目標醒來時，釘刺會在{2}秒內對其造成{1}點自然傷害。" },
	["when you cast a healing spell, gain mana equal to #% of the base cost of the spell if your previous heal was a different spell"] = { ko = "치유 주문을 시전할 때, 이전에 다른 주문으로 치유한 경우 이번 치유 주문의 기본 마나 소비량의 {1}%에 해당하는 마나를 회복합니다.", zhCN = "当你施放治疗法术时，若你上一次施放的是不同的治疗法术，则获得相当于本次法术基础法力消耗{1}%的法力值。", zhTW = "施放治療法術時，若此法術與你施放的上一個治療法術不同，則獲得相當於此法術基本法力消耗{1}%的法力。" },
	["when you cast shadow bolt or searing pain on an enemy below #% health, they deal #% increased damage, and for the next # sec your soul fire spell has its cast time reduced by #% and costs no soul shards"] = { ko = "생명력이 {1}% 미만인 적에게 어둠의 화살 또는 불타는 고통을 시전하면 {2}%의 추가 피해를 입히며, 다음 {3}초 동안 영혼의 불꽃의 시전 시간이 {4}%만큼 감소하고 영혼의 조각을 소모하지 않습니다.", zhCN = "当你对生命值低于{1}%的敌人施放暗影箭或灼热之痛时，这些法术造成的伤害提高{2}%，并且在接下来的{3}秒内，你的灵魂之火施法时间缩短{4}%，且不消耗灵魂碎片。", zhTW = "當你對生命力低於{1}%的敵人施放暗影箭或灼熱之痛時，其造成的傷害提高{2}%，同時在接下來的{3}秒內，你靈魂之火法術的施法時間縮短{4}%，且不消耗靈魂裂片。" },
	["when you deal damage with a melee attack, you have a chance to reduce the cast time and mana cost of your next lightning bolt spell by #%"] = { ko = "근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살의 시전 시간과 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "近战攻击造成伤害时，你有几率使下一个闪电箭的施法时间和法力消耗降低{1}%。" },
	["when you deal damage with a melee attack, you have a chance to reduce the cast time and mana cost of your next lightning bolt spell by #%. stacks up to # times. lasts # sec"] = { ko = "근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살의 시전 시간과 마나 소모량이 {1}%만큼 감소합니다. 최대 {2}번까지 중첩됩니다. {3}초 동안 지속됩니다.", zhCN = "近战攻击造成伤害时，你有几率使下一个闪电箭的施法时间和法力消耗降低{1}%。最多叠加{2}次。持续{3}秒。", zhTW = "當你的近戰攻擊造成傷害時，你有一定的機率使你的下一個閃電箭的施法時間與法力消耗降低{1}%。最多可堆疊{2}次，持續{3}秒。" },
	["when you gain mana from life tap, your summoned demon gains #% of the mana you gain"] = { ko = "생명력 전환으로 마나를 회복하면, 소환된 악마가 회복한 마나의 {1}%를 얻습니다.", zhCN = "通过生命分流获得法力时，召唤的恶魔会获得相当于你所得法力{1}%的法力。", zhTW = "當你從生命分流獲得法力時，你召喚的惡魔將得到相當於你獲得{1}%的法力。" },
	["when you shift into cat form, you will regain #% of the energy you had when you were last in cat form, plus # energy for each second you spent not in bear form, cat form, or dire bear form, up to a maximum of # energy"] = { ko = "또한 표범 변신 시 지난 표범 변신 상태일 때 보유했던 기력의 {1}%를 다시 회복하며, 추가로 곰 변신이나 표범 변신, 광포한 곰 변신 상태가 아니었던 시간 1초당 기력을 {2}만큼, 최대 {3}만큼 생성합니다.", zhCN = "当你变身为猎豹形态时，将恢复上次处于猎豹形态时所拥有能量的{1}%，外加你在未处于熊形态、猎豹形态或巨熊形态的每秒{2}点能量，最多{3}点能量。", zhTW = "當你變身為獵豹形態時，將恢復上次處於獵豹形態時所擁有能量的{1}%，外加你在未處於熊形態、獵豹形態或巨熊形態的每秒{2}點能量，最多{3}點能量。" },
	["when you stormstrike, you have a #% chance to gain #% mana regeneration while casting spells for # sec, and stormstrike's cooldown has a #% chance to reset each time you dodge or parry"] = { ko = "폭풍의 일격 사용 시 {1}%의 확률로 {3}초 동안 주문을 시전할 때 마나 회복 속도가 {2}%만큼 증가합니다. 또한 공격을 회피하거나 무기로 막을 때마다 {4}%의 확률로 폭풍의 일격의 재사용 대기시간이 초기화됩니다.", zhCN = "使用风暴打击时，你有{1}%的几率获得{2}%的施法时法力回复，持续{3}秒；每当你躲闪或招架时，风暴打击的冷却时间有{4}%的几率重置。", zhTW = "施放風暴打擊時，你有{1}%的機率在施放法術時獲得你{2}%法力恢復速度的法力，持續{3}秒，且每次你閃躲或招架時，有{4}%的機率重置風暴打擊的冷卻時間。" },
	["when your rupture ability deals periodic damage, the energy cost of your next hemorrhage or backstab ability within # sec is reduced by #, stacking up to # times"] = { ko = "파열로 주기적인 피해를 입히면 {1}초 안에 사용하는 다음 과다출혈 또는 기습의 기력 소모량이 {2}만큼 감소합니다. 최대 {3}번까지 중첩됩니다.", zhCN = "当你的割裂造成周期性伤害时，使你在{1}秒内下一次出血或背刺消耗的能量值降低{2}点，最多叠加{3}次。", zhTW = "當你的割裂技能造成週期性傷害，你在{1}秒內施放的下一個出血或背刺技能的能量消耗降低{2}點，最多可堆疊{3}層。" },
	["when your traps are triggered, all affected targets are entrapped, preventing them from moving for # sec"] = { ko = "덫 발동 시 영향을 받는 모든 대상이 덫에 걸림 상태가 되어 {1}초 동안 이동하지 못하게 됩니다.", zhCN = "当你的陷阱被触发时，所有受影响的目标被诱捕，无法移动，持续{1}秒。", zhTW = "當你的陷阱觸發時，所有受影響目標都會被困住，令其無法移動，持續{1}秒。" },
	["whenever you suffer bleed damage, one dose is spread to a nearby enemy within # yds"] = { ko = "출혈 피해를 받을 때마다 {1}미터 내의 주위 적에게 맹독성 피를 1회 살포합니다.", zhCN = "每当你受到流血伤害时，就会有一层毒血传播给{1}码内的一名附近敌人。", zhTW = "每當你受到流血傷害時，會將一層效果濺射至附近{1}碼範圍內的一個敵人。" },
	["while a shield is equipped, each attack also grants an absorb shield equal to #% of the holy damage dealt"] = { ko = "방패를 장착하고 있으면 공격할 때마다 입힌 신성 피해의 {1}%만큼 피해를 흡수하는 보호막도 얻습니다.", zhCN = "装备盾牌时，每次攻击还会获得相当于所造成神圣伤害{1}%的吸收护盾。", zhTW = "裝備盾牌時，每次攻擊也會賦予相當於所造成神聖傷害{1}%的吸收護盾。" },
	["while affected, the target cannot stealth or turn invisible"] = { ko = "효과가 지속되는 동안은 은신이나 투명화가 불가능합니다.", zhCN = "在效果持续期间，目标无法潜行或隐形。", zhTW = "在效果持續期間，目標無法潛行或隱形。" },
	["while aspect of the beast is active, all melee auto attacks have a #% chance of increasing melee attack speed by #% for # sec"] = { ko = "야수의 상이 활성화된 동안에는 모든 근접 자동 공격이 {1}%의 확률로 {3}초 동안 근접 공격 속도를 {2}%만큼 증가시킵니다.", zhCN = "野兽守护激活时，所有近战自动攻击都有{1}%的几率使近战攻击速度提高{2}%，持续{3}秒。", zhTW = "在野獸守護作用期間，所有近戰自動攻擊會有{1}%的機率使近戰攻擊速度提高{2}%，持續{3}秒。" },
	["while aspect of the hawk is active, auto shot has a #% chance of increasing ranged attack speed by #% for # sec"] = { ko = "매의 상이 활성화된 동안에는 자동 사격 사용 시 {1}%의 확률로 {3}초 동안 원거리 공격 속도가 {2}%만큼 증가합니다.", zhCN = "雄鹰守护激活时，自动射击有{1}%的几率使远程攻击速度提高{2}%，持续{3}秒。", zhTW = "在雄鷹守護作用期間，自動射擊會有{1}%的機率使遠程攻擊速度提高{2}%，持續{3}秒。" },
	["while aspect of the hawk is active, auto shot has a #% chance of increasing ranged attack speed by #% for # sec. while aspect of the beast is active, all melee auto attacks have a #% chance of increasing melee attack speed by #% for # sec"] = { ko = "매의 상이 활성화된 동안에는 자동 사격 사용 시 {1}%의 확률로 {3}초 동안 원거리 공격 속도가 {2}%만큼 증가합니다. 야수의 상이 활성화된 동안에는 모든 근접 자동 공격이 {4}%의 확률로 {6}초 동안 근접 공격 속도를 {5}%만큼 증가시킵니다.", zhCN = "雄鹰守护激活时，自动射击有{1}%的几率使远程攻击速度提高{2}%，持续{3}秒。野兽守护激活时，所有近战自动攻击都有{4}%的几率使近战攻击速度提高{5}%，持续{6}秒。", zhTW = "在雄鷹守護作用期間，自動射擊會有{1}%的機率使遠程攻擊速度提高{2}%，持續{3}秒。在野獸守護作用期間，所有近戰自動攻擊會有{4}%的機率使近戰攻擊速度提高{5}%，持續{6}秒。" },
	["while channeling this spell, your mana regeneration is active and increased by #,#%"] = { ko = "이 주문을 사용하는 중에는 마나 회복 속도가 {1},{2}%만큼 증가하여 마나 회복이 이루어집니다.", zhCN = "在引导此法术时，你的法力值回复速度提高{1},{2}%。", zhTW = "在引導此法術時，你的法力回復速度提高{1},{2}%。" },
	["while channeling this spell, your mana regeneration is active and increased by #,#%. lasts # sec"] = { ko = "이 주문을 사용하는 중에는 마나 회복 속도가 {1},{2}%만큼 증가하여 마나 회복이 이루어집니다. {3}초 동안 지속됩니다.", zhCN = "在引导此法术时，你的法力值回复速度提高{1},{2}%。持续{3}秒。", zhTW = "在引導此法術時，你的法力回復速度提高{1},{2}%。持續{3}秒。" },
	["while enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed"] = { ko = "광포한 동안엔 어떠한 방법으로도 공격을 저지할 수 없습니다.", zhCN = "在这种状态下，宠物不会有任何恐惧或怜悯，也无法停止下来，除非被杀死。", zhTW = "在這種狀態下，寵物不會有任何憐憫、自責或恐懼，也無法被阻止，除非被殺死。" },
	["while in bear form, cat form, dire bear form, or moonkin form, you gain # additional base armor per level and another # base armor for each point of defense skill beyond five times your level"] = { zhCN = "处于熊形态、猎豹形态、巨熊形态或枭兽形态时，你每级获得{1}点额外基础护甲；防御技能超过你等级五倍后，每一点还会提供{2}点基础护甲。", zhTW = "在熊形態、獵豹形態、巨熊形態或梟獸形態下，你根據等級獲得{1}點額外基礎護甲值，並根據防禦技能高於等級五倍的點數，每點額外獲得{2}點基礎護甲值。" },
	["while in bear form, cat form, dire bear form, or moonkin form, you gain # additional base armor per level and another # base armor for each point of defense skill beyond five times your level. this amount can be further increased by multipliers from those forms"] = { ko = "곰 변신, 표범 변신, 광포한 곰 변신 또는 달빛야수 변신 상태일 때 레벨당 기본 방어도가 {1}만큼 증가합니다. 또한 자신의 레벨의 5배를 초과하는 방어 숙련도 1점당 기본 방어도가 {2}만큼 추가로 증가합니다. 이 수치는 해당 변신의 배수에 비례합니다.", zhCN = "处于熊形态、猎豹形态、巨熊形态或枭兽形态时，你每级获得{1}点额外基础护甲；防御技能超过你等级五倍后，每一点还会提供{2}点基础护甲。该数值可进一步受到这些形态的倍率加成。", zhTW = "在熊形態、獵豹形態、巨熊形態或梟獸形態下，你根據等級獲得{1}點額外基礎護甲值，並根據防禦技能高於等級五倍的點數，每點額外獲得{2}點基礎護甲值。那些形態的加成可以進一步提高此數值。" },
	["while in cat form, bear form, or dire bear form, the leader of the pack increases the critical strike chance of all party members within # yards by #%, exclusive with moonkin aura"] = { ko = "표범 변신, 곰 변신 또는 광포한 곰 변신 상태에서 무리의 우두머리가 주위 {1}미터 반경 내에 있는 모든 파티원의 치명타 및 극대화율을 {2}%만큼 증가시킵니다. 달빛야수 오라와 겸용해서 사용할 수 없습니다.", zhCN = "处于猎豹、熊或巨熊形态时，兽群领袖使{1}码内所有小队成员的爆击几率提高{2}%。不可与枭兽光环共存。", zhTW = "在獵豹形態、熊形態或巨熊形態下，獸群領袖使半徑{1}碼範圍內的所有小隊成員的致命一擊機率提高{2}%，但不可與梟獸光環並用。" },
	["while in desolace, your movement speed is also increased by #% and this transformation persists through combat"] = { ko = "잊혀진 땅에 있는 동안 이동 속도가 {1}%만큼 증가하며, 이 변신은 전투 중에도 지속됩니다.", zhCN = "在凄凉之地时，你的移动速度也将提高{1}%，并且此变形效果在战斗中依然持续。", zhTW = "在淒涼之地中，你的移動速度也會提高{1}%，且此變形效果在戰鬥之後仍然有效。" },
	["while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% critical strike chance"] = { ko = "하이잘 산과 하이잘 정상, 지하굴에서 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "在海加尔山、海加尔峰和深穴内，你还会获得{1}%的爆击几率。", zhTW = "在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{1}%致命一擊機率。" },
	["while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% haste"] = { ko = "하이잘 산과 하이잘 정상, 지하굴에서 가속이 {1}%만큼 증가합니다.", zhCN = "在海加尔山、海加尔峰和深穴内，你还会获得{1}%的急速。", zhTW = "在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{1}%加速。" },
	["while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% hit chance"] = { ko = "하이잘 산과 하이잘 정상, 지하굴에서 적중률이 {1}%만큼 증가합니다.", zhCN = "在海加尔山、海加尔峰和深穴内，你还会获得{1}%的命中几率。", zhTW = "在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{1}%命中機率。" },
	["while in mount hyjal, hyjal summit, and the barrow deeps, you also gain #% reduced chance to be dodged or parried"] = { ko = "하이잘 산과 하이잘 정상, 지하굴에서 공격이 회피되거나 무기 막기에 막힐 확률이 {1}%만큼 감소합니다.", zhCN = "在海加尔山、海加尔峰和深穴内，你的攻击被躲闪或招架的几率还会降低{1}%。", zhTW = "在海加爾山、海加爾山之巔和地深獸穴時，你被閃躲或招架的機率還會降低{1}%。" },
	["while in this form the priest can cast any healing spell free of cost"] = { ko = "이 형태에서는 모든 치유 주문을 마나 소비 없이 사용할 수 있습니다.", zhCN = "在这个形态下，牧师可以施放任何治疗法术，不需消耗任何法力值。", zhTW = "進入此形態，牧師可不消耗能量施放任何治療法術。" },
	["while levitating, you will fall at a reduced speed and travel over water-like surfaces"] = { ko = "공중 부양 중에는 낙하 속도가 감소하며 물 위를 걸을 수 있습니다.", zhCN = "漂浮时，你的下落速度降低，并可在水面等表面上移动。" },
	["while righteous fury is active, all damage taken is reduced by #%"] = { ko = "정의의 격노가 활성화되어 있는 동안 받는 모든 피해가 {1}%만큼 감소합니다.", zhCN = "当正义之怒处于激活状态时，你所承受的一切伤害降低{1}%。", zhTW = "正義之怒啟動時，可使你受到的所有傷害降低{1}%。" },
	["while righteous fury is active, holy strike also reduces your damage taken by #% for # sec"] = { ko = "정의의 격노가 활성화되어 있는 동안에는 신성한 일격이 {2}초 동안 받는 피해를 {1}%만큼 감소시킵니다.", zhCN = "在正义之怒激活时，神圣打击还会使你受到的伤害降低{1}%，持续{2}秒。", zhTW = "在正義之怒啟用時，神聖打擊還會使你受到的傷害降低{1}%，持續{2}秒。" },
	["while subjugated, the time between the demon's attacks is increased by #% and its casting speed is slowed by #%"] = { ko = "예속된 상태에서는 대상 악마의 공격 간격이 {1}%만큼 늘어나고 주문 시전 속도가 {2}%만큼 감소합니다.", zhCN = "被征服的恶魔的攻击间隔延长{1}%，施法速度降低{2}%。", zhTW = "被制伏的惡魔攻擊間隔時間延長{1}%，施法速度降低{2}%。" },
	["while the shield holds, spellcasting will not be interrupted by damage"] = { ko = "보호막이 지속되는 동안은 피해에 의해 주문 시전이 방해받지 않습니다.", zhCN = "护盾存在期间，其施法不会因受到伤害而被打断。", zhTW = "只要護盾存在，受保護者的施法就不會被傷害打斷。" },
	["while the shield holds, your spellcasts will not be interrupted or delayed from taking damage"] = { ko = "보호막이 지속되는 동안에는 주문 시전 중 피해를 받아도 방해받거나 지연되지 않습니다." },
	["while tracking beasts, demons, dragonkin, elementals, giants, humanoids, or undead, all damage you deal to the tracked creature type is increased by #%"] = { ko = "야수, 악마, 용족, 정령, 거인, 인간형, 언데드를 추적하는 동안, 해당 추적 생명체 유형에 입히는 모든 피해가 {1}%만큼 증가합니다.", zhCN = "在追踪野兽、恶魔、龙类、元素生物、巨人、人型生物或亡灵时，你对该被追踪生物类型造成的所有伤害提高{1}%。", zhTW = "當你追蹤野獸、惡魔、龍類、元素生物、巨人、人形生物和不死生物時，你對所追蹤生物類型造成的所有傷害提高{1}%。" },
	["while you are not moving for # sec, nearby moving stealthed enemies may reveal a heat trail"] = { ko = "{1}초 동안 움직이지 않으면 주위의 은신한 적이 움직일 때 열기 흔적이 드러날 수 있습니다.", zhCN = "静止不动{1}秒后，附近正在移动的潜行敌人可能显露出热力轨迹。", zhTW = "當你靜止不動{1}秒時，附近移動中的潛行敵人可能會顯現熱成像痕跡。" },
	["while you are protected, damaging attacks will not cause spellcasting delays"] = { ko = "효과가 지속되는 동안에는 공격에 의해 시전 시간이 지연되지 않습니다.", zhCN = "受保护期间，受到伤害不会导致施法延迟。" },
	["while your pet is active, you and your pet will regenerate #% of total health every # sec"] = { ko = "활성화되면 자신과 야수 모두 {2}초마다 전체 생명력의 {1}%에 달하는 생명력이 회복됩니다.", zhCN = "当你的宠物被激活后，你和你的宠物都会每{2}秒回复{1}%的生命值。", zhTW = "只要你的寵物處於活動狀態，你與你的寵物都會每{2}秒恢復總生命力{1}%的生命力。" },
	["will affect up to # targets"] = { ko = "최대 {1}개의 대상에게 영향을 미칩니다.", zhCN = "最多影响{1}个目标。", zhTW = "最多可影響{1}個目標。" },
	["will not work if the target is in another instance or on another continent"] = { ko = "대상이 다른 대륙이나 인스턴스 지역에 있을 때는 사용할 수 없습니다.", zhCN = "如果该目标身处另一个副本区域或另一块大陆则无法施展。", zhTW = "如果該目標身處另一個副本區域或另一塊大陸則無法施展。" },
	["wounds the target causing them to bleed for # damage over # sec"] = { ko = "적에게 깊은 상처를 입혀 출혈을 일으킵니다. {2}초에 걸쳐 총 {1}의 피해를 입힙니다.", zhCN = "使目标的伤口不断流血，在{2}秒内造成累计{1}点伤害。", zhTW = "使目標的傷口不斷流血，在{2}秒內造成累計{1}點傷害。" },
	["wounds the target for # damage"] = { ko = "대상에게 상처를 입혀 {1}의 피해를 입힙니다.", zhCN = "对目标造成{1}点伤害。", zhTW = "重創目標，造成{1}點傷害。" },
	["wounds the target for # damage. naga are stunned for # sec"] = { ko = "대상에게 상처를 입혀 {1}의 피해를 입힙니다. 나가는 {2}초 동안 기절합니다.", zhCN = "对目标造成{1}点伤害。若目标为纳迦，则还会昏迷{2}秒。", zhTW = "重創目標，造成{1}點傷害。納迦會昏迷{2}秒。" },
	["wounds the target for # physical damage"] = { ko = "상처를 내 {1}의 물리 피해를 입힙니다.", zhCN = "对目标造成{1}点物理伤害。", zhTW = "對目標造成{1}點物理傷害。" },
	["yanks the caster through the twisting nether back to hearthstone location"] = { ko = "복잡하게 꼬인 영혼의 세계를 통과하여 귀환석 위치로 귀환합니다.", zhCN = "令施法者穿越扭曲虚空，回到 。", zhTW = "令施法者穿越扭曲虛空，回到 。" },
	["yanks the caster through the twisting nether back to hearthstone location. speak to an innkeeper in a different place to change your home location"] = { ko = "복잡하게 꼬인 영혼의 세계를 통과하여 귀환석 위치로 귀환합니다. 귀환 장소를 변경하려면 여관주인과 대화하십시오.", zhCN = "令施法者穿越扭曲虚空，回到 。与不同地区的旅店老板谈话可以改变你的家所在的位置。", zhTW = "令施法者穿越扭曲虛空，回到 。與不同地區的旅店老闆談話可以改變你的家所在的位置。" },
	["you are protected from all physical attacks and spells for # sec, but during that time you cannot attack or use physical abilities yourself"] = { zhCN = "使你免受一切物理攻击和法术，持续{1}秒，但在此期间你不能攻击或使用物理技能。", zhTW = "讓你免受一切物理和法術攻擊，持續{1}秒，但是在這段時間內你不能攻擊或者使用非法術類的能力。" },
	["you are protected from all physical attacks and spells for # sec, but during that time you cannot attack or use physical abilities yourself. applies forbearance for # min. cannot be cast while forbearance is active"] = { ko = "{1}초 동안 어떠한 주문이나 물리 공격에도 피해를 받지 않습니다. 하지만 이 동안 공격하거나 물리 능력을 사용할 수 없습니다. {2}분 동안 참을성이 부여됩니다. 참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "使你免受一切物理攻击和法术，持续{1}秒，但在此期间你不能攻击或使用物理技能。施加自律，持续{2}分钟。自律效果激活时无法施放。", zhTW = "讓你免受一切物理和法術攻擊，持續{1}秒，但是在這段時間內你不能攻擊或者使用非法術類的能力。施加自律效果，持續{2}分鐘。自律效果生效期間，無法施放。" },
	["you become encased in a block of ice, protecting you from all physical attacks and spells for # sec, but during that time you cannot attack, move, or cast spells"] = { ko = "커다란 얼음 덩어리에 둘러싸여 {1}초 동안 모든 물리 공격과 주문으로부터 보호받습니다. 하지만 이 동안은 공격하거나 이동하거나 마법을 사용하지 못합니다.", zhCN = "你被封在一块寒冰中，在{1}秒内免受所有物理攻击和法术影响，但在此期间无法攻击、移动或施法。", zhTW = "你被一道寒冰屏障所籠罩，在{1}秒內對所有物理攻擊和法術免疫，但是在這段期間內你也無法攻擊、移動或施法。" },
	["you can create and mix poisons, with both found and storebought ingredients"] = { ko = "곳곳에서 발견한 재료와 상인에게서 구입한 재료를 혼합하여 독을 조제할 수 있습니다.", zhCN = "你可以使用各种材料制造并调配毒药。", zhTW = "你可以使用各種材料製造並調配毒藥。" },
	["you can only have the effect of one flask at a time"] = { ko = "영약은 동시에 하나만 사용할 수 있습니다.", zhCN = "你同时只能获得一种合剂的效果。", zhTW = "你同時只能有一種精煉藥劑的效果。" },
	["you deal #% increased damage with all attacks while you do not have an active pet"] = { ko = "활성화된 야수가 없을 때 모든 공격의 공격력이 {1}%만큼 증가합니다.", zhCN = "没有激活的宠物时，你的所有攻击造成的伤害提高{1}%。", zhTW = "當你沒有啟用寵物時，你所有攻擊造成的傷害提高{1}%。" },
	["you heal your pet for #% of all spell damage you deal"] = { ko = "입히는 모든 주문 피해의 {1}%만큼 소환수를 치유합니다.", zhCN = "你造成的所有法术伤害会为宠物恢复相当于该伤害{1}%的生命值。", zhTW = "你為寵物治療相當於你造成的{1}%所有法術傷害的生命力。" },
	["you heal your pet for #% of all spell damage you deal. when you gain mana from life tap, your summoned demon gains #% of the mana you gain"] = { ko = "입히는 모든 주문 피해의 {1}%만큼 소환수를 치유합니다. 생명력 전환으로 마나를 회복하면, 소환된 악마가 회복한 마나의 {2}%를 얻습니다.", zhCN = "你造成的所有法术伤害会为宠物恢复相当于该伤害{1}%的生命值。通过生命分流获得法力时，召唤的恶魔会获得相当于你所得法力{2}%的法力。", zhTW = "你為寵物治療相當於你造成的{1}%所有法術傷害的生命力。當你從生命分流獲得法力時，你召喚的惡魔將得到相當於你獲得{2}%的法力。" },
	["you hurl molten lava at the target, dealing # to # fire damage"] = { ko = "대상에게 용해된 용암을 날려 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "向目标掷出熔岩，造成{1}至{2}点火焰伤害。", zhTW = "你對目標射出熔岩，造成{1}至{2}點火焰傷害。" },
	["you hurl molten lava at the target, dealing # to # fire damage. if your flame shock is on the target, lava burst deals #% increased damage"] = { ko = "대상에게 용해된 용암을 날려 {1}~{2}의 화염 피해를 입힙니다. 대상에 화염 충격 효과가 걸려 있으면 용암 폭발이 {3}%의 추가 피해를 입힙니다.", zhCN = "向目标掷出熔岩，造成{1}至{2}点火焰伤害。如果目标受到你的烈焰震击影响，熔岩爆裂造成的伤害提高{3}%。", zhTW = "你對目標射出熔岩，造成{1}至{2}點火焰傷害。若目標已受烈焰震擊影響時，熔岩爆發造成的傷害提高{3}%。" },
	["you may only have # target rooted at a time"] = { ko = "동시에 한 명의 대상을 이동 불가 상태로 만들 수 있습니다.", zhCN = "同一时间内，你可以定身仅{1}个目标。", zhTW = "你同一時間只能將{1}個目標定身。" },
	["you may only have one light's vigil active per party"] = { ko = "빛의 경계는 파티당 하나만 유지할 수 있습니다." },
	["you must add to or use those combo points within # sec or the combo points are lost"] = { ko = "{1}초 내에 연계 점수를 추가하거나 추가된 연계 점수를 사용하지 않으면 연계 점수가 사라집니다.", zhCN = "你必须在{1}秒内增加或消耗这些连击点数，否则它们就会消失。", zhTW = "你必須在{1}秒內追加或消耗掉這些點數，否則它們就會消失。" },
	["you retain up to # rage when you change stances"] = { ko = "태세를 변경할 때 최대 {1}의 분노가 유지됩니다.", zhCN = "切换姿态时，你最多保留{1}点怒气。", zhTW = "在改變姿態的時候你可以保留最多{1}點怒氣。" },
	["your armor is reduced by #% while you focus on taming the beast for # sec"] = { ko = "야수를 길들이는 데 집중하는 {2}초 동안은 방어도가 {1}%만큼 감소합니다." },
	["your attacks against targets with hunter's mark have a #% chance to activate your mongoose bite for # sec"] = { ko = "사냥꾼의 징표에 걸린 대상을 공격하면 {1}%의 확률로 {2}초 동안 살쾡이의 이빨이 활성화됩니다.", zhCN = "你对带有猎人印记的目标的攻击有{1}%的几率激活猫鼬撕咬，持续{2}秒。", zhTW = "攻擊受到獵人印記影響的目標時，你有{1}%的機率觸發貓鼬撕咬，持續{2}秒。" },
	["your backstab has a #% chance to cause your next ambush within # sec to not require stealth"] = { ko = "기습 사용 시 {1}%의 확률로 {2}초 안에 다음 매복을 은신 상태가 아니어도 사용할 수 있도록 합니다.", zhCN = "你的背刺有{1}%的几率使你在{2}秒内的下一个伏击不需要潜行。", zhTW = "你的背刺有{1}%的機率使你在{2}秒內施放的下一個伏擊不需要你處於潛行狀態。" },
	["your berserker rage ability will instantly generate # rage and has a #% chance to remove all movement impairing effects when activated"] = { ko = "광전사의 격노를 활성화하는 즉시 {1}의 분노를 생성하고 {2}%의 확률로 모든 이동 방해 효과를 제거합니다.", zhCN = "你的狂暴之怒激活时会立即获得{1}点怒气，并有{2}%的几率移除所有移动限制效果。", zhTW = "啟動時，你的狂暴之怒技能會立刻產生{1}點怒氣，並有{2}%的機率移除所有移動限制效果。" },
	["your casts of greater heal, healing touch, healing wave, or holy light in combat grant up to # increased healing and up to # increased damage for # sec"] = { ko = "전투에서 상급 치유, 치유의 손길, 치유의 물결 또는 성스러운 빛 시전 시 {3}초 동안 치유량이 최대 {1}만큼, 공격력이 최대 {2}만큼 증가합니다.", zhCN = "你在战斗中施放的强效治疗术、治疗之触、治疗波或圣光术会使你的治疗效果提高最多{1}点，伤害提高最多{2}点，持续{3}秒。", zhTW = "你在戰鬥中施放強效治療術、治療之觸、治療波或聖光術時，使治療效果最多提高{1}點，傷害最多提高{2}點，持續{3}秒。" },
	["your charge ability is now usable while in defensive stance"] = { ko = "방어 태세일 때도 돌진을 사용할 수 있게 됩니다.", zhCN = "你的冲锋技能现在可以在防御姿态下使用。", zhTW = "你現在可以在防禦姿態下使用衝鋒。" },
	["your counterspell also silences the target for # sec"] = { ko = "마법 차단 시 {1}초 동안 대상을 침묵시킵니다.", zhCN = "你的法术反制还会使目标沉默{1}秒。", zhTW = "你的法術反制同時使目標沉默{1}秒。" },
	["your critical heals create a protective shield on the target, absorbing #% of the amount healed"] = { ko = "치유 주문이 극대화 효과를 발휘하면 대상에게 치유량의 {1}%만큼 피해를 흡수하는 보호막을 생성합니다.", zhCN = "你的极效治疗会在目标身上生成一道保护性护盾，吸收相当于治疗量{1}%的伤害。" },
	["your critical heals create a protective shield on the target, absorbing #% of the amount healed. lasts # sec"] = { ko = "치유 주문이 극대화 효과를 발휘하면 대상에게 치유량의 {1}%만큼 피해를 흡수하는 보호막을 생성합니다. {2}초 동안 지속됩니다.", zhCN = "你的极效治疗会在目标身上生成一道保护性护盾，吸收相当于治疗量{1}%的伤害。持续{2}秒。", zhTW = "你的極效治療效果將在目標身上生成一個護盾，可吸收該法術{1}%治療量的傷害，持續{2}秒。" },
	["your critical strikes cause your opponent to bleed, dealing #% of your melee weapon's average damage over # sec"] = { ko = "적에게 치명타 및 극대화 공격을 적중시키면 출혈을 일으켜 {2}초에 걸쳐 근접 무기 평균 공격력의 {1}%에 해당하는 피해를 입힙니다.", zhCN = "你的爆击会使对手流血，在{2}秒内造成相当于你近战武器平均伤害{1}%的伤害。", zhTW = "你的致命一擊導致目標流血，在{2}秒內造成相當於你的近戰武器{1}%的平均傷害。" },
	["your critical strikes from abilities that add combo points have a #% chance to add an additional combo point"] = { ko = "연계 점수가 주어지는 기술로 적에게 치명타 공격을 적중시킬 경우 {1}%의 확률로 연계 점수가 추가됩니다.", zhCN = "可增加连击点数的技能造成爆击时，有{1}%的几率额外增加一个连击点数。", zhTW = "你的所有可以增加連擊點數的技能造成了致命一擊後有{1}%的機率增加一個額外的連擊點數。" },
	["your critical strikes from fire damage spells cause the target to burn for an additional #% of your spell's damage over # sec"] = { ko = "화염 주문이 치명타로 적중했을 때, 입힌 피해의 {1}%에 해당하는 추가 피해를 {2}초에 걸쳐 입힙니다.", zhCN = "你的火焰伤害法术造成爆击后会使目标燃烧，在{2}秒内额外造成相当于该法术伤害{1}%的伤害。", zhTW = "你的火焰法術在造成致命一擊後使目標燃燒，令其在{2}秒內承受相當於該法術傷害{1}%的額外傷害。" },
	["your demonic sacrifice effect is no longer cancelled by summoning a different demon pet"] = { ko = "다른 악마 소환수를 소환해도 악마의 제물 효과가 취소되지 않습니다.", zhCN = "你的恶魔牺牲效果不再因召唤其它不同的恶魔宠物而取消。", zhTW = "你的惡魔犧牲效果不再會因召喚不同的惡魔寵物而取消。" },
	["your demonic sacrifice effect is no longer cancelled by summoning a different demon pet. resummoning the sacrificed pet will still cancel the effect"] = { ko = "다른 악마 소환수를 소환해도 악마의 제물 효과가 취소되지 않습니다. 단, 제물로 바친 소환수를 재소환하는 경우에는 효과가 취소됩니다.", zhCN = "你的恶魔牺牲效果不再因召唤其它不同的恶魔宠物而取消。重新召唤已被牺牲的宠物仍会取消该效果。", zhTW = "你的惡魔犧牲效果不再會因召喚不同的惡魔寵物而取消。重新召喚已被犧牲的寵物仍會取消效果。" },
	["your earthbind totem immobilizes nearby targets for # sec when cast"] = { ko = "속박의 토템 시전 시 주위 대상을 {1}초 동안 이동 불가 상태로 만듭니다.", zhCN = "施放地缚图腾时，使附近目标无法移动{1}秒。", zhTW = "施放地縛圖騰時，會使附近目標無法移動，持續{1}秒。" },
	["your enrage, berserker rage, bloodrage, death wish, and bloodthirst abilities cause your next # melee attacks to restore #% of your maximum health"] = { ko = "격노, 광전사의 격노, 피의 분노, 죽음의 소원, 피의 갈증이 발동하면 다음 근접 공격 {1}회가 각각 최대 생명력의 {2}%를 회복시킵니다." },
	["your finishing moves have a #% chance per combo point to restore # energy"] = { ko = "마무리 일격 사용 시 {1}%의 확률로 소모한 연계 점수당 {2}의 기력을 회복합니다.", zhCN = "你的终结技每消耗一个连击点数都有{1}%的几率恢复{2}点能量。", zhTW = "使用終結技時，每個連擊點數有{1}%的機率恢復{2}點能量。" },
	["your fire and frost critical strikes will refund #% of their base mana cost"] = { ko = "화염 및 냉기 주문이 극대화 효과를 발휘할 경우 해당 주문 기본 마나 소모량의 {1}%를 되돌려받습니다.", zhCN = "你的火焰和冰霜法术造成爆击时，会返还其基础法力消耗的{1}%。", zhTW = "使你的火焰和冰霜法術在造成致命一擊後將返還{1}%基礎法力消耗。" },
	["your heals from flash heal, binding heal, lesser heal, heal, greater heal, and penance gain #% increased critical strike chance when cast on targets with weakened soul, and reduce the remaining duration of weakened soul on their target by # sec"] = { ko = "약화된 영혼이 부여된 대상에게 순간 치유, 결속의 치유, 하급 치유, 치유, 상급 치유, 회개 시전 시 치유 효과의 치명타 및 극대화율이 {1}%만큼 증가하며, 대상에게 부여된 약화된 영혼의 남은 지속시간이 {2}초만큼 감소합니다.", zhCN = "你对具有虚弱灵魂的目标施放的快速治疗、联结治疗、次级治疗术、治疗术、强效治疗术和苦修的爆击几率提高{1}%，并使目标身上虚弱灵魂的剩余持续时间缩短{2}秒。", zhTW = "當你對虛弱靈魂的目標施放快速治療、束縛治療、次級治療術、治療術、強效治療術和懺悟時，造成極效治療的機率提高{1}%，並使目標的虛弱靈魂的剩餘持續時間縮短{2}秒。" },
	["your holy shock and flash of light critical hits reduce the cast time of your next holy light cast within # sec by # sec"] = { ko = "신성 충격 및 빛의 섬광이 극대화 효과를 발휘하면 {1}초 안에 시전하는 다음 성스러운 빛의 시전 시간이 {2}초만큼 감소합니다.", zhCN = "你的神圣震击和圣光闪现造成爆击时，使你在{1}秒内下一次圣光术的施法时间缩短{2}秒。", zhTW = "你的神聖震擊和聖光閃現造成致命一擊時，使你在{1}秒內施放的下一個聖光術的施法時間縮短{2}秒。" },
	["your lacerate hits have a #% chance to reset the cooldown on mangle (bear)"] = { ko = "가르기 적중 시 {1}%의 확률로 짓이기기(곰)의 재사용 대기시간이 초기화됩니다.", zhCN = "你的割伤有{1}%的几率重置割碎（熊）的冷却时间。", zhTW = "你的割裂命中時，有{1}%的機率重置割碎（熊形態）的冷卻時間。" },
	["your main hand melee attacks against enemies afflicted by your rend have a #% chance to allow the use of your overpower ability on the target"] = { ko = "자신의 분쇄에 걸린 적을 주 장비 근접 공격으로 공격하면 {1}%의 확률로 대상에게 제압을 사용할 수 있게 됩니다." },
	["your main hand melee attacks against enemies afflicted by your rend have a #% chance to allow the use of your overpower ability on the target. lasts # sec"] = { ko = "자신의 분쇄에 걸린 적을 주 장비 근접 공격으로 공격하면 {1}%의 확률로 대상에게 제압을 사용할 수 있게 됩니다. {2}초 동안 지속됩니다.", zhCN = "Your Main Hand melee attacks against enemies afflicted by your Rend have a {1}% chance to allow the use of your Overpower ability on the target. Lasts {2}秒.", zhTW = "Your Main Hand melee attacks against enemies afflicted by your Rend have a {1}% chance to allow the use of your Overpower ability on the target. Lasts {2}秒." },
	["your melee strikes will refresh the spell's duration"] = { ko = "매번 공격 시 주문의 지속시간이 초기화됩니다.", zhTW = "被審判的目標無法逃跑。" },
	["your melee weapon attacks deal # nature damage to both you and your target"] = { ko = "근접 무기 공격이 자신과 대상 모두에게 {1}의 자연 피해를 입힙니다.", zhCN = "你的近战武器攻击会对你和目标同时造成{1}点自然伤害。", zhTW = "你的近戰武器攻擊對你和目標造成{1}點自然傷害。" },
	["your mind flay now deals #% more damage, gains # yards increased range, but slows the target's movement speed by #%"] = { ko = "정신의 채찍의 공격력이 {1}%만큼, 사정거리가 {2}미터만큼 증가하지만, 대상의 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "你的精神鞭笞现在造成的伤害提高{1}%，射程提高{2}码，但会使目标的移动速度降低{3}%。", zhTW = "你的精神鞭笞現在造成的傷害提高{1}%，施法距離延長{2}碼，但會使目標的移動速度降低{3}%。" },
	["your mongoose bite also causes the target to bleed for damage equal to #% of the damage done by mongoose bite over # sec"] = { ko = "살쾡이의 이빨이 대상에게 출혈을 일으켜 {2}초에 걸쳐 살쾡이의 이빨로 입힌 피해의 {1}%에 해당하는 피해를 추가로 입힙니다.", zhCN = "你的猫鼬撕咬还会使目标流血，在{2}秒内造成相当于猫鼬撕咬伤害{1}%的伤害。", zhTW = "你的貓鼬撕咬還會使目標流血，在{2}秒內造成相當於貓鼬撕咬傷害{1}%的傷害。" },
	["your next # melee attacks strike an additional nearby opponent"] = { ko = "다음 {1}회의 근접 공격은 주위의 적 1명을 추가로 공격합니다.", zhCN = "你在接下来的{1}次近战攻击中可以攻击到一个额外的敌人。", zhTW = "你在接下來的{1}次近戰攻擊中可以攻擊到一個額外的敵人。" },
	["your next holy shock cast on them triggers no cooldown and causes enemy targets to suffer # to # holy damage and refund #% of light's vigil's mana cost, or allied targets to heal their party for # to #"] = { ko = "다음에 그 대상에게 시전하는 신성 충격은 재사용 대기시간이 발생하지 않으며, 적이면 {1}~{2}의 신성 피해를 입히고 빛의 경계 마나 비용의 {3}%를 돌려받고, 아군이면 그 파티원을 {4}~{5}만큼 치유합니다." },
	["your next imp, voidwalker, succubus, incubus, or felhunter summon spell has its casting time reduced by # sec and its mana cost reduced by #%"] = { ko = "다음 임프와 보이드워커, 서큐버스, 인큐버스, 지옥사냥개 소환 주문의 시전 시간이 {1}초만큼 단축되고 소비되는 마나가 {2}%만큼 감소합니다.", zhCN = "你的下一个召唤小鬼、虚空行者、魅魔、夜魔或地狱猎犬的法术施法时间减少{1}秒，法力消耗减少{2}%。", zhTW = "你的下一個召喚小鬼、虛空行者、魅魔、夢魔或地獄獵犬法術施法時間減少{1}秒，法力消耗減少{2}%。" },
	["your next melee attack applies the replaced seal's effects, consuming the echo"] = { ko = "다음 근접 공격 시 메아리를 소모하여 교체된 문장의 효과를 적용합니다." },
	["your non-periodic critical heals increase your target's armor by #% for # sec"] = { ko = "시전자의 비주기적인 치유 효과가 극대화 효과를 발휘하면 {2}초 동안 대상의 방어도를 {1}%만큼 증가시킵니다.", zhCN = "你的非周期性治疗爆击会使目标的护甲值提高{1}%，持续{2}秒。", zhTW = "你的非週期性極效治療使你目標的護甲值提高{1}%，持續{2}秒。" },
	["your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by #% for # sec"] = { ko = "공격 주문이 치명타 및 극대화 효과를 발휘하면 {2}초 동안 근접 공격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "你的进攻性法术造成爆击时，会使你的近战攻击爆击几率提高{1}%，持续{2}秒。", zhTW = "在你的攻擊法術造成致命一擊後使你的近戰攻擊造成致命一擊的機率提高{1}%，持續{2}秒。" },
	["your pet cannot cast fire shield on itself"] = { ko = "소환수는 자기 자신에게 화염 보호막을 시전하지 못합니다.", zhCN = "你的宠物无法对自身施放火焰之盾。", zhTW = "你的寵物不能對自己施放火焰之盾。" },
	["your pet's next # attacks against the target generate high threat and deal # to # fire or shadow damage based on the pet"] = { ko = "대상에 대한 소환수의 다음 {1}회 공격은 높은 위협 수준을 발생시키며, 소환수에 따라 {2}~{3}의 화염 또는 암흑 피해를 입힙니다." },
	["your scorch spell has a #% chance to cause your target to be vulnerable to fire damage"] = { ko = "불태우기 사용 시 {1}%의 확률로 30초 동안 자신이 대상에게 입히는 모든 화염 피해가 3%만큼 증가합니다.", zhCN = "你的灼烧法术有{1}%的几率使目标更易受到火焰伤害。" },
	["your scorch spell has a #% chance to cause your target to be vulnerable to fire damage. this vulnerability increases all fire damage you deal to your target by #% and lasts # sec, stacking up to # times"] = { ko = "불태우기 사용 시 {1}%의 확률로 {3}초 동안 자신이 대상에게 입히는 모든 화염 피해가 {2}%만큼 증가합니다. 최대 {4}번까지 중첩됩니다.", zhCN = "你的灼烧法术有{1}%的几率使目标更易受到火焰伤害。该易伤效果会使你对该目标造成的所有火焰伤害提高{2}%，持续{3}秒，最多叠加{4}次。", zhTW = "使你的灼燒法術有{1}%的機率令目標更易受到火焰傷害。此易傷效果會使你對目標造成的所有火焰傷害提高{2}%，持續{3}秒。最多可堆疊{4}層。" },
	["your searing pain generates #% less threat and brands the target for # sec"] = { ko = "불타는 고통으로 발생하는 위협 수준이 {1}%만큼 감소하며, {2}초 동안 대상에게 낙인을 새깁니다." },
	["your searing pain generates #% less threat and brands the target for # sec. your pet's next # attacks against the target generate high threat and deal # to # fire or shadow damage based on the pet"] = { ko = "불타는 고통으로 발생하는 위협 수준이 {1}%만큼 감소하며, {2}초 동안 대상에게 낙인을 새깁니다. 대상에 대한 소환수의 다음 {3}회 공격은 높은 위협 수준을 발생시키며, 소환수에 따라 {4}~{5}의 화염 또는 암흑 피해를 입힙니다." },
	["your shadow bolt critical strikes increase shadow damage taken by the target from your attacks by #% for # sec"] = { ko = "어둠의 화살이 치명타 및 극대화 효과를 발휘하면 {2}초 동안 대상이 시전자의 공격으로 받는 암흑 피해가 {1}%만큼 증가합니다.", zhCN = "你的暗影箭爆击会使目标受到来自你攻击的暗影伤害提高{1}%，持续{2}秒。", zhTW = "你的暗影箭造成致命一擊時，你的攻擊對該目標造成的暗影傷害提高{1}%，持續{2}秒。" },
	["your shadow damage spells have a #% chance to increase the shadow damage you deal by #% for # sec, stacking up to # times"] = { ko = "암흑 계열 공격 주문 사용 시 {1}%의 확률로 {3}초 동안 암흑 공격력이 {2}%만큼 증가합니다. 최대 {4}번까지 중첩됩니다.", zhCN = "你的暗影伤害法术有{1}%的几率使你造成的暗影伤害提高{2}%，持续{3}秒，最多叠加{4}次。", zhTW = "你的暗影系傷害性法術有{1}%的機率使你造成的暗影傷害提高{2}%，持續{3}秒，最多可堆疊{4}次。" },
	["your sinister strike, ghostly strike, and hemorrhage abilities cause #% more damage against targets below #% health"] = { ko = "생명력이 {2}% 미만인 대상에게 사악한 일격, 유령의 일격, 과다출혈이 {1}%의 추가 피해를 입힙니다.", zhCN = "你的邪恶攻击、鬼魅攻击和出血对生命值低于{2}%的目标造成的伤害提高{1}%。", zhTW = "你的邪惡攻擊、鬼魅攻擊和出血技能對生命力低於{2}%的目標造成的傷害提高{1}%。" },
	["your skin becomes as tough as bark"] = { ko = "피부가 나무 껍질처럼 단단해집니다.", zhCN = "你的皮肤变得如树皮一样坚硬。" },
	["your skin becomes as tough as bark. physical damage taken is reduced by #%. while you are protected, damaging attacks will not cause spellcasting delays. lasts # sec"] = { ko = "피부가 나무 껍질처럼 단단해집니다. 받는 물리 피해가 {1}%만큼 감소합니다. 효과가 지속되는 동안에는 공격에 의해 시전 시간이 지연되지 않습니다. {2}초 동안 지속됩니다.", zhCN = "你的皮肤变得如树皮一样坚硬。受到的物理伤害降低{1}%。受保护期间，受到伤害不会导致施法延迟。持续{2}秒。", zhTW = "你的皮膚會變得跟樹皮一樣堅韌。受到的物理傷害降低{1}%。受到保護時，傷害性攻擊不會導致施法延遲，持續{2}秒。" },
	["your smite and penance spells deal #% increased damage to targets afflicted with your holy fire"] = { ko = "성스러운 일격과 회개가 신성한 불꽃에 걸린 대상에게 {1}%의 추가 피해를 입힙니다.", zhCN = "你的惩击和苦修法术对受到神圣之火影响的目标造成的伤害提高{1}%。", zhTW = "你的懲擊和懺悟對受到你神聖之火影響的目標所造成的傷害提高{1}%。" },
	["your spells and attacks have a chance to grant you clearcasting, reducing the mana, rage, or energy cost of your next damage or healing spell or offensive ability by #%"] = { ko = "주문 시전 및 공격 시 일정 확률로 번뜩임이 부여되어 다음 공격 주문이나 치유 주문, 공격 능력의 마나, 분노 혹은 기력 소모량이 {1}%만큼 감소합니다.", zhCN = "你的法术和攻击有几率使你获得节能施法，使你的下一个伤害、治疗法术或进攻技能所消耗的法力值、怒气或能量降低{1}%。", zhTW = "你的法術和攻擊有一定的機率使你進入節能施法狀態，你的下一個傷害法術、治療法術或攻擊技能所消耗的法力、怒氣或能量降低{1}%。" },
	["your spells and attacks have a chance to grant you clearcasting, reducing the mana, rage, or energy cost of your next damage or healing spell or offensive ability by #%. clearcasting is not consumed by wrath or by spells or abilities that cost no resources"] = { ko = "주문 시전 및 공격 시 일정 확률로 번뜩임이 부여되어 다음 공격 주문이나 치유 주문, 공격 능력의 마나, 분노 혹은 기력 소모량이 {1}%만큼 감소합니다. 번뜩임은 천벌 또는 자원을 소모하지 않는 주문이나 능력으로는 소모되지 않습니다.", zhCN = "你的法术和攻击有几率使你获得节能施法，使你的下一个伤害、治疗法术或进攻技能所消耗的法力值、怒气或能量降低{1}%。愤怒以及不消耗资源的法术或技能不会消耗节能施法。", zhTW = "你的法術和攻擊有一定的機率使你進入節能施法狀態，你的下一個傷害法術、治療法術或攻擊技能所消耗的法力、怒氣或能量降低{1}%。節能施法效果不會被憤怒或不消耗資源的法術/技能消耗。" },
	["your target's armor"] = { zhTW = "護甲值。" },
	["your wrath spell reduces the cast time of your next # starfire spells by # sec"] = { ko = "천벌 시전 시 다음 {1}회의 별빛 화살의 시전 시간이 {2}초만큼 감소합니다.", zhCN = "你的愤怒使接下来{1}次星火术的施法时间缩短{2}秒。" },
	["your wrath spell reduces the cast time of your next # starfire spells by # sec. stores up to # charges. lasts # sec"] = { ko = "천벌 시전 시 다음 {1}회의 별빛 화살의 시전 시간이 {2}초만큼 감소합니다. 최대 {3}회 충전됩니다. {4}초 동안 지속됩니다.", zhCN = "你的愤怒使接下来{1}次星火术的施法时间缩短{2}秒。最多储存{3}层。持续{4}秒。", zhTW = "你的憤怒法術使你接下來{1}個星火術的施法時間縮短{2}秒。最多可儲存{3}次使用次數，持續{4}秒。" },
	["yup, nothing bad could ever happen while using this device"] = { ko = "절대로 문제가 일어나지 않으니 안심하고 사용하시기 바랍니다.", zhCN = "没错，你完全不必有任何担心！", zhTW = "沒錯，你完全不必有任何擔心！" },
	["zooms in the hunter's vision"] = { ko = "사냥꾼의 시야를 확장하여 더 먼 곳까지 볼 수 있습니다.", zhCN = "增长猎人的视距。", zhTW = "增長獵人的視距。" },
	["zooms in the hunter's vision. only usable outdoors. lasts # min"] = { ko = "사냥꾼의 시야를 확장하여 더 먼 곳까지 볼 수 있습니다. 야외에서만 사용할 수 있습니다. {1}분 동안 지속됩니다.", zhCN = "增长猎人的视距。只能在户外使用。持续{1}分钟。", zhTW = "增長獵人的視距。只能在戶外使用。持續{1}分鐘。" },
}
