	{ "damage deals disorients range sec short shot target weapon", { zhCN = "短程射击，对目标造成{1}%的武器伤害，并使其困惑{2}秒。", zhTW = "短程射擊，對目標造成{1}%的武器傷害，並使其暈眩{2}秒。" }, "p,n" },
