	{ "casting heals single slow spell target", { ko = "대상의 생명력을 {1},{2}~{3},{4}만큼 회복시킵니다.", zhCN = "施法缓慢的法术，可以为单一目标治疗{1},{2}至{3},{4}点伤害。", zhTW = "施法緩慢的法術，可以為單一目標治療{1},{2}至{3},{4}點傷害。" }, "n,n,n,n" },
