	{ "amount attack causes damage high increases melee strong threat", { ko = "적을 강하게 내리쳐 {1}의 추가 피해를 입힙니다. 위협 수준이 크게 증가합니다.", zhCN = "强力的攻击，使近战攻击所造成的伤害提高{1}点，并造成大量的威胁。", zhTW = "強力的攻擊，使近戰攻擊所造成的傷害提高{1}點並造成大量威脅。" }, "n" },
	{ "attack damage does enemy nearby plus second sweeping target weapon", { ko = "무기를 크게 휘둘러 공격하여 대상과 그 주위의 두 번째 적에게 무기 공격력에 {1}의 추가 피해를 입힙니다.", zhCN = "发动横扫攻击，对目标及附近的另一名敌人造成武器伤害外加{1}点伤害。", zhTW = "橫掃攻擊，對目標和其附近的第二個敵人造成你的武器傷害再加上{1}點傷害。" }, "n" },
