	{ "any damage deals effectiveness healing plus reducing sec strike target vicious weapon wounds", { ko = "무기 공격력에 추가로 {1}만큼의 피해를 입히고 {3}초 동안 모든 치유의 효과가 {2}%만큼 감소되도록 상처를 입힙니다.", zhCN = "一次邪恶的攻击，对目标造成武器伤害外加{1}点伤害，并使任何形式的治疗对其产生的效果降低{2}%，持续{3}秒。", zhTW = "一次猛烈的攻擊，對目標造成武器傷害外加{1}點傷害，並使任何形式的治療對其產生的效果降低{2}%，持續{3}秒。" }, "n,p,n" },
	{ "all blast caster caught damage damaging dazing enemies fire flame movement outward radiates reduced sec speed them wave within", { ko = "불의 파도가 시전자 주위로 뿜어져 나와 모든 적을 불길로 감싸 {1}~{2}의 화염 피해를 입히고, 멍하게 만들어 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "施法者向外释放一道火焰冲击波，对冲击范围内的所有敌人造成{1}至{2}点火焰伤害，并使其眩晕，移动速度降低{3}%，持续{4}秒。", zhTW = "施法者放出一道烈焰衝擊波，所有被衝擊波觸及的敵人都會受到{1}至{2}點火焰傷害，並使其陷入暈眩，移動速度降低{3}%，持續{4}秒。" }, "n,n,p,n" },
	{ "binding damage dark inflicts shadow target word", { ko = "어둠의 힘으로 대상에게 {1}~{2}의 암흑 피해를 입힙니다.", zhCN = "黑暗束缚的咒语，对目标造成{1}至{2}点暗影伤害。", zhTW = "黑暗的咒語對目標造成{1}至{2}點暗影傷害。" }, "n,n" },
	{ "backlash binding damage dark death equal health if inflicts killed maximum not shadow take target word", { ko = "어둠의 힘으로 대상에게 {1}~{2}의 암흑 피해를 입힙니다. 대상이 어둠의 권능: 죽음으로 사망하지 않으면 최대 생명력의 {3}%에 해당하는 반발 피해를 받습니다.", zhCN = "黑暗束缚的咒语，对目标造成{1}至{2}点暗影伤害。如果你的目标没有被暗言术：灭杀死，你将承受相当于你最大生命值{3}%的伤害反噬。", zhTW = "黑暗的咒語對目標造成{1}至{2}點暗影傷害。如果你的目標沒有被暗言術：死所殺害，你會受到相當於你生命力上限{3}%的反傷。" }, "n,n,p" },
	{ "causes damage darkness over sec shadow word", { ko = "어둠의 힘으로 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다.", zhCN = "黑暗的咒语，在{2}秒内造成总计{1}点暗影伤害。", zhTW = "黑暗的咒語，在{2}秒內造成總計{1}點暗影傷害。" }, "n,n" },
