	{ "absorbs damage frost lasts sec", { ko = "{1}의 냉기 피해를 흡수합니다. {2}초 동안 지속됩니다.", zhCN = "吸收{1}点冰霜伤害。持续{2}秒。", zhTW = "吸收{1}點冰霜傷害，持續{2}秒。" }, "n,n" },
	{ "absorbs damage draining instead mana physical", { ko = "마나를 소비하여 {1}의 물리 피해를 흡수합니다.", zhCN = "吸收{1}点物理伤害，同时消耗法力值。", zhTW = "吸收{1}點物理傷害，同時消耗法力。" }, "n" },
	{ "absorbed absorbs damage draining drains instead lasts mana min per physical", { ko = "마나를 소비하여 {1}의 물리 피해를 흡수합니다. 흡수된 피해당 {2}의 마나를 소비합니다. {3}분 동안 지속됩니다.", zhCN = "吸收{1}点物理伤害，同时消耗法力值。每吸收{3}点物理伤害，就消耗{2}点法力值。持续1分钟。", zhTW = "吸收{1}點物理傷害，同時消耗法力。每吸收{3}點物理傷害，就消耗{2}點法力。持續1分鐘。" }, "n,n,n" },
	{ "absorbs damage lasts sec shadow", { ko = "{1}의 암흑 피해를 흡수합니다. {2}초 동안 지속됩니다.", zhCN = "吸收{1}点暗影伤害，持续{2}秒。", zhTW = "吸收{1}點暗影傷害，持續{2}秒。" }, "n,n" },
	{ "activate increase jets movement sec set speed up", { ko = "추진기를 가동하여 이동 속도가 최대 {1}%만큼 증가합니다. 최대 {2}초 동안 지속됩니다.", zhCN = "激活一组推进器，使你的移动速度提高{1}%，持续最多{2}秒。", zhTW = "啟用一組推進器，使你的移動速度提高{1}%，持續最多{2}秒。" }, "p,n" },
	{ "additionally experience gained increased kills", { ko = "추가로, 적 처치 시 획득하는 경험치가 {1}%만큼 증가합니다." }, "p" },
	{ "ability additionally aspect effect gains monkey pet", { ko = "추가로 야수가 원숭이의 상 효과의 {1}%를 받습니다.", zhCN = "此外，你的宠物获得灵猴守护效果的{1}%。", zhTW = "此外，你的寵物獲得你靈猴守護技能的{1}%效果。" }, "p" },
	{ "adds combo points target", { ko = "대상에 대한 연계 점수 {1}점이 추가됩니다.", zhCN = "为你的目标增加{1}个连击点数。", zhTW = "為你的目標增加{1}個連擊點數。" }, "n" },
	{ "add adds combo lost must points sec target those use within", { ko = "대상에 대한 연계 점수 {1}점이 추가됩니다. {2}초 내에 연계 점수를 추가하거나 추가된 연계 점수를 사용하지 않으면 연계 점수가 사라집니다.", zhCN = "为你的目标增加{1}个连击点数。你必须在{2}秒内增加或消耗这些连击点数，否则它们就会消失。", zhTW = "為你的目標增加{1}個連擊點數。你必須在{2}秒內追加或消耗掉這些點數，否則它們就會消失。" }, "n,n" },
	{ "adds blizzard chill effect spell", { ko = "눈보라 주문이 빙결 효과를 일으킵니다." }, "" },
