	{ "additional affected damage every sec suffer targets will", { ko = "영향을 받는 대상은 {3}초 동안 {2}초마다 {1}의 추가 피해를 받습니다.", zhCN = "受影响的目标每{2}秒额外受到{1}点伤害，持续{3}秒。", zhTW = "受影響的目標每{2}秒額外受到{1}點傷害，持續{3}秒。" }, "n,n,n" },
	{ "afflicts all also causing cursed damage dealt done min other target targets warlock", { zhCN = "使目标遭受浩劫灾祸，持续{1}分钟，术士对其他目标造成的所有伤害有{2}%也会施加给被诅咒的目标。", zhTW = "對目標施加災厄，使其受到相當於該術士對其他目標所造成的所有傷害的{2}%傷害，持續{1}分鐘。" }, "n,p" },
	{ "active afflicts all also any bane can causing cursed damage dealt done havoc limited min one only other per target targets warlock", { ko = "{1}분 동안 대상을 고통에 빠뜨립니다. 이때 흑마법사가 다른 대상에게 입히는 모든 피해의 {2}%를 저주받은 대상에게도 입힙니다. 대혼란의 파멸은 한 번에 하나의 대상에게만 걸 수 있으며, 흑마법사마다 한 대상에게 하나의 파멸만 걸 수 있습니다.", zhCN = "使目标遭受浩劫灾祸，持续{1}分钟，术士对其他目标造成的所有伤害有{2}%也会施加给被诅咒的目标。浩劫灾祸只能影响{3}个目标，且每个术士在任一目标身上只能维持一种灾祸。", zhTW = "對目標施加災厄，使其受到相當於該術士對其他目標所造成的所有傷害的{2}%傷害，持續{1}分鐘。僅限對{3}個目標施加浩劫之禍，且每個術士只能對同一個目標施加一種災厄。" }, "n,p,n" },
	{ "afflicts causes damage disease over sec shadow target", { ko = "적을 질병에 감염시켜 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다." }, "n,n" },
	{ "afflicts caster caused causes damage devouring disease heals over plague sec shadow target", { ko = "적을 질병에 감염시켜 {2}초에 걸쳐 총 {1}의 암흑 피해를 입힙니다. 파멸의 역병으로 인해 입히는 피해만큼 시전자의 생명력이 회복됩니다.", zhCN = "使目标患上疾病，在{2}秒内造成总计{1}点暗影伤害，并为施法者恢复等量的生命值。", zhTW = "使目標患上疾病，在{2}秒內造成總計{1}點暗影傷害，並為施法者恢復等量的生命力。" }, "n,n" },
	{ "afflicts agony causing damage over sec shadow target", { ko = "고통의 저주를 걸어 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다.", zhCN = "使目标遭受痛楚，在{2}秒内受到{1}点暗影伤害。", zhTW = "對目標施加痛苦，使其在{2}秒內受到{1}點暗影傷害。" }, "n,n" },
	{ "active afflicts agony any bane builds can causing damage dealt duration first full one only over per reaches sec shadow slowly target up warlock", { ko = "고통의 저주를 걸어 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다. 처음엔 피해를 천천히 입히다가 갈수록 피해를 주는 속도가 빨라집니다. 흑마법사마다 대상에 동시에 하나의 파멸만 걸 수 있습니다.", zhCN = "使目标遭受痛楚，在{2}秒内受到{1}点暗影伤害。该伤害起初较低，并会随着灾祸接近完整持续时间而逐渐提高。每个术士在任一目标身上只能维持一种灾祸。", zhTW = "對目標施加痛苦，使其在{2}秒內受到{1}點暗影傷害。此傷害在初期較低，但是會在作用效果期間不斷提高，直到結束。每個術士只能對同一個目標施加一種災禍。" }, "n,n" },
	{ "afflicts after causing damage doom impending min shadow target", { ko = "대상에게 임박하는 파멸을 걸어 {1}분 후에 {3},{2}의 암흑 피해를 입힙니다.", zhCN = "对目标施加末日将至的效果，在{1}分钟后造成{3},{2}点暗影伤害。", zhTW = "對目標施加厄運降臨，在{1}分鐘後造成{3},{2}點暗影傷害。" }, "n,n,n" },
	{ "active afflicts after any bane can cannot cast causing chance damage dies doom doomguard if impending min one only per players shadow summoned target there warlock will", { ko = "대상에게 임박하는 파멸을 걸어 {1}분 후에 {3},{2}의 암흑 피해를 입힙니다. 그 피해로 인해 대상이 죽으면 일정 확률로 파멸의 수호병이 소환됩니다. 플레이어에게는 사용할 수 없습니다. 흑마법사마다 한 대상에게 하나의 파멸만 걸 수 있습니다.", zhCN = "对目标施加末日将至的效果，在{1}分钟后造成{3},{2}点暗影伤害。如果目标死于该伤害，则有几率召唤一名末日守卫。无法对玩家施放。每个术士对同一目标同时只能施加一种灾祸。", zhTW = "對目標施加厄運降臨，在{1}分鐘後造成{3},{2}點暗影傷害。如果目標死於該傷害，則有機率召喚出一個末日守衛。無法對玩家施放。每個術士只能對一個目標施加一種災厄。" }, "n,n,n" },
	{ "afflicts all any causes damage deal energy healed members party sec shadow spell target", { ko = "대상에게 암흑 마법을 겁니다. {2}초 동안 암흑 주문으로 입히는 피해의 {1}%만큼 모든 파티원을 치유합니다.", zhCN = "以暗影能量笼罩目标，使你在{2}秒内对其造成的所有暗影法术伤害的{1}%转化为对全体小队成员的治疗。吸血鬼的拥抱还会使受其影响的敌人死亡时，有几率触发你的精神分流天赋。", zhTW = "以暗影能量籠罩目標，使你在{2}秒內對其造成的所有暗影法術傷害的{1}%轉化為對全體小隊成員的治療。吸血鬼的擁抱還會使受其影響的敵人死亡時，有機率觸發你的精神分流天賦。" }, "p,n" },
	{ "after attack being critical damage heal health hit maximum melee more over ranged sec single struck suffering taken than", { ko = "근접 및 원거리 치명타 공격을 받거나 한 번의 공격으로 최대 생명력의 {1}%를 넘는 피해를 받으면 {3}초에 걸쳐 받은 피해의 {2}%만큼 생명력을 회복합니다.", zhCN = "在遭受近战或远程爆击，或单次攻击受到超过最大生命值{1}%的伤害后，在{3}秒内恢复相当于所受伤害{2}%的生命值。", zhTW = "受到近戰或遠程致命一擊，或單次攻擊承受超過相當於你生命力上限{1}%的傷害後，在{3}秒內治療受到傷害的{2}%。" }, "p,p,n" },
	{ "after any attack being carries critical damage effect heal healing health hit maximum melee more over ranged refreshing remaining sec single struck suffering taken than", { ko = "근접 및 원거리 치명타 공격을 받거나 한 번의 공격으로 최대 생명력의 {1}%를 넘는 피해를 받으면 {3}초에 걸쳐 받은 피해의 {2}%만큼 생명력을 회복합니다. 이 효과를 갱신하면 남은 치유량이 이월됩니다.", zhCN = "在遭受近战或远程爆击，或单次攻击受到超过最大生命值{1}%的伤害后，在{3}秒内恢复相当于所受伤害{2}%的生命值。刷新该效果时会保留剩余治疗量。", zhTW = "受到近戰或遠程致命一擊，或單次攻擊承受超過相當於你生命力上限{1}%的傷害後，在{3}秒內治療受到傷害的{2}%。重置此效果會繼承剩餘的所有治療效果。" }, "p,p,n" },
	{ "after combat damage entering instance next physical reduce sec taken within", { ko = "전투가 시작된 후 {1}초 안에 받는 다음 물리 피해가 {2}만큼 감소합니다." }, "n,n" },
	{ "after base chance cost critical effect equal flash gain getting have heal holy light light's mana shock spell vigil", { ko = "빛의 섬광이나 성스러운 빛, 빛의 경계, 신성 충격의 치유 효과가 극대화 효과를 발휘하면 {1}%의 확률로 해당 주문의 기본 마나 소모량의 {2}%에 해당하는 마나를 회복합니다.", zhCN = "在你的圣光闪现、圣光术、圣光守夜或神圣震击治疗法术造成爆击效果后，你有{1}%的几率回复相当于该法术基础消耗{2}%的法力值。", zhTW = "在你的聖光閃現、聖光術、聖光戒備或神聖震擊等治療法術造成極效治療後，你有{1}%的機率獲得該法術基礎法力消耗的{2}%法力。" }, "p,p" },
	{ "after ambush backstab chance critical enemy ghostly gives increased killing mutilate next non sinister strike trivial", { ko = "사소하지 않은 적을 처치하면 다음 사악한 일격, 기습, 매복, 절단 또는 그림자 일격의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "击杀一个能为你提供经验值或荣誉值的敌人后，使你的下一次邪恶攻击、背刺、伏击、毁伤或鬼魅攻击的爆击几率提高{1}%。" }, "p" },
	{ "after ambush backstab chance critical enemy ghostly gives increased killing lasts mutilate next non sec sinister strike trivial", { ko = "사소하지 않은 적을 처치하면 다음 사악한 일격, 기습, 매복, 절단 또는 그림자 일격의 치명타 및 극대화율이 {1}%만큼 증가합니다. {2}초 동안 지속됩니다.", zhCN = "击杀一个能为你提供经验值或荣誉值的敌人后，使你的下一次邪恶攻击、背刺、伏击、毁伤或鬼魅攻击的爆击几率提高{1}%。持续{2}秒。", zhTW = "在殺死一個有實力的敵人後，使你的下一次邪惡攻擊、背刺、伏擊、截肢或鬼魅攻擊造成致命一擊的機率提高{1}%，效果持續{2}秒。" }, "p,n" },
	{ "after effect expires health lost", { ko = "20초 동안 지속되며 지속시간이 끝나면 임시 생명력은 사라집니다.", zhCN = "效果结束后会失去这些生命值。", zhTW = "效果結束後，這些生命力會被扣除。" }, "" },
	{ "aimed cooldown multi shares shot", { ko = "조준 사격은 일제 사격과 재사용 대기시간을 공유합니다.", zhCN = "瞄准射击与多重射击共享冷却时间。", zhTW = "瞄準射擊與多重射擊共用冷卻時間。" }, "" },
