	{ "additional causes damage holy instant plus strike weapon", { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%에 {2}~{3}의 추가 신성 피해를 입힙니다.", zhCN = "立即打击，造成{1}%武器伤害，外加{2}至{3}点神圣伤害。", zhTW = "立即對敵人造成{1}%的武器傷害，同時額外造成{2}至{3}點神聖傷害。" }, "p,n,n" },
	{ "causes dagger damage deals equipped if increased instant rogue rupture strike take target weapon", { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%(단검 착용 시 {2}%)에 해당하는 피해를 입히고 대상이 도적의 파열로 받는 피해를 {3}%만큼 증가시킵니다." }, "p,p,p" },
	{ "awards causes combo dagger damage deals equipped if increased instant lasts point rogue rupture sec strike take target weapon", { ko = "적에게 즉시 일격을 가하여 무기 공격력의 {1}%(단검 착용 시 {2}%)에 해당하는 피해를 입히고 대상이 도적의 파열로 받는 피해를 {3}%만큼 증가시킵니다. {4}초 동안 지속됩니다. 연계 점수 {5}점을 생성합니다.", zhCN = "发动瞬发打击，造成{1}%武器伤害（装备匕首时为{2}%），并使目标受到来自游荡者的割裂伤害提高{3}%，持续{4}秒。奖励{5}个连击点数。", zhTW = "立即對目標造成{1}%的武器傷害（如果裝備匕首則為{2}%），並使盜賊對目標造成的割裂傷害提高{3}%，持續{4}秒。獎勵{5}個連擊點數。" }, "p,p,p,n,n" },
	{ "any awaken caused damage target will", { ko = "대상이 피해를 입으면 깨어납니다.", zhCN = "造成任何伤害都会唤醒目标。", zhTW = "任何傷害都會喚醒目標。" }, "" },
	{ "any break caused damage ice will", { ko = "적이 다가오면 얼려서 최대 10초 동안 모든 행동을 불가능하게 만듭니다.", zhCN = "造成任何伤害都会打破冰冻。", zhTW = "任何傷害都會中斷冰凍效果。" }, "" },
	{ "any caused damage release target will", { ko = "대상은 피해를 입으면 해제됩니다.", zhCN = "任何对其造成伤害的行为都将解除束缚。", zhTW = "任何對其造成傷害的行為都將解除束縛。" }, "" },
	{ "any caused damage effect remove will", { ko = "피해를 입게 되면 효과가 사라집니다.", zhCN = "任何伤害都会打断该效果。", zhTW = "任何傷害都會打斷該效果。" }, "" },
	{ "any break damage effect taken will", { ko = "피해를 받으면 효과가 해제됩니다.", zhCN = "受到任何伤害都会打破该效果。", zhTW = "受到任何傷害都會中斷此效果。" }, "" },
	{ "any awaken damage target will", { ko = "대상이 피해를 입으면 깨어납니다." }, "" },
	{ "any break damage effect will", { ko = "대상이 피해를 받으면 효과가 사라집니다.", zhCN = "任何伤害都会打断此效果。", zhTW = "任何傷害都會打斷此效果。" }, "" },
	{ "any cancel damage effect will", { ko = "피해를 받으면 효과가 사라집니다.", zhCN = "任何伤害都会取消沉睡效果。", zhTW = "任何傷害都會取消沉睡效果。" }, "" },
	{ "against any attacker's burn burned cast causing damage each mana point priest shadow spell successful will", { ko = "자신에게 주문이 적중했을 경우 공격자의 마나를 {1}만큼 소진시키고 소진된 마나 당 {2}의 암흑 피해를 입힙니다.", zhCN = "任何对牧师成功施放的敌对法术都会令施法者损失{1}点法力值，并对其造成等量的暗影伤害。" }, "n,n" },
	{ "applies light's sec target vigil", { ko = "{1}초 동안 대상에게 빛의 경계를 겁니다." }, "n" },
	{ "active allied applies cast causes cooldown cost damage enemy have heal holy light's mana may next no one only party per refund sec shock suffer target targets their them triggers vigil vigil's", { ko = "{1}초 동안 대상에게 빛의 경계를 겁니다. 다음에 그 대상에게 시전하는 신성 충격은 재사용 대기시간이 발생하지 않으며, 적이면 {2}~{3}의 신성 피해를 입히고 빛의 경계 마나 비용의 {4}%를 돌려받고, 아군이면 그 파티원을 {5}~333만큼 치유합니다. 빛의 경계는 파티당 하나만 유지할 수 있습니다.", zhCN = "Applies Light's Vigil to the target for {1}秒. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer {2}至{3} Holy damage and refund {4}% of Light's Vigil's Mana cost, or allied targets to heal their party for {5}至{6} The Paladin may only have one Light's Vigil active per party.", zhTW = "Applies Light's Vigil to the target for {1}秒. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer {2}至{3} Holy damage and refund {4}% of Light's Vigil's Mana cost, or allied targets to heal their party for {5}至{6} The Paladin may only have one Light's Vigil active per party." }, "n,n,n,p,n,n" },
	{ "assault causing damage energy mind movement over sec shadow slowing speed target's their", { ko = "대상의 정신을 암흑의 기운으로 공격하여, {2}초에 걸쳐 {1}의 암흑 피해를 입히고 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "以暗影能量冲击目标的心灵，在{2}秒内造成{1}点暗影伤害，并使其移动速度降低{3}%。", zhTW = "以暗影能量攻擊目標的心智，在{2}秒內對其造成{1}點暗影傷害，並使其移動速度降低{3}%。" }, "n,n,p" },
	{ "all allows assembles attacks aura camp chair chance critical exclusive gain increased moonkin mutually nearby others sitting spells strike", { ko = "야영지 의자를 조립해 자신과 주위에 앉은 다른 플레이어의 모든 주문 및 공격의 치명타 및 극대화율을 {1}%만큼 증가시킵니다. 달빛야수 오라와 겸용해서 사용할 수 없습니다.", zhCN = "组装一把营地椅子，使你和附近坐下的其他人所有法术和攻击的爆击几率提高{1}%，与枭兽光环不叠加。", zhTW = "組裝一把營地椅子，使你和附近坐下的其他人所有法術和攻擊的致命一擊機率提高{1}%，與梟獸光環不疊加。" }, "p" },
	{ "all assume bonus cost critical damage increasing mana physical reducing shadow shadowform spells strike taken", { zhCN = "进入暗影形态，使你的暗影伤害提高{1}%，所有暗影法术消耗的法力值降低{2}%，暗影法术的爆击伤害加成提高{3}%，你受到的物理伤害降低{4}%。", zhTW = "進入暗影形態，使你造成的暗影傷害提高{1}%，所有暗影法術的法力消耗降低{2}%，暗影法術的致命一擊傷害加成提高{3}%，你受到的物理傷害降低{4}%。" }, "p,p,p,p" },
	{ "all assume bonus cast cost critical damage form healing however increasing mana may not physical reducing shadow shadowform spells strike taken while", { ko = "어둠의 형상을 취해 암흑 공격력이 {1}%만큼 증가하고 모든 암흑 주문의 마나 소모량이 {2}%만큼 감소합니다. 추가로 암흑 주문의 치명타 및 극대화 피해 증가량이 {3}%만큼 증가하며, 받는 물리 피해가 {4}%만큼 감소합니다. 하지만 이 상태에서는 치유 주문을 시전하지 못합니다.", zhCN = "进入暗影形态，使你的暗影伤害提高{1}%，所有暗影法术消耗的法力值降低{2}%，暗影法术的爆击伤害加成提高{3}%，你受到的物理伤害降低{4}%。但是在此形态下，你无法施放治疗法术。", zhTW = "進入暗影形態，使你造成的暗影傷害提高{1}%，所有暗影法術的法力消耗降低{2}%，暗影法術的致命一擊傷害加成提高{3}%，你受到的物理傷害降低{4}%。然而，在此形態下你無法施放治療法術。" }, "p,p,p,p" },
	{ "attaches bow chance critical crossbow gun increases permanent scope strike", { ko = "활이나 총, 석궁에 영구적으로 장착하여 치명타 및 극대화율을 {1}%만큼 증가시킵니다.", zhCN = "在弓、枪械或弩上加装永久性的瞄准镜，使其爆击几率提高{1}%。", zhTW = "在弓、槍械或弩上加裝永久性的瞄準鏡，使其致命一擊機率提高{1}。" }, "p" },
	{ "all attack damage dealing enemies every movement nearby own plus reducing sec speed weapon", { ko = "주위 모든 적을 공격해 {3}초 동안 {2}초마다 무기 공격력에 {1}의 피해를 합산하여 입히고, 자신의 이동 속도를 {4}%만큼 감소시킵니다.", zhCN = "攻击附近的所有敌人，每{2}秒造成武器伤害外加{1}点伤害，持续{3}秒，并使你的移动速度降低{4}%。", zhTW = "攻擊附近所有敵人，造成武器傷害，同時每{2}秒額外造成{1}點傷害，持續{3}秒，並使你的移動速度降低{4}%。" }, "n,n,n,p" },
	{ "attackers can damaged every few once only seconds", { ko = "이로 인한 피해는 위협 수준을 발생시키지 않습니다.", zhCN = "一个攻击者在短期内只会受到一次反噬伤害。", zhTW = "一個攻擊者在短期內只會受到一次反噬傷害。" }, "" },
	{ "additional attempt causing converting damage each extra finish foe off point rage wounded", { ko = "상처 입은 적에게 마무리 일격을 시도하여 {1}의 피해를 입히고 나머지 분노를 모두 소모하여 분노당 {2}의 피해를 추가로 입힙니다.", zhCN = "尝试杀死一个受伤的敌人，对其造成{1}点基础伤害，并将每一个额外的怒气点数转化为{2}点额外伤害。", zhTW = "嘗試殺死一個受傷的敵人，對其造成{1}點基礎傷害，並將每一個額外的怒氣點數轉化為{2}點額外傷害。" }, "n,n" },
	{ "additional attempt causing converting damage each enemies extra finish foe have health less off only point rage usable wounded", { ko = "상처 입은 적에게 마무리 일격을 시도하여 {1}의 피해를 입히고 나머지 분노를 모두 소모하여 분노당 {2}의 피해를 추가로 입힙니다. 생명력이 {3}%미만인 적에게만 사용할 수 있습니다.", zhCN = "尝试杀死一个受伤的敌人，对其造成{1}点基础伤害，并将每一个额外的怒气点数转化为{2}点额外伤害。只对生命值少于{3}%的敌人有效。", zhTW = "嘗試殺死一個受傷的敵人，對其造成{1}點基礎傷害，並將每一個額外的怒氣點數轉化為{2}點額外傷害。只對生命力少於{3}%的敵人有效。" }, "n,n,p" },
	{ "attempts cure disease effect every more sec target", { ko = "질병 {1}개의 치료를 시도하고 추가로 {4}초 동안 매 {3}초마다 {2}개의 질병 해제를 시도합니다.", zhCN = "尝试驱散目标身上的{1}个疾病效果，并每{3}秒驱散{2}个疾病效果，持续{4}秒。", zhTW = "嘗試驅散目標身上的{1}個疾病效果，並每{3}秒驅散{2}個疾病效果，持續{4}秒。" }, "n,n,n,n" },
	{ "attempts cure effect every more poison sec target", { ko = "독 {1}개의 치료를 시도하고 추가로 {4}초 동안 매 {3}초마다 {2}개의 독 해제를 시도합니다.", zhCN = "尝试驱散目标身上的{1}个中毒效果，并每{3}秒驱散{2}个中毒效果，持续{4}秒。", zhTW = "嘗試驅散目標身上的{1}個中毒效果，並每{3}秒驅散{2}個中毒效果，持續{4}秒。" }, "n,n,n,n" },
	{ "attempts disengage reducing target threat", { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다.", zhCN = "尝试脱离目标，降低威胁值。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。" }, "" },
	{ "attack attempts auto disables disengage reducing target threat", { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다. 자동 공격을 비활성화합니다.", zhCN = "尝试脱离目标，降低威胁值。停用自动攻击。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。停用自動攻擊。" }, "" },
	{ "attack attempts auto disables disengage effective more rank reducing target than threat", { ko = "대상으로부터 철수를 시도하여 위협 수준을 감소시킵니다. 철수 {1}레벨보다 효과가 높습니다. 자동 공격이 비활성화됩니다.", zhCN = "尝试通过降低威胁来脱离目标。比逃脱（等级 {1}）更有效。会停止自动攻击。", zhTW = "透過降低威脅值，嘗試從敵人面前逃脫。比逃脫（等級{1}）更有效。停用自動攻擊。" }, "n" },
	{ "attempts creature effect enemy frenzy remove", { ko = "적에게서 광기 효과 {1}개의 제거를 시도합니다.", zhCN = "尝试从一个敌方生物身上移除{1}个疯狂效果。", zhTW = "嘗試從一個敵方生物身上移除{1}個瘋狂效果。" }, "n" },
	{ "augment belt effect following give", { ko = "허리띠를 강화하여 아래 효과를 부여합니다.", zhCN = "强化你的腰带，提供以下效果：", zhTW = "強化你的腰帶，提供以下效果：" }, "" },
	{ "automatically cancelled shoots target until", { ko = "취소할 때까지 자동으로 적을 공격합니다.", zhCN = "自动射击目标，直到取消。", zhTW = "自動射擊目標，直到取消。" }, "" },
	{ "awards backstab behind causing combo dagger damage hand main must plus point requires target weapon", { ko = "적을 기습하여 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다. 주장비에 단검을 착용해야 하며 적의 배후에서 공격해야 합니다. {3}의 연계 점수를 얻습니다.", zhCN = "背刺目标，对其造成{1}%的武器伤害外加{2}点伤害，必须在目标背后发动，你的主手中必须有一把匕首。奖励{3}个连击点数。", zhTW = "背刺目標，對其造成{1}%武器傷害再加上{2}點傷害，必須在目標背後發動，需要在主手裝備匕首。獎勵{3}個連擊點數。" }, "p,n,n" },
	{ "active any bane can havoc limited one only per target warlock", { zhCN = "浩劫灾祸只能影响{1}个目标，且每个术士在任一目标身上只能维持一种灾祸。", zhTW = "僅限對{1}個目標施加浩劫之禍，且每個術士只能對同一個目標施加一種災厄。" }, "n" },
	{ "action all banished banishes but can demons elementals enemy invulnerable making one only preventing sec target time up works", { ko = "적을 차원의 저편으로 추방하여 어떤 행동도 하지 못하게 만듭니다. 최대 {1}초 동안 이 대상에겐 어떤 피해도 입히지 못합니다. 동시에 한 대상만 추방할 수 있습니다. 악마와 정령에게만 사용할 수 있습니다.", zhCN = "放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续{1}秒。每个术士在同一时间内只能放逐一个目标，只能对恶魔和元素生物使用。", zhTW = "放逐敵對目標，使其完全無法行動，但也不會受到任何傷害，最多持續{1}秒。每個術士在同一時間內只能放逐一個目標，只能對惡魔和元素生物使用。" }, "n" },
	{ "bashes damage shield target", { ko = "적을 방패로 가격하여 {1}의 피해를 입힙니다." }, "n" },
	{ "also any bashes being cast damage interrupts prevents school sec shield spell spellcasting target", { ko = "적을 방패로 가격하여 {1}의 피해를 입힙니다. 또한 대상이 {2}초 동안 같은 계열의 주문을 시전하는 것을 방해합니다.", zhCN = "使用你的盾牌重击目标，对其造成{1}点伤害，并使其无法施放法术，持续{2}秒。", zhTW = "使用你的盾牌重擊目標，對其造成{1}點傷害，並使其無法施放法術，持續{2}秒。" }, "n,n" },
	{ "begins doomguard participant random ritual sacrifices summon", { ko = "참가자 중 한명을 무작위로 제물로 바쳐 파멸의수호병을 소환하는 의식을 올립니다.", zhTW = "進行儀式，犧牲一名隨機參與者以召喚末日守衛。" }, "" },
	{ "additional all attack begins caster click complete doomguard immediately members move must not order participant participants participate party players portal random requires right ritual sacrifices subjugated summon until will", { ko = "참가자 중 한명을 무작위로 제물로 바쳐 파멸의수호병을 소환하는 의식을 올립니다. 파멸의 수호병을 즉시 예속하지 않으면 의식에 참가한 사람을 공격합니다. 의식을 수행하려면 흑마법사를 제외하고 파티원 {1}명이 필요합니다. 의식에 참가하려는 플레이어는 파멸의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhCN = "进行祭祀仪式，随机牺牲一个参与者以召唤出一个末日守卫。你必须立即征服末日守卫，否则它就会攻击参与仪式者。需要施法者和{1}个队友共同进行仪式，所有参与者都必须使用右键点击传送门，在完成仪式之前不得移动。", zhTW = "進行儀式，犧牲一名隨機參與者以召喚末日守衛。務必立刻制伏該末日守衛，否則它就會攻擊儀式參與者。需要施法者以及{1}名額外的隊伍成員才能完成儀式。所有參與者都必須使用右鍵點擊傳送門，並且在完成儀式之前不得移動。" }, "n" },
	{ "begins group member ritual summons targeted", { ko = "대상 파티원을 소환하는 의식을 시작합니다.", zhCN = "开启一个召唤指定队友的传送门。", zhTW = "開啟一個召喚指定隊友的傳送門。" }, "" },
	{ "additional all begins caster click combat complete group member members move must not order out participate party players portal requires right ritual summons targeted until", { ko = "대상 파티원을 소환하는 의식을 시작합니다. 의식을 수행하려면 흑마법사를 제외하고 파티원 {1}명이 필요합니다. 의식에 참가하려는 플레이어는 비전투 상태여야 하며 소환의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.", zhCN = "开启一个召唤指定队友的传送门。需要施法者和{1}名队友共同完成召唤仪式。所有参与召唤的队友都必须使用右键点击传送门，并且在召唤完成之前不得移动。", zhTW = "開啟一個召喚指定隊友的傳送門。需要施法者和{1}名隊友共同完成召喚儀式。所有參與召喚的隊友都必須必須離開交戰狀態並使用右鍵點擊傳送門，並且在召喚完成之前不得移動。" }, "n" },
	{ "beast begins companion taming", { ko = "야수를 길들여 친구로 만듭니다." }, "" },
	{ "any armor attention beast beast's begins companion disloyal fail feeding focus happy if immediately lose make once pet process reason reduced sec tamed taming try unhappy very while will", { ko = "야수를 길들여 친구로 만듭니다. 야수를 길들이는 데 집중하는 {2}초 동안은 방어도가 {1}%만큼 감소합니다. 만약 이 동안 어떤 이유로든 야수의 주의가 딴데로 돌아가게 된다면 길들이는 것은 실패하게 됩니다. 길들이는 데 성공하면 만족도와 충성도가 매우 낮습니다. 즉시 먹을 것을 줘서 만족도를 높이도록 하십시오.", zhCN = "尝试驯服一只野兽，使其成为你的宠物。在这个过程中，你的护甲值降低{1}%，持续{2}秒。如果你因为任何原因失去了它的注意力，则驯服过程失败。刚刚被驯服的野兽会表现得非常烦躁而不可靠，立刻给它喂食可以让它高兴一些。", zhTW = "嘗試馴服一隻野獸，使其成為你的寵物。在這個過程中，你的護甲值降低{1}%，持續{2}秒。如果你因為任何原因失去了它的注意力，則馴服過程失敗。剛剛被馴服的野獸會表現得非常煩躁而不可靠，立刻給它餵食可以讓它高興一些。" }, "p,n" },
	{ "attacked being cancels effect", { ko = "공격을 받게 되면 효과가 취소됩니다.", zhCN = "被攻击会中断这个效果。", zhTW = "受到攻擊會取消此效果。" }, "" },
	{ "amount bite damage dealing generating high normal plus target threat", { ko = "대상을 물어뜯어 일반 피해의 {1}%에 {2}의 추가 피해를 입히고 높은 위협 수준을 생성합니다." }, "p,n" },
	{ "blasts damage fire target", { ko = "적을 강타하여 {1}의 화염 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点火焰伤害。", zhTW = "衝擊目標，對其造成{1}點火焰傷害。" }, "n" },
	{ "blasts damage frost target", { ko = "적을 강타하여 {1}의 냉기 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点冰霜伤害。", zhTW = "衝擊目標，對其造成{1}點冰霜傷害。" }, "n" },
	{ "blasts damage nature target", { ko = "적을 강타하여 {1}의 자연 피해를 입힙니다.", zhCN = "冲击目标，对其造成{1}点自然伤害。", zhTW = "衝擊目標，對其造成{1}點自然傷害。" }, "n" },
	{ "blasts damage mechanical nature take target targets", { ko = "대상에게 {1}의 자연 피해를 입힙니다. 기계 대상은 {2}배의 피해를 받습니다.", zhCN = "轰击目标，造成{1}点自然伤害。机械目标会受到{2}x倍的伤害。", zhTW = "衝擊目標，對其造成{1}點自然傷害。機械目標受到{2}x點傷害。" }, "n,n" },
	{ "blasts caster damage enemies freezes frost near place sec them up", { ko = "주위의 적을 냉기로 강타하여 {1}에서 {2}의 냉기 피해를 입히고 최대 {3}초 동안 그 자리에 얼어붙게 만듭니다.", zhCN = "冲击施法者附近的所有敌人，对它们造成{1}至{2}点冰霜伤害并将其冻结在原地，最多持续{3}秒。", zhTW = "衝擊施法者附近的所有敵人，對它們造成{1}點到{2}點冰霜傷害並將其凍結在原地，最高可持續{3}秒。" }, "n,n,n" },
	{ "blasts caster caused damage effect enemies freezes frost interrupt may near place sec them up", { ko = "주위의 적을 냉기로 강타하여 {1}에서 {2}의 냉기 피해를 입히고 최대 {3}초 동안 그 자리에 얼어붙게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.", zhCN = "冲击施法者附近的所有敌人，对它们造成{1}至{2}点冰霜伤害并将其冻结在原地，最多持续{3}秒。对被冻结的目标造成伤害可能打断这个效果。", zhTW = "衝擊施法者附近的所有敵人，對它們造成{1}點到{2}點冰霜傷害並將其凍結在原地，最高可持續{3}秒。任何傷害將會中止此效果。" }, "n,n,n" },
	{ "attacks between blasts damage doing enemies increasing nearby sec their them thunder time", { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" }, "p,n,n" },
	{ "affect attacks between blasts damage doing enemies increasing nearby sec targets their them thunder time up will", { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다. 최대 {4}명의 대상에게 영향을 줍니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" }, "p,n,n,n" },
	{ "attacks between blasts damage doing enemies increasing nearby sec their them thunder time", { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" }, "p,n,n" },
	{ "affect attacks between blasts damage doing enemies increasing nearby sec targets their them thunder time up will", { ko = "주위 적을 천둥벼락으로 강타하여 {3}의 피해를 입히고 {2}초 동안 적의 공격 간격을 {1}%만큼 증가시킵니다. 최대 {4}명의 대상에게 영향을 줍니다.", zhCN = "以雷霆冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以雷霆震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" }, "p,n,n,n" },
	{ "attacks between blasts damage doing enemies increasing nearby sec their them time", { ko = "주위 적을 강타하여 {2}의 피해를 입히고 {3}초 동안 적의 공격 간격을 {1}%만큼 늘입니다.", zhCN = "冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。", zhTW = "以震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。" }, "p,n,n" },
	{ "affect attacks between blasts damage doing enemies increasing nearby sec targets their them time up will", { ko = "주위 적을 강타하여 {2}의 피해를 입히고 {3}초 동안 적의 공격 간격을 {1}%만큼 늘입니다. 최대 {4}개의 대상에게 영향을 미칩니다.", zhCN = "冲击附近的敌人，使其攻击间隔延长{1}%，持续{2}秒，并对其造成{3}点伤害。最多影响{4}个目标。", zhTW = "以震擊附近的敵人，使他們的攻擊間隔時間延長{1}%，持續{2}秒，並對他們造成{3}點傷害。最多可影響{4}個目標。" }, "p,n,n,n" },
	{ "blasts damage enemy fire", { ko = "적을 강타하여 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "施放火焰冲击敌人，对其造成{1}至{2}点火焰伤害。", zhTW = "施放火焰衝擊敵人，對其造成{1}至{2}點火焰傷害。" }, "n,n" },
	{ "amount blasts but causes damage high shadow target threat", { ko = "대상의 정신을 분열시켜 {1}~{2}의 암흑 피해를 입힙니다. 대상에 대한 위협 수준이 크게 증가합니다.", zhCN = "用暗影魔法冲击敌人，对其造成{1}至{2}点暗影伤害，同时产生很高的威胁值。", zhTW = "用暗影魔法衝擊敵人，對敵人造成{1}至{2}點暗影傷害，同時產生很高的威脅值。" }, "n,n" },
	{ "arcane blasts damage dealing energy target", { ko = "적을 강력한 에너지로 강타하여 {1}~{2}의 비전 피해를 입힙니다.", zhCN = "用能量冲击目标，造成{1}至{2}点奥术伤害。", zhTW = "以能量衝擊目標，對其造成{1}至{2}點秘法傷害。" }, "n,n" },
	{ "all any arcane blast blasts cast cost damage dealing each effect energy increased lasts mana other sec spell spells stacks target time times until up", { ko = "적을 강력한 에너지로 강타하여 {1}~{2}의 비전 피해를 입힙니다. 이 주문을 시전할 때마다 다른 모든 주문의 공격력이 {3}%만큼, 비전 작렬 주문의 마나 소모량이 {4}%만큼 증가합니다. 이 효과는 최대 {5}번까지 중첩되며 {6}초 동안 혹은 비전 작렬을 제외한 다른 공격 주문 시전 시까지 지속됩니다.", zhCN = "用能量冲击目标，造成{1}至{2}点奥术伤害。每次施放奥术冲击，所有其他法术的伤害提高{3}%，奥术冲击的法力消耗提高{4}%。该效果最多叠加{5}次，持续{6}秒，或直到施放任何其他伤害法术。", zhTW = "以能量衝擊目標，對其造成{1}至{2}點秘法傷害。每次施放秘法衝擊時會使你所有其他法術的傷害提高{3}%，並且秘法衝擊的法力消耗提高{4}%。此效果最多可堆疊{5}次，持續{6}秒，或直到施放任何其他傷害性法術為止。" }, "n,n,p,p,n,n" },
	{ "ally blasts causing damage enemy energy healing holy target", { ko = "대상을 성스러운 기운으로 강타하여 {1}~{2}의 신성 피해를 입히거나, 아군의 생명력을 {3}~{4}만큼 회복시킵니다.", zhCN = "以神圣能量冲击目标，对一个敌人造成{1}至{2}点神圣伤害，或者为一个友方目标恢复{3}至{4}点生命值。", zhTW = "以神聖的能量衝擊目標，造成{1}至{2}點神聖傷害，或為盟友恢復{3}至{4}點生命力。" }, "n,n,n,n" },
	{ "blinds causing disoriented sec target up wander", { ko = "대상의 눈을 멀게 해 최대 {1}초 동안 방황하게 만듭니다.", zhCN = "使目标暂时失明并到处乱走，持续最多{1}秒。", zhTW = "使目標暫時失明，在周圍盲目地遊蕩，持續最多{1}秒。" }, "n" },
	{ "any blinds caused causing damage disoriented effect remove sec target up wander will", { ko = "대상의 눈을 멀게 해 최대 {1}초 동안 방황하게 만듭니다. 피해를 입게 되면 효과가 사라집니다.", zhCN = "使目标暂时失明并到处乱走，持续最多{1}秒。任何对其造成的伤害都会解除此效果。", zhTW = "使目標暫時失明，在周圍盲目地遊蕩，持續最多{1}秒。任何對其造成的傷害都會解除此效果。" }, "n" },
	{ "back brings dead health life mana player", { zhCN = "复活一个死去的玩家，复活后该玩家拥有{1}点生命值和{2}点法力值。", zhTW = "復活一個死去的玩家，復活後該玩家擁有{1}點生命力和{2}點法力。" }, "n,n" },
	{ "back brings cannot cast combat dead health life mana player when", { ko = "죽은 플레이어를 되살립니다. 대상은 {1}의 생명력과 {2}의 마나를 지닌 채로 되살아납니다. 전투 중에는 사용할 수 없습니다.", zhCN = "复活一个死去的玩家，复活后该玩家拥有{1}点生命值和{2}点法力值。无法在战斗中使用。", zhTW = "復活一個死去的玩家，復活後該玩家擁有{1}點生命力和{2}點法力。無法在戰鬥中使用。" }, "n,n" },
	{ "additional allows basic builds camp campfire cooking features placement up", { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 기본 모닥불을 만듭니다.", zhCN = "生起一堆基础营火，可以用来烹饪，并允许额外放置最多{1}个露营设施。", zhTW = "升起基礎營火，可用來烹飪，以及設置最多額外{1}個營地功能。" }, "n" },
	{ "additional allows basic benefits builds camp campfire cooking crafting features gain min nearby other placement players sitting up will", { ko = "요리에 사용할 수 있고 최대 {1}개의 추가 야영 요소를 배치할 수 있게 하는 기본 모닥불을 만듭니다. 주위에서 {2}분 동안 앉아 있거나 제작을 하는 플레이어는 다른 야영 설비의 이로운 효과를 받습니다.", zhCN = "生起一堆基础营火，可以用来烹饪，并允许额外放置最多{1}个露营设施。在附近坐下或制造物品持续{2}分钟的玩家将获得其他露营设施的增益。", zhTW = "升起基礎營火，可用來烹飪，以及設置最多額外{1}個營地功能。玩家在附近坐下或製作物品，持續{2}分鐘，就能獲得其他營地功能的增益效果。" }, "n,n" },
