	{ "affect can higher levels only targets than up", { ko = "시전자보다 레벨이 최대 {1}만큼 높은 대상에게만 영향을 줍니다.", zhCN = "只能影响等级最多高于你{1}级的目标。", zhTW = "只能影響等級最多高於你{1}級的目標。" }, "n" },
