	{ "cast causes holy light next reduce sec shock time within", { ko = "신성 충격 사용 시 {1}초 안에 시전하는 다음 성스러운 빛의 시전 시간이 -{2}.{3}초만큼 감소합니다.", zhCN = "使神圣震击令你在{1}秒内施放的下一个圣光术的施法时间缩短-{2}.{3}秒。", zhTW = "使神聖震擊令你在{1}秒內施放的下一個聖光術的施法時間縮短-{2}.{3}秒。" }, "n,n,n" },
	{ "causes damage enemy horror run sec shadow target", { ko = "적을 {1}초 동안 공포에 질려 달아나게 만들고 {2}의 암흑 피해를 입힙니다." }, "n,n" },
	{ "caster caused causes damage enemy gains health horror run sec shadow target", { ko = "적을 {1}초 동안 공포에 질려 달아나게 만들고 {2}의 암흑 피해를 입힙니다. 시전자는 입힌 피해의 {3}%만큼 생명력을 회복합니다.", zhCN = "使目标因恐惧而逃跑，持续{1}秒，并对其造成{2}点暗影伤害，所有伤害都被用来治疗施法者。", zhTW = "使目標因恐懼而逃跑，持續{1}秒，並對其造成{2}點暗影傷害，所有傷害都被用來治療施法者。" }, "n,n,p" },
	{ "causes chance have mana restore wrath", { ko = "천벌 사용 시 {1}%의 확률로 {2}의 마나를 회복합니다.", zhCN = "使愤怒有{1}%的几率恢复{2}点法力值。", zhTW = "使憤怒有{1}%的機率恢復{2}點法力。" }, "p,n" },
	{ "ability armor attacks causes damage dealt ignore increases rupture target's", { ko = "공격 시 대상의 방어도를 {1}%만큼 무시하며, 파열로 입히는 피해가 {2}%만큼 증가합니다.", zhCN = "使你的攻击忽略目标{1}%的护甲，并使你的割裂技能造成的伤害提高{2}%。", zhTW = "使你的攻擊無視目標{1}%的護甲值，並使割裂技能造成的傷害提高{2}%。" }, "p,p" },
