	{ "blast chance damage fire hit target", { ko = "적중 시 일정 확률로 대상에게 {1}의 화염 피해를 입힙니다.", zhCN = "击中时有几率轰击目标，造成{1}点火焰伤害。", zhTW = "命中時有機率衝擊目標，造成{1}點火焰傷害。" }, "n" },
	{ "caster's changes location targeted viewpoint", { ko = "시전자의 시야를 지정한 곳으로 이동하여 먼 곳까지 볼 수 있게 합니다." }, "" },
	{ "caster's changes lasts location min only outdoors targeted useable viewpoint", { ko = "시전자의 시야를 지정한 곳으로 이동하여 먼 곳까지 볼 수 있게 합니다. {1}분 동안 지속됩니다. 야외에서만 사용할 수 있습니다.", zhCN = "将施法者的视点切换到目标区域，持续{1}分钟。只能在户外使用。", zhTW = "將施法者的視點切換到目標區域，持續{1}分鐘。只能在戶外使用。" }, "n" },
	{ "all bolt caster causing channels damage enemies front hurls lightning nature towards", { ko = "번개를 집중시켜 시전자 전방의 모든 적에게 날려보내 {1}의 자연 피해를 입힙니다.", zhCN = "引导一道闪电并将其掷向施法者前方的所有敌人，造成{1}点自然伤害。", zhTW = "導引一發閃電箭攻擊施法者面前所有敵人，造成{1}點自然傷害。" }, "n" },
