	{ "causing charge damage enemy sec stunning", { ko = "적에게 돌격하여 {1}의 피해를 입히고 {2}초 동안 기절시킵니다.", zhCN = "向敌人冲锋，造成{1}点伤害，并使其昏迷{2}秒。", zhTW = "向敵人衝鋒，造成{1}點傷害，並使其昏迷{2}秒。" }, "n,n" },
	{ "charge enemy generate rage sec stun", { ko = "적에게 돌진하여 {1}의 분노를 얻고 {2}초 동안 기절시킵니다.", zhCN = "向一名敌人冲锋，产生{1}点怒气，并使其昏迷{2}秒。", zhTW = "向敵人衝鋒，產生{1}點怒氣，並使其昏迷{2}秒。" }, "n,n" },
	{ "cannot charge combat enemy generate rage sec stun used", { ko = "적에게 돌진하여 {1}의 분노를 얻고 {2}초 동안 기절시킵니다. 전투 중에는 사용할 수 없습니다.", zhCN = "向一名敌人冲锋，产生{1}点怒气，并使其昏迷{2}秒。无法在战斗中使用。", zhTW = "向敵人衝鋒，產生{1}點怒氣，並使其昏迷{2}秒。無法在戰鬥中使用。" }, "n,n" },
	{ "any casting charge enemy immobilizing interrupting sec spell them they", { ko = "적에게 돌진해 {1}초 동안 이동 불가 상태로 만들고 시전 중인 주문을 방해합니다.", zhCN = "向敌人冲锋，使其无法移动，并打断其正在施放的任何法术，持续{1}秒。", zhTW = "向目標衝鋒，使其無法移動，並使其在{1}秒內不能施放任何法術。" }, "n" },
	{ "any behind casting charge enemy immobilizing interrupting leap sec spell them they", { ko = "적에게 돌진해 {1}초 동안 이동 불가 상태로 만들고 시전 중인 주문을 방해합니다. 적의 배후로 도약합니다.", zhCN = "向敌人冲锋，使其无法移动，并打断其正在施放的任何法术，持续{1}秒。 跳跃到敌人的背后。", zhTW = "向敵人衝鋒，使其無法移動，並打斷其正在施放的任何法術，持續{1}秒。 跳躍到敵人的背後。" }, "n" },
	{ "causing chastise damage holy immobilizing sec target them up", { ko = "대상을 응징하여 {1}~{2}의 신성 피해를 입히고 최대 {3}초 동안 이동 불가 상태로 만듭니다." }, "n,n,n" },
	{ "against causes causing chastise damage holy humanoids immobilizing low only sec spell target them threat up very works", { ko = "대상을 응징하여 {1}~{2}의 신성 피해를 입히고 최대 {3}초 동안 이동 불가 상태로 만듭니다. 인간형에게만 효과를 발휘합니다. 이 주문은 매우 낮은 위협 수준을 생성합니다." }, "n,n,n" },
	{ "claw damage enemy normal plus", { ko = "적을 발톱으로 할퀴어 일반 공격력의 {1}%에 해당하는 피해와 {2}의 추가 피해를 입힙니다.", zhCN = "爪击敌人，造成{1}%普通伤害，外加{2}点伤害。", zhTW = "用爪攻擊敵人，造成{1}%普通傷害再加上{2}點額外傷害。" }, "p,n" },
	{ "awards claw combo damage enemy normal plus point", { ko = "적을 발톱으로 할퀴어 일반 공격력의 {1}%에 해당하는 피해와 29의 추가 피해를 입힙니다. 연계 점수 {3}점을 생성합니다.", zhCN = "爪击敌人，造成{1}%普通伤害，外加29点伤害。奖励{3}个连击点。", zhTW = "用爪攻擊敵人，造成{1}%普通傷害再加上29點額外傷害。獎勵{3}個連擊點數。" }, "p,n,n" },
	{ "causing claw damage enemy", { ko = "적을 할퀴어 {1} 에서 {2}의 피해를 입힙니다.", zhCN = "用爪攻击敌人，对其造成{1}至{2}点伤害。", zhTW = "用爪攻擊敵人，對其造成{1}至{2}點傷害。" }, "n,n" },
	{ "cleanses disease effect friendly magic poison removing target", { ko = "대상을 정화하여 아군에게서 독 {1}개와 질병 {2}개, 마법 효과 {3}개를 제거합니다.", zhCN = "净化一个友方目标，驱散{1}个中毒效果，{2}个疾病效果和{3}个魔法效果。", zhTW = "淨化一個友方目標，驅散{1}個中毒效果，{2}個疾病效果和{3}個魔法效果。" }, "n,n,n" },
	{ "abilities clearcasting consumed cost no not resources spells wrath", { ko = "번뜩임은 천벌 또는 자원을 소모하지 않는 주문이나 능력으로는 소모되지 않습니다.", zhCN = "愤怒以及不消耗资源的法术或技能不会消耗节能施法。", zhTW = "節能施法效果不會被憤怒或不消耗資源的法術/技能消耗。" }, "" },
	{ "clears duration effects fear grants immunity", { ko = "공포 효과를 해제하고 지속시간 동안 공포에 면역이 됩니다." }, "" },
	{ "cloaks field min stealth up user", { ko = "최대 {1}분 동안 사용자를 은신 영역으로 감쌉니다.", zhCN = "使使用者笼罩在潜行力场中，最多持续{1}分钟。", zhTW = "將使用者罩在潛行力場中，最多持續{1}分鐘。" }, "n" },
