	{ "coats lasts min poison weapon", { ko = "무기에 {1}분 동안 유지되는 독을 바릅니다.", zhCN = "给一件武器浸毒，效果持续{1}分钟。", zhTW = "給一件武器浸毒，效果持續{1}分鐘。" }, "n" },
	{ "assault attack bomb command continuing damage dealing dive enemy hawk physical power ranged sec targeted", { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}(+ 원거리 전투력의 {2}%)의 물리 피해를 입히고 {3}초 동안 지속적으로 공격을 퍼붓게 합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}（+远程攻击强度的{2}%）点物理伤害并继续攻击{3}秒。", zhTW = "命令一隻雄鷹俯衝轟炸目標敵人，造成{1}（+遠程攻擊強度的{2}%）點物理傷害並繼續攻擊{3}秒。" }, "n,p,n" },
	{ "active arcane assault attack bomb can command continuing cooldown damage dealing dive enemy hawk hawks once only physical power ranged sec shares shot summon targeted", { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}(+ 원거리 전투력의 {2}%)의 물리 피해를 입히고 {3}초 동안 지속적으로 공격을 퍼붓게 합니다. 매는 한 번에 {4}마리만 활성화될 수 있습니다. 매 소환은 신비한 사격과 재사용 대기시간을 공유합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}（+远程攻击强度的{2}%）点物理伤害并继续攻击{3}秒。同时最多只能激活{4}只雄鹰。召唤雄鹰与奥术射击共享冷却时间。", zhTW = "命令一隻雄鷹俯衝轟炸目標敵人，造成{1}（+遠程攻擊強度的{2}%）點物理傷害並繼續攻擊{3}秒。同時最多隻能啟用{4}只雄鷹。召喚獵鷹與秘法射擊共享冷卻時間。" }, "n,p,n,n" },
	{ "assault bomb command continuing damage dealing dive enemy hawk physical sec targeted", { ko = "매에게 명령을 내려, 대상 적에게 급강하해 {1}의 물리 피해를 입히고 {2}초 동안 지속적으로 공격을 퍼붓게 합니다.", zhCN = "命令一只雄鹰俯冲轰炸目标敌人，造成{1}点物理伤害并继续攻击{2}秒。", zhTW = "命令一隻獵鷹俯衝攻擊鎖定的敵人，造成{1}點物理傷害並持續進行攻擊，持續{2}秒。" }, "n,n" },
