	{ "concuss movement sec slowing speed target", { ko = "대상에게 뇌진탕을 일으켜 {2}초 동안 이동 속도를 {1}%만큼 감소시킵니다.", zhCN = "震荡目标，使其移动速度降低{1}%，持续{2}秒。", zhTW = "震盪目標，使其移動速度降低{1}%，持續{2}秒。" }, "p,n" },
