	{ "area attacks between causing creates damage enemies every increasing nature sec storm target time violent", { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 적의 공격 간격을 {3}%만큼 늘입니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使敌人的攻击间隔延长{3}%。" }, "n,n,p" },
	{ "area attacks between causing channel creates damage druid enemies every increasing lasts maintain must nature sec spell storm target time violent", { ko = "대상 지역에 맹렬한 폭풍을 생성하여 {2}초마다 적에게 {1}의 자연 피해를 입히고 적의 공격 간격을 {3}%만큼 늘입니다. {4}초 동안 지속됩니다. 주문을 유지하려면 계속 정신을 집중해야 합니다.", zhCN = "在目标区域制造一场猛烈风暴，每{2}秒对敌人造成{1}点自然伤害，并使敌人的攻击间隔延长{3}%。持续{4}秒。德鲁伊必须持续引导才能维持该法术。", zhTW = "在施法者指定的區域製造一場強烈的風暴，對範圍內的所有敵人每{2}秒造成{1}點自然傷害，並使其攻擊間隔時間延長{3}%，持續{4}秒。德魯伊必須引導以維持法術效果。" }, "n,n,p,n" },
	{ "all chance critical damage increased strike taken", { ko = "치명타 및 극대화율이 {1}%만큼 증가하지만, 받는 모든 피해가 {2}%만큼 증가합니다.", zhCN = "爆击几率提高{1}%，受到的所有伤害提高{2}%。" }, "p,p" },
	{ "cures effect poison target", { ko = "대상에 걸린 {1}개의 독을 치료합니다.", zhCN = "治愈目标身上的{1}个中毒效果。", zhTW = "治癒目標身上的{1}個中毒效果。" }, "n" },
	{ "curse each every idiocy intellect reduced reducing sec spirit target total until", { zhCN = "使目标受到痴呆的诅咒，每{2}秒降低{1}点智力和精神，直到这两种属性都被降低了{3}点为止。", zhTW = "使目標受到癡呆的詛咒，每{2}秒降低{1}點智力和精神，直到這兩種屬性都被降低了{3}點。" }, "n,n,n" },
	{ "active any can curse each every idiocy intellect one only per reduced reducing sec spirit target total until warlock", { ko = "무지의 저주를 걸어 매 {2}초마다 지능과 정신력을 {1}씩 감소시킵니다. 최대 90까지 감소됩니다. 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "使目标受到痴呆的诅咒，每{2}秒降低{1}点智力和精神，直到这两种属性都被降低了90点为止。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", zhTW = "使目標受到癡呆的詛咒，每{2}秒降低{1}點智力和精神，直到這兩種屬性都被降低了90點。每個術士只能對一個目標施加一種詛咒，且同類詛咒不能疊加。" }, "n,n,n" },
	{ "cursed effects enemies fear flee horror ignore not will", { ko = "이 마법이 지속되는 한 대상은 도망치지 않으며 겁이나 공포 효과를 무시합니다.", zhCN = "被诅咒的敌人不会逃跑，并会无视恐惧和惊骇效果。", zhTW = "被詛咒的敵人不會逃跑，也不會受到恐懼的影響。" }, "" },
	{ "curses damage increases magic min reducing resistances taken target", { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다.", zhCN = "诅咒目标，持续{1}分钟，使其魔法抗性降低{2}点，受到的魔法伤害提高{3}%。", zhTW = "對目標施放詛咒，使其魔法抗性降低{2}點，並且受到的魔法傷害提高{3}%，效果持續{1}分鐘。" }, "n,n,p" },
	{ "active any can curse curses damage increases magic min one only per reducing resistances taken target warlock", { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "诅咒目标，持续{1}分钟，使其魔法抗性降低{2}点，受到的魔法伤害提高{3}%。每个术士对同一目标同时只能施加一种诅咒。", zhTW = "對目標施放詛咒，使其魔法抗性降低{2}點，並且受到的魔法傷害提高{3}%，效果持續{1}分鐘。每個術士只能對一個目標施加一種詛咒。" }, "n,n,p" },
	{ "curses damage increasing magic min reducing resistances taken target", { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다." }, "n,n,p" },
	{ "active any can curse curses damage increasing magic min one only per reducing resistances taken target warlock", { ko = "저주를 걸어 {1}분 동안 마법 저항력을 {2}만큼 감소시키고, 받는 마법 피해는 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다." }, "n,n,p" },
	{ "arcane curses damage increasing min reducing resistances shadow taken target", { ko = "저주를 걸어 {1}분 동안 대상의 암흑과 비전 마법에 대한 저항력을 {2}만큼 감소시키고 받는 암흑과 비전 피해를 {3}%만큼 증가시킵니다.", zhCN = "对目标施放诅咒，使其暗影和奥术抗性降低{2}点，受到暗影和奥术系攻击时所承受的伤害提高{3}%，效果持续{1}分钟。", zhTW = "對目標施放詛咒，使其暗影和秘法抗性降低{2}點，受到暗影和秘法系攻擊時所承受的傷害提高{3}%，效果持續{1}分鐘。" }, "n,n,p" },
	{ "active any arcane can curse curses damage increasing min one only per reducing resistances shadow taken target warlock", { ko = "저주를 걸어 {1}분 동안 대상의 암흑과 비전 마법에 대한 저항력을 {2}만큼 감소시키고 받는 암흑과 비전 피해를 {3}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "对目标施放诅咒，使其暗影和奥术抗性降低{2}点，受到暗影和奥术系攻击时所承受的伤害提高{3}%，效果持续{1}分钟。每个术士只能对一个目标施加一种诅咒，且同类诅咒不能叠加。", zhTW = "對目標施放詛咒，使其暗影和秘法抗性降低{2}點，受到暗影和秘法系攻擊時所承受的傷害提高{3}%，效果持續{1}分鐘。每個術士只能對一個目標施加一種詛咒，且同類詛咒不能疊加。" }, "n,n,p" },
	{ "armor curses min recklessness reducing target target's", { ko = "무모함의 저주를 걸어 {2}분 동안 대상의 방어도를 {1}만큼 감소시킵니다.", zhCN = "以鲁莽诅咒目标，使其护甲降低{1}点，持续{2}分钟。", zhTW = "對目標施加魯莽的詛咒，使其護甲值降低{1}點，持續{2}分鐘。" }, "n,n" },
	{ "active any armor can curse cursed curses effects enemies fear flee horror ignore min not one only per recklessness reducing target target's warlock will", { ko = "무모함의 저주를 걸어 {2}분 동안 대상의 방어도를 {1}만큼 감소시킵니다. 이 마법이 지속되는 한 대상은 도망치지 않으며 겁이나 공포 효과를 무시합니다. 흑마법사마다 한 대상에 하나의 저주만 걸 수 있습니다.", zhCN = "以鲁莽诅咒目标，使其护甲降低{1}点，持续{2}分钟。被诅咒的敌人不会逃跑，并会无视恐惧和惊骇效果。每个术士在任一目标身上只能维持一种诅咒。", zhTW = "對目標施加魯莽的詛咒，使其護甲值降低{1}點，持續{2}分鐘。被詛咒的敵人不會逃跑，也不會受到恐懼的影響。每個術士只能對同一個目標施加一種詛咒。" }, "n,n" },
