	{ "additional afflicted damage deals fire if immolate target", { ko = "대상에게 {1}~{2}의 화염 피해를 입힙니다. 또한 대상에게 제물이 걸려 있으면 {3}%의 추가 피해를 입힙니다.", zhCN = "对你的目标造成{1}至{2}点火焰伤害，如果目标受到献祭的影响，则额外造成{3}%的伤害。", zhTW = "對你的目標造成{1}至{2}點火焰傷害，如果目標受獻祭影響會額外造成{3}%傷害。" }, "n,n,p" },
	{ "damage deals enemy frost target", { ko = "적 대상에게 {1}~{2}의 냉기 피해를 입힙니다.", zhCN = "对一个敌方目标造成{1}至{2}点冰霜伤害。", zhTW = "對一個敵方目標造成{1}至{2}點冰霜傷害。" }, "n,n" },
