	{ "absorbed damage drains mana per", { ko = "흡수된 피해당 {1}의 마나를 소비합니다.", zhCN = "每吸收1点物理伤害，就消耗{1}点法力值。", zhTW = "每吸收1點物理傷害，就消耗{1}點法力。" }, "n" },
	{ "drains mana pet's returning", { ko = "소환수에게서 {1}의 마나를 흡수하여 그의 {2}%에 해당하는 마나를 자신의 것으로 만듭니다.", zhCN = "从你的宠物身上抽取{1}点法力值并全部转化给你。", zhTW = "從你的寵物身上抽取{1}點法力並全部轉化給你。" }, "n,p" },
	{ "damage drained drains each mana shadow takes target way", { ko = "대상의 마나를 {1}~{2}만큼 소진시킵니다. 대상은 소진된 마나의 절반만큼 암흑 피해를 입습니다.", zhCN = "从目标身上吸取{1}至{2}点法力值，每吸取1点法力值，目标就受到{3}点伤害。", zhTW = "從目標身上吸取{1}至{2}點法力，每吸取1點法力，目標就受到{3}點傷害。" }, "n,n,n" },
	{ "all but does drains interrupt mana not paladin's regeneration remaining used when", { ko = "이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" }, "" },
	{ "causing damage drains over sec shadow soul target", { ko = "적의 영혼을 소진시켜 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다.", zhCN = "吸取目标的灵魂，在{2}秒内造成{1}点暗影伤害。", zhTW = "吸取目標的靈魂，在{2}秒內對其造成累計{1}點暗影傷害。" }, "n,n" },
	{ "always causing chance damage damaged drain drains grant have killed non other over required sec shadow shard shards soul spells target targets trivial will", { ko = "적의 영혼을 소진시켜 {2}초에 걸쳐 {1}의 암흑 피해를 입힙니다. 영혼 흡수로 사소하지 않은 대상에게 피해를 입히면 일정 확률로 영혼의 조각을 얻습니다. 영혼 흡수로 사소하지 않은 대상을 처치하면 항상 영혼의 조각을 얻습니다. 영혼의 조각은 다른 흑마법에 사용됩니다.", zhCN = "吸取目标的灵魂，在{2}秒内造成{1}点暗影伤害。对能为你提供经验值或荣誉值的敌人造成吸取灵魂伤害时，有几率使你获得一块灵魂碎片。消灭一个能为你提供经验值或荣誉值的敌人且其死于吸取灵魂时，必定使你获得一块灵魂碎片。灵魂碎片是施放其他法术所需的材料。", zhTW = "吸取目標的靈魂，在{2}秒內對其造成累計{1}點暗影傷害。以吸取靈魂對有實力的目標造成傷害時，有一定機率使你獲得一塊靈魂裂片。以吸取靈魂擊殺有實力的目標時，則一律獲得一塊靈魂裂片。靈魂碎片是施放其他一些法術所必需的材料。" }, "n,n" },
	{ "absorbing damage draws member party shield soul them", { ko = "파티원의 영적인 힘을 이용하여 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다.", zhCN = "汲取一名队伍成员的灵魂力量，为其施加护盾，吸收{1}点伤害。", zhTW = "汲取隊友的靈魂之力，為其加上魔法護盾，可吸收{1}點傷害。" }, "n" },
	{ "absorbing again cannot damage draws holds interrupted lasts member not once party sec shield shielded soul spellcasting target them while will", { ko = "파티원의 영적인 힘을 이용하여 즉시 보호막을 생성하여 {1}의 피해를 흡수합니다. {2}초 동안 지속됩니다. 보호막이 지속되는 동안은 피해에 의해 주문 시전이 방해받지 않습니다. 한 번 보호막을 사용한 대상에겐 {3}초 동안 다시 보호막을 사용할 수 없습니다.", zhCN = "汲取一名队伍成员的灵魂力量，为其施加护盾，吸收{1}点伤害。持续{2}秒。护盾存在期间，其施法不会因受到伤害而被打断。受到护盾保护后，该目标在{3}秒内无法再次受到护盾保护。", zhTW = "汲取隊友的靈魂之力，為其加上魔法護盾，可吸收{1}點傷害。持續{2}秒。只要護盾存在，受保護者的施法就不會被傷害打斷。目標在被加上護盾之後的{3}秒內無法再被加上護盾。" }, "n,n,n" },
	{ "done drink effects healing increase spells up", { ko = "마시면 주문 및 효과에 의한 치유량이 최대 {1}만큼 증가합니다." }, "n" },
