	{ "drink increase lasts min strength", { ko = "마시면 힘이 10만큼 증가합니다. {2}분 동안 지속됩니다.", zhCN = "饮用以使你的力量提高10点，持续{2}分钟。", zhTW = "飲用以使你的力量提高10點，持續{2}分鐘。" }, "n,n" },
