	{ "drink every lasts mana min regenerate sec", { ko = "마시면 {2}초마다 마나를 {1}만큼 회복합니다. {3}분 동안 지속됩니다.", zhCN = "饮用以使你每{2}秒恢复{1}点法力值，持续{3}分钟。", zhTW = "飲用以使你每{2}秒恢復{1}點法力，持續{3}分鐘。" }, "n,n,n" },
