	{ "casting chance charges each enemy has increasing poisoning sec strike their time", { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 시전 시간을 {2}%만큼 지연시킵니다. {4}회 사용 가능.", zhCN = "每次攻击都有{1}%的几率令敌人中毒，使其施法时间延长{2}%，持续{3}秒。可使用{4}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其施法時間延長{2}%，持續{3}秒。可使用{4}次。" }, "p,p,n,n" },
	{ "all chance charges each effects enemy has healing poisoning reducing sec single stacks strike target them times up used", { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 대상에 대한 모든 치유 효과를 {2}만큼 감소시킵니다. 효과는 대상마다 {4}번까지 중첩될 수 있습니다. {5}회 사용 가능합니다.", zhCN = "每次攻击都有{1}%的几率使敌人中毒，使其受到的所有治疗效果降低{2}，持续{3}秒。对单一目标最多叠加{4}次。可使用{5}次。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其在受到治療時效果降低{2}點，持續{3}秒。對單一目標最多可堆疊{4}次。可使用{5}次。" }, "p,n,n,n,n" },
	{ "chance each enemy has movement poisoning sec slowing speed strike their", { ko = "매 공격 시 {1}%의 확률로 적을 중독시켜 {3}초 동안 이동 속도를 {2}%만큼 감소시킵니다.", zhCN = "每次攻击都有{1}%的几率令敌人中毒，使其移动速度降低{2}%，持续{3}秒。", zhTW = "每次攻擊都有{1}%的機率令敵人中毒，使其移動速度降低{2}%，持續{3}秒。" }, "p,p,n" },
