	{ "allows attack blessing erects exclusive gain increased lodestone melee might mutually nearby others power sitting", { ko = "자철석을 세워 자신과 주위에 앉은 다른 플레이어의 근접 전투력을 {1}만큼 증가시킵니다. 힘의 축복과 겸용해서 사용할 수 없습니다.", zhCN = "竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高{1}，与力量祝福互斥。", zhTW = "豎起一塊磁石，使你和附近坐下的其他人近戰攻擊強度提高{1}，與力量祝福互斥。" }, "n" },
	{ "all effects escape immobilizing", { ko = "모든 이동 불가 효과에서 벗어납니다.", zhCN = "解除所有定身效果。", zhTW = "擺脫所有無法移動效果。" }, "" },
	{ "against attacker causes damage every fire strike target", { ko = "이 대상을 공격할 때마다 {1}의 화염 피해를 받습니다.", zhCN = "每次击中目标都会使攻击者受到{1}点火焰伤害。", zhTW = "任何使用近戰武器擊中被保護者的敵人都會受到{1}點火焰傷害。" }, "n" },
	{ "all area enemies exposes hidden invisible sec targeted within yards", { ko = "{2}초 동안 대상 지역 주위 {1}미터 반경 내에 있는 은신이나 투명 상태에 있는 모든 적을 감지합니다.", zhCN = "侦测指定区域半径{1}码范围内的所有潜行和隐形的敌人，持续{2}秒。", zhTW = "偵測指定區域半徑{1}碼範圍內的所有潛行和隱形的敵人，持續{2}秒。" }, "n,n" },
	{ "all area darkness enemies exposes hidden invisible magical off sec staves targeted within yards", { ko = "{2}초 동안 대상 지역 주위 {1}미터 반경 내에 있는 은신이나 투명 상태의 적을 모두 감지하고, 마법의 어둠을 몰아냅니다.", zhCN = "使指定区域{1}码范围内的所有潜行和隐形的敌人暴露，并抵挡源自魔法的黑暗，持续{2}秒。", zhTW = "偵測指定區域半徑{1}碼範圍內的所有隱藏和隱形的敵人，並暫時阻擋魔法黑暗，持續{2}秒。" }, "n,n" },
	{ "attacking discouraging enemies fade out sec", { ko = "{1}초 동안 몸을 희미하게 만들어 적이 자신을 공격할 확률을 감소시킵니다.", zhCN = "渐渐消失，使敌人不再攻击你，持续{1}秒。", zhTW = "漸漸消失，使敵人不再攻擊你，持續{1}秒。" }, "n" },
	{ "attacking discouraging effective enemies fade more out rank sec than", { ko = "{1}초 동안 몸을 희미하게 만들어 적이 자신을 공격할 확률을 감소시킵니다. {2}레벨 소실보다 효과가 좋습니다.", zhCN = "渐渐消失，使敌人不再攻击你，持续{1}秒。比渐隐术（等级 {2}）的效果更好。", zhTW = "漸漸消失，使敵人不再攻擊你，持續{1}秒。比漸隱術（等級 {2}）的效果更好。" }, "n,n" },
	{ "feed item pet selected", { ko = "자신의 야수에게 선택한 먹이를 줍니다." }, "" },
