	{ "actually after cancelled death die enemies feign if ignoring lasts may min not trick which will", { ko = "적을 속여 자신이 죽은 것처럼 보이게 만듭니다. {1}분 동안 지속됩니다. 취소하지 않으면 {2}분 후에 실제로 사망합니다.", zhCN = "假死，可能使敌人忽略你。持续{1}分钟。若未取消，在{2}分钟之后你将真正死亡。", zhTW = "假死，可能使敵人忽略你。持續{1}分鐘。如果未取消，你會在{2}分鐘後真的死亡。" }, "n,n" },
	{ "damage felhunter magic reduces taken", { ko = "지옥사냥개 - 받는 마법 피해가 {1}%만큼 감소합니다.", zhCN = "地狱猎犬 - 受到的魔法伤害降低{1}%。", zhTW = "惡魔獵犬 - 受到的魔法傷害降低{1}%。" }, "p" },
	{ "every felhunter health restores sec total", { ko = "지옥사냥개: {2}초마다 전체 생명력의 {1}%에 해당하는 생명력을 회복합니다.", zhCN = "地狱猎犬：每{2}秒恢复总生命值的{1}%。", zhTW = "惡魔獵犬：使你每{2}秒恢復{1}%生命力上限。" }, "p,n" },
	{ "additional attacks causing damage deal divine fills fury holy melee paladin sec", { ko = "성기사가 {1}초 동안 거룩한 분노로 충만해져 근접 공격 시 {2}의 추가 신성 피해를 입히게 합니다.", zhCN = "以神圣愤怒充满圣骑士，持续{1}秒，使近战攻击额外造成{2}点神圣伤害。", zhTW = "神聖的憤怒充滿聖騎士的體內，使其近戰攻擊額外造成{2}點神聖傷害，持續{1}秒。" }, "n,n" },
	{ "absorb active additional also any attack attacks can causing damage deal dealt divine each equal equipped fills fury grants holy melee one only paladin seal sec shield time while", { ko = "성기사가 {1}초 동안 거룩한 분노로 충만해져 근접 공격 시 {2}의 추가 신성 피해를 입히게 합니다. 방패를 착용한 동안에는 공격할 때마다 입힌 신성 피해의 {3}%에 해당하는 피해 흡수 보호막이 부여됩니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "以神圣愤怒充满圣骑士，持续{1}秒，使近战攻击额外造成{2}点神圣伤害。装备盾牌时，每次攻击还会获得相当于所造成神圣伤害{3}%的吸收护盾。每名圣骑士在同一时间只能激活一种圣印。", zhTW = "神聖的憤怒充滿聖騎士的體內，使其近戰攻擊額外造成{2}點神聖傷害，持續{1}秒。裝備盾牌時，每次攻擊也會賦予相當於所造成神聖傷害{3}%的吸收護盾。聖騎士在同一時間內只能啟動一種聖印。" }, "n,n,p" },
	{ "attack chance divine each fills giving heal light melee paladin sec", { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 생명력을 {2}만큼 회복시킵니다.", zhCN = "神圣之光充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率回复{2}点生命值。", zhTW = "神聖之光充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率回復{2}點生命力。" }, "n,n" },
	{ "active any attack can chance divine each fills giving heal light melee one only paladin seal sec time", { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 생명력을 39만큼 회복시킵니다. 성기사마다 하나의 문장만 효력을 발휘합니다.", zhCN = "神圣之光充满圣骑士的体内，持续{1}秒，使其每次近战攻击都有一定几率回复39点生命值。圣骑士在同一时间内只能激活一种圣印。", zhTW = "神聖之光充滿聖騎士的體內，持續{1}秒，使其每次近戰攻擊都有一定機率回復39點生命力。聖騎士在同一時間內只能啟動一種聖印。" }, "n,n" },
	{ "attack chance divine each fills giving mana melee paladin paladin's restore sec wisdom", { ko = "{1}초 동안 성기사를 천상의 빛으로 감싸 매 근접 공격 시 일정 확률로 성기사의 마나를 {2}만큼 회복시킵니다.", zhCN = "神圣的智慧充满圣骑士的体内，持续{1}秒，令其每次使用近战武器击中敌人时都有一定几率恢复{2}点法力值。", zhTW = "神聖的智慧充滿聖騎士的體內，持續{1}秒，令其每次使用近戰武器擊中敵人時都有一定機率恢復{2}點法力。" }, "n,n" },
