	{ "absorb active additional also any attack attacks can causing damage dealt divine each equal equipped fills fury grants holy inflict melee one only paladin seal sec shield time while", { ko = "{1}초 동안 자신을 신성한 격노로 채워 근접 공격 시 {2}의 신성 피해를 추가로 입힙니다. 방패를 장착하고 있으면 공격할 때마다 입힌 신성 피해의 {3}%만큼 피해를 흡수하는 보호막도 얻습니다. 성기사마다 하나의 문장만 효력을 발휘합니다." }, "n,n,p" },
	{ "all cooldown finishes frost other remaining spells", { ko = "다른 모든 냉기 주문의 남은 재사용 대기시간이 초기화됩니다.", zhCN = "结束你所有其他冰霜法术的剩余冷却时间。", zhTW = "立即結束你其他所有冰霜法術的剩餘冷卻時間。" }, "" },
	{ "ability cooldown cost finishes judgement mana next reduces remaining", { ko = "심판의 남은 재사용 대기시간을 초기화하고, 다음 심판의 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "结束审判的剩余冷却时间，并使你下一次审判消耗的法力值降低{1}%。", zhTW = "立即結束你審判技能的剩餘冷卻時間，並使你下一個審判的法力消耗降低{1}%。" }, "p" },
	{ "causes damage finishing move over time", { ko = "마무리 일격을 시도하여 적에게 지속적인 피해를 입힙니다.", zhCN = "终结技，使目标在一段时间内受到持续伤害。", zhTW = "終結技，使目標在一段時間內受到持續的傷害。" }, "" },
	{ "attack causes damage finishing increased move over power time", { zhCN = "终结技，造成持续伤害，伤害受攻击强度加成。", zhTW = "終結技，使目標在一段時間內受到持續的傷害，以攻擊強度來提升。" }, "" },
	{ "attack causes combo damage finishing increased lasts longer move over per point power time", { ko = "마무리 일격을 시도하여 적에게 지속 피해를 입힙니다. 입히는 피해는 전투력에 비례합니다. 연계 점수에 따라 지속시간이 증가합니다.", zhCN = "终结技，造成持续伤害，伤害受攻击强度加成。每个连击点数可延长持续时间：", zhTW = "終結技，使目標在一段時間內受到持續的傷害，以攻擊強度來提升。根據連擊點數決定持續時間：" }, "" },
	{ "attack causes combo damage finishing increases move over per point power time", { ko = "마무리 일격을 시도하여 적에게 지속적인 피해를 입힙니다. 연계 점수와 전투력에 따라 피해가 증가합니다:", zhCN = "终结技，使目标在一段时间内受到持续伤害。伤害将根据连击点数和攻击强度决定：", zhTW = "終結技，使目標在一段時間內受到持續的傷害。根據連擊點數和你的攻擊強度決定傷害量：" }, "" },
	{ "additional causes combo converts damage each energy extra finishing move per point", { ko = "적에게 마무리 일격을 날리고 남은 기력을 전환하여 {1}의 추가 피해를 입힙니다.", zhTW = "終結技，根據連擊點數決定所造成的傷害，並將每一點額外的能量點數轉化為{1}點額外傷害。" }, "n" },
	{ "additional attack causes combo converts damage each energy extra finishing increased move per point power", { ko = "적에게 마무리 일격을 날리고 남은 기력을 전환하여 {1}의 추가 피해를 입힙니다. 입히는 피해는 전투력에 따라 증가합니다.", zhCN = "终结技，根据连击点数决定所造成的伤害，并将每一点额外的能量点数转化为{1}点额外伤害，该伤害会受到攻击强度的加成影响：", zhTW = "終結技，根據連擊點數決定所造成的傷害，並將每一點額外的能量點數轉化為{1}點額外傷害。以你的攻擊強度來提升傷害：" }, "n" },
	{ "attack causes combo damage finishing increased move per point power", { ko = "적에게 마무리 일격을 날립니다. 연계 점수와 전투력에 따라 피해가 증가합니다.", zhCN = "终结技，根据连击点数造成伤害，伤害受攻击强度加成：", zhTW = "終結技，根據連擊點數決定造成的傷害，並根據攻擊強度提高傷害：" }, "" },
	{ "armor combo exposes finishing move per point reducing sec target", { ko = "마무리 일격으로 {1}초 동안 대상의 빈틈을 드러내, 연계 점수에 따라 방어도를 감소시킵니다." }, "n" },
	{ "attack finishing increases melee move speed", { ko = "마무리 일격을 시도하여 근접 공격 속도를 {1}%만큼 증가시킵니다.", zhCN = "终结技，使近战攻击速度提高{1}%。", zhTW = "終結技，使你的近戰攻擊速度提高{1}%。" }, "p" },
	{ "attack combo finishing increases lasts longer melee move per point speed", { ko = "마무리 일격을 시도하여 근접 공격 속도를 {1}%만큼 증가시킵니다. 연계 점수에 따라 지속시간이 증가합니다.", zhCN = "终结技，使近战攻击速度提高{1}%。根据连击点数的数量决定效果持续时间：", zhTW = "終結技，使你的近戰攻擊速度提高{1}%。根據連擊點數的數量決定效果持續時間：" }, "p" },
	{ "apply chance damage finishing increases move poisons", { ko = "마무리 일격을 날려 독이 입히는 피해를 {1}%만큼, 독을 부여할 확률을 {2}%만큼 증가시킵니다.", zhCN = "终结技，使你的毒药伤害提高{1}%，施加毒药的几率提高{2}%。", zhTW = "終結技，使你的毒藥傷害提高{1}%，施加毒藥的機率提高{2}%。" }, "p,p" },
