	{ "finishing move stuns target", { ko = "적에게 마무리 일격을 날려 기절시킵니다.", zhCN = "终结技，使目标昏迷。", zhTW = "終結技，使目標昏迷。" }, "" },
	{ "combo finishing lasts longer move per point stuns target", { ko = "적에게 마무리 일격을 날려 기절시킵니다. 연계 포인트 당 다음 시간만큼 지속됩니다.", zhCN = "终结技，使目标昏迷。根据连击点数的数量决定效果持续时间：", zhTW = "終結技，使目標昏迷。根據連擊點數的數量決定效果持續時間：" }, "" },
	{ "damage fire increased taken", { ko = "받는 화염 피해 {1}%만큼 증가", zhCN = "受到的火焰伤害提高{1}%。", zhTW = "受到的火焰傷害提高{1}%。" }, "p" },
	{ "fires hitting missiles several targets", { ko = "여러 발의 탄환을 동시에 쏴서 {1}명의 대상을 적중시킵니다.", zhCN = "连续射出弹药，击中{1}个目标。", zhTW = "射出數發彈矢，命中{1}個目標。" }, "n" },
	{ "aimed cooldown fires hitting missiles multi several shares shot targets", { ko = "여러 발의 탄환을 동시에 쏴서 {1}명의 대상을 적중시킵니다. 일제 사격은 조준 사격과 재사용 대기시간을 공유합니다.", zhCN = "连续射出弹药，击中{1}个目标。多重射击与瞄准射击共享冷却时间。", zhTW = "射出數發彈矢，命中{1}個目標。多重射擊與瞄準射擊共用冷卻時間。" }, "n" },
	{ "damage drained each mana shadow takes target way", { ko = "대상은 소진된 마나의 절반만큼 암흑 피해를 입습니다." }, "n" },
	{ "casting continue duration mana regeneration while will", { ko = "이 동안은 주문 시전 중 마나가 평소의 {1}%의 속도로 회복됩니다.", zhCN = "在此期间，你在施法时仍可保持{1}%的正常法力回复速度。", zhTW = "在此期間，你在施法時仍可保持{1}%的正常法力回覆速度。" }, "p" },
	{ "cast costing damage deal mana more next sec spells while", { ko = "다음 {1}초 동안 주문 시전 시 {2}%의 마나를 추가로 소모하여 {3}%의 추가 피해를 입힙니다.", zhCN = "在接下来的{1}秒内，你的法术造成的伤害提高{2}%，但消耗的法力值也提高{3}%。", zhTW = "在接下來的{1}秒內，你的法術會造成{2}%的額外傷害，但同時也要消耗{3}%的額外法力才能施放。" }, "n,p,p" },
	{ "all attacks enemies focus forces nearby sec", { ko = "{1}초 동안 주위의 모든 적이 자신에게 공격을 집중하도록 만듭니다.", zhCN = "嘲讽附近所有的敌人，持续{1}秒。", zhTW = "嘲諷附近所有的敵人，持續{1}秒。" }, "n" },
	{ "all attacks enemies focus forces nearby sec within yards", { ko = "{2}초 동안 주위 {1}미터 반경 내에 있는 모든 적이 자신에게 공격을 집중하도록 만듭니다.", zhCN = "嘲讽附近半径{1}码范围内的所有敌人，强制它们攻击你，持续{2}秒。", zhTW = "迫使周圍{1}碼範圍內的敵人集中攻擊你，持續{2}秒。" }, "n,n" },
	{ "enemy forces sec sleep target up", { ko = "적을 최대 {1}초 동안 잠들게 합니다." }, "n" },
	{ "any awaken beasts can damage dragonkin enemy forced forces hibernate one only sec sleep target time up will works", { ko = "적을 최대 {1}초 동안 잠들게 합니다. 대상이 피해를 입으면 깨어납니다. 동시에 한 대상만 잠들게 할 수 있습니다. 야수와 용족에게만 사용할 수 있습니다.", zhCN = "使敌方目标沉睡，最多持续{1}秒，任何伤害都会唤醒被催眠的目标。在同一时间内只能强制使一个目标进入休眠状态，只对野兽和龙类有效。", zhTW = "使敵方目標沉睡，最多持續{1}秒，任何傷害都會喚醒被催眠的目標。在同一時間內只能強制使一個目標進入休眠狀態，只對野獸和龍類有效。" }, "n" },
	{ "all casting demonic forces increasing speak spells target time", { ko = "대상을 강제로 악마어로 말하도록 하여 모든 주문의 시전 시간을 {1}%만큼 증가시킵니다.", zhCN = "强迫目标使用恶魔语，使其所有法术的施放时间延长{1}%。", zhTW = "強迫目標使用惡魔語，使其所有法術的施法時間延長{1}%。" }, "p" },
	{ "active all any can casting curse demonic forces increasing lasts one only per sec speak spells target time warlock", { ko = "대상을 강제로 악마어로 말하도록 하여 모든 주문의 시전 시간을 {1}%만큼 증가시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다. {2}초 동안 지속됩니다.", zhCN = "强迫目标使用恶魔语，使其所有法术的施放时间延长{1}%。每个术士在任一目标身上只能维持一种诅咒。持续{2}秒。", zhTW = "強迫目標使用惡魔語，使其所有法術的施法時間延長{1}%。每個術士只能對同一個目標施加一種詛咒。持續{2}秒。" }, "p,n" },
	{ "blood doses gain venomous", { ko = "맹독성 피 {1}중첩이 부여됩니다.", zhCN = "获得{1}层毒血效果。", zhTW = "獲得{1}層毒血效果。" }, "n" },
	{ "bleed blood damage dose doses enemy gain lasts nearby one sec spread suffer up venomous whenever within yds", { ko = "맹독성 피 {1}중첩이 부여됩니다. 출혈 피해를 받을 때마다 {2}미터 내의 주위 적에게 맹독성 피를 1회 살포합니다. 최대 {3}초 동안 지속됩니다.", zhCN = "获得{1}层毒血效果。每当你受到流血伤害时，就会有一层毒血传播给{2}码内的一名附近敌人。最多持续{3}秒。", zhTW = "獲得{1}層毒血效果。每當你受到流血傷害時，會將一層效果濺射至附近{2}碼範圍內的一個敵人。最多持續{3}秒。" }, "n,n,n" },
	{ "attack causing damage enemy garrote increased over power sec", { zhCN = "猛勒敌人的脖子，在{2}秒内对其造成总计{1}点伤害，该伤害会受到攻击强度的加成影响。" }, "n,n" },
	{ "attack awards behind causing combo damage enemy garrote increased must over point power sec stealthed target", { ko = "적의 목을 졸라 {2}초에 걸쳐 총 {1}의 피해를 입힙니다. 총 피해는 전투력에 따라 증가합니다. 적의 배후에서 은신 상태로 사용해야 합니다. {3}의 연계 포인트가 주어집니다.", zhCN = "猛勒敌人的脖子，在{2}秒内对其造成总计{1}点伤害，该伤害会受到攻击强度的加成影响。必须在潜行状态下从目标背后发动。奖励{3}个连击点数。", zhTW = "猛勒敵人的脖子，在{2}秒內對其造成總計{1}點傷害，以你的攻擊強度來提升，必須在潛行狀態下從目標背後發動。獎勵{3}個連擊點數。" }, "n,n,n" },
	{ "about beast gather information target", { ko = "대상 야수의 정보를 수집합니다.", zhCN = "收集目标野兽的相关资料。", zhTW = "收集目標野獸的相關資料。" }, "" },
	{ "about any armor beast damage diet display gather health information resistances special target tooltip will", { ko = "대상 야수의 정보를 수집합니다. 대상에 마우스 커서를 올려 놓으면 공격력과 생명력, 방어도, 저항력, 먹이의 종류가 표시됩니다.", zhCN = "收集目标野兽的相关资料。信息栏里会显示出该野兽的伤害、生命值、护甲值和魔法抗性，以及它通常吃的食物。", zhTW = "收集目標野獸的相關資料。資訊欄裡會顯示出該野獸的傷害、生命力、護甲值和魔法抗性，以及它通常吃的食物。" }, "" },
	{ "additional cost generates health over rage sec then", { ko = "생명력을 대가로 {1}의 분노를 생성한 후 {2}초에 걸쳐 {3}의 추가 분노를 생성합니다." }, "n,n,n" },
	{ "combat every generates loss out rage reduces sec while", { ko = "전투 중 {2}초마다 {1}의 분노를 생성합니다. 또한 전투 중이 아닐 때 분노 손실이 {3}%만큼 감소합니다.", zhCN = "在战斗中每{2}秒获得{1}点怒气，并使脱战怒气衰减降低{3}%。", zhTW = "在戰鬥中，每{2}秒產生{1}點怒氣，脫離戰鬥後，失去的怒氣降低{3}%。" }, "n,n,p" },
	{ "amount generates high threat", { ko = "대상에 대한 위협 수준이 크게 증가합니다.", zhCN = "产生很高的威胁值。", zhTW = "產生很高的威脅值。" }, "" },
	{ "additional armor gives members party within yards", { ko = "주위 {2}미터 반경에 있는 파티원의 방어도가 {1}만큼 상승합니다.", zhCN = "使半径{2}码范围内的所有小队成员获得{1}点额外的护甲。", zhTW = "使半徑{2}碼範圍內的所有小隊成員獲得{1}點額外的護甲。" }, "n,n" },
	{ "additional any armor aura gives have may members one only paladin party per players them time within yards", { ko = "주위 {2}미터 반경에 있는 파티원의 방어도가 {1}만큼 상승합니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使半径{2}码范围内的所有小队成员获得{1}点额外的护甲。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。", zhTW = "使半徑{2}碼範圍內的所有小隊成員獲得{1}點額外的護甲。每個聖騎士在同一時間內只能開啟一種光環，且同類光環的效果無法疊加。" }, "n,n" },
	{ "additional all fire gives members party raid resistance within yards", { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 화염 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的火焰抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的火焰抗性提高額外{2}點。" }, "n,n" },
