	{ "additional all frost gives members party raid resistance within yards", { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的冰霜抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的冰霜抗性提高額外{2}點。" }, "n,n" },
	{ "additional all any aura frost gives have may members one only paladin party per players raid resistance them time within yards", { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 냉기 저항력을 {2}만큼 증가시킵니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使{1}码内所有队伍和团队成员的冰霜抗性提高{2}点。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的冰霜抗性提高額外{2}點。每個聖騎士在同一時間內只能開啟一種光環。" }, "n,n" },
	{ "additional all gives members party raid resistance shadow within yards", { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 암흑 저항력을 {2}만큼 증가시킵니다.", zhCN = "使{1}码内所有队伍和团队成员的暗影抗性提高{2}点。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的暗影抗性提高額外{2}點。" }, "n,n" },
	{ "additional all any aura gives have may members one only paladin party per players raid resistance shadow them time within yards", { ko = "주위 {1} 미터 반경에 있는 파티원과 공격대원의 암흑 저항력을 {2}만큼 증가시킵니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다.", zhCN = "使{1}码内所有队伍和团队成员的暗影抗性提高{2}点。每个玩家同一时间只能受到每名圣骑士的一种光环影响。", zhTW = "使半徑{1}碼範圍內所有隊伍和團隊成員的暗影抗性提高額外{2}點。每個聖騎士在同一時間內只能開啟一種光環。" }, "n,n" },
	{ "caster caster's channels every gives health long pet sec second", { ko = "시전자가 정신을 집중하는 동안 {2}초 동안 1초마다 {1}의 생명력을 시전자의 소환수에게 이전합니다.", zhCN = "只要施法者持续引导，就会每秒为施法者的宠物恢复{1}点生命值，持续{2}秒。", zhTW = "只要施法者保持著引導法術的狀態，就會每秒將{1}點生命力轉移給施法者的寵物，最多持續{2}秒。" }, "n,n" },
	{ "caster caster's channels every generates gives health long pet reduced sec second threat", { ko = "시전자가 정신을 집중하는 동안 {2}초 동안 1초마다 {1}의 생명력을 시전자의 소환수에게 이전합니다. 위협 수준 생성량이 감소합니다.", zhCN = "只要施法者持续引导，就会每秒为施法者的宠物恢复{1}点生命值，持续{2}秒。产生的威胁较低。", zhTW = "只要施法者保持著引導法術的狀態，就會每秒將{1}點生命力轉移給施法者的寵物，最多持續{2}秒。產生的威脅值降低。" }, "n,n" },
	{ "all chance damaged gives ignoring interruption members party spell when within yards", { ko = "{2}미터 반경 내의 파티원이 주문을 시전할 때 {1}%의 확률로 피해로 인한 방해를 받지 않도록 합니다.", zhCN = "使半径{2}码范围内的所有队友在施法时都有{1}%的几率不会因为受到伤害而被打断。", zhTW = "使半徑{2}碼範圍內的所有隊友在施法時都有{1}%的機率不會因為受到傷害而被打斷。" }, "p,n" },
	{ "all any aura chance damaged gives have ignoring interruption may members one only paladin party per players spell them time when within yards", { ko = "{2}미터 반경 내의 파티원이 주문을 시전할 때 {1}%의 확률로 피해로 인한 방해를 받지 않도록 합니다. 성기사마다 하나의 대상에게 하나의 오라만 효력을 발휘합니다.", zhCN = "使半径{2}码范围内的所有队友在施法时都有{1}%的几率不会因为受到伤害而被打断。每个圣骑士在同一时间内只能开启一种光环，且同类光环的效果无法叠加。", zhTW = "使半徑{2}碼範圍內的所有隊友在施法時都有{1}%的機率不會因為受到傷害而被打斷。每個聖騎士在同一時間內只能開啟一種光環，且同類光環的效果無法疊加。" }, "p,n" },
	{ "ability activate all chance effects gives impairing movement remove sprint when", { ko = "전력 질주 사용 시 {1}%의 확률로 모든 이동 방해 효과에서 벗어납니다.", zhCN = "使你在启动疾跑技能时有{1}%的几率移除所有移动限制效果。", zhTW = "有{1}%的機率使你在啟動疾跑後移除所有限制移動的效果。" }, "p" },
	{ "attacks chance enemy gives melee parry", { ko = "일정 확률로 적의 근접 공격을 무기로 막아냅니다.", zhCN = "有一定几率招架敌人的近战攻击。", zhTW = "有一定機率招架敵人的近戰攻擊。" }, "" },
	{ "active all attacks chance enemy generated gives increases melee not parry reduces rockbiter threat weapon while", { ko = "일정 확률로 적의 근접 공격을 무기로 막아냅니다. 대지의 무기가 활성화되지 않은 동안에는 공격으로 생성되는 모든 위협 수준이 {1}%만큼 감소하고, 활성화된 동안에는 모든 위협 수준 생성량이 {2}%만큼 증가합니다.", zhCN = "有几率招架敌人的近战攻击。未激活石化武器时，你的攻击产生的威胁值降低{1}%；激活石化武器时，产生的所有威胁值提高{2}%。", zhTW = "有一定機率招架敵人的近戰攻擊，在石化武器未生效時，你的攻擊產生的所有威脅值降低{1}%，而在石化武器生效期間，產生的所有威脅值提高{2}%。" }, "p,p" },
	{ "all blessing class gives greater group hr increasing kings members raid same share stats target total", { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高{1}%，持续{2}小时。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效王者祝福的效果，使其所有屬性提高{1}%，持續{2}小時。" }, "p,n" },
	{ "all any blessing class gives greater group have hr increasing kings may members one only paladin per players raid same share stats target them time total", { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效王者祝福的效果，使其所有属性提高{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效王者祝福的效果，使其所有屬性提高{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "p,n" },
	{ "all any blessing class effect effects flash gives greater group have holy hr increasing lasts light may members one only paladin per players raid same share spells target them time up used", { ko = "공격대나 파티 중 대상과 같은 직업을 가진 대원에게 빛의 축복을 걸어 {3}시간 동안 성스러운 빛의 효과를 최대 {1}만큼, 빛의 섬광의 효과를 최대 115만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "使团队或小队中所有与目标职业相同的玩家都获得强效光明祝福的效果，使圣光术为其恢复的生命值提高{1}点，圣光闪现为其恢复的生命值提高115点，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "使團隊或小隊中所有與目標職業相同的玩家都獲得強效光明祝福的效果，使聖光術為其恢復的生命力提高{1}點，聖光閃現為其恢復的生命力提高115點，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "n,n,n" },
