	{ "add after attacks chance combo dodging fully gives one point resisting spells target their", { ko = "대상의 공격을 회피하거나 대상의 주문을 완전히 저항했을 때 {1}%의 확률로 그 대상에 대한 연계 포인트 1점이 추가됩니다.", zhCN = "使你在躲闪攻击或完全抵抗法术后有{1}%的几率为目标增加一个连击点数。", zhTW = "使你在躲閃攻擊或完全抵抗法術後有{1}%的機率為目標增加一個連擊點數。" }, "p" },
	{ "ability add additional ambush chance cheap combo garrote gives point shot target using when", { ko = "매복, 목조르기, 비열한 습격 사용 시 {1}%의 확률로 대상에 대한 연계 포인트 1점이 추가됩니다.", zhCN = "使你有{1}%的几率在使用伏击、绞喉或偷袭技能后获得1个额外的连击点数。", zhTW = "使你有{1}%的機率在使用伏擊、絞喉或偷襲技能後獲得1個額外的連擊點數。" }, "p" },
	{ "any avoid casting caused chance damage gives healing interruption spell while", { ko = "모든 치유 계열 주문 시전 시 {1}%의 확률로 피해로 인한 주문 시전 방해를 받지 않습니다.", zhCN = "使你在施放任意治疗法术的时候有{1}%的几率避免因受到伤害而被打断。", zhTW = "使你在施放治療法術的時候有{1}%的機率不會因為受到傷害而中斷施法。" }, "p" },
