	{ "avoid casting caused chance channeling damage drain gives interruption life mana soul spells while wrack", { ko = "생명력 흡수, 마나 흡수, 영혼 흡수, 파멸에 정신을 집중하거나 시전 시 {1}%의 확률로 마법 시전 방해를 받지 않습니다.", zhCN = "使你在引导或施放吸取生命、吸取法力、吸取灵魂或折磨时有{1}%的几率避免因受到伤害而被打断。", zhTW = "使你有{1}%的機率在引導或施放吸取生命、吸取法力、吸取靈魂或毀壞法術時不會因為受到傷害而中斷施法。" }, "p" },
	{ "after any attack being chance damage damaging deal gives increased physical sec victim", { ko = "공격으로 피해를 받으면 {1}%의 확률로 {3}초 동안 물리 공격력이 {2}%만큼 증가합니다.", zhCN = "使你在遭受任何伤害性攻击后，有{1}%的几率使你造成的物理伤害提高{2}%，持续{3}秒。", zhTW = "在受到任何傷害性攻擊之後，你有{1}%的機率使造成的物理傷害提高{2}%，持續{3}秒。" }, "p,p,n" },
	{ "after any casting chance clearcasting damage enter fire frost gives nature spell state", { ko = "화염, 냉기, 자연 계열 공격 주문을 시전한 이후 {1}%의 확률로 정신 집중 상태를 취하게 됩니다.", zhCN = "使你有{1}%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。", zhTW = "使你有{1}%的機率在施放任何火焰、冰霜或自然系的傷害性法術之後進入節能施法狀態。" }, "p" },
	{ "after any casting chance clearcasting cost damage enter fire frost gives mana nature next reduces spell state", { ko = "화염, 냉기, 자연 계열 공격 주문을 시전한 이후 {1}%의 확률로 정신 집중 상태를 취하게 됩니다. 정신 집중 상태에서는 다음 공격 주문의 마나 소비량이 {2}%만큼 감소됩니다.", zhCN = "使你有{1}%的几率在施放任何火焰、冰霜或自然系的伤害性法术之后进入节能施法状态。这个状态可以使你的下一个伤害性法术所消耗的法力值减少{2}%。", zhTW = "使你有{1}%的機率在施放任何火焰、冰霜或自然系的傷害性法術之後進入節能施法狀態。這個狀態可以使你的下一個傷害性法術所消耗的法力降低{2}%。" }, "p,p" },
	{ "bear chance dire form gain gives rage shapeshift when", { ko = "곰 변신 또는 광포한 곰 변신 시 {1}%의 확률로 {2}의 분노를 생성합니다.", zhCN = "使你有{1}%的几率在变身为熊形态或巨熊形态时获得{2}点怒气。", zhTW = "使你有{1}%的機率在變身為熊形態或巨熊形態時獲得{2}點怒氣。" }, "p,n" },
	{ "bear cat chance dire each energy form gain gives had last maximum not plus rage regain second shapeshift shift spent up were when will", { ko = "곰 변신 또는 광포한 곰 변신 시 {1}%의 확률로 {2}의 분노를 생성합니다. 또한 표범 변신 시 지난 표범 변신 상태일 때 보유했던 기력의 {3}%를 다시 회복하며, 추가로 곰 변신이나 표범 변신, 광포한 곰 변신 상태가 아니었던 시간 1초당 기력을 {4}만큼, 최대 {5}만큼 생성합니다.", zhCN = "使你有{1}%的几率在变身为熊形态或巨熊形态时获得{2}点怒气。当你变身为猎豹形态时，将恢复上次处于猎豹形态时所拥有能量的{3}%，外加你在未处于熊形态、猎豹形态或巨熊形态的每秒{4}点能量，最多{5}点能量。", zhTW = "在你進入熊形態和巨熊形態時有{1}%的機率獲得{2}點怒氣，在進入獵豹形態時，重新獲得上次處於獵豹形態時擁有的{3}%%能量，而且根據在非熊形態、獵豹形態或巨熊形態下的持續秒數，每秒追加{4}點能量，最多獲得{5}點能量。" }, "p,n,p,n,n" },
	{ "additional any bear chance critical dire form gain get gives rage strike time while", { ko = "곰 변신 또는 광포한 곰 변신 상태에서 치명타 공격이 적중할 때마다 {1}%의 확률로 {2}의 추가 분노를 생성합니다.", zhCN = "使你在熊形态或巨熊形态下造成爆击时，有{1}%的几率额外获得{2}点怒气。", zhTW = "使你在熊形態或巨熊形態下對目標造成致命一擊後，有{1}%的機率額外獲得{2}點怒氣。" }, "p,n" },
	{ "abilities add addition additional any bear cat chance combo critical dire form gain generate get gives have non periodic point points rage strike strikes time while", { ko = "곰 변신 또는 광포한 곰 변신 상태에서 치명타 공격이 적중할 때마다 {1}%의 확률로 {2}의 추가 분노를 생성합니다. 또한 연계 점수를 생성하는 표범 변신 능력이 비주기적인 치명타 및 극대화 효과를 발휘하면 {3}%의 확률로 추가 연계 점수를 생성합니다.", zhCN = "使你在熊形态或巨熊形态下造成爆击时，有{1}%的几率额外获得{2}点怒气。此外，你的猎豹形态下可产生连击点数的技能的非周期性爆击有{3}%的几率额外增加一个连击点数。", zhTW = "使你在熊形態或巨熊形態下對目標造成致命一擊後，有{1}%的機率額外獲得{2}點怒氣。此外，而在獵豹形態時可產生連擊點數的非週期性效果造成致命一擊後，有{3}%的機率再獲取一個額外的連擊點數。" }, "p,n,p" },
	{ "after attack being blocking chance critical extra gain gives melee non periodic strike victim", { ko = "근접 공격을 방패로 막은 후 {1}%의 확률로 추가 공격 기회를 얻고, 비주기적인 치명타 및 극대화 공격을 받았을 때 {2}%%의 확률로 추가 공격 기회를 얻습니다.", zhCN = "使你在格挡一次近战攻击后有{1}%的几率获得一次额外攻击，受到非周期性爆击之后有{2}%%的几率获得一次额外攻击。", zhTW = "使你在格擋一次近戰攻擊後有{1}%的機率獲得一次額外的攻擊機會，並在遭受非週期性致命一擊後有{2}%%的機率獲得一次額外的攻擊機會。" }, "p,p" },
	{ "after being casting chance critical focused gain gives melee ranged sec strike victim", { ko = "근접 및 원거리 치명타 공격을 받았을 때 {1}%의 확률로 {2}초 동안 집중력을 획득합니다.", zhCN = "使你有{1}%的几率在受到敌人的近战或远程爆击后得到专注施法，持续{2}秒。", zhTW = "使你有{1}%機率在受到敵人近戰或遠程致命一擊後獲得專注施法，持續{2}秒。" }, "p,n" },
	{ "after being casting chance critical damage effect effects focused gain gives increases interrupt losing melee prevents ranged resistance sec strike taking time victim when", { ko = "근접 및 원거리 치명타 공격을 받았을 때 {1}%의 확률로 {2}초 동안 집중력을 획득합니다. 집중력의 효과를 받을 땐 받는 피해로 인해 시전 시간이 지연되지 않으며 방해 효과에 대한 저항이 {3}%만큼 증가합니다.", zhCN = "使你有{1}%的几率在受到敌人的近战或远程爆击后得到专注施法，持续{2}秒。专注施法效果可以让你在施法时不会因为受到伤害而延长施法时间，且令你抵抗打断效果的几率提高{3}%。", zhTW = "使你有{1}%機率在受到敵人近戰或遠程致命一擊後獲得專注施法，持續{2}秒。專注施法效果可防止因受到傷害而損失施法時間，並使你對中斷效果的抗性提高{3}%。" }, "p,n,p" },
	{ "additional chance damage deal generate gives melee rage weapon when", { ko = "근접 무기로 적에게 피해를 입힐 시 {1}%의 확률로 {2}의 추가 분노를 생성합니다." }, "p,n" },
	{ "afflicted after chance dies embrace enemy gives increase killing non sec spirit target trivial vampiric when", { ko = "경험치 또는 명예 점수를 주는 적을 처치하거나 흡혈의 선물에 걸린 적이 죽으면 {1}%의 확률로 {3}초 동안 정신력이 {2}%만큼 증가합니다.", zhCN = "在消灭一个能为你提供经验值或荣誉值的敌人后，有{1}%的几率使你的精神提高{2}%，持续{3}秒。", zhTW = "在消滅一個能為你提供經驗值或榮譽值的敵人後，有{1}%的機率使你的精神提高{2}%，持續{3}秒。" }, "p,p,n" },
	{ "afflicted after casting chance continue dies duration embrace enemy gives increase killing mana non regeneration sec spirit target trivial vampiric when while will", { ko = "경험치 또는 명예 점수를 주는 적을 처치하거나 흡혈의 선물에 걸린 적이 죽으면 {1}%의 확률로 {3}초 동안 정신력이 {2}%만큼 증가합니다. 이 동안은 주문 시전 중 마나가 평소의 {4}%의 속도로 회복됩니다.", zhCN = "在消灭一个能为你提供经验值或荣誉值的敌人后，有{1}%的几率使你的精神提高{2}%，持续{3}秒。在此期间，你在施法时仍可保持{4}%的正常法力回复速度。", zhTW = "在消滅一個能為你提供經驗值或榮譽值的敵人後，有{1}%的機率使你的精神提高{2}%，持續{3}秒。在此期間，你在施法時仍可保持{4}%的正常法力回覆速度。" }, "p,p,n,p" },
	{ "any casting caused chance channeling damage destruction gives interruption resist spell while", { ko = "모든 파괴 계열 주문 시전 시 {1}%의 확률로 마법 시전 방해를 받지 않습니다.", zhCN = "使你有{1}%的几率在施放或引导任何毁灭系法术时不会因受到伤害而被打断。", zhTW = "使你有{1}%的機率在施放或引導毀滅系法術時不會因受到傷害而被打斷。" }, "p" },
	{ "arcane blast bolt chance channeled cost duration every fire fireball frostbolt frostfire gives mana missiles next reduce sec spell spells", { ko = "비전 작렬 시전 시 {1}%의 확률로, 화염구와 얼음 화살, 얼음불꽃 화살 시전 시 {2}%의 확률로 다음 신비한 화살 주문의 정신 집중 지속시간이 {3}%만큼, 마나 소모량이 {4}%만큼 감소하며, {5}초마다 화살을 발사합니다.", zhCN = "你的奥术冲击有{1}%的几率，火球术、寒冰箭和霜火之箭有{2}%的几率，使下一个奥术飞弹的引导时间缩短{3}%、法力消耗减少{4}%，且每{5}秒发射一次飞弹。", zhTW = "使你的秘法衝擊有{1}%的機率、而你的火球術、寒冰箭和霜火箭則有{2}%的機率使你下一個秘法飛彈法術的引導時間縮短{3}%，法力消耗降低{4}%，且每{5}秒發射一發飛彈。" }, "p,p,p,p,n" },
	{ "chance chill effects freeze gives sec target", { ko = "{1}%의 확률로 빙결 효과에 걸린 적을 {2}초 동안 움직이지 못하도록 만듭니다.", zhCN = "你的冰冷效果有{1}%的几率将目标冰冻{2}秒。", zhTW = "使你的冰冷效果有{1}%的機率讓目標凍結{2}秒。" }, "p,n" },
	{ "cast chance chill effect effects fingers frost frozen gives grant if next spell target treats were which", { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。", zhTW = "你的冰冷效果有{1}%的機率使你獲得冰霜之指效果，使你的下{2}次法術將目標視為已被凍結。" }, "p,n" },
	{ "cast chance chill effect effects fingers frost frozen gives grant if lasts next sec spell target treats were which", { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다. {3}초 동안 지속됩니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。持续{3}秒。", zhTW = "你的冰冷效果有{1}%的機率使你獲得冰霜之指效果，使你的下{2}次法術將目標視為已被凍結。持續{3}秒。" }, "p,n,n" },
	{ "cast chance chill effect effects fingers frost frozen gives grant if next spells target treats were which", { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。" }, "p,n" },
	{ "cast chance chill effect effects fingers frost frozen gives grant if lasts next sec spells target treats were which", { ko = "빙결 효과를 일으키면 {1}%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 {2}회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다. {3}초 동안 지속됩니다.", zhCN = "你的冰冷效果有{1}%的几率使你获得寒冰指效果，使你的下{2}次法术将目标视为已被冻结。持续{3}秒。", zhTW = "你的冰冷效果有{1}%的機率賦予你冰霜之指的效果，使你接下來施放的{2}發法術視同目標處於冰凍狀態，持續{3}秒。" }, "p,n,n" },
	{ "chance concussive gives sec shot stun target", { ko = "충격포 사용 시 {1}%의 확률로 적을 {2}초 동안 기절시킵니다.", zhCN = "使你的震荡射击有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的震盪射擊有{1}%的機率令目標昏迷{2}秒。" }, "p,n" },
	{ "after cause chance corruption damaging drain enter gives life opponent shadow soul spells trance wrack", { ko = "부패, 영혼 흡수, 생명력 흡수, 파멸로 적에게 피해를 입히면 {1}%의 확률로 어둠의 무아지경에 빠져듭니다.", zhCN = "使你的腐蚀术、吸取灵魂、吸取生命和折磨在对敌人造成伤害后有{1}%的几率令你进入暗影冥思。", zhTW = "使你的腐蝕術、吸取靈魂、吸取生命和毀壞法術有{1}%的機率在對敵人造成傷害之後令你進入暗影冥思。" }, "p" },
	{ "after bolt casting cause chance corruption damaging drain enter gives life next opponent reduces shadow soul spell spells time trance wrack", { ko = "부패, 영혼 흡수, 생명력 흡수, 파멸로 적에게 피해를 입히면 {1}%의 확률로 어둠의 무아지경에 빠져듭니다. 이 상태에서 다음 어둠의 화살의 시전 시간이 {2}%만큼 단축됩니다.", zhCN = "使你的腐蚀术、吸取灵魂、吸取生命和折磨在对敌人造成伤害后有{1}%的几率令你进入暗影冥思。暗影冥思使你的下一个暗影箭的施法时间缩短{2}%。", zhTW = "使你的腐蝕術、吸取靈魂、吸取生命和毀壞法術有{1}%的機率在對敵人造成傷害之後令你進入暗影冥思。暗影冥思令你下一個暗影箭法術的施法時間縮短{2}%。" }, "p,p" },
	{ "attack attacks chance damaging gives increase melee power reduce sec target's", { ko = "근접 공격으로 피해를 입히면 일정 확률로 {3}초 동안 대상의 전투력을 {1}만큼 감소시키고 자신의 전투력은 {2}%만큼 증가시킵니다.", zhCN = "使你的伤害性近战攻击有几率令目标的攻击强度降低{1}点，并使你的攻击强度提高{2}%，持续{3}秒。", zhTW = "使你的近戰攻擊有一定機率使目標的攻擊強度降低{1}點，並使你的攻擊強度提高{2}%，持續{3}秒。" }, "n,p,n" },
	{ "add chance combo finishing gives moves point target", { ko = "마무리 일격 사용 시 {1}%의 확률로 대상에게 연계 점수 1점을 추가합니다.", zhCN = "使你的终结技有{1}%的几率为目标增加一个连击点数。", zhTW = "使你的終結技有{1}%的機率為目標增加一個連擊點數。" }, "p" },
	{ "casting caused chance damage fire gives lose not reduces spells take threat time when", { ko = "화염 주문 사용 시 피해를 입어도 {1}%의 확률로 시전 시간이 지연되지 않으며 화염 주문으로 발생되는 위협 수준이 {2}%만큼 감소합니다.", zhCN = "使你的火焰系法术有{1}%的几率不会因为你受到伤害而被干扰，火焰系法术所造成的威胁值降低{2}%。", zhTW = "使你的火焰法術有{1}%的機率不會因為你受到傷害而損失施法時間，並使你的火焰法術所產生的威脅值降低{2}%。" }, "p,p" },
	{ "chance fire gives sec spells stun target", { ko = "화염 주문 적중 시 {1}%의 확률로 적을 {2}초 동안 기절시킵니다.", zhCN = "使你的火焰法术有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的火焰法術有{1}%的機率令目標昏迷{2}秒。" }, "p,n" },
	{ "casting chance damage flash gives holy light light's lose not spells take time vigil when", { ko = "빛의 섬광, 성스러운 빛, 빛의 경계 시전 시 피해를 받아도 {1}%의 확률로 시전 시간이 지연되지 않습니다.", zhCN = "使你的圣光闪现、圣光术和圣光守望有{1}%的几率在受到伤害时不损失施法时间。", zhTW = "使你的聖光閃現、聖光術和聖光戒備有{1}%的機率在受到傷害時不會損失施法時間。" }, "p" },
	{ "apply chance chill critically damage effect frost frostbolt gives hit ice increases lance sec spells target which will winter's", { zhCN = "你的冰霜伤害法术有{1}%的几率施加深冬之寒效果，使你的冰枪术和寒冰箭对该目标的爆击几率提高{2}%，持续{3}秒。", zhTW = "使你的冰霜傷害法術有{1}%的機率施加深冬之寒效果，使你的冰霜長矛和寒冰箭對目標造成致命一擊的機率提高{2}%，持續{3}秒。" }, "p,p,n" },
