	{ "ability chance gives hamstring immobilize sec target", { ko = "무력화 사용 시 {1}%의 확률로 대상을 {2}초 동안 이동 불가 상태로 만듭니다.", zhCN = "使你的断筋技能有{1}%的几率令目标无法移动，持续{2}秒。", zhTW = "使你的斷筋技能有{1}%的機率令目標無法移動，持續{2}秒。" }, "p,n" },
	{ "against consecration damage enemies enter first gives holy increased spells", { ko = "자신의 신성화 지역에 들어오는 첫 {2}명의 적에게 입히는 신성 주문의 피해가 {1}%만큼 증가합니다.", zhCN = "使你的神圣法术对最先进入你的奉献的{2}个敌人造成的伤害提高{1}%。", zhTW = "你神聖法術對前{2}個進入奉獻效果範圍的敵人造成的傷害提高{1}%。" }, "p,n" },
	{ "ability chance cost gives judged judgement mana return seal", { ko = "심판 사용 시, {1}%의 확률로 심판이 적용된 문장의 마나 소모량의 {2}%를 되돌려받습니다.", zhCN = "使你的审判有{1}%几率返还被审判圣印法力消耗的{2}%。", zhTW = "使你的審判技能有{1}%的機率返還審判聖印消耗的{2}%法力。" }, "p,p" },
	{ "ability chance gives kick sec silence target", { ko = "발차기에 적중한 적을 {1}%의 확률로 {2}초 동안 침묵하도록 만듭니다.", zhCN = "使你的脚踢技能有{1}%的几率令目标沉默{2}秒。", zhTW = "使你的腳踢技能有{1}%的機率令目標沉默{2}秒。" }, "p,n" },
