	{ "attacks benefit depending gives melee weapon", { zhCN = "根据你所使用的武器，为你的近战武器攻击提供一定的加成效果。", zhTW = "根據你所使用的武器，為你的近戰武器攻擊提供一定的加成效果。" }, "" },
	{ "armor attack attacks axe benefit chance critical depending extra gives have ignore increases mace melee polearm staff strike successful sword target target's trigger weapon", { ko = "무기 종류에 따라 근접 공격에 이로운 효과를 부여합니다. 도끼류/장창류: 치명타 및 극대화율이 {1}%만큼 증가합니다. 둔기류/지팡이류: 공격 시 대상의 방어도를 {2}%만큼 무시합니다. 도검류: 근접 공격 적중 시 {3}%의 확률로 대상에게 추가 공격을 가합니다." }, "p,p,p" },
	{ "armor attack attacks axe benefit chance critical dagger depending extra fist gives have ignore increases mace melee strike successful sword target target's trigger weapon", { ko = "무기 종류에 따라 근접 공격에 이로운 효과를 부여합니다. 도끼류/도검류: 근접 공격 적중 시 {1}%의 확률로 대상에게 추가 공격을 가합니다. 단검류/장착 무기류: 치명타 및 극대화율이 {2}%만큼 증가합니다. 둔기류: 공격 시 대상의 방어도를 {3}%만큼 무시합니다.", zhCN = "使你的近战武器攻击根据武器类型获得不同增益。 斧/剑：你的成功近战攻击有{1}%的几率对目标触发一次额外攻击。 匕首/拳套：使你的爆击几率提高{2}%。 锤：你的攻击无视 目标{3}%的护甲值。", zhTW = "使你的近戰武器攻擊根據武器類型獲得不同增益。 斧/劍：你的成功近戰攻擊有{1}%的機率對目標觸發一次額外攻擊。 匕首/拳套：使你的致命一擊機率提高{2}%。 錘：你的攻擊無視 目標{3}%的護甲值。" }, "p,p,p" },
	{ "chance cleansing cost curse disease each effect gives heals magic mana mend pet poison reduces spell time", { ko = "동물 치료 시, 치유 효과를 발휘할 때마다 {1}%의 확률로 야수에게서 {2}개의 저주나 질병, 마법, 독 효과를 제거합니다. 또한 마나 소모량이 {3}%만큼 감소합니다.", zhCN = "使你的治疗宠物每次治疗时有{1}%的几率净化宠物身上的{2}个诅咒、疾病、魔法或中毒效果，并使法力消耗降低{3}%。", zhTW = "使你的治療寵物技能每次造成治療效果時都有{1}%的機率移除寵物身上{2}個詛咒、疾病、魔法或中毒效果，並使法力消耗降低{3}%。" }, "p,n,p" },
	{ "after attack chance critical dealing gain gives increase pet sec speed strike", { ko = "야수의 공격이 치명타로 적중할 시 {1}%의 확률로 공격 속도가 {3}초 동안 {2}%만큼 증가합니다.", zhCN = "使你的宠物有{1}%的几率在对敌人造成爆击后获得攻击速度提高{2}%的效果，持续{3}秒。", zhTW = "使你的寵物有{1}%的機率在對敵人造成致命一擊後獲得攻擊速度提高{2}%的效果，持續{3}秒。" }, "p,p,n" },
	{ "chance damage gives sec shadow spells stun target", { ko = "암흑 공격 주문 사용 시 {1}%의 확률로 대상을 {2}초 동안 기절시킵니다.", zhCN = "使你的暗影系伤害性法术有{1}%的几率令目标昏迷{2}秒。", zhTW = "使你的暗影系傷害性法術有{1}%的機率令目標昏迷{2}秒。" }, "p,n" },
	{ "ability bash chance gives sec shield silence target", { ko = "방패 가격 시 {1}%의 확률로 {2}초 동안 적을 침묵시킵니다.", zhCN = "使你的盾击技能有{1}%的几率令目标沉默{2}秒。", zhTW = "使你的盾擊技能有{1}%的機率使目標沉默{2}秒。" }, "p,n" },
