	{ "demon gives invisibility lesser min summoned up", { ko = "최대 {1}분 동안 소환된 악마가 하급 투명 효과를 얻습니다.", zhCN = "使你召唤的恶魔获得次级隐形术的效果，最多持续{1}分钟。", zhTW = "使你召喚的惡魔獲得次級隱形術的效果，最多持續{1}分鐘。" }, "n" },
