	{ "ability chance clip gives immobilize sec target wing", { ko = "날개 절단 사용 시 {1}%의 확률로 대상을 {2}초 동안 움직이지 못하도록 만듭니다.", zhCN = "使你的摔绊技能有{1}%的几率令目标在{2}秒内无法移动。", zhTW = "使你的摔絆技能有{1}%的機率令目標在{2}秒內無法移動。" }, "p,n" },
	{ "air controlling direction downward glide sec through travel while", { ko = "{1}초 동안 활공하며 내려갑니다. 시전자가 방향을 조정할 수 있습니다.", zhCN = "在半空中滑翔下降，持续{1}秒，并可控制移动方向。", zhTW = "一邊控制移動方向，一邊在空中向下滑翔，持續{1}秒。" }, "n" },
	{ "causing damage disarming enemy's grabs sec talons them weapon", { ko = "발톱으로 적의 무기를 낚아채 {1}~{2}의 피해를 입히고 {3}초 동안 무장을 해제시킵니다.", zhCN = "用利爪夺取敌人的武器，造成{1}至{2}点伤害并将其缴械，持续{3}秒。", zhTW = "用利爪奪取敵人的武器，造成{1}至{2}點傷害並將其繳械，持續{3}秒。" }, "n,n,n" },
	{ "every grants health mana one resisted sec spells when", { ko = "적이 자신의 주문에 저항하면 {4}초 동안 {3}초마다 {1}의 생명력과 {2}의 마나를 회복합니다.", zhCN = "当你的法术被抵抗时，每{3}秒恢复{1}点生命值和{2}点法力值，持续{4}秒。", zhTW = "當你的其中一個法術被抵抗時，每{3}秒賦予{1}點生命力和{2}點法力，持續{4}秒。" }, "n,n,n,n" },
	{ "active both demon effect grants long summoned warlock", { ko = "소환수를 부리고 있을 때 소환수의 종류에 따라 흑마법사와 소환수에게 다음의 효과가 주어집니다.", zhCN = "只要召唤的恶魔保持激活，使术士和该恶魔获得一个效果。", zhTW = "只要術士召喚的惡魔存在，術士與該惡魔便會獲得特殊效果。" }, "" },
	{ "chance dodge equipped generate grants parry rage shield when while", { ko = "방패를 장착한 동안 회피하거나 무기 막기에 성공하면 {1}%의 확률로 {2}의 분노를 얻습니다.", zhCN = "使你有{1}%的几率在装备盾牌并躲闪或招架时产生{2}点怒气。", zhTW = "裝備盾牌的情況下，你閃躲或招架時有{1}%的機率產生{2}點怒氣。" }, "p,n" },
	{ "effects grants immunity interrupt sec silence", { ko = "{1}초 동안 침묵과 시전 방해 효과에 면역이 됩니다.", zhCN = "使你免疫沉默和中断效果。持续{1}秒。", zhTW = "使你免疫沉默和中斷效果。持續{1}秒。" }, "n" },
	{ "chance detect greatly increased traps", { ko = "함정을 찾을 확률이 대폭 증가합니다.", zhCN = "极大提高侦测陷阱的能力。", zhTW = "大幅度提高偵測陷阱的機會。" }, "" },
	{ "casts damage fire harmful sear spell target", { ko = "해로운 주문 시전 시 대상을 그을려 {1}의 화염 피해를 입힙니다.", zhCN = "施放有害法术会灼烧目标，造成{1}点火焰伤害。", zhTW = "施放有害法術時，灼燒目標，造成{1}點火焰傷害。" }, "n" },
	{ "friendly heal target yourself", { ko = "자신과 아군 대상 하나를 {1}~{2}만큼 치유합니다." }, "n,n" },
	{ "causes friendly heal low target threat yourself", { ko = "자신과 아군 대상 하나를 {1}~341만큼 치유합니다. 낮은 위협 수준을 생성합니다." }, "n,n" },
	{ "damage heals over sec", { ko = "{2}초에 걸쳐 생명력을 {1}만큼 회복시킵니다.", zhCN = "在{2}秒内恢复{1}点生命值。", zhTW = "在{2}秒內恢復{1}點生命力。" }, "n,n" },
	{ "caster friendly heals target", { ko = "아군 대상과 시전자를 {1}~{2}만큼 치유합니다.", zhCN = "为一个友方目标和施法者本身各恢复{1}至{2}点生命值。" }, "n,n" },
	{ "caster friendly heals low target threat", { ko = "아군 대상과 시전자를 {1}~271만큼 치유합니다. 낮은 위협 수준을 생성합니다.", zhCN = "为一个友方目标和施法者本身各恢复{1}至271点生命值。低威胁值的技能。", zhTW = "同時治療一名友方目標和施法者{1}至271點生命力，造成低量的威脅值。" }, "n,n" },
	{ "another friendly heals over sec target", { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 추가로 {4}초에 걸쳐 총 {3}의 생명력을 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2}点生命值，并在{4}秒内恢复额外的{3}点生命值。", zhTW = "治療友方目標，恢復{1}至{2}點生命力，並在{4}秒內恢復額外的{3}點生命力。" }, "n,n,n,n" },
	{ "additional casts chain directly effectiveness friendly heal heals increases over sec target", { ko = "아군 대상을 {1}~{2}만큼 치유한 후, 추가로 {4}초에 걸쳐 {3}만큼 회복시킵니다. 또한 대상에게 직접 시전하는 연쇄 치유의 효과가 {5}%만큼 증가합니다.", zhCN = "治疗一个友方目标，为其恢复{1}至{2}点生命值，并在{4}秒内额外恢复{3}点，同时使你对该目标直接施放的治疗链效果提高{5}%。", zhTW = "為一個友方目標治療{1}至{2}點生命力，同時在{4}秒內額外治療{3}點生命力，且你的治療鍊直接對該目標施放時，效果提高{5}%。" }, "n,n,n,n,p" },
	{ "another friendly heals over sec target", { ko = "대상의 생명력을 {1}~{2},{3}만큼 회복시키고 추가로 {5}초에 걸쳐 총 {4}의 생명력을 회복시킵니다.", zhCN = "治疗友方目标，恢复{1}至{2},{3}点生命值，并在{5}秒内恢复额外的{4}点生命值。", zhTW = "治療友方目標，恢復{1}至{2},{3}點生命力，並在{5}秒內恢復額外的{4}點生命力。" }, "n,n,n,n,n" },
	{ "amount equal friendly heals health maximum paladin's target", { ko = "성기사의 최대 생명력만큼 아군 대상을 치유합니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力。" }, "" },
	{ "amount equal friendly heals health mana maximum paladin's restores target their", { ko = "성기사의 최대 생명력만큼 아군 대상을 치유하고 {1}의 마나를 회복시킵니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值，并为其恢复{1}点法力值。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力，並恢復{1}點法力。" }, "n" },
	{ "all amount but does drains equal friendly heals health interrupt mana maximum not paladin's regeneration remaining restores target their used when", { ko = "성기사의 최대 생명력만큼 아군 대상을 치유하고 {1}의 마나를 회복시킵니다. 이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值，并为其恢复{1}点法力值。使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力，並恢復{1}點法力。使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" }, "n" },
	{ "all amount but does drains equal friendly heals health interrupt mana maximum not paladin's regeneration remaining target used when", { ko = "성기사의 최대 생명력만큼 아군 대상을 치유합니다. 이 능력을 사용하면 성기사의 남은 모든 마나가 소진되지만, 마나 회복을 방해하진 않습니다.", zhCN = "治疗一个友方目标，为其恢复相当于圣骑士最大生命值的生命值。使用时会消耗圣骑士剩余的所有法力值，但不会中断法力回复。", zhTW = "治療一個友方目標，為其恢復相當於聖騎士生命力上限的生命力。使用這一法術將消耗聖騎士的所有剩餘法力，但不會中斷法力恢復。" }, "" },
	{ "additional friendly heal heals jumps nearby target targets then", { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 그 주위의 아군을 연쇄적으로 회복시킵니다.", zhCN = "为友方目标回复{1}至{2}点生命值，然后转而治疗附近的目标。", zhTW = "為友方目標恢復{1}至{2}點生命力，然後轉而治療附近其他的目標。" }, "n,n" },
	{ "additional cast each effective friendly heal heals if jump jumps member members nearby only other party previous target targets then total will", { ko = "대상의 생명력을 {1}~{2}만큼 회복시키고 그 주위의 아군을 연쇄적으로 회복시킵니다. 파티원에게 사용하면 같은 파티원에게만 효과가 전달됩니다. 대상이 바뀔 때마다 이전 대상 대비 {3}%의 효율을 발휘합니다. 최대 {4}명의 대상에게 효력을 미칩니다.", zhCN = "为友方目标回复{1}至{2}点生命值，然后转而治疗附近的目标。如果对小队成员施法，则治疗链只会继续治疗其队友。治疗链每次跳跃后的治疗效果是上一个目标的{3}%。总共可治疗{4}个目标。", zhTW = "為友方目標恢復{1}至{2}點生命力，然後轉而治療附近其他的目標。如果施放在隊伍成員身上，則治療效果只會治療其他的隊伍成員。治療鍊每次跳躍後的治療效果會等同於先前目標的{3}%。總共可治療{4}個目標。" }, "n,n,p,n" },
	{ "heals over party sec target their", { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다.", zhTW = "治療目標和其隊伍，使其在{2}秒內恢復{1}點生命力。" }, "n,n" },
	{ "amount applied down duration first full growth healed heals members must over party quickly reaches sec slows target their wild within yards", { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다. 파티원이 대상의 {3}미터 내에 있어야 합니다. 처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다.", zhCN = "在{2}秒内为目标及其{3}码内的小队成员恢复{1}点生命值。治疗效果起初较快，随着野性成长接近结束而变慢。", zhTW = "治療目標和其隊伍，使其在{2}秒內恢復{1}點生命力。小隊成員必須在目標附近{3}碼內。野性痊癒的恢復速度在起步時最快，並且隨時間而減緩，直到結束為止。" }, "n,n,n" },
	{ "amount applied down duration first full growth healed heals members must over party quickly reaches sec slows target their wild within yds", { ko = "대상과 대상의 파티를 {2}초에 걸쳐 {1}만큼 치유합니다. 파티원이 대상의 {3}미터 내에 있어야 합니다. 처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다." }, "n,n,n" },
	{ "heals over sec target", { ko = "{2}초에 걸쳐 {1}의 생명력을 회복시킵니다.", zhCN = "治疗目标，在{2}秒内恢复总计{1}点生命值。", zhTW = "治療目標，在{2}秒內恢復總計{1}點生命力。" }, "n,n" },
	{ "damage heals over sec target", { ko = "{2}초에 걸쳐 대상의 생명력을 총 {1}만큼 회복시킵니다.", zhCN = "治疗目标，在{2}秒内恢复总计{1}点生命值。", zhTW = "治療目標，在{2}秒內恢復總計{1}點生命力。" }, "n,n" },
	{ "every focus heals health pet second while", { ko = "야수에 정신을 집중하는 동안 매초마다 {1}의 생명력을 치료합니다.", zhCN = "集中注意力为宠物治疗，令其每秒恢复{1}点生命值。", zhTW = "集中注意力為寵物治療，令其每秒恢復{1}點生命力。" }, "n" },
	{ "every focus heals health lasts pet sec second while", { ko = "야수에 정신을 집중하는 동안 매초마다 {1}의 생명력을 치료합니다. {2}초 동안 지속됩니다.", zhCN = "集中注意力为宠物治疗，令其每秒恢复{1}点生命值。持续{2}秒。", zhTW = "集中注意力為寵物治療，令其每秒恢復{1}點生命力。持續{2}秒。" }, "n,n" },
	{ "ability casting consuming grants hitting killing mana next rapid regeneration sec serpent sting target while", { ko = "독사 쐐기를 대상에게 적중시키면 다음 {3}초 동안 시전 중에도 {1}%의 속도로 마나를 회복합니다. 신속한 사냥을 소모하는 경우에는 {2}%의 속도로 회복합니다.", zhCN = "用毒蛇钉刺命中目标时使你获得{1}%、消耗疾速杀戮时使你获得{2}%的施法时法力回复，持续{3}秒。", zhTW = "以毒蛇釘刺技能命中目標，或消耗急速殺戮後，分別使你在接下來的{3}秒內在施法時仍保持{1}%和{2}%的法力恢復速度。" }, "p,p,n" },
	{ "all conflagrate damage deal enemy fire hitting increases sec shadow shadowburn", { ko = "적에게 점화를 적중시키면 {2}초 동안 주는 모든 암흑 피해가 {1}%만큼 증가하고, 적에게 어둠의 연소를 적중시키면 {4}초 동안 주는 모든 화염 피해가 {3}%만큼 증가합니다.", zhTW = "以焚燒命中敵人會使你造成的所有暗影傷害提高{1}%，持續{2}秒，且以暗影灼燒命中敵人會使你造成的所有火焰傷害提高{3}%，持續{4}秒。" }, "p,n,p,n" },
	{ "addition all chance conflagrate consume damage deal enemy fire has hitting immolate increases instantly not refund sec shadow shadowburn shard soul", { ko = "적에게 점화를 적중시키면 {2}초 동안 주는 모든 암흑 피해가 {1}%만큼 증가하고, 적에게 어둠의 연소를 적중시키면 {4}초 동안 주는 모든 화염 피해가 {3}%만큼 증가합니다. 추가로, 점화가 {5}%의 확률로 제물을 소모하지 않고, 어둠의 연소가 {6}%의 확률로 영혼의 조각을 즉시 돌려줍니다.", zhCN = "使用燃烧击中敌人后，你造成的所有暗影伤害提高{1}%，持续{2}秒。使用暗影灼烧击中敌人后，你造成的所有火焰伤害提高{3}%，持续{4}秒。此外，燃烧有{5}%的几率不消耗献祭，暗影灼烧有{6}%的几率立刻返还一块灵魂碎片。", zhTW = "以焚燒命中敵人會使你造成的所有暗影傷害提高{1}%，持續{2}秒，且以暗影灼燒命中敵人會使你造成的所有火焰傷害提高{3}%，持續{4}秒。此外，焚燒有{5}%機率不會消耗獻祭，且暗影灼燒有{6}%機率會立即返還一個靈魂裂片。" }, "p,n,p,n,p,p" },
	{ "holy hr increasing infuses power spirit target their", { ko = "신성한 힘이 대상을 감싸 {2}시간 동안 정신력을 {1}만큼 증가시킵니다.", zhCN = "圣洁的能量充满目标全身，令其精神提高{1}点，持续{2}小时。", zhTW = "聖潔的能量充滿目標全身，令其精神提高{1}點，持續{2}小時。" }, "n,n" },
	{ "cast form healing however may not spells while", { zhCN = "但是在此形态下，你无法施放治疗法术。", zhTW = "然而，在此形態下你無法施放治療法術。" }, "" },
	{ "causing enemies flee howl sec terror within yds", { ko = "끔찍한 소리로 울부짖어 {2}초 동안 {3}미터 반경의 적 {1}명을 공포에 질려 도망가게 만듭니다.", zhCN = "使半径{2}码范围内的{1}个敌人因恐惧而逃跑，持续{3}秒。", zhTW = "使半徑{2}碼範圍內的{1}個敵人因恐懼而逃跑，持續{3}秒。" }, "n,n,n" },
	{ "caused causing damage effect enemies flee howl interrupt may sec terror within yds", { ko = "끔찍한 소리로 울부짖어 {2}초 동안 {3}미터 반경의 적 {1}명을 공포에 질려 도망가게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.", zhCN = "使半径{2}码范围内的{1}个敌人因恐惧而逃跑，持续{3}秒。逃跑的敌人若受到伤害，则恐惧效果可能被打断。", zhTW = "使半徑{2}碼範圍內的{1}個敵人因恐懼而逃跑，持續{3}秒。逃跑的敵人若受到傷害，則恐懼效果可能被打斷。" }, "n,n,n" },
	{ "additional damage dealing enemy hurl jumping nearby physical spikes target", { ko = "대상에게 가시를 던져 {1}의 물리 피해를 입히고 주위의 추가 적 {2}명에게 튕깁니다." }, "n,n" },
	{ "additional damage dealing each enemy hurl jump jumping nearby physical reduces spikes target", { ko = "대상에게 가시를 던져 {1}의 물리 피해를 입히고 주위의 추가 적 {2}명에게 튕깁니다. 튕길 때마다 입히는 피해가 {3}%만큼 감소합니다." }, "n,n,p" },
	{ "additional ball causes damage fiery fire hurls over sec", { ko = "적에게 불타는 구체를 날려 {1}의 화염 피해를 입히고 {3}초에 걸쳐 총 {2}의 추가 피해를 입힙니다.", zhCN = "发射一枚火球攻击目标，对其造成{1}点火焰伤害，并在{3}秒内造成额外的{2}点伤害。", zhTW = "發射一枚火球攻擊目標，對其造成{1}點火焰傷害，並在{3}秒內造成額外的{2}點傷害。" }, "n,n,n" },
	{ "additional ball causes damage fiery fire hurls over sec", { ko = "적에게 불타는 구체를 날려 {1}~{2}의 화염 피해를 입히고 {4}초에 걸쳐 총 {3}의 추가 화염 피해를 입힙니다.", zhCN = "发射一枚火球攻击目标，对其造成{1}至{2}点火焰伤害，并在{4}秒内造成额外的{3}点伤害。", zhTW = "發射一枚火球攻擊目標，對其造成{1}至{2}點火焰傷害，並在{4}秒內造成額外的{3}點火焰傷害。" }, "n,n,n,n" },
	{ "damage enemy hammer holy hurls strikes", { ko = "망치를 적에게 던져 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "投掷一柄战锤，对敌人造成{1}至{2}点神圣伤害。", zhTW = "投擲一柄戰錘，對敵人造成{1}至{2}點神聖傷害。" }, "n,n" },
	{ "damage enemies enemy hammer have health holy hurls less only strikes usable", { ko = "망치를 적에게 던져 {1}~{2}의 신성 피해를 입힙니다. 생명력이 {3}%미만인 적에게만 사용할 수 있습니다.", zhCN = "投掷一柄战锤，对敌人造成{1}至{2}点神圣伤害。只能对生命值少于{3}%的目标使用。", zhTW = "投擲一柄戰錘，對敵人造成{1}至{2}點神聖傷害。只能對生命低於{3}%的目標使用。" }, "n,n,p" },
	{ "additional bolt damage dealing enemies enemy hurls jumping lightning nature nearby then", { ko = "적에게 번개를 날려 {1}~{2}의 자연 피해를 입히고 주위 적을 연쇄적으로 가격합니다." }, "n,n" },
	{ "additional affects bolt damage dealing each enemies enemy hurls jump jumping lightning nature nearby reduces targets then total", { ko = "적에게 번개를 날려 {1}~{2}의 자연 피해를 입히고 주위 적을 연쇄적으로 가격합니다. 대상이 바뀔 때마다 피해는 {3}%씩 감소됩니다. 최대 {4}명의 대상을 공격합니다.", zhCN = "向敌人射出一支闪电箭，对其造成{1}至{2}点自然伤害，随后这支闪电箭会继续攻击它周围最近的敌人。闪电箭每跳跃一次，伤害就减少{3}%，最多可攻击{4}个目标。", zhTW = "向敵人射出一支閃電箭，對其造成{1}至{2}點自然傷害，隨後這支閃電箭會繼續攻擊它周圍最近的敵人。閃電箭每跳躍一次，傷害就減少{3}%，最多可影響{4}個目標。" }, "n,n,p,n" },
	{ "additional boulder causes damage fiery fire hurls immense over sec", { ko = "엄청난 크기의 불덩이를 던져 {1}~{2}의 화염 피해를 입히고 추가로 {4}초에 걸쳐 총 {3}의 화염 피해를 입힙니다.", zhCN = "发射一枚巨大的火球，对目标造成{1}至{2}点火焰伤害，并在{4}秒内造成总计{3}点额外伤害。", zhTW = "發射一枚巨大的火球，對目標造成{1}至{2}點火焰傷害，並在{4}秒內造成總計{3}點額外傷害。" }, "n,n,n,n" },
	{ "area damage doing frost ice over pelt sec shards target", { ko = "대상 지역에 얼음 파편을 퍼부어, {2}초에 걸쳐 총 {1}의 냉기 피해를 입힙니다.", zhCN = "破碎的冰块从天而降，在{2}秒内对目标区域中的敌人造成{1}点冰霜伤害。", zhTW = "寒冰的裂片墜落在目標區域，在{2}秒內造成總計{1}點冰霜傷害。" }, "n,n" },
	{ "area damage doing frost ice over pelt sec shards target", { ko = "대상 지역에 얼음 파편을 퍼부어, {3}초에 걸쳐 총 {1},{2}의 냉기 피해를 입힙니다.", zhCN = "破碎的冰块从天而降，在{3}秒内对目标区域中的敌人造成{1},{2}点冰霜伤害。", zhTW = "寒冰的裂片墜落在目標區域，在{3}秒內造成總計{1},{2}點冰霜傷害。" }, "n,n,n" },
	{ "being caster dies gains hit if non sec shadowburn shard soul target trivial within", { ko = "사소하지 않은 대상이 이 주문에 걸린 지 {1}초 내에 사망하면 시전자가 영혼의 조각을 얻습니다.", zhCN = "若消灭一个能为你提供经验值或荣誉值的敌人，且其在受到暗影灼烧后的{1}秒内死亡，则施法者获得一块灵魂碎片。", zhTW = "如果有實力的目標在被暗影灼燒命中後的{1}秒內死亡，則施法者獲得一塊靈魂裂片。" }, "n" },
	{ "damage dazed if member pack sec takes they will", { ko = "이 동안 파티원이 피해를 입게 되면 {1}초 동안 멍해지게 됩니다.", zhCN = "如果任何一个队友受到伤害，则全队都会眩晕{1}秒。", zhTW = "如果任何一個隊友受到傷害，則全隊都會眩暈{1}秒。" }, "n" },
	{ "devoured effect felhunter healed if will", { ko = "마법을 삼키게 되면 지옥사냥개는 {1}의 생명력을 회복합니다.", zhCN = "每吞噬一个魔法效果，地狱猎犬就可回复{1}点生命值。", zhTW = "每吞噬一個魔法效果，地獄獵犬就可回復{1}點生命力。" }, "n" },
