	{ "addition attack attacker blocks damage holy melee take target when will", { ko = "추가로 근접 공격을 방어할 경우 공격자에게 {1}의 신성 피해를 입힙니다.", zhCN = "另外，当目标格挡一次近战攻击时，攻击者会受到{1}点神圣伤害。", zhTW = "另外，當目標格擋一次近戰攻擊時，攻擊者會受到{1}點神聖傷害。" }, "n" },
	{ "ability addition afflicted damage dies enemy gain increasing kill killing next non rapid sec serpent shot sting trivial when while within", { ko = "또한 사소하지 않은 적을 처치하거나 해당 적이 자신의 독사 쐐기에 걸린 상태로 사망하면 신속한 사냥이 부여되어 {1}초 안에 사용하는 다음 사격 능력의 공격력이 {2}%만큼 증가합니다.", zhCN = "此外，当你消灭一个能为你提供经验值或荣誉值的敌人，或其在受到你的毒蛇钉刺影响时死亡，你获得疾速杀戮，使你在{1}秒内的下一个射击技能造成的伤害提高{2}%。", zhTW = "此外，如果你擊殺有實力的敵人，或該敵人在受你毒蛇釘刺影響時死亡，你會獲得急速殺戮，使你在{1}秒內施放的下一個射擊技能的傷害提高{2}%。" }, "n,p" },
	{ "addition bear cat dire form increased stamina strength while", { ko = "추가로 곰 변신이나 광포한 곰 변신 상태에서 체력이 {1}%만큼, 표범 변신 상태에서 힘이 {2}%만큼 증가합니다.", zhCN = "此外，在熊形态或巨熊形态下，耐力提高{1}%；在猎豹形态下，力量提高{2}%。", zhTW = "另外，在熊形態或巨熊形態下，你的耐力提高{1}%，在獵豹形態下，你的力量提高{2}%。" }, "p,p" },
	{ "addition allow casting chance continue critical have mana regeneration sec strikes while", { ko = "또한 치명타 발생 시 {1}%의 확률로 {3}초 동안 시전 중에도 평소의 {2}%에 달하는 속도로 마나가 회복됩니다." }, "p,p,n" },
	{ "abilities add addition additional cat chance combo critical form generate have non periodic point points strikes", { ko = "또한 연계 점수를 생성하는 표범 변신 능력이 비주기적인 치명타 및 극대화 효과를 발휘하면 {1}%의 확률로 추가 연계 점수를 생성합니다.", zhCN = "此外，你的猎豹形态下可产生连击点数的技能的非周期性爆击有{1}%的几率额外增加一个连击点数。", zhTW = "此外，而在獵豹形態時可產生連擊點數的非週期性效果造成致命一擊後，有{1}%的機率再獲取一個額外的連擊點數。" }, "p" },
