	{ "armor frost increases resistance", { ko = "방어도를 {1}만큼, 냉기 저항력을 {2}만큼 증가시킵니다.", zhCN = "使护甲值提高{1}点，冰霜抗性提高{2}点。", zhTW = "使護甲值提高{1}點，冰霜抗性提高{2}點。" }, "n,n" },
