	{ "active any armor attacks between can caster enemy have if increased increases lasts mage may min movement one only sec slowed spell strikes their they time type", { ko = "방어도가 {2}만큼 증가하고 시전자를 공격한 적은 일정 확률로 {4}초 동안 이동 속도가 {5}%만큼 감소하며 공격 간격이 {3}%만큼 늘어날 수 있습니다. 마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다. 30분 동안 지속됩니다.", zhCN = "使护甲值提高{2}点。如果敌人使用近战武器攻击施法者，他们的移动速度就有可能被降低{5}%，攻击间隔延长{3}%，冰冻效果持续{4}秒。法师在同一时间内只能保有一种魔法护甲效果。持续30分钟。", zhTW = "使護甲值提高{2}點。如果敵人使用近戰武器攻擊施法者，他們的移動速度就有可能降低{5}%，攻擊間隔時間延長{3}%，持續{4}秒。同一時間內法師只能擁有一種護甲法術。霜甲術可持續30分鐘。" }, "n,p,p,n,n" },
	{ "attack increases power sec", { ko = "{2}초 동안 전투력이 {1}만큼 증가합니다.", zhCN = "攻击强度提高{1}点，持续{2}秒。", zhTW = "攻擊強度提高{1}點，持續{2}秒。" }, "n,n" },
	{ "areas attack doubled effect increases power sec volcanic", { ko = "{2}초 동안 전투력이 {1}만큼 증가합니다. 화산 지역에서는 효과가 2배로 증가합니다.", zhCN = "攻击强度提高{1}点，持续{2}秒。在火山区域时，攻击强度加成翻倍。", zhTW = "攻擊強度提高{1}點，持續{2}秒。在火山區域時，攻擊強度加成翻倍。" }, "n,n" },
	{ "active attack block blocked chance damage deals each holy increases sec while", { ko = "{2}초 동안 방패 막기 확률이 {1}%만큼 증가하며, 효과가 활성화된 동안 공격을 방패로 막을 때마다 공격자에게 {3}의 신성 피해를 입힙니다.", zhTW = "使你的格擋機率提高{1}%，持續{2}秒，在此期間每次成功格擋都會對攻擊者造成{3}點神聖傷害。" }, "p,n,n" },
