	{ "amount healed increases spells", { ko = "주문으로 회복되는 생명력이 {1}%만큼 증가합니다.", zhCN = "使你的法术治疗量提高{1}%。", zhTW = "使你法術的治療效果提高{1}%。" }, "p" },
	{ "absorbed amount blocks chance damage gives increases mana maximum restore shield", { zhCN = "使你的盾牌吸收的伤害提高{1}%，并使你的格挡有{2}%的几率恢复最大法力值的{3}%。", zhTW = "使你盾牌吸收的傷害值提高{1}%，且格擋時，有{2}%的機率恢復法力上限{3}%的法力。" }, "p,p,p" },
