	{ "amount awarded increases life mana spell tap", { ko = "생명력 전환으로 얻는 마나가 {1}%만큼 증가합니다.", zhCN = "使你的生命分流法术所转化的法力值提高{1}%。", zhTW = "使你的生命分流法術所轉化的法力提高{1}%。" }, "p" },
