	{ "also barrow deeps gain haste hyjal increases mount stamina summit while", { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 가속이 {2}%만큼 증가합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你还会获得{2}%的急速。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{2}%加速。" }, "n,p" },
	{ "also barrow chance deeps gain hit hyjal increases mount stamina summit while", { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 적중률이 {2}%만큼 증가합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你还会获得{2}%的命中几率。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你還會獲得{2}%命中機率。" }, "n,p" },
	{ "also barrow chance deeps dodged gain hyjal increases mount parried reduced stamina summit while", { ko = "체력이 60만큼 증가합니다. 하이잘 산과 하이잘 정상, 지하굴에서 공격이 회피되거나 무기 막기에 막힐 확률이 {2}%만큼 감소합니다.", zhCN = "使你的耐力提高60点。在海加尔山、海加尔峰和深穴内，你的攻击被躲闪或招架的几率还会降低{2}%。", zhTW = "使你的耐力提高60點。在海加爾山、海加爾山之巔和地深獸穴時，你被閃躲或招架的機率還會降低{2}%。" }, "n,p" },
	{ "attacks chance detection higher hit if increases level ranged reduces spells stealth were", { ko = "은신 감지 효과가 {1}레벨만큼 증가하고 주문과 원거리 공격에 적중당할 확률이 {2}%만큼 감소합니다.", zhCN = "使你的潜行侦测相当于提高{1}级，并使你被法术和远程攻击命中的几率降低{2}%。", zhTW = "提高偵測潛行的能力，效果相當於你的等級高{1}級，並使你被法術和遠程攻擊命中的機率降低{2}%。" }, "n,p" },
	{ "attacks chance detection higher hit if increases levels ranged reduces spells stealth were", { ko = "은신 감지 효과가 {1}레벨만큼 증가하고 주문과 원거리 공격에 적중당할 확률이 {2}%만큼 감소합니다.", zhCN = "使你的潜行侦测相当于提高{1}级，并使你被法术和远程攻击命中的几率降低{2}%。", zhTW = "提高偵測潛行的能力，效果相當於你的等級高{1}級，並使你被法術和遠程攻擊命中的機率降低{2}%。" }, "n,p" },
	{ "after armor critical effect getting healing increases one sec spells target's value", { ko = "치유 주문이 극대화 효과를 발휘했을 때 {2}초 동안 대상의 방어도를 {1}%만큼 증가시킵니다.", zhCN = "在你的任何一个治疗法术对目标造成极效治疗效果后，使目标因装备而获得的护甲值提高{1}%，持续{2}秒。", zhTW = "在你的任何一個治療法術對目標造成極效治療效果後，使目標的護甲值提高{1}%，持續{2}秒。" }, "p,n" },
	{ "bulwark cooldown divine increases protection reduces sec shield spells stamina templar's total", { ko = "전체 체력이 {1}%만큼 증가합니다. 또한 천상의 보호막과 신의 가호, 기사단의 보루의 재사용 대기시간이 {2}초만큼 감소합니다.", zhCN = "使你的耐力总值提高{1}%，并使圣盾术、圣佑术和圣殿骑士壁垒的冷却时间缩短{2}秒。", zhTW = "使你的總耐力提高{1}%，並使聖盾術、聖佑術和聖殿騎士之壁壘的冷卻時間縮短{2}秒。" }, "p,n" },
	{ "above against ineffective level targets", { zhCN = "对?级以上的目标不产生效果。", zhTW = "對?級以上的目標不產生效果。" }, "" },
