	{ "damage enemy inflicts movement reduces sec speed target's", { ko = "{1}의 피해를 입히고 {3}초 동안 적의 이동 속도를 {2}%만큼 감소시킵니다.", zhCN = "对敌人造成{1}点伤害，并使其移动速度降低{2}%，持续{3}秒。", zhTW = "對敵人造成{1}點傷害，並使其移動速度降低{2}%，持續{3}秒。" }, "n,p,n" },
