	{ "damage fire inflicts radius sec stuns targets yd", { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다.", zhCN = "造成{1}点火焰伤害，并使半径{2}码范围内的目标昏迷，持续{3}秒。", zhTW = "造成{1}點火焰傷害，並使半徑{2}碼範圍內的目標昏迷，持續{3}秒。" }, "n,n,n" },
