	{ "damage fire inflicts radius sec stuns targets yd", { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다.", zhCN = "造成{1}点火焰伤害，并使{2}码范围内的目标昏迷{3}秒。", zhTW = "造成{1}點火焰傷害，並使{2}碼範圍內的目標昏迷{3}秒。" }, "n,n,n" },
	{ "any break damage effect fire inflicts radius sec stuns targets will yd", { ko = "{2}미터 반경에 {1}의 화염 피해를 입히고 대상을 {3}초 동안 기절시킵니다. 대상이 피해를 받으면 효과가 사라집니다.", zhCN = "造成{1}点火焰伤害，并使{2}码范围内的目标昏迷{3}秒。任何伤害都会打破该效果。", zhTW = "造成{1}點火焰傷害，並使{2}碼範圍內的目標昏迷{3}秒。任何傷害都會打破該效果。" }, "n,n,n" },
	{ "damage fire inflicts radius yd", { ko = "{2}미터 반경에 {1}의 화염 피해를 입힙니다.", zhCN = "对半径{2}码范围内的目标造成{1}点火焰伤害。", zhTW = "對半徑{2}碼範圍內的目標造成{1}點火焰傷害。" }, "n,n" },
	{ "damage done healing increasing infuses power sec spell target their", { ko = "대상에게 마력을 주입하여 모든 주문의 피해와 치유량을 {1}%만큼 증가시킵니다. {2}초 동안 지속됩니다.", zhCN = "为目标注入能量，使其法术伤害和治疗量提高{1}%，持续{2}秒。", zhTW = "對目標注入能量，使他們造成的法術傷害和治療效果提高{1}%。持續{2}秒。" }, "p,n" },
	{ "brilliance hr increasing infuses intellect party raid target's their", { ko = "대상 파티원 및 공격대원에게 총명한 기운을 불어넣어 {2}시간 동안 지능을 {1}만큼 증가시킵니다.", zhCN = "为目标所在的队伍和团队注入智慧，使其智力提高{1}点，持续{2}小时。", zhTW = "魔法的光輝籠罩著目標所在的隊伍和團隊，使他們的智力提高{1}點，持續{2}小時。" }, "n,n" },
	{ "attack causing damage healing health instantly maximum power target", { ko = "즉시 대상을 공격하여 {1}(+ 전투력의 {2}%)의 피해를 입히고 최대 생명력의 {3}%에 해당하는 생명력을 회복합니다.", zhCN = "立即攻击目标，造成{1}（+攻击强度的{2}%）点伤害，并为你恢复最大生命值的{3}%。", zhTW = "立即攻擊目標，造成{1}（+攻擊強度的{2}%）點傷害，併為你恢復最大生命力的{3}%。" }, "n,p,p" },
	{ "after attack causing damage enemy healing health instantly kill maximum non only power sec target trivial useable within", { ko = "즉시 대상을 공격하여 {1}(+ 전투력의 {2}%)의 피해를 입히고 최대 생명력의 {3}%에 해당하는 생명력을 회복합니다. 사소하지 않은 적을 처치한 후 {4}초 동안에만 사용할 수 있습니다.", zhCN = "立即攻击目标，造成{1}（+攻击强度的{2}%）点伤害，并为你恢复最大生命值的{3}%。只能在击杀一个能为你提供经验值或荣誉值的敌人后的{4}秒内使用。", zhTW = "立即攻擊目標，造成{1}（+攻擊強度的{2}%）點傷害，併為你恢復最大生命力的{3}%。只能在擊殺一個能為你提供經驗值或榮譽值的敵人後的{4}秒內使用。" }, "n,p,p,n" },
	{ "attack causing damage equal increasing instantly movement plus power sec speed target", { ko = "즉시 적을 공격하여 전투력의 {1}%에 해당하는 피해와 {2}의 추가 피해를 입힙니다. 추가로 {3}초 동안 시전자의 이동 속도가 {4}%만큼 증가합니다.", zhCN = "立即攻击目标，造成相当于攻击强度{1}%外加{2}点的伤害，并使移动速度提高{3}%，持续{4}秒。", zhTW = "立刻攻擊目標，對其造成相當於你的攻擊強度{1}%再加上{2}點的傷害，並使你的移動速度提高{3}%，持續{4}秒。" }, "p,n,p,n" },
	{ "additional attacks both damage each instantly plus weapon weapons", { ko = "양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다.", zhCN = "立即用两把武器攻击，每把武器造成{1}%武器伤害，外加{2}点伤害。", zhTW = "立即使用主、副手武器攻擊，使其各自造成{1}%武器傷害外加{2}點的額外傷害。" }, "p,n" },
	{ "additional against attacks awards both combo damage each increased instantly plus points poisoned targets weapon weapons", { ko = "양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 {1}%에 {2}의 추가 피해를 입힙니다. 독에 걸린 대상을 가격할 때 공격력이 {3}%만큼 증가합니다. 연계 점수 {4}점이 주어집니다.", zhCN = "立即用两把武器攻击，每把武器造成{1}%武器伤害，外加{2}点伤害。对中毒目标造成的伤害提高{3}%。奖励{4}个连击点。", zhTW = "立即使用主、副手武器攻擊，使其各自造成{1}%武器傷害外加{2}點的額外傷害。對中毒目標造成的傷害提高{3}%。獎勵{4}個連擊點數。" }, "p,n,p,n" },
	{ "blasts damage instantly shadow target", { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다.", zhCN = "立即冲击目标，造成{1}至{2}点暗影伤害。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。" }, "n,n" },
	{ "being blasts caster damage dies gains hit if instantly non sec shadow shadowburn shard soul target trivial within", { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다. 사소하지 않은 대상이 이 주문에 걸린 지 {3}초 내에 사망하면 시전자가 영혼의 조각을 얻습니다.", zhCN = "立即冲击目标，造成{1}至{2}点暗影伤害。若消灭一个能为你提供经验值或荣誉值的敌人，且其在受到暗影灼烧后的{3}秒内死亡，则施法者获得一块灵魂碎片。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。如果有實力的目標在被暗影灼燒命中後的{3}秒內死亡，則施法者獲得一塊靈魂裂片。" }, "n,n,n" },
	{ "blasts caster damage dies experience gains honor if instantly sec shadow shadowburn shard soul target within yields", { ko = "즉시 적을 강타하여 {1}~{2}의 암흑 피해를 입힙니다. 이 주문이 걸린 지 {3}초 내에 대상이 죽고 경험치나 명예 점수를 받게되면 영혼의 조각 1개를 얻습니다.", zhCN = "立即使用暗影能量冲击目标，对其造成{1}至{2}点暗影伤害。如果目标受到暗影灼烧伤害之后的{3}秒内死亡，且施法者因此获得经验值或荣誉，则施法者获得一块灵魂碎片。", zhTW = "立即使用暗影能量衝擊目標，對其造成{1}至{2}點暗影傷害。如果目標於{3}秒內死於暗影灼燒，且施法者因此獲得經驗值或榮譽，則施法者獲得一塊靈魂碎片。" }, "n,n,n" },
	{ "base convert energy instantly mana", { ko = "즉시 기본 마나의 {1}%를 {2}의 기력으로 바꿉니다." }, "p,n" },
	{ "base convert cost effects energy instantly mana power's reduce reduced shapeshifting shifting", { ko = "즉시 기본 마나의 {1}%를 {2}의 기력으로 바꿉니다. 변신의 마나 비용을 줄이는 효과는 변신의 힘의 비용도 줄입니다." }, "p,n" },
	{ "amount counterattack damage enemy high instantly threat", { zhCN = "立即反击敌人，对其造成{1}至{2}点伤害，并造成大量的威胁。", zhTW = "立即反擊敵人，對其造成{1}至{2}點傷害，並造成大量的威脅。" }, "n,n" },
	{ "amount block counterattack damage dodge enemy follow high instantly must parry revenge threat", { ko = "즉시 적의 공격에 반격하여 {1}~{2}의 피해를 입힙니다. 위협 수준이 크게 증가합니다. 적의 공격에 대해 방어 행동을 취한 직후에만 사용할 수 있습니다.", zhCN = "立即反击敌人，对其造成{1}至{2}点伤害，并造成大量的威胁。复仇只有在成功格挡、躲闪或招架之后才能使用。", zhTW = "立即反擊敵人，對其造成{1}至{2}點傷害，並造成大量的威脅。復仇只有在成功格擋、躲閃或招架之後才能使用。" }, "n,n" },
	{ "any counterattack enemy instantly melee sec strikes", { ko = "{1}초 동안 근접 공격을 하는 모든 적에게 반격합니다.", zhCN = "在任何敌人以近战武器击中你之后可以立刻对其进行反击，持续{1}秒。", zhTW = "在任何敵人的近戰攻擊命中你之後可以立即對其進行反擊，持續{1}秒。" }, "n" },
	{ "any attacks behind cannot cause counterattack counterattacked enemy instantly made maximum melee retaliation sec strikes will", { ko = "{1}초 동안 근접 공격을 하는 모든 적에게 반격합니다. 등 뒤에서의 공격은 반격할 수 없습니다. 최대 {2}회의 반격이 가능합니다.", zhCN = "在任何敌人以近战武器击中你之后可以立刻对其进行反击，持续{1}秒。从你背后发动的近战攻击无法被反击。最多可反击{2}次攻击。", zhTW = "在任何敵人的近戰攻擊命中你之後可以立即對其進行反擊，持續{1}秒。從你背後發動的近戰攻擊無法被反擊。最多可反擊{2}次攻擊。" }, "n,n" },
	{ "another armor base bear but dire form generates instantly over rage reduces sec", { zhCN = "立即产生{1}点怒气，随后在{3}秒内额外产生{2}点怒气，但在熊形态下基础护甲降低{4}%，在巨熊形态下基础护甲降低{5}%。", zhTW = "立即產生{1}點怒氣，並在{3}秒內產生{2}點怒氣，不過在熊形態下基礎護甲值降低{4}%，在巨熊形態下則降低{5}%。" }, "n,n,n,p,p" },
