	{ "charges lasts min until used", { ko = "{1}분 동안 지속됩니다.", zhCN = "效果可持续{1}分钟，或在{2}次防护之后消失。", zhTW = "持續{1}分鐘或直至防護能量被使用{2}次。" }, "n,n" },
