	{ "can death effect flask have hr lasts one only persists through time", { ko = "{1}시간 동안 지속됩니다. 영약은 동시에 하나만 사용할 수 있습니다. 이 효과는 죽어도 지속됩니다.", zhCN = "持续{1}小时。你同时只能获得一种合剂的效果。这种效果在死亡后仍可继续存在。", zhTW = "持續{1}小時。你同時只能有一種精煉藥劑的效果。此效果在死亡之後仍然有效。" }, "n" },
	{ "explodes lasts min until", { ko = "{1}분이 지나거나 폭발할 때까지 지속됩니다.", zhCN = "持续{1}分钟或直到它爆炸为止。", zhTW = "綿羊自召喚出來後最多存在{1}分鐘。" }, "n" },
