	{ "bolt causing damage enemy frost launches movement sec slowing speed", { ko = "적에게 얼음 화살을 날려 {1} 에서 {2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다." }, "n,n,p,n" },
	{ "bolt causing damage enemy frost launches movement sec slowing speed", { ko = "적에게 얼음 화살을 날려 {1}에서 {2}의 냉기 피해를 입히고 {4}초 동안 이동 속도를 {3}%만큼 감소시킵니다.", zhCN = "向目标射出一支寒冰箭，对其造成{1}至{2}点冰霜伤害并使其移动速度降低{3}%，持续{4}秒。", zhTW = "向敵人射出一支寒冰箭，對其造成{1}點到{2}點冰霜傷害，並降低{3}%的移動速度，持續{4}秒。" }, "n,n,p,n" },
	{ "additional bolt causing damage enemy frostfire launches movement over sec slowing speed", { ko = "적에게 얼음불꽃 화살을 발사하여 {1}~{2}의 냉기화염 피해를 입히고 이동 속도를 {3}%만큼 감소시킨 후 {5}초에 걸쳐 추가로 {4}의 냉기화염 피해를 입힙니다.", zhCN = "对敌人施放霜火之箭，造成{1}至{2}点霜火伤害，使其移动速度降低{3}%，并在{5}秒内造成额外{4}点霜火伤害。", zhTW = "向目標射出一支霜火箭，造成{1}至{2}點霜火傷害並使其移動速度降低{3}%，同時在{5}秒內額外造成{4}點霜火傷害。" }, "n,n,p,n,n" },
	{ "additional against bolt both causing checked counts damage enemy fire frost frostfire launches lower movement over resists sec slowing speed spell target's will", { ko = "적에게 얼음불꽃 화살을 발사하여 {1}~{2}의 냉기화염 피해를 입히고 이동 속도를 {3}%만큼 감소시킨 후 {5}초에 걸쳐 추가로 {4}의 냉기화염 피해를 입힙니다. 이 주문은 대상의 냉기 및 화염 저항력 중 낮은 수치를 상대로 적중하며, 냉기 및 화염 피해로 간주됩니다.", zhCN = "对敌人施放霜火之箭，造成{1}至{2}点霜火伤害，使其移动速度降低{3}%，并在{5}秒内造成额外{4}点霜火伤害。该法术同时视为冰霜与火焰伤害，并以目标冰霜与火焰抗性中较低者为准。", zhTW = "向目標射出一支霜火箭，造成{1}至{2}點霜火傷害並使其移動速度降低{3}%，同時在{5}秒內額外造成{4}點霜火傷害。此法術將會檢視目標的冰霜與火焰抗性，依照較低的一方造成傷害，並同時視為冰霜和火焰傷害。" }, "n,n,p,n,n" },
	{ "ally causing damage enemy every healing holy instantly launches light sec target volley", { ko = "대상에게 신성한 빛의 화살을 날립니다. 적에게는 즉시, 그리고 {4}초 동안 {3}초마다 {1}의 신성 피해를 입히며, 아군에게는 같은 주기로 {2}만큼 생명력을 회복시킵니다.", zhCN = "向目标释放圣光能量，立即对一名敌人造成{1}点神圣伤害，或为一名盟友恢复{2}点生命值，并在接下来的{4}秒内每{3}秒重复一次效果。", zhTW = "對目標發出數道神聖之光，立即對敵人造成{1}點神聖傷害，或為一名盟友治療{2}點生命力，每{3}秒重複一次，持續{4}秒。" }, "n,n,n,n" },
