	{ "armor chest feet hands increase item legs permanently power spell value worn", { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。" }, "n,n" },
	{ "above armor chest feet hands increase item items legs level only permanently power spell usable value worn", { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다. {3} 레벨 이상의 아이템에만 사용할 수 있습니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。只能用于{3}级及以上的物品。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。只能用於{3}級及以上的物品。" }, "n,n,n" },
	{ "armor chest feet hands increase item legs permanently power spell value worn", { ko = "가슴이나 발, 손, 다리에 착용하는 방어구의 주문력이 {1}만큼, 방어도는 {2}만큼 영구적으로 증가합니다.", zhCN = "永久性地使一件装备在胸部、腿部、手部或脚部的物品的法术强度提高{1}点，护甲值提高{2}点。", zhTW = "永久性地使一件裝備在胸部、腿部、手部或腳部的物品的法術能量提高{1}點，護甲值提高{2}點。" }, "n,n" },
	{ "caused damage min physical reduced target", { ko = "{2}분 동안 대상의 물리 공격력을 {1}만큼 감소시킵니다.", zhCN = "目标造成的物理伤害降低{1}点，持续{2}分钟。", zhTW = "目標所能造成的物理傷害降低{1}點，持續{2}分鐘。" }, "n,n" },
	{ "active any can caused curse damage min one only per physical reduced target warlock", { ko = "{2}분 동안 대상의 물리 공격력을 {1}만큼 감소시킵니다. 흑마법사마다 한 대상에 동시에 하나의 저주만 걸 수 있습니다.", zhCN = "目标造成的物理伤害降低{1}点，持续{2}分钟。每个术士在任一目标身上只能维持一种诅咒。", zhTW = "目標所能造成的物理傷害降低{1}點，持續{2}分鐘。每個術士只能對同一個目標施加一種詛咒。" }, "n,n" },
	{ "damage physical reduced taken", { ko = "받는 물리 피해가 {1}%만큼 감소합니다.", zhCN = "受到的物理伤害降低{1}%。" }, "p" },
	{ "access allows carrier compact critter group hunters min pets place stabled their", { ko = "{1}분 동안 소형 동물 이동장을 놓아 파티 내 사냥꾼이 야수 우리에 있는 야수를 이용할 수 있게 합니다.", zhCN = "放置一个便携式小动物箱，持续{1}分钟，使队伍中的猎人可以取用寄养在兽栏中的宠物。", zhTW = "放置一個持續{1}分鐘的輕巧小動物提籠，讓你隊伍中的獵人得以取用獸欄中的寵物。" }, "n" },
	{ "additional all approaches causing damage enemy explodes fire over place sec trap when within yards", { ko = "덫을 설치합니다.", zhCN = "放置一个火焰陷阱，当敌人接近时爆炸，对{5}码内所有目标造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。", zhTW = "在地面上放置一個火焰陷阱，當敵人接近時會爆炸，對半徑{5}碼範圍內的所有目標造成{1}至{2}點火焰傷害，並在接下來的{4}秒內額外造成{3}點火焰傷害。" }, "n,n,n,n,n" },
	{ "active additional all approaches can causing damage enemy exist explodes fire min one only over place sec time trap when will within yards", { ko = "덫을 설치합니다. 적이 다가오면 폭발하여 적에게 {1}~{2}의 화염 피해를 입히고 주위 {5}미터 반경에 있는 모든 대상에게 {4}초에 걸쳐 {3}의 추가 화염 피해를 입힙니다. 덫은 {6}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个火焰陷阱，当敌人接近时爆炸，对{5}码内所有目标造成{1}至{2}点火焰伤害，并在{4}秒内额外造成{3}点火焰伤害。陷阱会存在{6}分钟。同一时间只能激活一个火焰陷阱。", zhTW = "在地面上放置一個火焰陷阱，當敵人接近時會爆炸，對半徑{5}碼範圍內的所有目標造成{1}至{2}點火焰傷害，並在接下來的{4}秒內額外造成{3}點火焰傷害。陷阱可存在{6}分鐘。同一時間內只能設置一個火焰陷阱。" }, "n,n,n,n,n,n" },
	{ "approach burn damage enemy fire first over place sec trap will", { ko = "덫을 설치합니다.", zhCN = "放置一个火焰陷阱，灼烧第一个接近它的敌人，在{2}秒内造成{1}点火焰伤害。", zhTW = "在地面上放置一個火焰陷阱，灼燒第一個接近它的敵人，在{2}秒內對其造成{1}點火焰傷害。" }, "n,n" },
	{ "active approach burn can damage enemy exist fire first min one only over place sec time trap will", { ko = "덫을 설치합니다. 적이 다가오면 불태워 {2}초에 걸쳐 총 {1}의 화염 피해를 입힙니다. 덫은 {3}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个火焰陷阱，灼烧第一个接近它的敌人，在{2}秒内造成{1}点火焰伤害。陷阱会存在{3}分钟。同一时间只能激活一个火焰陷阱。", zhTW = "在地面上放置一個火焰陷阱，灼燒第一個接近它的敵人，在{2}秒內對其造成{1}點火焰傷害。陷阱可存在{3}分鐘。同一時間內只能設置一個火焰陷阱。" }, "n,n,n" },
	{ "approaches around creates enemy first frost ice itself place sec slick trap when", { zhCN = "放置一个冰霜陷阱，当第一个敌人接近时，会在其周围形成一片持续{1}秒的冰面。", zhTW = "在地面上放置一個冰霜陷阱，在敵人接近時會製造一片光滑的冰面，持續{1}秒。" }, "n" },
	{ "active all approaches area around can creates effect enemies enemy exist first frost ice itself min one only place sec slick slowed time trap when while will within yards", { ko = "냉기의 덫을 설치합니다. 적이 다가오면 얇은 얼음판을 펼쳐, {1}초 동안 {2}미터 내의 적의 이동 속도를 {3}%만큼 감소시킵니다. 덫은 {4}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个冰霜陷阱，当第一个敌人接近时，会在其周围形成一片持续{1}秒的冰面。效果区域内{2}码范围的所有敌人移动速度降低{3}%。陷阱会存在{4}分钟。同一时间只能激活一个冰霜陷阱。", zhTW = "在地面上放置一個冰霜陷阱，在敵人接近時會製造一片光滑的冰面，持續{1}秒。所有在{2}碼範圍內的敵人的移動速度都會降低{3}%。陷阱可存在{4}分鐘。同一時間內只能設置一個冰霜陷阱。" }, "n,n,p,n" },
	{ "action all approaches enemy first freezes frost place preventing sec trap up", { ko = "냉기의 덫을 설치합니다.", zhCN = "放置一个冰霜陷阱，冻结第一个接近它的敌人，使其最多{1}秒内无法行动。", zhTW = "在地面上放置一個冰霜陷阱，將第一個接近的敵人凍結，使其無法採取任何行動，最多持續{1}秒。" }, "n" },
	{ "action active all any approaches break can caused damage enemy exist first freezes frost ice min one only place preventing sec time trap up will", { ko = "냉기의 덫을 설치합니다. 적이 다가오면 얼려서 최대 {1}초 동안 모든 행동을 불가능하게 만듭니다. 덫에 걸린 적이 피해를 입으면 효과가 풀립니다. 덫은 {2}분 동안 지속되며, 한 개만 놓아둘 수 있습니다.", zhCN = "放置一个冰霜陷阱，冻结第一个接近它的敌人，使其最多{1}秒内无法行动。造成任何伤害都会打破冰冻。陷阱会存在{2}分钟。同一时间只能激活一个冰霜陷阱。", zhTW = "在地面上放置一個冰霜陷阱，將第一個接近的敵人凍結，使其無法採取任何行動，最多持續{1}秒。任何傷害都會中斷冰凍效果。陷阱可存在{2}分鐘。同一時間內只能設置一個冰霜陷阱。" }, "n,n" },
	{ "ally holy place sec ward", { ko = "{1}초 동안 아군에게 신성한 수호를 겁니다.", zhCN = "为一名友方目标施加神圣结界，持续{1}秒。", zhTW = "為一名友方目標施加神聖結界，持續{1}秒。" }, "n" },
	{ "absorbing affected ally begin below contingency damage dropping gain healing health holy may next one only over place plan sec shield takes target their they time ward will", { ko = "{1}초 동안 아군에게 신성한 수호를 겁니다. 다음에 이 아군이 피해를 입어 생명력이 {2}% 아래로 떨어지면 {3}의 피해를 흡수하는 보호막을 얻고 {5}초에 걸쳐 {4}의 생명력을 회복하기 시작합니다. 대상 하나에는 비상 대책이 하나만 걸립니다.", zhCN = "为一名友方目标施加神圣结界，持续{1}秒。该目标下一次受到伤害导致生命值低于{2}%时，会获得一个可吸收{3}点伤害的护盾，并在{5}秒内恢复{4}点生命值。一个目标同一时间只能受到一个应急方案的影响。", zhTW = "為一名友方目標施加神聖結界，持續{1}秒。該目標下一次受到傷害導致生命力低於{2}%時，會獲得一個可吸收{3}點傷害的護盾，並在{5}秒內恢復{4}點生命力。一個目標同一時間只能受到一個應變計畫的影響。" }, "n,p,n,n,n" },
	{ "blessing effects friendly granting immunity impairing movement places sec target", { ko = "대상에게 자유의 축복을 걸어주어 {1}초 동안 이동 방해 효과에 면역이 되도록 합니다.", zhCN = "为友方目标施加祝福，使其免疫任何减缓移动速度的法术和技能效果，持续{1}秒。", zhTW = "為友方目標施加祝福，使其免疫任何減緩移動速度的法術和技能效果，持續{1}秒。" }, "n" },
	{ "any blessing effects friendly granting have immunity impairing may movement one only paladin per places players sec target them time", { ko = "대상에게 자유의 축복을 걸어주어 {1}초 동안 이동 방해 효과에 면역이 되도록 합니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其免疫任何减缓移动速度的法术和技能效果，持续{1}秒。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其免疫任何減緩移動速度的法術和技能效果，持續{1}秒。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "n" },
	{ "attack blessing friendly hr increasing melee places power target", { ko = "대상에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다.", zhCN = "为友方目标施加祝福，使其近战攻击强度提高{1}，持续{2}小时。", zhTW = "為友方目標施加祝福，使其近戰攻擊強度提高{1}，持續{2}小時。" }, "n,n" },
	{ "any attack blessing friendly have hr increasing may melee one only paladin per places players power target them time", { ko = "대상에게 힘의 축복을 걸어 {2}시간 동안 근접 전투력을 {1}만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其近战攻击强度提高{1}，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其近戰攻擊強度提高{1}，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "n,n" },
	{ "any blessing effect effects flash friendly have holy hr increasing lasts light may one only paladin per places players spells target them time up used", { ko = "대상에게 빛의 축복을 걸어 {3}시간 동안 성스러운 빛의 효과를 최대 {1}만큼, 빛의 섬광의 효과를 최대 60만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使圣光术为其恢复的生命值提高{1}点，圣光闪现为其恢复的生命值提高60点，持续{3}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使聖光術為其恢復的生命力提高{1}點，聖光閃現為其恢復的生命力提高60點，持續{3}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "n,n,n" },
	{ "blessing friendly hr increasing places stats target total", { ko = "파티원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다.", zhCN = "为友方目标施加祝福，使其所有属性提高{1}%，持续{2}小时。", zhTW = "為友方目標施加祝福，使其所有屬性提高{1}%，持續{2}小時。" }, "p,n" },
	{ "any blessing friendly have hr increasing may one only paladin per places players stats target them time total", { ko = "파티원에게 왕의 축복을 걸어 {2}시간 동안 모든 능력치를 {1}%만큼 증가시킵니다. 성기사마다 하나의 대상에게 하나의 축복만 효력을 발휘합니다.", zhCN = "为友方目标施加祝福，使其所有属性提高{1}%，持续{2}小时。每个圣骑士在同一时间内只能给目标施加一种祝福，同类型的祝福不能重叠。", zhTW = "為友方目標施加祝福，使其所有屬性提高{1}%，持續{2}小時。每個聖騎士在同一時間內只能給目標施加一種祝福，同類型的祝福不能重疊。" }, "p,n" },
