	{ "bag best hope reach", { ko = "가방에 손을 넣고 좋은 게 나오기를 바랍니다.", zhCN = "把手伸进袋子里，自求多福吧。", zhTW = "將手伸入袋子中，祈求最好的結果。" }, "" },
