	{ "body dead health life mana restoring returns spirit target", { ko = "죽은자의 영혼을 육체로 불러들여 {1}의 생명력과 {2}의 마나를 지닌채 살아나게 합니다.", zhCN = "让已死的目标复活，并恢复{1}点生命值和{2}点法力值。", zhTW = "讓已死的目標復活，並恢復{1}點生命力和{2}點法力。" }, "n,n" },
	{ "body cannot cast combat dead health life mana restoring returns spirit target when", { ko = "죽은자의 영혼을 육체로 불러들여 {1}의 생명력과 {2}의 마나를 지닌채 살아나게 합니다. 전투 중에는 사용할 수 없습니다.", zhCN = "让已死的目标复活，并恢复{1}点生命值和{2}点法力值。无法在战斗中施放。", zhTW = "讓已死的目標復活，並恢復{1}點生命力和{2}點法力。無法在戰鬥中施放。" }, "n,n" },
