	{ "cast destroyed each earth giving mana recall required returns totem totemic totems", { ko = "자신의 토템을 땅으로 돌려 보내고 토템의 귀환으로 파괴된 모든 토템 소환에 소비된 마나의 {1}%만큼을 되돌려 받습니다.", zhCN = "将你的图腾送回大地中，每个因收回而被摧毁的图腾都可以为你返还召唤该图腾所需法力值的{1}%。", zhTW = "將你的圖騰歸還大地，並使你獲得被召回圖騰所摧毀的每一根圖騰召喚時所需的{1}%法力。" }, "p" },
	{ "block dodge follow must parry revenge", { zhCN = "复仇只有在成功格挡、躲闪或招架之后才能使用。", zhTW = "復仇只有在成功格擋、躲閃或招架之後才能使用。" }, "" },
	{ "additional casting cost health increases mana pet pet's reduced returns revive sec time", { ko = "야수 되살리기의 시전 시간이 {1}초만큼 단축되며 소비되는 마나가 {2}%만큼 감소합니다. 또한 부활할 때 {3}%만큼 추가 생명력을 지닌 채로 부활합니다.", zhCN = "使你的复活宠物法术的施法时间减少{1}秒，法力值消耗降低{2}%，宠物复活后的生命值提高{3}%。", zhTW = "使你的復活寵物法術的施法時間減少{1}秒，法力消耗降低{2}%，寵物復活後的生命提高{3}%。" }, "n,p,p" },
	{ "health life pet returning revive", { ko = "야수를 {1}%의 생명력을 지닌 채로 되살아나게 합니다.", zhCN = "复活你的宠物，并为其回复{1}%的生命值。", zhTW = "復活你的寵物，並為其回復{1}%的生命力。" }, "p" },
	{ "click dismiss right robot summon", { ko = "애완용 로봇을 소환하거나 소환 해제합니다.", zhCN = "右键点击以召唤或解散你的机器人。", zhTW = "右鍵點擊以召喚或解散你的機器人。" }, "" },
	{ "asunder dimensional everlook rips transports walls winterspring", { zhCN = "穿透空间限制，将你传送到冬泉谷的永望镇。", zhTW = "穿透空間限制，將你傳送到冬泉谷的永望鎮。" }, "" },
	{ "about all asunder but dimensional engineering everlook goblin occur problems rips sometimes technical that's there transports walls what winterspring", { ko = "차원의 경계를 분할하여 여명의 설원에 있는 눈망루 마을로 순간이동합니다. 가끔 기술적인 오동작이 발생하곤 하지만. 그게 바로 고블린 기계공학이니까요.", zhCN = "穿透空间限制，将你传送到冬泉谷的永望镇。虽然有些时候可能会发生技术故障，但这难道不是地精工程学的最大亮点吗？", zhTW = "穿透空間限制，將你傳送到冬泉谷的永望鎮。雖然有些時候可能會發生技術故障，但這難道不是哥布林工程學的最大特點嗎？" }, "" },
	{ "asunder dimensional hyjal kaylaena's mount rips transports walls workshop", { ko = "차원의 벽을 찢고 하이잘 산에 있는 케이레나의 작업장으로 이동합니다.", zhCN = "撕裂空间位面，将你传送到海加尔山凯莱娜的工坊。", zhTW = "穿透空間限制，將你傳送到海加爾山的凱蕾娜的工作坊。" }, "" },
	{ "asunder chance combination dimensional engineering gnomish goblin have high hyjal kaylaena's mad mount occur problems rips technical transports walls workshop", { ko = "차원의 벽을 찢고 하이잘 산에 있는 케이레나의 작업장으로 이동합니다. 고블린과 노움 기계공학이 광기 어린 방식으로 결합된 장치인 터라, 기술적인 문제가 발생할 확률이 높습니다.", zhCN = "撕裂空间位面，将你传送到海加尔山凯莱娜的工坊。这种地精与侏儒工程学疯狂结合的产物有很高的几率发生技术故障。", zhTW = "穿透空間限制，將你傳送到海加爾山的凱蕾娜的工作坊。但作為哥布林和地精工程學的共同結晶，發生技術故障的機率極高。" }, "" },
	{ "causes damage nature over place roots sec target", { ko = "대상을 제자리에 묶어 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다.", zhCN = "将目标定身，并在{2}秒内对其造成总计{1}点自然伤害。", zhTW = "將目標固定在原地，並在{2}秒內對其造成總計{1}點自然傷害。" }, "n,n" },
	{ "caused causes damage effect have interrupt may nature only over place rooted roots sec target time", { ko = "대상을 제자리에 묶어 {2}초에 걸쳐 총 {1}의 자연 피해를 입힙니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 동시에 한 명의 대상을 이동 불가 상태로 만들 수 있습니다.", zhCN = "将目标定身，并在{2}秒内对其造成总计{1}点自然伤害。受到伤害可能会打断该效果。同一时间内，你可以定身仅{3}个目标。", zhTW = "將目標固定在原地，並在{2}秒內對其造成總計{1}點自然傷害。任何傷害都有可能終止此效果。你同一時間只能將{3}個目標定身。" }, "n,n,n" },
	{ "absorb damage giving owner sacrifices sec shield voidwalker will", { ko = "보이드워커를 희생하여 소환자를 {2}초 동안 {1}의 피해를 흡수하도록 만듭니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1}点伤害的防护盾，持续{2}秒。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1}點傷害的防護盾，持續{2}秒。" }, "n,n" },
	{ "absorb damage giving holds interrupted not owner sacrifices sec shield spellcasting voidwalker while will", { ko = "보이드워커를 희생하여 소환자를 {2}초 동안 {1}의 피해를 흡수하도록 만듭니다. 이 동안은 피해에 의해 주문 시전이 방해받지 않습니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1}点伤害的防护盾，持续{2}秒。在防护盾未消失之前，术士的施法过程不会被打断。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1}點傷害的防護盾，持續{2}秒。在防護盾未消失之前，術士的施法過程不會被打斷。" }, "n,n" },
	{ "absorb damage giving owner sacrifices sec shield voidwalker will", { ko = "보이드워커를 희생하여 소환자를 {3}초 동안 {1},{2}의 피해를 흡수하도록 만듭니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1},{2}点伤害的防护盾，持续{3}秒。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1},{2}點傷害的防護盾，持續{3}秒。" }, "n,n,n" },
	{ "absorb damage giving holds interrupted not owner sacrifices sec shield spellcasting voidwalker while will", { ko = "보이드워커를 희생하여 소환자를 {3}초 동안 {1},{2}의 피해를 흡수하도록 만듭니다. 이 동안은 피해에 의해 주문 시전이 방해받지 않습니다.", zhCN = "献祭虚空行者，使它的主人获得一层可以吸收{1},{2}点伤害的防护盾，持续{3}秒。在防护盾未消失之前，术士的施法过程不会被打断。", zhTW = "獻祭虛空行者，使它的主人獲得一層可以吸收{1},{2}點傷害的防護盾，持續{3}秒。在防護盾未消失之前，術士的施法過程不會被打斷。" }, "n,n,n" },
	{ "gadgetzan safely tanaris transport yourself", { ko = "타나리스 사막의 가젯잔으로 순간이동합니다.", zhCN = "将你安全地传送到塔纳利斯的加基森。", zhTW = "將你安全地傳送到塔納利斯的加基森。" }, "" },
