	{ "parts salvage shredder spare wreckage", { ko = "벌목기 잔해에서 쓸 만한 부품을 수습합니다.", zhCN = "回收伐木机残骸，获取备用零件。", zhTW = "回收伐木機殘骸以取得備用零件。" }, "" },
	{ "beast causing fear run scares sec up", { ko = "야수를 겁줘서 최대 {1}초 동안 달아나도록 만듭니다.", zhCN = "恐吓一头野兽，使其因恐慌而逃跑，最多持续{1}秒。", zhTW = "恐嚇一頭野獸，使其因恐慌而逃跑，最多持續{1}秒。" }, "n" },
