	{ "damage enemy fire scorch", { ko = "적을 불태워 {1}~{2}의 화염 피해를 입힙니다.", zhCN = "灼烧敌人，对其造成{1}至{2}点火焰伤害。", zhTW = "灼燒敵人，對其造成{1}至{2}點火焰傷害。" }, "n,n" },
	{ "actions all preventing sec seduces target up", { ko = "대상을 현혹하여 최대 {1}초 동안 어떤 행동도 하지 못하도록 만듭니다.", zhCN = "诱惑目标，使其在最多{1}秒内无法行动。", zhTW = "誘惑目標，使其在最多{1}秒內無法行動。" }, "n" },
