	{ "additional beast cannot causing damage does enraged fear feel killed not pet pity rage remorse sec send stopped unless while", { ko = "야수를 광폭하게 만들어 {2}초 동안 공격력을 {1}%만큼 증가시킵니다. 광포한 동안엔 어떠한 방법으로도 공격을 저지할 수 없습니다.", zhCN = "使宠物进入疯狂状态，对目标造成的伤害提高{1}%，持续{2}秒。在这种状态下，宠物不会有任何恐惧或怜悯，也无法停止下来，除非被杀死。", zhTW = "使你的寵物進入憤怒狀態，對目標造成的傷害提高{1}%，持續{2}秒。在這種狀態下，寵物不會有任何憐憫、自責或恐懼，也無法被阻止，除非被殺死。" }, "p,n" },
	{ "bolt causing damage enemy sends shadow shadowy", { ko = "적에게 어둠의 화살을 발사하여 {1}의 암흑 피해를 입힙니다.", zhCN = "向目标射出一支暗影箭，对其造成{1}点暗影伤害。", zhTW = "向目標射出一支暗影箭，對其造成{1}點暗影傷害。" }, "n" },
