	{ "enemy sec shackles target undead up", { ko = "최대 {1}초 동안 대상 언데드를 속박시킵니다.", zhCN = "束缚敌对亡灵单位，最多持续{1}秒。", zhTW = "束縛敵對不死族單位，最多持續{1}秒。" }, "n" },
	{ "any attack can cast caused damage enemy move one only release sec shackled shackles spells target time unable undead unit up will", { ko = "최대 {1}초 동안 대상 언데드를 속박시킵니다. 속박된 대상은 이동하거나 공격, 주문 시전이 불가능합니다. 대상은 피해를 입으면 해제됩니다. 한 번에 하나의 대상만 속박할 수 있습니다.", zhCN = "束缚敌对亡灵单位，最多持续{1}秒。被束缚的亡灵无法移动、攻击或施法。任何对其造成伤害的行为都将解除束缚。一个牧师在同一时间内只能束缚一个目标。", zhTW = "束縛敵對不死族單位，最多持續{1}秒。被束縛的不死族無法移動、攻擊或施法。任何對其造成傷害的行為都將解除束縛。一個牧師在同一時間內只能束縛一個目標。" }, "n" },
