	{ "damage done increases incubus shadow succubus", { ko = "서큐버스/인큐버스 - 암흑 공격력이 {1}%만큼 증가합니다.", zhCN = "魅魔/夜魔 - 暗影伤害提高{1}%。", zhTW = "魅魔/夢魔 - 造成的暗影傷害提高{1}%。" }, "p" },
	{ "damage fire increases incubus succubus", { ko = "서큐버스/인큐버스: 화염 공격력이 {1}%만큼 증가합니다.", zhCN = "魅魔/夜魔：使你的火焰伤害提高{1}%。", zhTW = "魅魔/夢魔：使你的火焰傷害提高{1}%。" }, "p" },
