	{ "air caster feet health summons totem tranquil", { zhCN = "在施法者身边召唤一个生命值为{1}点的宁静之风图腾。", zhTW = "在施法者身邊召喚一個生命力為{1}點的寧靜之風圖騰。" }, "n" },
