	{ "damage increasing min physical taken target tenderize", { ko = "대상을 연하게 만들어 {1}분 동안 받는 물리 피해를 {2}만큼 증가시킵니다.", zhCN = "软化目标，使其受到的物理伤害提高{1}点，持续{2}分钟。", zhTW = "使目標變得軟嫩，受到的物理傷害提高{1}點，持續{2}分鐘。" }, "n,n" },
	{ "act caster effects frees impairing movement polymorph shapeshifting", { ko = "변신을 하게 되면 변이와 이동 방해 효과에서 벗어날 수 있습니다.", zhCN = "变形可解除施法者身上的变形术和移动限制效果。", zhTW = "變形可解除施法者身上的變形術和移動限制效果。" }, "" },
	{ "amount applied down duration first full growth healed quickly reaches slows wild", { ko = "처음에는 회복 속도가 빠르지만 시간이 지날수록 점차 느려집니다.", zhTW = "野性痊癒的恢復速度在起步時最快，並且隨時間而減緩，直到結束為止。" }, "" },
