	{ "ghost increasing only outdoors shaman speed turns useable wolf", { ko = "주술사의 모습을 늑대 정령으로 바꿉니다. 이동 속도가 {1}%만큼 증가합니다. 야외에서만 사용할 수 있습니다.", zhCN = "将萨满祭司变成一头幽魂之狼，移动速度提高{1}%。只能在户外使用。", zhTW = "將薩滿變成一頭鬼魂之狼，移動速度提高{1}%。只能在戶外使用。" }, "p" },
	{ "chicken sec target turns", { ko = "{1}초 동안 대상을 닭으로 변신시킵니다.", zhCN = "将目标变成一只小鸡，持续{1}秒。", zhTW = "將目標變成雞，持續{1}秒。" }, "n" },
	{ "assuming been chicken has not polarity reversed sec target transmogrification turns well", { ko = "{1}초 동안 대상을 닭으로 변신시킵니다. 변이 과정이 역전되는 일은 아직까지는 발생하지 않았습니다.", zhCN = "将目标变成一只小鸡，持续{1}秒。当然，前提是幻化极性没有反转……", zhTW = "將目標變成雞，持續{1}秒。嗯，假設變形術的極性沒有被反轉…" }, "n" },
	{ "breath lasts longer normal than underwater", { ko = "수중에서 다른 종족의 {1}%만큼 호흡을 오래 유지할 수 있습니다.", zhCN = "水下呼吸的时间延长{1}%。", zhTW = "在水下呼吸的時間延長{1}%。" }, "p" },
	{ "belch cone damage dealing dragonfire fire front instantly narrow unleash", { ko = "전방 좁은 부채꼴 범위로 용의 불꽃을 내뿜어 즉시 {1}의 화염 피해를 입힙니다.", zhCN = "喷出一口龙火，立即对前方狭窄锥形范围内的敌人造成{1}点火焰伤害。", zhTW = "吐出一團龍火，立刻在你面前的狹窄錐形範圍內造成{1}點火焰傷害。" }, "n" },
	{ "additional affected belch cone damage dealing dragonfire every fire front instantly narrow sec suffer targets unleash will", { ko = "전방 좁은 부채꼴 범위로 용의 불꽃을 내뿜어 즉시 {1}의 화염 피해를 입힙니다. 영향을 받는 대상은 {4}초 동안 {3}초마다 {2}의 추가 피해를 받습니다.", zhCN = "喷出一口龙火，立即对前方狭窄锥形范围内的敌人造成{1}点火焰伤害。受影响的目标每{3}秒额外受到{2}点伤害，持续{4}秒。", zhTW = "吐出一團龍火，立刻在你面前的狹窄錐形範圍內造成{1}點火焰傷害。受影響的目標每{3}秒額外受到{2}點傷害，持續{4}秒。" }, "n,n,n,n" },
	{ "enemy energy seal spell unleash upon", { ko = "문장의 에너지를 적에게 폭발시킵니다.", zhCN = "对敌人释放圣印法术的能量。", zhTW = "將聖印法術的能量釋放到敵人身上。" }, "" },
	{ "consume does effect enemy energy individual judgement not refer seal seals spell unleash upon", { ko = "문장의 에너지를 적에게 폭발시킵니다. 문장을 소모하지 않습니다. 효과는 문장에 따라 달라집니다.", zhCN = "对敌人释放圣印法术的能量。不会消耗圣印。有关审判效果，请参阅各个圣印的说明。", zhTW = "將聖印法術的能量釋放到敵人身上。不會消耗聖印。請參閱每種聖印的審判效果說明。" }, "" },
	{ "attack causes damage enemy energy holy seal's sec target taunts unleashing", { ko = "문장의 에너지를 폭발시키면 적에게 {1}~{2}의 신성 피해를 입히고 대상을 도발해 {3}초 동안 자신을 공격하게 합니다.", zhCN = "释放此圣印的能量会对一名敌人造成{1}至{2}点神圣伤害，并嘲讽该目标攻击你，持续{3}秒。", zhTW = "釋放這種聖印的能量會對敵人造成{1}至{2}點神聖傷害，並嘲諷目標，使其向你發起攻擊，持續{3}秒。" }, "n,n,n" },
	{ "attack damage enemy energy holy inflicts seal's sec target taunts unleashing", { ko = "문장의 에너지를 적에게 폭발시키면 {1}~{2}의 신성 피해를 입히고 {3}초 동안 대상이 자신을 공격하도록 도발합니다." }, "n,n,n" },
	{ "attack damage enemy energy holy inflicts seal's sec target taunts unleashing", { ko = "문장의 에너지를 적에게 폭발시키면 {1}~{2}의 신성 피해를 입히고 {3}초 동안 대상이 자신을 공격하도록 도발합니다." }, "n,n,n" },
	{ "cause damage enemy energy holy seal's unleashing will", { ko = "문장의 에너지를 폭발시키면 적에게 {1}~{2}의 신성 피해를 입힙니다.", zhCN = "释放这种圣印的能量将对目标造成{1}至{2}点神圣伤害。", zhTW = "釋放這種聖印的能量將對目標造成{1}至{2}點神聖傷害。" }, "n,n" },
	{ "against attacker attacks chance enemy energy granting judge judged mana restore seal's sec spells unleashing used will", { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" }, "n,n" },
	{ "active against any attacker attacks can chance duration enemy energy granting judge judged judgement mana melee one only paladin per refresh restore seal's sec spell's spells strikes time unleashing used will", { ko = "문장의 에너지를 폭발시키면 {1}초 동안 해당 적에 심판을 내립니다. 심판이 내려진 적을 공격하는 이는 일정 확률로 {2}의 마나가 회복됩니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。如果被审判的目标受到了武器和法术攻击，攻击者就有一定几率恢复{2}点法力值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。如果被審判的目標受到了武器或法術攻擊，攻擊者就有一定機率恢復{2}點法力。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" }, "n,n" },
	{ "against attacker attacks chance enemy energy granting healing judge judged made melee seal's sec unleashing will", { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" }, "n,n" },
	{ "active against any attacker attacks can chance duration enemy energy granting healing judge judged judgement made melee one only paladin per refresh seal's sec spell's strikes time unleashing will", { ko = "문장의 에너지를 폭발시키면 {1}초 동안 해당 적에 심판을 내립니다. 심판이 내려진 적을 공격하는 이는 일정 확률로 25의 생명력이 회복됩니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。使用近战武器击中被审判的目标就有一定几率令攻击者回复25点生命值。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。使用近戰武器擊中被審判的目標就有一定機率令攻擊者回復25點生命力。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" }, "n,n" },
	{ "damage enemy energy holy increasing judge seal's sec taken unleashing up will", { ko = "문장의 에너지를 적에게 폭발시키면 {1}초 동안 적이 입는 신성 피해가 {2}까지 증가합니다." }, "n,n" },
	{ "active any can damage duration enemy energy holy increasing judge judgement melee one only paladin per refresh seal's sec spell's strikes taken time unleashing up will", { ko = "문장의 에너지를 적에게 폭발시키면 {1}초 동안 적이 입는 신성 피해가 23까지 증가합니다. 매번 공격 시 주문의 지속시간이 초기화됩니다. 성기사마다 하나의 심판만 효력을 발휘합니다.", zhCN = "释放这种圣印的能量将对目标造成审判效果，持续{1}秒。神圣系的伤害性法术对被审判的目标造成最多23点额外的神圣伤害。你的近战攻击将使得该法术的持续时间延长。每个圣骑士在同一时间内只能给目标施加一种审判效果，同类型的审判不能重叠。", zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。神聖系的傷害性法術對被審判的目標造成最多23額外的神聖傷害。你的近戰打擊會更新法術的持續時間。每個聖騎士在同一時間內只能給目標施加一種審判效果，同類型的審判不能重疊。" }, "n,n" },
	{ "enemy energy fleeing judge preventing seal's sec them unleashing will", { zhTW = "釋放這種聖印的能量將對目標造成審判效果，持續{1}秒。" }, "n" },
