	{ "alliance allows banner divine exclusive gain increased members mutually nearby other sitting spirit unrolls", { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 얼라이언스 구성원의 정신력을 {1}만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他联盟成员的精神提高{1}。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他聯盟成員的精神提高{1}。與神聖之靈互斥。" }, "n" },
	{ "above allows banner below divine exclusive gain horde increased members mutually nearby other sitting spirit unrolls", { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 호드 구성원의 정신력을 {1}({2}레벨 미만) · {3}({4}레벨 미만) · {5}({6}레벨 미만) · {7}(그 위)만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他部落成员的精神提高{1}（{2}级以下） · {3}（{4}级以下） · {5}（{6}级以下） · {7}（更高）。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他部落成員的精神提高{1}（{2}級以下） · {3}（{4}級以下） · {5}（{6}級以下） · {7}（更高）。與神聖之靈互斥。" }, "n,n,n,n,n,n,n" },
	{ "allows banner divine exclusive gain horde increased members mutually nearby other sitting spirit unrolls", { ko = "깃발을 펼쳐 자신과 주위에 앉은 다른 호드 구성원의 정신력을 {1}만큼 증가시킵니다. 천상의 정신과 겸용해서 사용할 수 없습니다.", zhCN = "展开一面旗帜，使你和附近坐着的其他部落成员的精神提高{1}。与神圣之灵互斥。", zhTW = "展開一面旗幟，使你和附近坐著的其他部落成員的精神提高{1}。與神聖之靈互斥。" }, "n" },
	{ "becomes death priest redemption sec spirit upon", { ko = "사제가 생명력을 모두 잃으면 {1}초 동안 구원의 영혼으로 변합니다.", zhCN = "在死亡时，牧师变成一个救赎之魂，持续{1}秒。", zhTW = "死亡之時，牧師變為救贖之魂，持續{1}秒。" }, "n" },
	{ "any attack attacked becomes can cannot cast cost death dies effect effects ends form free healing move priest redemption sec spell spells spirit targeted upon when while", { ko = "사제가 생명력을 모두 잃으면 {1}초 동안 구원의 영혼으로 변합니다. 구원의 영혼은 이동하거나 공격하거나 공격받거나 어떠한 주문이나 효과의 대상이 될 수 없습니다. 이 형태에서는 모든 치유 주문을 마나 소비 없이 사용할 수 있습니다. 효과가 종료되면 사제는 죽습니다.", zhCN = "在死亡时，牧师变成一个救赎之魂，持续{1}秒。救赎之魂无法移动、攻击，也不会受到任何法术或效果的影响。在这个形态下，牧师可以施放任何治疗法术，不需消耗任何法力值。当救赎之魂效果结束时，牧师死亡。", zhTW = "死亡之時，牧師變為救贖之魂，持續{1}秒。救贖之魂無法移動、攻擊，且不受任何法術或效果攻擊或鎖定。進入此形態，牧師可不消耗能量施放任何治療法術。效果結束後，牧師就會死亡。" }, "n" },
	{ "cemetery graveyard hill monastery raven scarlet usable", { ko = "까마귀 언덕 묘지와 붉은십자군 수도원 묘지에서 사용할 수 있습니다." }, "" },
	{ "better close food have level pet's result using will", { ko = "야수의 레벨에 맞는 먹이를 주면 더 효과가 좋습니다." }, "" },
	{ "damage nature shot target venom", { ko = "대상에게 맹독 화살을 날려 {1}의 자연 피해를 입힙니다.", zhCN = "向目标发射毒箭，造成{1}点自然伤害。", zhTW = "對目標施放毒液射擊，造成{1}點自然傷害。" }, "n" },
	{ "blood damage deals dose expires nature per venomous when", { ko = "맹독성 피는 만료될 때 중첩 하나당 {1}의 자연 피해를 입힙니다.", zhCN = "当毒血效果结束时，每层会造成{1}点自然伤害。", zhTW = "效果結束後，每層毒血造成{1}點自然傷害。" }, "n" },
	{ "damage physical reduces taken voidwalker", { ko = "보이드워커 - 받는 물리 피해가 {1}%만큼 감소합니다.", zhCN = "虚空行者 - 受到的物理伤害降低{1}%。", zhTW = "虛無行者 - 所承受的物理傷害降低{1}%。" }, "p" },
	{ "every mana restores sec total voidwalker", { ko = "보이드워커: {2}초마다 전체 마나의 {1}%에 해당하는 마나를 회복합니다.", zhCN = "虚空行者：每{2}秒恢复总法力值的{1}%。", zhTW = "虛無行者：使你每{2}秒恢復{1}%法力上限。" }, "p,n" },
	{ "against fear friendly target wards", { ko = "대상을 공포로부터 보호합니다.", zhCN = "使友方目标获得抵抗恐惧的结界。", zhTW = "使友方目標獲得抵抗恐懼的結界。" }, "" },
	{ "against effect fail fear friendly lasts min next target up used using ward wards will", { ko = "대상을 공포로부터 보호합니다. 해당 대상에게 적용되는 다음 공포 효과는 실패하게 됩니다. {1}분 동안 지속됩니다.", zhCN = "使友方目标获得抵抗恐惧的结界。下一次对该目标施放的恐惧效果会失败并消耗结界。结界持续{1}分钟。", zhTW = "使友方目標獲得抵抗恐懼的結界。下一次對該目標施放的恐懼效果會失敗並消耗結界。結界持續{1}分鐘。" }, "n" },
	{ "any attack effectiveness enemy healing melee power reducing target weakens", { zhCN = "削弱目标敌人，使其近战攻击强度降低{1}点，并使其受到的任何治疗效果降低{2}%。" }, "n,p" },
	{ "any attack effectiveness enemy healing lasts melee min power reducing target weakens", { ko = "적을 약화시켜 {3}분 동안 근접 전투력을 {1}만큼 감소시키고 해당 대상이 받는 치유 효과를 {2}%만큼 감소시킵니다.", zhCN = "削弱目标敌人，使其近战攻击强度降低{1}点，并使其受到的任何治疗效果降低{2}%。持续{3}分钟。", zhTW = "削弱目標，使其近戰攻擊強度降低{1}點，並使任何形式的治療對其產生的效果降低{2}%，持續{3}分鐘。" }, "n,p,n" },
	{ "assuming been has not polarity reversed transmogrification well", { ko = "변이 과정이 역전되는 일은 아직까지는 발생하지 않았습니다.", zhCN = "当然，前提是幻化极性没有反转……", zhTW = "嗯，假設變形術的極性沒有被反轉…" }, "" },
	{ "attack attacker caster damage hits melee nature ranged spell struck when will", { ko = "만약 시전자에게 주문이나 근접 또는 원거리 공격을 시도할 경우 공격자는 {1}의 자연 피해를 입게 됩니다." }, "n" },
	{ "attack attacker caster damage hits melee ranged shadow spell struck when will", { ko = "주문이나 근접 또는 원거리 공격을 받게 되면 공격자는 {1}의 암흑 피해를 입게 됩니다.", zhCN = "如果施法者受到了法术、近战或远程伤害，则攻击者会受到{1}点暗影伤害。", zhTW = "如果施法者受到了近戰或遠程傷害，則攻擊者會受到{1}點暗影傷害。" }, "n" },
	{ "attack caster caster's critical expending gets globe healing hits mana maximum melee one ranged restored result spell spells water when", { zhCN = "当法术、近战或远程攻击命中施法者，或施法者的治疗法术造成爆击时，恢复最大法力值的{1}%，并消耗一个水球。" }, "p" },
	{ "activated chance critical effect flash gives holy light next shock spell when", { ko = "활성화되면 다음 빛의 섬광, 성스러운 빛, 신성 충격 주문이 {1}%의 확률로 극대화 효과를 발휘합니다.", zhCN = "激活之后，使你的下一个圣光闪现、圣光术或神圣震击有{1}%的几率造成极效治疗效果。", zhTW = "啟動之後，使你的下一個聖光閃現，聖光術或神聖震擊的治療法術有{1}%的機率造成極效治療。" }, "p" },
	{ "activated ambush backstab chance critical eviscerate increases mutilate next sinister strike when", { ko = "활성화 시 다음 사악한 일격, 기습, 매복, 절개 또는 절단의 치명타 및 극대화율이 {1}%만큼 증가합니다.", zhCN = "激活后，使你的下一次邪恶攻击、背刺、伏击、刺骨或毁伤的爆击几率提高{1}%。", zhTW = "啟動之後，你的下一次邪惡攻擊、背刺、伏擊、剔骨或截肢造成致命一擊的機率提高{1}%。" }, "p" },
	{ "activated chance dodge increases parry sec when", { ko = "활성화되면 {2}초 동안 회피와 무기 막기 확률이 {1}%만큼 증가합니다.", zhCN = "激活之后，使你的躲闪和招架几率提高{1}%，持续{2}秒。", zhTW = "啟動之後，使你的躲閃和招架機率提高{1}%，持續{2}秒。" }, "p,n" },
	{ "activated all but damage done effects fear immune increases makes physical take when", { ko = "활성화 시 물리 공격력이 {1}%만큼 증가하고 공포 효과에 면역이 되지만, 받는 모든 피해가 {2}%만큼 증가합니다.", zhCN = "激活后，你造成的物理伤害提高{1}%，并免疫恐惧效果，但受到的所有伤害提高{2}%。" }, "p,p" },
	{ "activated all but damage done effects fear immune increases lasts makes physical sec take when", { ko = "활성화 시 물리 공격력이 {1}%만큼 증가하고 공포 효과에 면역이 되지만, 받는 모든 피해가 {2}%만큼 증가합니다. {3}초 동안 지속됩니다.", zhCN = "激活后，你造成的物理伤害提高{1}%，并免疫恐惧效果，但受到的所有伤害提高{2}%。持续{3}秒。", zhTW = "啟動之後，你造成的物理傷害提高{1}%，並免疫恐懼效果，但你受到的所有傷害提高{2}%，持續{3}秒。" }, "p,p,n" },
	{ "activated capable chance cost critical effect if increases mana next non periodic reduces spell when", { ko = "활성화되면 다음 주문에 소비되는 마나를 {1}%만큼 감소시키고, 그 주문이 주기 효과가 아니고 극대화 효과를 낼 수 있는 주문이면 극대화 확률이 {2}%만큼 증가합니다.", zhCN = "激活之后，你的下一个法术所消耗的法力值减少{1}%，造成爆击或极效治疗的几率提高{2}%（如果它有可能造成这些效果的话）。", zhTW = "啟用之後，你的下一個法術所消耗的法力減少{1}%，造成致命一擊或極效治療的機率提高{2}%（如果它有可能造成這些效果的話）。" }, "p,p" },
	{ "activated aspect demon effect enhance granting hr lasts opposing power sacrifices summoned when", { ko = "활성화되면 소환된 악마를 제물로 바쳐 힘의 반대되는 측면을 강화합니다.", zhCN = "激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续{1}小时的效果。", zhTW = "啟動之後，犧牲你目前所召喚的惡魔，強化你力量的相反層面，使你獲得一種特殊效果，持續{1}小時。" }, "n" },
	{ "activated any aspect canceled demon effect enhance granting hr if lasts opposing power sacrifices summoned when", { ko = "활성화되면 소환된 악마를 제물로 바쳐 힘의 반대되는 측면을 강화합니다. 이 효과는 {1}시간 동안 지속되며 소환수를 소환하면 사라집니다.", zhCN = "激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续{1}小时的效果。如果召唤任何恶魔，该效果会被取消。", zhTW = "啟動之後，犧牲你目前所召喚的惡魔，強化你力量的相反層面，使你獲得一種特殊效果，持續{1}小時。如果在此期間你召喚任意一個惡魔，該效果就會被取消。" }, "n" },
	{ "ability absorb activated equal grants health maximum sec shield when", { ko = "이 능력을 활성화하면 {2}초 동안 최대 생명력의 {1}%에 해당하는 피해를 흡수하는 보호막을 얻습니다.", zhCN = "激活后，获得相当于你最大生命值{1}%的吸收护盾，持续{2}秒。", zhTW = "啟用後，獲得相當於你最大生命力{1}%的吸收護盾，持續{2}秒。" }, "p,n" },
	{ "ability absorb activated active applies cannot cast equal forbearance grants health maximum min sec shield when while", { ko = "이 능력을 활성화하면 {2}초 동안 최대 생명력의 {1}%에 해당하는 피해를 흡수하는 보호막을 얻습니다. {3}분 동안 참을성이 부여됩니다. 참을성이 활성화된 동안에는 시전할 수 없습니다.", zhCN = "激活后，获得相当于你最大生命值{1}%的吸收护盾，持续{2}秒。施加自律，持续{3}分钟。自律效果激活时无法施放。", zhTW = "啟用後，獲得相當於你最大生命力{1}%的吸收護盾，持續{2}秒。施加自律，持續{3}分鐘。自律效果啟用時無法施放。" }, "p,n,n" },
	{ "abilities ability activated cooldown finishes immediately other rogue when", { ko = "활성화되면 다른 모든 도적 기술들의 재사용 대기시간이 초기화됩니다.", zhCN = "激活之后，这项技能立刻令你的其它潜行者技能的冷却时间结束。", zhTW = "啟動之後，這項技能立刻令你的其他盜賊技能的冷卻時間結束。" }, "" },
	{ "ability activated grants health maximum sec temporarily when", { ko = "활성화 시 일시적으로 최대 생명력이 {1}%만큼 증가합니다.", zhCN = "激活后，该技能会使你暂时获得相当于最大生命值{1}%的生命值，持续{2}秒。", zhTW = "啟動之後，使你的生命力上限暫時提高{1}%，持續{2}秒。" }, "p,n" },
	{ "ability activated after effect expires grants health lost maximum sec temporarily when", { ko = "활성화 시 일시적으로 최대 생명력이 {1}%만큼 증가합니다. {2}초 동안 지속되며 지속시간이 끝나면 임시 생명력은 사라집니다.", zhCN = "激活后，该技能会使你暂时获得相当于最大生命值{1}%的生命值，持续{2}秒。效果结束后会失去这些生命值。", zhTW = "啟動之後，使你的生命力上限暫時提高{1}%，持續{2}秒。效果結束後，這些生命力會被扣除。" }, "p,n" },
