	{ "all amount chance damaged enemies has level reduce sec small threat when", { ko = "피해를 받으면 일정 확률로 {1}초 동안 모든 적에 대한 위협 수준 약간 감소합니다.", zhCN = "在受到伤害时，有一定几率小幅降低所有敌人的威胁值，持续{1}秒。", zhTW = "受到傷害時，有一定機率使你對所有敵人的威脅等級略微降低，持續{1}秒。" }, "n" },
	{ "above absorbed attacker fully fury's increased level mana per restore seal shield up when", { ko = "격노의 문장의 보호막이 완전히 흡수되면 {1}의 마나를 회복합니다. 회복량은 공격자가 자신보다 레벨이 높은 경우 1 레벨당 {2}%씩, 최대 {3}%까지 증가합니다.", zhCN = "愤怒圣印提供的护盾被完全吸收时，恢复{1}点法力值。攻击者每比你高一级，恢复量提高{2}%，最高提高{3}%。", zhTW = "當憤怒聖印的護盾被完全消耗時，恢復{1}點法力。攻擊者每高於你1級，法力恢復量便提高{2}%，最多提高{3}%。" }, "n,p,p" },
	{ "attacker chance combat damage has inflicting nature struck when", { ko = "가격당했을 때 {1}%의 확률로 공격자에게 {2}의 자연 피해를 입힙니다.", zhCN = "在战斗中被击中时，有{1}%的几率对攻击者造成{2}点自然伤害。", zhTW = "在戰鬥中被擊中之後，有{1}%的機率對攻擊者造成{2}點自然傷害。" }, "p,n" },
	{ "attacker chance combat damage has inflicting shadow struck when", { ko = "가격 당했을 때 {1}%의 확률로 공격자에게 {2}의 암흑 피해를 입힙니다.", zhCN = "在战斗中被敌人击中之后，有{1}%的机会对攻击者造成{2}点暗影伤害。", zhTW = "在戰鬥中被敵人擊中之後，有{1}%的機會對攻擊者造成{2}點暗影傷害。" }, "p,n" },
	{ "attacker combat damage inflicts shadow struck when", { ko = "전투 중 공격을 받으면 공격자에게 {1}의 암흑 피해를 입힙니다.", zhCN = "在战斗中被击中时，对攻击者造成{1}点暗影伤害。", zhTW = "在戰鬥中被擊中之後，對攻擊者造成{1}點暗影傷害。" }, "n" },
