	{ "attack attacker felhunter hit lose melee power sec when will", { ko = "지옥사냥개가 근접 공격을 받으면 공격자는 {2}초 동안 {1}의 근접 전투력을 상실합니다.", zhCN = "如果它被近战攻击打中，则攻击者会损失{1}点近战攻击强度，持续{2}秒。", zhTW = "如果它被近戰攻擊打中，則攻擊者會損失{1}近戰攻擊強度，持續{2}秒。" }, "n,n" },
	{ "heal jumps member mending occurs party prayer raid when within yards", { ko = "생명력이 회복되면 {1}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다.", zhCN = "这个治疗效果发生之后，愈合祷言会转移到{1}码范围内的小队或团队成员身上。", zhTW = "當治療效果發動時，癒合禱言將會跳至半徑{1}碼範圍內的一名小隊或團隊成員身上。" }, "n" },
	{ "heal jumps member mending occurs party prayer raid when within yds", { ko = "생명력이 회복되면 {1}미터 반경 내의 파티원 혹은 공격대원에게 회복의 기원이 전달됩니다." }, "n" },
	{ "causes damage nature over sec sting target up wakes when", { zhCN = "当目标醒来时，钉刺会在{2}秒内对其造成{1}点自然伤害。", zhTW = "當目標醒來時，釘刺會在{2}秒內對其造成{1}點自然傷害。" }, "n,n" },
	{ "base cast cost different equal gain heal healing if mana previous spell was when", { ko = "치유 주문을 시전할 때, 이전에 다른 주문으로 치유한 경우 이번 치유 주문의 기본 마나 소비량의 {1}%에 해당하는 마나를 회복합니다.", zhCN = "当你施放治疗法术时，若你上一次施放的是不同的治疗法术，则获得相当于本次法术基础法力消耗{1}%的法力值。", zhTW = "施放治療法術時，若此法術與你施放的上一個治療法術不同，則獲得相當於此法術基本法力消耗{1}%的法力。" }, "p" },
	{ "below bolt cast costs damage deal enemy fire has health increased next no pain reduced searing sec shadow shards soul spell they time when", { ko = "생명력이 {1}% 미만인 적에게 어둠의 화살 또는 불타는 고통을 시전하면 {2}%의 추가 피해를 입히며, 다음 {3}초 동안 영혼의 불꽃의 시전 시간이 {4}%만큼 감소하고 영혼의 조각을 소모하지 않습니다.", zhCN = "当你对生命值低于{1}%的敌人施放暗影箭或灼热之痛时，这些法术造成的伤害提高{2}%，并且在接下来的{3}秒内，你的灵魂之火施法时间缩短{4}%，且不消耗灵魂碎片。", zhTW = "當你對生命力低於{1}%的敵人施放暗影箭或灼熱之痛時，其造成的傷害提高{2}%，同時在接下來的{3}秒內，你靈魂之火法術的施法時間縮短{4}%，且不消耗靈魂裂片。" }, "p,p,n,p" },
	{ "attack bolt cast chance cost damage deal have lightning mana melee next reduce spell time when", { ko = "근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살의 시전 시간과 마나 소모량이 {1}%만큼 감소합니다.", zhCN = "近战攻击造成伤害时，你有几率使下一个闪电箭的施法时间和法力消耗降低{1}%。" }, "p" },
	{ "attack bolt cast chance cost damage deal have lasts lightning mana melee next reduce sec spell stacks time times up when", { ko = "근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살의 시전 시간과 마나 소모량이 {1}%만큼 감소합니다. 최대 {2}번까지 중첩됩니다. {3}초 동안 지속됩니다.", zhCN = "近战攻击造成伤害时，你有几率使下一个闪电箭的施法时间和法力消耗降低{1}%。最多叠加{2}次。持续{3}秒。", zhTW = "當你的近戰攻擊造成傷害時，你有一定的機率使你的下一個閃電箭的施法時間與法力消耗降低{1}%。最多可堆疊{2}次，持續{3}秒。" }, "p,n,n" },
	{ "demon gain gains life mana summoned tap when", { ko = "생명력 전환으로 마나를 회복하면, 소환된 악마가 회복한 마나의 {1}%를 얻습니다.", zhCN = "通过生命分流获得法力时，召唤的恶魔会获得相当于你所得法力{1}%的法力。", zhTW = "當你從生命分流獲得法力時，你召喚的惡魔將得到相當於你獲得{1}%的法力。" }, "p" },
	{ "bear cat dire each energy form had last maximum not plus regain second shift spent up were when will", { ko = "또한 표범 변신 시 지난 표범 변신 상태일 때 보유했던 기력의 {1}%를 다시 회복하며, 추가로 곰 변신이나 표범 변신, 광포한 곰 변신 상태가 아니었던 시간 1초당 기력을 {2}만큼, 최대 {3}만큼 생성합니다.", zhCN = "当你变身为猎豹形态时，将恢复上次处于猎豹形态时所拥有能量的{1}%，外加你在未处于熊形态、猎豹形态或巨熊形态的每秒{2}点能量，最多{3}点能量。", zhTW = "當你變身為獵豹形態時，將恢復上次處於獵豹形態時所擁有能量的{1}%，外加你在未處於熊形態、獵豹形態或巨熊形態的每秒{2}點能量，最多{3}點能量。" }, "p,n,n" },
	{ "casting chance cooldown dodge each gain has have mana parry regeneration reset sec spells stormstrike stormstrike's time when while", { ko = "폭풍의 일격 사용 시 {1}%의 확률로 {3}초 동안 주문을 시전할 때 마나 회복 속도가 {2}%만큼 증가합니다. 또한 공격을 회피하거나 무기로 막을 때마다 {4}%의 확률로 폭풍의 일격의 재사용 대기시간이 초기화됩니다.", zhCN = "使用风暴打击时，你有{1}%的几率获得{2}%的施法时法力回复，持续{3}秒；每当你躲闪或招架时，风暴打击的冷却时间有{4}%的几率重置。", zhTW = "施放風暴打擊時，你有{1}%的機率在施放法術時獲得你{2}%法力恢復速度的法力，持續{3}秒，且每次你閃躲或招架時，有{4}%的機率重置風暴打擊的冷卻時間。" }, "p,p,n,p" },
	{ "ability backstab cost damage deals energy hemorrhage next periodic reduced rupture sec stacking times up when within", { ko = "파열로 주기적인 피해를 입히면 {1}초 안에 사용하는 다음 과다출혈 또는 기습의 기력 소모량이 {2}만큼 감소합니다. 최대 {3}번까지 중첩됩니다.", zhCN = "当你的割裂造成周期性伤害时，使你在{1}秒内下一次出血或背刺消耗的能量值降低{2}点，最多叠加{3}次。", zhTW = "當你的割裂技能造成週期性傷害，你在{1}秒內施放的下一個出血或背刺技能的能量消耗降低{2}點，最多可堆疊{3}層。" }, "n,n,n" },
	{ "affected all entrapped moving preventing sec targets them traps triggered when", { ko = "덫 발동 시 영향을 받는 모든 대상이 덫에 걸림 상태가 되어 {1}초 동안 이동하지 못하게 됩니다.", zhCN = "当你的陷阱被触发时，所有受影响的目标被诱捕，无法移动，持续{1}秒。", zhTW = "當你的陷阱觸發時，所有受影響目標都會被困住，令其無法移動，持續{1}秒。" }, "n" },
	{ "bleed damage dose enemy nearby one spread suffer whenever within yds", { ko = "출혈 피해를 받을 때마다 {1}미터 내의 주위 적에게 맹독성 피를 1회 살포합니다.", zhCN = "每当你受到流血伤害时，就会有一层毒血传播给{1}码内的一名附近敌人。", zhTW = "每當你受到流血傷害時，會將一層效果濺射至附近{1}碼範圍內的一個敵人。" }, "n" },
