	{ "cast earthbind immobilizes nearby sec targets totem when", { ko = "속박의 토템 시전 시 주위 대상을 {1}초 동안 이동 불가 상태로 만듭니다.", zhCN = "施放地缚图腾时，使附近目标无法移动{1}秒。", zhTW = "施放地縛圖騰時，會使附近目標無法移動，持續{1}秒。" }, "n" },
	{ "abilities attacks berserker bloodrage bloodthirst cause death enrage health maximum melee next rage restore wish", { ko = "격노, 광전사의 격노, 피의 분노, 죽음의 소원, 피의 갈증이 발동하면 다음 근접 공격 {1}회가 각각 최대 생명력의 {2}%를 회복시킵니다." }, "n,p" },
	{ "chance combo energy finishing have moves per point restore", { ko = "마무리 일격 사용 시 {1}%의 확률로 소모한 연계 점수당 {2}의 기력을 회복합니다.", zhCN = "你的终结技每消耗一个连击点数都有{1}%的几率恢复{2}点能量。", zhTW = "使用終結技時，每個連擊點數有{1}%的機率恢復{2}點能量。" }, "p,n" },
	{ "base cost critical fire frost mana refund strikes their will", { ko = "화염 및 냉기 주문이 극대화 효과를 발휘할 경우 해당 주문 기본 마나 소모량의 {1}%를 되돌려받습니다.", zhCN = "你的火焰和冰霜法术造成爆击时，会返还其基础法力消耗的{1}%。", zhTW = "使你的火焰和冰霜法術在造成致命一擊後將返還{1}%基礎法力消耗。" }, "p" },
